def require(condition: bool, message: str) -> None:
    if not condition:
        raise ByteIdentityError(message)


def unique_json_object(pairs: list[tuple[str, object]]) -> dict:
    result = {}
    for key, value in pairs:
        require(key not in result, f"JSON object contains duplicate key: {key}")
        result[key] = value
    return result


class PreservedJsonObject(list):
    """A JSON object whose ordered pairs remain available after a strict failure."""


def preserved_json_object(pairs: list[tuple[str, object]]) -> PreservedJsonObject:
    return PreservedJsonObject(pairs)


def reject_json_constant(value: str) -> object:
    raise ByteIdentityError(f"JSON non-finite constant is forbidden: {value}")


def strict_json_loads(data: str | bytes, *, preserve_pairs: bool = False) -> object:
    return json.loads(
        data,
        object_pairs_hook=(preserved_json_object if preserve_pairs else unique_json_object),
        parse_constant=reject_json_constant,
    )


def sha256_bytes(data: bytes) -> str:
    return hashlib.sha256(data).hexdigest()


def md5_bytes(data: bytes) -> str:
    """Return the legacy image identity digest, never a security decision."""
    return hashlib.md5(data, usedforsecurity=False).hexdigest()


def sha256_file(path: Path) -> str:
    authority = active_authority_for_path(path)
    if authority is not None:
        return sha256_bytes(authority.read_bytes(path))
    if ACTIVE_BUILD_AUTHORITIES:
        return sha256_bytes(ACTIVE_BUILD_AUTHORITIES[-1].read_external_bytes(path))
    try:
        return sha256_bytes(path.read_bytes())
    except OSError as error:
        raise ByteIdentityError(f"cannot hash {path}: {error}") from error


def canonical_json_bytes(value: object) -> bytes:
    return (
        json.dumps(value, indent=2, sort_keys=True, allow_nan=False) + "\n"
    ).encode("utf-8")


def exact_keys(value: dict, allowed: set[str], context: str) -> None:
    unknown = set(value) - allowed
    require(not unknown, f"{context} has unknown keys: {sorted(unknown)}")


def exact_audit_keys(
    value: dict, expected: set[str], context: str,
    optional: set[str] | None = None,
) -> None:
    unknown = set(value) - expected
    missing = expected - set(value) - (optional or set())
    require(
        not unknown and not missing,
        f"{context} schema differs; unknown={sorted(unknown)} "
        f"missing={sorted(missing)}",
    )


def exact_json_equal(left: object, right: object) -> bool:
    """JSON equality that never treats bool/int/float as interchangeable."""
    if type(left) is not type(right):
        return False
    if isinstance(left, dict):
        return (left.keys() == right.keys()
                and all(exact_json_equal(left[key], right[key]) for key in left))
    if isinstance(left, list):
        return (len(left) == len(right)
                and all(exact_json_equal(a, b) for a, b in zip(left, right)))
    return left == right


def require_sha(value: object, context: str) -> str:
    require(isinstance(value, str) and SHA256_RE.fullmatch(value) is not None,
            f"{context} must be a lowercase SHA-256")
    return value


def require_md5(value: object, context: str) -> str:
    require(isinstance(value, str) and MD5_RE.fullmatch(value) is not None,
            f"{context} must be a lowercase MD5")
    return value


def require_nonnegative_finite_number(value: object, context: str) -> float:
    require(
        type(value) is float
        and math.isfinite(value)
        and value >= 0,
        f"{context} must be a finite nonnegative JSON float",
    )
    return value


def require_exact_int(
    value: object, context: str, *, minimum: int | None = None,
    maximum: int | None = None,
) -> int:
    require(type(value) is int, f"{context} must be an exact JSON integer")
    if minimum is not None:
        require(value >= minimum, f"{context} is below its minimum")
    if maximum is not None:
        require(value <= maximum, f"{context} exceeds its maximum")
    return value


def require_exact_bool(value: object, context: str) -> bool:
    require(type(value) is bool, f"{context} must be an exact JSON boolean")
    return value


def resolve_relative(root: Path, relative: object, context: str) -> tuple[str, Path]:
    require(isinstance(relative, str) and relative, f"{context} must be a non-empty path")
    require("\\" not in relative and ";" not in relative, f"{context} must use a safe POSIX path")
    pure = PurePosixPath(relative)
    require(not pure.is_absolute() and ".." not in pure.parts, f"{context} must stay below the source tree")
    resolved_root = root.resolve()
    candidate = (resolved_root / Path(*pure.parts)).resolve()
    try:
        candidate.relative_to(resolved_root)
    except ValueError as error:
        raise ByteIdentityError(f"{context} escapes the source tree") from error
    require(candidate.is_file(), f"{context} does not exist: {relative}")
    return pure.as_posix(), candidate


def canonical_source_relative_path(value: object, context: str) -> str:
    """Normalize one lexical source-tree path without requiring it to exist."""
    require(isinstance(value, str) and value,
            f"{context} must be a non-empty path")
    require("\\" not in value and ";" not in value and "\0" not in value,
            f"{context} must use a safe POSIX path")
    pure = PurePosixPath(value)
    require(
        not pure.is_absolute() and pure.as_posix() == value
        and all(part not in ("", ".", "..") for part in pure.parts),
        f"{context} must be one canonical source-relative path",
    )
    return pure.as_posix()


def source_overlay_relative_path(value: object, context: str) -> str:
    """Normalize one manifest-owned logical source/header overlay path.

    Generated-only overlay outputs are intentionally absent from the clean
    checkout, so the ordinary ``resolve_relative`` existence check is not an
    authority for this namespace.  Overlay recipes additionally admit only
    the closed C/C++ source/header suffix family.  Ordinary CMake inventory
    paths use :func:`canonical_source_relative_path` because an explicit
    LANGUAGE property may legitimately assign C or C++ to another suffix.
    """
    relative = canonical_source_relative_path(value, context)
    pure = PurePosixPath(relative)
    require(pure.suffix.casefold() in {
        ".c", ".cc", ".cpp", ".cxx", ".h", ".hh", ".hpp", ".hxx",
        ".inc", ".inl",
    }, f"{context} has an unsupported source/header suffix")
    return relative


def source_overlay_logical_path(source_root: Path, relative: str) -> Path:
    """Return an exact lexical source seat and reject redirected ancestors."""
    root = source_root.resolve(strict=True)
    require(root.is_dir() and not root.is_symlink(),
            "source overlay root is absent or redirected")
    current = root
    parts = PurePosixPath(relative).parts
    for part in parts[:-1]:
        current = current / part
        try:
            metadata = current.lstat()
        except OSError as error:
            raise ByteIdentityError(
                f"source overlay parent is absent: {current}: {error}"
            ) from error
        require(stat.S_ISDIR(metadata.st_mode) and not current.is_symlink(),
                f"source overlay parent is redirected: {current}")
    return root.joinpath(*parts)


@functools.lru_cache(maxsize=256)
def source_overlay_tokens(data: bytes) -> tuple[tuple[str, int, int], ...]:
    """Lex C/C++ significant tokens with stable byte spans.

    Latin-1 provides a one-to-one byte/character mapping.  Comments never
    participate in anchor authority; string and character literals remain
    single exact tokens.  The result is a pure function of the input bytes
    and is memoized (returned as an immutable tuple) because anchor
    resolution lexes the same clean input once per operation.
    """
    text = data.decode("latin1")
    result = []
    for match in SOURCE_OVERLAY_TOKEN_RE.finditer(text):
        token = match.group(0)
        if token.startswith(("//", "/*")):
            continue
        result.append((token, match.start(), match.end()))
    return tuple(result)


def source_overlay_token_sha256(tokens: list[str]) -> str:
    return sha256_bytes("\0".join(tokens).encode("latin1"))


def source_overlay_significant_sha256(data: bytes) -> str:
    return source_overlay_token_sha256(
        [token for token, _, _ in source_overlay_tokens(data)]
    )


@functools.lru_cache(maxsize=64)
def _source_overlay_anchor_seat_index(
    data: bytes, before_count: int, after_count: int,
) -> dict[str, tuple[int, ...]]:
    """Map every seat signature sha to its token boundaries, once per input.

    This is a pure restatement of the exhaustive per-anchor scan: for each
    token boundary the same ``before/<SEAT>/after`` signature sha is
    computed, so a lookup yields exactly the candidate set the linear scan
    would have produced.  Memoizing per (input, window) lets every anchor
    that shares a clean input and window reuse one scan.
    """
    tokens = [item[0] for item in source_overlay_tokens(data)]
    seats: dict[str, list[int]] = {}
    for index in range(len(tokens) + 1):
        if index < before_count or len(tokens) - index < after_count:
            continue
        signature = (
            tokens[index - before_count:index]
            + ["<SEAT>"]
            + tokens[index:index + after_count]
        )
        seats.setdefault(
            source_overlay_token_sha256(signature), []
        ).append(index)
    return {sha: tuple(indices) for sha, indices in seats.items()}


def source_overlay_member_is_declared(
    data: bytes, class_identifier: str, member_identifier: str, kind: str,
) -> bool:
    """A7a: does this checked-in source authorise the signature's seat?

    Comments are stripped first so a mention inside prose cannot authorise a
    signature.  Only the class's own brace-balanced body is searched, so a
    member of some *other* class never satisfies the check.

    The question the answer must be is a function of the kind:

    * ``destructor`` -- "is the member already declared on the class?".  A
      class has at most one destructor, so an existing declaration is exactly
      what authorises re-emitting its signature text.
    * ``constructor`` -- that question is VACUOUS, because a class that
      declares any constructor at all trivially contains ``Name (``.  Here the
      existential half only asks "does the class exist in this source?"; the
      load-bearing half of A7a is the FRESHNESS obligation in
      ``source_overlay_constructor_overload_count``, which the caller applies
      to every clean input.  Splitting it this way keeps A7a a real gate for
      constructors instead of turning it into a hole.
    """
    require(kind in MEMBER_SIGNATURE_KINDS,
            f"member signature kind {kind!r} is outside the closed enum")
    clean = source_overlay_strip_comments_preserve_lines(data).decode("latin1")
    opening = re.compile(
        r"\b(?:struct|class)\s+" + re.escape(class_identifier)
        + r"\b[^{;]*\{"
    )
    wanted = "~" + member_identifier
    for match in opening.finditer(clean):
        depth, index = 0, match.end() - 1
        while index < len(clean):
            character = clean[index]
            if character == "{":
                depth += 1
            elif character == "}":
                depth -= 1
                if depth == 0:
                    break
            index += 1
        body = clean[match.end():index]
        if kind == "constructor":
            # A7a(i): the class this signature names must EXIST in checked-in
            # source.  Its overload freshness is a separate, universal
            # obligation and is never satisfied by an existential scan.
            return True
        if re.search(r"(?<![\w~])" + re.escape(wanted) + r"\s*\(", body):
            return True
    return False


def source_overlay_class_scope_declarator_parameters(
    data: bytes, class_identifier: str,
) -> list[list[list[str]]]:
    """Every class-scope ``Name(...)`` declarator's parameter TYPE sequences.

    Comments are excluded and nested scopes are skipped, so only declarators
    at depth one of the named class's own brace-balanced body are returned.
    A trailing parameter identifier is dropped from each parameter: two
    declarations that differ only in parameter spelling are the SAME overload
    to the language, so freshness has to be asked about types.
    """
    tokens = _semantic_significant_tokens(data)
    declarators = []
    for index in range(len(tokens) - 2):
        if (tokens[index][0] not in {"class", "struct"}
                or tokens[index + 1][0] != class_identifier):
            continue
        opening = next(
            (cursor for cursor in range(index + 2, len(tokens))
             if tokens[cursor][0] in {"{", ";"}),
            None,
        )
        if opening is None or tokens[opening][0] != "{":
            continue
        depth = 1
        closing = None
        for cursor in range(opening + 1, len(tokens)):
            if tokens[cursor][0] == "{":
                depth += 1
            elif tokens[cursor][0] == "}":
                depth -= 1
                if depth == 0:
                    closing = cursor
                    break
        if closing is None:
            continue
        depth = 1
        for cursor in range(opening + 1, closing):
            token = tokens[cursor][0]
            if (depth == 1 and token == class_identifier
                    and tokens[cursor - 1][0] != "~"
                    and cursor + 1 < closing
                    and tokens[cursor + 1][0] == "("):
                inner = 0
                stop = None
                for scan in range(cursor + 1, closing):
                    if tokens[scan][0] == "(":
                        inner += 1
                    elif tokens[scan][0] == ")":
                        inner -= 1
                        if inner == 0:
                            stop = scan
                            break
                if stop is not None:
                    declarators.append(
                        _split_declarator_parameter_types(
                            [item[0] for item in tokens[cursor + 2:stop]]))
            if token == "{":
                depth += 1
            elif token == "}":
                depth -= 1
    return declarators


def _split_declarator_parameter_types(tokens: list[str]) -> list[list[str]]:
    """Split one parameter-list token run into per-parameter type runs."""
    groups: list[list[str]] = []
    current: list[str] = []
    depth = 0
    for token in tokens:
        if token in {"(", "[", "<"}:
            depth += 1
        elif token in {")", "]", ">"}:
            depth -= 1
        if token == "," and depth == 0:
            groups.append(current)
            current = []
            continue
        current.append(token)
    if current:
        groups.append(current)
    stripped = []
    for group in groups:
        if (len(group) > 1
                and SOURCE_OVERLAY_IDENTIFIER_RE.fullmatch(group[-1])
                is not None):
            group = group[:-1]
        stripped.append(group)
    return stripped


def source_overlay_constructor_signature_parameter_types(
    parameters: list[dict],
) -> list[list[str]]:
    """The per-parameter type token runs one constructor overload occupies."""
    return [
        [token for token, _, _ in source_overlay_tokens(
            render_source_overlay_cpp_type(item["type"]).encode("ascii"))]
        for item in parameters
    ]


def source_overlay_constructor_overload_count(
    data: bytes, class_identifier: str, parameters: list[dict],
) -> int:
    """A7a(ii): how many times does this exact overload already exist here?

    Zero is the only value that authorises a fresh constructor signature.  A
    non-zero count means the manifest is re-declaring something checked-in
    source already declares, which would be a redefinition rather than the
    donor-private addition the class was amended for.
    """
    wanted = source_overlay_constructor_signature_parameter_types(parameters)
    return sum(
        1 for item in source_overlay_class_scope_declarator_parameters(
            data, class_identifier)
        if item == wanted
    )


def source_overlay_strip_comments_preserve_lines(data: bytes) -> bytes:
    """Remove only comment bytes while retaining exact physical line seats."""
    text = data.decode("latin1")
    result = bytearray(data)
    for match in SOURCE_OVERLAY_TOKEN_RE.finditer(text):
        token = match.group(0)
        if not token.startswith(("//", "/*")):
            continue
        for index in range(match.start(), match.end()):
            if result[index] not in (10, 13):
                result[index] = 32
    return bytes(result)


SOURCE_OVERLAY_ANNOTATION_COMMENT_RE = re.compile(
    r"//\s*(?:FUNCTION|GLOBAL|VTABLE|STRING|LIBRARY|SYNTHETIC|TODO|OFFSET"
    r"|SIZE)\b"
)


SOURCE_OVERLAY_RANGE_RENDER_POLICIES = {
    "strip_comments_preserve_physical_lines_v1",
    "strip_prose_preserve_physical_lines_v1",
}


def source_overlay_strip_prose_preserve_lines(data: bytes) -> bytes:
    """Strip prose comments but keep annotation comments and line seats."""
    text = data.decode("latin1")
    result = bytearray(data)
    for match in SOURCE_OVERLAY_TOKEN_RE.finditer(text):
        token = match.group(0)
        if not token.startswith(("//", "/*")):
            continue
        if token.startswith("//") and SOURCE_OVERLAY_ANNOTATION_COMMENT_RE.match(
                token) is not None:
            continue
        for index in range(match.start(), match.end()):
            if result[index] not in (10, 13):
                result[index] = 32
    return bytes(result)


def source_overlay_render_relocated_range(data: bytes, policy: object) -> bytes:
    require(policy in SOURCE_OVERLAY_RANGE_RENDER_POLICIES,
            "source relocation render policy differs")
    if policy == "strip_prose_preserve_physical_lines_v1":
        return source_overlay_strip_prose_preserve_lines(data)
    return source_overlay_strip_comments_preserve_lines(data)


def source_overlay_seat_lines(data: bytes, offset: int) -> tuple[bytes, bytes]:
    """Return the physical line ending before and starting at ``offset``."""
    require(0 <= offset <= len(data), "source overlay seat offset is invalid")
    prefix_lines = data[:offset].splitlines()
    suffix_lines = data[offset:].splitlines()
    before = prefix_lines[-1] if prefix_lines else b""
    after = suffix_lines[0] if suffix_lines else b""
    return before, after


def validate_source_overlay_anchor(value: object, context: str) -> dict:
    """Validate one lean single-tier structural anchor.

    The anchor is one 32/32 significant-token context sha (narrower only at
    file edges), a byte-boundary kind, and -- exclusively for the default
    ``after_newline`` boundary, where several newlines can sit between the
    same two tokens -- the shas of the physical lines surrounding the seat.
    Zero matches and ambiguity both refuse at resolve time.
    """
    require(isinstance(value, dict), f"{context} must be an object")
    exact_audit_keys(
        value, {"ctx", "b", "a", "at", "line_before", "line_after"}, context,
        optional={"b", "a", "at", "line_before", "line_after"},
    )
    before_count = require_exact_int(
        value.get("b", 32), context + ".b", minimum=0, maximum=32,
    )
    after_count = require_exact_int(
        value.get("a", 32), context + ".a", minimum=0, maximum=32,
    )
    require(before_count or after_count,
            f"{context} cannot match an empty context")
    raw_boundary = value.get("at")
    if raw_boundary is None:
        boundary = "after_newline"
    else:
        require(raw_boundary in SOURCE_OVERLAY_LEAN_BOUNDARIES,
                f"{context}.at is unsupported")
        boundary = SOURCE_OVERLAY_LEAN_BOUNDARIES[raw_boundary]
    normalized = {
        "context_sha256": require_sha(value.get("ctx"), context + ".ctx"),
        "before_token_count": before_count,
        "after_token_count": after_count,
        "boundary": boundary,
    }
    if boundary == "after_newline":
        normalized["before_line_sha256"] = require_sha(
            value.get("line_before"), context + ".line_before"
        )
        normalized["after_line_sha256"] = require_sha(
            value.get("line_after"), context + ".line_after"
        )
    else:
        require("line_before" not in value and "line_after" not in value,
                f"{context} line shas belong to after_newline seats only")
    return normalized


def resolve_source_overlay_anchor(
    data: bytes, anchor: dict, context: str, *,
    evidence: list[dict] | None = None, logical_path: str | None = None,
    operation_id: str | None = None, role: str | None = None,
) -> int:
    """Resolve the unique token context to one exact byte seat."""
    matches = source_overlay_tokens(data)
    before_count = anchor["before_token_count"]
    after_count = anchor["after_token_count"]
    candidates = list(_source_overlay_anchor_seat_index(
        data, before_count, after_count,
    ).get(anchor["context_sha256"], ()))
    require(len(candidates) <= 1, f"{context} is ambiguous")
    require(candidates, f"{context} is missing from its clean input")
    index = candidates[0]
    lower = matches[index - 1][2] if index else 0
    upper = matches[index][1] if index < len(matches) else len(data)
    require(lower <= upper, f"{context} token boundary is invalid")
    boundary = anchor["boundary"]
    if boundary == "file_start":
        require(lower == 0, f"{context} is not at file start")
        selected_offset = 0
    elif boundary == "file_end":
        require(upper == len(data), f"{context} is not at file end")
        selected_offset = len(data)
    elif boundary == "after_previous_token":
        selected_offset = lower
    elif boundary == "before_next_token":
        selected_offset = upper
    elif boundary == "after_newline":
        selected = []
        for position in range(lower, upper):
            if data[position:position + 1] != b"\n":
                continue
            before, after = source_overlay_seat_lines(data, position + 1)
            if (sha256_bytes(before) == anchor["before_line_sha256"]
                    and sha256_bytes(after) == anchor["after_line_sha256"]):
                selected.append(position + 1)
        require(len(selected) == 1,
                f"{context} has no unique after-newline structural seat")
        selected_offset = selected[0]
    else:
        raise ByteIdentityError(f"{context} byte boundary is unsupported")
    if evidence is not None:
        require(all(isinstance(item, str) and item
                    for item in (logical_path, operation_id, role)),
                f"{context} evidence identity is incomplete")
        evidence.append({
            "logical_path": logical_path,
            "operation_id": operation_id,
            "role": role,
            "selected_token_boundary": index,
            "selected_byte_offset": selected_offset,
            "context_sha256": anchor["context_sha256"],
        })
    return selected_offset


def _source_overlay_identifier(value: object, context: str) -> str:
    require(isinstance(value, str)
            and SOURCE_OVERLAY_IDENTIFIER_RE.fullmatch(value) is not None,
            f"{context} must be a C/C++ identifier")
    return value


def _source_overlay_qualified_identifier(value: object, context: str) -> str:
    require(isinstance(value, str)
            and SOURCE_OVERLAY_QUALIFIED_IDENTIFIER_RE.fullmatch(value) is not None,
            f"{context} must be a qualified C/C++ identifier")
    return value


def _source_overlay_census_identifier(value: object, context: str) -> str:
    require(isinstance(value, str) and 1 <= len(value) <= 256
            and value.isascii() and not any(
                character in value for character in "\0\n\r\t;{}#<>\\\"'"
            ), f"{context} is not one safe census identity")
    if SOURCE_OVERLAY_QUALIFIED_IDENTIFIER_RE.fullmatch(value) is not None:
        return value
    if re.fullmatch(
        r"[A-Za-z_][A-Za-z0-9_]*(?:::[A-Za-z_~][A-Za-z0-9_]*)+",
        value,
    ) is not None:
        return value
    if re.fullmatch(
        r"[A-Za-z_][A-Za-z0-9_]*(?:::[A-Za-z_][A-Za-z0-9_]*)+"
        r"\(\) const",
        value,
    ) is not None:
        return value
    try:
        return source_overlay_relative_path(value, context)
    except ByteIdentityError as error:
        raise ByteIdentityError(f"{context} is not one closed census identity") from error


def validate_source_overlay_range_pin(value: object, context: str) -> dict:
    """Validate an exact byte-and-token identity for a destructive range."""
    require(isinstance(value, dict), f"{context} must be an object")
    exact_audit_keys(value, {
        "baseline_sha256", "baseline_size", "baseline_line_count",
        "baseline_significant_token_sha256",
    }, context)
    return {
        "baseline_sha256": require_sha(
            value.get("baseline_sha256"), context + ".baseline_sha256"
        ),
        "baseline_size": require_exact_int(
            value.get("baseline_size"), context + ".baseline_size",
            minimum=0, maximum=64 * 1024 * 1024,
        ),
        "baseline_line_count": require_exact_int(
            value.get("baseline_line_count"), context + ".baseline_line_count",
            minimum=0, maximum=2_000_000,
        ),
        "baseline_significant_token_sha256": require_sha(
            value.get("baseline_significant_token_sha256"),
            context + ".baseline_significant_token_sha256",
        ),
    }


def require_source_overlay_range_pin(
    data: bytes, expected: dict, context: str,
) -> dict:
    """Authenticate one already-resolved clean-input byte range."""
    actual = {
        "actual_removed_range_sha256": sha256_bytes(data),
        "actual_removed_range_size": len(data),
        "actual_removed_range_line_count": data.count(b"\n"),
        "actual_removed_range_significant_token_sha256":
            source_overlay_significant_sha256(data),
    }
    require(
        actual["actual_removed_range_sha256"] == expected["baseline_sha256"]
        and actual["actual_removed_range_size"] == expected["baseline_size"]
        and actual["actual_removed_range_line_count"]
        == expected["baseline_line_count"]
        and actual["actual_removed_range_significant_token_sha256"]
        == expected["baseline_significant_token_sha256"],
        f"{context} differs from its authenticated input-range pins",
    )
    return actual


def validate_target_source_range_proof(value: object, context: str) -> dict:
    """Validate the closed source window used by a target-only donor.

    Both complete source renderings are already content-pinned.  The two
    unique markers select the function text, while the ordinary range pin
    prevents a marker edit from silently widening or narrowing that proof.
    """
    require(isinstance(value, dict), f"{context} must be an object")
    exact_audit_keys(value, {"start_marker", "end_marker", "range_pin"},
                     context)
    markers = {}
    for name in ("start_marker", "end_marker"):
        marker = value.get(name)
        require(isinstance(marker, str) and marker.isascii()
                and 8 <= len(marker) <= 256
                and not any(character in marker for character in "\0\r\n"),
                f"{context}.{name} is invalid")
        markers[name] = marker
    require(markers["start_marker"] != markers["end_marker"],
            f"{context} markers must differ")
    return {
        **markers,
        "range_pin": validate_source_overlay_range_pin(
            value.get("range_pin"), context + ".range_pin"
        ),
    }


FIXED_ARRAY_FILL_ELEMENT_TYPE_SPELLINGS = frozenset({
    "char", "signed char", "unsigned char",
    "short", "short int", "signed short", "signed short int",
    "unsigned short", "unsigned short int",
    "int", "signed", "signed int", "unsigned", "unsigned int",
    "long", "long int", "signed long", "signed long int",
    "unsigned long", "unsigned long int",
    "MxS8", "MxU8", "MxS16", "MxU16", "MxS32", "MxU32",
    "MxLong", "MxULong",
})


FIXED_ARRAY_FILL_INDEX_TYPE_SPELLINGS = (
    FIXED_ARRAY_FILL_ELEMENT_TYPE_SPELLINGS
    - {"char", "signed char", "unsigned char", "MxS8", "MxU8"}
)


def validate_fixed_array_declaration_proof(
    value: object, context: str,
) -> dict:
    """Pin the actual integral array declaration that owns a loop bound."""
    require(isinstance(value, dict), f"{context} must be an object")
    exact_audit_keys(value, {
        "path", "source_sha256", "owner", "array", "element_type",
        "extent", "direct_include_range_pin", "declaration_range_pin",
    }, context)
    element_type = validate_source_overlay_cpp_type(
        value.get("element_type"), context + ".element_type")
    require(render_source_overlay_cpp_type(element_type)
            in FIXED_ARRAY_FILL_ELEMENT_TYPE_SPELLINGS,
            f"{context}.element_type is not a closed integral type")
    return {
        "path": source_overlay_relative_path(
            value.get("path"), context + ".path"),
        "source_sha256": require_sha(
            value.get("source_sha256"), context + ".source_sha256"),
        "owner_identifier": _source_overlay_identifier(
            value.get("owner"), context + ".owner"),
        "array_identifier": _source_overlay_identifier(
            value.get("array"), context + ".array"),
        "element_type": element_type,
        "extent": require_exact_int(
            value.get("extent"), context + ".extent",
            minimum=1, maximum=4096,
        ),
        "direct_include_range_pin": validate_source_overlay_range_pin(
            value.get("direct_include_range_pin"),
            context + ".direct_include_range_pin",
        ),
        "declaration_range_pin": validate_source_overlay_range_pin(
            value.get("declaration_range_pin"),
            context + ".declaration_range_pin",
        ),
    }


def validate_fixed_array_shuffle_semantic_witness(
    value: object, context: str,
) -> dict:
    """Validate the closed declarations behind an in-place array shuffle."""
    require(isinstance(value, dict), f"{context} must be an object")
    exact_audit_keys(value, {
        "source_owner", "array_member", "element_type", "extent",
        "index_identifier", "index_type", "owner_header", "base_header",
        "types_header", "next_index_overwrite_range_pin",
    }, context)

    def value_type(name: str) -> dict:
        result = validate_source_overlay_cpp_type(
            value.get(name), f"{context}.{name}")
        require(not result["base_const"]
                and not result["indirection"]
                and not result["trailing_const"]
                and render_source_overlay_cpp_type(result)
                in FIXED_ARRAY_FILL_ELEMENT_TYPE_SPELLINGS,
                f"{context}.{name} is not a closed integral value type")
        return result

    normalized = {
        "source_owner": _source_overlay_identifier(
            value.get("source_owner"), context + ".source_owner"),
        "array_member": _source_overlay_identifier(
            value.get("array_member"), context + ".array_member"),
        "element_type": value_type("element_type"),
        "extent": require_exact_int(
            value.get("extent"), context + ".extent",
            minimum=2, maximum=4096,
        ),
        "index_identifier": _source_overlay_identifier(
            value.get("index_identifier"), context + ".index_identifier"),
        "index_type": value_type("index_type"),
        "next_index_overwrite_range_pin": validate_source_overlay_range_pin(
            value.get("next_index_overwrite_range_pin"),
            context + ".next_index_overwrite_range_pin",
        ),
    }
    header_keys = {
        "owner_header": {
            "path", "source_sha256", "unit_include_range_pin",
            "base_include_range_pin", "array_declaration_range_pin",
            "member_block_range_pin",
        },
        "base_header": {
            "path", "source_sha256", "types_include_range_pin",
        },
        "types_header": {
            "path", "source_sha256", "element_typedef_range_pin",
            "index_typedef_range_pin",
        },
    }
    for name, keys in header_keys.items():
        item_context = f"{context}.{name}"
        item = value.get(name)
        require(isinstance(item, dict), f"{item_context} must be an object")
        exact_audit_keys(item, keys, item_context)
        normalized_item = {
            "path": source_overlay_relative_path(
                item.get("path"), item_context + ".path"),
            "source_sha256": require_sha(
                item.get("source_sha256"), item_context + ".source_sha256"),
        }
        for key in keys - {"path", "source_sha256"}:
            normalized_item[key] = validate_source_overlay_range_pin(
                item.get(key), f"{item_context}.{key}")
        normalized[name] = normalized_item
    require(len({normalized[name]["path"] for name in header_keys}) == 3,
            f"{context}: shuffle semantic witness headers must be distinct")
    return normalized


def validate_constructor_allocation_lift_semantic_witness(
    value: object, context: str,
) -> dict:
    """Validate the closed declarations behind a constructor allocation lift.

    Like every other semantic witness in this module the witness is
    source-shaped rather than prose-shaped: it names the entry class, the
    buffer member that receives the allocation, the members the lifted body
    nulls, the checked-in constructor whose argument roles make the two forms
    equivalent, and the destructor whose ownership guard makes the temporary's
    lifetime unchanged.  Every one of those is then proved by exact token
    range out of the pinned checked-in header.
    """
    require(isinstance(value, dict), f"{context} must be an object")
    exact_audit_keys(value, {
        "source_owner", "entry_class", "buffer_member", "buffer_member_type",
        "null_members", "null_argument_position",
        "baseline_constructor_parameter_identifiers", "owner_header",
        "target_parameter_range_pin",
    }, context)
    buffer_member_type = validate_source_overlay_cpp_type(
        value.get("buffer_member_type"), context + ".buffer_member_type")
    require(buffer_member_type["indirection"] == ["pointer"]
            and not buffer_member_type["trailing_const"],
            f"{context}.buffer_member_type is not a single mutable pointer")
    raw_null_members = value.get("null_members")
    require(isinstance(raw_null_members, list)
            and len(raw_null_members) == 1,
            f"{context}.null_members must name exactly one nulled member")
    null_members = []
    for index, item in enumerate(raw_null_members):
        item_context = f"{context}.null_members[{index}]"
        require(isinstance(item, dict), f"{item_context} must be an object")
        exact_audit_keys(item, {"identifier", "type"}, item_context)
        null_members.append({
            "identifier": _source_overlay_identifier(
                item.get("identifier"), item_context + ".identifier"),
            "type": validate_source_overlay_cpp_type(
                item.get("type"), item_context + ".type"),
        })
    parameter_identifiers = _source_overlay_identifier_list(
        value.get("baseline_constructor_parameter_identifiers"),
        context + ".baseline_constructor_parameter_identifiers",
        minimum=len(null_members) + 1, maximum=len(null_members) + 1,
    )
    require(len(set(parameter_identifiers)) == len(parameter_identifiers),
            f"{context}.baseline_constructor_parameter_identifiers must be "
            "distinct")
    normalized = {
        "source_owner": _source_overlay_identifier(
            value.get("source_owner"), context + ".source_owner"),
        "entry_class": _source_overlay_identifier(
            value.get("entry_class"), context + ".entry_class"),
        "buffer_member": _source_overlay_identifier(
            value.get("buffer_member"), context + ".buffer_member"),
        "buffer_member_type": buffer_member_type,
        "null_members": null_members,
        "null_argument_position": require_exact_int(
            value.get("null_argument_position"),
            context + ".null_argument_position",
            minimum=0, maximum=len(null_members),
        ),
        "baseline_constructor_parameter_identifiers": parameter_identifiers,
        "target_parameter_range_pin": validate_source_overlay_range_pin(
            value.get("target_parameter_range_pin"),
            context + ".target_parameter_range_pin",
        ),
    }
    members = {normalized["buffer_member"]} | {
        item["identifier"] for item in null_members
    }
    require(len(members) == len(null_members) + 1
            and not members.intersection(parameter_identifiers),
            f"{context}: member and parameter identities collide")
    header_keys = {
        "path", "source_sha256", "unit_include_range_pin",
        "class_body_range_pin", "buffer_member_declaration_range_pin",
        "null_member_declaration_range_pins",
        "baseline_constructor_range_pin", "destructor_body_range_pin",
    }
    item_context = f"{context}.owner_header"
    item = value.get("owner_header")
    require(isinstance(item, dict), f"{item_context} must be an object")
    exact_audit_keys(item, header_keys, item_context)
    header = {
        "path": source_overlay_relative_path(
            item.get("path"), item_context + ".path"),
        "source_sha256": require_sha(
            item.get("source_sha256"), item_context + ".source_sha256"),
    }
    for key in ("unit_include_range_pin", "class_body_range_pin",
                "buffer_member_declaration_range_pin",
                "baseline_constructor_range_pin",
                "destructor_body_range_pin"):
        header[key] = validate_source_overlay_range_pin(
            item.get(key), f"{item_context}.{key}")
    pins = item.get("null_member_declaration_range_pins")
    require(isinstance(pins, list) and len(pins) == len(null_members),
            f"{item_context}.null_member_declaration_range_pins must pin "
            "every nulled member")
    header["null_member_declaration_range_pins"] = [
        validate_source_overlay_range_pin(
            entry,
            f"{item_context}.null_member_declaration_range_pins[{index}]")
        for index, entry in enumerate(pins)
    ]
    normalized["owner_header"] = header
    return normalized


INCLUSIVE_EXTENT_BARRIER = "msvc_i386_empty_inline_assembly_v1"


def validate_inclusive_extent_semantic_witness(
    value: object, context: str,
) -> dict:
    """Validate the closed declarations behind an inclusive extent rewrite.

    The witness is deliberately source-shaped rather than prose-shaped.  It
    pins the member that supplies the rectangle, its side-effect-free access
    path, the two endpoint readers, and the original inclusive-width reader.
    The include edges bind those declarations to the compiled translation
    unit instead of allowing an unrelated repository header to certify them.
    """
    require(isinstance(value, dict), f"{context} must be an object")
    exact_audit_keys(value, {
        "source_owner", "source_member", "source_member_type",
        "aggregate_accessor", "aggregate_member", "aggregate_type",
        "extent_template", "template_parameter", "coordinate_type",
        "lower_accessor",
        "lower_member", "upper_accessor", "upper_member",
        "extent_accessor", "source_owner_header",
        "source_accessor_header", "extent_header",
    }, context)

    coordinate_type = validate_source_overlay_cpp_type(
        value.get("coordinate_type"), context + ".coordinate_type")
    require(not coordinate_type["base_const"]
            and not coordinate_type["indirection"]
            and not coordinate_type["trailing_const"]
            and render_source_overlay_cpp_type(coordinate_type)
            in FIXED_ARRAY_FILL_ELEMENT_TYPE_SPELLINGS,
            f"{context}.coordinate_type is not a closed integral type")

    normalized = {
        name: _source_overlay_identifier(value.get(name),
                                         f"{context}.{name}")
        for name in (
            "source_owner", "source_member", "source_member_type",
            "aggregate_accessor", "aggregate_member", "aggregate_type",
            "extent_template", "template_parameter", "lower_accessor",
            "lower_member",
            "upper_accessor", "upper_member", "extent_accessor",
        )
    }
    normalized["coordinate_type"] = coordinate_type

    header_keys = {
        "source_owner_header": {
            "path", "source_sha256", "unit_include_range_pin",
            "member_declaration_range_pin",
        },
        "source_accessor_header": {
            "path", "source_sha256", "owner_include_range_pin",
            "accessor_range_pin",
        },
        "extent_header": {
            "path", "source_sha256", "accessor_include_range_pin",
            "concrete_inheritance_range_pin", "concrete_class_range_pin",
            "lower_accessor_range_pin", "upper_accessor_range_pin",
            "extent_accessor_range_pin",
        },
    }
    for name, keys in header_keys.items():
        item_context = f"{context}.{name}"
        item = value.get(name)
        require(isinstance(item, dict), f"{item_context} must be an object")
        exact_audit_keys(item, keys, item_context)
        normalized_item = {
            "path": source_overlay_relative_path(
                item.get("path"), item_context + ".path"),
            "source_sha256": require_sha(
                item.get("source_sha256"), item_context + ".source_sha256"),
        }
        for key in keys - {"path", "source_sha256"}:
            normalized_item[key] = validate_source_overlay_range_pin(
                item.get(key), f"{item_context}.{key}")
        normalized[name] = normalized_item
    require(len({normalized[name]["path"] for name in header_keys}) == 3,
            f"{context}: semantic witness headers must be distinct")
    return normalized


def validate_discarded_increment_semantic_witness(
    value: object, context: str,
) -> dict:
    """Validate the complete type/include proof for a discarded increment.

    This schema deliberately carries declarations and include edges, never a
    prose assertion that two overloads are equivalent.  The corresponding
    identity check selects the iterator typedef and the exact prefix/postfix
    implementations from the sealed compiler include tree.
    """
    require(isinstance(value, dict), f"{context} must be an object")
    exact_audit_keys(value, {
        "iterator_identifier", "source_alias", "source_alias_arguments",
        "iterator_member", "map_template", "tree_template",
        "increment_helper", "iterator_base", "iterator_category_base",
        "iterator_category_tag", "node_pointer_type",
        "node_pointer_member", "source_alias_header",
        "source_include_chain", "map_header", "tree_header",
        "iterator_header", "utility_header", "memory_header",
        "xmemory_header",
        "loop_declaration_range_pin",
    }, context)
    identifiers = {
        name: _source_overlay_identifier(value.get(name), f"{context}.{name}")
        for name in (
            "iterator_identifier", "source_alias", "iterator_member",
            "map_template", "tree_template", "increment_helper",
            "iterator_base", "iterator_category_base",
            "iterator_category_tag", "node_pointer_type",
            "node_pointer_member",
        )
    }
    require(
        identifiers["iterator_base"] == "_Bidit"
        and identifiers["iterator_category_base"] == "iterator"
        and identifiers["iterator_category_tag"]
        == "bidirectional_iterator_tag"
        and identifiers["node_pointer_type"] == "_Nodeptr"
        and identifiers["node_pointer_member"] == "_Ptr",
        f"{context}: sealed iterator state identities differ",
    )
    raw_arguments = value.get("source_alias_arguments")
    require(isinstance(raw_arguments, list)
            and 1 <= len(raw_arguments) <= 8,
            f"{context}.source_alias_arguments differs")
    arguments = [
        validate_source_overlay_cpp_type(
            item, f"{context}.source_alias_arguments[{index}]"
        ) for index, item in enumerate(raw_arguments)
    ]

    alias = value.get("source_alias_header")
    alias_context = context + ".source_alias_header"
    require(isinstance(alias, dict), f"{alias_context} must be an object")
    exact_audit_keys(alias, {
        "path", "source_sha256", "unit_include_range_pin",
        "alias_range_pin",
    }, alias_context)
    normalized_alias = {
        "path": source_overlay_relative_path(
            alias.get("path"), alias_context + ".path"),
        "source_sha256": require_sha(
            alias.get("source_sha256"), alias_context + ".source_sha256"),
        "unit_include_range_pin": validate_source_overlay_range_pin(
            alias.get("unit_include_range_pin"),
            alias_context + ".unit_include_range_pin"),
        "alias_range_pin": validate_source_overlay_range_pin(
            alias.get("alias_range_pin"),
            alias_context + ".alias_range_pin"),
    }

    raw_chain = value.get("source_include_chain")
    require(isinstance(raw_chain, list) and 1 <= len(raw_chain) <= 16,
            f"{context}.source_include_chain differs")
    chain = []
    for index, item in enumerate(raw_chain):
        item_context = f"{context}.source_include_chain[{index}]"
        require(isinstance(item, dict), f"{item_context} must be an object")
        exact_audit_keys(item, {
            "including_path", "including_sha256", "included_path",
            "included_sha256", "include_range_pin",
        }, item_context)
        chain.append({
            "including_path": source_overlay_relative_path(
                item.get("including_path"), item_context + ".including_path"),
            "including_sha256": require_sha(
                item.get("including_sha256"),
                item_context + ".including_sha256"),
            "included_path": source_overlay_relative_path(
                item.get("included_path"), item_context + ".included_path"),
            "included_sha256": require_sha(
                item.get("included_sha256"),
                item_context + ".included_sha256"),
            "include_range_pin": validate_source_overlay_range_pin(
                item.get("include_range_pin"),
                item_context + ".include_range_pin"),
        })
    require(chain[0]["including_path"] == normalized_alias["path"],
            f"{context}: source include chain does not start at the alias "
            "header")
    require(all(
        left["included_path"] == right["including_path"]
        and left["included_sha256"] == right["including_sha256"]
        for left, right in zip(chain, chain[1:])
    ), f"{context}: source include chain is discontinuous")
    require(len({item["including_path"] for item in chain}) == len(chain)
            and normalized_alias["path"] not in {
                item["included_path"] for item in chain
            }, f"{context}: source include chain contains a cycle")

    toolchain_specs = {}
    spec_keys = {
        "map_header": {
            "tree_role", "path", "source_sha256",
            "repository_include_range_pin", "tree_include_range_pin",
            "implementation_alias_range_pin", "iterator_alias_range_pin",
        },
        "tree_header": {
            "tree_role", "path", "source_sha256",
            "iterator_include_range_pin", "memory_include_range_pin",
            "node_pointer_alias_range_pin", "iterator_class_range_pin",
            "increment_range_pin",
        },
        "iterator_header": {
            "tree_role", "path", "source_sha256",
            "utility_include_range_pin",
        },
        "utility_header": {
            "tree_role", "path", "source_sha256",
            "category_base_range_pin", "bidirectional_base_range_pin",
        },
        "memory_header": {
            "tree_role", "path", "source_sha256",
            "xmemory_include_range_pin",
        },
        "xmemory_header": {
            "tree_role", "path", "source_sha256",
            "pointer_macro_range_pin",
        },
    }
    for name, keys in spec_keys.items():
        item_context = f"{context}.{name}"
        item = value.get(name)
        require(isinstance(item, dict), f"{item_context} must be an object")
        exact_audit_keys(item, keys, item_context)
        path = canonical_source_relative_path(
            item.get("path"), item_context + ".path")
        normalized_item = {
            "tree_role": item.get("tree_role"),
            "path": path,
            "source_sha256": require_sha(
                item.get("source_sha256"), item_context + ".source_sha256"),
        }
        require(item.get("tree_role") == "msvc_include",
                f"{item_context}.tree_role differs")
        for key in keys - {"tree_role", "path", "source_sha256"}:
            normalized_item[key] = validate_source_overlay_range_pin(
                item.get(key), f"{item_context}.{key}")
        toolchain_specs[name] = normalized_item
    require(toolchain_specs["map_header"]["path"].casefold() == "map"
            and toolchain_specs["tree_header"]["path"].casefold() == "xtree"
            and toolchain_specs["iterator_header"]["path"].casefold()
            == "iterator"
            and toolchain_specs["utility_header"]["path"].casefold()
            == "utility"
            and toolchain_specs["memory_header"]["path"].casefold()
            == "memory"
            and toolchain_specs["xmemory_header"]["path"].casefold()
            == "xmemory",
            f"{context}: iterator toolchain header identities differ")
    return {
        **identifiers,
        "source_alias_arguments": arguments,
        "source_alias_header": normalized_alias,
        "source_include_chain": chain,
        **toolchain_specs,
        "loop_declaration_range_pin": validate_source_overlay_range_pin(
            value.get("loop_declaration_range_pin"),
            context + ".loop_declaration_range_pin"),
    }


def require_target_source_range_identity(
    seed_source: bytes, donor_source: bytes, proof: dict, context: str,
) -> dict:
    """Prove a donor changed compiler state outside, not inside, the target."""
    require(isinstance(seed_source, bytes) and isinstance(donor_source, bytes),
            f"{context} source renderings are missing")

    def selected(data: bytes, role: str) -> bytes:
        start_marker = proof["start_marker"].encode("ascii")
        end_marker = proof["end_marker"].encode("ascii")
        require(data.count(start_marker) == 1,
                f"{context} {role} start marker is not unique")
        require(data.count(end_marker) == 1,
                f"{context} {role} end marker is not unique")
        start = data.index(start_marker)
        end = data.index(end_marker)
        require(start < end,
                f"{context} {role} source markers are reversed")
        return data[start:end]

    seed_range = selected(seed_source, "seed")
    donor_range = selected(donor_source, "donor")
    require_source_overlay_range_pin(
        seed_range, proof["range_pin"], context + " seed target range"
    )
    require(donor_range == seed_range,
            f"{context} donor changes the target source range")
    require_source_overlay_range_pin(
        donor_range, proof["range_pin"], context + " donor target range"
    )
    return {
        "target_source_size": len(seed_range),
        "target_source_sha256": sha256_bytes(seed_range),
    }


SAME_TU_TEMPLATE_INSTANTIATION_IDENTITY_KIND = (
    "same_tu_template_instantiation_source_identity_v1"
)


SAME_TU_TEMPLATE_INSTANTIATION_SELECTOR = (
    "declaration_carrier_seat_complement_v1"
)


GENERATED_DECLARATION_LINE = re.compile(
    rb"^(?:class|struct)[ ]+[A-Za-z_][A-Za-z0-9_]*[0-9]{2,};$"
    rb"|^extern[ ]int[ ]+[A-Za-z_][A-Za-z0-9_]*[0-9]{2,};$"
)


def require_declaration_carrier_seat_complement(
    seed_source: bytes, donor_source: bytes, context: str,
) -> tuple[int, int]:
    """Prove one rendering is the seed plus two generated declaration blocks.

    `render_same_tu_declaration_carrier` writes a forward-declaration block at
    offset zero and an extern block directly after the last `#include` line,
    and changes nothing else.  This inverts that rule structurally: the donor
    must split into a generated prefix block, the seed's own lines up to and
    including its last `#include`, a generated block, and the seed's remaining
    lines -- every inserted line matching the closed generated grammar.  The
    seed's own lines are compared literally, so a declaration the seed already
    carries can never be masked.
    """
    seed_lines = seed_source.split(b"\n")
    include_rows = [index for index, line in enumerate(seed_lines)
                    if line.startswith(b"#include")]
    require(include_rows, f"{context} seed lacks an include seat")
    insert_at = include_rows[-1] + 1
    head, tail = seed_lines[:insert_at], seed_lines[insert_at:]
    require(head and tail, f"{context} seed include seat is degenerate")
    donor_lines = donor_source.split(b"\n")
    require(
        len(donor_lines) > len(tail)
        and donor_lines[len(donor_lines) - len(tail):] == tail,
        f"{context} rendering does not retain the seed tail",
    )
    rest = donor_lines[:len(donor_lines) - len(tail)]
    splits = [
        index for index in range(len(rest) - len(head) + 1)
        if rest[index:index + len(head)] == head
        and all(GENERATED_DECLARATION_LINE.match(line)
                for line in rest[:index])
        and all(GENERATED_DECLARATION_LINE.match(line)
                for line in rest[index + len(head):])
    ]
    require(len(splits) == 1,
            f"{context} rendering is not the seed plus two carrier blocks")
    index = splits[0]
    return index, len(rest) - index - len(head)


def require_forward_run_placement_complement(
    seed_source: bytes, donor_source: bytes, context: str,
) -> int:
    """Prove one rendering is the seed plus one seated generated run.

    `render_forward_run_with_shape_carrier` writes a forward-declaration run
    either at offset zero or as whole appended lines, and changes nothing
    else.  This inverts that rule structurally: the donor must be the seed's
    own lines, in order and contiguous, with one block of generated
    declaration lines at exactly one end.  The seed's lines are compared
    literally, so a declaration the seed already carries is never masked.
    """
    seed_lines = seed_source.split(b"\n")
    donor_lines = donor_source.split(b"\n")
    require(len(donor_lines) > len(seed_lines),
            f"{context} rendering carries no seated run")
    extra = len(donor_lines) - len(seed_lines)
    prefix_seated = (
        donor_lines[extra:] == seed_lines
        and all(GENERATED_DECLARATION_LINE.match(line)
                for line in donor_lines[:extra])
    )
    suffix_seated = (
        donor_lines[:len(seed_lines)] == seed_lines
        and all(GENERATED_DECLARATION_LINE.match(line)
                for line in donor_lines[len(seed_lines):])
    )
    require(prefix_seated or suffix_seated,
            f"{context} rendering is not the seed plus one seated run")
    return extra


def validate_same_tu_source_identity_proof(
    value: object, context: str,
) -> dict:
    """Validate a complete same-TU function or instantiation source pin."""
    require(isinstance(value, dict), f"{context} must be an object")
    kind = value.get("kind")
    require(
        kind in ("same_tu_function_source_identity_v1",
                 SAME_TU_TEMPLATE_INSTANTIATION_IDENTITY_KIND),
        f"{context} kind differs",
    )
    owner = value.get("source_owner_mangled")
    require(
        isinstance(owner, str) and owner.startswith("?") and len(owner) >= 8,
        f"{context}.source_owner_mangled is invalid",
    )
    if kind == SAME_TU_TEMPLATE_INSTANTIATION_IDENTITY_KIND:
        exact_audit_keys(value, {
            "kind", "selector", "carrier_layout", "source_owner_mangled",
            "range_pin",
        }, context)
        require(
            value.get("selector")
            == SAME_TU_TEMPLATE_INSTANTIATION_SELECTOR,
            f"{context} selector differs",
        )
        layout = value.get("carrier_layout")
        require(
            layout in set(SAME_TU_HYBRID_CARRIER_LAYOUTS.values()),
            f"{context}.carrier_layout is not a closed carrier layout",
        )
        require(
            "@?$" in owner,
            f"{context}.source_owner_mangled is not a template instantiation",
        )
        return {
            "kind": SAME_TU_TEMPLATE_INSTANTIATION_IDENTITY_KIND,
            "selector": SAME_TU_TEMPLATE_INSTANTIATION_SELECTOR,
            "carrier_layout": layout,
            "source_owner_mangled": owner,
            "range_pin": validate_source_overlay_range_pin(
                value.get("range_pin"), context + ".range_pin"),
        }
    exact_audit_keys(value, {
        "kind", "selector", "start_marker", "source_owner_mangled",
        "range_pin",
    }, context)
    require(
        value.get("selector")
        == "brace_balanced_function_physical_line_v1",
        f"{context} selector differs",
    )
    marker = value.get("start_marker")
    require(
        isinstance(marker, str) and marker.isascii()
        and 8 <= len(marker) <= 256
        and not any(character in marker for character in "\0\r\n"),
        f"{context}.start_marker is invalid",
    )
    return {
        "kind": "same_tu_function_source_identity_v1",
        "selector": "brace_balanced_function_physical_line_v1",
        "start_marker": marker,
        "source_owner_mangled": owner,
        "range_pin": validate_source_overlay_range_pin(
            value.get("range_pin"), context + ".range_pin"),
    }


def select_same_tu_source_identity_window(
    data: bytes, proof: dict, context: str,
) -> bytes:
    """Select one function through the LF terminating its closing-brace line."""
    marker = proof["start_marker"].encode("ascii")
    require(data.count(marker) == 1,
            f"{context} start marker is not unique")
    start = data.index(marker)
    tokens = [item for item in source_overlay_tokens(data)
              if item[1] >= start]
    opening = next((index for index, item in enumerate(tokens)
                    if item[0] == "{"), None)
    require(opening is not None, f"{context} function body is missing")
    depth = 0
    close = None
    for token, _, token_end in tokens[opening:]:
        if token == "{":
            depth += 1
        elif token == "}":
            depth -= 1
            require(depth >= 0, f"{context} braces are unbalanced")
            if depth == 0:
                close = token_end
                break
    require(close is not None and close < len(data) and data[close] == 0x0A,
            f"{context} closing brace lacks one physical LF")
    return data[start:close + 1]


def require_same_tu_source_identity(
    seed_source: bytes,
    target_donor_source: bytes,
    instruction_donor_source: bytes,
    proof: dict,
    context: str,
) -> dict:
    """Prove both declaration-carrier donors retain the target source."""
    require(
        all(isinstance(item, bytes) for item in (
            seed_source, target_donor_source, instruction_donor_source)),
        f"{context} source renderings are missing",
    )
    if proof.get("kind") == SAME_TU_TEMPLATE_INSTANTIATION_IDENTITY_KIND:
        layout = proof["carrier_layout"]
        for data, role in ((target_donor_source, "target donor"),
                           (instruction_donor_source, "instruction donor")):
            if layout == "declaration_carrier_seats_v1":
                blocks = sum(require_declaration_carrier_seat_complement(
                    seed_source, data, f"{context} {role}"))
            else:
                blocks = require_forward_run_placement_complement(
                    seed_source, data, f"{context} {role}")
            require(blocks > 0,
                    f"{context} {role} carries no declaration carrier")
        selected = [seed_source, seed_source, seed_source]
    else:
        selected = [
            select_same_tu_source_identity_window(data, proof, context + role)
            for data, role in (
                (seed_source, " seed"),
                (target_donor_source, " target donor"),
                (instruction_donor_source, " instruction donor"),
            )
        ]
    for role, data in zip(("seed", "target donor", "instruction donor"),
                          selected):
        require_source_overlay_range_pin(
            data, proof["range_pin"], f"{context} {role} target range")
    require(selected[0] == selected[1] == selected[2],
            f"{context} target source differs between same-TU donors")
    return {
        "target_source_size": len(selected[0]),
        "target_source_sha256": sha256_bytes(selected[0]),
    }


def validate_target_source_refactor_proof(value: object, context: str) -> dict:
    """Validate one closed manifest-declared source-permutation window."""
    require(isinstance(value, dict), f"{context} must be an object")
    kind = value.get("kind")
    if kind == "single_evaluation_bindings_v1":
        exact_audit_keys(value, {
            "kind", "start_marker", "end_marker", "seed_range_pin",
            "donor_range_pin", "operation_ids",
        }, context)
        marker_names = ("start_marker", "end_marker")
    elif kind in {
        "for_initializer_declaration_reseat_v1",
        "captured_pointer_tail_return_v1",
        "fixed_array_fill_loop_v1",
        "fixed_array_shuffle_pointer_countdown_v1",
        "inclusive_extent_assignment_v1",
        "discarded_postfix_increment_v1",
        "constructor_allocation_lift_v1",
    }:
        required_keys = {
            "kind", "selector", "start_marker", "source_owner_mangled",
            "seed_range_pin", "donor_range_pin", "operation_ids",
        }
        if kind == "fixed_array_fill_loop_v1":
            required_keys.add("array_declaration")
        if kind == "fixed_array_shuffle_pointer_countdown_v1":
            required_keys.add("semantic_witness")
        if kind == "inclusive_extent_assignment_v1":
            required_keys.add("semantic_witness")
        if kind == "discarded_postfix_increment_v1":
            required_keys.add("semantic_witness")
        if kind == "constructor_allocation_lift_v1":
            required_keys |= {"semantic_witness", "constructor_signature"}
        exact_audit_keys(value, required_keys, context)
        require(value.get("selector")
                == "brace_balanced_function_after_marker_v1",
                f"{context}.selector differs")
        owner = value.get("source_owner_mangled")
        require(isinstance(owner, str) and owner.startswith("?")
                and len(owner) >= 8,
                f"{context}.source_owner_mangled is invalid")
        marker_names = ("start_marker",)
    else:
        raise ByteIdentityError(f"{context}.kind is unsupported: {kind!r}")
    markers = {}
    for name in marker_names:
        marker = value.get(name)
        require(isinstance(marker, str) and marker.isascii()
                and 8 <= len(marker) <= 256
                and not any(character in marker for character in "\0\r\n"),
                f"{context}.{name} is invalid")
        markers[name] = marker
    if len(markers) == 2:
        require(markers["start_marker"] != markers["end_marker"],
                f"{context} markers must differ")
    operation_ids = value.get("operation_ids")
    require(
        isinstance(operation_ids, list)
        and 1 <= len(operation_ids) <= 32
        and all(isinstance(item, str)
                and re.fullmatch(r"op_[a-z0-9_]{1,120}", item)
                for item in operation_ids)
        and len(set(operation_ids)) == len(operation_ids),
        f"{context}.operation_ids is invalid",
    )
    if kind == "captured_pointer_tail_return_v1":
        require(len(operation_ids) == 5,
                f"{context}.operation_ids must name the five tail-return "
                "fragments")
    if kind == "fixed_array_fill_loop_v1":
        require(len(operation_ids) == 1,
                f"{context}.operation_ids must name one array-fill "
                "replacement")
    if kind == "fixed_array_shuffle_pointer_countdown_v1":
        require(len(operation_ids) == 1,
                f"{context}.operation_ids must name one array-shuffle "
                "replacement")
    if kind == "inclusive_extent_assignment_v1":
        require(len(operation_ids) == 1,
                f"{context}.operation_ids must name one inclusive-extent "
                "replacement")
    if kind == "discarded_postfix_increment_v1":
        require(len(operation_ids) == 1,
                f"{context}.operation_ids must name one discarded-increment "
                "replacement")
    if kind == "constructor_allocation_lift_v1":
        require(len(operation_ids) == 4,
                f"{context}.operation_ids must name the four bound "
                "allocation-lift roles")
    normalized = {
        "kind": kind,
        **markers,
        "seed_range_pin": validate_source_overlay_range_pin(
            value.get("seed_range_pin"), context + ".seed_range_pin"
        ),
        "donor_range_pin": validate_source_overlay_range_pin(
            value.get("donor_range_pin"), context + ".donor_range_pin"
        ),
        "operation_ids": list(operation_ids),
    }
    if kind in {
        "for_initializer_declaration_reseat_v1",
        "captured_pointer_tail_return_v1",
        "fixed_array_fill_loop_v1",
        "fixed_array_shuffle_pointer_countdown_v1",
        "inclusive_extent_assignment_v1",
        "discarded_postfix_increment_v1",
        "constructor_allocation_lift_v1",
    }:
        normalized.update({
            "selector": value["selector"],
            "source_owner_mangled": value["source_owner_mangled"],
        })
    if kind == "fixed_array_fill_loop_v1":
        normalized["array_declaration"] = (
            validate_fixed_array_declaration_proof(
                value.get("array_declaration"),
                context + ".array_declaration",
            )
        )
    if kind == "fixed_array_shuffle_pointer_countdown_v1":
        normalized["semantic_witness"] = (
            validate_fixed_array_shuffle_semantic_witness(
                value.get("semantic_witness"),
                context + ".semantic_witness",
            )
        )
    if kind == "inclusive_extent_assignment_v1":
        normalized["semantic_witness"] = (
            validate_inclusive_extent_semantic_witness(
                value.get("semantic_witness"),
                context + ".semantic_witness",
            )
        )
    if kind == "discarded_postfix_increment_v1":
        normalized["semantic_witness"] = (
            validate_discarded_increment_semantic_witness(
                value.get("semantic_witness"),
                context + ".semantic_witness",
            )
        )
    if kind == "constructor_allocation_lift_v1":
        normalized["semantic_witness"] = (
            validate_constructor_allocation_lift_semantic_witness(
                value.get("semantic_witness"),
                context + ".semantic_witness",
            )
        )
        # The PROOF, not either generator instance, is the single authority on
        # the new member's identity; the recipe policy then requires both
        # member_signature_v1 operations to be equal to it, so the
        # declaration and the definition header cannot drift apart.
        normalized["constructor_signature"] = (
            validate_member_constructor_signature(
                value.get("constructor_signature"),
                context + ".constructor_signature",
            )
        )
        require(
            normalized["constructor_signature"]["class_identifier"]
            == normalized["semantic_witness"]["entry_class"],
            f"{context}.constructor_signature names a different class than "
            "its semantic witness",
        )
    return normalized


def validate_member_constructor_signature(
    value: object, context: str,
) -> dict:
    """Validate the closed identity of a refactor's new constructor."""
    require(isinstance(value, dict), f"{context} must be an object")
    exact_audit_keys(value, {"class_identifier", "parameters"}, context)
    return {
        "class_identifier": _source_overlay_identifier(
            value.get("class_identifier"), context + ".class_identifier"),
        "parameters": validate_member_signature_parameters(
            value.get("parameters"), context + ".parameters"),
    }


def select_source_permutation_window(
    data: bytes, proof: dict, context: str,
) -> bytes:
    """Select the complete source window authenticated by a proof."""
    start_marker = proof["start_marker"].encode("ascii")
    require(data.count(start_marker) == 1,
            f"{context} start marker is not unique")
    start = data.index(start_marker)
    if proof["kind"] == "single_evaluation_bindings_v1":
        end_marker = proof["end_marker"].encode("ascii")
        require(data.count(end_marker) == 1,
                f"{context} end marker is not unique")
        end = data.index(end_marker)
        require(start < end, f"{context} source markers are reversed")
        return data[start:end]

    require(proof["kind"] in {
                "for_initializer_declaration_reseat_v1",
                "captured_pointer_tail_return_v1",
                "fixed_array_fill_loop_v1",
                "fixed_array_shuffle_pointer_countdown_v1",
                "inclusive_extent_assignment_v1",
                "discarded_postfix_increment_v1",
                "constructor_allocation_lift_v1",
            }
            and proof["selector"]
            == "brace_balanced_function_after_marker_v1",
            f"{context} source selector differs")
    tokens = [item for item in source_overlay_tokens(data)
              if item[1] >= start]
    opening = next((index for index, item in enumerate(tokens)
                    if item[0] == "{"), None)
    require(opening is not None, f"{context} function body is missing")
    depth = 0
    end = None
    for token, _, token_end in tokens[opening:]:
        if token == "{":
            depth += 1
        elif token == "}":
            depth -= 1
            if depth == 0:
                end = token_end
                break
    require(end is not None, f"{context} function body is unbalanced")
    if data[end:end + 1] == b"\n":
        end += 1
    return data[start:end]


def require_target_source_refactor_identity(
    seed_source: bytes, donor_source: bytes, proof: dict, context: str,
) -> dict:
    """Pin both complete target ranges before a refactor donor is composed."""
    require(isinstance(seed_source, bytes) and isinstance(donor_source, bytes),
            f"{context} source renderings are missing")

    seed_range = select_source_permutation_window(
        seed_source, proof, context + " seed")
    donor_range = select_source_permutation_window(
        donor_source, proof, context + " donor")
    require_source_overlay_range_pin(
        seed_range, proof["seed_range_pin"], context + " seed target range"
    )
    require_source_overlay_range_pin(
        donor_range, proof["donor_range_pin"], context + " donor target range"
    )
    require(seed_range != donor_range,
            f"{context} donor does not contain its declared source refactor")
    return {
        "seed_target_source_size": len(seed_range),
        "seed_target_source_sha256": sha256_bytes(seed_range),
        "donor_target_source_size": len(donor_range),
        "donor_target_source_sha256": sha256_bytes(donor_range),
    }


TARGET_REFACTOR_ENTROPY_GENERATOR_KINDS = frozenset({
    "composed_typed_sequence_v1",
    "declaration_sequence_v1",
    "extern_declaration_run_v1",
    "line_reservation_v1",
})


def render_single_evaluation_binding_use(params: dict, value: str) -> str:
    """Render one closed evaluated-use form from manifest fields."""
    use = params["use"]
    indent = params["declaration_indent"]
    if use["kind"] == "new_array_extent_binding":
        element = render_source_overlay_cpp_type(use["element_type"])
        return (f"{indent}{element}* {use['result_identifier']} = "
                f"new {element}[{value}];\n")
    if use["kind"] == "member_assignment_receiver_binding":
        return (f"{indent}{value}->{use['member_identifier']} = "
                f"{use['value_identifier']};\n")
    raise ByteIdentityError(
        f"single-evaluation use kind is unsupported: {use['kind']!r}"
    )


def render_single_evaluation_binding_input(params: dict) -> bytes:
    """Reconstruct the checked-in statement before a bind-once permutation."""
    return render_single_evaluation_binding_use(
        params, params["expression"]
    ).encode("ascii")


def render_single_evaluation_binding_output(params: dict) -> bytes:
    """Render the manifest's declaration plus its one substituted use."""
    declaration = (
        params["declaration_indent"]
        + render_source_overlay_cpp_type(params["declaration_type"])
        + " " + params["identifier"] + " = " + params["expression"] + ";\n"
    )
    use = render_single_evaluation_binding_use(params, params["identifier"])
    return (declaration + use).encode("ascii")


def render_for_initializer_declaration_reseat_input(params: dict) -> bytes:
    """Reconstruct the checked-in side of a closed declaration reseat."""
    indent = params["indentation"]
    iterator_type = render_source_overlay_cpp_type(params["iterator_type"])
    identifier = params["identifier"]
    container = params["container_identifier"]
    begin = params["begin_member"]
    end = params["end_member"]
    declaration_in_initializer = (
        f"{indent}for ({iterator_type} {identifier} = "
        f"{container}.{begin}(); {identifier} != {container}.{end}(); "
        f"{identifier}++) {{\n"
    ).encode("ascii")
    standalone = (
        f"{indent}{iterator_type} {identifier};\n\n"
        f"{indent}for ({identifier} = {container}.{begin}(); "
        f"{identifier} != {container}.{end}(); {identifier}++) {{\n"
    ).encode("ascii")
    if params["form"] == "standalone_then_assignment_v1":
        return declaration_in_initializer
    require(params["form"] == "declaration_in_initializer_v1",
            "for-initializer reseat form differs")
    return standalone


def render_for_initializer_declaration_reseat_output(params: dict) -> bytes:
    """Render the opposite, manifest-selected declaration seat."""
    inverse = dict(params)
    inverse["form"] = (
        "declaration_in_initializer_v1"
        if params["form"] == "standalone_then_assignment_v1"
        else "standalone_then_assignment_v1"
    )
    return render_for_initializer_declaration_reseat_input(inverse)


def render_fixed_array_fill_loop_input(params: dict) -> bytes:
    """Reconstruct the checked-in whole-array fill statement."""
    indent = params["declaration_indent"]
    array = params["array_identifier"]
    return (
        f"{indent}memset({array}, -1, sizeof({array}));\n"
    ).encode("ascii")


def render_fixed_array_fill_loop_output(params: dict) -> bytes:
    """Render one bounded index loop equivalent to the whole-array fill."""
    indent = params["declaration_indent"]
    array = params["array_identifier"]
    index = params["index_identifier"]
    index_type = render_source_overlay_cpp_type(params["index_type"])
    count = params["count"]
    return (
        f"{indent}for ({index_type} {index} = 0; {index} < {count}; "
        f"{index}++) {array}[{index}] = -1;\n"
    ).encode("ascii")


def render_fixed_array_shuffle_countdown_input(params: dict) -> bytes:
    """Reconstruct one canonical indexed in-place array shuffle."""
    indent = params["declaration_indent"]
    inner = indent + "\t"
    array = params["array_identifier"]
    index = params["index_identifier"]
    swap_type = render_source_overlay_cpp_type(params["swap_type"])
    swap = params["swap_identifier"]
    temporary = params["temporary_identifier"]
    temporary_type = render_source_overlay_cpp_type(
        params["temporary_type"])
    random_function = params["random_function"]
    count = params["count"]
    return (
        f"{indent}for ({index} = 0; {index} < {count}; {index}++) {{\n"
        f"{inner}{swap_type} {swap} = {random_function}() % {count};\n"
        f"{inner}{temporary_type} {temporary} = {array}[{index}];\n"
        f"{inner}{array}[{index}] = {array}[{swap}];\n"
        f"{inner}{array}[{swap}] = {temporary};\n"
        f"{indent}}}\n"
    ).encode("ascii")


def render_fixed_array_shuffle_countdown_output(params: dict) -> bytes:
    """Render the equivalent pointer walk with a countdown loop."""
    indent = params["declaration_indent"]
    inner = indent + "\t"
    array = params["array_identifier"]
    index = params["index_identifier"]
    pointer = params["pointer_identifier"]
    element_type = render_source_overlay_cpp_type(params["element_type"])
    swap = params["swap_identifier"]
    swap_type = render_source_overlay_cpp_type(params["swap_type"])
    temporary = params["temporary_identifier"]
    temporary_type = render_source_overlay_cpp_type(
        params["temporary_type"])
    random_function = params["random_function"]
    count = params["count"]
    return (
        f"{indent}{element_type}* {pointer} = {array};\n"
        f"{indent}for ({index} = {count}; {index} != 0; {index}--) {{\n"
        f"{inner}{pointer}++;\n"
        f"{inner}{swap_type} {swap} = {random_function}() % {count};\n"
        f"{inner}{temporary_type} {temporary} = {pointer}[-1];\n"
        f"{inner}{pointer}[-1] = {array}[{swap}];\n"
        f"{inner}{array}[{swap}] = {temporary};\n"
        f"{indent}}}\n"
    ).encode("ascii")


def render_inclusive_extent_assignment_input(params: dict) -> bytes:
    """Reconstruct the checked-in inclusive extent assignment."""
    indent = params["declaration_indent"]
    source = (
        f'{params["source_object"]}.{params["aggregate_accessor"]}()'
    )
    destination = (
        f'{params["destination_object"]}.{params["destination_member"]}'
    )
    return (
        f'{indent}{destination} = '
        f'{source}.{params["seed_extent_accessor"]}();\n'
    ).encode("ascii")


def render_inclusive_extent_assignment_output(params: dict) -> bytes:
    """Render one typed endpoint subtraction with an inert compiler barrier."""
    require(params["barrier"] == INCLUSIVE_EXTENT_BARRIER,
            "inclusive-extent barrier differs")
    indent = params["declaration_indent"]
    coordinate_type = render_source_overlay_cpp_type(
        params["coordinate_type"])
    identifier = params["identifier"]
    source = (
        f'{params["source_object"]}.{params["aggregate_accessor"]}()'
    )
    destination = (
        f'{params["destination_object"]}.{params["destination_member"]}'
    )
    return (
        f'{indent}{coordinate_type} {identifier} = '
        f'{source}.{params["upper_endpoint_accessor"]}() - '
        f'{source}.{params["lower_endpoint_accessor"]}();\n'
        f'{indent}++{identifier};\n'
        '#if defined(_MSC_VER) && defined(_M_IX86)\n'
        f'{indent}__asm {{\n'
        f'{indent}}}\n'
        '#endif\n'
        f'{indent}{destination} = {identifier};\n'
    ).encode("ascii")


def render_discarded_postfix_increment_input(params: dict) -> bytes:
    """Reconstruct one standalone postfix increment with discarded result."""
    return (
        f'{params["declaration_indent"]}{params["identifier"]}++;\n'
    ).encode("ascii")


def render_discarded_postfix_increment_output(params: dict) -> bytes:
    """Render the same standalone state transition through prefix increment."""
    return (
        f'{params["declaration_indent"]}++{params["identifier"]};\n'
    ).encode("ascii")


def render_constructor_allocation_lift_arguments(params: dict) -> str:
    """Render the checked-in call's argument list from one closed field.

    ``null_argument_position`` says which argument carried the null pointer;
    the other carries the caller's own buffer.  There is no free text here and
    no way for the two roles to disagree about which is which.
    """
    position = params["null_argument_position"]
    return ", ".join(
        "NULL" if index == position else params["caller_result_identifier"]
        for index in range(len(params["null_members"]) + 1)
    )


def render_constructor_allocation_lift_input(params: dict) -> bytes:
    """Reconstruct the checked-in caller statements a lift removes.

    This and ``render_constructor_allocation_lift_constructor_body`` are two
    renderings of ONE parameter set: the allocation is named once
    (``element_type``, ``extent_function``, ``copy_function``,
    ``parameter_identifier``) and the two texts differ only in the store
    destination.  There is no field from which they could disagree, so "the
    constructor body is the caller's statements with the buffer substituted"
    is structural rather than asserted.
    """
    indent = params["declaration_indent"]
    element = render_source_overlay_cpp_type(params["element_type"])
    return (
        f'{indent}{element}* {params["caller_result_identifier"]} = '
        f'new {element}[{params["extent_function"]}'
        f'({params["parameter_identifier"]}) + 1];\n'
        f'{indent}{params["copy_function"]}'
        f'({params["caller_result_identifier"]}, '
        f'{params["parameter_identifier"]});\n'
        f'\n'
        f'{indent}{render_source_overlay_cpp_type(params["iterator_type"])} '
        f'{params["iterator_identifier"]} = '
        f'{params["container_identifier"]}.{params["find_member"]}'
        f'({params["class_identifier"]}'
        f'({render_constructor_allocation_lift_arguments(params)}));\n'
    ).encode("ascii")


def render_constructor_allocation_lift_call_site(params: dict) -> bytes:
    """Render the one statement that replaces the removed caller statements."""
    indent = params["declaration_indent"]
    return (
        f'{indent}{render_source_overlay_cpp_type(params["iterator_type"])} '
        f'{params["iterator_identifier"]} = '
        f'{params["container_identifier"]}.{params["find_member"]}'
        f'({params["class_identifier"]}'
        f'({params["parameter_identifier"]}));\n'
    ).encode("ascii")


def render_constructor_allocation_lift_constructor_body(
    params: dict,
) -> bytes:
    """Render the lifted body: the same allocation, stored into the member."""
    element = render_source_overlay_cpp_type(params["element_type"])
    cast = render_source_overlay_cpp_type(params["buffer_cast_type"])
    lines = [
        f'\t{params["buffer_member"]} = new {element}'
        f'[{params["extent_function"]}({params["parameter_identifier"]})'
        f' + 1];',
        f'\t{params["copy_function"]}(({cast}) {params["buffer_member"]}, '
        f'{params["parameter_identifier"]});',
    ]
    lines += [f'\t{member} = NULL;' for member in params["null_members"]]
    # The trailing blank line is part of the closed form, not a separate
    # operation: a lifted definition is always followed by exactly one blank
    # line, so the seat it shares with its definition header renders one
    # complete, separated definition and nothing else.
    return ("\n{\n" + "\n".join(lines) + "\n}\n\n").encode("ascii")


def render_constructor_allocation_lift_output(params: dict) -> bytes:
    """Dispatch the two bound output roles of one closed parameter set."""
    if params["role"] == "call_site":
        return render_constructor_allocation_lift_call_site(params)
    require(params["role"] == "constructor_body",
            "constructor allocation lift role differs")
    return render_constructor_allocation_lift_constructor_body(params)


def decorated_member_owner_identifier(mangled: str, context: str) -> str:
    """Extract one exact class component from a closed MSVC member name."""
    require(isinstance(mangled, str) and mangled.isascii(),
            f"{context}: decorated member identity is invalid")
    constructor = re.match(
        r"^\?\?[01]([A-Za-z_][A-Za-z0-9_]*)@@", mangled)
    ordinary = re.match(
        r"^\?[A-Za-z_][A-Za-z0-9_]*@"
        r"([A-Za-z_][A-Za-z0-9_]*)@@",
        mangled,
    )
    match = constructor or ordinary
    require(match is not None and match.end() < len(mangled),
            f"{context}: decorated member owner is outside the closed form")
    return match.group(1)


def decorated_immediate_member_owner_identifier(
    mangled: str, context: str,
) -> str:
    """Extract the immediate owner component of a possibly nested member."""
    require(isinstance(mangled, str) and mangled.isascii(),
            f"{context}: decorated member identity is invalid")
    match = re.match(
        r"^\?[A-Za-z_][A-Za-z0-9_]*@"
        r"([A-Za-z_][A-Za-z0-9_]*)@",
        mangled,
    )
    require(match is not None and "@@" in mangled[match.end():],
            f"{context}: decorated immediate owner is outside the closed form")
    return match.group(1)


def require_direct_array_header_include(
    source_root: Path,
    unit_source: str,
    unit_data: bytes,
    declaration: dict,
    declaration_path: Path,
    context: str,
) -> dict:
    """Bind a declaration proof to a unique direct quoted TU include."""
    basename = PurePosixPath(declaration["path"]).name
    require(basename and basename.isascii(),
            f"{context}: declaration header basename is invalid")

    # A basename-only quoted include is accepted only when it names exactly
    # one ordinary, non-hidden source-tree file.  This prevents a recipe from
    # pointing the declaration proof at an unrelated same-named header while
    # preserving the source spelling the compiler actually consumes.
    candidates = []
    for candidate in source_root.rglob(basename):
        relative = candidate.relative_to(source_root)
        if any(part.startswith(".") for part in relative.parts):
            continue
        try:
            metadata = candidate.lstat()
            resolved = candidate.resolve(strict=True)
        except OSError as error:
            raise ByteIdentityError(
                f"{context}: declaration include candidate is redirected: "
                f"{error}"
            ) from error
        require(stat.S_ISREG(metadata.st_mode) and not candidate.is_symlink()
                and resolved == candidate,
                f"{context}: declaration include candidate is redirected or "
                "non-regular")
        candidates.append(candidate)
    require(candidates == [declaration_path],
            f"{context}: declaration header is not the unique checked-in "
            "include identity")

    wanted = ["#", "include", f'"{basename}"']
    include_lines = [
        line for line in unit_data.splitlines(keepends=True)
        if [token for token, _, _ in source_overlay_tokens(line)] == wanted
    ]
    require(len(include_lines) == 1,
            f"{context}: target translation unit does not directly include "
            "its declaration header exactly once")
    include_line = include_lines[0]
    include_detail = require_source_overlay_range_pin(
        include_line, declaration["direct_include_range_pin"],
        context + " direct declaration include",
    )
    return {
        "array_declaration_include": basename,
        "array_declaration_include_owner": unit_source,
        **include_detail,
    }


def require_fixed_array_member_use_is_unshadowed(
    target_source: bytes, expected_input: bytes, array_identifier: str,
    context: str,
) -> dict:
    """Confine the member name to the authenticated statement being replaced."""
    expected_count = sum(
        token == array_identifier
        for token, _, _ in source_overlay_tokens(expected_input)
    )
    target_count = sum(
        token == array_identifier
        for token, _, _ in source_overlay_tokens(target_source)
    )
    require(expected_count == 2 and target_count == expected_count,
            f"{context}: array member is shadowed or referenced outside its "
            "authenticated fill statement")
    return {"array_member_source_occurrences": target_count}


def require_fixed_array_declaration_identity(
    root, unit_source: str, unit_data: bytes, target_source: bytes,
    expected_input: bytes, proof: dict, params: dict, context: str,
) -> dict:
    """Prove a literal loop bound equals one pinned integral array extent."""
    declaration = proof["array_declaration"]
    require(
        declaration["array_identifier"] == params["array_identifier"]
        and declaration["extent"] == params["count"],
        f"{context}: array-fill bound differs from its declaration",
    )

    source_root = Path(root).resolve(strict=True)
    path = source_overlay_logical_path(source_root, declaration["path"])
    try:
        metadata = path.lstat()
        resolved = path.resolve(strict=True)
    except OSError as error:
        raise ByteIdentityError(
            f"{context}: array declaration source is absent or redirected: "
            f"{error}"
        ) from error
    require(stat.S_ISREG(metadata.st_mode) and not path.is_symlink()
            and resolved == path and resolved.is_relative_to(source_root),
            f"{context}: array declaration source is redirected or "
            "non-regular")
    data = path.read_bytes()
    require(sha256_bytes(data) == declaration["source_sha256"],
            f"{context}: array declaration source differs from its pin")

    include_detail = require_direct_array_header_include(
        source_root, unit_source, unit_data, declaration, path, context)
    shadow_detail = require_fixed_array_member_use_is_unshadowed(
        target_source, expected_input, declaration["array_identifier"],
        context,
    )

    def significant(data: bytes) -> list[tuple[str, int, int]]:
        return [
            item for item in source_overlay_tokens(data)
            if not item[0].startswith(("//", "/*"))
        ]

    target_tokens = significant(target_source)
    opening = next((index for index, item in enumerate(target_tokens)
                    if item[0] == "{"), None)
    require(opening is not None,
            f"{context}: array-fill source owner has no body")
    qualifiers = [
        index for index, item in enumerate(target_tokens[:opening])
        if item[0] == "::" and index > 0
    ]
    require(qualifiers,
            f"{context}: array-fill source owner is not qualified")
    source_owner = target_tokens[qualifiers[-1] - 1][0]
    require(
        source_owner == declaration["owner_identifier"]
        and source_owner == decorated_member_owner_identifier(
            proof["source_owner_mangled"], context),
        f"{context}: array declaration owner differs from the source owner",
    )

    tokens = significant(data)
    owner_candidates = []
    for index in range(len(tokens) - 2):
        if (tokens[index][0] not in {"class", "struct"}
                or tokens[index + 1][0] != declaration["owner_identifier"]):
            continue
        delimiter = next(
            (cursor for cursor in range(index + 2, len(tokens))
             if tokens[cursor][0] in {"{", ";"}),
            None,
        )
        if delimiter is not None and tokens[delimiter][0] == "{":
            depth = 1
            close = None
            for cursor in range(delimiter + 1, len(tokens)):
                if tokens[cursor][0] == "{":
                    depth += 1
                elif tokens[cursor][0] == "}":
                    depth -= 1
                    if depth == 0:
                        close = cursor
                        break
            require(close is not None,
                    f"{context}: array declaration owner is unbalanced")
            owner_candidates.append((delimiter, close))
    require(len(owner_candidates) == 1,
            f"{context}: array declaration owner is absent or ambiguous")

    element_tokens = [
        item[0] for item in significant(
            render_source_overlay_cpp_type(
                declaration["element_type"]).encode("ascii")
        )
    ]
    wanted = element_tokens + [
        declaration["array_identifier"], "[", str(declaration["extent"]),
        "]", ";",
    ]
    owner_open, owner_close = owner_candidates[0]
    matches = []
    depth = 1
    for index in range(owner_open + 1, owner_close):
        token = tokens[index][0]
        if token == "{":
            depth += 1
            continue
        if token == "}":
            depth -= 1
            continue
        if depth == 1 and [item[0] for item in
                           tokens[index:index + len(wanted)]] == wanted:
            matches.append((tokens[index][1],
                            tokens[index + len(wanted) - 1][2]))
    require(len(matches) == 1,
            f"{context}: integral fixed-array declaration is absent or "
            "ambiguous")
    token_start, token_end = matches[0]
    line_start = data.rfind(b"\n", 0, token_start) + 1
    newline = data.find(b"\n", token_end)
    line_end = len(data) if newline < 0 else newline + 1
    declaration_line = data[line_start:line_end]
    range_detail = require_source_overlay_range_pin(
        declaration_line, declaration["declaration_range_pin"],
        context + " array declaration",
    )
    return {
        "array_declaration_path": declaration["path"],
        "array_element_type": render_source_overlay_cpp_type(
            declaration["element_type"]),
        "array_extent": declaration["extent"],
        **include_detail,
        **shadow_detail,
        **range_detail,
    }


def _semantic_significant_tokens(data: bytes) -> list[tuple[str, int, int]]:
    """Return source tokens excluding comments for structural witnesses."""
    return [
        item for item in source_overlay_tokens(data)
        if not item[0].startswith(("//", "/*"))
    ]


def _unique_class_body(
    tokens: list[tuple[str, int, int]], identifier: str, context: str,
) -> tuple[int, int, int]:
    """Select one complete ordinary class/struct definition by exact name."""
    candidates = []
    for index in range(len(tokens) - 2):
        if (tokens[index][0] not in {"class", "struct"}
                or tokens[index + 1][0] != identifier):
            continue
        opening = next(
            (cursor for cursor in range(index + 2, len(tokens))
             if tokens[cursor][0] in {"{", ";"}),
            None,
        )
        if opening is None or tokens[opening][0] != "{":
            continue
        depth = 1
        closing = None
        for cursor in range(opening + 1, len(tokens)):
            if tokens[cursor][0] == "{":
                depth += 1
            elif tokens[cursor][0] == "}":
                depth -= 1
                if depth == 0:
                    closing = cursor
                    break
        require(closing is not None,
                f"{context}: class {identifier} is unbalanced")
        candidates.append((index, opening, closing))
    require(len(candidates) == 1,
            f"{context}: class {identifier} is absent or ambiguous")
    return candidates[0]


def _unique_class_level_token_range(
    tokens: list[tuple[str, int, int]], opening: int, closing: int,
    wanted: list[str], context: str,
) -> tuple[int, int]:
    """Find one exact token sequence beginning at class scope depth one."""
    matches = []
    depth = 1
    for index in range(opening + 1, closing):
        token = tokens[index][0]
        if depth == 1 and [item[0] for item in
                           tokens[index:index + len(wanted)]] == wanted:
            matches.append((tokens[index][1],
                            tokens[index + len(wanted) - 1][2]))
        if token == "{":
            depth += 1
        elif token == "}":
            depth -= 1
    require(len(matches) == 1,
            f"{context}: semantic declaration is absent or ambiguous")
    return matches[0]


def require_no_class_scope_identifiers(
    tokens: list[tuple[str, int, int]], opening: int, closing: int,
    identifiers: set[str], context: str,
) -> dict:
    """Reject declarations/uses that can hide inherited member accessors."""
    found = []
    depth = 1
    for index in range(opening + 1, closing):
        token = tokens[index][0]
        if depth == 1 and token in identifiers:
            found.append(token)
        if token == "{":
            depth += 1
        elif token == "}":
            depth -= 1
    require(not found,
            f"{context}: concrete class shadows an inherited accessor: "
            f"{sorted(set(found))}")
    return {"concrete_accessor_shadow_count": 0}


def require_inclusive_extent_concrete_class_identity(
    extent_data: bytes, witness: dict, context: str,
) -> dict:
    """Authenticate the concrete extent class and inherited-name closure."""
    extent_tokens = _semantic_significant_tokens(extent_data)
    concrete_index, concrete_open, concrete_close = _unique_class_body(
        extent_tokens, witness["aggregate_type"], context)
    require(concrete_close + 1 < len(extent_tokens)
            and extent_tokens[concrete_close + 1][0] == ";",
            f"{context}: concrete extent class terminator differs")
    concrete_start = extent_data.rfind(
        b"\n", 0, extent_tokens[concrete_index][1]) + 1
    concrete_token_end = extent_tokens[concrete_close + 1][2]
    concrete_newline = extent_data.find(b"\n", concrete_token_end)
    concrete_end = (
        len(extent_data) if concrete_newline < 0 else concrete_newline + 1
    )
    concrete_detail = require_source_overlay_range_pin(
        extent_data[concrete_start:concrete_end],
        witness["extent_header"]["concrete_class_range_pin"],
        context + " body",
    )
    shadow_detail = require_no_class_scope_identifiers(
        extent_tokens, concrete_open, concrete_close,
        {
            witness["lower_accessor"], witness["upper_accessor"],
            witness["extent_accessor"],
        },
        context,
    )
    return {"concrete_class": concrete_detail, **shadow_detail}


def _pinned_source_line(
    data: bytes, token_range: tuple[int, int], pin: dict, context: str,
) -> dict:
    """Authenticate the complete physical line containing a token range."""
    start, end = token_range
    line_start = data.rfind(b"\n", 0, start) + 1
    newline = data.find(b"\n", end)
    line_end = len(data) if newline < 0 else newline + 1
    return require_source_overlay_range_pin(
        data[line_start:line_end], pin, context)


def _read_pinned_semantic_source(
    source_root: Path, spec: dict, context: str,
) -> tuple[Path, bytes]:
    """Read one ordinary, canonical, content-pinned witness source."""
    path = source_overlay_logical_path(source_root, spec["path"])
    try:
        metadata = path.lstat()
        resolved = path.resolve(strict=True)
    except OSError as error:
        raise ByteIdentityError(
            f"{context}: semantic witness source is absent or redirected: "
            f"{error}"
        ) from error
    require(stat.S_ISREG(metadata.st_mode) and not path.is_symlink()
            and resolved == path and resolved.is_relative_to(source_root),
            f"{context}: semantic witness source is redirected or "
            "non-regular")
    data = path.read_bytes()
    require(sha256_bytes(data) == spec["source_sha256"],
            f"{context}: semantic witness source differs from its pin")
    return path, data


def _require_unique_quoted_include_edge(
    source_root: Path, including_path: str, including_data: bytes,
    included_path: Path, pin: dict, context: str,
) -> dict:
    """Bind one exact quoted include to a unique source-tree basename."""
    basename = included_path.name
    require(basename and basename.isascii(),
            f"{context}: include basename is invalid")
    candidates = []
    for candidate in source_root.rglob(basename):
        relative = candidate.relative_to(source_root)
        if any(part.startswith(".") for part in relative.parts):
            continue
        try:
            metadata = candidate.lstat()
            resolved = candidate.resolve(strict=True)
        except OSError as error:
            raise ByteIdentityError(
                f"{context}: include candidate is redirected: {error}"
            ) from error
        require(stat.S_ISREG(metadata.st_mode) and not candidate.is_symlink()
                and resolved == candidate,
                f"{context}: include candidate is redirected or non-regular")
        candidates.append(candidate)
    require(candidates == [included_path],
            f"{context}: included header is not the unique checked-in "
            "basename")
    included_relative = included_path.relative_to(source_root)
    lines = []
    for line in including_data.splitlines(keepends=True):
        tokens = [token for token, _, _ in source_overlay_tokens(line)]
        if len(tokens) != 3 or tokens[:2] != ["#", "include"]:
            continue
        quoted = tokens[2]
        if not (len(quoted) >= 3 and quoted[0] == quoted[-1] == '"'):
            continue
        spelling = PurePosixPath(quoted[1:-1])
        if (spelling.parts
                and included_relative.parts[-len(spelling.parts):]
                == spelling.parts):
            lines.append(line)
    require(len(lines) == 1,
            f"{context}: include edge is absent or ambiguous")
    detail = require_source_overlay_range_pin(
        lines[0], pin, context + " include line")
    return {
        "including_path": including_path,
        "included_basename": basename,
        **detail,
    }


def require_fixed_array_shuffle_semantic_identity(
    root, unit_source: str, unit_data: bytes, target_source: bytes,
    expected_input: bytes, proof: dict, params: dict, context: str,
) -> dict:
    """Prove one indexed shuffle equals its pointer-countdown rendering."""
    witness = proof["semantic_witness"]
    require(
        witness["array_member"] == params["array_identifier"]
        and witness["index_identifier"] == params["index_identifier"]
        and witness["element_type"] == params["element_type"]
        == params["temporary_type"]
        and witness["index_type"] == params["index_type"]
        == params["swap_type"]
        and witness["extent"] == params["count"],
        f"{context}: shuffle roles, types, or extent differ",
    )
    require(
        decorated_member_owner_identifier(
            proof["source_owner_mangled"], context)
        == witness["source_owner"],
        f"{context}: shuffle source owner differs",
    )
    require(target_source.count(expected_input) == 1,
            f"{context}: canonical shuffle input is absent or ambiguous")
    input_start = target_source.index(expected_input)
    input_end = input_start + len(expected_input)

    tokens = _semantic_significant_tokens(target_source)
    opening = next((index for index, item in enumerate(tokens)
                    if item[0] == "{"), None)
    require(opening is not None,
            f"{context}: shuffle source owner has no body")
    qualifiers = [
        index for index, item in enumerate(tokens[:opening])
        if item[0] == "::" and index > 0
    ]
    require(qualifiers
            and tokens[qualifiers[-1] - 1][0] == witness["source_owner"],
            f"{context}: shuffle source owner is not exact")

    pointer = params["pointer_identifier"]
    require(not any(token == pointer for token, _, _ in tokens),
            f"{context}: generated shuffle pointer is not fresh")
    for identifier in (params["swap_identifier"],
                       params["temporary_identifier"]):
        expected_count = sum(
            token == identifier
            for token, _, _ in _semantic_significant_tokens(expected_input)
        )
        occurrences = [
            start for token, start, _ in tokens if token == identifier
        ]
        require(expected_count > 0 and len(occurrences) == expected_count
                and all(input_start <= start < input_end
                        for start in occurrences),
                f"{context}: shuffle local {identifier} is shadowed or "
                "escapes its authenticated loop")
    array_uses = [
        index for index, item in enumerate(tokens)
        if item[0] == params["array_identifier"]
    ]
    require(array_uses and all(
                index + 1 < len(tokens) and tokens[index + 1][0] == "["
                and (index == 0 or tokens[index - 1][0] not in {
                    "class", "struct", "typedef", "const", "volatile", "*",
                    "&", render_source_overlay_cpp_type(
                        params["element_type"]),
                })
                for index in array_uses),
            f"{context}: shuffle array member is shadowed or escapes indexed "
            "use")

    index_type = render_source_overlay_cpp_type(params["index_type"])
    index_identifier = params["index_identifier"]
    declaration_pattern = [index_type, index_identifier, ";"]
    declaration_matches = [
        index for index in range(len(tokens) - len(declaration_pattern) + 1)
        if [item[0] for item in
            tokens[index:index + len(declaration_pattern)]]
        == declaration_pattern
    ]
    require(len(declaration_matches) == 1,
            f"{context}: shuffle index declaration is absent or ambiguous")
    declaration_offset = tokens[declaration_matches[0]][1]
    require(declaration_offset < input_start,
            f"{context}: shuffle index is declared after its use")

    next_lines = [
        line for line in target_source[input_end:].splitlines(keepends=True)
        if any(not token.startswith(("//", "/*"))
               for token, _, _ in source_overlay_tokens(line))
    ]
    require(next_lines,
            f"{context}: shuffle index has no authenticated overwrite")
    next_detail = require_source_overlay_range_pin(
        next_lines[0], witness["next_index_overwrite_range_pin"],
        context + " next index overwrite",
    )
    next_tokens = [
        token for token, _, _ in _semantic_significant_tokens(next_lines[0])
    ]
    require(next_tokens[:6] == [
                "for", "(", index_identifier, "=", "0", ";",
            ],
            f"{context}: shuffle index is not overwritten before its next "
            "read")

    # The declaration, replaced shuffle, and next overwrite must share the
    # same immediate lexical block. This closes a shadow in a nested scope.
    def lexical_stack(position: int) -> tuple[int, ...]:
        stack = []
        serial = 0
        for token, start, _ in tokens:
            if start >= position:
                break
            if token == "{":
                serial += 1
                stack.append(serial)
            elif token == "}":
                require(stack, f"{context}: source braces are unbalanced")
                stack.pop()
        return tuple(stack)

    next_offset = target_source.index(next_lines[0], input_end)
    require(lexical_stack(declaration_offset)
            == lexical_stack(input_start)
            == lexical_stack(next_offset),
            f"{context}: shuffle index declaration/overwrite scopes differ")

    source_root = Path(root).resolve(strict=True)
    owner_path, owner_data = _read_pinned_semantic_source(
        source_root, witness["owner_header"], context + " owner header")
    base_path, base_data = _read_pinned_semantic_source(
        source_root, witness["base_header"], context + " base header")
    types_path, types_data = _read_pinned_semantic_source(
        source_root, witness["types_header"], context + " types header")
    include_details = [
        _require_unique_quoted_include_edge(
            source_root, unit_source, unit_data, owner_path,
            witness["owner_header"]["unit_include_range_pin"],
            context + " unit-to-owner"),
        _require_unique_quoted_include_edge(
            source_root, witness["owner_header"]["path"], owner_data,
            base_path, witness["owner_header"]["base_include_range_pin"],
            context + " owner-to-base"),
        _require_unique_quoted_include_edge(
            source_root, witness["base_header"]["path"], base_data,
            types_path, witness["base_header"]["types_include_range_pin"],
            context + " base-to-types"),
    ]

    owner_tokens = _semantic_significant_tokens(owner_data)
    _, owner_open, owner_close = _unique_class_body(
        owner_tokens, witness["source_owner"], context)
    element_type = render_source_overlay_cpp_type(witness["element_type"])
    declaration_range = _unique_class_level_token_range(
        owner_tokens, owner_open, owner_close,
        [element_type, witness["array_member"], "[",
         str(witness["extent"]), "]", ";"],
        context + " array member")
    declaration_detail = _pinned_source_line(
        owner_data, declaration_range,
        witness["owner_header"]["array_declaration_range_pin"],
        context + " array declaration")
    declaration_line_start = owner_data.rfind(
        b"\n", 0, declaration_range[0]) + 1
    block_start = owner_data.rfind(b"\n", 0, max(0, declaration_line_start - 1)) + 1
    declaration_line_end = owner_data.find(b"\n", declaration_range[1])
    require(declaration_line_end >= 0,
            f"{context}: array declaration line is unterminated")
    block_end_newline = owner_data.find(b"\n", declaration_line_end + 1)
    require(block_end_newline >= 0,
            f"{context}: array member block is unterminated")
    member_block_detail = require_source_overlay_range_pin(
        owner_data[block_start:block_end_newline + 1],
        witness["owner_header"]["member_block_range_pin"],
        context + " array member block")

    type_tokens = _semantic_significant_tokens(types_data)

    def typedef_line(type_name: str, underlying: list[str], pin: dict,
                     label: str) -> dict:
        wanted = ["typedef", *underlying, type_name, ";"]
        matches = [
            (type_tokens[index][1],
             type_tokens[index + len(wanted) - 1][2])
            for index in range(len(type_tokens) - len(wanted) + 1)
            if [item[0] for item in
                type_tokens[index:index + len(wanted)]] == wanted
        ]
        require(len(matches) == 1,
                f"{context}: {label} typedef is absent or ambiguous")
        return _pinned_source_line(
            types_data, matches[0], pin, context + " " + label + " typedef")

    element_detail = typedef_line(
        element_type, ["unsigned", "short"],
        witness["types_header"]["element_typedef_range_pin"], "element")
    index_detail = typedef_line(
        index_type, ["signed", "int"],
        witness["types_header"]["index_typedef_range_pin"], "index")
    return {
        "shuffle_source_owner": witness["source_owner"],
        "shuffle_array_member": witness["array_member"],
        "shuffle_extent": witness["extent"],
        "shuffle_include_edges": len(include_details),
        "shuffle_array_use_count": len(array_uses),
        "shuffle_witness_sha256": sha256_bytes(canonical_json_bytes({
            "includes": include_details,
            "declaration": declaration_detail,
            "member_block": member_block_detail,
            "element": element_detail,
            "index": index_detail,
            "next_overwrite": next_detail,
        })),
    }


def _class_scope_member_declaration_tokens(member: dict) -> list[str]:
    """The exact class-scope token run one plain data member occupies."""
    return (
        [token for token, _, _ in source_overlay_tokens(
            render_source_overlay_cpp_type(member["type"]).encode("ascii"))]
        + [member["identifier"], ";"]
    )


def _constructor_allocation_lift_argument_members(witness: dict) -> list[dict]:
    """Map each checked-in constructor argument position to its member.

    ``null_argument_position`` names the position that carried the null
    pointer; the remaining position carries the buffer.  With exactly one
    nulled member this mapping is total and unambiguous, and it is the fact
    that makes ``m_sound = NULL;`` plus ``m_name = <allocation>;`` have the
    same state effect as the removed two-argument temporary.
    """
    members = []
    remaining = list(witness["null_members"])
    for position in range(len(witness["null_members"]) + 1):
        if position == witness["null_argument_position"]:
            members.append(remaining.pop(0))
        else:
            members.append({
                "identifier": witness["buffer_member"],
                "type": witness["buffer_member_type"],
            })
    return members


def _constructor_allocation_lift_called_identifiers(data: bytes) -> set[str]:
    """Identifiers this rendered text applies as a function or constructor."""
    tokens = [item[0] for item in source_overlay_tokens(data)]
    return {
        token for index, token in enumerate(tokens)
        if SOURCE_OVERLAY_IDENTIFIER_RE.fullmatch(token)
        and index + 1 < len(tokens) and tokens[index + 1] == "("
    }


def require_constructor_allocation_lift_semantic_identity(
    root, unit_source: str, unit_data: bytes, target_source: bytes,
    expected_input: bytes, proof: dict, params: dict, context: str,
) -> dict:
    """Prove the lifted constructor equals the caller statements it replaces.

    The equality of the two rendered texts is structural (one parameter set,
    two renderers).  What this adds is everything the rendering cannot know:
    that the members exist with the pinned types on the pinned class, that the
    checked-in constructor's argument roles are what the lift assumes, that
    the temporary's destructor still frees the buffer at the same point, that
    the removed local escapes nowhere, and that the lifted body calls nothing
    the checked-in statements did not already call.
    """
    witness = proof["semantic_witness"]
    require(
        witness["entry_class"] == params["class_identifier"]
        and witness["buffer_member"] == params["buffer_member"]
        and witness["null_argument_position"]
        == params["null_argument_position"]
        and [item["identifier"] for item in witness["null_members"]]
        == params["null_members"],
        f"{context}: allocation-lift roles differ from their witness",
    )
    require(
        {**witness["buffer_member_type"], "base_const": False}
        == params["buffer_cast_type"],
        f"{context}: the buffer cast is not a const strip of the pinned "
        "member type",
    )
    require(
        decorated_member_owner_identifier(
            proof["source_owner_mangled"], context)
        == witness["source_owner"],
        f"{context}: allocation-lift source owner differs",
    )

    tokens = _semantic_significant_tokens(target_source)
    opening = next((index for index, item in enumerate(tokens)
                    if item[0] == "{"), None)
    require(opening is not None,
            f"{context}: allocation-lift source owner has no body")
    qualifiers = [
        index for index, item in enumerate(tokens[:opening])
        if item[0] == "::" and index > 0
    ]
    require(qualifiers
            and tokens[qualifiers[-1] - 1][0] == witness["source_owner"],
            f"{context}: allocation-lift source owner is not exact")

    # (d) second half: the substituted identifier must be the target
    # function's OWN parameter, proved from the declarator's parameter list.
    open_paren = next(
        (index for index in range(opening - 1, -1, -1)
         if tokens[index][0] == "("), None)
    require(open_paren is not None,
            f"{context}: allocation-lift target has no parameter list")
    depth = 0
    close_paren = None
    for index in range(open_paren, opening):
        if tokens[index][0] == "(":
            depth += 1
        elif tokens[index][0] == ")":
            depth -= 1
            if depth == 0:
                close_paren = index
                break
    require(close_paren is not None,
            f"{context}: allocation-lift target parameter list is unbalanced")
    parameter_tokens = [
        item[0] for item in tokens[open_paren + 1:close_paren]
    ]
    require(parameter_tokens.count(params["parameter_identifier"]) == 1,
            f"{context}: substituted identifier is not the target function's "
            "own parameter")
    parameter_detail = _pinned_source_line(
        target_source,
        (tokens[open_paren][1], tokens[close_paren][2]),
        witness["target_parameter_range_pin"],
        context + " target parameter list",
    )

    # (d) first half: the removed local must occur only inside the removed
    # range, so deleting its declaration can leave no dangling use.
    require(target_source.count(expected_input) == 1,
            f"{context}: canonical allocation-lift input is absent or "
            "ambiguous")
    input_start = target_source.index(expected_input)
    input_end = input_start + len(expected_input)
    caller_result = params["caller_result_identifier"]
    expected_count = sum(
        token == caller_result
        for token, _, _ in _semantic_significant_tokens(expected_input)
    )
    occurrences = [
        start for token, start, _ in tokens if token == caller_result
    ]
    require(expected_count > 0 and len(occurrences) == expected_count
            and all(input_start <= start < input_end
                    for start in occurrences),
            f"{context}: removed local {caller_result} is shadowed or "
            "escapes its authenticated range")

    source_root = Path(root).resolve(strict=True)
    owner_path, owner_data = _read_pinned_semantic_source(
        source_root, witness["owner_header"], context + " owner header")
    include_detail = _require_unique_quoted_include_edge(
        source_root, unit_source, unit_data, owner_path,
        witness["owner_header"]["unit_include_range_pin"],
        context + " unit-to-owner")

    owner_tokens = _semantic_significant_tokens(owner_data)
    class_index, class_open, class_close = _unique_class_body(
        owner_tokens, witness["entry_class"], context)
    class_body_detail = require_source_overlay_range_pin(
        owner_data[
            owner_data.rfind(b"\n", 0, owner_tokens[class_index][1]) + 1:
            owner_data.find(b"\n", owner_tokens[class_close][2]) + 1
        ],
        witness["owner_header"]["class_body_range_pin"],
        context + " entry class body",
    )

    buffer_detail = _pinned_source_line(
        owner_data,
        _unique_class_level_token_range(
            owner_tokens, class_open, class_close,
            _class_scope_member_declaration_tokens({
                "identifier": witness["buffer_member"],
                "type": witness["buffer_member_type"],
            }),
            context + " buffer member"),
        witness["owner_header"]["buffer_member_declaration_range_pin"],
        context + " buffer member declaration",
    )
    null_details = [
        _pinned_source_line(
            owner_data,
            _unique_class_level_token_range(
                owner_tokens, class_open, class_close,
                _class_scope_member_declaration_tokens(member),
                context + f" nulled member {member['identifier']}"),
            pin, context + f" nulled member {member['identifier']}"
                            " declaration",
        )
        for member, pin in zip(
            witness["null_members"],
            witness["owner_header"]["null_member_declaration_range_pins"],
        )
    ]

    # (c)(1): the checked-in constructor's argument roles, as one exact
    # class-scope token run including its complete mem-init list.
    argument_members = _constructor_allocation_lift_argument_members(witness)
    parameter_identifiers = witness[
        "baseline_constructor_parameter_identifiers"]
    wanted = [witness["entry_class"], "("]
    for position, member in enumerate(argument_members):
        if position:
            wanted.append(",")
        wanted += [
            token for token, _, _ in source_overlay_tokens(
                render_source_overlay_cpp_type(
                    member["type"]).encode("ascii"))
        ]
        wanted.append(parameter_identifiers[position])
    wanted.append(")")
    wanted.append(":")
    for position, member in enumerate(argument_members):
        if position:
            wanted.append(",")
        wanted += [member["identifier"], "(",
                   parameter_identifiers[position], ")"]
    wanted += ["{", "}"]
    constructor_detail = _pinned_source_line(
        owner_data,
        _unique_class_level_token_range(
            owner_tokens, class_open, class_close, wanted,
            context + " baseline constructor"),
        witness["owner_header"]["baseline_constructor_range_pin"],
        context + " baseline constructor",
    )

    # (c)(3): ownership is unchanged -- the temporary is still built with the
    # nulled member null, so its destructor still frees the buffer.
    destructor_start, _ = _unique_class_level_token_range(
        owner_tokens, class_open, class_close,
        ["~", witness["entry_class"], "(", ")"],
        context + " entry destructor")
    body_open = next(
        (index for index, item in enumerate(owner_tokens)
         if item[1] >= destructor_start and item[0] == "{"), None)
    require(body_open is not None,
            f"{context}: entry destructor has no body")
    depth = 0
    body_close = None
    for index in range(body_open, class_close):
        if owner_tokens[index][0] == "{":
            depth += 1
        elif owner_tokens[index][0] == "}":
            depth -= 1
            if depth == 0:
                body_close = index
                break
    require(body_close is not None,
            f"{context}: entry destructor body is unbalanced")
    guard = [item[0] for item in owner_tokens[body_open + 1:body_close]]
    nulled = witness["null_members"][0]["identifier"]
    expected_guard = (
        ["if", "(", nulled, "==", "NULL", "&&", witness["buffer_member"],
         "!=", "NULL", ")", "{", "delete", "[", "]", "const_cast", "<"]
        + [token for token, _, _ in source_overlay_tokens(
            render_source_overlay_cpp_type(
                params["buffer_cast_type"]).encode("ascii"))]
        + [">", "(", witness["buffer_member"], ")", ";", "}"]
    )
    require(guard == expected_guard,
            f"{context}: entry destructor does not free the buffer under the "
            "nulled-member guard")
    destructor_detail = require_source_overlay_range_pin(
        owner_data[owner_tokens[body_open][1]:owner_tokens[body_close][2]],
        witness["owner_header"]["destructor_body_range_pin"],
        context + " entry destructor body",
    )

    # (7): the overload the signature generators mint must not already exist
    # on the pinned class.
    require(
        source_overlay_constructor_overload_count(
            owner_data, witness["entry_class"],
            proof["constructor_signature"]["parameters"]) == 0,
        f"{context}: the lifted constructor overload already exists on "
        f"{witness['entry_class']}",
    )

    # (c)(4): no new external dependency -- the rendered body may apply only
    # identifiers the pinned checked-in statements already applied.
    body = render_constructor_allocation_lift_constructor_body(params)
    introduced = (
        _constructor_allocation_lift_called_identifiers(body)
        - _constructor_allocation_lift_called_identifiers(expected_input)
    )
    require(not introduced,
            f"{context}: lifted body introduces a called identifier the "
            f"checked-in statements do not call: {sorted(introduced)}")

    return {
        "allocation_lift_source_owner": witness["source_owner"],
        "allocation_lift_entry_class": witness["entry_class"],
        "allocation_lift_buffer_member": witness["buffer_member"],
        "allocation_lift_nulled_members": [
            item["identifier"] for item in witness["null_members"]
        ],
        "constructor_allocation_lift_witness_sha256": sha256_bytes(
            canonical_json_bytes({
                "include": include_detail,
                "class_body": class_body_detail,
                "buffer_member": buffer_detail,
                "null_members": null_details,
                "baseline_constructor": constructor_detail,
                "destructor_body": destructor_detail,
                "target_parameters": parameter_detail,
            })
        ),
    }


def require_identifier_fresh_at_source_seat(
    target_source: bytes, seat: int, identifier: str, context: str,
) -> dict:
    """Prove a new local is fresh in its block and every visible ancestor."""
    require(0 <= seat <= len(target_source),
            f"{context}: source seat is outside its target")
    tokens = _semantic_significant_tokens(target_source)
    scopes = []
    stack = []
    for token, start, end in tokens:
        if token == "{":
            scope = {"open": end, "close": None}
            scopes.append(scope)
            stack.append(scope)
        elif token == "}":
            require(stack, f"{context}: source braces are unbalanced")
            stack.pop()["close"] = start
    require(not stack and scopes
            and all(scope["close"] is not None for scope in scopes),
            f"{context}: source braces are unbalanced")
    ancestors = [
        scope for scope in scopes
        if scope["open"] <= seat <= scope["close"]
    ]
    require(ancestors, f"{context}: source seat has no lexical scope")
    target_scope = min(
        ancestors, key=lambda item: item["close"] - item["open"])
    ancestor_ids = {id(scope) for scope in ancestors}
    occurrences = [
        start for token, start, _ in tokens if token == identifier
    ]
    for occurrence in occurrences:
        if target_scope["open"] <= occurrence <= target_scope["close"]:
            raise ByteIdentityError(
                f"{context}: local is not fresh in its destination block: "
                f"{identifier}"
            )
        containing = [
            scope for scope in scopes
            if scope["open"] <= occurrence <= scope["close"]
        ]
        if not containing:
            raise ByteIdentityError(
                f"{context}: local collides with a function declaration: "
                f"{identifier}"
            )
        occurrence_scope = min(
            containing, key=lambda item: item["close"] - item["open"])
        if id(occurrence_scope) in ancestor_ids:
            raise ByteIdentityError(
                f"{context}: local collides with a visible ancestor: "
                f"{identifier}"
            )
    return {
        "fresh_local_identifier": identifier,
        "fresh_local_disjoint_occurrences": len(occurrences),
    }


def require_inclusive_extent_semantic_identity(
    root, unit_source: str, unit_data: bytes, target_source: bytes,
    proof: dict, params: dict, context: str,
) -> dict:
    """Prove endpoint subtraction plus increment equals one extent reader."""
    witness = proof["semantic_witness"]
    role_pairs = (
        ("source_object", "source_member"),
        ("aggregate_accessor", "aggregate_accessor"),
        ("seed_extent_accessor", "extent_accessor"),
        ("upper_endpoint_accessor", "upper_accessor"),
        ("lower_endpoint_accessor", "lower_accessor"),
    )
    require(all(params[param_name] == witness[witness_name]
                for param_name, witness_name in role_pairs)
            and params["coordinate_type"] == witness["coordinate_type"],
            f"{context}: inclusive-extent roles differ from their witness")
    require(decorated_member_owner_identifier(
                proof["source_owner_mangled"], context)
            == witness["source_owner"],
            f"{context}: inclusive-extent source owner differs")

    target_tokens = _semantic_significant_tokens(target_source)
    opening = next((index for index, item in enumerate(target_tokens)
                    if item[0] == "{"), None)
    require(opening is not None,
            f"{context}: inclusive-extent source owner has no body")
    qualifiers = [
        index for index, item in enumerate(target_tokens[:opening])
        if item[0] == "::" and index > 0
    ]
    require(qualifiers
            and target_tokens[qualifiers[-1] - 1][0]
            == witness["source_owner"],
            f"{context}: inclusive-extent source owner is not exact")
    source_uses = [
        index for index, item in enumerate(target_tokens)
        if item[0] == witness["source_member"]
    ]
    require(source_uses and all(index > opening for index in source_uses)
            and all(
                index + 1 < len(target_tokens)
                and (
                    target_tokens[index + 1][0] == "."
                    or (
                        target_tokens[index + 1][0] == "="
                        and target_tokens[index - 1][0] in {"{", "}", ";"}
                    )
                )
                for index in source_uses
            ),
            f"{context}: extent source member is shadowed or redeclared")

    source_root = Path(root).resolve(strict=True)
    owner_spec = witness["source_owner_header"]
    accessor_spec = witness["source_accessor_header"]
    extent_spec = witness["extent_header"]
    owner_path, owner_data = _read_pinned_semantic_source(
        source_root, owner_spec, context + " source owner header")
    accessor_path, accessor_data = _read_pinned_semantic_source(
        source_root, accessor_spec, context + " source accessor header")
    extent_path, extent_data = _read_pinned_semantic_source(
        source_root, extent_spec, context + " extent header")

    include_details = [
        _require_unique_quoted_include_edge(
            source_root, unit_source, unit_data, owner_path,
            owner_spec["unit_include_range_pin"],
            context + " unit-to-owner"),
        _require_unique_quoted_include_edge(
            source_root, owner_spec["path"], owner_data, accessor_path,
            accessor_spec["owner_include_range_pin"],
            context + " owner-to-accessor"),
        _require_unique_quoted_include_edge(
            source_root, accessor_spec["path"], accessor_data, extent_path,
            extent_spec["accessor_include_range_pin"],
            context + " accessor-to-extent"),
    ]

    owner_tokens = _semantic_significant_tokens(owner_data)
    _, owner_open, owner_close = _unique_class_body(
        owner_tokens, witness["source_owner"], context)
    member_range = _unique_class_level_token_range(
        owner_tokens, owner_open, owner_close,
        [witness["source_member_type"], witness["source_member"], ";"],
        context + " source member")
    member_detail = _pinned_source_line(
        owner_data, member_range,
        owner_spec["member_declaration_range_pin"],
        context + " source member line")

    accessor_tokens = _semantic_significant_tokens(accessor_data)
    _, accessor_open, accessor_close = _unique_class_body(
        accessor_tokens, witness["source_member_type"], context)
    accessor_range = _unique_class_level_token_range(
        accessor_tokens, accessor_open, accessor_close,
        [witness["aggregate_type"], "&", witness["aggregate_accessor"],
         "(", ")", "{", "return", witness["aggregate_member"], ";", "}"],
        context + " aggregate accessor")
    accessor_detail = _pinned_source_line(
        accessor_data, accessor_range, accessor_spec["accessor_range_pin"],
        context + " aggregate accessor line")

    extent_tokens = _semantic_significant_tokens(extent_data)
    template_index, extent_open, extent_close = _unique_class_body(
        extent_tokens, witness["extent_template"], context)
    template_prefix = [
        "template", "<", "class", witness["template_parameter"], ">",
        "class", witness["extent_template"],
    ]
    require(template_index >= 5
            and [item[0] for item in
                 extent_tokens[template_index - 5:template_index + 2]]
            == template_prefix,
            f"{context}: extent template declaration differs")
    parameter = witness["template_parameter"]
    lower_range = _unique_class_level_token_range(
        extent_tokens, extent_open, extent_close,
        [parameter, witness["lower_accessor"], "(", ")", "const", "{",
         "return", witness["lower_member"], ";", "}"],
        context + " lower endpoint accessor")
    upper_range = _unique_class_level_token_range(
        extent_tokens, extent_open, extent_close,
        [parameter, witness["upper_accessor"], "(", ")", "const", "{",
         "return", witness["upper_member"], ";", "}"],
        context + " upper endpoint accessor")
    extent_range = _unique_class_level_token_range(
        extent_tokens, extent_open, extent_close,
        [parameter, witness["extent_accessor"], "(", ")", "const", "{",
         "return", "(", witness["upper_member"], "-",
         witness["lower_member"], "+", "1", ")", ";", "}"],
        context + " inclusive extent accessor")

    coordinate_tokens = [
        item[0] for item in _semantic_significant_tokens(
            render_source_overlay_cpp_type(
                witness["coordinate_type"]).encode("ascii"))
    ]
    inheritance_wanted = [
        "class", witness["aggregate_type"], ":", "public",
        witness["extent_template"], "<", *coordinate_tokens, ">", "{",
    ]
    inheritance_matches = []
    for index in range(len(extent_tokens) - len(inheritance_wanted) + 1):
        if [item[0] for item in
                extent_tokens[index:index + len(inheritance_wanted)]] \
                == inheritance_wanted:
            inheritance_matches.append((
                extent_tokens[index][1],
                extent_tokens[index + len(inheritance_wanted) - 1][2],
            ))
    require(len(inheritance_matches) == 1,
            f"{context}: concrete extent inheritance is absent or ambiguous")
    concrete_identity = require_inclusive_extent_concrete_class_identity(
        extent_data, witness, context + " concrete extent class")

    line_details = [
        _pinned_source_line(
            extent_data, inheritance_matches[0],
            extent_spec["concrete_inheritance_range_pin"],
            context + " concrete inheritance line"),
        _pinned_source_line(
            extent_data, lower_range,
            extent_spec["lower_accessor_range_pin"],
            context + " lower accessor line"),
        _pinned_source_line(
            extent_data, upper_range,
            extent_spec["upper_accessor_range_pin"],
            context + " upper accessor line"),
        _pinned_source_line(
            extent_data, extent_range,
            extent_spec["extent_accessor_range_pin"],
            context + " extent accessor line"),
    ]
    return {
        "inclusive_extent_source_owner": witness["source_owner"],
        "inclusive_extent_source_member": witness["source_member"],
        "inclusive_extent_coordinate_type": render_source_overlay_cpp_type(
            witness["coordinate_type"]),
        "inclusive_extent_source_use_count": len(source_uses),
        "inclusive_extent_include_edges": len(include_details),
        "inclusive_extent_semantic_lines": 6,
        "inclusive_extent_witness_sha256": sha256_bytes(
            canonical_json_bytes({
                "includes": include_details,
                "member": member_detail,
                "accessor": accessor_detail,
                "extent": line_details,
                "concrete": concrete_identity["concrete_class"],
            })),
        "concrete_accessor_shadow_count":
            concrete_identity["concrete_accessor_shadow_count"],
    }


def _read_pinned_toolchain_semantic_source(
    compiler_root: Path, sealed_include_trees: list[dict], spec: dict,
    context: str,
) -> tuple[Path, bytes]:
    """Read one exact regular header below a sealed compiler include root."""
    require(isinstance(sealed_include_trees, list),
            f"{context}: sealed include-tree census is missing")
    matches = [
        item for item in sealed_include_trees
        if isinstance(item, dict) and item.get("role") == spec["tree_role"]
    ]
    require(len(matches) == 1,
            f"{context}: compiler include-tree role is absent or ambiguous")
    tree = matches[0]
    root = Path(compiler_root).resolve(strict=True) / tree["path"]
    require(root.is_dir() and not root.is_symlink(),
            f"{context}: compiler include root is redirected")
    path = source_overlay_logical_path(root, spec["path"])
    try:
        metadata = path.lstat()
        resolved = path.resolve(strict=True)
    except OSError as error:
        raise ByteIdentityError(
            f"{context}: compiler semantic header is absent or redirected: "
            f"{error}"
        ) from error
    require(stat.S_ISREG(metadata.st_mode) and not path.is_symlink()
            and resolved == path and resolved.is_relative_to(root),
            f"{context}: compiler semantic header is redirected or "
            "non-regular")
    data = path.read_bytes()
    require(sha256_bytes(data) == spec["source_sha256"],
            f"{context}: compiler semantic header differs from its pin")
    return path, data


def _require_unique_angle_include(
    data: bytes, spelling: str, pin: dict, context: str,
) -> dict:
    """Authenticate one exact angle-bracket include spelling and line."""
    require(isinstance(spelling, str) and spelling.isascii()
            and re.fullmatch(r"[A-Za-z_][A-Za-z0-9_.]*", spelling),
            f"{context}: include spelling is invalid")
    wanted = ["#", "include", "<", spelling, ">"]
    lines = [
        line for line in data.splitlines(keepends=True)
        if [token for token, _, _ in source_overlay_tokens(line)] == wanted
    ]
    require(len(lines) == 1,
            f"{context}: angle include edge is absent or ambiguous")
    return require_source_overlay_range_pin(
        lines[0], pin, context + " include line")


def _unique_nested_class_body(
    tokens: list[tuple[str, int, int]], outer_open: int, outer_close: int,
    identifier: str, context: str,
) -> tuple[int, int, int]:
    """Select one directly nested class definition by exact identifier."""
    candidates = []
    depth = 1
    for index in range(outer_open + 1, outer_close):
        token = tokens[index][0]
        if (depth == 1 and token == "class"
                and index + 2 < outer_close
                and tokens[index + 1][0] == identifier):
            opening = next(
                (cursor for cursor in range(index + 2, outer_close)
                 if tokens[cursor][0] in {"{", ";"}),
                None,
            )
            if opening is not None and tokens[opening][0] == "{":
                nested_depth = 1
                closing = None
                for cursor in range(opening + 1, outer_close):
                    if tokens[cursor][0] == "{":
                        nested_depth += 1
                    elif tokens[cursor][0] == "}":
                        nested_depth -= 1
                        if nested_depth == 0:
                            closing = cursor
                            break
                require(closing is not None,
                        f"{context}: nested class is unbalanced")
                candidates.append((index, opening, closing))
        if token == "{":
            depth += 1
        elif token == "}":
            depth -= 1
    require(len(candidates) == 1,
            f"{context}: nested class is absent or ambiguous")
    return candidates[0]


def _physical_source_range_for_tokens(
    data: bytes, tokens: list[tuple[str, int, int]], start: int, close: int,
    context: str,
) -> tuple[int, int]:
    """Expand a class token span through its required `;` and full lines."""
    require(close + 1 < len(tokens) and tokens[close + 1][0] == ";",
            f"{context}: class definition lacks its terminator")
    begin = data.rfind(b"\n", 0, tokens[start][1]) + 1
    newline = data.find(b"\n", tokens[close + 1][2])
    end = len(data) if newline < 0 else newline + 1
    return begin, end


def _direct_class_scope_tokens(
    tokens: list[tuple[str, int, int]], opening: int, closing: int,
) -> list[str]:
    """Project tokens at direct class scope, excluding all method bodies."""
    result = []
    depth = 1
    for index in range(opening + 1, closing):
        token = tokens[index][0]
        if depth == 1:
            result.append(token)
        if token == "{":
            depth += 1
        elif token == "}":
            depth -= 1
    return result


def require_discarded_increment_semantic_identity(
    root, unit_source: str, unit_data: bytes, target_source: bytes,
    proof: dict, params: dict, context: str, *, compiler_root,
    sealed_include_trees: list[dict],
) -> dict:
    """Prove a discarded postfix increment has the prefix state effect.

    The source declaration binds the local through the project alias, the
    repository include chain binds that alias to the sealed compiler MAP and
    XTREE headers, and the nested iterator methods prove both forms perform
    exactly one prefix/_Inc transition.  Absence of a user copy/destructor
    closes observable temporary-copy effects in the discarded postfix form.
    """
    witness = proof["semantic_witness"]
    require(params["identifier"] == witness["iterator_identifier"],
            f"{context}: increment identifier differs from its witness")
    source_root = Path(root).resolve(strict=True)
    alias_spec = witness["source_alias_header"]
    alias_path, alias_data = _read_pinned_semantic_source(
        source_root, alias_spec, context + " source alias header")
    require(alias_spec["source_sha256"]
            == witness["source_include_chain"][0]["including_sha256"],
            f"{context}: alias header and include-chain pins differ")
    include_details = [_require_unique_quoted_include_edge(
        source_root, unit_source, unit_data, alias_path,
        alias_spec["unit_include_range_pin"], context + " unit-to-alias")]

    last_path = alias_path
    last_data = alias_data
    for index, edge in enumerate(witness["source_include_chain"]):
        edge_context = f"{context} source include edge[{index}]"
        including_spec = {
            "path": edge["including_path"],
            "source_sha256": edge["including_sha256"],
        }
        included_spec = {
            "path": edge["included_path"],
            "source_sha256": edge["included_sha256"],
        }
        including_path, including_data = _read_pinned_semantic_source(
            source_root, including_spec, edge_context + " owner")
        included_path, included_data = _read_pinned_semantic_source(
            source_root, included_spec, edge_context + " target")
        include_details.append(_require_unique_quoted_include_edge(
            source_root, edge["including_path"], including_data,
            included_path, edge["include_range_pin"], edge_context))
        last_path, last_data = included_path, included_data

    alias_tokens = _semantic_significant_tokens(alias_data)
    argument_tokens = []
    for index, argument in enumerate(witness["source_alias_arguments"]):
        if index:
            argument_tokens.append(",")
        argument_tokens.extend(
            item[0] for item in _semantic_significant_tokens(
                render_source_overlay_cpp_type(argument).encode("ascii"))
        )
    alias_wanted = [
        "typedef", witness["map_template"], "<", *argument_tokens, ">",
        witness["source_alias"], ";",
    ]
    alias_matches = []
    for index in range(len(alias_tokens) - len(alias_wanted) + 1):
        if [item[0] for item in
                alias_tokens[index:index + len(alias_wanted)]] == alias_wanted:
            alias_matches.append((
                alias_tokens[index][1],
                alias_tokens[index + len(alias_wanted) - 1][2],
            ))
    require(len(alias_matches) == 1,
            f"{context}: iterator source alias is absent or ambiguous")
    alias_detail = _pinned_source_line(
        alias_data, alias_matches[0], alias_spec["alias_range_pin"],
        context + " source alias")

    target_tokens = _semantic_significant_tokens(target_source)
    declaration_wanted = [
        "for", "(", witness["source_alias"], "::",
        witness["iterator_member"], witness["iterator_identifier"], "=",
    ]
    declarations = []
    for index in range(len(target_tokens) - len(declaration_wanted) + 1):
        if [item[0] for item in target_tokens[
                index:index + len(declaration_wanted)]] == declaration_wanted:
            declarations.append(index)
    require(len(declarations) == 1,
            f"{context}: iterator loop declaration is absent or ambiguous")
    declaration_index = declarations[0]
    declaration_identifier_index = (
        declaration_index + declaration_wanted.index(
            witness["iterator_identifier"])
    )
    opening = next(
        (index for index in range(declaration_index, len(target_tokens))
         if target_tokens[index][0] == "{"), None)
    require(opening is not None,
            f"{context}: iterator loop body is missing")
    depth = 1
    closing = None
    for index in range(opening + 1, len(target_tokens)):
        if target_tokens[index][0] == "{":
            depth += 1
        elif target_tokens[index][0] == "}":
            depth -= 1
            if depth == 0:
                closing = index
                break
    require(closing is not None,
            f"{context}: iterator loop body is unbalanced")
    uses = [
        index for index, item in enumerate(target_tokens)
        if item[0] == witness["iterator_identifier"]
    ]
    require(len(uses) >= 4
            and all(declaration_index <= index <= closing for index in uses),
            f"{context}: iterator is shadowed or escapes its declared loop")
    increment_input = render_discarded_postfix_increment_input(params)
    increment_seats = [
        index for index in range(len(target_source))
        if target_source.startswith(increment_input, index)
    ]
    require(len(increment_seats) == 1,
            f"{context}: discarded increment seat is absent or ambiguous")
    postfix_uses = [
        index for index in uses
        if index + 1 < len(target_tokens)
        and target_tokens[index + 1][0] == "++"
    ]
    require(
        len(postfix_uses) == 1
        and opening < postfix_uses[0] < closing
        and target_tokens[postfix_uses[0]][1]
        == increment_seats[0] + len(
            params["declaration_indent"].encode("ascii")),
        f"{context}: discarded increment is not the bound loop iterator",
    )
    for index in uses:
        if index in {declaration_identifier_index, postfix_uses[0]}:
            continue
        before = target_tokens[index - 1][0] if index else None
        after = (target_tokens[index + 1][0]
                 if index + 1 < len(target_tokens) else None)
        require(
            (before == "*" and after == ")")
            or after in {"!=", "==", "->"}
            or before in {"!=", "=="},
            f"{context}: iterator has an unbound use or shadow declaration",
        )
    declaration_detail = _pinned_source_line(
        target_source,
        (target_tokens[declaration_index][1],
         target_tokens[declaration_index + len(declaration_wanted) - 1][2]),
        witness["loop_declaration_range_pin"],
        context + " iterator loop declaration")

    map_spec = witness["map_header"]
    tree_spec = witness["tree_header"]
    iterator_spec = witness["iterator_header"]
    utility_spec = witness["utility_header"]
    memory_spec = witness["memory_header"]
    xmemory_spec = witness["xmemory_header"]
    require(compiler_root is not None,
            f"{context}: compiler root is unavailable")
    _, map_data = _read_pinned_toolchain_semantic_source(
        Path(compiler_root), sealed_include_trees, map_spec,
        context + " map header")
    _, tree_data = _read_pinned_toolchain_semantic_source(
        Path(compiler_root), sealed_include_trees, tree_spec,
        context + " tree header")
    _, iterator_data = _read_pinned_toolchain_semantic_source(
        Path(compiler_root), sealed_include_trees, iterator_spec,
        context + " iterator header")
    _, utility_data = _read_pinned_toolchain_semantic_source(
        Path(compiler_root), sealed_include_trees, utility_spec,
        context + " utility header")
    _, memory_data = _read_pinned_toolchain_semantic_source(
        Path(compiler_root), sealed_include_trees, memory_spec,
        context + " memory header")
    _, xmemory_data = _read_pinned_toolchain_semantic_source(
        Path(compiler_root), sealed_include_trees, xmemory_spec,
        context + " xmemory header")
    repository_map_include = _require_unique_angle_include(
        last_data, map_spec["path"].casefold(),
        map_spec["repository_include_range_pin"],
        context + " repository-to-map")
    map_tree_include = _require_unique_angle_include(
        map_data, tree_spec["path"].casefold(),
        map_spec["tree_include_range_pin"], context + " map-to-tree")
    tree_iterator_include = _require_unique_angle_include(
        tree_data, iterator_spec["path"].casefold(),
        tree_spec["iterator_include_range_pin"],
        context + " tree-to-iterator")
    tree_memory_include = _require_unique_angle_include(
        tree_data, memory_spec["path"].casefold(),
        tree_spec["memory_include_range_pin"],
        context + " tree-to-memory")
    iterator_utility_include = _require_unique_angle_include(
        iterator_data, utility_spec["path"].casefold(),
        iterator_spec["utility_include_range_pin"],
        context + " iterator-to-utility")
    memory_xmemory_include = _require_unique_angle_include(
        memory_data, xmemory_spec["path"].casefold(),
        memory_spec["xmemory_include_range_pin"],
        context + " memory-to-xmemory")

    map_tokens = _semantic_significant_tokens(map_data)
    _, map_open, map_close = _unique_class_body(
        map_tokens, witness["map_template"], context + " map template")
    implementation_range = _unique_class_level_token_range(
        map_tokens, map_open, map_close,
        ["typedef", witness["tree_template"], "<", "_K", ",",
         "value_type", ",", "_Kfn", ",", "_Pr", ",", "_A", ">",
         "_Imp", ";"],
        context + " map implementation alias")
    iterator_range = _unique_class_level_token_range(
        map_tokens, map_open, map_close,
        ["typedef", "_Imp", "::", witness["iterator_member"],
         witness["iterator_member"], ";"],
        context + " map iterator alias")
    map_details = [
        _pinned_source_line(
            map_data, implementation_range,
            map_spec["implementation_alias_range_pin"],
            context + " map implementation alias"),
        _pinned_source_line(
            map_data, iterator_range, map_spec["iterator_alias_range_pin"],
            context + " map iterator alias"),
    ]

    tree_tokens = _semantic_significant_tokens(tree_data)
    _, tree_open, tree_close = _unique_class_body(
        tree_tokens, witness["tree_template"], context + " tree template")
    node_pointer_range = _unique_class_level_token_range(
        tree_tokens, tree_open, tree_close,
        ["typedef", "_POINTER_X", "(", "_Node", ",", "_A", ")",
         witness["node_pointer_type"], ";"],
        context + " node pointer alias")
    node_pointer_detail = _pinned_source_line(
        tree_data, node_pointer_range,
        tree_spec["node_pointer_alias_range_pin"],
        context + " node pointer alias")
    iterator_index, iterator_open, iterator_close = _unique_nested_class_body(
        tree_tokens, tree_open, tree_close, witness["iterator_member"],
        context + " tree iterator")
    expected_inheritance = [
        "class", witness["iterator_member"], ":", "public",
        witness["iterator_base"], "<", "_TYPE", ",",
        "difference_type", ">", "{",
    ]
    require(
        [item[0] for item in tree_tokens[
            iterator_index:iterator_open + 1]] == expected_inheritance,
        f"{context}: iterator inheritance differs",
    )
    iterator_physical_range = _physical_source_range_for_tokens(
        tree_data, tree_tokens, iterator_index, iterator_close,
        context + " tree iterator")
    iterator_class_detail = require_source_overlay_range_pin(
        tree_data[iterator_physical_range[0]:iterator_physical_range[1]],
        tree_spec["iterator_class_range_pin"],
        context + " iterator class range",
    )
    prefix_range = _unique_class_level_token_range(
        tree_tokens, iterator_open, iterator_close,
        [witness["iterator_member"], "&", "operator", "++", "(", ")",
         "{", witness["increment_helper"], "(", ")", ";", "return",
         "(", "*", "this", ")", ";", "}"],
        context + " prefix increment")
    postfix_range = _unique_class_level_token_range(
        tree_tokens, iterator_open, iterator_close,
        [witness["iterator_member"], "operator", "++", "(", "int", ")",
         "{", witness["iterator_member"], "_Tmp", "=", "*", "this", ";",
         "++", "*", "this", ";", "return", "(", "_Tmp", ")", ";",
         "}"],
        context + " postfix increment")
    require(prefix_range[0] < postfix_range[0],
            f"{context}: iterator increment overload order differs")
    line_start = tree_data.rfind(b"\n", 0, prefix_range[0]) + 1
    newline = tree_data.find(b"\n", postfix_range[1])
    line_end = len(tree_data) if newline < 0 else newline + 1
    increment_detail = require_source_overlay_range_pin(
        tree_data[line_start:line_end], tree_spec["increment_range_pin"],
        context + " increment overload range")

    class_scope = _direct_class_scope_tokens(
        tree_tokens, iterator_open, iterator_close)
    constructor_parameters = []
    for index in range(len(class_scope) - 1):
        if class_scope[index:index + 2] != [
                witness["iterator_member"], "("]:
            continue
        closing_parenthesis = next(
            (cursor for cursor in range(index + 2, len(class_scope))
             if class_scope[cursor] in {")", "{", ";"}), None)
        require(closing_parenthesis is not None
                and class_scope[closing_parenthesis] == ")",
                f"{context}: iterator constructor declaration is malformed")
        constructor_parameters.append(
            class_scope[index + 2:closing_parenthesis])
    state_declaration = [
        witness["node_pointer_type"], witness["node_pointer_member"], ";",
    ]
    state_matches = sum(
        class_scope[index:index + len(state_declaration)]
        == state_declaration
        for index in range(len(class_scope) - len(state_declaration) + 1)
    )
    require("~" not in class_scope
            and not any(
                class_scope[index:index + 2] == ["operator", "="]
                for index in range(len(class_scope) - 1)
            )
            and constructor_parameters == [
                [], [witness["node_pointer_type"], "_P"]],
            f"{context}: iterator temporary has a user-defined copy, "
            "assignment, or destructor effect")
    require(state_matches == 1 and class_scope.count(";") == 1,
            f"{context}: iterator has state beyond its sole node pointer")

    utility_tokens = _semantic_significant_tokens(utility_data)
    category_index, category_open, category_close = _unique_class_body(
        utility_tokens, witness["iterator_category_base"],
        context + " iterator category base")
    category_prefix = [
        "template", "<", "class", "_C", ",", "class", "_TYPE", ",",
        "class", "_D", ">", "struct",
        witness["iterator_category_base"], "{",
    ]
    category_prefix_start = category_index - category_prefix.index("struct")
    require(category_prefix_start >= 0
            and [item[0] for item in utility_tokens[
                category_prefix_start:category_open + 1]] == category_prefix
            and [item[0] for item in utility_tokens[
                category_open + 1:category_close]] == [
                    "typedef", "_C", "iterator_category", ";",
                    "typedef", "_TYPE", "value_type", ";",
                    "typedef", "_D", "distance_type", ";",
                ],
            f"{context}: iterator category base carries nontrivial state")
    category_physical = _physical_source_range_for_tokens(
        utility_data, utility_tokens, category_prefix_start, category_close,
        context + " iterator category base")
    category_detail = require_source_overlay_range_pin(
        utility_data[category_physical[0]:category_physical[1]],
        utility_spec["category_base_range_pin"],
        context + " iterator category base range")

    bidit_index, bidit_open, bidit_close = _unique_class_body(
        utility_tokens, witness["iterator_base"],
        context + " bidirectional iterator base")
    bidit_prefix = [
        "template", "<", "class", "_TYPE", ",", "class", "_D", ">",
        "struct", witness["iterator_base"], ":", "public",
        witness["iterator_category_base"], "<",
        witness["iterator_category_tag"], ",", "_TYPE", ",", "_D", ">",
        "{",
    ]
    bidit_prefix_start = bidit_index - bidit_prefix.index("struct")
    require(bidit_prefix_start >= 0
            and [item[0] for item in utility_tokens[
                bidit_prefix_start:bidit_open + 1]] == bidit_prefix
            and bidit_open + 1 == bidit_close,
            f"{context}: bidirectional iterator base is not empty")
    bidit_physical = _physical_source_range_for_tokens(
        utility_data, utility_tokens, bidit_prefix_start, bidit_close,
        context + " bidirectional iterator base")
    bidit_detail = require_source_overlay_range_pin(
        utility_data[bidit_physical[0]:bidit_physical[1]],
        utility_spec["bidirectional_base_range_pin"],
        context + " bidirectional iterator base range")

    xmemory_tokens = _semantic_significant_tokens(xmemory_data)
    pointer_macro_wanted = [
        "#", "define", "_POINTER_X", "(", "T", ",", "A", ")",
        "T", "_FARQ", "*",
    ]
    pointer_macro_matches = []
    for index in range(
            len(xmemory_tokens) - len(pointer_macro_wanted) + 1):
        if [item[0] for item in xmemory_tokens[
                index:index + len(pointer_macro_wanted)]] \
                == pointer_macro_wanted:
            pointer_macro_matches.append((
                xmemory_tokens[index][1],
                xmemory_tokens[index + len(pointer_macro_wanted) - 1][2],
            ))
    require(len(pointer_macro_matches) == 1,
            f"{context}: node pointer macro is absent or ambiguous")
    pointer_macro_detail = _pinned_source_line(
        xmemory_data, pointer_macro_matches[0],
        xmemory_spec["pointer_macro_range_pin"],
        context + " node pointer macro")
    return {
        "discarded_increment_identifier": witness["iterator_identifier"],
        "discarded_increment_source_alias": witness["source_alias"],
        "discarded_increment_include_edges": len(include_details) + 6,
        "discarded_increment_iterator_uses": len(uses),
        "discarded_increment_witness_sha256": sha256_bytes(
            canonical_json_bytes({
                "includes": include_details,
                "repository_map_include": repository_map_include,
                "map_tree_include": map_tree_include,
                "tree_iterator_include": tree_iterator_include,
                "tree_memory_include": tree_memory_include,
                "iterator_utility_include": iterator_utility_include,
                "memory_xmemory_include": memory_xmemory_include,
                "alias": alias_detail,
                "declaration": declaration_detail,
                "map": map_details,
                "increment": increment_detail,
                "iterator_class": iterator_class_detail,
                "node_pointer_alias": node_pointer_detail,
                "node_pointer_macro": pointer_macro_detail,
                "iterator_category_base": category_detail,
                "bidirectional_base": bidit_detail,
            })
        ),
    }


CAPTURED_POINTER_TAIL_RETURN_ROLES = frozenset({
    "capture_declaration", "capture_assignment", "read_reseat",
    "return_to_goto", "tail_return",
})


def render_captured_pointer_tail_return_input(params: dict) -> bytes:
    """Reconstruct one seed-side fragment of a captured tail return."""
    role = params["role"]
    if role in {"capture_declaration", "capture_assignment", "tail_return"}:
        return b""
    if role == "read_reseat":
        return params["source_identifier"].encode("ascii")
    require(role == "return_to_goto", "captured tail-return role differs")
    return f'return {params["source_identifier"]};'.encode("ascii")


def render_captured_pointer_tail_return_output(params: dict) -> bytes:
    """Render one donor-side fragment without accepting arbitrary text."""
    role = params["role"]
    if role == "capture_declaration":
        return (
            params["indentation"]
            + render_source_overlay_cpp_type(params["pointer_type"])
            + " " + params["capture_identifier"] + ";\n"
        ).encode("ascii")
    if role == "capture_assignment":
        return (
            params["indentation"] + params["capture_identifier"] + " = "
            + params["source_identifier"] + ";\n"
        ).encode("ascii")
    if role == "read_reseat":
        return params["capture_identifier"].encode("ascii")
    if role == "return_to_goto":
        return f'goto {params["label_identifier"]};'.encode("ascii")
    require(role == "tail_return", "captured tail-return role differs")
    return (
        "\n" + params["label_identifier"] + ":\n"
        + params["indentation"] + "return "
        + params["capture_identifier"] + ";\n"
    ).encode("ascii")


CONSTRUCTOR_ALLOCATION_LIFT_ROLES = frozenset({
    "class_declaration", "definition_header", "constructor_body", "call_site",
})


def _bind_constructor_allocation_lift_role(
    operation: dict, clean: bytes, logical_path: str, proof: dict,
    roles: dict, seen: set, operation_index: int | None, context: str,
) -> None:
    """Bind one operation to exactly one role of an allocation-lift proof.

    The role is DERIVED from the typed generator, never declared: a
    constructor member signature is the class declaration or the definition
    header according to its form, and an allocation lift is the call site or
    the constructor body according to its role field.  The mapping is a
    bijection, so a manifest cannot label an operation as something it is not.
    """
    operation_id = operation["id"]
    generators = list(_source_overlay_generators(operation["generator"]))
    require(len(generators) == 1,
            f"{context}: allocation-lift operation {operation_id} must carry "
            "exactly one generator")
    generator = generators[0]
    params = generator["params"]
    if generator["kind"] == "member_signature_v1":
        require(params["kind"] == "constructor",
                f"{context}: allocation-lift operation {operation_id} must "
                "emit a constructor signature")
        role = ("class_declaration"
                if params["form"] == "in_class_declaration"
                else "definition_header")
    elif generator["kind"] == "constructor_allocation_lift_v1":
        role = params["role"]
    else:
        raise ByteIdentityError(
            f"{context}: allocation-lift operation {operation_id} uses an "
            f"unbound generator: {generator['kind']}"
        )
    require(role not in roles and operation_id not in seen,
            f"{context}: allocation-lift role {role} is bound twice")
    require((role == "class_declaration") == (operation_index is None),
            f"{context}: allocation-lift role {role} is rendered into the "
            "wrong file")
    expected_action = "replace" if role == "call_site" else "insert"
    require(operation["action"] == expected_action,
            f"{context}: allocation-lift role {role} action differs")
    start = resolve_source_overlay_anchor(
        clean, operation["start_anchor"], context + f" allocation-lift {role}",
        logical_path=logical_path,
    )
    end = start
    if expected_action == "replace":
        end = resolve_source_overlay_anchor(
            clean, operation["end_anchor"],
            context + f" allocation-lift {role} end",
            logical_path=logical_path,
        )
    roles[role] = {
        "operation": operation,
        "operation_id": operation_id,
        "params": params,
        "start": start,
        "end": end,
        "index": operation_index,
    }
    seen.add(operation_id)


def constructor_allocation_lift_declared_locals(
    params: dict, rendered: bytes,
) -> set[str]:
    """Which of the closed form's two locals this rendering declares.

    Derived from the rendered bytes, not asserted: a local is declared when
    the text contains its typed initialising declaration.  The input renderer
    declares the caller's buffer and the iterator; the call-site renderer
    declares only the iterator.
    """
    declared = set()
    for type_key, identifier_key in (
        ("caller_result_type", "caller_result_identifier"),
        ("iterator_type", "iterator_identifier"),
    ):
        needle = (
            render_source_overlay_cpp_type(params[type_key]) + " "
            + params[identifier_key] + " = "
        ).encode("ascii")
        if needle in rendered:
            declared.add(params[identifier_key])
    return declared


def require_constructor_allocation_lift_role_set(
    roles: dict, proof: dict, root, unit_source: str, clean: bytes,
    target_range: bytes, target_start: int, target_end: int,
    header_clean: bytes, local_set_delta: dict | None, context: str,
) -> dict:
    """Close the four bound roles of one constructor allocation lift."""
    require(set(roles) == CONSTRUCTOR_ALLOCATION_LIFT_ROLES,
            f"{context}: allocation-lift role set is incomplete")
    witness = proof["semantic_witness"]
    signature = proof["constructor_signature"]

    # Both signature seats must render the SAME closed identity, and that
    # identity is the proof's, not either generator's.
    for role in ("class_declaration", "definition_header"):
        params = roles[role]["params"]
        require(params["class_identifier"] == signature["class_identifier"]
                and params["member_identifier"]
                == signature["class_identifier"]
                and params["parameters"] == signature["parameters"],
                f"{context}: allocation-lift {role} signature differs from "
                "the proof's constructor signature")
    require("specifiers" not in roles["class_declaration"]["params"],
            f"{context}: an in-class declaration carries no specifiers")
    require(roles["definition_header"]["params"].get("specifiers")
            == ["inline"],
            f"{context}: the out-of-class definition header must be inline, "
            "or the donor grows a constructor COMDAT the seed does not have")

    call_site = roles["call_site"]["params"]
    body = roles["constructor_body"]["params"]
    require({**call_site, "role": None} == {**body, "role": None},
            f"{context}: the allocation-lift call site and constructor body "
            "are not two renderings of one parameter set")

    require(len(signature["parameters"]) == 1
            and signature["parameters"][0]["identifier"]
            == call_site["parameter_identifier"]
            and signature["parameters"][0]["type"]
            == witness["buffer_member_type"],
            f"{context}: the lifted constructor's parameter is not the "
            "pinned buffer member type bound to the substituted identifier")

    # The declaration must seat inside the pinned class's own body.
    header_tokens = _semantic_significant_tokens(header_clean)
    _, class_open, class_close = _unique_class_body(
        header_tokens, witness["entry_class"], context + " header")
    seat = roles["class_declaration"]["start"]
    require(header_tokens[class_open][2] <= seat
            <= header_tokens[class_close][1],
            f"{context}: the allocation-lift declaration seats outside its "
            "class body")

    definition = roles["definition_header"]
    constructor_body = roles["constructor_body"]
    require(definition["start"] == constructor_body["start"],
            f"{context}: the allocation-lift definition header and body do "
            "not share one seat")
    require(definition["index"] < constructor_body["index"],
            f"{context}: the allocation-lift body is rendered before its "
            "definition header")
    # An insert seats text BEFORE the byte at its offset, so a seat at
    # target_start lands entirely above the target window's first byte and
    # cannot alter one byte of it.  `<=` is therefore exactly "outside the
    # target"; anything strictly greater would be inside it.
    require(definition["start"] <= target_start,
            f"{context}: the allocation-lift definition seats inside its "
            "target")

    start = roles["call_site"]["start"]
    end = roles["call_site"]["end"]
    require(target_start <= start < end <= target_end,
            f"{context}: refactor operation leaves its target")
    expected_input = render_constructor_allocation_lift_input(call_site)
    removed = clean[start:end]
    require(removed == expected_input,
            f"{context}: refactor input statement differs")
    pin = roles["call_site"]["operation"]["baseline_input_range"]
    require(sha256_bytes(removed) == pin["baseline_sha256"]
            and len(removed) == pin["baseline_size"],
            f"{context}: refactor input pin differs")

    if local_set_delta is not None:
        # D1 obligation (7).  This is the binding that stops the manifest
        # naming an arbitrary debug record: the object-level removal set must
        # be EXACTLY the locals this refactor's input renderer declares and
        # its output renderer does not.  It is discharged here because this is
        # the one place that holds both the object-level pin and the typed
        # generator parameters.
        removed_locals = (
            constructor_allocation_lift_declared_locals(
                call_site, expected_input)
            - constructor_allocation_lift_declared_locals(
                call_site,
                render_constructor_allocation_lift_call_site(call_site))
        )
        require(
            {item["identifier"]
             for item in local_set_delta["removed_records"]}
            == removed_locals,
            f"{context}: the pinned local-set delta is not the set of locals "
            "this refactor removes from its target",
        )
    detail = require_constructor_allocation_lift_semantic_identity(
        root, unit_source, clean, target_range, expected_input, proof,
        call_site, context + " allocation-lift witness",
    )
    return {
        **detail,
        "allocation_lift_declaration_seat": seat,
        "allocation_lift_definition_seat": definition["start"],
    }


def require_target_source_refactor_recipe_policy(
    recipe: dict, function: dict, root, unit_source: str, context: str,
    canonical_operations: list[dict] | None = None,
    overlaid_paths: set[str] | None = None,
    *, proof_key: str = "target_source_refactor", compiler_root=None,
    sealed_include_trees: list[dict] | None = None,
) -> dict:
    """Confine manifest-declared source permutations to one source owner.

    Each replacement is rendered from one closed typed form, and its inverse
    reconstructs the checked-in statement byte-for-byte.  Everything outside
    the pinned source-owner window remains limited to fresh, non-emitting
    compiler-state entropy.
    """
    require(proof_key in {
                "target_source_refactor",
                "instruction_donor_source_refactor",
            }, f"{context}: source-refactor proof role differs")
    proof = function[proof_key]
    if proof["kind"] in {
        "fixed_array_fill_loop_v1",
        "fixed_array_shuffle_pointer_countdown_v1",
        "inclusive_extent_assignment_v1",
        "discarded_postfix_increment_v1",
    }:
        require(proof["source_owner_mangled"] == function["mangled"],
                f"{context}: source permutation owner must be the mosaic "
                "target")
    if proof["kind"] == "fixed_array_shuffle_pointer_countdown_v1":
        require(
            function.get("splice_class") in {
                "retail_exact_instruction_mosaic",
                RETAIL_EXACT_SOURCE_EQUAL_BODY_CLASS,
            }
            and isinstance(function.get("source_fpo_identity"), dict)
            and "ordinary_fpo_identity" not in function,
            f"{context}: fixed-array shuffle is restricted to its isolated "
            "source FPO body composer",
        )
        require(isinstance(overlaid_paths, set),
                f"{context}: fixed-array shuffle overlay census is missing")
        witness_paths = {
            proof["semantic_witness"][name]["path"]
            for name in ("owner_header", "base_header", "types_header")
        }
        require(not witness_paths.intersection(overlaid_paths),
                f"{context}: fixed-array shuffle witness header has an "
                "effective source overlay")
    if proof["kind"] == "inclusive_extent_assignment_v1":
        require(isinstance(overlaid_paths, set),
                f"{context}: inclusive-extent overlay census is missing")
        witness_paths = {
            proof["semantic_witness"][name]["path"]
            for name in (
                "source_owner_header", "source_accessor_header",
                "extent_header",
            )
        }
        require(not witness_paths.intersection(overlaid_paths),
                f"{context}: inclusive-extent semantic witness header has "
                "an effective source overlay")
    if proof["kind"] == "constructor_allocation_lift_v1":
        require(function.get("splice_class")
                == "retail_exact_reloc_divergent",
                f"{context}: a constructor allocation lift belongs to the "
                "retail-exact divergent class")
        require(isinstance(overlaid_paths, set),
                f"{context}: allocation-lift overlay census is missing")
        require(
            proof["semantic_witness"]["owner_header"]["path"]
            not in overlaid_paths,
            f"{context}: allocation-lift semantic witness header has an "
            "effective source overlay",
        )
    if proof["kind"] == "discarded_postfix_increment_v1":
        require(isinstance(overlaid_paths, set),
                f"{context}: discarded-increment overlay census is missing")
        witness = proof["semantic_witness"]
        witness_paths = {witness["source_alias_header"]["path"]}
        for edge in witness["source_include_chain"]:
            witness_paths.update({
                edge["including_path"], edge["included_path"],
            })
        require(not witness_paths.intersection(overlaid_paths),
                f"{context}: discarded-increment semantic witness header "
                "has an effective source overlay")
    validated = validate_donor_source_overlay_recipe(
        recipe, root, seed_outputs_touched=False,
        canonical_operations=canonical_operations,
    )
    allocation_lift = proof["kind"] == "constructor_allocation_lift_v1"
    header_rendering = None
    header_clean = b""
    if allocation_lift:
        # The lift is the one refactor whose text cannot live in a single
        # file: the constructor it introduces must be DECLARED on the class,
        # which lives in a header.  The second rendering is therefore
        # admitted, and immediately re-closed: it must be exactly the header
        # the semantic witness pins, it may carry exactly ONE operation, and
        # that operation must be a bound role of this proof.  No entropy, no
        # whole-file append, no second op.
        require(len(validated["renderings"]) == 2,
                f"{context}: an allocation-lift donor renders its own TU and "
                "the class's owning header, and nothing else")
        unit_renderings = [item for item in validated["renderings"]
                           if item["path"] == unit_source]
        other_renderings = [item for item in validated["renderings"]
                            if item["path"] != unit_source]
        require(len(unit_renderings) == 1 and len(other_renderings) == 1,
                f"{context}: an allocation-lift donor must render its own TU")
        header_rendering = other_renderings[0]
        require(
            header_rendering["path"]
            == proof["semantic_witness"]["owner_header"]["path"],
            f"{context}: allocation-lift header rendering is not the pinned "
            "owner header",
        )
        require(len(header_rendering["operations"]) == 1,
                f"{context}: the allocation-lift header rendering may carry "
                "exactly one bound operation")
        header_clean = (Path(root) / header_rendering["path"]).read_bytes()
    else:
        require(len(validated["renderings"]) == 1
                and validated["renderings"][0]["path"] == unit_source,
                f"{context}: refactor donor may render only its own TU")
    source = Path(root) / unit_source
    clean = source.read_bytes()
    start_marker = proof["start_marker"].encode("ascii")
    target_range = select_source_permutation_window(
        clean, proof, context + " clean source owner")
    target_start = clean.index(start_marker)
    target_end = target_start + len(target_range)

    clean_tokens = {token for token, _, _ in source_overlay_tokens(clean)}
    target_tokens = {
        token for token, _, _ in
        source_overlay_tokens(clean[target_start:target_end])
    }
    introduced_identifiers = set()
    refactor_identifiers = set()
    expected = set(proof["operation_ids"])
    seen = set()
    tail_fragments = {}
    semantic_detail = {}
    canonical_by_id = {
        operation["id"]: operation
        for operation in (canonical_operations or [])
    }
    require(len(canonical_by_id) == len(canonical_operations or []),
            f"{context}: canonical source operations are duplicated")
    canonical_seen = set()
    lift_roles: dict[str, dict] = {}
    rendering = unit_renderings[0] if allocation_lift else (
        validated["renderings"][0])
    if allocation_lift:
        header_operation = header_rendering["operations"][0]
        require(header_operation["id"] in expected,
                f"{context}: the allocation-lift header operation is not a "
                "bound role of this proof")
        _bind_constructor_allocation_lift_role(
            header_operation, header_clean, header_rendering["path"],
            proof, lift_roles, seen, None, context,
        )
    for operation_index, operation in enumerate(rendering["operations"]):
        operation_id = operation["id"]
        generators = list(_source_overlay_generators(operation["generator"]))
        require(generators, f"{context}: empty generator tree")
        if operation_id in expected:
            if allocation_lift:
                _bind_constructor_allocation_lift_role(
                    operation, clean, unit_source, proof, lift_roles, seen,
                    operation_index, context,
                )
                continue
            if proof["kind"] == "captured_pointer_tail_return_v1":
                require(len(generators) == 1
                        and generators[0]["kind"]
                        == "captured_pointer_tail_return_fragment_v1"
                        and operation_id not in seen,
                        f"{context}: tail-return operation {operation_id} "
                        "differs")
                params = generators[0]["params"]
                role = params["role"]
                expected_action = (
                    "replace" if role in {"read_reseat", "return_to_goto"}
                    else "insert"
                )
                require(operation["action"] == expected_action
                        and role not in tail_fragments,
                        f"{context}: tail-return role {role} differs")
                start = resolve_source_overlay_anchor(
                    clean, operation["start_anchor"],
                    context + f" tail-return {role}",
                    logical_path=unit_source,
                )
                require(target_start <= start <= target_end,
                        f"{context}: tail-return operation leaves its target")
                end = start
                expected_input = (
                    render_captured_pointer_tail_return_input(params)
                )
                if expected_action == "replace":
                    end = resolve_source_overlay_anchor(
                        clean, operation["end_anchor"],
                        context + f" tail-return {role} end",
                        logical_path=unit_source,
                    )
                    require(start < end <= target_end
                            and clean[start:end] == expected_input,
                            f"{context}: tail-return input {role} differs")
                    pin = operation["baseline_input_range"]
                    require(sha256_bytes(expected_input)
                            == pin["baseline_sha256"]
                            and len(expected_input) == pin["baseline_size"],
                            f"{context}: tail-return input pin {role} differs")
                else:
                    require(expected_input == b"",
                            f"{context}: inserted tail-return input differs")
                tail_fragments[role] = {
                    "operation_id": operation_id,
                    "start": start,
                    "end": end,
                    "params": params,
                }
                seen.add(operation_id)
                continue
            expected_kind = {
                "single_evaluation_bindings_v1":
                    "single_evaluation_binding_source_permutation_v1",
                "for_initializer_declaration_reseat_v1":
                    "for_initializer_declaration_reseat_v1",
                "fixed_array_fill_loop_v1":
                    "fixed_array_fill_loop_v1",
                "fixed_array_shuffle_pointer_countdown_v1":
                    "fixed_array_shuffle_pointer_countdown_v1",
                "inclusive_extent_assignment_v1":
                    "inclusive_extent_assignment_v1",
                "discarded_postfix_increment_v1":
                    "discarded_postfix_increment_v1",
            }[proof["kind"]]
            require(operation["action"] == "replace"
                    and len(generators) == 1
                    and generators[0]["kind"] == expected_kind
                    and operation_id not in seen,
                    f"{context}: refactor operation {operation_id} differs")
            params = generators[0]["params"]
            identifier = (
                params["pointer_identifier"]
                if proof["kind"]
                == "fixed_array_shuffle_pointer_countdown_v1"
                else params["index_identifier"]
                if proof["kind"] == "fixed_array_fill_loop_v1"
                else params["identifier"]
            )
            if proof["kind"] == "single_evaluation_bindings_v1":
                require(identifier not in target_tokens
                        and identifier not in refactor_identifiers,
                        f"{context}: refactor local is not fresh: "
                        f"{identifier}")
                expected_input = render_single_evaluation_binding_input(params)
            elif proof["kind"] == "fixed_array_fill_loop_v1":
                require(identifier not in target_tokens
                        and identifier not in refactor_identifiers,
                        f"{context}: array-fill index is not fresh: "
                        f"{identifier}")
                require(params["array_identifier"] in target_tokens,
                        f"{context}: array-fill target is outside its source "
                        "owner")
                expected_input = render_fixed_array_fill_loop_input(params)
                semantic_detail = require_fixed_array_declaration_identity(
                    root, unit_source, clean, target_range, expected_input,
                    proof, params,
                    context + " fixed-array declaration",
                )
            elif (proof["kind"]
                  == "fixed_array_shuffle_pointer_countdown_v1"):
                require(params["array_identifier"] in target_tokens,
                        f"{context}: array-shuffle target is outside its "
                        "source owner")
                expected_input = (
                    render_fixed_array_shuffle_countdown_input(params)
                )
                semantic_detail = (
                    require_fixed_array_shuffle_semantic_identity(
                        root, unit_source, clean, target_range,
                        expected_input, proof, params,
                        context + " fixed-array shuffle witness",
                    )
                )
            elif proof["kind"] == "inclusive_extent_assignment_v1":
                require(identifier not in refactor_identifiers,
                        f"{context}: inclusive-extent local is repeated: "
                        f"{identifier}")
                expected_input = render_inclusive_extent_assignment_input(
                    params)
                semantic_detail = require_inclusive_extent_semantic_identity(
                    root, unit_source, clean, target_range, proof, params,
                    context + " inclusive-extent witness",
                )
            elif proof["kind"] == "discarded_postfix_increment_v1":
                require(identifier in target_tokens,
                        f"{context}: increment iterator is outside its "
                        "source owner")
                expected_input = render_discarded_postfix_increment_input(
                    params)
                semantic_detail = require_discarded_increment_semantic_identity(
                    root, unit_source, clean, target_range, proof, params,
                    context + " discarded-increment witness",
                    compiler_root=compiler_root,
                    sealed_include_trees=sealed_include_trees or [],
                )
            else:
                require(identifier not in refactor_identifiers,
                        f"{context}: reseated iterator is repeated: "
                        f"{identifier}")
                expected_input = (
                    render_for_initializer_declaration_reseat_input(params)
                )
            start = resolve_source_overlay_anchor(
                clean, operation["start_anchor"], context + " refactor.from",
                logical_path=unit_source,
            )
            end = resolve_source_overlay_anchor(
                clean, operation["end_anchor"], context + " refactor.to",
                logical_path=unit_source,
            )
            require(target_start <= start < end <= target_end,
                    f"{context}: refactor operation leaves its target")
            removed = clean[start:end]
            require(removed == expected_input,
                    f"{context}: refactor input statement differs")
            pin = operation["baseline_input_range"]
            require(sha256_bytes(removed) == pin["baseline_sha256"]
                    and len(removed) == pin["baseline_size"],
                    f"{context}: refactor input pin differs")
            if proof["kind"] == "inclusive_extent_assignment_v1":
                semantic_detail.update(
                    require_identifier_fresh_at_source_seat(
                        target_range, start - target_start, identifier,
                        context + " inclusive-extent local",
                    )
                )
            if proof["kind"] == "for_initializer_declaration_reseat_v1":
                relative_start = start - target_start
                relative_end = end - target_start
                owner_tokens = source_overlay_tokens(target_range)
                openings = [
                    index for index, (token, token_start, token_end)
                    in enumerate(owner_tokens)
                    if token == "{" and relative_start <= token_start
                    and token_end <= relative_end
                ]
                require(len(openings) == 1,
                        f"{context}: reseated for-loop opening differs")
                depth = 0
                loop_end = None
                for token, _, token_end in owner_tokens[openings[0]:]:
                    if token == "{":
                        depth += 1
                    elif token == "}":
                        depth -= 1
                        if depth == 0:
                            loop_end = token_end
                            break
                require(loop_end is not None,
                        f"{context}: reseated for-loop is unbalanced")
                uses = [token_start for token, token_start, _ in owner_tokens
                        if token == identifier]
                require(len(uses) >= 4
                        and all(relative_start <= item < loop_end
                                for item in uses),
                        f"{context}: iterator use escapes its declared loop")
            seen.add(operation_id)
            refactor_identifiers.add(identifier)
            continue

        if operation["id"] in canonical_by_id:
            require(operation == canonical_by_id[operation["id"]]
                    and operation["id"] not in canonical_seen,
                    f"{context}: canonical source operation differs")
            require(operation["action"] in {"insert", "whole_file_append"},
                    f"{context}: canonical source operation is destructive")
            if operation["action"] == "insert":
                seat = resolve_source_overlay_anchor(
                    clean, operation["start_anchor"],
                    context + " canonical source seat",
                    logical_path=unit_source,
                )
                require(seat < target_start or seat >= target_end,
                        f"{context}: canonical source operation overlaps the "
                        "refactor target")
            canonical_seen.add(operation["id"])
            continue

        require(operation["action"] in {"insert", "whole_file_append"},
                f"{context}: unbound destructive donor operation")
        require(all(generator["kind"] in
                    TARGET_REFACTOR_ENTROPY_GENERATOR_KINDS
                    for generator in generators),
                f"{context}: refactor donor uses unsupported entropy")
        for generator in generators:
            if generator["kind"] == "declaration_sequence_v1":
                require(generator["params"].get("shape") in (
                    "forward", "empty_class",
                    "unused_class_void_member_sequence",
                ), f"{context}: refactor donor declaration may emit")
        if operation["action"] == "insert":
            seat = resolve_source_overlay_anchor(
                clean, operation["start_anchor"], context + " entropy seat",
                logical_path=unit_source,
            )
            require(seat < target_start or seat >= target_end,
                    f"{context}: extra entropy overlaps the refactor target")
        for leaf in iter_source_overlay_leaf_generators(
                operation["generator"]):
            roles = source_overlay_expected_identifier_roles(
                leaf["kind"], leaf["params"]
            )
            require(not roles["emitted_identifiers"],
                    f"{context}: donor entropy emits a linked identity")
            for identifier in roles["declared_identifiers"]:
                if "::" in identifier:
                    continue
                require(identifier not in clean_tokens,
                        f"{context}: donor declaration collides with clean "
                        f"source: {identifier}")
                require(identifier not in introduced_identifiers,
                        f"{context}: donor declaration is repeated: "
                        f"{identifier}")
                introduced_identifiers.add(identifier)
    if allocation_lift:
        semantic_detail = require_constructor_allocation_lift_role_set(
            lift_roles, proof, root, unit_source, clean, target_range,
            target_start, target_end, header_clean,
            function.get("local_set_delta"), context,
        )
    if proof["kind"] == "captured_pointer_tail_return_v1":
        require(set(tail_fragments) == CAPTURED_POINTER_TAIL_RETURN_ROLES,
                f"{context}: captured tail-return role set is incomplete")
        ordered_roles = [
            "capture_declaration", "capture_assignment", "read_reseat",
            "return_to_goto", "tail_return",
        ]
        require([tail_fragments[role]["start"] for role in ordered_roles]
                == sorted(tail_fragments[role]["start"]
                          for role in ordered_roles),
                f"{context}: captured tail-return fragments are reordered")
        declaration = tail_fragments["capture_declaration"]["params"]
        assignment = tail_fragments["capture_assignment"]["params"]
        read = tail_fragments["read_reseat"]["params"]
        branch = tail_fragments["return_to_goto"]["params"]
        tail = tail_fragments["tail_return"]["params"]
        capture = declaration["capture_identifier"]
        source = assignment["source_identifier"]
        label = branch["label_identifier"]
        require(
            assignment["capture_identifier"] == capture
            and read["capture_identifier"] == capture
            and tail["capture_identifier"] == capture
            and read["source_identifier"] == source
            and branch["source_identifier"] == source
            and tail["label_identifier"] == label,
            f"{context}: captured tail-return identities diverge",
        )
        require(capture not in target_tokens and label not in target_tokens
                and capture not in clean_tokens,
                f"{context}: captured tail-return identity is not fresh")
        refactor_identifiers.update({capture, label})
    carrier = validated.get("compiler_state_carrier")
    carrier_identifiers = set()
    if carrier is not None:
        require(proof["kind"] == "discarded_postfix_increment_v1",
                f"{context}: compiler-state carrier is outside its closed "
                "source permutation")
        for role in ("header", "seat"):
            prefix = carrier[f"{role}_prefix"]
            width = carrier["width"]
            carrier_identifiers.update(
                f"{prefix}{index:0{width}d}"
                for index in range(carrier[f"{role}_count"])
            )
        require(not carrier_identifiers.intersection(clean_tokens)
                and not carrier_identifiers.intersection(
                    introduced_identifiers),
                f"{context}: compiler-state carrier declaration collides "
                "with its source rendering")
        introduced_identifiers.update(carrier_identifiers)
    require(seen == expected,
            f"{context}: source-permutation set is incomplete")
    require(canonical_seen == set(canonical_by_id),
            f"{context}: donor rendering omits a canonical source operation")
    return {
        "refactor_operation_ids": sorted(seen),
        "refactor_local_identifiers": sorted(refactor_identifiers),
        "entropy_identifier_count": len(introduced_identifiers),
        "compiler_state_carrier_identifier_count": len(carrier_identifiers),
        **semantic_detail,
    }


TARGET_CLOSURE_GENERATOR_KINDS = frozenset({
    "composed_typed_sequence_v1",
    "declaration_sequence_v1",
    "line_reservation_v1",
})


def require_target_closure_recipe_policy(
    recipe: dict, function: dict, root, unit_source: str, context: str,
) -> dict:
    """Confine target-closure donors to non-emitting entropy plus a bound
    removal of a complete seed-retained definition outside the target.

    The general source-overlay grammar intentionally supports much broader
    project reconstruction.  This splice class does not: a future manifest
    cannot smuggle probes, suppliers, archive pulls, constants, or live body
    statements into a retail-exact donor merely because its target bytes match.
    """
    validated = validate_donor_source_overlay_recipe(
        recipe, root, seed_outputs_touched=False
    )
    require(len(validated["renderings"]) == 1
            and validated["renderings"][0]["path"] == unit_source,
            f"{context}: target-closure donor may render only its own TU")
    proof = function["target_source_range"]
    source = Path(root) / unit_source
    clean = source.read_bytes()
    start_marker = proof["start_marker"].encode("ascii")
    end_marker = proof["end_marker"].encode("ascii")
    require(clean.count(start_marker) == clean.count(end_marker) == 1,
            f"{context}: target markers are not unique in clean source")
    target_start = clean.index(start_marker)
    target_end = clean.index(end_marker)
    require(target_start < target_end,
            f"{context}: target markers are reversed in clean source")
    clean_tokens = {
        token for token, _, _ in source_overlay_tokens(clean)
    }
    introduced_identifiers = set()

    raw_bindings = function["destructive_source_bindings"]
    require(isinstance(raw_bindings, list) and raw_bindings,
            f"{context}: destructive source bindings are absent")
    bindings = {}
    for index, item in enumerate(raw_bindings):
        item_context = f"{context}.destructive_source_bindings[{index}]"
        require(isinstance(item, dict), f"{item_context} must be an object")
        exact_audit_keys(item, {
            "path", "operation_id", "retained_function",
            "source_qualified_identifier",
        }, item_context)
        path = source_overlay_relative_path(
            item.get("path"), item_context + ".path"
        )
        operation_id = item.get("operation_id")
        retained = item.get("retained_function")
        qualified = _source_overlay_qualified_identifier(
            item.get("source_qualified_identifier"),
            item_context + ".source_qualified_identifier",
        )
        require(path == unit_source
                and isinstance(operation_id, str)
                and re.fullmatch(r"op_[a-z0-9_]{1,120}", operation_id)
                and retained in function["expected_seed_only_functions"],
                f"{item_context} does not bind a seed-retained definition")
        require(all(part in retained for part in qualified.split("::")),
                f"{item_context} source identity differs from its symbol")
        key = (path, operation_id)
        require(key not in bindings,
                f"{item_context} duplicates a destructive operation")
        bindings[key] = (retained, qualified)

    used = set()
    rendering = validated["renderings"][0]
    for operation in rendering["operations"]:
        generators = list(_source_overlay_generators(operation["generator"]))
        require(generators and all(
            generator["kind"] in TARGET_CLOSURE_GENERATOR_KINDS
            for generator in generators
        ), f"{context}: target-closure recipe uses an emitting or "
           "unsupported generator")
        for generator in generators:
            if generator["kind"] == "declaration_sequence_v1":
                require(generator["params"].get("shape") in (
                    "forward", "unused_class_void_member_sequence",
                ), f"{context}: target-closure declaration shape may emit")
        for leaf in iter_source_overlay_leaf_generators(
                operation["generator"]):
            roles = source_overlay_expected_identifier_roles(
                leaf["kind"], leaf["params"]
            )
            for identifier in roles["declared_identifiers"]:
                if "::" in identifier:
                    continue
                require(identifier not in clean_tokens,
                        f"{context}: target-closure declaration collides "
                        f"with clean source: {identifier}")
                require(identifier not in introduced_identifiers,
                        f"{context}: target-closure declaration is repeated: "
                        f"{identifier}")
                introduced_identifiers.add(identifier)
        if operation["action"] == "insert":
            continue
        require(operation["action"] == "replace",
                f"{context}: target-closure donor permits inserts and one "
                "bound replacement class only")
        key = (rendering["path"], operation["id"])
        require(key in bindings and key not in used,
                f"{context}: destructive operation is not uniquely bound")
        used.add(key)
        require(len(generators) == 1
                and generators[0]["kind"] == "line_reservation_v1",
                f"{context}: destructive replacement must reserve lines only")
        start = resolve_source_overlay_anchor(
            clean, operation["start_anchor"], context + " replacement.from",
            logical_path=unit_source,
        )
        end = resolve_source_overlay_anchor(
            clean, operation["end_anchor"], context + " replacement.to",
            logical_path=unit_source,
        )
        require(start < end
                and (end <= target_start or start >= target_end),
                f"{context}: destructive replacement overlaps the target")
        removed = clean[start:end]
        range_pin = operation["baseline_input_range"]
        require(sha256_bytes(removed) == range_pin["baseline_sha256"]
                and len(removed) == range_pin["baseline_size"],
                f"{context}: destructive range differs from its pin")
        replacement = render_source_overlay_generator(operation["generator"])
        require(set(replacement) <= {9, 10, 13, 32}
                and replacement.count(b"\n") == removed.count(b"\n"),
                f"{context}: destructive replacement is not line-neutral")

        _, qualified = bindings[key]
        parts = qualified.split("::")
        needle = []
        for part in parts:
            if needle:
                needle.append("::")
            needle.append(part)
        tokens = [token for token, _, _ in source_overlay_tokens(removed)]
        matches = [
            index for index in range(len(tokens) - len(needle) + 1)
            if tokens[index:index + len(needle)] == needle
        ]
        require(len(matches) == 1,
                f"{context}: removed definition identity is absent/ambiguous")
        try:
            open_brace = tokens.index("{", matches[0] + len(needle))
        except ValueError as error:
            raise ByteIdentityError(
                f"{context}: removed definition has no body"
            ) from error
        depth = 0
        close_brace = None
        for index in range(open_brace, len(tokens)):
            if tokens[index] == "{":
                depth += 1
            elif tokens[index] == "}":
                depth -= 1
                require(depth >= 0,
                        f"{context}: removed definition braces are invalid")
                if depth == 0:
                    close_brace = index
                    break
        require(close_brace == len(tokens) - 1,
                f"{context}: destructive range is not one complete definition")
    require(used == set(bindings),
            f"{context}: destructive source binding has no operation")
    return {
        "destructive_source_binding_count": len(used),
        "fresh_declaration_identifier_count": len(introduced_identifiers),
        "target_closure_generator_kinds": sorted(
            {generator["kind"] for operation in rendering["operations"]
             for generator in _source_overlay_generators(
                 operation["generator"])}
        ),
    }


SOURCE_TARGET_PERMUTATION_KINDS = frozenset({
    "dead_local_linear_updates_v1",
    "inline_default_constructor_dead_updates_v1",
})


# Which emission classes a target donor may seat in its OWN translation unit.
# Read from `SOURCE_OVERLAY_KIND_POLICIES`, the module's own per-generator
# classification, so this list cannot drift from what those generators
# actually emit.  `composed` is the sequence container itself, which carries
# no payload of its own -- every item inside it is classified separately by
# the same walk.
SOURCE_TARGET_CLOSURE_UNIT_EMISSION_CLASSES = frozenset({
    "non_emitting_declaration", "source_layout_only", "composed",
})


def require_source_target_closure_recipe_policy(
    recipe: dict, root, unit_source: str, context: str,
) -> dict:
    """Confine a target donor to bounded dead-local header changes.

    The donor renders its own translation unit and one or two headers.  Each
    header carries exactly one operation from the closed
    ``SOURCE_TARGET_PERMUTATION_KINDS`` pair, on a fresh dead local.

    The translation unit itself may carry DECLARATION-ONLY operations and
    nothing else.  The invariant being protected is that a target donor
    invents no code, data, strings, vtables or linker directives in its own
    TU -- not that its TU text is literally the checked-in file.  A
    declaration carrier satisfies that invariant by construction; it is the
    same non-emitting mechanism every ordinary donor recipe seats, and it
    lets the donor's view of its TU match the SHIPPED overlay's view instead
    of a text the build never compiles.  Membership is decided by the
    module's own generator emission classification, walked recursively so a
    sequence cannot smuggle an emitting item inside itself.
    """
    validated = validate_donor_source_overlay_recipe(recipe, root)
    require(
        validated["compile_lane"].get("include_projection")
        == "source_root_mirror_v1",
        f"{context}: header source permutations require the private "
        "source-root projection",
    )
    renderings = validated["renderings"]
    require(2 <= len(renderings) <= 3
            and sum(item["path"] == unit_source for item in renderings) == 1,
            f"{context}: donor must render its TU and one or two headers")
    unit = next(item for item in renderings if item["path"] == unit_source)
    unit_generators = list(_source_overlay_generators(unit["operations"]))
    for generator in unit_generators:
        policy = SOURCE_OVERLAY_KIND_POLICIES.get(generator["kind"])
        require(
            policy is not None
            and policy[0] in SOURCE_TARGET_CLOSURE_UNIT_EMISSION_CLASSES,
            f"{context}: donor translation-unit operations must be "
            f"declaration-only, not {generator['kind']}",
        )
    root = Path(root).resolve(strict=True)
    fresh_locals = set()
    kinds = set()
    for rendering in renderings:
        path = rendering["path"]
        if path == unit_source:
            continue
        require(PurePosixPath(path).suffix in {".h", ".hpp"},
                f"{context}: source permutation owner is not a header")
        clean = (root / path).read_bytes()
        tokens = [token for token, _, _ in source_overlay_tokens(clean)]
        require(len(rendering["operations"]) == 1,
                f"{context}: each permutation header must carry one operation")
        operation = rendering["operations"][0]
        generator = operation["generator"]
        kind = generator["kind"]
        require(kind in SOURCE_TARGET_PERMUTATION_KINDS and kind not in kinds,
                f"{context}: source permutation kind differs or repeats")
        kinds.add(kind)
        params = generator["params"]
        local = params["identifier"]
        require(local not in tokens and local not in fresh_locals,
                f"{context}: dead local is not fresh: {local}")
        fresh_locals.add(local)

        if kind == "dead_local_linear_updates_v1":
            require(operation["action"] == "replace",
                    f"{context}: dead-local block must replace an empty body")
            start = resolve_source_overlay_anchor(
                clean, operation["start_anchor"], context + " dead block start",
                logical_path=path,
            )
            end = resolve_source_overlay_anchor(
                clean, operation["end_anchor"], context + " dead block end",
                logical_path=path,
            )
            require(clean[start:end] == b"{}"
                    and generator["params"].get("renderer_layout", {}).get("nl")
                    is False,
                    f"{context}: dead-local replacement is not one empty body")
        else:
            require(operation["action"] == "insert",
                    f"{context}: default constructor must be inserted")
            identifier = params["class_identifier"]
            require(sum(
                tokens[index] in {"class", "struct"}
                and tokens[index + 1] == identifier
                for index in range(len(tokens) - 1)
            ) == 1, f"{context}: constructor class is absent or ambiguous")
    require(kinds and kinds <= SOURCE_TARGET_PERMUTATION_KINDS,
            f"{context}: a closed source permutation is required")
    return {
        "source_permutation_count": len(kinds),
        "fresh_dead_local_count": len(fresh_locals),
        "source_permutation_kinds": sorted(kinds),
        "unit_declaration_generator_count": len(unit_generators),
    }


def _source_overlay_identifier_list(
    value: object, context: str, *, minimum: int = 0, maximum: int = 4096,
) -> list[str]:
    require(isinstance(value, list) and minimum <= len(value) <= maximum,
            f"{context} has an invalid length")
    return [
        _source_overlay_identifier(item, f"{context}[{index}]")
        for index, item in enumerate(value)
    ]


def _source_overlay_qualified_parts(value: object, context: str) -> list[str]:
    parts = _source_overlay_identifier_list(
        value, context, minimum=1, maximum=16
    )
    return parts


def _source_overlay_member_identifier(value: object, context: str) -> str:
    require(isinstance(value, str) and value,
            f"{context} must be a member identifier")
    if value.startswith("~"):
        _source_overlay_identifier(value[1:], context + ".destructor")
        return value
    return _source_overlay_identifier(value, context)


def validate_source_overlay_expression(value: object, context: str) -> dict:
    require(isinstance(value, dict), f"{context} must be an object")
    kind = value.get("kind")
    if kind == "integer_literal":
        exact_audit_keys(value, {"kind", "value"}, context)
        return {
            "kind": kind,
            "value": require_exact_int(
                value.get("value"), context + ".value",
                minimum=0, maximum=(1 << 31) - 1,
            ),
        }
    if kind in {"null_cast", "null_cast_dereference"}:
        exact_audit_keys(value, {"kind", "type"}, context)
        return {
            "kind": kind,
            "type": validate_source_overlay_cpp_type(
                value.get("type"), context + ".type"
            ),
        }
    if kind == "identifier":
        exact_audit_keys(value, {"kind", "identifier"}, context)
        return {
            "kind": kind,
            "identifier": _source_overlay_identifier(
                value.get("identifier"), context + ".identifier"
            ),
        }
    raise ByteIdentityError(f"{context}.kind is unsupported")


def render_source_overlay_expression(value: dict) -> str:
    kind = value["kind"]
    if kind == "integer_literal":
        return str(value["value"])
    if kind in {"null_cast", "null_cast_dereference"}:
        rendered = f'({render_source_overlay_cpp_type(value["type"])}) 0'
        return "*" + rendered if kind == "null_cast_dereference" else rendered
    if kind == "identifier":
        return value["identifier"]
    raise ByteIdentityError(f"typed source expression is unsupported: {kind}")


SOURCE_OVERLAY_BUILTIN_SPECIFIERS = frozenset({
    "void", "bool", "char", "short", "int", "long",
    "signed", "unsigned", "float", "double",
})


SOURCE_OVERLAY_TYPE_NAME_RE = re.compile(
    r"[A-Za-z_][A-Za-z0-9_]*(?:::[A-Za-z_][A-Za-z0-9_]*)*"
)


def _parse_source_overlay_cpp_type(
    text: str, position: int, context: str, depth: int,
) -> tuple[dict, int]:
    require(depth <= 8, f"{context} exceeds the type recursion bound")
    base_const = False
    if text.startswith("const ", position):
        base_const = True
        position += 6
    match = SOURCE_OVERLAY_TYPE_NAME_RE.match(text, position)
    require(match is not None, f"{context} is not a closed type spelling")
    first = match.group(0)
    position = match.end()
    if first in SOURCE_OVERLAY_BUILTIN_SPECIFIERS:
        specifiers = [first]
        while len(specifiers) < 3 and text.startswith(" ", position):
            follow = SOURCE_OVERLAY_TYPE_NAME_RE.match(text, position + 1)
            if (follow is None
                    or follow.group(0) not in SOURCE_OVERLAY_BUILTIN_SPECIFIERS):
                break
            specifiers.append(follow.group(0))
            position = follow.end()
        base = {"kind": "builtin", "specifier_sequence": specifiers}
    elif text.startswith("<", position):
        position += 1
        arguments = []
        while True:
            argument, position = _parse_source_overlay_cpp_type(
                text, position, context, depth + 1
            )
            arguments.append(argument)
            if text.startswith(", ", position):
                position += 2
                continue
            require(text.startswith(">", position),
                    f"{context} template argument list is unterminated")
            position += 1
            break
        base = {
            "kind": "template_id",
            "qualified_identifier": first.split("::"),
            "arguments": arguments,
        }
    else:
        base = {"kind": "named", "qualified_identifier": first.split("::")}
    indirection = []
    trailing_const = False
    while position < len(text):
        if text.startswith("*", position):
            indirection.append("pointer")
            position += 1
        elif text.startswith("&", position):
            indirection.append("lvalue_reference")
            position += 1
        elif text.startswith(" const", position):
            trailing_const = True
            position += 6
        else:
            break
    return {
        "kind": "cpp_type", "base": base, "base_const": base_const,
        "indirection": indirection, "trailing_const": trailing_const,
    }, position


def parse_source_overlay_cpp_type(value: str, context: str) -> dict:
    """Parse one canonical type spelling through the closed type grammar.

    The spelling must round-trip exactly through
    :func:`render_source_overlay_cpp_type`, so no free-form text and no
    alternative formatting of the same type can enter the manifest.
    """
    parsed, position = _parse_source_overlay_cpp_type(value, 0, context, 0)
    require(position == len(value),
            f"{context} has trailing type text: {value!r}")
    require(render_source_overlay_cpp_type(parsed) == value,
            f"{context} is not the canonical type spelling: {value!r}")
    return parsed


def validate_source_overlay_cpp_type(
    value: object, context: str, *, depth: int = 0,
) -> dict:
    """Validate the closed C++ type grammar shared by generator kinds.

    The manifest stores canonical type strings; they are parsed through the
    closed grammar (round-trip enforced) and then validated structurally.
    """
    require(depth <= 8, f"{context} exceeds the type recursion bound")
    if isinstance(value, str):
        value = parse_source_overlay_cpp_type(value, context)
    require(isinstance(value, dict), f"{context} must be an object")
    exact_audit_keys(value, {
        "kind", "base", "base_const", "indirection", "trailing_const",
    }, context)
    require(value.get("kind") == "cpp_type"
            and type(value.get("base_const")) is bool
            and type(value.get("trailing_const")) is bool,
            f"{context} type policy differs")
    indirection = value.get("indirection")
    require(isinstance(indirection, list) and len(indirection) <= 2
            and all(item in {"pointer", "lvalue_reference"}
                    for item in indirection)
            and indirection.count("pointer") <= 1
            and indirection.count("lvalue_reference") <= 1,
            f"{context}.indirection differs")
    base = value.get("base")
    require(isinstance(base, dict), f"{context}.base must be an object")
    base_kind = base.get("kind")
    if base_kind == "builtin":
        exact_audit_keys(base, {"kind", "specifier_sequence"}, context + ".base")
        specifiers = base.get("specifier_sequence")
        require(isinstance(specifiers, list) and 1 <= len(specifiers) <= 3
                and all(item in {
                    "void", "bool", "char", "short", "int", "long",
                    "signed", "unsigned", "float", "double",
                } for item in specifiers),
                f"{context}.base.specifier_sequence differs")
        normalized_base = {
            "kind": "builtin", "specifier_sequence": list(specifiers)
        }
    elif base_kind == "named":
        exact_audit_keys(base, {"kind", "qualified_identifier"}, context + ".base")
        normalized_base = {
            "kind": "named",
            "qualified_identifier": _source_overlay_qualified_parts(
                base.get("qualified_identifier"),
                context + ".base.qualified_identifier",
            ),
        }
    elif base_kind == "template_id":
        exact_audit_keys(base, {
            "kind", "qualified_identifier", "arguments",
        }, context + ".base")
        arguments = base.get("arguments")
        require(isinstance(arguments, list) and 1 <= len(arguments) <= 16,
                f"{context}.base.arguments has an invalid length")
        normalized_base = {
            "kind": "template_id",
            "qualified_identifier": _source_overlay_qualified_parts(
                base.get("qualified_identifier"),
                context + ".base.qualified_identifier",
            ),
            "arguments": [
                validate_source_overlay_cpp_type(
                    item, f"{context}.base.arguments[{index}]", depth=depth + 1
                )
                for index, item in enumerate(arguments)
            ],
        }
    else:
        raise ByteIdentityError(f"{context}.base.kind is unsupported")
    return {
        "kind": "cpp_type", "base": normalized_base,
        "base_const": value["base_const"],
        "indirection": list(indirection),
        "trailing_const": value["trailing_const"],
    }


def render_source_overlay_cpp_type(value: dict) -> str:
    base = value["base"]
    if base["kind"] == "builtin":
        rendered = " ".join(base["specifier_sequence"])
    else:
        rendered = "::".join(base["qualified_identifier"])
        if base["kind"] == "template_id":
            rendered += "<" + ", ".join(
                render_source_overlay_cpp_type(item)
                for item in base["arguments"]
            ) + ">"
    if value["base_const"]:
        rendered = "const " + rendered
    trailing_const_rendered = False
    for item in value["indirection"]:
        if item == "pointer":
            rendered += "*"
            if value["trailing_const"]:
                rendered += " const"
                trailing_const_rendered = True
        else:
            rendered += "&"
    if value["trailing_const"] and not trailing_const_rendered:
        rendered += " const"
    return rendered


def validate_source_overlay_parameter(value: object, context: str) -> dict:
    require(isinstance(value, dict), f"{context} must be an object")
    require(set(value) in ({"type"}, {"identifier", "type"}),
            f"{context} has unexpected fields")
    result = {
        "type": validate_source_overlay_cpp_type(
            value.get("type"), context + ".type"
        )
    }
    if "identifier" in value:
        result["identifier"] = _source_overlay_identifier(
            value.get("identifier"), context + ".identifier"
        )
    return result


def render_source_overlay_parameter(value: dict) -> str:
    rendered = render_source_overlay_cpp_type(value["type"])
    if "identifier" in value:
        rendered += " " + value["identifier"]
    return rendered


def validate_member_signature_parameters(
    value: object, context: str,
) -> list[dict]:
    """Validate one closed, bounded, fully named member parameter list.

    Both member-signature forms render the SAME list, which is what keeps a
    single list authoritative for the declaration and the definition header.
    Every element must therefore carry its own identifier, and the identifiers
    must be pairwise distinct so the rendered definition header is a legal
    parameter list on its own.
    """
    require(isinstance(value, list) and 1 <= len(value) <= 4,
            f"{context} must be one to four parameters")
    parameters = [
        validate_source_overlay_parameter(item, f"{context}[{index}]")
        for index, item in enumerate(value)
    ]
    identifiers = [item.get("identifier") for item in parameters]
    require(all(identifiers),
            f"{context} parameters must each name their identifier")
    require(len(set(identifiers)) == len(identifiers),
            f"{context} parameter identifiers must be distinct")
    return parameters


def render_member_signature_parameters(parameters: list[dict]) -> str:
    return ", ".join(
        render_source_overlay_parameter(item) for item in parameters
    )


def validate_source_overlay_identifier_run(value: object, context: str) -> dict:
    require(isinstance(value, dict), f"{context} must be an object")
    exact_audit_keys(value, {"kind", "stem", "first", "count", "width"}, context)
    require(value.get("kind") == "identifier_run",
            f"{context}.kind differs")
    return {
        "kind": "identifier_run",
        "stem": _source_overlay_identifier(value.get("stem"), context + ".stem"),
        "first": require_exact_int(
            value.get("first"), context + ".first", minimum=0, maximum=1_000_000
        ),
        "count": require_exact_int(
            value.get("count"), context + ".count", minimum=1, maximum=4096
        ),
        "width": require_exact_int(
            value.get("width"), context + ".width", minimum=1, maximum=8
        ),
    }


def source_overlay_expand_identifier_run(value: dict) -> list[str]:
    return [
        value["stem"] + str(index).zfill(value["width"])
        for index in range(value["first"], value["first"] + value["count"])
    ]


def validate_source_overlay_identifier_collection(
    value: object, context: str, *, maximum: int = 4096,
) -> list[str] | dict:
    if isinstance(value, list):
        identifiers = _source_overlay_identifier_list(
            value, context, minimum=0, maximum=maximum,
        )
        require(identifiers == list(dict.fromkeys(identifiers)),
                f"{context} contains duplicate identifiers")
        return identifiers
    run = validate_source_overlay_identifier_run(value, context)
    require(run["count"] <= maximum, f"{context} exceeds its maximum")
    return run


def source_overlay_expand_identifier_collection(value: list[str] | dict) -> list[str]:
    return (
        list(value) if isinstance(value, list)
        else source_overlay_expand_identifier_run(value)
    )


def source_overlay_named_type_identities(value: object) -> list[str]:
    """Collect source-spelled named/template type identities from typed ASTs."""
    result = set()
    pending = [value]
    while pending:
        node = pending.pop()
        if isinstance(node, list):
            pending.extend(node)
        elif isinstance(node, dict):
            qualified = node.get("qualified_identifier")
            if (node.get("kind") in {"named", "template_id"}
                    and isinstance(qualified, list)):
                result.add("::".join(qualified))
            pending.extend(node.values())
    return sorted(result)


def source_overlay_expected_identifier_roles(
    kind: str, params: dict,
) -> dict[str, list[str]]:
    """Derive the exact output-affecting declaration/reference/emission sets.

    These roles are recomputed solely from normalized typed parameters.  The
    manifest census is an assertion and cannot mint or reclassify a symbol.
    """
    declared: set[str] = set()
    referenced: set[str] = set()
    emitted: set[str] = set()

    def definition(identifier: str) -> None:
        declared.add(identifier)
        emitted.add(identifier)

    def identifiers(value: object) -> list[str]:
        if value is None:
            return []
        if isinstance(value, str):
            return [value]
        return source_overlay_expand_identifier_collection(value)

    if kind == "declaration_sequence_v1":
        referenced.update(source_overlay_named_type_identities(params))
        owners = identifiers(params.get("identifier"))
        declared.update(owners)
        declared.update(identifiers(params.get("identifiers")))
        declared.update(
            item["identifier"] for item in params.get("enumerators", [])
        )
        for owner in owners:
            declared.update(
                f'{owner}::{member["identifier"]}'
                for member in params.get("members", [])
            )
    elif kind == "record_header_v1":
        recipe = params["typed_recipe"]
        for item in recipe["items"]:
            if isinstance(item, str):
                declared.add(item)
                if recipe["kind"] == "unused_class_with_inline_void_methods":
                    policy = recipe["method_identifier_policy"]
                    if policy == "single_unindexed_record":
                        declared.add(f"{item}::Record")
                    else:
                        declared.update(
                            f"{item}::Record{index}"
                            for index in range(recipe["methods_per_class"])
                        )
            else:
                declared.update((item["name"], item["enumerator"]))
    elif kind == "conditional_declarations_v1":
        referenced.add(params["condition"]["macro_identifier"])
    elif kind in {
        "line_reservation_v1", "include_dependency_v1", "include_seat_v1",
        "empty_compound_statements_v1", "synthetic_constant_pool_tu_v1",
    }:
        pass
    elif kind == "single_evaluation_binding_source_permutation_v1":
        declared.add(params["identifier"])
        referenced.update(
            token for token, _, _ in source_overlay_tokens(
                render_single_evaluation_binding_output(params)
            )
            if re.fullmatch(r"[A-Za-z_][A-Za-z0-9_]*", token)
            and token != params["identifier"]
        )
    elif kind == "for_initializer_declaration_reseat_v1":
        declared.add(params["identifier"])
        referenced.update({
            params["identifier"], params["container_identifier"],
            params["begin_member"], params["end_member"],
        })
        referenced.update(
            token for token, _, _ in source_overlay_tokens(
                render_source_overlay_cpp_type(
                    params["iterator_type"]
                ).encode("ascii")
            )
            if re.fullmatch(r"[A-Za-z_][A-Za-z0-9_]*", token)
        )
    elif kind == "fixed_array_fill_loop_v1":
        declared.add(params["index_identifier"])
        referenced.update({
            params["array_identifier"], params["index_identifier"],
        })
        referenced.update(
            source_overlay_named_type_identities(params["index_type"])
        )
    elif kind == "fixed_array_shuffle_pointer_countdown_v1":
        declared.add(params["pointer_identifier"])
        referenced.update({
            params["array_identifier"], params["index_identifier"],
            params["pointer_identifier"], params["swap_identifier"],
            params["temporary_identifier"], params["random_function"],
        })
        for name in (
            "index_type", "element_type", "swap_type", "temporary_type",
        ):
            referenced.update(
                source_overlay_named_type_identities(params[name]))
    elif kind == "inclusive_extent_assignment_v1":
        declared.add(params["identifier"])
        referenced.update({
            params["identifier"], params["source_object"],
            params["aggregate_accessor"], params["seed_extent_accessor"],
            params["upper_endpoint_accessor"],
            params["lower_endpoint_accessor"],
            params["destination_object"], params["destination_member"],
        })
        referenced.update(
            source_overlay_named_type_identities(params["coordinate_type"])
        )
    elif kind == "discarded_postfix_increment_v1":
        referenced.add(params["identifier"])
    elif kind == "constructor_allocation_lift_v1":
        # The refactor REMOVES a local and adds no file-scope declaration, so
        # nothing is declared here.  `emitted` stays empty deliberately: the
        # claim that the lifted inline constructor emits no COMDAT is not
        # asserted in the manifest, it is proved by the composer's
        # function_multiset(seed) == function_multiset(donor) obligation.
        referenced.update(
            token for token, _, _ in source_overlay_tokens(
                render_constructor_allocation_lift_output(params))
            if SOURCE_OVERLAY_IDENTIFIER_RE.fullmatch(token)
        )
        for name in ("buffer_cast_type", "element_type",
                     "caller_result_type", "iterator_type"):
            referenced.update(
                source_overlay_named_type_identities(params[name]))
    elif kind == "extern_declaration_run_v1":
        declared.update(
            params["prefix"] + str(index).zfill(params["width"])
            for index in range(params["count"])
        )
    elif kind == "captured_pointer_tail_return_fragment_v1":
        role = params["role"]
        if role == "capture_declaration":
            declared.add(params["capture_identifier"])
            referenced.update(
                source_overlay_named_type_identities(params["pointer_type"])
            )
        elif role in {"capture_assignment", "read_reseat"}:
            referenced.update({
                params["capture_identifier"], params["source_identifier"],
            })
        elif role == "return_to_goto":
            referenced.add(params["source_identifier"])
        else:
            require(role == "tail_return",
                    "captured tail-return role differs")
            referenced.add(params["capture_identifier"])
    elif kind == "member_signature_v1":
        referenced.add(params["class_identifier"])
        referenced.add(params["member_identifier"])
        for parameter in params.get("parameters", ()):
            referenced.update(
                source_overlay_named_type_identities(parameter["type"]))
            if "identifier" in parameter:
                referenced.add(parameter["identifier"])
    elif kind == "inline_budget_noop_statements_v1":
        referenced.add(params["assignment_target"])
    elif kind == "dead_local_linear_updates_v1":
        declared.add(params["identifier"])
        referenced.add(params["identifier"])
    elif kind == "inline_default_constructor_dead_updates_v1":
        definition(
            f'{params["class_identifier"]}::{params["class_identifier"]}'
        )
        declared.add(params["identifier"])
        referenced.update((params["class_identifier"], params["identifier"]))
    elif kind == "local_symbol_id_carrier_v1":
        declared.update(params["identifiers"])
        referenced.add(params["type"])
    elif kind == "debug_assert_reseat_v1":
        dead_local = params.get("dead_local")
        if dead_local:
            declared.update(dead_local["identifiers"])
            referenced.add(dead_local["type"])
        if "condition" in params:
            referenced.update({
                "grec": {"grec"}, "donut": {"donut"},
                "proi": {"proi"}, "r2": {"r2"},
                "v1_and_v2": {"v1", "v2"},
            }[params["condition"]])
        else:
            referenced.update({
                "p_ammo", "m_world", "m_boundary", "m_pathController",
                "m_grec",
            })
    elif kind == "compile_time_layout_assert_seat_v1":
        referenced.update(item["type"] for item in params["assertions"])
    elif kind == "literal_first_use_alias_v1":
        if "type" in params:
            declared.add(params["local_identifier"])
            referenced.update(source_overlay_named_type_identities(params["type"]))
        else:
            referenced.add(params["local_identifier"])
    elif kind == "list_cursor_delete_emission_probe_v1":
        definition(params["function_identifier"])
        referenced.update((
            params["container_type"], params["cursor_type"],
            params["element_type"],
        ))
    elif kind == "local_object_emission_probe_v1":
        definition(params["function_identifier"])
        declared.add(params["local_identifier"])
        referenced.add(params["local_type"])
    elif kind == "qualified_member_comdat_emission_probe_v1":
        definition(params["function_identifier"])
        referenced.update(
            source_overlay_named_type_identities(params["receiver_type"])
        )
        target = "::".join(params["qualified_member"])
        referenced.add(target)
        emitted.add(target)
    elif kind == "discarded_console_crt_pull_v1":
        definition(params["function_identifier"])
        referenced.add(params["timer_type"])
        referenced.update(params["import_calls"])
        referenced.update(
            f'{params["timer_type"]}::{group["timer_member_call"]}'
            for group in params["control_flow"]["case_groups"]
        )
    elif kind == "discarded_import_library_probe_v1":
        definition(params["function_identifier"])
        referenced.update((
            params["api"], params["capabilities_type"],
            params["tested_flag"],
        ))
    elif kind == "recursive_frame_texture_refresh_probe_v1":
        definition(params["function_identifier"])
        referenced.update(
            source_overlay_named_type_identities(params["parameter_type"])
        )
        referenced.add(params["pull_identity"])
    elif kind == "synthetic_crt_pull_v1":
        definition(params["function_identifier"])
        referenced.update(
            source_overlay_named_type_identities(params["parameter"]["type"])
        )
    elif kind == "archive_pull_seed_function_v1":
        definition(params["function_identifier"])
        referenced.update(source_overlay_named_type_identities(params["calls"]))
        referenced.update(
            "::".join(call["qualified_member"])
            for call in params["calls"]
        )
    elif kind == "archive_pull_seed_sequence_v1":
        definition(params["function_identifier"])
        referenced.update(
            source_overlay_named_type_identities(params["declarations"])
        )
        referenced.update(
            source_overlay_named_type_identities(params["statements"])
        )
        for declaration in params["declarations"]:
            owner = declaration.get("identifier")
            if owner:
                declared.add(owner)
            declared.update(
                f'{owner}::{member["identifier"]}'
                for member in declaration.get("members", [])
            )
        for statement in params["statements"]:
            statement_kind = statement["kind"]
            if statement_kind == "discarded_new":
                for type_name in source_overlay_named_type_identities(
                    statement["type"]
                ):
                    referenced.add(
                        f'{type_name}::{type_name.rsplit("::", 1)[-1]}'
                    )
            elif statement_kind == "free_call":
                referenced.add(statement["function_identifier"])
            elif statement_kind in {
                "qualified_call", "null_receiver_qualified_call",
            }:
                referenced.add("::".join(
                    statement["qualifier"] + [statement["member_identifier"]]
                ))
            else:
                require(statement_kind == "volatile_local_binding",
                        "typed archive seed statement kind is unsupported")
                referenced.add(statement["initializer"]["identifier"])
    elif kind == "source_range_relocation_v1":
        if params.get("role") != "destination_include_seat":
            identity = params.get("range_identity") or params.get(
                "logical_header"
            )
            require(identity, "source relocation definition lacks an identity")
            definition(identity)
    elif kind in {
        "synthetic_template_member_supplier_v1",
        "synthetic_member_call_supplier_v1",
    }:
        referenced.update(source_overlay_named_type_identities(params))
        prefix = params["prefix_declarations"]
        for name in (
            "forward_class_identifiers", "empty_class_identifiers",
            "value_counter_class_identifiers", "range_class_identifiers",
        ):
            declared.update(identifiers(prefix[name]))
        for enum in prefix["enum_declarations"]:
            declared.update((enum["identifier"], enum["enumerator"]))
        for counter in identifiers(prefix["value_counter_class_identifiers"]):
            declared.update((
                f"{counter}::GetValue", f"{counter}::m_value",
            ))
        for range_class in identifiers(prefix["range_class_identifiers"]):
            declared.update((
                f"{range_class}::GetFirst", f"{range_class}::GetLast",
                f"{range_class}::m_first", f"{range_class}::m_last",
            ))
        if kind == "synthetic_template_member_supplier_v1":
            declared.add(params["container_alias"]["identifier"])
            for probe in params["probes"]:
                probe_id = probe["probe_identifier"]
                get_id = f"{probe_id}::Get"
                declared.update((probe_id, f"{probe_id}::Fn", get_id))
                emitted.add(get_id)
                target = "::".join(probe["target_qualified_identifier"])
                referenced.add(target)
                emitted.add(target)
        else:
            wrapper = params["wrapper"]
            definition(wrapper["function_identifier"])
            owner_types = source_overlay_named_type_identities(
                wrapper["parameter"]["type"]
            )
            require(len(owner_types) == 1,
                    "member-call supplier wrapper owner is not singular")
            target = f"{owner_types[0]}::erase"
            referenced.add(target)
            emitted.add(target)
            for relocated in params["relocated_ranges"]:
                definition(relocated["range_identity"])
    elif kind == "synthetic_discarded_relocation_ring_v1":
        functions = {
            f'{params["function_identifier_stem"]}'
            f'{index:0{params["function_identifier_width"]}d}'
            for index in range(params["function_count"])
        }
        declared.update(functions)
        referenced.update(functions)
        emitted.update(functions)
    elif kind == "composed_typed_sequence_v1":
        for item in params["items"]:
            child = source_overlay_expected_identifier_roles(
                item["generator"]["kind"], item["generator"]["params"]
            )
            declared.update(child["declared_identifiers"])
            referenced.update(child["referenced_identifiers"])
            emitted.update(child["emitted_identifiers"])
    else:
        raise ByteIdentityError(
            f"source overlay role derivation is absent: {kind}"
        )
    return {
        "declared_identifiers": sorted(declared),
        "referenced_identifiers": sorted(referenced),
        "emitted_identifiers": sorted(emitted),
    }


def iter_source_overlay_leaf_generators(generator: dict):
    """Yield the physical rendering owners beneath a composite summary."""
    if generator["kind"] == "composed_typed_sequence_v1":
        for item in generator["params"]["items"]:
            yield from iter_source_overlay_leaf_generators(item["generator"])
        return
    yield generator


def source_overlay_generator_identity_scope(generator: dict) -> str:
    """Derive the closed C++ scope used for declaration collisions."""
    kind = generator["kind"]
    params = generator["params"]
    if kind == "local_symbol_id_carrier_v1":
        return f'function:{params["function"]}'
    if kind == "debug_assert_reseat_v1" and params.get("dead_local"):
        return f'function:{params["carrier_function"]}'
    if kind == "literal_first_use_alias_v1":
        return f'function:{params["owner_function"]}'
    return "output_scope"


def validate_source_overlay_indentation_units(
    raw: object, item_context: str,
) -> list[dict]:
    """Validate one canonical alternating tab/space indentation run list."""
    require(isinstance(raw, list) and len(raw) <= 32,
            f"{item_context} must be a bounded array")
    result = []
    previous = None
    for index, item in enumerate(raw):
        unit_context = f"{item_context}[{index}]"
        require(isinstance(item, dict), f"{unit_context} must be an object")
        exact_audit_keys(item, {"unit", "count"}, unit_context)
        unit = item.get("unit")
        require(unit in {"tab", "space"} and unit != previous,
                f"{unit_context}.unit differs or is noncanonical")
        previous = unit
        result.append({
            "unit": unit,
            "count": require_exact_int(
                item.get("count"), unit_context + ".count",
                minimum=1, maximum=4096,
            ),
        })
    return result


def validate_source_overlay_layout(value: dict, context: str) -> dict:
    """Validate the residual layout overrides of one lean generator.

    A generator's semantic renderer owns its canonical bytes: consecutive
    physical lines with the renderer's own indentation, LF endings and a
    terminal newline.  Only deviations from that default are stored:

    - ``lines``/``at``: an explicit canvas -- ``lines`` physical lines with
      the semantic content lines seated at the 1-based ``at`` positions and
      every other physical line blank;
    - ``indent``: replacement indentation for named semantic content lines;
    - ``nl``: ``False`` for a single unterminated physical line, ``"open"``
      for LF-joined lines without the terminal newline;
    - ``blank_indent``: visible whitespace on otherwise blank canvas lines.
    """
    normalized: dict = {}
    if "lines" in value or "at" in value:
        count = require_exact_int(
            value.get("lines"), context + ".lines",
            minimum=1, maximum=2_000_000,
        )
        raw_at = value.get("at", None)
        if raw_at is None:
            positions = None
        else:
            require(isinstance(raw_at, list) and len(raw_at) <= count,
                    f"{context}.at differs")
            positions = [
                require_exact_int(
                    item, f"{context}.at[{index}]", minimum=1, maximum=count,
                )
                for index, item in enumerate(raw_at)
            ]
            require(len(set(positions)) == len(positions),
                    f"{context}.at positions are duplicated")
        normalized["lines"] = count
        if positions is not None:
            normalized["at"] = positions
    else:
        require("blank_indent" not in value,
                f"{context}.blank_indent requires an explicit canvas")
    if "indent" in value:
        raw_indent = value.get("indent")
        require(isinstance(raw_indent, list) and raw_indent
                and len(raw_indent) <= 4096,
                f"{context}.indent differs")
        indent = []
        seen = set()
        for index, item in enumerate(raw_indent):
            item_context = f"{context}.indent[{index}]"
            require(isinstance(item, list) and len(item) == 2,
                    f"{item_context} must be a [line, units] pair")
            line = require_exact_int(
                item[0], item_context + ".line", minimum=1, maximum=2_000_000,
            )
            require(line not in seen, f"{item_context}.line is duplicated")
            seen.add(line)
            indent.append([
                line,
                validate_source_overlay_indentation_units(
                    item[1], item_context + ".units"
                ),
            ])
        normalized["indent"] = indent
    if "nl" in value:
        nl = value.get("nl")
        require(nl is False or nl == "open", f"{context}.nl differs")
        normalized["nl"] = nl
    if "blank_indent" in value:
        raw_blank = value.get("blank_indent")
        require(isinstance(raw_blank, list) and raw_blank
                and len(raw_blank) <= 4096,
                f"{context}.blank_indent differs")
        blank = []
        previous_end = 0
        for index, item in enumerate(raw_blank):
            item_context = f"{context}.blank_indent[{index}]"
            require(isinstance(item, list) and len(item) == 3,
                    f"{item_context} must be a [first, count, units] triple")
            first = require_exact_int(
                item[0], item_context + ".first",
                minimum=1, maximum=normalized["lines"],
            )
            count = require_exact_int(
                item[1], item_context + ".count",
                minimum=1, maximum=normalized["lines"],
            )
            require(first > previous_end
                    and first + count - 1 <= normalized["lines"],
                    f"{item_context} is unsorted, overlapping, or out of range")
            previous_end = first + count - 1
            units = validate_source_overlay_indentation_units(
                item[2], item_context + ".units"
            )
            require(units, f"{item_context}.units must be visible whitespace")
            blank.append([first, count, units])
        normalized["blank_indent"] = blank
    return normalized


def source_overlay_generator_policy(kind: str, params: dict) -> tuple[str, str]:
    if kind != "source_range_relocation_v1":
        policy = SOURCE_OVERLAY_KIND_POLICIES.get(kind)
        require(policy is not None,
                f"source overlay generator kind is unsupported: {kind}")
        return policy
    if params.get("role") == "destination_include_seat":
        return "include_dependency", "source_relocation_include_seat"
    return "source_relocation", "authenticated_source_range_owner_transfer"


def _expand_source_overlay_name_runs(
    value: object, context: str, *, maximum: int = 4096,
) -> list[str]:
    """Expand one lean run-compressed name list (strings and run records)."""
    require(isinstance(value, list) and 1 <= len(value) <= maximum,
            f"{context} has an invalid length")
    names = []
    for index, item in enumerate(value):
        item_context = f"{context}[{index}]"
        if isinstance(item, str):
            names.append(_source_overlay_identifier(item, item_context))
            continue
        require(isinstance(item, dict), f"{item_context} must be a name or run")
        exact_audit_keys(item, {"stem", "first", "count", "width"},
                         item_context, optional={"width"})
        stem = _source_overlay_identifier(item.get("stem"), item_context + ".stem")
        first = require_exact_int(
            item.get("first"), item_context + ".first",
            minimum=0, maximum=1_000_000,
        )
        count = require_exact_int(
            item.get("count"), item_context + ".count",
            minimum=1, maximum=4096,
        )
        width = require_exact_int(
            item.get("width", len(str(first))), item_context + ".width",
            minimum=1, maximum=8,
        )
        names.extend(
            stem + str(number).zfill(width)
            for number in range(first, first + count)
        )
    require(len(names) <= maximum, f"{context} exceeds its maximum")
    return names


def _expand_source_overlay_lean_declaration(
    short: str, semantic: dict, context: str,
) -> dict:
    """Expand one lean declaration-shape record into rich typed params."""
    shape = SOURCE_OVERLAY_LEAN_SHAPES[short]
    params: dict = {"shape": shape}
    if shape in {
        "forward", "forward_sequence", "empty_class",
        "unused_class_void_member_sequence",
    }:
        params["tag"] = semantic.pop("tag", "class")
    if "id" in semantic:
        params["identifier"] = semantic.pop("id")
    if shape == "forward_sequence":
        params["identifiers"] = semantic.pop("identifiers", None)
    elif shape == "enum":
        params["enumerators"] = [
            {"identifier": name}
            for name in _expand_source_overlay_name_runs(
                semantic.pop("members", None), context + ".members"
            )
        ]
        params["trailing_comma"] = semantic.pop("trailing_comma", False)
    elif shape == "typedef_builtin":
        params["aliased_type"] = semantic.pop("aliased_type", None)
    elif shape == "function_prototype":
        params["return_type"] = semantic.pop("return_type", None)
        params["parameters"] = semantic.pop("parameters", None)
    elif shape == "unused_class_void_member_sequence":
        raw_members = semantic.pop("members", None)
        transitions = semantic.pop("access", [])
        inline_default = semantic.pop("inline", False)
        require(inline_default is True or inline_default is False,
                f"{context}.inline differs")
        require(isinstance(raw_members, list) and raw_members,
                f"{context}.members must be a non-empty array")
        members = []
        for index, item in enumerate(raw_members):
            item_context = f"{context}.members[{index}]"
            if isinstance(item, str) or (
                isinstance(item, dict) and "stem" in item
            ):
                members.extend(
                    {
                        "kind": "empty_void_method_definition",
                        "identifier": name,
                        "inline_specifier": inline_default,
                    }
                    for name in _expand_source_overlay_name_runs(
                        [item], item_context
                    )
                )
            elif isinstance(item, dict) and set(item) == {"decl"}:
                members.append({
                    "kind": "void_method_declaration",
                    "identifier": item["decl"],
                    "inline_specifier": False,
                })
            elif isinstance(item, dict) and set(item) == {"id", "inline"}:
                require(item["inline"] is True, f"{item_context}.inline differs")
                members.append({
                    "kind": "empty_void_method_definition",
                    "identifier": item["id"],
                    "inline_specifier": True,
                })
            else:
                raise ByteIdentityError(f"{item_context} member form differs")
        active = "implicit_default"
        transition_by_index = {}
        if isinstance(transitions, list):
            transition_by_index = {
                item.get("before_member_index"): item.get("access")
                for item in transitions if isinstance(item, dict)
            }
        for index, member in enumerate(members):
            if index in transition_by_index:
                active = transition_by_index[index]
            member["access"] = active
        params["members"] = members
        params["access_transitions"] = transitions
    require(not semantic,
            f"{context} has unexpected fields: {sorted(semantic)}")
    return params


def _expand_source_overlay_lean_generator(
    value: object, context: str,
) -> tuple[str, dict, dict]:
    """Split one lean generator record into (kind, params, layout residual)."""
    require(isinstance(value, dict), f"{context} must be an object")
    short = value.get("k")
    require(isinstance(short, str), f"{context}.k must be a generator kind")
    semantic = {
        key: item for key, item in value.items()
        if key != "k" and key not in SOURCE_OVERLAY_LEAN_LAYOUT_KEYS
    }
    layout_raw = {
        key: item for key, item in value.items()
        if key in SOURCE_OVERLAY_LEAN_LAYOUT_KEYS
    }
    if short in SOURCE_OVERLAY_LEAN_SHAPES:
        return (
            "declaration_sequence_v1",
            _expand_source_overlay_lean_declaration(short, semantic, context),
            layout_raw,
        )
    kind = SOURCE_OVERLAY_LEAN_KINDS.get(short)
    require(kind is not None, f"{context}.k is unsupported: {short}")
    if kind == "line_reservation_v1":
        exact_audit_keys(semantic, {"n"}, context)
        return kind, {"physical_line_count": semantic["n"]}, layout_raw
    if kind == "composed_typed_sequence_v1":
        exact_audit_keys(semantic, {"items"}, context)
        count = layout_raw.pop("lines", None)
        require(not layout_raw,
                f"{context} composite layout overrides are unsupported")
        raw_items = semantic["items"]
        require(isinstance(raw_items, list) and raw_items,
                f"{context}.items must be a non-empty array")
        items = []
        for index, item in enumerate(raw_items):
            item_context = f"{context}.items[{index}]"
            require(isinstance(item, dict) and "line" in item,
                    f"{item_context} must seat a generator at a line")
            item = dict(item)
            line = item.pop("line")
            if item.get("k") == "fwd_run":
                exact_audit_keys(
                    item, {"k", "stem", "first", "count", "width", "tag"},
                    item_context, optional={"width", "tag"},
                )
                run = {
                    key: item[key] for key in ("stem", "first", "count", "width")
                    if key in item
                }
                names = _expand_source_overlay_name_runs([run], item_context)
                require(isinstance(line, int), f"{item_context}.line differs")
                for offset, name in enumerate(names):
                    child = {"k": "fwd", "id": name}
                    if "tag" in item:
                        child["tag"] = item["tag"]
                    items.append({"line": line + offset, "lean": child})
            else:
                items.append({"line": line, "lean": item})
        return kind, {"physical_line_count": count, "items": items}, {}
    return kind, semantic, layout_raw


def _validate_dead_local_update_params(
    params: object, context: str, *, constructor: bool,
) -> dict:
    """Validate one closed, observable-effect-free integer state carrier."""
    require(isinstance(params, dict), f"{context} must be an object")
    keys = {"id", "initial", "increment", "repeat"}
    if constructor:
        keys.add("class")
    exact_audit_keys(params, keys, context)
    initial = require_exact_int(
        params.get("initial"), context + ".initial",
        minimum=-(1 << 31), maximum=(1 << 31) - 1,
    )
    increment = require_exact_int(
        params.get("increment"), context + ".increment",
        minimum=-(1 << 31), maximum=(1 << 31) - 1,
    )
    repeat = require_exact_int(
        params.get("repeat"), context + ".repeat", minimum=1, maximum=64,
    )
    require(increment != 0, f"{context}.increment must move compiler state")
    final = initial + increment * repeat
    require(-(1 << 31) <= final <= (1 << 31) - 1,
            f"{context} signed int update sequence can overflow")
    normalized = {
        "identifier": _source_overlay_identifier(
            params.get("id"), context + ".id"
        ),
        "initial_value": initial,
        "increment": increment,
        "repeat": repeat,
    }
    if constructor:
        normalized["class_identifier"] = _source_overlay_identifier(
            params.get("class"), context + ".class"
        )
    return normalized


def validate_source_overlay_generator(value: object, context: str) -> dict:
    """Validate the closed typed-generator registry in its lean surface form.

    Production kinds are added here with exact recursive schemas.  There is no
    generic text/template/command escape hatch, and descriptive metadata never
    reaches a renderer.
    """
    kind, params, layout_raw = _expand_source_overlay_lean_generator(
        value, context
    )
    param_context = context + ".params"
    layout = validate_source_overlay_layout(layout_raw, context + ".layout")
    if kind == "line_reservation_v1":
        normalized = {
            "physical_line_count": require_exact_int(
                params.get("physical_line_count"),
                param_context + ".physical_line_count", minimum=1, maximum=4096,
            ),
        }
    elif kind == "include_dependency_v1":
        exact_audit_keys(params, {"header", "style"}, param_context)
        header = params.get("header")
        require(isinstance(header, str) and header and len(header) <= 256
                and "\\" not in header and "\0" not in header
                and not PurePosixPath(header).is_absolute()
                and ".." not in PurePosixPath(header).parts
                and all(character not in header for character in '<>"\'\n\r'),
                f"{param_context}.header is unsafe")
        require(params.get("style") in {"angle", "quote"},
                f"{param_context}.style differs")
        normalized = {"header": header, "style": params["style"]}
    elif kind == "include_seat_v1":
        exact_audit_keys(params, {"basename", "logical_header", "style"}, param_context)
        logical = source_overlay_relative_path(
            params.get("logical_header"), param_context + ".logical_header"
        )
        basename = params.get("basename")
        require(isinstance(basename, str) and basename == PurePosixPath(logical).name,
                f"{param_context}.basename differs from logical_header")
        require(params.get("style") in {"angle", "quote"},
                f"{param_context}.style differs")
        normalized = {
            "basename": basename, "logical_header": logical,
            "style": params["style"],
        }
    elif kind == "member_signature_v1":
        # A7: {class_identifier, member_identifier, kind, form} and, for the
        # constructor kind only, one closed typed parameter list plus an
        # optional one-element specifier enum.  A7c stays structural -- there
        # is still no return-type key and no body key anywhere in the
        # parameter set, so neither can be emitted, and every parameter is
        # routed through the existing closed cpp-type grammar, so a parameter
        # can never become free-form text.
        require(params.get("kind") in MEMBER_SIGNATURE_KINDS,
                f"{param_context}.kind is outside the closed enum "
                f"{sorted(MEMBER_SIGNATURE_KINDS)}")
        require(params.get("form") in MEMBER_SIGNATURE_FORMS,
                f"{param_context}.form is outside the closed enum "
                f"{sorted(MEMBER_SIGNATURE_FORMS)}")
        signature_keys = {
            "class_identifier", "member_identifier", "kind", "form",
        }
        if params["kind"] == "constructor":
            signature_keys.add("parameters")
        optional_keys = (
            {"specifiers"} if params["kind"] == "constructor" else set()
        )
        exact_audit_keys(params, signature_keys | optional_keys,
                         param_context, optional=optional_keys)
        normalized = {
            "class_identifier": _source_overlay_identifier(
                params.get("class_identifier"),
                param_context + ".class_identifier",
            ),
            "member_identifier": _source_overlay_identifier(
                params.get("member_identifier"),
                param_context + ".member_identifier",
            ),
            "kind": params["kind"],
            "form": params["form"],
        }
        if params["kind"] == "constructor":
            # The name is not free: a constructor is named by its class, so
            # the generator cannot mint an arbitrary member name.
            require(normalized["member_identifier"]
                    == normalized["class_identifier"],
                    f"{param_context}.member_identifier must equal the class "
                    "identifier for a constructor signature")
            normalized["parameters"] = validate_member_signature_parameters(
                params.get("parameters"), param_context + ".parameters")
            if "specifiers" in params:
                # A one-element closed enum, not text.  `inline` is
                # load-bearing for the out-of-class definition header and has
                # no meaning on an in-class declaration, so it is admitted on
                # exactly one form.
                require(params.get("specifiers") == ["inline"],
                        f"{param_context}.specifiers must be exactly "
                        '["inline"]')
                require(params["form"] == "qualified_definition_header",
                        f"{param_context}.specifiers is admitted only on the "
                        "qualified definition header form")
                normalized["specifiers"] = ["inline"]
    elif kind == "single_evaluation_binding_source_permutation_v1":
        require(not layout,
                f"{context}: a bind-once source permutation cannot carry "
                "layout overrides")
        exact_audit_keys(params, {
            "type", "id", "expression", "use", "declaration_indent",
        }, param_context)
        identifier = _source_overlay_identifier(
            params.get("id"), param_context + ".id"
        )
        expression = params.get("expression")
        require(
            isinstance(expression, str) and expression.isascii()
            and 1 <= len(expression) <= 256
            and expression == expression.strip()
            and not any(character in expression for character in "\0\r\n;{}#\\\"'")
            and "++" not in expression and "--" not in expression
            and re.search(rf"\b{re.escape(identifier)}\b", expression) is None,
            f"{param_context}.expression is not a single safe expression",
        )
        use = params.get("use")
        declaration_indent = params.get("declaration_indent")
        require(
            isinstance(declaration_indent, str)
            and declaration_indent.isascii()
            and len(declaration_indent) <= 32
            and set(declaration_indent) <= {" ", "\t"},
            f"{param_context}.declaration_indent differs",
        )
        require(isinstance(use, dict), f"{param_context}.use must be an object")
        use_kind = use.get("kind")
        if use_kind == "new_array_extent_binding":
            exact_audit_keys(
                use, {"kind", "element_type", "result_identifier"},
                param_context + ".use",
            )
            element_type = validate_source_overlay_cpp_type(
                use.get("element_type"), param_context + ".use.element_type"
            )
            require(not element_type["indirection"]
                    and not element_type["trailing_const"],
                    f"{param_context}.use.element_type is not an array element")
            normalized_use = {
                "kind": use_kind,
                "element_type": element_type,
                "result_identifier": _source_overlay_identifier(
                    use.get("result_identifier"),
                    param_context + ".use.result_identifier",
                ),
            }
        elif use_kind == "member_assignment_receiver_binding":
            exact_audit_keys(
                use, {"kind", "member_identifier", "value_identifier"},
                param_context + ".use",
            )
            normalized_use = {
                "kind": use_kind,
                "member_identifier": _source_overlay_identifier(
                    use.get("member_identifier"),
                    param_context + ".use.member_identifier",
                ),
                "value_identifier": _source_overlay_identifier(
                    use.get("value_identifier"),
                    param_context + ".use.value_identifier",
                ),
            }
        else:
            raise ByteIdentityError(
                f"{param_context}.use.kind is unsupported: {use_kind!r}"
            )
        normalized = {
            "declaration_type": validate_source_overlay_cpp_type(
                params.get("type"), param_context + ".type"
            ),
            "identifier": identifier,
            "expression": expression,
            "use": normalized_use,
            "declaration_indent": declaration_indent,
        }
    elif kind == "for_initializer_declaration_reseat_v1":
        require(not layout,
                f"{context}: a for-initializer reseat cannot carry layout "
                "overrides")
        exact_audit_keys(params, {
            "form", "type", "id", "container", "begin", "end",
            "declaration_indent",
        }, param_context)
        require(params.get("form") in {
                    "standalone_then_assignment_v1",
                    "declaration_in_initializer_v1",
                },
                f"{param_context}.form differs")
        indentation = params.get("declaration_indent")
        require(isinstance(indentation, str) and indentation.isascii()
                and 1 <= len(indentation) <= 32
                and set(indentation) <= {" ", "\t"},
                f"{param_context}.declaration_indent differs")
        iterator_type = validate_source_overlay_cpp_type(
            params.get("type"), param_context + ".type")
        require(not iterator_type["indirection"]
                and not iterator_type["trailing_const"],
                f"{param_context}.type is not a value iterator type")
        normalized = {
            "form": params["form"],
            "iterator_type": iterator_type,
            "identifier": _source_overlay_identifier(
                params.get("id"), param_context + ".id"),
            "container_identifier": _source_overlay_identifier(
                params.get("container"), param_context + ".container"),
            "begin_member": _source_overlay_identifier(
                params.get("begin"), param_context + ".begin"),
            "end_member": _source_overlay_identifier(
                params.get("end"), param_context + ".end"),
            "indentation": indentation,
        }
    elif kind == "fixed_array_fill_loop_v1":
        require(not layout,
                f"{context}: a fixed-array fill loop cannot carry layout "
                "overrides")
        exact_audit_keys(params, {
            "array", "index", "index_type", "count", "value",
            "declaration_indent",
        }, param_context)
        array = _source_overlay_identifier(
            params.get("array"), param_context + ".array")
        index = _source_overlay_identifier(
            params.get("index"), param_context + ".index")
        require(array != index,
                f"{param_context}.index must differ from the array")
        index_type = validate_source_overlay_cpp_type(
            params.get("index_type"), param_context + ".index_type")
        require(not index_type["base_const"]
                and not index_type["indirection"]
                and not index_type["trailing_const"]
                and render_source_overlay_cpp_type(index_type)
                in FIXED_ARRAY_FILL_INDEX_TYPE_SPELLINGS,
                f"{param_context}.index_type is not a closed, bounded "
                "integral type")
        require(type(params.get("value")) is int
                and params["value"] == -1,
                f"{param_context}.value must be exactly -1")
        indentation = params.get("declaration_indent")
        require(isinstance(indentation, str) and indentation.isascii()
                and 1 <= len(indentation) <= 32
                and set(indentation) <= {" ", "\t"},
                f"{param_context}.declaration_indent differs")
        normalized = {
            "array_identifier": array,
            "index_identifier": index,
            "index_type": index_type,
            "count": require_exact_int(
                params.get("count"), param_context + ".count",
                minimum=1, maximum=4096,
            ),
            "value": -1,
            "declaration_indent": indentation,
        }
    elif kind == "fixed_array_shuffle_pointer_countdown_v1":
        require(not layout,
                f"{context}: a fixed-array shuffle countdown cannot carry "
                "layout overrides")
        exact_audit_keys(params, {
            "array", "index", "index_type", "pointer", "element_type",
            "swap", "swap_type", "temporary", "temporary_type",
            "random_function", "count", "declaration_indent",
        }, param_context)
        identifiers = {
            name: _source_overlay_identifier(
                params.get(raw), f"{param_context}.{raw}")
            for name, raw in (
                ("array_identifier", "array"),
                ("index_identifier", "index"),
                ("pointer_identifier", "pointer"),
                ("swap_identifier", "swap"),
                ("temporary_identifier", "temporary"),
                ("random_function", "random_function"),
            )
        }
        require(len(set(identifiers.values())) == len(identifiers),
                f"{param_context}: shuffle roles must be distinct")

        def integral_type(raw_name: str) -> dict:
            result = validate_source_overlay_cpp_type(
                params.get(raw_name), f"{param_context}.{raw_name}")
            require(not result["base_const"]
                    and not result["indirection"]
                    and not result["trailing_const"]
                    and render_source_overlay_cpp_type(result)
                    in FIXED_ARRAY_FILL_ELEMENT_TYPE_SPELLINGS,
                    f"{param_context}.{raw_name} is not a closed integral "
                    "value type")
            return result

        index_type = integral_type("index_type")
        element_type = integral_type("element_type")
        swap_type = integral_type("swap_type")
        temporary_type = integral_type("temporary_type")
        require(index_type == swap_type,
                f"{param_context}: index and swap types must match")
        require(element_type == temporary_type,
                f"{param_context}: element and temporary types must match")
        indentation = params.get("declaration_indent")
        require(isinstance(indentation, str) and indentation.isascii()
                and 1 <= len(indentation) <= 32
                and set(indentation) <= {" ", "\t"},
                f"{param_context}.declaration_indent differs")
        normalized = {
            **identifiers,
            "index_type": index_type,
            "element_type": element_type,
            "swap_type": swap_type,
            "temporary_type": temporary_type,
            "count": require_exact_int(
                params.get("count"), param_context + ".count",
                minimum=2, maximum=4096,
            ),
            "declaration_indent": indentation,
        }
    elif kind == "constructor_allocation_lift_v1":
        require(not layout,
                f"{context}: a constructor allocation lift cannot carry "
                "layout overrides")
        exact_audit_keys(params, {
            "role", "class_identifier", "parameter_identifier",
            "buffer_member", "buffer_cast_type", "element_type",
            "extent_function", "copy_function", "null_members",
            "caller_result_identifier", "caller_result_type",
            "null_argument_position", "iterator_type",
            "iterator_identifier", "container_identifier", "find_member",
            "declaration_indent",
        }, param_context)
        require(params.get("role") in {"call_site", "constructor_body"},
                f"{param_context}.role is outside the closed enum")
        identifiers = {
            name: _source_overlay_identifier(
                params.get(name), f"{param_context}.{name}")
            for name in (
                "class_identifier", "parameter_identifier", "buffer_member",
                "extent_function", "copy_function",
                "caller_result_identifier", "iterator_identifier",
                "container_identifier", "find_member",
            )
        }
        null_members = _source_overlay_identifier_list(
            params.get("null_members"), param_context + ".null_members",
            minimum=1, maximum=4,
        )
        require(len(set(null_members)) == len(null_members),
                f"{param_context}.null_members must be distinct")
        require(
            len(set(identifiers.values()) | set(null_members))
            == len(identifiers) + len(null_members),
            f"{param_context}: allocation-lift roles must be distinct",
        )
        element_type = validate_source_overlay_cpp_type(
            params.get("element_type"), param_context + ".element_type")
        require(not element_type["base_const"]
                and not element_type["indirection"]
                and not element_type["trailing_const"]
                and render_source_overlay_cpp_type(element_type)
                in FIXED_ARRAY_FILL_ELEMENT_TYPE_SPELLINGS,
                f"{param_context}.element_type is not a closed integral "
                "value type")
        buffer_cast_type = validate_source_overlay_cpp_type(
            params.get("buffer_cast_type"),
            param_context + ".buffer_cast_type")
        require(buffer_cast_type == {**element_type,
                                     "indirection": ["pointer"]},
                f"{param_context}.buffer_cast_type is not the element type "
                "plus exactly one pointer")
        caller_result_type = validate_source_overlay_cpp_type(
            params.get("caller_result_type"),
            param_context + ".caller_result_type")
        require(caller_result_type == buffer_cast_type,
                f"{param_context}.caller_result_type differs from the buffer "
                "cast type")
        iterator_type = validate_source_overlay_cpp_type(
            params.get("iterator_type"), param_context + ".iterator_type")
        require(not iterator_type["base_const"]
                and not iterator_type["indirection"]
                and not iterator_type["trailing_const"]
                and iterator_type["base"]["kind"] == "named",
                f"{param_context}.iterator_type is not a plain named type")
        null_argument_position = require_exact_int(
            params.get("null_argument_position"),
            param_context + ".null_argument_position",
            minimum=0, maximum=len(null_members),
        )
        indentation = params.get("declaration_indent")
        require(isinstance(indentation, str) and indentation.isascii()
                and 1 <= len(indentation) <= 32
                and set(indentation) <= {" ", "\t"},
                f"{param_context}.declaration_indent differs")
        normalized = {
            "role": params["role"],
            **identifiers,
            "buffer_cast_type": buffer_cast_type,
            "element_type": element_type,
            "null_members": null_members,
            "caller_result_type": caller_result_type,
            "null_argument_position": null_argument_position,
            "iterator_type": iterator_type,
            "declaration_indent": indentation,
        }
    elif kind == "inclusive_extent_assignment_v1":
        require(not layout,
                f"{context}: an inclusive-extent assignment cannot carry "
                "layout overrides")
        exact_audit_keys(params, {
            "type", "id", "source", "seed_extent_accessor",
            "upper_endpoint_accessor", "lower_endpoint_accessor",
            "destination", "declaration_indent", "barrier",
        }, param_context)
        source = params.get("source")
        require(isinstance(source, dict),
                f"{param_context}.source must be an object")
        exact_audit_keys(source, {"object", "aggregate_accessor"},
                         param_context + ".source")
        destination = params.get("destination")
        require(isinstance(destination, dict),
                f"{param_context}.destination must be an object")
        exact_audit_keys(destination, {"object", "member"},
                         param_context + ".destination")
        coordinate_type = validate_source_overlay_cpp_type(
            params.get("type"), param_context + ".type")
        require(not coordinate_type["base_const"]
                and not coordinate_type["indirection"]
                and not coordinate_type["trailing_const"]
                and render_source_overlay_cpp_type(coordinate_type)
                in FIXED_ARRAY_FILL_ELEMENT_TYPE_SPELLINGS,
                f"{param_context}.type is not a closed integral type")
        identifier = _source_overlay_identifier(
            params.get("id"), param_context + ".id")
        source_object = _source_overlay_identifier(
            source.get("object"), param_context + ".source.object")
        aggregate_accessor = _source_overlay_identifier(
            source.get("aggregate_accessor"),
            param_context + ".source.aggregate_accessor")
        destination_object = _source_overlay_identifier(
            destination.get("object"),
            param_context + ".destination.object")
        destination_member = _source_overlay_identifier(
            destination.get("member"),
            param_context + ".destination.member")
        accessors = {
            "seed_extent_accessor": _source_overlay_identifier(
                params.get("seed_extent_accessor"),
                param_context + ".seed_extent_accessor"),
            "upper_endpoint_accessor": _source_overlay_identifier(
                params.get("upper_endpoint_accessor"),
                param_context + ".upper_endpoint_accessor"),
            "lower_endpoint_accessor": _source_overlay_identifier(
                params.get("lower_endpoint_accessor"),
                param_context + ".lower_endpoint_accessor"),
        }
        require(len(set(accessors.values())) == 3,
                f"{param_context}: extent accessors must be distinct")
        require(aggregate_accessor not in accessors.values(),
                f"{param_context}: aggregate and extent accessors must "
                "differ")
        require(identifier not in {
                    source_object, aggregate_accessor, destination_object,
                    *accessors.values(),
                },
                f"{param_context}.id collides with an authenticated role")
        indentation = params.get("declaration_indent")
        require(isinstance(indentation, str) and indentation.isascii()
                and 1 <= len(indentation) <= 32
                and set(indentation) <= {" ", "\t"},
                f"{param_context}.declaration_indent differs")
        require(params.get("barrier") == INCLUSIVE_EXTENT_BARRIER,
                f"{param_context}.barrier differs")
        normalized = {
            "coordinate_type": coordinate_type,
            "identifier": identifier,
            "source_object": source_object,
            "aggregate_accessor": aggregate_accessor,
            **accessors,
            "destination_object": destination_object,
            "destination_member": destination_member,
            "declaration_indent": indentation,
            "barrier": INCLUSIVE_EXTENT_BARRIER,
        }
    elif kind == "discarded_postfix_increment_v1":
        require(not layout,
                f"{context}: a discarded increment cannot carry layout "
                "overrides")
        exact_audit_keys(params, {"id", "declaration_indent"}, param_context)
        indentation = params.get("declaration_indent")
        require(isinstance(indentation, str) and indentation.isascii()
                and 1 <= len(indentation) <= 32
                and set(indentation) <= {" ", "\t"},
                f"{param_context}.declaration_indent differs")
        normalized = {
            "identifier": _source_overlay_identifier(
                params.get("id"), param_context + ".id"),
            "declaration_indent": indentation,
        }
    elif kind == "extern_declaration_run_v1":
        require(not layout,
                f"{context}: an extern declaration run cannot carry layout "
                "overrides")
        exact_audit_keys(params, {"prefix", "count", "width"}, param_context)
        prefix = params.get("prefix")
        count = require_exact_int(
            params.get("count"), param_context + ".count",
            minimum=1, maximum=999)
        width = require_exact_int(
            params.get("width"), param_context + ".width",
            minimum=1, maximum=3)
        require(isinstance(prefix, str), f"{param_context}.prefix differs")
        try:
            entropy_generator.generate_extern_run(prefix, count, width)
        except ValueError as error:
            raise ByteIdentityError(
                f"{param_context}: extern declaration run differs: {error}"
            ) from error
