def source_overlay_generator_is_source_refactor(generator: dict) -> bool:
    """Does this generator make its recipe a source-refactor recipe?

    Membership in ``SOURCE_REFACTOR_GENERATOR_KINDS`` is the ordinary answer.
    A ``member_signature_v1`` with ``kind == "constructor"`` is the other one:
    it introduces a member the checked-in tree does not declare, so it must be
    subject to the same census as any other source permutation.  Because
    ``require_source_refactor_donor_bindings`` then demands that the recipe be
    bound EXACTLY ONCE to a source-aware composer, a constructor signature can
    only ever exist inside a donor carrying a validated
    ``target_source_refactor`` proof.
    """
    if generator["kind"] in SOURCE_REFACTOR_GENERATOR_KINDS:
        return True
    return (generator["kind"] == "member_signature_v1"
            and generator["params"].get("kind") == "constructor")


def render_cross_tu_complete_target_source(
    recipe: dict,
    owner_source: str,
    donor_source: str,
    donor_effective: bytes,
    forward_generated: bytes,
    context: str,
) -> bytes:
    """Render and pin the only source form admitted by the whole-target role."""
    require(
        recipe.get("role_policy")
        == CROSS_TU_COMPLETE_TARGET_RECIPE_POLICY,
        f"{context}: cross-TU complete-target role policy differs",
    )
    require(
        isinstance(owner_source, str) and isinstance(donor_source, str)
        and donor_source != owner_source
        and PurePosixPath(donor_source).suffix.casefold()
        in {".c", ".cc", ".cpp", ".cxx"},
        f"{context}: donor source is not a different translation unit",
    )
    require(isinstance(donor_effective, bytes) and donor_effective,
            f"{context}: effective donor source is empty")
    require(isinstance(forward_generated, bytes) and forward_generated,
            f"{context}: generated forward run is empty")
    require(
        sha256_bytes(donor_effective)
        == require_sha(
            recipe.get("donor_effective_source_sha256"),
            f"{context}.donor_effective_source_sha256",
        ),
        f"{context}: effective donor source differs from its pin",
    )
    if recipe.get("placement") == "prefix":
        rendered = forward_generated + donor_effective
    else:
        require(recipe.get("placement") == "suffix",
                f"{context}: cross-TU complete-target placement differs")
        rendered = b"\n".join(
            donor_effective.split(b"\n")
            + forward_generated.rstrip(b"\n").split(b"\n")
        )
    require(
        sha256_bytes(rendered)
        == require_sha(recipe.get("rendered_source_sha256"),
                       f"{context}.rendered_source_sha256")
        and require_exact_int(
            recipe.get("rendered_source_size"),
            f"{context}.rendered_source_size", minimum=1,
        ) == len(rendered)
        and require_exact_int(
            recipe.get("rendered_source_line_count"),
            f"{context}.rendered_source_line_count", minimum=1,
        ) == rendered.count(b"\n"),
        f"{context}: rendered cross-TU donor source differs from its pins",
    )
    return rendered


def require_clean_current_source_cross_tu_bindings(
    recipe_kinds: dict[str, object],
    primary_donor_ids: list[str],
    instruction_donor_ids: list[str],
    context: str,
) -> None:
    """Confine clean cross-TU donors to one instruction-only consumer."""
    clean_ids = {
        recipe_id for recipe_id, kind in recipe_kinds.items()
        if kind == CLEAN_CURRENT_SOURCE_CROSS_TU_RECIPE
    }
    primary_uses = clean_ids.intersection(primary_donor_ids)
    require(
        not primary_uses,
        f"{context}: clean current-source cross-TU recipes may be used only "
        f"as hybrid instruction donors, not primary donors: "
        f"{sorted(primary_uses)}",
    )
    instruction_counts = Counter(instruction_donor_ids)
    require(
        set(instruction_counts) == clean_ids
        and all(count == 1 for count in instruction_counts.values()),
        f"{context}: every clean current-source cross-TU recipe must be "
        "consumed exactly once as a hybrid instruction donor",
    )


def require_cross_tu_instruction_source_bindings(
    recipe_ids: set[str],
    primary_donor_ids: list[str],
    non_primary_donor_ids: list[str],
    bound_instruction_donor_ids: list[str],
    context: str,
) -> None:
    """Confine each overlaid sibling to one instruction-donor consumer.

    The role exists to supply pinned instruction bytes and nothing else.
    These donors are never primary/link candidates, may not be a whole-body
    (complete-target) source, and may not hold a second non-primary role.
    """
    protected = set(recipe_ids)
    primary_counts = Counter(primary_donor_ids)
    non_primary_counts = Counter(non_primary_donor_ids)
    bound_counts = Counter(bound_instruction_donor_ids)
    require(
        set(bound_counts) == protected
        and all(count == 1 for count in bound_counts.values()),
        f"{context}: every overlaid cross-TU instruction source must be "
        "consumed exactly once as a hybrid instruction donor",
    )
    require(
        all(primary_counts[recipe_id] == 0 for recipe_id in protected),
        f"{context}: overlaid cross-TU instruction sources may not be "
        "primary donors",
    )
    require(
        all(non_primary_counts[recipe_id] == bound_counts[recipe_id]
            for recipe_id in protected),
        f"{context}: overlaid cross-TU instruction sources may not have "
        "another non-primary role",
    )


def require_cross_tu_complete_target_bindings(
    recipe_ids: set[str],
    primary_donor_ids: list[str],
    non_primary_donor_ids: list[str],
    bound_complete_donor_ids: list[str],
    context: str,
) -> None:
    """Confine each cross-TU carrier to one whole-target consumer.

    These donors are never primary/link candidates and may not feed any
    instruction, variant, or source-mosaic role.  Their sole admissible use
    is as the complete body/ordinary-closure source for the narrow cross-TU
    resize class.
    """
    protected = set(recipe_ids)
    primary_counts = Counter(primary_donor_ids)
    non_primary_counts = Counter(non_primary_donor_ids)
    bound_counts = Counter(bound_complete_donor_ids)
    require(
        set(bound_counts) == protected
        and all(count == 1 for count in bound_counts.values()),
        f"{context}: every cross-TU complete-target donor must be bound "
        "exactly once",
    )
    require(
        all(primary_counts[recipe_id] == 0 for recipe_id in protected),
        f"{context}: cross-TU complete-target donors may not be primary",
    )
    require(
        all(non_primary_counts[recipe_id] == bound_counts[recipe_id]
            for recipe_id in protected),
        f"{context}: cross-TU complete-target donors may not have another "
        "non-primary role",
    )


def require_same_tu_hybrid_carrier_bindings(
    carrier_recipe_ids: set[str],
    primary_donor_ids: list[str],
    non_primary_donor_ids: list[str],
    bound_target_donor_ids: list[str],
    bound_instruction_donor_ids: list[str],
    context: str,
) -> None:
    """Confine each mixed carrier to one role in one same-TU hybrid."""
    carrier_ids = set(carrier_recipe_ids)
    primary_counts = Counter(primary_donor_ids)
    non_primary_counts = Counter(non_primary_donor_ids)
    target_counts = Counter(bound_target_donor_ids)
    instruction_counts = Counter(bound_instruction_donor_ids)
    require(
        set(target_counts) | set(instruction_counts) == carrier_ids
        and all(
            target_counts[recipe_id] + instruction_counts[recipe_id] == 1
            for recipe_id in carrier_ids
        ),
        f"{context}: every same-TU hybrid carrier must be bound exactly "
        "once as either its target or instruction donor",
    )
    require(
        all(primary_counts[recipe_id] == target_counts[recipe_id]
            for recipe_id in carrier_ids),
        f"{context}: same-TU target carriers may not have an ordinary, "
        "repeated, or instruction-only primary use",
    )
    require(
        all(non_primary_counts[recipe_id] == instruction_counts[recipe_id]
            for recipe_id in carrier_ids),
        f"{context}: same-TU instruction carriers may not have a variant, "
        "repeated, or other non-primary use",
    )


def require_stacked_carrier_hybrid_bindings(
    bound_donor_ids: list[str],
    primary_donor_ids: list[str],
    non_primary_donor_ids: list[str],
    context: str,
) -> None:
    """Confine every stacked carrier bound to a same-TU hybrid to that role.

    Unlike the mixed declaration carrier, this recipe kind is also an
    ordinary equal-body donor, so the census cannot demand that *every*
    stacked carrier be bound.  What it does demand is the same
    no-reuse property for the ones that are: a carrier that donates a body
    or an instruction to a same-TU hybrid may hold no other role anywhere
    in its translation unit.
    """
    bound_counts = Counter(bound_donor_ids)
    require(all(count == 1 for count in bound_counts.values()),
            f"{context}: a stacked carrier may fill only one same-TU "
            "hybrid role")
    primary_counts = Counter(primary_donor_ids)
    non_primary_counts = Counter(non_primary_donor_ids)
    for recipe_id in bound_counts:
        require(
            primary_counts[recipe_id] + non_primary_counts[recipe_id] == 1,
            f"{context}: same-TU hybrid stacked carrier {recipe_id} has an "
            "ordinary, repeated, or other non-primary use",
        )


def require_ordinary_fpo_mosaic_donor_bindings(
    recipe_ids: set[str],
    primary_donor_ids: list[str],
    non_primary_donor_ids: list[str],
    bound_donor_ids: list[str],
    context: str,
) -> None:
    """Confine each ordinary FPO carrier to one authenticated mosaic use."""
    protected_ids = set(recipe_ids)
    primary_counts = Counter(primary_donor_ids)
    non_primary_counts = Counter(non_primary_donor_ids)
    bound_counts = Counter(bound_donor_ids)
    require(
        set(bound_counts) == protected_ids
        and all(count == 1 for count in bound_counts.values()),
        f"{context}: every ordinary FPO mosaic donor must be bound exactly "
        "once to its authenticated FPO composer",
    )
    require(
        all(primary_counts[recipe_id] == 1 for recipe_id in protected_ids),
        f"{context}: ordinary FPO mosaic donors may not have an ordinary or "
        "repeated primary use",
    )
    require(
        all(non_primary_counts[recipe_id] == 0 for recipe_id in protected_ids),
        f"{context}: ordinary FPO mosaic donors may not have an instruction, "
        "variant, or other non-primary use",
    )


def require_ordinary_fpo_self_permutation_donor_bindings(
    recipe_ids: set[str],
    primary_donor_ids: list[str],
    non_primary_donor_ids: list[str],
    bound_donor_ids: list[str],
    context: str,
) -> None:
    """Confine each self-permutation carrier to one exact FPO composer."""
    protected_ids = set(recipe_ids)
    primary_counts = Counter(primary_donor_ids)
    non_primary_counts = Counter(non_primary_donor_ids)
    bound_counts = Counter(bound_donor_ids)
    require(
        set(bound_counts) == protected_ids
        and all(count == 1 for count in bound_counts.values()),
        f"{context}: every FPO self-permutation donor must be bound exactly "
        "once to its authenticated composer",
    )
    require(
        all(primary_counts[recipe_id] == 1 for recipe_id in protected_ids),
        f"{context}: FPO self-permutation donors may not have an ordinary "
        "or repeated primary use",
    )
    require(
        all(non_primary_counts[recipe_id] == 0 for recipe_id in protected_ids),
        f"{context}: FPO self-permutation donors may not have an instruction, "
        "variant, source, or other non-primary use",
    )


def require_instruction_hybrid_resize_span(
    seed_length: int,
    donor_length: int,
    linked_span: int,
    *, donor_governed: bool,
    context: str,
) -> None:
    """Prove the declared linked contribution span for one hybrid resize."""
    require(
        all(type(value) is int and value > 0 for value in (
            seed_length, donor_length, linked_span))
        and type(donor_governed) is bool,
        f"{context}: hybrid resize lengths are invalid",
    )
    require(
        linked_span % 16 == 0
        and ((donor_length + 15) // 16) * 16 == linked_span
        and (
            seed_length <= linked_span if donor_governed else
            ((seed_length + 15) // 16) * 16 == linked_span
        )
        and seed_length != donor_length,
        f"{context}: hybrid resize spans differ",
    )


def require_source_refactor_donor_bindings(
    refactor_recipe_ids: set[str],
    primary_donor_ids: list[str],
    bound_refactor_recipe_ids: list[str],
    non_primary_donor_ids: list[str],
    context: str,
    bound_instruction_refactor_recipe_ids: list[str] | None = None,
) -> None:
    """Confine each source rendering to exactly one authenticated role."""
    refactor_ids = set(refactor_recipe_ids)
    primary_counts = Counter(primary_donor_ids)
    primary_bound_counts = Counter(bound_refactor_recipe_ids)
    instruction_bound_counts = Counter(
        bound_instruction_refactor_recipe_ids or [])
    non_primary_counts = Counter(non_primary_donor_ids)
    require(
        set(primary_bound_counts) | set(instruction_bound_counts)
        == refactor_ids
        and all(
            primary_bound_counts[recipe_id]
            + instruction_bound_counts[recipe_id] == 1
            for recipe_id in refactor_ids
        ),
        f"{context}: every source-permutation donor must be bound exactly "
        "once to its authenticated source-aware composer",
    )
    require(
        all(primary_counts[recipe_id]
            == primary_bound_counts[recipe_id]
            for recipe_id in refactor_ids),
        f"{context}: every primary source-permutation donor must have "
        "exactly one total primary donor use and no unbound primary reuse",
    )
    require(
        all(non_primary_counts[recipe_id]
            == instruction_bound_counts[recipe_id]
            for recipe_id in refactor_ids),
        f"{context}: source-permutation donors may not appear in unbound "
        "instruction, variant, or other non-primary roles",
    )


def raw_manifest_source_refactor_recipe_ids(
    manifest: dict, context: str,
) -> set[str]:
    """Inventory typed source permutations before any host-dependent gate."""
    result = set()
    units = manifest.get("translation_units")
    if not isinstance(units, list):
        return result
    for unit_index, unit in enumerate(units):
        if not isinstance(unit, dict):
            continue
        donors = unit.get("donors")
        if not isinstance(donors, list):
            continue
        for donor_index, donor in enumerate(donors):
            if not isinstance(donor, dict):
                continue
            recipe = donor.get("recipe")
            if (not isinstance(recipe, dict)
                    or recipe.get("kind") != "donor_source_overlay"):
                continue
            recipe_id = donor.get("id")
            require(isinstance(recipe_id, str),
                    f"{context}: source-permutation donor id is invalid")
            renderings = recipe.get("renderings")
            if not isinstance(renderings, list):
                continue
            for rendering_index, rendering in enumerate(renderings):
                if not isinstance(rendering, dict):
                    continue
                operations = rendering.get("operations")
                if not isinstance(operations, list):
                    continue
                for operation_index, operation in enumerate(operations):
                    if not isinstance(operation, dict) \
                            or "gen" not in operation:
                        continue
                    generator = validate_source_overlay_generator(
                        operation["gen"],
                        f"{context} translation_units[{unit_index}]"
                        f".donors[{donor_index}].recipe.renderings"
                        f"[{rendering_index}].operations"
                        f"[{operation_index}].gen",
                    )
                    if any(
                        source_overlay_generator_is_source_refactor(item)
                        for item in _source_overlay_generators(generator)
                    ):
                        result.add(recipe_id)
    return result


def raw_manifest_recipe_kinds(manifest: dict) -> dict:
    """Map every donor id to its recipe kind before host-dependent gates."""
    kinds = {}
    units = manifest.get("translation_units")
    if not isinstance(units, list):
        return kinds
    for unit in units:
        if not isinstance(unit, dict):
            continue
        donors = unit.get("donors")
        if not isinstance(donors, list):
            continue
        for donor in donors:
            if not isinstance(donor, dict):
                continue
            recipe = donor.get("recipe")
            recipe_id = donor.get("id")
            if isinstance(recipe, dict) and isinstance(recipe_id, str):
                kinds[recipe_id] = recipe.get("kind")
    return kinds


