def require_manifest_source_refactor_role_preflight(
    manifest: dict, context: str, root=None,
) -> None:
    """Reject source-aware role and semantic escapes before host checks."""
    primary_donor_ids = []
    bound_refactor_recipe_ids = []
    bound_instruction_refactor_recipe_ids = []
    non_primary_donor_ids = []
    bound_same_tu_target_donor_ids = []
    bound_same_tu_instruction_donor_ids = []
    bound_stacked_carrier_donor_ids = []
    bound_ordinary_fpo_mosaic_donor_ids = []
    bound_ordinary_fpo_self_permutation_donor_ids = []
    bound_cross_tu_complete_target_donor_ids = []
    bound_cross_tu_instruction_source_donor_ids = []
    manifest_recipe_kinds = raw_manifest_recipe_kinds(manifest)
    manifest_role_policies = raw_manifest_recipe_role_policies(manifest)
    overlay = manifest.get("source_overlay")
    overlay_outputs = (
        overlay.get("outputs") if isinstance(overlay, dict) else None
    )
    if not isinstance(overlay_outputs, list):
        overlay_outputs = []
    overlaid_paths = {
        item["path"] for item in overlay_outputs
        if isinstance(item, dict) and isinstance(item.get("path"), str)
    }
    source_root = Path(root).resolve(strict=True) if root is not None else None
    refactor_recipe_ids = raw_manifest_source_refactor_recipe_ids(
        manifest, context)
    same_tu_carrier_recipe_ids = raw_manifest_same_tu_carrier_recipe_ids(
        manifest)
    ordinary_fpo_mosaic_recipe_ids = (
        raw_manifest_ordinary_fpo_mosaic_recipe_ids(manifest)
    )
    ordinary_fpo_self_permutation_recipe_ids = (
        raw_manifest_ordinary_fpo_self_permutation_recipe_ids(manifest)
    )
    cross_tu_complete_target_recipe_ids = (
        raw_manifest_cross_tu_complete_target_recipe_ids(manifest)
    )
    cross_tu_instruction_source_recipe_ids = (
        raw_manifest_cross_tu_instruction_source_recipe_ids(manifest)
    )
    units = manifest.get("translation_units")
    if not isinstance(units, list):
        return
    for unit in units:
        if not isinstance(unit, dict):
            continue
        functions = unit.get("functions")
        if not isinstance(functions, list):
            continue
        for function in functions:
            if not isinstance(function, dict):
                continue
            proof = function.get("target_source_refactor")
            if (isinstance(proof, dict)
                    and proof.get("kind")
                    == "fixed_array_shuffle_pointer_countdown_v1"):
                require(
                    function.get("splice_class") in {
                        "retail_exact_instruction_mosaic",
                        RETAIL_EXACT_SOURCE_EQUAL_BODY_CLASS,
                    }
                    and isinstance(function.get("source_fpo_identity"), dict)
                    and "ordinary_fpo_identity" not in function,
                    f"{context}: fixed-array shuffle is restricted to its "
                    "isolated source FPO body composer",
                )
                witness = validate_fixed_array_shuffle_semantic_witness(
                    proof.get("semantic_witness"),
                    context + " fixed-array shuffle semantic witness",
                )
                witness_paths = {
                    witness[name]["path"]
                    for name in ("owner_header", "base_header", "types_header")
                }
                require(not witness_paths.intersection(overlaid_paths),
                        f"{context}: fixed-array shuffle semantic witness "
                        "header has an effective source overlay")
            if (isinstance(proof, dict)
                    and proof.get("kind")
                    == "inclusive_extent_assignment_v1"):
                witness = validate_inclusive_extent_semantic_witness(
                    proof.get("semantic_witness"),
                    context + " inclusive-extent semantic witness",
                )
                witness_paths = {
                    witness[name]["path"]
                    for name in (
                        "source_owner_header", "source_accessor_header",
                        "extent_header",
                    )
                }
                require(not witness_paths.intersection(overlaid_paths),
                        f"{context}: inclusive-extent semantic witness "
                        "header has an effective source overlay")
                if source_root is not None:
                    _, extent_data = _read_pinned_semantic_source(
                        source_root, witness["extent_header"],
                        context + " inclusive-extent extent header",
                    )
                    require_inclusive_extent_concrete_class_identity(
                        extent_data, witness,
                        context + " inclusive-extent concrete class",
                    )
            instruction_proof = function.get(
                "instruction_donor_source_refactor")
            if isinstance(instruction_proof, dict):
                normalized_instruction_proof = (
                    validate_target_source_refactor_proof(
                        instruction_proof,
                        context + " instruction-donor source refactor",
                    )
                )
                require(
                    normalized_instruction_proof["kind"]
                    == "discarded_postfix_increment_v1",
                    f"{context}: instruction-donor source-refactor kind "
                    "differs",
                )
                witness = normalized_instruction_proof["semantic_witness"]
                witness_paths = {witness["source_alias_header"]["path"]}
                for edge in witness["source_include_chain"]:
                    witness_paths.update({
                        edge["including_path"], edge["included_path"],
                    })
                require(not witness_paths.intersection(overlaid_paths),
                        f"{context}: discarded-increment semantic witness "
                        "header has an effective source overlay")
            donor_id = function.get("donor")
            if isinstance(donor_id, str):
                primary_donor_ids.append(donor_id)
                if "target_source_refactor" in function:
                    bound_refactor_recipe_ids.append(donor_id)
                if (function.get("splice_class")
                        == SAME_TU_INSTRUCTION_HYBRID_RESIZE_CLASS):
                    if (manifest_recipe_kinds.get(donor_id)
                            == SAME_TU_DECLARATION_CARRIER_RECIPE):
                        bound_same_tu_target_donor_ids.append(donor_id)
                    else:
                        bound_stacked_carrier_donor_ids.append(donor_id)
                if ("ordinary_fpo_identity" in function
                        and "instruction_self_permutation" not in function):
                    bound_ordinary_fpo_mosaic_donor_ids.append(donor_id)
                if "instruction_self_permutation" in function:
                    require(
                        function.get("splice_class")
                        == "retail_exact_instruction_mosaic"
                        and "source_fpo_identity" not in function
                        and "target_source_refactor" not in function,
                        f"{context}: instruction self-permutation is "
                        "restricted to a source-authentic instruction "
                        "mosaic",
                    )
                    require(
                        manifest_role_policies.get(donor_id)
                        == (ORDINARY_FPO_SELF_PERMUTATION_ROLE_POLICY
                            if isinstance(
                                function.get("ordinary_fpo_identity"), dict)
                            else EH_CLOSURE_SELF_PERMUTATION_ROLE_POLICY),
                        f"{context}: instruction self-permutation carrier "
                        "role policy does not match its closure class",
                    )
                    bound_ordinary_fpo_self_permutation_donor_ids.append(
                        donor_id)
            instruction_donor = function.get("instruction_donor")
            if isinstance(instruction_donor, str):
                non_primary_donor_ids.append(instruction_donor)
                if (manifest_role_policies.get(instruction_donor)
                        == CROSS_TU_INSTRUCTION_SOURCE_RECIPE_POLICY):
                    require(
                        function.get("splice_class")
                        == CROSS_TU_INSTRUCTION_HYBRID_RESIZE_CLASS,
                        f"{context}: an overlaid cross-TU instruction source "
                        "may supply only cross-TU hybrid instruction bytes",
                    )
                    bound_cross_tu_instruction_source_donor_ids.append(
                        instruction_donor)
                if "instruction_donor_source_refactor" in function:
                    bound_instruction_refactor_recipe_ids.append(
                        instruction_donor)
                if (function.get("splice_class")
                        == SAME_TU_INSTRUCTION_HYBRID_RESIZE_CLASS):
                    if (manifest_recipe_kinds.get(instruction_donor)
                            == SAME_TU_DECLARATION_CARRIER_RECIPE):
                        bound_same_tu_instruction_donor_ids.append(
                            instruction_donor)
                    else:
                        bound_stacked_carrier_donor_ids.append(
                            instruction_donor)
            complete_donor = function.get("complete_donor")
            if isinstance(complete_donor, str):
                non_primary_donor_ids.append(complete_donor)
                if (function.get("splice_class")
                        == CROSS_TU_COMPLETE_TARGET_RESIZE_CLASS):
                    bound_cross_tu_complete_target_donor_ids.append(
                        complete_donor)
            variants = function.get("donor_variants")
            if isinstance(variants, list):
                non_primary_donor_ids.extend(
                    item["donor"] for item in variants
                    if isinstance(item, dict)
                    and isinstance(item.get("donor"), str)
                )
    require_source_refactor_donor_bindings(
        refactor_recipe_ids,
        primary_donor_ids,
        bound_refactor_recipe_ids,
        non_primary_donor_ids,
        context,
        bound_instruction_refactor_recipe_ids,
    )
    require_same_tu_hybrid_carrier_bindings(
        same_tu_carrier_recipe_ids,
        primary_donor_ids,
        non_primary_donor_ids,
        bound_same_tu_target_donor_ids,
        bound_same_tu_instruction_donor_ids,
        context,
    )
    require_stacked_carrier_hybrid_bindings(
        bound_stacked_carrier_donor_ids,
        primary_donor_ids,
        non_primary_donor_ids,
        context,
    )
    require_ordinary_fpo_mosaic_donor_bindings(
        ordinary_fpo_mosaic_recipe_ids,
        primary_donor_ids,
        non_primary_donor_ids,
        bound_ordinary_fpo_mosaic_donor_ids,
        context,
    )
    require_ordinary_fpo_self_permutation_donor_bindings(
        ordinary_fpo_self_permutation_recipe_ids,
        primary_donor_ids,
        non_primary_donor_ids,
        bound_ordinary_fpo_self_permutation_donor_ids,
        context,
    )
    require_cross_tu_complete_target_bindings(
        cross_tu_complete_target_recipe_ids,
        primary_donor_ids,
        non_primary_donor_ids,
        bound_cross_tu_complete_target_donor_ids,
        context,
    )
    require_cross_tu_instruction_source_bindings(
        cross_tu_instruction_source_recipe_ids,
        primary_donor_ids,
        non_primary_donor_ids,
        bound_cross_tu_instruction_source_donor_ids,
        context,
    )


def require_target_bound_retail_image(
    images: object,
    target: str,
    retail_image: object,
    context: str,
) -> str:
    """Bind an oracle filename to the unique image for its TU target."""
    require(isinstance(images, dict), f"{context}: images must be an object")
    matches = [
        image for image in images.values()
        if isinstance(image, dict) and image.get("target") == target
    ]
    require(len(matches) == 1,
            f"{context}: target must select exactly one retail image")
    original = matches[0].get("original")
    require(isinstance(original, str) and original,
            f"{context}: target retail image original is invalid")
    expected = PurePosixPath(original).name
    require(retail_image == expected,
            f"{context}: retail oracle image differs from the TU target")
    return expected


_IA32_PREFIXES = {0x26, 0x2E, 0x36, 0x3E, 0x64, 0x65, 0x66, 0xF0, 0xF2, 0xF3}

# One-byte opcode map (flat 32-bit code segment).  Each entry is a tuple of
# operand tokens: M = ModRM (with SIB/displacement), Ib/Iw/Iz = immediates
# (z = 4 bytes, 2 under an operand-size prefix), Jb/Jz = relative branches,
# Ov = 32-bit moffs, Ap = far pointer.  Absent opcodes (prefixes, the 0F
# escape and undefined slots) are refused.
def _ia32_one_byte_table() -> dict:
    table = {}
    for base in range(0x00, 0x40, 8):
        if base in (0x00, 0x08, 0x10, 0x18, 0x20, 0x28, 0x30, 0x38):
            table[base] = ("M",)
            table[base + 1] = ("M",)
            table[base + 2] = ("M",)
            table[base + 3] = ("M",)
            table[base + 4] = ("Ib",)
            table[base + 5] = ("Iz",)
    for opcode in (0x06, 0x07, 0x0E, 0x16, 0x17, 0x1E, 0x1F,
                   0x27, 0x2F, 0x37, 0x3F):
        table[opcode] = ()
    for opcode in range(0x40, 0x62):
        table[opcode] = ()
    table[0x62] = ("M",)
    table[0x63] = ("M",)
    table[0x68] = ("Iz",)
    table[0x69] = ("M", "Iz")
    table[0x6A] = ("Ib",)
    table[0x6B] = ("M", "Ib")
    for opcode in range(0x6C, 0x70):
        table[opcode] = ()
    for opcode in range(0x70, 0x80):
        table[opcode] = ("Jb",)
    table[0x80] = ("M", "Ib")
    table[0x81] = ("M", "Iz")
    table[0x82] = ("M", "Ib")
    table[0x83] = ("M", "Ib")
    for opcode in range(0x84, 0x90):
        table[opcode] = ("M",)
    for opcode in range(0x90, 0x9A):
        table[opcode] = ()
    table[0x9A] = ("Ap",)
    for opcode in range(0x9B, 0xA0):
        table[opcode] = ()
    for opcode in range(0xA0, 0xA4):
        table[opcode] = ("Ov",)
    for opcode in range(0xA4, 0xA8):
        table[opcode] = ()
    table[0xA8] = ("Ib",)
    table[0xA9] = ("Iz",)
    for opcode in range(0xAA, 0xB0):
        table[opcode] = ()
    for opcode in range(0xB0, 0xB8):
        table[opcode] = ("Ib",)
    for opcode in range(0xB8, 0xC0):
        table[opcode] = ("Iz",)
    table[0xC0] = ("M", "Ib")
    table[0xC1] = ("M", "Ib")
    table[0xC2] = ("Iw",)
    table[0xC3] = ()
    table[0xC4] = ("M",)
    table[0xC5] = ("M",)
    table[0xC6] = ("M", "Ib")
    table[0xC7] = ("M", "Iz")
    table[0xC8] = ("Iw", "Ib")
    table[0xC9] = ()
    table[0xCA] = ("Iw",)
    table[0xCB] = ()
    table[0xCC] = ()
    table[0xCD] = ("Ib",)
    table[0xCE] = ()
    table[0xCF] = ()
    for opcode in range(0xD0, 0xD4):
        table[opcode] = ("M",)
    table[0xD4] = ("Ib",)
    table[0xD5] = ("Ib",)
    table[0xD7] = ()
    for opcode in range(0xD8, 0xE0):
        table[opcode] = ("M",)
    for opcode in range(0xE0, 0xE4):
        table[opcode] = ("Jb",)
    for opcode in range(0xE4, 0xE8):
        table[opcode] = ("Ib",)
    table[0xE8] = ("Jz",)
    table[0xE9] = ("Jz",)
    table[0xEA] = ("Ap",)
    table[0xEB] = ("Jb",)
    for opcode in range(0xEC, 0xF0):
        table[opcode] = ()
    table[0xF4] = ()
    table[0xF5] = ()
    table[0xF6] = ("M", "F6")
    table[0xF7] = ("M", "F7")
    for opcode in range(0xF8, 0xFE):
        table[opcode] = ()
    table[0xFE] = ("M",)
    table[0xFF] = ("M",)
    return table


def _ia32_two_byte_table() -> dict:
    table = {}
    for opcode in (0x00, 0x01, 0x02, 0x03, 0x0D, 0x18, 0x1F):
        table[opcode] = ("M",)
    for opcode in (0x06, 0x08, 0x09, 0x0B, 0x30, 0x31, 0x32, 0x33,
                   0x77, 0xA0, 0xA1, 0xA2, 0xA8, 0xA9, 0xAA):
        table[opcode] = ()
    for opcode in range(0x10, 0x18):
        table[opcode] = ("M",)
    for opcode in range(0x20, 0x24):
        table[opcode] = ("M",)
    for opcode in range(0x28, 0x30):
        table[opcode] = ("M",)
    for opcode in range(0x40, 0x50):
        table[opcode] = ("M",)
    for opcode in range(0x50, 0x70):
        table[opcode] = ("M",)
    table[0x70] = ("M", "Ib")
    table[0x71] = ("M", "Ib")
    table[0x72] = ("M", "Ib")
    table[0x73] = ("M", "Ib")
    for opcode in range(0x74, 0x77):
        table[opcode] = ("M",)
    table[0x7E] = ("M",)
    table[0x7F] = ("M",)
    for opcode in range(0x80, 0x90):
        table[opcode] = ("Jz",)
    for opcode in range(0x90, 0xA0):
        table[opcode] = ("M",)
    table[0xA3] = ("M",)
    table[0xA4] = ("M", "Ib")
    table[0xA5] = ("M",)
    table[0xAB] = ("M",)
    table[0xAC] = ("M", "Ib")
    table[0xAD] = ("M",)
    table[0xAE] = ("M",)
    table[0xAF] = ("M",)
    for opcode in range(0xB0, 0xB8):
        table[opcode] = ("M",)
    table[0xB9] = ("M",)
    table[0xBA] = ("M", "Ib")
    for opcode in range(0xBB, 0xC2):
        table[opcode] = ("M",)
    table[0xC2] = ("M", "Ib")
    table[0xC3] = ("M",)
    table[0xC4] = ("M", "Ib")
    table[0xC5] = ("M", "Ib")
    table[0xC6] = ("M", "Ib")
    table[0xC7] = ("M",)
    for opcode in range(0xC8, 0xD0):
        table[opcode] = ()
    for opcode in range(0xD0, 0x100):
        table[opcode] = ("M",)
    return table


IA32_ONE_BYTE_OPCODES = _ia32_one_byte_table()
IA32_TWO_BYTE_OPCODES = _ia32_two_byte_table()


def supported_ia32_instruction_length(
    encoded: bytes, context: str,
) -> int:
    """Decode the length of one flat 32-bit IA-32 instruction.

    This is a fail-closed length decoder, not a disassembler: it knows the
    legacy prefixes, the complete one-byte opcode map and the two-byte 0F map
    of the 32-bit code the 1997 compiler emits, and derives ModRM, SIB,
    displacement and immediate widths from the bytes.  Repeated or address-
    size prefixes, undefined opcode slots, three-byte escapes and truncated
    encodings fail.  Every accepted length is cross-checked against an
    independent disassembler by the boundary-regression tests.
    """
    require(isinstance(encoded, bytes) and encoded,
            f"{context}: instruction encoding is missing")
    cursor = 0
    operand_size_16 = False
    seen_prefixes = set()
    while cursor < len(encoded) and encoded[cursor] in _IA32_PREFIXES:
        prefix = encoded[cursor]
        require(prefix not in seen_prefixes,
                f"{context}: unsupported repeated instruction prefix")
        seen_prefixes.add(prefix)
        if prefix == 0x66:
            operand_size_16 = True
        cursor += 1
    require(cursor < len(encoded),
            f"{context}: unsupported or truncated instruction prefix")
    require(cursor <= 4, f"{context}: unsupported instruction prefix run")
    opcode = encoded[cursor]
    cursor += 1
    if opcode == 0x0F:
        require(cursor < len(encoded),
                f"{context}: unsupported or truncated two-byte IA-32 opcode")
        opcode = encoded[cursor]
        cursor += 1
        operands = IA32_TWO_BYTE_OPCODES.get(opcode)
        require(operands is not None,
                f"{context}: unsupported two-byte IA-32 opcode")
    else:
        operands = IA32_ONE_BYTE_OPCODES.get(opcode)
        require(operands is not None,
                f"{context}: unsupported IA-32 instruction opcode")
    for token in operands:
        if token == "M":
            require(cursor < len(encoded),
                    f"{context}: IA-32 instruction lacks ModRM")
            modrm = encoded[cursor]
            cursor += 1
            mode = modrm >> 6
            rm = modrm & 7
            if mode != 3 and rm == 4:
                require(cursor < len(encoded),
                        f"{context}: IA-32 instruction lacks SIB")
                sib = encoded[cursor]
                cursor += 1
                if mode == 0 and (sib & 7) == 5:
                    cursor += 4
            elif mode == 0 and rm == 5:
                cursor += 4
            if mode == 1:
                cursor += 1
            elif mode == 2:
                cursor += 4
        elif token in ("F6", "F7"):
            # group 3: TEST carries an immediate, the other members do not
            if (modrm >> 3) & 7 in (0, 1):
                cursor += 1 if token == "F6" else (2 if operand_size_16 else 4)
        elif token in ("Ib", "Jb"):
            cursor += 1
        elif token == "Iw":
            cursor += 2
        elif token in ("Iz", "Jz"):
            cursor += 2 if operand_size_16 else 4
        elif token == "Ov":
            cursor += 4
        elif token == "Ap":
            cursor += 6
        else:  # pragma: no cover - table integrity
            raise ByteIdentityError(f"{context}: decoder table error")
    require(cursor <= len(encoded),
            f"{context}: supported IA-32 instruction is truncated")
    require(cursor <= 15, f"{context}: IA-32 instruction exceeds 15 bytes")
    return cursor


def require_supported_complete_ia32_instruction(
    encoded: bytes, context: str,
) -> int:
    """Require that an isolated range is exactly one supported instruction."""
    length = supported_ia32_instruction_length(encoded, context)
    require(length == len(encoded),
            f"{context}: encoding is not one complete supported IA-32 "
            "instruction")
    return length


def require_coff_line_certified_ia32_boundaries(
    coff, section: dict, body: bytes, ranges: list[dict], role: str,
    mangled: str, context: str,
) -> int:
    """Decode from the nearest compiler COFF line boundary through each span."""
    require(role in {"target", "instruction_donor", "seed", "donor"},
            f"{context}: IA-32 range role differs")
    line_bytes = _coff_table_bytes(coff, section, "lines")
    require(len(line_bytes) == section["line_count"] * 6
            and len(line_bytes) >= 12,
            f"{context}: compiler line-boundary certificate is missing")
    marker_index, marker_line = coff_unpack(
        "<IH", line_bytes, 0, context + " line sentinel")
    function_index, _ = function_symbol(
        coff, mangled, section["number"])
    require(marker_line == 0 and marker_index == function_index,
            f"{context}: compiler line sentinel differs")
    line_offsets = []
    previous = -1
    for index in range(1, section["line_count"]):
        offset, line = coff_unpack(
            "<IH", line_bytes, index * 6,
            f"{context} line row {index}")
        require(line != 0 and previous <= offset < len(body),
                f"{context}: compiler line boundary is invalid")
        previous = offset
        line_offsets.append(offset)
    require(line_offsets, f"{context}: compiler line boundaries are absent")
    prefixed = role in {"target", "instruction_donor"}
    prefix = role if prefixed else ""
    decoded_count = 0
    for index, item in enumerate(ranges):
        start = item[f"{prefix}_start"] if prefixed else item["start"]
        end = item[f"{prefix}_end"] if prefixed else item["end"]
        anchors = [offset for offset in line_offsets if offset <= start]
        require(anchors,
                f"{context}: range {index} has no preceding compiler line "
                "boundary")
        cursor = max(anchors)
        boundaries = {cursor}
        in_range_lengths = []
        while cursor < end:
            instruction_start = cursor
            length = supported_ia32_instruction_length(
                body[cursor:], f"{context} range {index} at {cursor}")
            cursor += length
            require(cursor <= len(body),
                    f"{context}: decoded instruction escapes the COMDAT")
            boundaries.add(cursor)
            if start <= instruction_start and cursor <= end:
                in_range_lengths.append(length)
            decoded_count += 1
        require(start in boundaries and end in boundaries,
                f"{context}: range {index} is not one containing-stream "
                "IA-32 instruction boundary")
        lengths_key = f"{role}_instruction_lengths"
        if lengths_key in item:
            require(
                in_range_lengths == item[lengths_key],
                f"{context}: range {index} decoded instruction partition "
                f"differs from {lengths_key}",
            )
    return decoded_count


def validate_cross_tu_instruction_hybrid_ranges(
    value: object,
    context: str,
    target_body_length: int,
    instruction_donor_body_length: int,
    *,
    range_kind: str = "cross_tu_same_mangled_complete_x86_instruction_v1",
    require_same_offsets: bool = False,
) -> list[dict]:
    """Pin equal-width supported instructions at independent COMDAT offsets.

    Literal bytes and hashes bind both compiler outputs.  The live composer
    separately decodes from compiler-emitted line-row boundaries through
    every range endpoint, then proves no relocation operand is intersected.
    """
    require(isinstance(value, list) and 1 <= len(value) <= 64,
            f"{context} must contain 1..64 instruction ranges")
    normalized = []
    previous_target_end = 0
    previous_source_end = 0
    for index, item in enumerate(value):
        item_context = f"{context}[{index}]"
        require(isinstance(item, dict), f"{item_context} must be an object")
        exact_audit_keys(item, CROSS_TU_INSTRUCTION_HYBRID_RANGE_KEYS,
                         item_context)
        require(item.get("kind") == range_kind,
                f"{item_context}.kind differs")
        target_start = require_exact_int(
            item.get("target_start"), item_context + ".target_start",
            minimum=0, maximum=target_body_length - 1,
        )
        target_end = require_exact_int(
            item.get("target_end"), item_context + ".target_end",
            minimum=1, maximum=target_body_length,
        )
        source_start = require_exact_int(
            item.get("instruction_donor_start"),
            item_context + ".instruction_donor_start",
            minimum=0, maximum=instruction_donor_body_length - 1,
        )
        source_end = require_exact_int(
            item.get("instruction_donor_end"),
            item_context + ".instruction_donor_end",
            minimum=1, maximum=instruction_donor_body_length,
        )
        target_width = target_end - target_start
        source_width = source_end - source_start
        require(1 <= target_width == source_width <= 15,
                f"{item_context} is not one equal-width x86 instruction")
        require(target_start >= previous_target_end
                and source_start >= previous_source_end,
                f"{context} is unsorted or overlapping")
        if require_same_offsets:
            require((target_start, target_end) == (source_start, source_end),
                    f"{item_context}: source-aware hybrid offsets differ")
        previous_target_end = target_end
        previous_source_end = source_end

        role_values = {}
        for role in ("target", "instruction_donor"):
            encoded = item.get(f"{role}_bytes")
            require(isinstance(encoded, str)
                    and re.fullmatch(r"[0-9a-f]+", encoded) is not None
                    and len(encoded) == target_width * 2,
                    f"{item_context}.{role}_bytes differs from its range")
            raw = bytes.fromhex(encoded)
            digest = require_sha(
                item.get(f"{role}_sha256"),
                f"{item_context}.{role}_sha256",
            )
            require(sha256_bytes(raw) == digest,
                    f"{item_context} {role} encoding/hash differs")
            require_supported_complete_ia32_instruction(
                raw, f"{item_context} {role}")
            role_values[role] = (encoded, digest)
        require(role_values["target"] != role_values["instruction_donor"],
                f"{item_context} does not change compiler output")
        normalized.append({
            "kind": item["kind"],
            "target_start": target_start,
            "target_end": target_end,
            "target_bytes": role_values["target"][0],
            "target_sha256": role_values["target"][1],
            "instruction_donor_start": source_start,
            "instruction_donor_end": source_end,
            "instruction_donor_bytes": role_values[
                "instruction_donor"][0],
            "instruction_donor_sha256": role_values[
                "instruction_donor"][1],
        })
    return normalized


def validate_same_tu_declaration_carrier_seats(
    value: object, source: bytes, context: str,
) -> dict:
    """Authenticate the two fixed insertion seats of a mixed carrier."""
    require(isinstance(value, dict), f"{context} must be an object")
    exact_audit_keys(value, {
        "kind", "prefix_offset", "prefix_input_sha256",
        "prefix_following_line_sha256", "prefix_context_sha256",
        "after_includes_offset", "preceding_line_sha256",
        "following_line_sha256", "centered_context_sha256",
    }, context)
    require(
        value.get("kind")
        == "prefix_and_after_last_include_seats_v1",
        f"{context}.kind differs",
    )
    prefix_offset = require_exact_int(
        value.get("prefix_offset"), context + ".prefix_offset",
        minimum=0, maximum=0,
    )
    require(
        require_sha(value.get("prefix_input_sha256"),
                    context + ".prefix_input_sha256")
        == sha256_bytes(source[:prefix_offset]),
        f"{context} prefix input differs",
    )
    first_end = source.find(b"\n")
    require(first_end >= 0 and len(source) >= 64,
            f"{context} source lacks the prefix witness")
    require(
        require_sha(value.get("prefix_following_line_sha256"),
                    context + ".prefix_following_line_sha256")
        == sha256_bytes(source[:first_end + 1])
        and require_sha(value.get("prefix_context_sha256"),
                        context + ".prefix_context_sha256")
        == sha256_bytes(source[:64]),
        f"{context} prefix witness differs",
    )

    physical_lines = source.splitlines(keepends=True)
    include_rows = [
        index for index, line in enumerate(physical_lines)
        if line.startswith(b"#include")
    ]
    require(include_rows and include_rows[-1] + 1 < len(physical_lines),
            f"{context} source lacks an after-includes seat")
    include_index = include_rows[-1]
    seat = sum(len(line) for line in physical_lines[:include_index + 1])
    require(
        require_exact_int(
            value.get("after_includes_offset"),
            context + ".after_includes_offset", minimum=32,
            maximum=len(source) - 32,
        ) == seat,
        f"{context} after-includes offset differs",
    )
    require(
        require_sha(value.get("preceding_line_sha256"),
                    context + ".preceding_line_sha256")
        == sha256_bytes(physical_lines[include_index])
        and require_sha(value.get("following_line_sha256"),
                        context + ".following_line_sha256")
        == sha256_bytes(physical_lines[include_index + 1])
        and require_sha(value.get("centered_context_sha256"),
                        context + ".centered_context_sha256")
        == sha256_bytes(source[seat - 32:seat + 32]),
        f"{context} after-includes witness differs",
    )
    return dict(value)


def render_same_tu_declaration_carrier(
    source: bytes, recipe: dict, context: str,
) -> bytes:
    """Render a typed prefix-forward plus after-includes extern carrier."""
    require(recipe.get("kind") == SAME_TU_DECLARATION_CARRIER_RECIPE,
            f"{context}.kind differs")
    validate_same_tu_declaration_carrier_seats(
        recipe.get("seat_proof"), source, context + ".seat_proof")
    try:
        forward = entropy_generator.generate_forward_run(
            recipe["forward_prefix"], recipe["forward_count"],
            recipe["forward_width"],
        ).encode("ascii")
        extern = entropy_generator.generate_extern_run(
            recipe["extern_prefix"], recipe["extern_count"],
            recipe["extern_width"],
        ).encode("ascii").rstrip(b"\n").split(b"\n")
    except (KeyError, ValueError) as error:
        raise ByteIdentityError(
            f"{context} declaration carrier is invalid: {error}") from error
    lines = source.split(b"\n")
    include_rows = [
        index for index, line in enumerate(lines)
        if line.startswith(b"#include")
    ]
    require(include_rows, f"{context} source lacks an include seat")
    insert_at = include_rows[-1] + 1
    return forward + b"\n".join(
        lines[:insert_at] + extern + lines[insert_at:])


def render_forward_run_with_shape_carrier(
    source: bytes, recipe: dict, context: str,
) -> bytes:
    """Render the source half of one stacked forward-run carrier.

    The declaration shape half of this recipe is force-included and never
    touches the translation unit, so only the forward run is seated here --
    at offset zero for `prefix`, or as whole appended lines for `suffix`.
    This mirrors the build's own rendering exactly.
    """
    require(recipe.get("kind") == FORWARD_RUN_WITH_SHAPE_RECIPE,
            f"{context}.kind differs")
    try:
        forward = entropy_generator.generate_forward_run(
            recipe["prefix"], recipe["count"], recipe["width"],
        ).encode("ascii")
    except (KeyError, ValueError) as error:
        raise ByteIdentityError(
            f"{context} forward run is invalid: {error}") from error
    placement = recipe.get("placement")
    if placement == "prefix":
        return forward + source
    require(placement == "suffix", f"{context}.placement differs")
    return b"\n".join(
        source.split(b"\n") + forward.rstrip(b"\n").split(b"\n"))


def validate_same_tu_declaration_carrier_recipe(
    recipe: object, source: bytes, context: str,
) -> tuple[dict, bytes, bytes]:
    """Validate one closed non-emitting mixed declaration carrier."""
    require(isinstance(recipe, dict), f"{context} must be an object")
    exact_audit_keys(recipe, {
        "kind", "forward_prefix", "forward_count", "forward_width",
        "extern_prefix", "extern_count", "extern_width", "seat_proof",
        "generated_header_sha256", "rendered_source_sha256",
        "rendered_source_size", "rendered_source_line_count",
        "compile_lane", "emission_policy", "authenticity_rationale",
    }, context)
    require(recipe.get("kind") == SAME_TU_DECLARATION_CARRIER_RECIPE,
            f"{context}.kind differs")
    lane = recipe.get("compile_lane")
    require(
        isinstance(lane, dict) and set(lane) == {"required_define"}
        and isinstance(lane.get("required_define"), str)
        and lane["required_define"],
        f"{context}.compile_lane differs",
    )
    require(recipe.get("emission_policy")
            == "non_emitting_declarations_only",
            f"{context}.emission_policy differs")
    rationale = recipe.get("authenticity_rationale")
    require(isinstance(rationale, str) and len(rationale) >= 32,
            f"{context}.authenticity_rationale is too weak")
    try:
        forward = entropy_generator.generate_forward_run(
            recipe.get("forward_prefix"), recipe.get("forward_count"),
            recipe.get("forward_width"),
        ).encode("ascii")
        extern = entropy_generator.generate_extern_run(
            recipe.get("extern_prefix"), recipe.get("extern_count"),
            recipe.get("extern_width"),
        ).encode("ascii")
    except ValueError as error:
        raise ByteIdentityError(
            f"{context} declaration carrier parameters: {error}") from error
    require(recipe.get("forward_width") == 3
            and recipe.get("extern_width") == 2,
            f"{context} declaration carrier widths differ")
    forward_identifiers = {
        f"{recipe['forward_prefix']}{index:0{recipe['forward_width']}d}"
        for index in range(recipe["forward_count"])
    }
    extern_identifiers = {
        f"{recipe['extern_prefix']}{index:0{recipe['extern_width']}d}"
        for index in range(recipe["extern_count"])
    }
    source_identifiers = {
        token for token, _, _ in _semantic_significant_tokens(source)
        if SOURCE_OVERLAY_IDENTIFIER_RE.fullmatch(token) is not None
    }
    require(
        forward_identifiers.isdisjoint(extern_identifiers)
        and (forward_identifiers | extern_identifiers)
        .isdisjoint(source_identifiers),
        f"{context} declaration carrier identifier collides with source",
    )
    generated = forward + extern
    require(
        require_sha(recipe.get("generated_header_sha256"),
                    context + ".generated_header_sha256")
        == sha256_bytes(generated),
        f"{context} generated declaration bytes differ",
    )
    rendered = render_same_tu_declaration_carrier(source, recipe, context)
    require(
        require_sha(recipe.get("rendered_source_sha256"),
                    context + ".rendered_source_sha256")
        == sha256_bytes(rendered)
        and require_exact_int(
            recipe.get("rendered_source_size"),
            context + ".rendered_source_size", minimum=1,
        ) == len(rendered)
        and require_exact_int(
            recipe.get("rendered_source_line_count"),
            context + ".rendered_source_line_count", minimum=1,
        ) == rendered.count(b"\n"),
        f"{context} rendered source differs from its pins",
    )
    serialized = json.dumps(recipe, sort_keys=True).casefold()
    require(not any(word in serialized for word in FORBIDDEN_RECIPE_WORDS),
            f"{context} contains forbidden provenance")
    return dict(recipe), generated, rendered


def require_instruction_mosaic_donor_recipe(
    recipe: object, context: str,
) -> None:
    """Restrict mosaics to the existing declaration-only carrier grammar."""
    require(isinstance(recipe, dict)
            and recipe.get("kind")
            in INSTRUCTION_MOSAIC_DECLARATION_RECIPE_KINDS,
            f"{context} is not an allowed declaration-only carrier recipe")
    require(recipe.get("emission_policy")
            == "non_emitting_declarations_only",
            f"{context} is not non-emitting declarations only")


def validate_same_function_carrier_source_identity(
    value: object, context: str,
) -> dict:
    """Validate exact source/header pins for an ordinary declaration carrier."""
    require(isinstance(value, dict), f"{context} must be an object")
    identity_keys = {
        "kind", "selector", "start_marker", "source_owner_mangled",
        "clean_source_sha256", "effective_source_sha256",
        "rendered_source_sha256", "rendered_source_size",
        "function_range_sha256", "function_range_size",
        "function_range_line_count", "owner_header", "carrier",
    }
    if "include_chain" in value:
        identity_keys.add("include_chain")
    exact_audit_keys(value, identity_keys, context)
    require(
        value.get("kind") == SAME_FUNCTION_CARRIER_SOURCE_IDENTITY_KIND
        and value.get("selector") in SAME_FUNCTION_SELECTORS,
        f"{context} kind or selector differs",
    )
    marker = value.get("start_marker")
    owner = value.get("source_owner_mangled")
    require(
        isinstance(marker, str) and marker.isascii()
        and 8 <= len(marker) <= 256
        and not any(character in marker for character in "\0\r\n")
        and isinstance(owner, str) and owner.startswith("?")
        and len(owner) >= 8,
        f"{context} source owner identity differs",
    )
    normalized = {
        "kind": value["kind"], "selector": value["selector"],
        "start_marker": marker, "source_owner_mangled": owner,
    }
    for name in (
        "clean_source_sha256", "effective_source_sha256",
        "rendered_source_sha256", "function_range_sha256",
    ):
        normalized[name] = require_sha(value.get(name), f"{context}.{name}")
    normalized["rendered_source_size"] = require_exact_int(
        value.get("rendered_source_size"),
        f"{context}.rendered_source_size", minimum=1,
    )
    normalized["function_range_size"] = require_exact_int(
        value.get("function_range_size"),
        f"{context}.function_range_size", minimum=1,
    )
    normalized["function_range_line_count"] = require_exact_int(
        value.get("function_range_line_count"),
        f"{context}.function_range_line_count", minimum=1,
    )
    normalized["carrier"] = validate_donor_source_compiler_state_carrier(
        value.get("carrier"), f"{context}.carrier")

    chain = value.get("include_chain")
    if chain is not None:
        require(isinstance(chain, list) and 1 <= len(chain) <= 4,
                f"{context}.include_chain must hold 1..4 pinned headers")
        normalized_chain = []
        seen_paths = set()
        for index, item in enumerate(chain):
            item_context = f"{context}.include_chain[{index}]"
            require(isinstance(item, dict),
                    f"{item_context} must be an object")
            exact_audit_keys(item, {
                "path", "overlaid", "source_sha256", "source_size",
                "include_line",
            }, item_context)
            path = source_overlay_relative_path(
                item.get("path"), f"{item_context}.path")
            require(path not in seen_paths,
                    f"{item_context}.path repeats an include-chain hop")
            seen_paths.add(path)
            require(type(item.get("overlaid")) is bool,
                    f"{item_context}.overlaid is invalid")
            normalized_chain.append({
                "path": path,
                "overlaid": item["overlaid"],
                "source_sha256": require_sha(
                    item.get("source_sha256"),
                    f"{item_context}.source_sha256"),
                "source_size": require_exact_int(
                    item.get("source_size"), f"{item_context}.source_size",
                    minimum=1),
                "include_line": validate_source_overlay_range_pin(
                    item.get("include_line"),
                    f"{item_context}.include_line"),
            })
        normalized["include_chain"] = normalized_chain

    header = value.get("owner_header")
    header_context = f"{context}.owner_header"
    require(isinstance(header, dict), f"{header_context} must be an object")
    header_keys = {
        "path", "source_sha256", "source_size", "owner_marker",
        "owner_range_sha256", "owner_range_size",
        "declaration_sha256", "declaration_size", "declaration_prefix_trim",
        "declaration_significant_token_sha256",
    }
    if chain is not None:
        header_keys.add("include_line")
    exact_audit_keys(header, header_keys, header_context)
    header_marker = header.get("owner_marker")
    require(
        isinstance(header_marker, str) and header_marker.isascii()
        and 8 <= len(header_marker) <= 256
        and not any(character in header_marker for character in "\0\r\n"),
        f"{header_context}.owner_marker is invalid",
    )
    normalized["owner_header"] = {
        "path": source_overlay_relative_path(
            header.get("path"), f"{header_context}.path"),
        "source_sha256": require_sha(
            header.get("source_sha256"), f"{header_context}.source_sha256"),
        "source_size": require_exact_int(
            header.get("source_size"), f"{header_context}.source_size",
            minimum=1,
        ),
        "owner_marker": header_marker,
        "owner_range_sha256": require_sha(
            header.get("owner_range_sha256"),
            f"{header_context}.owner_range_sha256"),
        "owner_range_size": require_exact_int(
            header.get("owner_range_size"),
            f"{header_context}.owner_range_size", minimum=1,
        ),
        "declaration_sha256": require_sha(
            header.get("declaration_sha256"),
            f"{header_context}.declaration_sha256"),
        "declaration_size": require_exact_int(
            header.get("declaration_size"),
            f"{header_context}.declaration_size", minimum=1,
        ),
        "declaration_prefix_trim": require_exact_int(
            header.get("declaration_prefix_trim"),
            f"{header_context}.declaration_prefix_trim",
            minimum=0, maximum=16,
        ),
        "declaration_significant_token_sha256": require_sha(
            header.get("declaration_significant_token_sha256"),
            f"{header_context}.declaration_significant_token_sha256"),
    }
    if chain is not None:
        normalized["owner_header"]["include_line"] = (
            validate_source_overlay_range_pin(
                header.get("include_line"),
                f"{header_context}.include_line")
        )
    return normalized


def select_same_function_carrier_source_window(
    data: bytes, identity: dict, context: str,
) -> bytes:
    """Select one brace-balanced function including its following blank LF."""
    marker = identity["start_marker"].encode("ascii")
    require(data.count(marker) == 1,
            f"{context}: function marker is absent or ambiguous")
    start = data.index(marker)
    tokens = [item for item in source_overlay_tokens(data)
              if item[1] >= start]
    opening = next((index for index, item in enumerate(tokens)
                    if item[0] == "{"), None)
    require(opening is not None, f"{context}: function body is missing")
    depth = 0
    close = None
    for token, _, token_end in tokens[opening:]:
        if token == "{":
            depth += 1
        elif token == "}":
            depth -= 1
            require(depth >= 0, f"{context}: function braces are unbalanced")
            if depth == 0:
                close = token_end
                break
    require(close is not None and data[close:close + 2] == b"\n\n",
            f"{context}: function lacks one trailing blank physical line")
    return data[start:close + 2]


def render_extern_run_pair_recipe_source(data: bytes, recipe: dict) -> bytes:
    """Render the typed two-seat extern carrier used by ordinary donors."""
    require(recipe.get("kind") == "extern_run_pair",
            "extern-pair source rendering requires its exact recipe")
    return render_donor_source_compiler_state_carrier(data, {
        "kind": "extern_run_pair_v1",
        "placement": "after_includes_and_eof_v1",
        "header_prefix": recipe["header_prefix"],
        "header_count": recipe["header_count"],
        "seat_prefix": recipe["seat_prefix"],
        "seat_count": recipe["seat_count"],
        "width": recipe["width"],
        "generated_declarations_sha256": recipe[
            "generated_header_sha256"],
    })


def _read_pinned_include_chain_source(
    source_root: Path, item: dict, rendered_by_path: dict, context: str,
) -> tuple[Path, bytes]:
    """Read one include-chain hop exactly as the compiler saw it."""
    path = source_overlay_logical_path(source_root, item["path"])
    try:
        metadata = path.lstat()
        resolved = path.resolve(strict=True)
    except OSError as error:
        raise ByteIdentityError(
            f"{context}: include-chain source is absent or redirected: "
            f"{error}"
        ) from error
    require(stat.S_ISREG(metadata.st_mode) and not path.is_symlink()
            and resolved == path and resolved.is_relative_to(source_root),
            f"{context}: include-chain source is redirected or non-regular")
    if item["overlaid"]:
        rendered = rendered_by_path.get(item["path"])
        require(isinstance(rendered, (bytes, bytearray)),
                f"{context}: overlaid include-chain source has no rendered "
                "effective view")
        data = bytes(rendered)
    else:
        data = path.read_bytes()
    require(len(data) == item["source_size"]
            and sha256_bytes(data) == item["source_sha256"],
            f"{context}: include-chain source differs from its pin")
    return path, data


def require_same_function_carrier_source_identity(
    source_root: Path, source_relative: str, clean_source: bytes,
    effective_source: bytes, recipe: dict, identity: dict,
    overlaid_paths: set[str], context: str,
    rendered_by_path: dict | None = None,
) -> dict:
    """Bind a carrier render to one unchanged function and owner declaration."""
    require(
        sha256_bytes(clean_source) == identity["clean_source_sha256"]
        and sha256_bytes(effective_source)
        == identity["effective_source_sha256"],
        f"{context}: clean/effective translation-unit source differs",
    )
    recipe_kind = {
        "extern_run_pair": "extern_run_pair_v1",
        "declaration_run_triple": "declaration_run_triple_v1",
    }.get(recipe.get("kind"))
    require(recipe_kind is not None,
            f"{context}: donor recipe is not a source-identity carrier")
    placement, roles = DONOR_SOURCE_CARRIER_SEATS[recipe_kind]
    recipe_carrier = validate_donor_source_compiler_state_carrier({
        "kind": recipe_kind,
        "placement": placement,
        "width": recipe.get("width"),
        "generated_declarations_sha256": recipe.get(
            "generated_header_sha256"),
        **{f"{role}_{field}": recipe.get(f"{role}_{field}")
           for role in roles for field in ("prefix", "count")},
    }, f"{context} donor recipe carrier")
    require(identity["carrier"] == recipe_carrier,
            f"{context}: carrier descriptor differs from the donor recipe")
    rendered_source = render_donor_source_compiler_state_carrier(
        effective_source, identity["carrier"])
    require(
        len(rendered_source) == identity["rendered_source_size"]
        and sha256_bytes(rendered_source)
        == identity["rendered_source_sha256"],
        f"{context}: carrier-rendered source differs from its pins",
    )
    header_spec = identity["owner_header"]
    require(header_spec["path"] not in overlaid_paths,
            f"{context}: owner header has an effective source overlay")
    header_path, header = _read_pinned_semantic_source(
        source_root, header_spec, f"{context} owner header")
    require(len(header) == header_spec["source_size"],
            f"{context}: owner header size differs")

    if identity["selector"] == SAME_FUNCTION_OWNER_HEADER_SELECTOR:
        # The target is defined inline in its own owner header.  That header
        # is content-pinned and carries no effective-source overlay, so it is
        # byte-identical in every compiler state of this unit; the carrier
        # cannot reach it at all.  Requiring the marker to be absent from the
        # unit keeps the ownership unambiguous.
        marker = identity["start_marker"].encode("ascii")
        require(
            not any(data.count(marker) for data in (
                clean_source, effective_source, rendered_source)),
            f"{context}: header-defined target marker also occurs in the "
            "translation unit",
        )
        target = select_same_function_carrier_source_window(
            header, identity, f"{context} owner header")
    else:
        selected = [
            select_same_function_carrier_source_window(
                data, identity, f"{context} {role}")
            for role, data in (
                ("clean", clean_source),
                ("effective", effective_source),
                ("donor", rendered_source),
            )
        ]
        require(selected[0] == selected[1] == selected[2],
                f"{context}: declaration carrier changes the target function")
        target = selected[0]
    require(
        len(target) == identity["function_range_size"]
        and target.count(b"\n") == identity["function_range_line_count"]
        and sha256_bytes(target) == identity["function_range_sha256"],
        f"{context}: target function source range differs from its pins",
    )

    chain = identity.get("include_chain")
    if chain is None:
        include_tokens = ["#", "include", f'"{header_path.name}"']
        include_lines = [
            line for line in effective_source.splitlines(keepends=True)
            if [token for token, _, _ in source_overlay_tokens(line)]
            == include_tokens
        ]
        require(len(include_lines) == 1,
                f"{context}: owner header is not a unique direct quoted "
                "include")
    else:
        # The owner header is reached through pinned intermediate headers.
        # Every hop is proven the same way a direct include is: the included
        # basename must be unique in the checked-in tree and the including
        # file must spell exactly one quoted include of it, with that line
        # itself byte- and token-pinned.
        including_relative = source_relative
        including_data = effective_source
        for index, item in enumerate(chain):
            item_context = f"{context} include chain[{index}]"
            require(item["overlaid"] == (item["path"] in overlaid_paths),
                    f"{item_context}: declared overlay state differs from "
                    "the manifest source overlay")
            item_path, item_data = _read_pinned_include_chain_source(
                source_root, item, rendered_by_path or {}, item_context)
            _require_unique_quoted_include_edge(
                source_root, including_relative, including_data,
                item_path, item["include_line"], item_context)
            including_relative = item["path"]
            including_data = item_data
        _require_unique_quoted_include_edge(
            source_root, including_relative, including_data,
            header_path, header_spec["include_line"],
            f"{context} owner header include")

    owner_marker = header_spec["owner_marker"].encode("ascii")
    require(header.count(owner_marker) == 1,
            f"{context}: owner header marker is absent or ambiguous")
    marker_offset = header.index(owner_marker)
    owner_start = header.rfind(b"\n", 0, marker_offset) + 1
    owner_end = owner_start + header_spec["owner_range_size"]
    require(
        owner_end <= len(header)
        and sha256_bytes(header[owner_start:owner_end])
        == header_spec["owner_range_sha256"],
        f"{context}: owner header range differs from its pin",
    )

    owner_identifier = decorated_immediate_member_owner_identifier(
        identity["source_owner_mangled"], context)
    function_match = re.match(
        r"^\?([A-Za-z_][A-Za-z0-9_]*)@", identity["source_owner_mangled"])
    require(function_match is not None,
            f"{context}: decorated function component differs")
    function_identifier = function_match.group(1)
    tokens = _semantic_significant_tokens(header)
    _, opening, closing = _unique_class_body(
        tokens, owner_identifier, f"{context} owner class")
    class_start = tokens[opening][1]
    class_end = tokens[closing][2]
    require(owner_start <= class_start < class_end <= owner_end,
            f"{context}: owner class escapes the pinned header range")
    line_records = []
    line_start = 0
    for line in header.splitlines(keepends=True):
        line_end = line_start + len(line)
        line_records.append((line_start, line_end,
                             [token for token, _, _
                              in source_overlay_tokens(line)]))
        line_start = line_end
    inside = [
        index for index, (start, end, _) in enumerate(line_records)
        if class_start <= start and end <= class_end
    ]
    declarators = []
    for index in inside:
        tokens_on_line = line_records[index][2]
        if any(token == function_identifier
               and tokens_on_line[position + 1] == "("
               for position, token in enumerate(tokens_on_line[:-1])):
            declarators.append(index)
    require(len(declarators) == 1,
            f"{context}: owner member declaration is absent or ambiguous")
    first = declarators[0]
    depth = 0
    last = None
    for index in inside[inside.index(first):]:
        for token in line_records[index][2]:
            if token == "(":
                depth += 1
            elif token == ")":
                depth -= 1
                require(depth >= 0,
                        f"{context}: owner member declaration is unbalanced")
            elif token == ";" and depth == 0:
                last = index
                break
        if last is not None:
            break
    require(last is not None,
            f"{context}: owner member declaration is unterminated")
    declaration = header[line_records[first][0]:line_records[last][1]]
    trim = header_spec["declaration_prefix_trim"]
    require(declaration[:trim] == b"\t" * trim,
            f"{context}: owner declaration prefix differs")
    declaration = declaration[trim:]
    require(
        len(declaration) == header_spec["declaration_size"]
        and sha256_bytes(declaration) == header_spec["declaration_sha256"]
        and source_overlay_significant_sha256(declaration)
        == header_spec["declaration_significant_token_sha256"],
        f"{context}: owner member declaration differs from its pins",
    )

    identifiers = []
    for role in DONOR_SOURCE_CARRIER_SEATS[identity["carrier"]["kind"]][1]:
        prefix = identity["carrier"][f"{role}_prefix"]
        count = identity["carrier"][f"{role}_count"]
        width = identity["carrier"]["width"]
        identifiers.extend(
            f"{prefix}{index:0{width}d}" for index in range(count)
        )
    source_identifiers = {
        token for token, _, _ in _semantic_significant_tokens(effective_source)
    }
    require(not source_identifiers.intersection(identifiers),
            f"{context}: generated declaration identity collides with source")
    return {
        **identity,
        "carrier_identifiers": identifiers,
        "target_source_sha256": sha256_bytes(target),
    }


_IA32_GENERAL_REGISTERS = (
    "eax", "ecx", "edx", "ebx", "esp", "ebp", "esi", "edi",
)


# The closed subset an instruction must belong to before it may take part in
# a self-permutation.  Both forms have a register destination, read no more
# than one memory operand, and write no memory at all, which is what makes a
# machine-checkable independence proof possible at all.  Any other encoding
# is refused rather than analysed.
_IA32_COMMUTABLE_OPCODES = {
    0x8B: ("mov_r32_rm32", False, False),
    0x33: ("xor_r32_rm32", True, True),
}


def decode_commutable_ia32_instruction(
    encoded: bytes, context: str,
) -> dict:
    """Decode one instruction of the closed commutable subset.

    Returns its exact register read set, register write set, and whether it
    reads or writes memory.  Prefixes, immediates and every opcode outside
    the subset are refused, and the encoding must be consumed exactly, so an
    instruction that cannot be reasoned about can never reach the proof.
    """
    require(isinstance(encoded, (bytes, bytearray)) and len(encoded) >= 2,
            f"{context}: commutable instruction is too short")
    encoded = bytes(encoded)
    entry = _IA32_COMMUTABLE_OPCODES.get(encoded[0])
    require(entry is not None,
            f"{context}: opcode is outside the commutable instruction subset")
    _, reads_destination, writes_flags = entry
    modrm = encoded[1]
    mod = modrm >> 6
    reg = (modrm >> 3) & 7
    rm = modrm & 7
    cursor = 2
    reads: set[str] = set()
    writes = {_IA32_GENERAL_REGISTERS[reg]}
    if reads_destination:
        reads.add(_IA32_GENERAL_REGISTERS[reg])
    if writes_flags:
        writes.add("flags")
    reads_memory = mod != 3
    if mod == 3:
        reads.add(_IA32_GENERAL_REGISTERS[rm])
    elif rm == 4:
        require(len(encoded) > cursor,
                f"{context}: SIB byte is missing")
        sib = encoded[cursor]
        cursor += 1
        index = (sib >> 3) & 7
        base = sib & 7
        if index != 4:
            reads.add(_IA32_GENERAL_REGISTERS[index])
        if base == 5 and mod == 0:
            cursor += 4
        else:
            reads.add(_IA32_GENERAL_REGISTERS[base])
    elif rm == 5 and mod == 0:
        cursor += 4
    else:
        reads.add(_IA32_GENERAL_REGISTERS[rm])
    if mod == 1:
        cursor += 1
    elif mod == 2:
        cursor += 4
    require(cursor == len(encoded),
            f"{context}: commutable instruction encoding is not exact")
    return {
        "reads": reads,
        "writes": writes,
        "reads_memory": reads_memory,
        "writes_memory": False,
    }


def require_commuting_ia32_instruction_pair(
    first: bytes, second: bytes, context: str,
) -> dict:
    """Prove two adjacent instructions may be exchanged without effect.

    Both must decode inside the closed subset, neither may write memory, and
    their register/flag read and write sets must be independent.  Two
    instructions that satisfy this leave the same architectural state in
    either order, so exchanging them is a pure reordering of the same
    compiler output rather than a rewrite of it.
    """
    decoded = [
        decode_commutable_ia32_instruction(first, f"{context} first"),
        decode_commutable_ia32_instruction(second, f"{context} second"),
    ]
    require(not any(item["writes_memory"] for item in decoded),
            f"{context}: a commuting instruction writes memory")
    require(not (decoded[0]["writes"] & decoded[1]["writes"]),
            f"{context}: commuting instructions write the same location")
    require(not (decoded[0]["reads"] & decoded[1]["writes"])
            and not (decoded[1]["reads"] & decoded[0]["writes"]),
            f"{context}: commuting instructions carry a register dependency")
    return {
        "first_reads": sorted(decoded[0]["reads"]),
        "first_writes": sorted(decoded[0]["writes"]),
        "second_reads": sorted(decoded[1]["reads"]),
        "second_writes": sorted(decoded[1]["writes"]),
    }


def validate_instruction_self_permutation(
    value: object, context: str, body_length: int,
) -> dict:
    """Validate a bijective commute of one closed independent IA-32 pair."""
    require(isinstance(value, dict), f"{context} must be an object")
    exact_audit_keys(value, {
        "kind", "source_start", "source_end", "target_start", "target_end",
        "source_instruction_lengths", "target_instruction_lengths",
        "moves", "expected_changed_offsets",
        "expected_function_multiset_sha256",
        "expected_comdat_multiset_sha256", "expected_section_shape_sha256",
        "expected_linker_payload_count", "expected_linker_payload_sha256",
    }, context)
    require(value.get("kind") in SELF_PERMUTATION_KINDS,
            f"{context}.kind differs")
    bounds = {}
    for role in ("source", "target"):
        start = require_exact_int(
            value.get(f"{role}_start"), f"{context}.{role}_start",
            minimum=0, maximum=body_length - 1)
        end = require_exact_int(
            value.get(f"{role}_end"), f"{context}.{role}_end",
            minimum=1, maximum=body_length)
        require(start < end, f"{context}.{role} range is empty")
        bounds[role] = (start, end)
    require(bounds["source"] == bounds["target"],
            f"{context}: self-permutation windows differ")
    width = bounds["source"][1] - bounds["source"][0]

    declared_lengths = {}
    for role in ("source", "target"):
        lengths = value.get(f"{role}_instruction_lengths")
        require(
            isinstance(lengths, list) and len(lengths) == 2
            and all(type(length) is int and 1 <= length <= 15
                    for length in lengths)
            and sum(lengths) == width,
            f"{context}.{role}_instruction_lengths differs",
        )
        declared_lengths[role] = list(lengths)

    moves = value.get("moves")
    require(isinstance(moves, list) and len(moves) == 2,
            f"{context}.moves must contain exactly two instructions")
    normalized_moves = []
    for index, move in enumerate(moves):
        move_context = f"{context}.moves[{index}]"
        require(isinstance(move, dict), f"{move_context} must be an object")
        exact_audit_keys(move, {
            "target_start", "target_end", "target_bytes", "target_sha256",
            "donor_start", "donor_end", "donor_bytes", "donor_sha256",
        }, move_context)
        intervals = {}
        for role, prefix in (("target", "target"), ("source", "donor")):
            outer_start, outer_end = bounds[role]
            start = require_exact_int(
                move.get(f"{prefix}_start"),
                f"{move_context}.{prefix}_start",
                minimum=outer_start, maximum=outer_end - 1)
            end = require_exact_int(
                move.get(f"{prefix}_end"),
                f"{move_context}.{prefix}_end",
                minimum=outer_start + 1, maximum=outer_end)
            require(start < end,
                    f"{move_context}.{prefix} interval is empty")
            intervals[role] = (start, end)
        require(
            intervals["target"][1] - intervals["target"][0]
            == intervals["source"][1] - intervals["source"][0],
            f"{move_context} source/target widths differ",
        )
        encoded = {}
        for role, prefix in (("target", "target"), ("source", "donor")):
            literal = move.get(f"{prefix}_bytes")
            expected_width = intervals[role][1] - intervals[role][0]
            require(
                isinstance(literal, str)
                and re.fullmatch(r"[0-9a-f]+", literal) is not None
                and len(literal) == expected_width * 2,
                f"{move_context}.{prefix}_bytes differs from its interval",
            )
            raw = bytes.fromhex(literal)
            digest = require_sha(
                move.get(f"{prefix}_sha256"),
                f"{move_context}.{prefix}_sha256")
            require(sha256_bytes(raw) == digest,
                    f"{move_context}.{prefix} encoding/hash differs")
            require_supported_complete_ia32_instruction(
                raw, f"{move_context}.{prefix}")
            encoded[role] = (literal, digest, raw)
        require(encoded["target"] == encoded["source"],
                f"{move_context} does not copy one exact donor instruction")
        normalized_moves.append({
            "target_start": intervals["target"][0],
            "target_end": intervals["target"][1],
            "target_bytes": encoded["target"][0],
            "target_sha256": encoded["target"][1],
            "donor_start": intervals["source"][0],
            "donor_end": intervals["source"][1],
            "donor_bytes": encoded["source"][0],
            "donor_sha256": encoded["source"][1],
        })

    for role, start_key, end_key in (
        ("target", "target_start", "target_end"),
        ("source", "donor_start", "donor_end"),
    ):
        ordered = sorted(normalized_moves, key=lambda item: item[start_key])
        cursor = bounds[role][0]
        lengths = []
        for move in ordered:
            require(move[start_key] == cursor,
                    f"{context}: {role} partition is overlapping or gapped")
            cursor = move[end_key]
            lengths.append(move[end_key] - move[start_key])
        require(cursor == bounds[role][1]
                and lengths == declared_lengths[role],
                f"{context}: {role} partition differs from its declaration")
    require(
        [(item["donor_start"], item["donor_end"])
         for item in normalized_moves]
        == list(reversed([
            (item["donor_start"], item["donor_end"])
            for item in sorted(
                normalized_moves, key=lambda item: item["donor_start"])
        ])),
        f"{context}: target order is not the exact two-instruction reversal",
    )

    source_order = sorted(
        normalized_moves, key=lambda item: item["donor_start"])
    first = bytes.fromhex(source_order[0]["donor_bytes"])
    second = bytes.fromhex(source_order[1]["donor_bytes"])
    if value["kind"] == ORDINARY_FPO_SELF_PERMUTATION_KIND:
        # The historical kind additionally names its exact encodings, so a
        # manifest that claims it cannot silently become a different pair.
        require(first == b"\x33\xff",
                f"{context}: first source instruction is not the closed "
                "XOR-zero encoding")
        zero_modrm = first[1]
        zero_reg = (zero_modrm >> 3) & 7
        require(zero_modrm >> 6 == 3 and (zero_modrm & 7) == zero_reg,
                f"{context}: XOR does not zero exactly one register")
        require(second == b"\x8b\x54\x24\x14",
                f"{context}: second source instruction is not the closed "
                "stack-load encoding")
    independence = require_commuting_ia32_instruction_pair(
        first, second, f"{context} commuting pair")

    normalized = {
        "kind": value["kind"],
        "commuting_pair_independence": independence,
        "source_start": bounds["source"][0],
        "source_end": bounds["source"][1],
        "target_start": bounds["target"][0],
        "target_end": bounds["target"][1],
        "source_instruction_lengths": declared_lengths["source"],
        "target_instruction_lengths": declared_lengths["target"],
        "moves": normalized_moves,
        "expected_changed_offsets": [],
        "expected_linker_payload_count": require_exact_int(
            value.get("expected_linker_payload_count"),
            f"{context}.expected_linker_payload_count", minimum=0),
    }
    changed_offsets = value.get("expected_changed_offsets")
    require(
        isinstance(changed_offsets, list) and changed_offsets
        and changed_offsets == sorted(set(changed_offsets))
        and all(type(offset) is int and 0 <= offset < body_length
                for offset in changed_offsets),
        f"{context}.expected_changed_offsets differs",
    )
    normalized["expected_changed_offsets"] = list(changed_offsets)
    for name in (
        "expected_function_multiset_sha256",
        "expected_comdat_multiset_sha256",
        "expected_section_shape_sha256",
        "expected_linker_payload_sha256",
    ):
        normalized[name] = require_sha(value.get(name), f"{context}.{name}")
    return normalized


def validate_instruction_mosaic_ranges(
    value: object, context: str, body_length: int,
) -> list[dict]:
    """Validate literal same-offset instruction range declarations.

    This schema gate closes order, width, bytes, digests, and declared
    partitions.  Routes that require complete-instruction evidence separately
    prove both endpoints and every partition with the line-row-anchored,
    fail-closed IA-32 decoder before any bytes cross.  Runtime composition
    copies bytes from the freshly compiled donor, never from the manifest.
    """
    require(isinstance(value, list) and 1 <= len(value) <= 64,
            f"{context} must contain 1..64 instruction ranges")
    normalized = []
    previous_end = 0
    for index, item in enumerate(value):
        item_context = f"{context}[{index}]"
        require(isinstance(item, dict), f"{item_context} must be an object")
        kind = item.get("kind")
        if kind == "same_offset_complete_x86_instruction_v1":
            exact_audit_keys(item, INSTRUCTION_MOSAIC_RANGE_KEYS,
                             item_context,
                             optional=INSTRUCTION_MOSAIC_RANGE_OPTIONAL_KEYS)
        elif kind == "same_offset_complete_x86_instruction_sequence_v1":
            exact_audit_keys(item, INSTRUCTION_MOSAIC_SEQUENCE_RANGE_KEYS,
                             item_context,
                             optional=INSTRUCTION_MOSAIC_RANGE_OPTIONAL_KEYS)
        else:
            raise ByteIdentityError(f"{item_context}.kind differs")
        start = require_exact_int(
            item.get("start"), item_context + ".start",
            minimum=0, maximum=body_length - 1,
        )
        end = require_exact_int(
            item.get("end"), item_context + ".end",
            minimum=1, maximum=body_length,
        )
        maximum = 15 if kind == "same_offset_complete_x86_instruction_v1" else 64
        require(start < end and end - start <= maximum,
                f"{item_context} is not a bounded x86 instruction range")
        require(start >= previous_end,
                f"{context} is unsorted or overlapping")
        previous_end = end
        seed_hex = item.get("seed_bytes")
        donor_hex = item.get("donor_bytes")
        require(isinstance(seed_hex, str) and isinstance(donor_hex, str)
                and re.fullmatch(r"[0-9a-f]+", seed_hex) is not None
                and re.fullmatch(r"[0-9a-f]+", donor_hex) is not None
                and len(seed_hex) == len(donor_hex) == 2 * (end - start),
                f"{item_context} literal encodings differ from its range")
        seed_bytes = bytes.fromhex(seed_hex)
        donor_bytes = bytes.fromhex(donor_hex)
        seed_sha = require_sha(
            item.get("seed_sha256"), item_context + ".seed_sha256")
        donor_sha = require_sha(
            item.get("donor_sha256"), item_context + ".donor_sha256")
        require(sha256_bytes(seed_bytes) == seed_sha
                and sha256_bytes(donor_bytes) == donor_sha,
                f"{item_context} literal encoding/hash differs")
        require(seed_bytes != donor_bytes and seed_sha != donor_sha,
                f"{item_context} does not move compiler state")
        normalized_item = {
            "kind": kind,
            "start": start, "end": end,
            "seed_bytes": seed_hex, "seed_sha256": seed_sha,
            "donor_bytes": donor_hex, "donor_sha256": donor_sha,
        }
        if "donor" in item:
            donor_id = item.get("donor")
            require(isinstance(donor_id, str)
                    and re.fullmatch(r"d_[0-9a-f]{12}", donor_id),
                    f"{item_context}.donor is invalid")
            normalized_item["donor"] = donor_id
        reseat_keys = {"relocation_reseat", "seed_relocation_offsets",
                       "donor_relocation_offsets"}
        if reseat_keys & set(item):
            require(item.get("relocation_reseat") is True
                    and reseat_keys <= set(item),
                    f"{item_context} relocation reseat declaration is "
                    "incomplete")
            offsets = {}
            for role in ("seed", "donor"):
                values = item.get(f"{role}_relocation_offsets")
                require(isinstance(values, list) and 1 <= len(values) <= 16
                        and all(type(v) is int and start <= v
                                and v + 4 <= end for v in values)
                        and values == sorted(set(values)),
                        f"{item_context}.{role}_relocation_offsets differ")
                offsets[role] = list(values)
            require(len(offsets["seed"]) == len(offsets["donor"])
                    and offsets["seed"] != offsets["donor"],
                    f"{item_context} relocation reseat does not move a "
                    "relocation operand")
            normalized_item["relocation_reseat"] = True
            normalized_item["seed_relocation_offsets"] = offsets["seed"]
            normalized_item["donor_relocation_offsets"] = offsets["donor"]
        if kind == "same_offset_complete_x86_instruction_sequence_v1":
            for role in ("seed", "donor"):
                lengths = item.get(f"{role}_instruction_lengths")
                require(isinstance(lengths, list) and lengths
                        and len(lengths) <= 64
                        and all(type(length) is int and 1 <= length <= 15
                                for length in lengths)
                        and sum(lengths) == end - start,
                        f"{item_context}.{role}_instruction_lengths differ")
                normalized_item[f"{role}_instruction_lengths"] = list(lengths)
        normalized.append(normalized_item)
    return normalized


def require_instruction_mosaic_range_donor_bindings(
    ranges: list[dict], main_donor: str, variant_donors: set[str],
    context: str,
) -> None:
    """Make per-range donor provenance explicit only for multi-donor rows."""
    if variant_donors:
        range_donors = {item.get("donor") for item in ranges}
        require(None not in range_donors
                and range_donors == variant_donors | {main_donor},
                f"{context}: instruction ranges do not use every declared "
                "donor variant")
        return
    require(all("donor" not in item for item in ranges),
            f"{context}: a single-donor instruction mosaic may not label "
            "ranges")


def require_retail_relocation_oracle(
    donor_rows: list[dict], retail_body: bytes, retail_address: int,
    oracle: list[dict], context: str,
) -> dict:
    """Bind every masked operand to the symbol it resolves to in retail.

    Masked body equality alone is insufficient: two COFF objects can carry
    identical instruction bytes while naming different callees.  This check
    decodes each pinned retail operand before the mask is applied.
    """
    require(len(donor_rows) == len(oracle),
            f"{context} relocation count differs from its semantic oracle")
    fields = (
        "offset", "type", "addend", "target", "target_section",
        "target_value", "target_type", "target_storage",
    )
    for index, (record, expected) in enumerate(zip(donor_rows, oracle)):
        require(all(record[field] == expected[field] for field in fields),
                f"{context} relocation {index} differs from its COFF oracle")
        offset = record["offset"]
        raw = retail_body[offset:offset + 4]
        require(len(raw) == 4,
                f"{context} relocation {index} leaves the retail body")
        if record["type"] == 0x0006:  # IMAGE_REL_I386_DIR32
            resolved = int.from_bytes(raw, "little")
        else:  # IMAGE_REL_I386_REL32
            displacement = int.from_bytes(raw, "little", signed=True)
            resolved = (retail_address + offset + 4 + displacement) & 0xFFFFFFFF
        symbol_base = (resolved - record["addend"]) & 0xFFFFFFFF
        require(symbol_base == int(expected["retail_target"], 16),
                f"{context} relocation {index} resolves to 0x{symbol_base:08x}, "
                f"not {expected['retail_target']}")
    return {"semantic_relocation_count": len(donor_rows)}


# D1.  A CLOSED set: a pinned local-set delta on a target's `.debug$S`
# closure child is admitted for exactly the source-refactor kinds listed here,
# and for no other function in the manifest.
LOCAL_SET_DELTA_REFACTOR_KINDS = frozenset({"constructor_allocation_lift_v1"})


def validate_local_set_delta(value: object, context: str) -> dict:
    """Validate one pinned, removal-only `.debug$S` local-set delta."""
    require(isinstance(value, dict), f"{context} must be an object")
    exact_audit_keys(value, {
        "kind", "expected_seed_debug_size", "expected_donor_debug_size",
        "removed_records",
    }, context)
    require(value.get("kind") == "removed_caller_locals_v1",
            f"{context}.kind is unsupported")
    seed_size = require_exact_int(
        value.get("expected_seed_debug_size"),
        context + ".expected_seed_debug_size", minimum=1, maximum=1 << 20)
    donor_size = require_exact_int(
        value.get("expected_donor_debug_size"),
        context + ".expected_donor_debug_size", minimum=1, maximum=1 << 20)
    require(seed_size > donor_size,
            f"{context} must remove locals, never add them")
    raw = value.get("removed_records")
    require(isinstance(raw, list) and 1 <= len(raw) <= 8,
            f"{context}.removed_records must name one to eight records")
    records = []
    previous = -1
    for index, item in enumerate(raw):
        item_context = f"{context}.removed_records[{index}]"
        require(isinstance(item, dict), f"{item_context} must be an object")
        exact_audit_keys(item, {
            "seed_offset", "size", "record_type", "identifier",
        }, item_context)
        seed_offset = require_exact_int(
            item.get("seed_offset"), item_context + ".seed_offset",
            minimum=0, maximum=seed_size)
        require(seed_offset > previous,
                f"{item_context}.seed_offset is unsorted or repeated")
        previous = seed_offset
        record_type = item.get("record_type")
        require(record_type in CODEVIEW_REMOVED_LOCAL_RECORD_TYPES,
                f"{item_context}.record_type is outside the closed local "
                "record types")
        records.append({
            "seed_offset": seed_offset,
            "size": require_exact_int(
                item.get("size"), item_context + ".size",
                minimum=4, maximum=seed_size),
            "record_type": record_type,
            "identifier": _source_overlay_identifier(
                item.get("identifier"), item_context + ".identifier"),
        })
    identifiers = [item["identifier"] for item in records]
    require(len(set(identifiers)) == len(identifiers),
            f"{context}.removed_records identifiers must be distinct")
    require(seed_size - donor_size == sum(item["size"] for item in records),
            f"{context} sizes do not account for the whole debug$S change")
    return {
        "kind": "removed_caller_locals_v1",
        "expected_seed_debug_size": seed_size,
        "expected_donor_debug_size": donor_size,
        "removed_records": records,
    }


# Only the record types a caller-local removal can legitimately delete.
CODEVIEW_REMOVED_LOCAL_RECORD_TYPES = frozenset({0x0002, 0x0200})


# The byte offset of the length-prefixed name inside each admitted CodeView
# symbol record's payload; None means the record carries no name.
CODEVIEW_SYMBOL_NAME_OFFSETS = {
    0x0002: 4,      # S_REGISTER: typind u16, reg u16
    0x0006: None,   # S_END
    0x0200: 6,      # S_BPREL32: off i32, typind u16
    0x0201: 8,      # S_LDATA32: off u32, seg u16, typind u16
    0x0204: 33,     # S_GPROC32
    0x0205: 33,     # S_LPROC32
    0x0209: 7,      # S_LABEL32: off u32, seg u16, flags u8
}


CODEVIEW_PROCEDURE_RECORD_TYPES = frozenset({0x0204, 0x0205})


CODEVIEW_END_RECORD_TYPE = 0x0006


def parse_codeview_symbol_stream(data: bytes, context: str) -> list[dict]:
    """Parse one object-file `.debug$S` symbol-record stream to exhaustion.

    Every record is `reclen:u16, rectyp:u16, payload[reclen-2]`, and every
    record type must be one this module knows how to name.  A stream that does
    not parse exactly, or that carries a record type outside the table, is
    refused rather than approximated.
    """
    records = []
    offset = 0
    while offset < len(data):
        require(offset + 4 <= len(data),
                f"{context}: symbol record header is truncated")
        length = int.from_bytes(data[offset:offset + 2], "little")
        total = length + 2
        require(length >= 2 and offset + total <= len(data),
                f"{context}: symbol record length is out of range")
        record_type = int.from_bytes(data[offset + 2:offset + 4], "little")
        require(record_type in CODEVIEW_SYMBOL_NAME_OFFSETS,
                f"{context}: symbol record type 0x{record_type:04x} is "
                "outside the closed table")
        payload = data[offset + 4:offset + total]
        name_offset = CODEVIEW_SYMBOL_NAME_OFFSETS[record_type]
        if name_offset is None:
            require(not payload,
                    f"{context}: terminator record carries a payload")
            name = ""
        else:
            require(len(payload) > name_offset,
                    f"{context}: symbol record has no name field")
            count = payload[name_offset]
            require(len(payload) == name_offset + 1 + count,
                    f"{context}: symbol record name length is inconsistent")
            name = payload[name_offset + 1:].decode("latin1")
        records.append({
            "offset": offset, "size": total, "type": record_type,
            "name": name,
        })
        offset += total
    require(offset == len(data),
            f"{context}: symbol stream does not parse to exhaustion")
    return records


def codeview_symbol_identity(record: dict) -> tuple[int, str]:
    """A record's (type, name) with compiler-local serials collapsed.

    `$L`/`$T` serials are per-compile counters, exactly as they are for
    relocation targets -- `local_symbol_kind` is the same classifier the
    divergent relocation comparison already uses.  Collapsing them is what
    makes the two streams comparable at all; every other name is compared
    literally.
    """
    kind = local_symbol_kind(record["name"])
    return record["type"], ("$" + kind if kind is not None
                            else record["name"])


def require_removed_caller_locals_delta(
    seed_stream: bytes, donor_stream: bytes, relocation_offsets: list[int],
    delta: dict, context: str,
) -> tuple[dict, bytes]:
    """D1: prove a `.debug$S` size change is exactly a pinned local removal.

    The equality this replaces was a same-function sanity proxy, not an
    output-integrity check -- no donor `.debug$S` byte has ever reached the
    output.  What stands in its place is strictly more: the removal is pinned
    record by record, it is proved to be a removal and never an addition, it
    may not touch any relocated span, the surviving record sequence must equal
    the donor's, and the composed output DROPS the removed records instead of
    keeping a stale local the installed body does not have.
    """
    seed_records = parse_codeview_symbol_stream(seed_stream, context + " seed")
    donor_records = parse_codeview_symbol_stream(
        donor_stream, context + " donor")
    for records, role in ((seed_records, "seed"), (donor_records, "donor")):
        require(records
                and records[0]["type"] in CODEVIEW_PROCEDURE_RECORD_TYPES
                and records[-1]["type"] == CODEVIEW_END_RECORD_TYPE,
                f"{context}: {role} symbol stream is not one bounded "
                "procedure record")
    removed = delta["removed_records"]
    require(len(seed_stream) == delta["expected_seed_debug_size"]
            and len(donor_stream) == delta["expected_donor_debug_size"],
            f"{context}: debug$S sizes differ from their local-set pins")
    require(len(seed_stream) - len(donor_stream)
            == sum(item["size"] for item in removed),
            f"{context}: the pinned local-set delta does not account for the "
            "whole debug$S size change")

    guard = max(relocation_offsets, default=-4) + 4
    by_offset = {record["offset"]: record for record in seed_records}
    for item in removed:
        record = by_offset.get(item["seed_offset"])
        require(record is not None
                and record["size"] == item["size"]
                and record["type"] == item["record_type"]
                and record["name"] == item["identifier"],
                f"{context}: pinned removed record at "
                f"{item['seed_offset']} is not the seed's "
                f"{item['identifier']!r}")
        require(item["seed_offset"] >= guard,
                f"{context}: a removed record overlaps a relocated span, so "
                "debug$S relocation offsets would move")

    removed_offsets = {item["seed_offset"] for item in removed}
    surviving = [record for record in seed_records
                 if record["offset"] not in removed_offsets]
    require([codeview_symbol_identity(item) for item in surviving]
            == [codeview_symbol_identity(item) for item in donor_records],
            f"{context}: the seed symbol stream minus its pinned removals is "
            "not the donor's symbol sequence")
    removed_identifiers = {item["identifier"] for item in removed}
    require(not removed_identifiers.intersection(
                record["name"] for record in donor_records),
            f"{context}: a pinned removed local still exists in the donor's "
            "symbol stream")

    reduced = b"".join(
        seed_stream[record["offset"]:record["offset"] + record["size"]]
        for record in surviving
    )
    require(len(reduced) == len(donor_stream),
            f"{context}: the reduced seed symbol stream has the wrong size")
    return {
        "local_set_removed_records": len(removed),
        "local_set_removed_identifiers": sorted(removed_identifiers),
        "local_set_debug_size_delta": len(reduced) - len(seed_stream),
    }, reduced


def local_symbol_kind(name: str) -> str | None:
    if len(name) > 2 and name[0] == "$" and name[1] in "LT" and name[2:].isdigit():
        return name[1]
    if name.startswith("$done$") and name[6:].isdigit():
        return "done"
    return None


def relocation_compatibility(
    seed_rows: list[dict], donor_rows: list[dict], seed_primary: int, donor_primary: int
) -> dict | None:
    """Pair primary relocations by semantic target/type/addend, not file offset."""
    if len(seed_rows) != len(donor_rows):
        return None
    local_updates = {}
    pairs = []
    for seed, donor in zip(seed_rows, donor_rows):
        if not (
            seed["type"] == donor["type"]
            and seed["width"] == donor["width"]
            and seed["addend"] == donor["addend"]
            and seed["target_type"] == donor["target_type"]
            and seed["target_storage"] == donor["target_storage"]
        ):
            return None
        seed_internal = seed["target_section"] == seed_primary
        donor_internal = donor["target_section"] == donor_primary
        if seed_internal != donor_internal:
            return None
        seed_kind = local_symbol_kind(seed["target"])
        donor_kind = local_symbol_kind(donor["target"])
        if seed_kind or donor_kind:
            if not (seed_internal and donor_internal and seed_kind == donor_kind):
                return None
            previous = local_updates.setdefault(seed["symbol_index"], donor["target_value"])
            if previous != donor["target_value"]:
                return None
        elif not (
            seed["target"] == donor["target"]
            and (
                (seed_internal and seed["target_value"] == donor["target_value"])
                or (
                    not seed_internal
                    and seed["target_section"] == donor["target_section"]
                    and seed["target_value"] == donor["target_value"]
                )
            )
        ):
            return None
        pairs.append(
            {
                "ordinal": seed["ordinal"],
                "seed_offset": seed["offset"],
                "donor_offset": donor["offset"],
                "type": donor["type"],
                "addend": donor["addend"],
                "seed_target": seed["target"],
                "donor_target": donor["target"],
            }
        )
    return {"pairs": pairs, "local_updates": local_updates}


def linker_payload_multiset(coff: CoffObject) -> Counter:
    """Fingerprint every non-code, non-CodeView linker contribution.

    This intentionally includes `.drectve`, `.xdata`, import/CRT/tls families,
    and unknown section names.  A declaration shape is not allowed to create
    or perturb any such payload even though the final composition retains the
    seed copy. Raw relocation-table bytes are deliberately excluded because
    their symbol-index field is object bookkeeping; the ordered resolved tuple
    below retains offset, type, addend, target identity, section, value, type,
    and storage while the section-body digest retains the relocated operands.
    """
    result = Counter()
    for section in coff.sections:
        if section["name"].startswith(".text") or section["name"].startswith(".debug"):
            continue
        relocations = tuple(
            (
                item["offset"], item["type"], item["addend"],
                local_symbol_kind(item["target"]) or item["target"],
                item["target_section"], item["target_value"],
                item["target_type"], item["target_storage"],
            )
            for item in detailed_relocations(coff, section)
        )
        result[
            (
                section["name"], section["raw_size"], section["characteristics"],
                sha256_bytes(coff_body(coff, section)), relocations,
            )
        ] += 1
    return result


def declaration_identifiers(header: bytes) -> set[str]:
    text = header.decode("ascii", "strict")
    require("Generated declaration-only entropy shape. Emits no code or data." in text,
            "generated declaration shape marker is absent")
    identifiers = set(re.findall(r"\b(?:Class|Function)[A-Za-z]+\b", text))
    require(identifiers, "generated declaration shape has no identifiers")
    return identifiers


def verify_non_emitting_donor(
    seed: CoffObject, donor: CoffObject, identifiers: set[str]
) -> dict:
    require(function_multiset(seed) == function_multiset(donor),
            "declaration shape changed the complete function multiset")
    require(len(seed.sections) == len(donor.sections),
            "declaration shape changed the section count")
    require(
        all(
            left["name"] == right["name"]
            and left["characteristics"] == right["characteristics"]
            for left, right in zip(seed.sections, donor.sections)
        ),
        "declaration shape changed section order or characteristics",
    )
    leaked_symbols = sorted(
        symbol["name"]
        for symbol in donor.symbols.values()
        if any(identifier in symbol["name"] for identifier in identifiers)
    )
    require(not leaked_symbols,
            f"declaration shape emitted COFF symbols: {leaked_symbols[:5]}")
    require(linker_payload_multiset(seed) == linker_payload_multiset(donor),
            "declaration shape added or altered non-code/directive/import/CRT linker payload")

    # VC4.2 can place CodeView type records in an ordinary `.debug$S` stream
    # (not only `.debug$T`).  Such records are compiler metadata, not linker
    # payload, and none of them is copied into the seed-based composition.
    debug_type_ranges = [
        (section["raw_offset"], section["raw_offset"] + section["raw_size"])
        for section in donor.sections
        if section["name"] in (".debug$S", ".debug$T") and section["raw_size"]
    ]
    for identifier in identifiers:
        needle = identifier.encode("ascii")
        start = 0
        while True:
            occurrence = donor.data.find(needle, start)
            if occurrence < 0:
                break
            require(any(left <= occurrence < right for left, right in debug_type_ranges),
                    f"declaration identifier escaped CodeView types: {identifier}")
            start = occurrence + 1
    return {
        "function_count": sum(function_multiset(seed).values()),
        "section_count": len(seed.sections),
        "defined_or_undefined_shape_symbols": [],
        "noncode_directive_import_crt_payload_identical": True,
    }


def normalized_donor_lines(
    seed: CoffObject,
    donor: CoffObject,
    seed_section: dict,
    donor_section: dict,
    seed_function_index: int,
    donor_function_index: int,
) -> bytes:
    require(seed_section["line_count"] > 0 and donor_section["line_count"] > 0,
            "FPO composer requires COFF line tables")
    seed_lines = coff_table(seed, seed_section, "lines")
    donor_lines = bytearray(coff_table(donor, donor_section, "lines"))
    require(struct.unpack_from("<IH", seed_lines, 0) == (seed_function_index, 0),
            "seed COFF line sentinel is invalid")
    require(struct.unpack_from("<IH", donor_lines, 0) == (donor_function_index, 0),
            "donor COFF line sentinel is invalid")
    struct.pack_into("<I", donor_lines, 0, seed_function_index)
    previous = -1
    for index in range(1, donor_section["line_count"]):
        offset, line = struct.unpack_from("<IH", donor_lines, index * 6)
        require(line != 0 and previous <= offset < donor_section["raw_size"],
                f"donor COFF line row {index} is outside or nonmonotonic")
        previous = offset
    return bytes(donor_lines)


def apply_replacements(data: bytes, replacements: list[tuple[int, int, bytes]]) -> bytes:
    ordered = sorted(replacements, key=lambda item: item[0])
    cursor = 0
    chunks = []
    for start, end, replacement in ordered:
        require(cursor <= start <= end <= len(data), "COFF replacement ranges overlap")
        chunks.extend((data[cursor:start], replacement))
        cursor = end
    chunks.append(data[cursor:])
    return b"".join(chunks)


def shifted_pointer(pointer: int, replacements: list[tuple[int, int, bytes]]) -> int:
    if pointer == 0:
        return 0
    delta = 0
    for start, end, replacement in sorted(replacements, key=lambda item: item[0]):
        if pointer < start:
            break
        if pointer == start:
            return start + delta
        require(pointer >= end, "COFF pointer falls inside a replaced range")
        delta += len(replacement) - (end - start)
    return pointer + delta


FPO_RECORD_KEYS = {
    "ulOffStart", "cbProcSize", "cdwLocals", "cdwParams", "cbProlog",
    "cbRegs", "fHasSEH", "fUseBP", "reserved", "cbFrame", "raw_sha256",
}


def parse_fpo_data(raw: bytes, *, expected_proc_size: int | None = None) -> dict:
    """Decode and structurally validate one classic 16-byte FPO_DATA row."""
    require(isinstance(raw, bytes) and len(raw) == 16,
            "associated FPO record is not exactly 16 bytes")
    ul_off_start, cb_proc_size, cdw_locals, cdw_params = struct.unpack_from(
        "<IIIH", raw, 0
    )
    cb_prolog = raw[14]
    packed = raw[15]
    result = {
        "ulOffStart": ul_off_start,
        "cbProcSize": cb_proc_size,
        "cdwLocals": cdw_locals,
        "cdwParams": cdw_params,
        "cbProlog": cb_prolog,
        "cbRegs": packed & 0x7,
        "fHasSEH": (packed >> 3) & 0x1,
        "fUseBP": (packed >> 4) & 0x1,
        "reserved": (packed >> 5) & 0x1,
        "cbFrame": (packed >> 6) & 0x3,
        "raw_sha256": sha256_bytes(raw),
    }
    require(result["ulOffStart"] == 0,
            "associative function FPO ulOffStart must be zero")
    require(result["cbProcSize"] > 0,
            "FPO cbProcSize must be positive")
    if expected_proc_size is not None:
        require(type(expected_proc_size) is int and expected_proc_size > 0
                and result["cbProcSize"] == expected_proc_size,
                "FPO cbProcSize differs from its function section")
    require(result["cbProlog"] <= result["cbProcSize"],
            "FPO cbProlog exceeds cbProcSize")
    require(result["reserved"] == 0,
            "FPO reserved bit must remain zero")
    require(result["cdwLocals"] <= 0x3FFFFFFF,
            "FPO local DWORD count overflows its byte range")
    require(result["cdwParams"] <= 0x7FFF,
            "FPO parameter WORD count overflows its byte range")
    return result


def validate_manifest_fpo_record(value: object, context: str) -> dict:
    require(isinstance(value, dict), f"{context} must be an object")
    exact_audit_keys(value, FPO_RECORD_KEYS, context)
    integer_ranges = {
        "ulOffStart": (0, 0xFFFFFFFF),
        "cbProcSize": (1, 0xFFFFFFFF),
        "cdwLocals": (0, 0x3FFFFFFF),
        "cdwParams": (0, 0x7FFF),
        "cbProlog": (0, 0xFF),
        "cbRegs": (0, 7),
        "fHasSEH": (0, 1),
        "fUseBP": (0, 1),
        "reserved": (0, 0),
        "cbFrame": (0, 3),
    }
    normalized = {}
    for name, (minimum, maximum) in integer_ranges.items():
        item = value.get(name)
        require(type(item) is int and minimum <= item <= maximum,
                f"{context}.{name} is invalid")
        normalized[name] = item
    normalized["raw_sha256"] = require_sha(
        value.get("raw_sha256"), f"{context}.raw_sha256"
    )
    require(normalized["ulOffStart"] == 0
            and normalized["cbProlog"] <= normalized["cbProcSize"],
            f"{context} is structurally invalid")
    return normalized


ORDINARY_FPO_CHILD_IDENTITY_KEYS = {
    "section_number", "raw_size", "relocation_count", "line_count",
    "characteristics", "selection", "associated",
    "expected_seed_body_sha256", "expected_donor_body_sha256",
    "expected_seed_relocation_sha256", "expected_donor_relocation_sha256",
}


def validate_ordinary_fpo_mosaic_identity(
    value: object, context: str, primary_section: int, body_length: int,
) -> dict:
    """Validate the narrow seed-authoritative FPO mosaic identity schema."""
    require(isinstance(value, dict), f"{context} must be an object")
    exact_audit_keys(value, {
        "kind", "expected_primary_characteristics",
        "expected_primary_selection", "expected_function_count",
        "expected_comdat_count", "expected_seed_line_sha256",
        "expected_donor_line_sha256", "debug_f", "debug_s",
    }, context)
    require(value.get("kind") == ORDINARY_FPO_MOSAIC_IDENTITY_KIND,
            f"{context}.kind differs")
    normalized = {"kind": value["kind"]}
    for name, minimum, maximum in (
        ("expected_primary_characteristics", 1, 0xFFFFFFFF),
        ("expected_primary_selection", 1, 7),
        ("expected_function_count", 1, 0x7FFFFFFF),
        ("expected_comdat_count", 1, 0x7FFFFFFF),
    ):
        normalized[name] = require_exact_int(
            value.get(name), f"{context}.{name}",
            minimum=minimum, maximum=maximum,
        )
    for name in ("expected_seed_line_sha256",
                 "expected_donor_line_sha256"):
        normalized[name] = require_sha(value.get(name), f"{context}.{name}")

    children = {}
    for key, section_name in (("debug_f", ".debug$F"),
                              ("debug_s", ".debug$S")):
        child_context = f"{context}.{key}"
        child = value.get(key)
        require(isinstance(child, dict), f"{child_context} must be an object")
        extra_keys = ({"expected_record"} if key == "debug_f" else {
            "expected_common_prefix_sha256", "expected_record_kind",
            "expected_cb_proc", "expected_dbg_start", "expected_dbg_end",
        })
        exact_audit_keys(
            child, ORDINARY_FPO_CHILD_IDENTITY_KEYS | extra_keys,
            child_context,
        )
        normalized_child = {}
        for name, minimum, maximum in (
            ("section_number", 1, 0x7FFF),
            ("raw_size", 1, 0xFFFFFFFF),
            ("relocation_count", 0, 0xFFFF),
            ("line_count", 0, 0xFFFF),
            ("characteristics", 1, 0xFFFFFFFF),
            ("selection", 1, 7),
            ("associated", 1, 0x7FFF),
        ):
            normalized_child[name] = require_exact_int(
                child.get(name), f"{child_context}.{name}",
                minimum=minimum, maximum=maximum,
            )
        require(normalized_child["associated"] == primary_section
                and normalized_child["selection"] == 5
                and normalized_child["line_count"] == 0,
                f"{child_context} is not an associative debug child")
        for name in (
            "expected_seed_body_sha256", "expected_donor_body_sha256",
            "expected_seed_relocation_sha256",
            "expected_donor_relocation_sha256",
        ):
            normalized_child[name] = require_sha(
                child.get(name), f"{child_context}.{name}")
        if key == "debug_f":
            require(normalized_child["raw_size"] == 16
                    and normalized_child["relocation_count"] == 1,
                    f"{child_context} is not one classic FPO record")
            record = validate_manifest_fpo_record(
                child.get("expected_record"),
                f"{child_context}.expected_record",
            )
            require(record["cbProcSize"] == body_length,
                    f"{child_context} FPO size differs from the function")
            normalized_child["expected_record"] = record
        else:
            require(normalized_child["raw_size"] >= 28
                    and normalized_child["relocation_count"] == 2,
                    f"{child_context} is not one CodeView procedure record")
            normalized_child["expected_common_prefix_sha256"] = require_sha(
                child.get("expected_common_prefix_sha256"),
                f"{child_context}.expected_common_prefix_sha256",
            )
            require(child.get("expected_record_kind") == "0502",
                    f"{child_context}.expected_record_kind differs")
            normalized_child["expected_record_kind"] = "0502"
            for name in ("expected_cb_proc", "expected_dbg_start",
                         "expected_dbg_end"):
                normalized_child[name] = require_exact_int(
                    child.get(name), f"{child_context}.{name}",
                    minimum=0, maximum=body_length,
                )
            require(
                normalized_child["expected_cb_proc"] == body_length
                and 0 <= normalized_child["expected_dbg_start"]
                <= normalized_child["expected_dbg_end"] < body_length,
                f"{child_context} CodeView procedure range differs",
            )
        children[key] = normalized_child
    normalized.update(children)
    require(children["debug_f"]["section_number"]
            != children["debug_s"]["section_number"],
            f"{context} child seats are not distinct")
    return normalized


SOURCE_FPO_CHILD_IDENTITY_KEYS = {
    "section_number", "expected_seed_raw_size", "expected_donor_raw_size",
    "relocation_count", "line_count", "characteristics", "selection",
    "associated", "expected_seed_body_sha256",
    "expected_donor_body_sha256", "expected_seed_relocation_sha256",
    "expected_donor_relocation_sha256",
}


SOURCE_FPO_EXTRA_RELOCATION_KEYS = {
    "offset", "width", "type", "addend", "target", "target_section",
    "target_value", "target_type", "target_storage",
}


def validate_source_fpo_mosaic_identity(
    value: object, context: str, primary_section: int, body_length: int,
) -> dict:
    """Validate the isolated source-refactor FPO/CodeView identity."""
    require(isinstance(value, dict), f"{context} must be an object")
    exact_audit_keys(value, {
        "kind", "expected_primary_characteristics",
        "expected_primary_selection", "expected_function_count",
        "expected_comdat_count", "expected_seed_line_sha256",
        "expected_donor_line_sha256", "debug_f", "debug_s",
    }, context)
    require(value.get("kind") == SOURCE_FPO_MOSAIC_IDENTITY_KIND,
            f"{context}.kind differs")
    normalized = {"kind": value["kind"]}
    for name, minimum, maximum in (
        ("expected_primary_characteristics", 1, 0xFFFFFFFF),
        ("expected_primary_selection", 1, 7),
        ("expected_function_count", 1, 0x7FFFFFFF),
        ("expected_comdat_count", 1, 0x7FFFFFFF),
    ):
        normalized[name] = require_exact_int(
            value.get(name), f"{context}.{name}",
            minimum=minimum, maximum=maximum)
    for name in ("expected_seed_line_sha256",
                 "expected_donor_line_sha256"):
        normalized[name] = require_sha(value.get(name), f"{context}.{name}")

    children = {}
    for key in ("debug_f", "debug_s"):
        child_context = f"{context}.{key}"
        child = value.get(key)
        require(isinstance(child, dict), f"{child_context} must be an object")
        extras = ({"expected_record"} if key == "debug_f" else {
            "expected_common_prefix_sha256", "expected_record_kind",
            "expected_cb_proc", "expected_dbg_start", "expected_dbg_end",
            "expected_seed_tail_sha256", "expected_donor_tail_sha256",
        })
        optional = (
            {"expected_extra_relocations"} if key == "debug_s" else set()
        )
        exact_audit_keys(
            child, SOURCE_FPO_CHILD_IDENTITY_KEYS | extras | optional,
            child_context, optional=optional)
        normalized_child = {}
        for name, minimum, maximum in (
            ("section_number", 1, 0x7FFF),
            ("expected_seed_raw_size", 1, 0xFFFFFFFF),
            ("expected_donor_raw_size", 1, 0xFFFFFFFF),
            ("relocation_count", 0, 0xFFFF),
            ("line_count", 0, 0xFFFF),
            ("characteristics", 1, 0xFFFFFFFF),
            ("selection", 1, 7),
            ("associated", 1, 0x7FFF),
        ):
            normalized_child[name] = require_exact_int(
                child.get(name), f"{child_context}.{name}",
                minimum=minimum, maximum=maximum)
        require(normalized_child["associated"] == primary_section
                and normalized_child["selection"] == 5
                and normalized_child["line_count"] == 0,
                f"{child_context} is not an associative debug child")
        for name in (
            "expected_seed_body_sha256", "expected_donor_body_sha256",
            "expected_seed_relocation_sha256",
            "expected_donor_relocation_sha256",
        ):
            normalized_child[name] = require_sha(
                child.get(name), f"{child_context}.{name}")
        if key == "debug_f":
            require(normalized_child["expected_seed_raw_size"] == 16
                    and normalized_child["expected_donor_raw_size"] == 16
                    and normalized_child["relocation_count"] == 1,
                    f"{child_context} is not one classic FPO record")
            record = validate_manifest_fpo_record(
                child.get("expected_record"),
                f"{child_context}.expected_record")
            require(record["cbProcSize"] == body_length,
                    f"{child_context} FPO size differs from the function")
            normalized_child["expected_record"] = record
        else:
            extra_relocations = child.get("expected_extra_relocations", [])
            require(isinstance(extra_relocations, list),
                    f"{child_context}.expected_extra_relocations must be "
                    "an array")
            normalized_extra_relocations = []
            for index, relocation in enumerate(extra_relocations):
                relocation_context = (
                    f"{child_context}.expected_extra_relocations[{index}]"
                )
                require(isinstance(relocation, dict),
                        f"{relocation_context} must be an object")
                exact_audit_keys(
                    relocation, SOURCE_FPO_EXTRA_RELOCATION_KEYS,
                    relocation_context)
                normalized_relocation = {}
                for name, minimum, maximum in (
                    ("offset", 34, 0xFFFFFFFF),
                    ("width", 1, 4),
                    ("type", 0, 0xFFFF),
                    ("addend", 0, 0xFFFFFFFF),
                    ("target_section", 1, 0x7FFF),
                    ("target_value", 0, body_length - 1),
                    ("target_type", 0, 0xFFFF),
                    ("target_storage", 0, 0xFF),
                ):
                    normalized_relocation[name] = require_exact_int(
                        relocation.get(name),
                        f"{relocation_context}.{name}",
                        minimum=minimum, maximum=maximum)
                target = relocation.get("target")
                require(isinstance(target, str) and target,
                        f"{relocation_context}.target is invalid")
                normalized_relocation["target"] = target
                require(
                    RELOCATION_WIDTHS.get(normalized_relocation["type"])
                    == normalized_relocation["width"]
                    and normalized_relocation["target_section"]
                    == primary_section
                    and normalized_relocation["offset"]
                    + normalized_relocation["width"]
                    <= min(
                        normalized_child["expected_seed_raw_size"],
                        normalized_child["expected_donor_raw_size"],
                    ),
                    f"{relocation_context} shape or target seat differs",
                )
                normalized_extra_relocations.append(normalized_relocation)
            require(
                all(
                    left["offset"] + left["width"] <= right["offset"]
                    for left, right in zip(
                        normalized_extra_relocations,
                        normalized_extra_relocations[1:])
                ),
                f"{child_context}.expected_extra_relocations overlap or "
                "are not ordered",
            )
            require(normalized_child["expected_seed_raw_size"] >= 28
                    and normalized_child["expected_donor_raw_size"] >= 28
                    and normalized_child["relocation_count"]
                    == 2 + len(normalized_extra_relocations),
                    f"{child_context} is not a CodeView procedure record")
            if "expected_extra_relocations" in child:
                require(normalized_extra_relocations,
                        f"{child_context}.expected_extra_relocations is "
                        "empty")
                normalized_child["expected_extra_relocations"] = (
                    normalized_extra_relocations)
            for name in (
                "expected_common_prefix_sha256", "expected_seed_tail_sha256",
                "expected_donor_tail_sha256",
            ):
                normalized_child[name] = require_sha(
                    child.get(name), f"{child_context}.{name}")
            require(child.get("expected_record_kind") == "0502",
                    f"{child_context}.expected_record_kind differs")
            normalized_child["expected_record_kind"] = "0502"
            for name in ("expected_cb_proc", "expected_dbg_start",
                         "expected_dbg_end"):
                normalized_child[name] = require_exact_int(
                    child.get(name), f"{child_context}.{name}",
                    minimum=0, maximum=body_length)
            require(
                normalized_child["expected_cb_proc"] == body_length
                and 0 <= normalized_child["expected_dbg_start"]
                <= normalized_child["expected_dbg_end"] < body_length,
                f"{child_context} CodeView procedure range differs")
        children[key] = normalized_child
    normalized.update(children)
    require(children["debug_f"]["section_number"]
            != children["debug_s"]["section_number"],
            f"{context} child seats are not distinct")
    return normalized


def _comdat_child_closure(coff: CoffObject, primary: dict) -> tuple:
    """Return (count, sorted child section names) of a COMDAT's selection-5
    associates."""
    definitions = section_definitions(coff)
    children = tuple(sorted(
        section["name"]
        for section in coff.sections
        if definitions.get(section["number"], {}).get("selection") == 5
        and definitions[section["number"]]["associated"] == primary["number"]
    ))
    return (len(children), children)


def _comdat_child(coff: CoffObject, primary: dict, name: str) -> dict:
    definitions = section_definitions(coff)
    matches = [
        section
        for section in coff.sections
        if section["name"] == name
        and definitions.get(section["number"], {}).get("selection") == 5
        and definitions[section["number"]]["associated"] == primary["number"]
    ]
    require(len(matches) == 1, f"expected one {name} child, found {len(matches)}")
    return matches[0]


def _normalized_relocation_renames(
    seed: CoffObject, seed_section: dict,
    donor: CoffObject, donor_section: dict,
    context: str,
    seat_map: dict | None = None,
) -> list[tuple[int, str]]:
    """Require literal relocation equality except paired object-local $L/$T
    serial renames whose targets are structurally identical.

    seat_map maps a declared cross-lane donor's spliced-group section
    numbers onto the seed's, so in-group targets compare structurally."""
    left = detailed_relocations(seed, seed_section)
    right = detailed_relocations(donor, donor_section)
    require(len(left) == len(right), f"{context}: relocation counts differ")
    renames = []
    for a, b in zip(left, right):
        require(
            (a["offset"], a["type"], a["addend"])
            == (b["offset"], b["type"], b["addend"]),
            f"{context}: relocation offset/type/addend differs",
        )
        if a["target"] == b["target"]:
            continue
        kind = local_symbol_kind(a["target"])
        if kind is None:
            # function-static data: <base>$S<serial> renumbered by state
            left_base, _, left_serial = a["target"].rpartition("$S")
            right_base, _, right_serial = b["target"].rpartition("$S")
            require(
                left_base and left_base == right_base
                and left_serial.isdigit() and right_serial.isdigit()
                and a["target_type"] == b["target_type"]
                and a["target_storage"] == b["target_storage"],
                f"{context}: non-local relocation rename "
                f"{a['target']!r} -> {b['target']!r}",
            )
            renames.append((a["offset"], "S"))
            continue
        require(
            kind == local_symbol_kind(b["target"]),
            f"{context}: non-local relocation rename "
            f"{a['target']!r} -> {b['target']!r}",
        )
        donor_target_section = b["target_section"]
        if seat_map:
            donor_target_section = seat_map.get(
                donor_target_section, donor_target_section
            )
        require(
            a["target_section"] == donor_target_section
            and all(a["target_" + field] == b["target_" + field]
                    for field in ("value", "type", "storage")),
            f"{context}: renamed local relocation target structure differs",
        )
        renames.append((a["offset"], kind))
    return renames


def require_same_semantic_relocations(
    seed: CoffObject,
    seed_section: dict,
    donor: CoffObject,
    donor_section: dict,
    context: str,
) -> list[tuple[int, str]]:
    """Require identical resolved relocation semantics at identical offsets.

    Compiler-local ``$L``/``$T`` serials may be renamed, but only when their
    section seat, value, type, and storage class are unchanged.  Ordinary
    symbols must retain their literal identity and the same structural target.
    This is deliberately stricter than the relocation pairing used by resize
    composers: an instruction mosaic retains the seed table verbatim.
    """
    renames = _normalized_relocation_renames(
        seed, seed_section, donor, donor_section, context)
    left = detailed_relocations(seed, seed_section)
    right = detailed_relocations(donor, donor_section)
    target_fields = (
        "target_section", "target_value", "target_type", "target_storage",
    )
    for index, (seed_row, donor_row) in enumerate(zip(left, right)):
        require(seed_row["width"] == donor_row["width"],
                f"{context}: relocation {index} width differs")
        if seed_row["target"] != donor_row["target"]:
            seed_kind = local_symbol_kind(seed_row["target"])
            require(seed_kind is not None
                    and seed_kind == local_symbol_kind(donor_row["target"]),
                    f"{context}: relocation {index} changes symbol identity")
        require(all(seed_row[field] == donor_row[field]
                    for field in target_fields),
                f"{context}: relocation {index} target structure differs")
    return renames


MOSAIC_PERMUTED_RELOCATION_ORDER = "permuted_outside_ranges"


def _mosaic_relocation_pair_rename(
    seed: CoffObject, donor: CoffObject, a: dict, b: dict,
) -> tuple[bool, tuple[int, str] | None]:
    """Judge one same-offset seed/donor relocation pair under the strict
    instruction-mosaic rule (``require_instruction_mosaic_semantic_relocations``
    plus ``_normalized_relocation_renames``) without raising.

    Returns ``(ok, rename)`` where ``rename`` is the recorded local
    ``$L``/``$T`` serial rename, if any."""
    if (a["offset"], a["type"], a["addend"], a["width"]) != (
            b["offset"], b["type"], b["addend"], b["width"]):
        return False, None
    if a["target"] == b["target"]:
        if any(a[field] != b[field]
               for field in ("target_value", "target_type",
                             "target_storage")):
            return False, None
        if a["target_section"] == b["target_section"]:
            return True, None
        if (local_symbol_kind(a["target"]) is not None
                or a["target_section"] <= 0 or b["target_section"] <= 0):
            return False, None
        seed_target = seed.sections[a["target_section"] - 1]
        donor_target = donor.sections[b["target_section"] - 1]
        return (comdat_primary_identity(seed, seed_target)
                == comdat_primary_identity(donor, donor_target)), None
    kind = local_symbol_kind(a["target"])
    if kind is None:
        # the strict mosaic rule refuses every ordinary-symbol rename
        # (including function-static ``$S`` serials)
        return False, None
    if kind != local_symbol_kind(b["target"]):
        return False, None
    if (a["target_section"] != b["target_section"]
            or any(a["target_" + field] != b["target_" + field]
                   for field in ("value", "type", "storage"))):
        return False, None
    return True, (a["offset"], kind)


def _permuted_relocation_key(row: dict) -> tuple:
    """Offset-free identity of one relocation record for the multiset rule.

    Compiler-local ``$L``/``$T`` serials are reduced to their kind; their
    structural target (section seat, value, type, storage) stays literal."""
    kind = local_symbol_kind(row["target"])
    target = row["target"] if kind is None else "$" + kind
    return (row["width"], row["type"], row["addend"], target,
            row["target_section"], row["target_value"],
            row["target_type"], row["target_storage"])


def _require_permuted_instruction_mosaic_relocations(
    seed: CoffObject,
    seed_section: dict,
    donor: CoffObject,
    donor_section: dict,
    permuted_ranges: list[tuple[int, int]],
    context: str,
) -> list[tuple[int, str]]:
    """The ``permuted_outside_ranges`` relocation-order rule.

    A declaration-only carrier may re-order otherwise identical constant
    stores, so the donor's relocation records outside the imported ranges may
    stand at other offsets and in another order.  The output still retains
    the seed relocation table verbatim; the donor only proves that it is the
    same compiler output of the same source: every same-offset pair obeys the
    strict rule, and the remaining records are an exact offset-free multiset
    permutation of each other that touches no imported range.  A donor that
    satisfies the strict rule must be declared under it (an empty permutation
    is refused), so this mode is never a silent relaxation.
    """
    left = detailed_relocations(seed, seed_section)
    right = detailed_relocations(donor, donor_section)
    require(len(left) == len(right), f"{context}: relocation counts differ")
    right_by_offset = {}
    for index, row in enumerate(right):
        require(row["offset"] not in right_by_offset,
                f"{context}: donor relocation offsets collide")
        right_by_offset[row["offset"]] = index
    renames = []
    unmatched_left = []
    matched_right = set()
    for a in left:
        index = right_by_offset.get(a["offset"])
        if index is not None and index not in matched_right:
            ok, rename = _mosaic_relocation_pair_rename(
                seed, donor, a, right[index])
            if ok:
                matched_right.add(index)
                if rename is not None:
                    renames.append(rename)
                continue
        unmatched_left.append(a)
    unmatched_right = [row for index, row in enumerate(right)
                       if index not in matched_right]
    require(unmatched_left,
            f"{context}: relocation permutation is empty; the strict "
            "relocation order applies")
    require(
        sorted(_permuted_relocation_key(row) for row in unmatched_left)
        == sorted(_permuted_relocation_key(row) for row in unmatched_right),
        f"{context}: relocations outside the imported ranges are not a "
        "permutation of the seed's",
    )
    for role, rows in (("seed", unmatched_left), ("donor", unmatched_right)):
        for row in rows:
            operand_start = row["offset"]
            operand_end = operand_start + row["width"]
            require(
                all(operand_end <= start or operand_start >= end
                    for start, end in permuted_ranges),
                f"{context}: permuted {role} relocation at offset "
                f"{operand_start} lies inside an imported range",
            )
    return renames


def _require_reseat_instruction_mosaic_relocations(
    seed: CoffObject,
    seed_section: dict,
    donor: CoffObject,
    donor_section: dict,
    reseat_windows: list[tuple[int, int]],
    context: str,
) -> list[tuple[int, str]]:
    """The ``relocation_reseat`` relocation rule.

    Records pair by ordinal exactly as under the strict rule; the only
    relaxation is that a paired record may carry its operand at another
    offset when both the seed's and the donor's operand lie inside the same
    declared reseat window.  Everything else about the pair (type, width,
    addend, target identity and structure, COMDAT seat) is the strict rule.
    """
    left = detailed_relocations(seed, seed_section)
    right = detailed_relocations(donor, donor_section)
    require(len(left) == len(right), f"{context}: relocation counts differ")
    renames = []
    for index, (a, b) in enumerate(zip(left, right)):
        if a["offset"] != b["offset"]:
            window = next(
                ((start, end) for start, end in reseat_windows
                 if start <= a["offset"] and a["offset"] + a["width"] <= end),
                None,
            )
            require(
                window is not None
                and window[0] <= b["offset"]
                and b["offset"] + b["width"] <= window[1],
                f"{context}: relocation {index} moves outside a declared "
                "reseat window",
            )
            b = dict(b)
            b["offset"] = a["offset"]
        ok, rename = _mosaic_relocation_pair_rename(seed, donor, a, b)
        require(ok, f"{context}: relocation {index} differs from the seed")
        if rename is not None:
            renames.append(rename)
    return renames


def require_instruction_mosaic_semantic_relocations(
    seed: CoffObject,
    seed_section: dict,
    donor: CoffObject,
    donor_section: dict,
    context: str,
    *,
    permuted_ranges: list[tuple[int, int]] | None = None,
    reseat_windows: list[tuple[int, int]] | None = None,
) -> list[tuple[int, str]]:
    """Compare mosaic relocations while permitting benign COMDAT reseating.

    With ``reseat_windows`` (the declared ``relocation_reseat`` ranges) the
    ordinal rule still applies to every record, but a paired record may stand
    at another offset when both operands lie inside the same declared window
    (``_require_reseat_instruction_mosaic_relocations``).

    With ``permuted_ranges`` (the imported instruction ranges of a mosaic
    declared ``relocation_order: permuted_outside_ranges``) the offset-free
    multiset rule of ``_require_permuted_instruction_mosaic_relocations``
    applies instead of the ordinal rule.

    A declaration-only carrier can reorder otherwise identical vtable/data
    COMDATs.  The output retains the seed relocation table, so a same-named
    ordinary target may move seats only when both seats describe the exact
    same primary COMDAT identity.  Compiler-local symbols remain under the
    stricter ordinary mosaic rule.
    """
    require(permuted_ranges is None or reseat_windows is None,
            f"{context}: relocation permutation and reseat are exclusive")
    if permuted_ranges is not None:
        return _require_permuted_instruction_mosaic_relocations(
            seed, seed_section, donor, donor_section, permuted_ranges,
            context,
        )
    if reseat_windows is not None:
        return _require_reseat_instruction_mosaic_relocations(
            seed, seed_section, donor, donor_section, reseat_windows,
            context,
        )
    renames = _normalized_relocation_renames(
        seed, seed_section, donor, donor_section, context
    )
    left = detailed_relocations(seed, seed_section)
    right = detailed_relocations(donor, donor_section)
    for index, (seed_row, donor_row) in enumerate(zip(left, right)):
        require(seed_row["width"] == donor_row["width"],
                f"{context}: relocation {index} width differs")
        same_name = seed_row["target"] == donor_row["target"]
        local = (local_symbol_kind(seed_row["target"]) is not None
                 or local_symbol_kind(donor_row["target"]) is not None)
        common_fields = ("target_value", "target_type", "target_storage")
        require(same_name or local,
                f"{context}: relocation {index} changes symbol identity")
        require(all(seed_row[field] == donor_row[field]
                    for field in common_fields),
                f"{context}: relocation {index} target structure differs")
        if seed_row["target_section"] == donor_row["target_section"]:
            continue
        require(same_name and not local
                and seed_row["target_section"] > 0
                and donor_row["target_section"] > 0,
                f"{context}: relocation {index} changes target seat")
        seed_target = seed.sections[seed_row["target_section"] - 1]
        donor_target = donor.sections[donor_row["target_section"] - 1]
        require(
            comdat_primary_identity(seed, seed_target)
            == comdat_primary_identity(donor, donor_target),
            f"{context}: relocation {index} reseats a different COMDAT",
        )
    return renames


def require_ordinary_fpo_mosaic_identity(
    seed: CoffObject,
    seed_primary: dict,
    donor: CoffObject,
    donor_primary: dict,
    function: dict,
    identity: dict,
    context: str,
) -> list[tuple[dict, dict]]:
    """Authenticate one ordinary mosaic's exact FPO/CodeView closure."""
    mangled = function["mangled"]
    seed_definitions = section_definitions(seed)
    donor_definitions = section_definitions(donor)
    require(
        seed_primary["characteristics"]
        == donor_primary["characteristics"]
        == identity["expected_primary_characteristics"],
        f"{context}: primary characteristics differ",
    )
    require(
        seed_definitions[seed_primary["number"]]["selection"]
        == donor_definitions[donor_primary["number"]]["selection"]
        == identity["expected_primary_selection"],
        f"{context}: primary COMDAT selection differs",
    )
    for role, coff in (("seed", seed), ("donor", donor)):
        require(
            sum(function_multiset(coff).values())
            == identity["expected_function_count"],
            f"{context}: {role} function census differs",
        )
        require(
            sum(comdat_primary_identity_multiset(coff).values())
            == identity["expected_comdat_count"],
            f"{context}: {role} COMDAT census differs",
        )
    require(linker_payload_multiset(seed) == linker_payload_multiset(donor),
            f"{context}: declaration carrier changed linker payload")
    require(
        sha256_bytes(_coff_table_bytes(seed, seed_primary, "lines"))
        == identity["expected_seed_line_sha256"]
        and sha256_bytes(_coff_table_bytes(donor, donor_primary, "lines"))
        == identity["expected_donor_line_sha256"],
        f"{context}: target line-table pin differs",
    )
    require(
        _comdat_child_closure(seed, seed_primary)
        == _comdat_child_closure(donor, donor_primary)
        == (2, (".debug$F", ".debug$S")),
        f"{context}: closure is not the exact FPO pair",
    )

    pairs = []
    for key, name in (("debug_f", ".debug$F"),
                      ("debug_s", ".debug$S")):
        pin = identity[key]
        left = _comdat_child(seed, seed_primary, name)
        right = _comdat_child(donor, donor_primary, name)
        for role, coff, section, definitions in (
            ("seed", seed, left, seed_definitions),
            ("donor", donor, right, donor_definitions),
        ):
            definition = definitions[section["number"]]
            require(
                section["number"] == pin["section_number"]
                and section["raw_size"] == pin["raw_size"]
                and section["relocation_count"]
                == pin["relocation_count"]
                and section["line_count"] == pin["line_count"]
                and section["characteristics"] == pin["characteristics"]
                and definition["selection"] == pin["selection"]
                and definition["associated"] == pin["associated"],
                f"{context}: {role} {name} geometry differs",
            )
            require(
                sha256_bytes(coff_body(coff, section))
                == pin[f"expected_{role}_body_sha256"],
                f"{context}: {role} {name} body pin differs",
            )
            require(
                sha256_bytes(_coff_table_bytes(
                    coff, section, "relocations"))
                == pin[f"expected_{role}_relocation_sha256"],
                f"{context}: {role} {name} relocation-table pin differs",
            )
        require_same_semantic_relocations(
            seed, left, donor, right, f"{context} {name}")
        left_rows = detailed_relocations(seed, left)
        right_rows = detailed_relocations(donor, right)
        expected_rows = (
            [(0, 4, 7)] if name == ".debug$F"
            else [(28, 4, 11), (32, 2, 10)]
        )
        for role, rows in (("seed", left_rows), ("donor", right_rows)):
            require(
                len(rows) == len(expected_rows)
                and all(
                    (row["offset"], row["width"], row["type"])
                    == expected
                    and row["addend"] == 0
                    and row["target"] == mangled
                    and row["target_section"] == seed_primary["number"]
                    and row["target_value"] == 0
                    and row["target_type"] == 32
                    and row["target_storage"] == 2
                    for row, expected in zip(rows, expected_rows)
                ),
                f"{context}: {role} {name} semantic relocations differ",
            )
        pairs.append((left, right))

    seed_f = coff_body(seed, pairs[0][0])
    donor_f = coff_body(donor, pairs[0][1])
    require(seed_f == donor_f,
            f"{context}: FPO raw bytes differ between compiler states")
    require(
        exact_json_equal(
            parse_fpo_data(seed_f, expected_proc_size=seed_primary["raw_size"]),
            identity["debug_f"]["expected_record"],
        )
        and exact_json_equal(
            parse_fpo_data(
                donor_f, expected_proc_size=donor_primary["raw_size"]),
            identity["debug_f"]["expected_record"],
        ),
        f"{context}: parsed FPO record differs",
    )
    seed_s = coff_body(seed, pairs[1][0])
    donor_s = coff_body(donor, pairs[1][1])
    debug_pin = identity["debug_s"]
    require(
        len(seed_s) == len(donor_s) == debug_pin["raw_size"]
        and seed_s[:28] == donor_s[:28]
        and sha256_bytes(seed_s[:28])
        == debug_pin["expected_common_prefix_sha256"]
        and seed_s[2:4].hex() == debug_pin["expected_record_kind"],
        f"{context}: CodeView procedure identity differs",
    )
    for role, raw in (("seed", seed_s), ("donor", donor_s)):
        cb_proc, dbg_start, dbg_end = struct.unpack_from("<III", raw, 16)
        require(
            (cb_proc, dbg_start, dbg_end) == (
                debug_pin["expected_cb_proc"],
                debug_pin["expected_dbg_start"],
                debug_pin["expected_dbg_end"],
            )
            and 0 <= dbg_start <= dbg_end < cb_proc,
            f"{context}: {role} CodeView procedure range differs",
        )
    return pairs


def require_ordinary_fpo_self_permutation_receipts(
    seed: CoffObject, donor: CoffObject, function: dict, context: str,
) -> dict:
    """Pin all object-wide identities for the isolated FPO permutation."""
    return require_self_permutation_receipts(
        seed, donor, function, ORDINARY_FPO_CLOSURE_CHILDREN, context)


def require_self_permutation_receipts(
    seed: CoffObject, donor: CoffObject, function: dict,
    closure_children: tuple[str, ...], context: str,
) -> dict:
    """Pin all object-wide identities for one isolated self-permutation.

    The permutation exchanges two of the seed's own complete instructions,
    so the donor is a witness rather than a byte source: it must be the same
    translation unit in a different declaration-carrier state, with an
    identical function set, COMDAT identity set, section shape and linker
    payload, and a COMDAT closure that describes the same procedure.
    """
    require(closure_children in (ORDINARY_FPO_CLOSURE_CHILDREN,
                                 EH_CLOSURE_CHILDREN),
            f"{context}: self-permutation closure class is not supported")
    permutation = function["instruction_self_permutation"]
    seed_functions = function_multiset(seed)
    donor_functions = function_multiset(donor)
    seed_comdats = comdat_primary_identity_multiset(seed)
    donor_comdats = comdat_primary_identity_multiset(donor)
    seed_linker = linker_payload_multiset(seed)
    donor_linker = linker_payload_multiset(donor)
    require(
        seed_functions == donor_functions
        and canonical_counter_receipt_sha256(seed_functions)
        == canonical_counter_receipt_sha256(donor_functions)
        == permutation["expected_function_multiset_sha256"],
        f"{context}: function multiset receipt differs",
    )
    require(
        seed_comdats == donor_comdats
        and canonical_counter_receipt_sha256(seed_comdats)
        == canonical_counter_receipt_sha256(donor_comdats)
        == permutation["expected_comdat_multiset_sha256"],
        f"{context}: COMDAT multiset receipt differs",
    )
    require(
        len(seed.sections) == len(donor.sections)
        and section_shape_receipt_sha256(seed)
        == section_shape_receipt_sha256(donor)
        == permutation["expected_section_shape_sha256"],
        f"{context}: section shape receipt differs",
    )
    require(
        seed_linker == donor_linker
        and sum(seed_linker.values()) == sum(donor_linker.values())
        == permutation["expected_linker_payload_count"]
        and canonical_counter_receipt_sha256(seed_linker)
        == canonical_counter_receipt_sha256(donor_linker)
        == permutation["expected_linker_payload_sha256"],
        f"{context}: linker payload receipt differs",
    )
    seed_primary = seed.function_section(function["mangled"])
    donor_primary = donor.function_section(function["mangled"])
    for child_name in closure_children:
        seed_child = _comdat_child(seed, seed_primary, child_name)
        donor_child = _comdat_child(donor, donor_primary, child_name)
        seed_child_body = coff_body(seed, seed_child)
        donor_child_body = coff_body(donor, donor_child)
        if (closure_children == EH_CLOSURE_CHILDREN
                and child_name == ".debug$S"):
            # An EH closure's .debug$S embeds CodeView type indices, which a
            # declaration carrier legitimately renumbers.  The procedure
            # record itself -- record kind, code length and debug range --
            # must still be identical, and the composed object keeps the
            # seed's table verbatim, so the permutation cannot move a debug
            # boundary.
            require(
                len(seed_child_body) == len(donor_child_body) >= 28
                and seed_child_body[:28] == donor_child_body[:28]
                and seed_child_body[2:4] == b"\x05\x02",
                f"{context}: {child_name} procedure identity differs "
                "between compiler states",
            )
        else:
            require(
                seed_child_body == donor_child_body,
                f"{context}: {child_name} body differs between compiler "
                "states",
            )
    source_identity = function["same_function_source_identity"]
    carrier = validate_donor_source_compiler_state_carrier(
        source_identity.get("carrier"), f"{context} carrier descriptor")
    identifiers = [
        f"{carrier[f'{role}_prefix']}{index:0{carrier['width']}d}"
        for role in DONOR_SOURCE_CARRIER_SEATS[carrier["kind"]][1]
        for index in range(carrier[f"{role}_count"])
    ]
    normalized_identifiers = source_identity.get("carrier_identifiers")
    require(
        normalized_identifiers is None
        or normalized_identifiers == identifiers,
        f"{context}: normalized carrier identifier set differs",
    )
    leaked_symbols = [
        symbol["name"] for symbol in donor.symbols.values()
        if any(identifier in symbol["name"] for identifier in identifiers)
    ]
    leaked_bytes = [
        identifier for identifier in identifiers
        if identifier.encode("ascii") in donor.data
    ]
    require(not leaked_symbols and not leaked_bytes,
            f"{context}: generated declarations leaked into donor output")
    return {
        "function_multiset_sha256": permutation[
            "expected_function_multiset_sha256"],
        "comdat_multiset_sha256": permutation[
            "expected_comdat_multiset_sha256"],
        "section_shape_sha256": permutation[
            "expected_section_shape_sha256"],
        "linker_payload_sha256": permutation[
            "expected_linker_payload_sha256"],
        "carrier_identifiers_absent": True,
    }


def require_source_fpo_mosaic_identity(
    seed: CoffObject,
    seed_primary: dict,
    donor: CoffObject,
    donor_primary: dict,
    function: dict,
    identity: dict,
    context: str,
) -> list[tuple[dict, dict]]:
    """Authenticate one source-refactor mosaic's exact FPO closure.

    The seed and donor may have separately pinned CodeView payload sizes and
    bodies, but they must describe the same procedure and retain identical
    FPO data and semantic child relocations. The composed output remains
    seed-authoritative for both children.
    """
    mangled = function["mangled"]
    seed_definitions = section_definitions(seed)
    donor_definitions = section_definitions(donor)
    require(
        seed_primary["characteristics"]
        == donor_primary["characteristics"]
        == identity["expected_primary_characteristics"],
        f"{context}: primary characteristics differ",
    )
    require(
        seed_definitions[seed_primary["number"]]["selection"]
        == donor_definitions[donor_primary["number"]]["selection"]
        == identity["expected_primary_selection"],
        f"{context}: primary COMDAT selection differs",
    )
    for role, coff in (("seed", seed), ("donor", donor)):
        require(
            sum(function_multiset(coff).values())
            == identity["expected_function_count"],
            f"{context}: {role} function census differs",
        )
        require(
            sum(comdat_primary_identity_multiset(coff).values())
            == identity["expected_comdat_count"],
            f"{context}: {role} COMDAT census differs",
        )
    require(linker_payload_multiset(seed) == linker_payload_multiset(donor),
            f"{context}: source refactor changed linker payload")
    require(
        sha256_bytes(_coff_table_bytes(seed, seed_primary, "lines"))
        == identity["expected_seed_line_sha256"]
        and sha256_bytes(_coff_table_bytes(donor, donor_primary, "lines"))
        == identity["expected_donor_line_sha256"],
        f"{context}: target line-table pin differs",
    )
    require(
        _comdat_child_closure(seed, seed_primary)
        == _comdat_child_closure(donor, donor_primary)
        == (2, (".debug$F", ".debug$S")),
        f"{context}: closure is not the exact FPO pair",
    )

    pairs = []
    for key, name in (("debug_f", ".debug$F"),
                      ("debug_s", ".debug$S")):
        pin = identity[key]
        left = _comdat_child(seed, seed_primary, name)
        right = _comdat_child(donor, donor_primary, name)
        for role, coff, section, definitions, primary in (
            ("seed", seed, left, seed_definitions, seed_primary),
            ("donor", donor, right, donor_definitions, donor_primary),
        ):
            definition = definitions[section["number"]]
            require(
                section["number"] == pin["section_number"]
                and section["raw_size"]
                == pin[f"expected_{role}_raw_size"]
                and section["relocation_count"]
                == pin["relocation_count"]
                and section["line_count"] == pin["line_count"]
                and section["characteristics"] == pin["characteristics"]
                and definition["selection"] == pin["selection"]
                and definition["associated"] == primary["number"]
                == pin["associated"],
                f"{context}: {role} {name} geometry differs",
            )
            require(
                sha256_bytes(coff_body(coff, section))
                == pin[f"expected_{role}_body_sha256"],
                f"{context}: {role} {name} body pin differs",
            )
            require(
                sha256_bytes(_coff_table_bytes(
                    coff, section, "relocations"))
                == pin[f"expected_{role}_relocation_sha256"],
                f"{context}: {role} {name} relocation-table pin differs",
            )
        require_same_semantic_relocations(
            seed, left, donor, right, f"{context} {name}")
        expected_rows = (
            [(0, 4, 7)] if name == ".debug$F"
            else [(28, 4, 11), (32, 2, 10)]
        )
        expected_extra = (
            [] if name == ".debug$F" else
            pin.get("expected_extra_relocations", [])
        )
        for role, coff, section, primary in (
            ("seed", seed, left, seed_primary),
            ("donor", donor, right, donor_primary),
        ):
            rows = detailed_relocations(coff, section)
            require(
                len(rows) == len(expected_rows) + len(expected_extra)
                and all(
                    (row["offset"], row["width"], row["type"])
                    == expected
                    and row["addend"] == 0
                    and row["target"] == mangled
                    and row["target_section"] == primary["number"]
                    and row["target_value"] == 0
                    and row["target_type"] == 32
                    and row["target_storage"] == 2
                    for row, expected in zip(rows, expected_rows)
                ),
                f"{context}: {role} {name} semantic relocations differ",
            )
            require(
                all(
                    all(row[field] == expected[field] for field in (
                        "offset", "width", "type", "addend", "target",
                        "target_section", "target_value", "target_type",
                        "target_storage",
                    ))
                    for row, expected in zip(
                        rows[len(expected_rows):], expected_extra)
                ),
                f"{context}: {role} {name} extra semantic relocations "
                "differ",
            )
        pairs.append((left, right))

    seed_f = coff_body(seed, pairs[0][0])
    donor_f = coff_body(donor, pairs[0][1])
    fpo_pin = identity["debug_f"]["expected_record"]
    require(
        seed_f == donor_f
        and sha256_bytes(seed_f) == fpo_pin["raw_sha256"],
        f"{context}: FPO raw bytes differ",
    )
    require(
        exact_json_equal(
            parse_fpo_data(seed_f, expected_proc_size=seed_primary["raw_size"]),
            fpo_pin,
        )
        and exact_json_equal(
            parse_fpo_data(
                donor_f, expected_proc_size=donor_primary["raw_size"]),
            fpo_pin,
        ),
        f"{context}: parsed FPO record differs",
    )

    seed_s = coff_body(seed, pairs[1][0])
    donor_s = coff_body(donor, pairs[1][1])
    debug_pin = identity["debug_s"]
    require(
        len(seed_s) == debug_pin["expected_seed_raw_size"]
        and len(donor_s) == debug_pin["expected_donor_raw_size"]
        and seed_s[:28] == donor_s[:28]
        and sha256_bytes(seed_s[:28])
        == debug_pin["expected_common_prefix_sha256"]
        and seed_s[2:4].hex() == debug_pin["expected_record_kind"]
        and sha256_bytes(seed_s[28:])
        == debug_pin["expected_seed_tail_sha256"]
        and sha256_bytes(donor_s[28:])
        == debug_pin["expected_donor_tail_sha256"],
        f"{context}: CodeView procedure identity differs",
    )
    for role, raw in (("seed", seed_s), ("donor", donor_s)):
        cb_proc, dbg_start, dbg_end = struct.unpack_from("<III", raw, 16)
        require(
            (cb_proc, dbg_start, dbg_end) == (
                debug_pin["expected_cb_proc"],
                debug_pin["expected_dbg_start"],
                debug_pin["expected_dbg_end"],
            )
            and 0 <= dbg_start <= dbg_end < cb_proc,
            f"{context}: {role} CodeView procedure range differs",
        )
    return pairs


def _coff_table_bytes(coff: CoffObject, section: dict, kind: str) -> bytes:
    if kind == "relocations":
        start = section["relocation_offset"]
        size = section["relocation_count"] * 10
    else:
        start = section["line_offset"]
        size = section["line_count"] * 6
    return coff.data[start:start + size] if size else b""


def _coff_marker(coff: CoffObject, name: str, section_number: int):
    matches = [
        (index, symbol) for index, symbol in coff.symbols.items()
        if symbol["name"] == name and symbol["section"] == section_number
        and symbol["storage"] == 101 and symbol["aux_count"] >= 1
    ]
    require(len(matches) == 1,
            f"expected one {name} marker in section {section_number}")
    return matches[0]


def _coff_section_symbol(coff: CoffObject, section: dict):
    matches = [
        (index, symbol) for index, symbol in coff.symbols.items()
        if symbol["name"] == section["name"]
        and symbol["section"] == section["number"]
        and symbol["storage"] == 3 and symbol["aux_count"] >= 1
    ]
    require(len(matches) == 1, "expected one section definition symbol")
    return matches[0]


def _pair_same_slot_relocations(seed_rows, donor_rows, seed_primary,
                                donor_primary, seed_xdata, donor_xdata,
                                mapping, context):
    """Pair ordinal relocation semantics allowing offset movement and
    consistently mapped object-local symbols inside the target closure."""
    require(len(seed_rows) == len(donor_rows),
            f"{context}: relocation counts differ")
    reverse = {right: left for left, right in mapping.items()}

    def role(section_number, primary, xdata):
        if section_number == primary:
            return "primary"
        if section_number == xdata:
            return "xdata"
        return "external"

    pairs = []
    for left, right in zip(seed_rows, donor_rows):
        require(left["type"] == right["type"]
                and left["addend"] == right["addend"],
                f"{context}: relocation type/addend differs")
        require(
            role(left["target_section"], seed_primary, seed_xdata)
            == role(right["target_section"], donor_primary, donor_xdata),
            f"{context}: relocation target role differs",
        )
        left_local = local_symbol_kind(left["target"]) is not None
        right_local = local_symbol_kind(right["target"]) is not None
        if left_local or right_local:
            require(
                left_local and right_local
                and left["target"][1] == right["target"][1]
                and left["target_type"] == right["target_type"]
                and left["target_storage"] == right["target_storage"],
                f"{context}: local relocation target class differs",
            )
            if role(left["target_section"], seed_primary,
                    seed_xdata) in ("primary", "xdata"):
                require(
                    mapping.setdefault(left["symbol_index"],
                                       right["symbol_index"])
                    == right["symbol_index"]
                    and reverse.setdefault(right["symbol_index"],
                                           left["symbol_index"])
                    == left["symbol_index"],
                    f"{context}: local symbol mapping is inconsistent",
                )
            else:
                # An equal-valued local in a shared external section needs
                # no remapping: the seed's own symbol already denotes the
                # same location.
                require(
                    left["target_section"] == right["target_section"]
                    and left["target_value"] == right["target_value"],
                    f"{context}: external local relocation target differs",
                )
        else:
            require(
                left["target"] == right["target"]
                and left["target_type"] == right["target_type"]
                and left["target_storage"] == right["target_storage"],
                f"{context}: relocation target differs",
            )
        pairs.append((left, right))
    return pairs


def _resolve_substituted_seed_symbol(
    seed: CoffObject, donor_record: dict, context: str,
) -> int:
    """B5/B6: map a donor relocation's EXTERNAL target onto the seed's own
    symbol table, by name, unambiguously, with matching class.

    Compiler-local `$L`/`$T`/`$S` serials are deliberately NOT routed here --
    they are assigned per compile, are never present in the seed, and stay
    with the existing rename machinery (spec amendment 2).
    """
    name = donor_record["target"]
    require(local_symbol_kind(name) is None,
            f"{context}: compiler-local target {name!r} must not be remapped")
    matches = [
        (index, symbol) for index, symbol in seed.symbols.items()
        if symbol["name"] == name
    ]
    require(matches,
            f"{context}: donor relocation target {name!r} is not declared "
            f"or defined by the seed object")
    require(len(matches) == 1,
            f"{context}: ambiguous symbol remap for {name!r} -- "
            f"{len(matches)} seed symbols share the name")
    index, symbol = matches[0]
    require(
        symbol["type"] == donor_record["target_type"]
        and symbol["storage"] == donor_record["target_storage"],
        f"{context}: seed symbol {name!r} differs in type or storage class "
        f"(seed type=0x{symbol['type']:02x} storage={symbol['storage']}, "
        f"donor type=0x{donor_record['target_type']:02x} "
        f"storage={donor_record['target_storage']})",
    )
    return index


def _source_target_relocation_substitutions(
    seed: CoffObject, donor_rows: list[dict], mapping: dict[int, int],
    expected_imports: list[str], section_map: dict[int, int], context: str,
) -> tuple[dict[int, int], list[tuple[str, int, int]]]:
    """Resolve a whole donor target table into seed locals/externals."""
    reverse = {donor_index: seed_index
               for seed_index, donor_index in mapping.items()}
    imports = {}
    substitutions = {}
    for ordinal, record in enumerate(donor_rows):
        if local_symbol_kind(record["target"]) is not None:
            if record["symbol_index"] not in reverse:
                candidates = [
                    index for index, symbol in seed.symbols.items()
                    if local_symbol_kind(symbol["name"])
                    == local_symbol_kind(record["target"])
                    and symbol["section"]
                    == section_map.get(record["target_section"])
                    and symbol["value"] == record["target_value"]
                    and symbol["type"] == record["target_type"]
                    and symbol["storage"] == record["target_storage"]
                ]
                require(len(candidates) == 1,
                        f"{context}: target local has no unique seed structure")
                mapping[candidates[0]] = record["symbol_index"]
                reverse[record["symbol_index"]] = candidates[0]
            substitutions[ordinal] = reverse[record["symbol_index"]]
            continue
        matches = [index for index, symbol in seed.symbols.items()
                   if symbol["name"] == record["target"]]
        if matches:
            substitutions[ordinal] = _resolve_substituted_seed_symbol(
                seed, record, context
            )
            continue
        name = record["target"]
        require(name in expected_imports
                and record["target_value"] == 0
                and record["target_type"] == 0x20
                and record["target_storage"] == 2,
                f"{context}: donor target {name!r} is absent from the seed")
        imports.setdefault(
            name, (name, record["target_type"], record["target_storage"])
        )
        substitutions[ordinal] = seed.symbol_count + expected_imports.index(name)
    require(sorted(imports) == expected_imports,
            f"{context}: imported undefined symbol set differs")
    return substitutions, [imports[name] for name in expected_imports]


def _append_undefined_external_symbols(
    data: bytes, symbols: list[tuple[str, int, int]],
) -> bytes:
    if not symbols:
        return data
    coff = CoffObject(data)
    strings = bytearray(data[coff.string_offset:coff.string_end])
    records = bytearray()
    for name, symbol_type, storage in symbols:
        encoded = name.encode("ascii")
        if len(encoded) <= 8:
            name_field = encoded.ljust(8, b"\0")
        else:
            name_field = b"\0\0\0\0" + len(strings).to_bytes(4, "little")
            strings.extend(encoded + b"\0")
        records.extend(name_field + struct.pack("<IhHBB", 0, 0, symbol_type,
                                                storage, 0))
    strings[:4] = len(strings).to_bytes(4, "little")
    output = bytearray(data[:coff.string_offset] + records + strings)
    output[12:16] = (coff.symbol_count + len(symbols)).to_bytes(4, "little")
    return bytes(output)


def _pair_reloc_divergent(seed, donor, seed_rows, donor_rows, seed_primary,
                          donor_primary, seed_xdata, donor_xdata, mapping,
                          context):
    """Pair the primary table allowing a divergent EXTERNAL target set.

    Identical to `_pair_same_slot_relocations` except that where both sides
    name ordinary (non-local) symbols and those names DIFFER, the ordinal is
    recorded as a substitution and the donor's target is resolved into the
    seed's symbol table under B5/B6.  Returns (pairs, substitutions) where
    substitutions maps the ordinal index to the seed symbol index to write.
    """
    # B7 -- the count-divergent path.  The donor may carry MORE relocations
    # than the seed (retail calls where we inline), in which case the seed's
    # rows must pair with a PREFIX of the donor's and every extra donor row is
    # appended.  A non-trailing divergence would mean the two tables describe
    # different code at the same ordinals, so it is refused loudly rather than
    # paired by position.
    require(len(donor_rows) >= len(seed_rows),
            f"{context}: the donor carries FEWER relocations than the seed; "
            f"the shrinking path is not implemented")
    appended_rows = donor_rows[len(seed_rows):]
    donor_rows = donor_rows[:len(seed_rows)]
    reverse = {right: left for left, right in mapping.items()}

    def role(section_number, primary, xdata):
        if section_number == primary:
            return "primary"
        if section_number == xdata:
            return "xdata"
        return "external"

    pairs = []
    substitutions: dict[int, int] = {}
    for ordinal, (left, right) in enumerate(zip(seed_rows, donor_rows)):
        require(left["type"] == right["type"],
                f"{context}: relocation type differs")
        left_local = local_symbol_kind(left["target"]) is not None
        right_local = local_symbol_kind(right["target"]) is not None
        if left_local or right_local:
            require(left["addend"] == right["addend"],
                    f"{context}: relocation addend differs")
            require(
                role(left["target_section"], seed_primary, seed_xdata)
                == role(right["target_section"], donor_primary, donor_xdata),
                f"{context}: relocation target role differs",
            )
            require(
                left_local and right_local
                and left["target"][1] == right["target"][1]
                and left["target_type"] == right["target_type"]
                and left["target_storage"] == right["target_storage"],
                f"{context}: local relocation target class differs",
            )
            if role(left["target_section"], seed_primary,
                    seed_xdata) in ("primary", "xdata"):
                require(
                    mapping.setdefault(left["symbol_index"],
                                       right["symbol_index"])
                    == right["symbol_index"]
                    and reverse.setdefault(right["symbol_index"],
                                           left["symbol_index"])
                    == left["symbol_index"],
                    f"{context}: local symbol mapping is inconsistent",
                )
            else:
                left_section_number = left["target_section"]
                right_section_number = right["target_section"]
                require(
                    0 < left_section_number <= len(seed.sections)
                    and right_section_number <= len(donor.sections)
                    and left_section_number == right_section_number
                    and left["target_value"] == right["target_value"],
                    f"{context}: external local relocation target differs",
                )
                # A same-seat/value compiler local is only interchangeable
                # when the shared section it names is itself identical.  The
                # relocation mask must never turn a merely coincident seat
                # into a semantic-equivalence claim.
                left_section = seed.sections[left_section_number - 1]
                right_section = donor.sections[right_section_number - 1]
                left_definition = section_definitions(seed).get(
                    left_section_number)
                right_definition = section_definitions(donor).get(
                    right_section_number)
                require(
                    all(left_section[key] == right_section[key] for key in (
                        "name", "raw_size", "relocation_count", "line_count",
                        "characteristics",
                    ))
                    and coff_body(seed, left_section)
                    == coff_body(donor, right_section)
                    and _coff_table_bytes(seed, left_section, "relocations")
                    == _coff_table_bytes(donor, right_section, "relocations")
                    and _coff_table_bytes(seed, left_section, "lines")
                    == _coff_table_bytes(donor, right_section, "lines")
                    and left_definition is not None
                    and right_definition is not None
                    and left_definition["raw"] == right_definition["raw"],
                    f"{context}: external local target section differs",
                )
        elif left["target"] == right["target"]:
            require(left["addend"] == right["addend"],
                    f"{context}: relocation addend differs")
            require(
                left["target_type"] == right["target_type"]
                and left["target_storage"] == right["target_storage"],
                f"{context}: relocation target class differs",
            )
            require(
                _resolve_substituted_seed_symbol(seed, right, context)
                == left["symbol_index"],
                f"{context}: same-name relocation target is ambiguous or "
                "does not name the paired seed symbol",
            )
        else:
            # The divergence this class exists for: retail calls a function
            # where we inline it (or the reverse).  B1 is what proves the
            # substitution is retail's own, so nothing is inferred here --
            # only that the seed can name the donor's target.
            substitutions[ordinal] = _resolve_substituted_seed_symbol(
                seed, right, context)
        pairs.append((left, right))
    # Each appended donor row must be an ORDINARY target the seed can already
    # name (B5/B6).  A compiler-local extra would need a symbol the seed does
    # not have, which this class does not invent.
    appended: list[tuple[dict, int]] = []
    for extra_index, record in enumerate(appended_rows):
        where = f"{context} appended relocation {extra_index}"
        require(local_symbol_kind(record["target"]) is None,
                f"{where}: appended compiler-local target "
                f"{record['target']!r} has no seed symbol to name it")
        appended.append(
            (record, _resolve_substituted_seed_symbol(seed, record, where))
        )
    return pairs, substitutions, appended


def compose_same_slot_resize(
    seed_bytes: bytes,
    donor_bytes: bytes,
    function: dict,
    *,
    retail_body: bytes | None = None,
    target_closure_extract: bool = False,
    source_target_extract: bool = False,
) -> tuple[bytes, dict]:
    """Install a donor code body of a different size that occupies the same
    16-byte linked contribution slot, repairing every dependent COFF record.

    The seed supplies the object, symbol table, CodeView types/names, xdata
    raw bytes/relocations, and every non-target section.  The donor supplies
    the compiler-generated target code, COFF line offsets, and procedure
    debug range.  Mapped object-local symbol values move to the donor's.

    ``retail_body`` selects a retail-exact class: the donor's EXTERNAL
    relocation target set may then differ from the seed's, and the composed
    body is required to be byte-identical to retail's own code under the
    relocation mask (B1).  ``target_closure_extract`` replaces only the two
    whole-donor topology guards with a pinned strict-subset proof; every
    target-closure and output-conservation guard remains shared.
    """
    splice_class = function.get("splice_class")
    require(splice_class in (
        "same_slot_resize", "retail_exact_reloc_divergent",
        "retail_exact_target_closure", "retail_exact_source_target_closure",
    ), "same-slot composer received an unsupported splice class")
    expected_divergent = splice_class != "same_slot_resize"
    expected_extract = splice_class == "retail_exact_target_closure"
    expected_source_extract = (
        splice_class == "retail_exact_source_target_closure"
    )
    require((retail_body is not None) == expected_divergent,
            "retail oracle presence differs from the splice class")
    require(target_closure_extract == expected_extract,
            "target-closure topology mode differs from the splice class")
    require(source_target_extract == expected_source_extract,
            "source-target topology mode differs from the splice class")
    divergent = expected_divergent
    seed = CoffObject(seed_bytes)
    donor = CoffObject(donor_bytes)
    mangled = function["mangled"]
    sp = seed.function_section(mangled)
    dp = donor.function_section(mangled)
    require(sp["raw_size"] == function["expected_seed_length"]
            and dp["raw_size"] == function["expected_donor_length"],
            "target body lengths changed")
    require(
        ((dp["raw_size"] + 15) // 16) * 16
        == function["expected_linked_span"],
        "donor 16-byte linked contribution span changed",
    )
    require(sp["number"] == dp["number"],
            "target section seat changed")
    # Ordinary carrier donors must be whole-object-equivalent.  A target-only
    # donor may omit a pinned strict subset because the composed output keeps
    # every original seed definition and copies only this target closure.
    topology_detail = {}
    if source_target_extract:
        topology_detail = require_source_target_closure_topology(
            seed, donor, function, "source-target closure extraction"
        )
    elif target_closure_extract:
        topology_detail = require_target_closure_extraction_topology(
            seed, donor, function, "target-closure extraction"
        )
    else:
        require(len(seed.sections) == len(donor.sections),
                "global section count differs")
        require(function_multiset(seed) == function_multiset(donor),
                "donor function set differs")
    require(
        all(sp[key] == dp[key] for key in ("name", "characteristics")),
        "target header shape changed",
    )
    # Under the divergent class the primary relocation COUNT may in principle
    # move; the substitution path this implements requires it to hold, and
    # `_pair_reloc_divergent` refuses with a message naming B7 if it does not.
    require(divergent or sp["relocation_count"] == dp["relocation_count"],
            "target header shape changed")
    if ("expected_seed_line_count" in function
            or "expected_donor_line_count" in function):
        require(sp["line_count"] == function["expected_seed_line_count"]
                and dp["line_count"] == function["expected_donor_line_count"],
                "target COFF line counts differ from their split pins")
    else:
        require(sp["line_count"] == dp["line_count"],
                "target header shape changed")
    seed_defs = section_definitions(seed)
    donor_defs = section_definitions(donor)
    require(
        seed_defs[sp["number"]]["selection"]
        == donor_defs[dp["number"]]["selection"],
        "target COMDAT selection changed",
    )
    closure = _comdat_child_closure(seed, seed_primary := sp)
    require(closure == _comdat_child_closure(donor, dp)
            and closure in ((2, (".debug$S", ".xdata$x")),
                            (2, (".debug$F", ".debug$S"))),
            "target closure is not an EH or FPO debug pair")
    fpo_closure = closure == (2, (".debug$F", ".debug$S"))
    if fpo_closure:
        sx = _comdat_child(seed, sp, ".debug$F")
        dx = _comdat_child(donor, dp, ".debug$F")
    else:
        sx = _comdat_child(seed, sp, ".xdata$x")
        dx = _comdat_child(donor, dp, ".xdata$x")
    sd = _comdat_child(seed, sp, ".debug$S")
    dd = _comdat_child(donor, dp, ".debug$S")
    require(sx["number"] == dx["number"] and sd["number"] == dd["number"],
            "closure section seats changed")
    # D1.  `raw_size` equality on the `.debug$S` closure child is a
    # same-function sanity proxy: no donor `.debug$S` byte ever reaches the
    # output.  A source refactor that removes a caller local legitimately
    # shortens that child, so the equality may be replaced -- but ONLY by a
    # pinned, source-bound local-set delta that proves record by record what
    # was removed, proves it is a removal, proves it moves no relocated span,
    # proves the surviving record sequence is the donor's, and makes the
    # composed output drop the stale records.  Every other field of the tuple,
    # and the whole tuple for the sibling child, is unchanged.
    local_set_delta = function.get("local_set_delta")
    local_set_detail = {}
    reduced_debug_raw = None
    debug_shape_keys = ("name", "raw_size", "relocation_count", "line_count",
                        "characteristics")
    if local_set_delta is not None:
        require("target_source_refactor" in function
                and function["target_source_refactor"]["kind"]
                in LOCAL_SET_DELTA_REFACTOR_KINDS,
                "local-set delta is outside its closed source-refactor kinds")
        debug_shape_keys = ("name", "relocation_count", "line_count",
                            "characteristics")
    for left, right, name, keys in (
        (sx, dx, "xdata",
         ("name", "raw_size", "relocation_count", "line_count",
          "characteristics")),
        (sd, dd, "debug$S", debug_shape_keys),
    ):
        require(
            all(left[key] == right[key] for key in keys),
            f"{name} section shape changed",
        )
    if local_set_delta is not None:
        local_set_detail, reduced_debug_raw = (
            require_removed_caller_locals_delta(
                coff_body(seed, sd), coff_body(donor, dd),
                [item["offset"] for item in detailed_relocations(seed, sd)],
                local_set_delta, "debug$S local-set delta",
            )
        )
    if fpo_closure:
        # The donor's FPO record describes the donor body; adopt it whole
        # after proving both records parse with their own body sizes.
        parse_fpo_data(coff_body(seed, sx),
                       expected_proc_size=sp["raw_size"])
        donor_fpo = coff_body(donor, dx)
        parse_fpo_data(donor_fpo, expected_proc_size=dp["raw_size"])
    else:
        require(coff_body(seed, sx) == coff_body(donor, dx),
                "runtime xdata bytes differ")

    donor_code = coff_body(donor, dp)
    require(sha256_bytes(donor_code) == function["expected_body_sha256"],
            "donor body differs from its pinned compiler output")

    spr = detailed_relocations(seed, sp)
    dpr = detailed_relocations(donor, dp)
    sxr = detailed_relocations(seed, sx)
    dxr = detailed_relocations(donor, dx)
    sdr = detailed_relocations(seed, sd)
    ddr = detailed_relocations(donor, dd)
    mapping: dict[int, int] = {}
    substitutions: dict[int, int] = {}
    appended_relocations: list[tuple[dict, int]] = []
    imported_symbols: list[tuple[str, int, int]] = []
    xdata_pairs = _pair_same_slot_relocations(
        sxr, dxr, sp["number"], dp["number"], sx["number"], dx["number"],
        mapping, "xdata")
    debug_pairs = _pair_same_slot_relocations(
        sdr, ddr, sp["number"], dp["number"], sx["number"], dx["number"],
        mapping, "debug$S")
    if divergent:
        # B1 -- THE LOAD-BEARING OBLIGATION.  This class may only ever install
        # retail's own code, so the body is compared against retail before any
        # of it is written anywhere.  The build performs the pinned extraction
        # from the sha256-pinned image; here we enforce length and mask.
        pinned_length = function["retail_oracle"]["length"]
        require(len(retail_body) == pinned_length,
                f"retail oracle body length {len(retail_body)} differs from "
                f"its pinned length {pinned_length}")
        require(len(donor_code) == len(retail_body),
                f"composed body length {len(donor_code)} differs from the "
                f"retail oracle length {len(retail_body)}")
        semantic_detail = require_retail_relocation_oracle(
            dpr, retail_body, int(function["retail_oracle"]["address"], 16),
            function["retail_relocations"], "retail relocation oracle",
        )
        masked_donor = bytearray(donor_code)
        masked_retail = bytearray(retail_body)
        for record in dpr:
            start, width = record["offset"], record["width"]
            masked_donor[start:start + width] = b"\0" * width
            masked_retail[start:start + width] = b"\0" * width
        differing = sum(1 for a, b in zip(masked_donor, masked_retail)
                        if a != b)
        require(differing == 0,
                f"composed body is not retail-exact: {differing} byte(s) "
                f"differ from the retail oracle under the relocation mask")
        if source_target_extract:
            require(len(spr) == len(dpr),
                    "source-target relocation table count changed")
            substitutions, imported_symbols = (
                _source_target_relocation_substitutions(
                    seed, dpr, mapping,
                    function["expected_imported_undefined_symbols"],
                    {dp["number"]: sp["number"], dx["number"]: sx["number"]},
                    "source-target primary",
                )
            )
        else:
            _, substitutions, appended_relocations = _pair_reloc_divergent(
                seed, donor, spr, dpr, sp["number"], dp["number"],
                sx["number"], dx["number"], mapping, "primary")
    else:
        semantic_detail = {}
        _pair_same_slot_relocations(spr, dpr, sp["number"], dp["number"],
                                    sx["number"], dx["number"], mapping,
                                    "primary")
    require(all(a["offset"] == b["offset"] for a, b in xdata_pairs),
            "xdata relocation offsets moved")
    require(all(a["offset"] == b["offset"] for a, b in debug_pairs),
            "debug$S relocation offsets moved")
    allowed_sections = {sp["number"], sx["number"], sd["number"]}
    for section in seed.sections:
        for record in (detailed_relocations(seed, section)
                       if section["relocation_count"]
                       and section["number"] not in allowed_sections else []):
            require(record["symbol_index"] not in mapping,
                    "mapped local is consumed outside the target closure")
    for seed_index, donor_index in mapping.items():
        left = seed.symbols[seed_index]
        right = donor.symbols[donor_index]
        require(
            (left["section"], left["type"], left["storage"])
            == (right["section"], right["type"], right["storage"]),
            "mapped local symbol class changed",
        )

    seed_function_index, seed_function = function_symbol(
        seed, mangled, sp["number"])
    donor_function_index, donor_function = function_symbol(
        donor, mangled, dp["number"])
    require(sp["line_count"] > 0 and dp["line_count"] > 0,
            "target COFF line count changed")
    seed_lines = _coff_table_bytes(seed, sp, "lines")
    donor_lines = bytearray(_coff_table_bytes(donor, dp, "lines"))
    require(
        coff_unpack("<IH", seed_lines, 0, "seed line sentinel")
        == (seed_function_index, 0)
        and coff_unpack("<IH", donor_lines, 0, "donor line sentinel")
        == (donor_function_index, 0),
        "COFF line sentinel is invalid",
    )
    donor_lines[0:4] = seed_function_index.to_bytes(4, "little")
    previous = -1
    for index in range(1, dp["line_count"]):
        offset, line = coff_unpack("<IH", bytes(donor_lines), index * 6,
                                   "donor line row")
        require(line != 0 and previous <= offset < dp["raw_size"],
                "donor COFF line row is outside/nonmonotonic")
        previous = offset
    donor_lines = bytes(donor_lines)

    seed_debug_raw = coff_body(seed, sd)
    donor_debug_raw = coff_body(donor, dd)
    require(len(seed_debug_raw) >= 28 and seed_debug_raw[2:4] == b"\x05\x02"
            and donor_debug_raw[2:4] == b"\x05\x02",
            "debug$S is not an S_*PROC32 record")
    donor_cbproc, donor_dbgstart, donor_dbgend = coff_unpack(
        "<III", donor_debug_raw, 16, "donor debug range")
    require(donor_cbproc == dp["raw_size"]
            and 0 <= donor_dbgstart <= donor_dbgend < donor_cbproc,
            "donor debug procedure range is stale")
    expected_debug_raw = bytearray(
        seed_debug_raw if reduced_debug_raw is None else reduced_debug_raw)
    expected_debug_raw[16:28] = donor_debug_raw[16:28]

    old_end = sp["raw_offset"] + sp["raw_size"]
    replacements = [
        (sp["raw_offset"], old_end, donor_code),
        (
            sp["line_offset"],
            sp["line_offset"] + sp["line_count"] * 6,
            donor_lines,
        ),
    ]
    if reduced_debug_raw is not None:
        # D1 obligation (8): the composed object stops claiming a local its
        # installed body does not have.
        replacements.append((
            sd["raw_offset"], sd["raw_offset"] + sd["raw_size"],
            bytes(expected_debug_raw),
        ))
    if appended_relocations:
        # B7: the donor carries relocations the seed's table has no room for,
        # so the table is rebuilt rather than overwritten in place.  Paired
        # ordinals keep the seed's symbol index (or its substitution); each
        # appended row names the seed symbol resolved for the donor's target.
        grown = bytearray()
        for index, (left, right) in enumerate(zip(spr, dpr)):
            grown += right["offset"].to_bytes(4, "little")
            grown += substitutions.get(
                index, left["symbol_index"]).to_bytes(4, "little")
            grown += right["type"].to_bytes(2, "little")
        for record, seed_symbol_index in appended_relocations:
            grown += record["offset"].to_bytes(4, "little")
            grown += seed_symbol_index.to_bytes(4, "little")
            grown += record["type"].to_bytes(2, "little")
        require(len(grown) == dp["relocation_count"] * 10,
                "rebuilt relocation table size does not match the donor count")
        replacements.append((
            sp["relocation_offset"],
            sp["relocation_offset"] + sp["relocation_count"] * 10,
            bytes(grown),
        ))
    total_delta = sum(len(replacement) - (end - start)
                      for start, end, replacement in replacements)

    def shifted(pointer: int) -> int:
        return shifted_pointer(pointer, replacements)

    output = bytearray(apply_replacements(seed_bytes, replacements))
    new_symbol_offset = shifted(seed.symbol_offset)
    output[8:12] = new_symbol_offset.to_bytes(4, "little")

    for section in seed.sections:
        header = 20 + (section["number"] - 1) * 40
        if section["number"] == sp["number"]:
            output[header + 16:header + 20] = dp["raw_size"].to_bytes(
                4, "little")
            output[header + 34:header + 36] = dp["line_count"].to_bytes(
                2, "little")
            if appended_relocations:
                output[header + 32:header + 34] = (
                    dp["relocation_count"].to_bytes(2, "little"))
        if (reduced_debug_raw is not None
                and section["number"] == sd["number"]):
            output[header + 16:header + 20] = len(
                expected_debug_raw).to_bytes(4, "little")
        for field, relative in (("raw_offset", 20),
                                ("relocation_offset", 24),
                                ("line_offset", 28)):
            pointer = shifted(section[field])
            if pointer != section[field]:
                output[header + relative:header + relative + 4] = (
                    pointer.to_bytes(4, "little"))

    primary_relocation_output = shifted(sp["relocation_offset"])
    for index, (left, right) in enumerate(
            [] if appended_relocations else zip(spr, dpr)):
        at = primary_relocation_output + index * 10
        # A substituted ordinal must name the SEED's symbol for the DONOR's
        # target, not the seed's own former target -- that is the whole point
        # of the class.  Every other ordinal keeps the seed's index.
        symbol_index = substitutions.get(index, left["symbol_index"])
        output[at:at + 4] = right["offset"].to_bytes(4, "little")
        output[at + 4:at + 8] = symbol_index.to_bytes(4, "little")
        output[at + 8:at + 10] = right["type"].to_bytes(2, "little")

    for symbol_index, item in seed.symbols.items():
        if item["type"] != 0x20 or item["aux_count"] < 1:
            continue
        auxiliary = coff_auxiliary(seed, symbol_index, item)
        line_pointer = int.from_bytes(auxiliary[8:12], "little")
        mapped = shifted(line_pointer) if line_pointer else line_pointer
        if mapped != line_pointer:
            at = new_symbol_offset + (symbol_index + 1) * 18
            output[at + 8:at + 12] = mapped.to_bytes(4, "little")

    local_value_updates = 0
    for seed_index, donor_index in sorted(mapping.items()):
        value = donor.symbols[donor_index]["value"]
        if value != seed.symbols[seed_index]["value"]:
            local_value_updates += 1
        at = new_symbol_offset + seed_index * 18
        output[at + 8:at + 12] = value.to_bytes(4, "little")

    donor_function_aux = coff_auxiliary(donor, donor_function_index,
                                        donor_function)
    require(int.from_bytes(donor_function_aux[4:8], "little")
            == dp["raw_size"],
            "donor Function Definition TotalSize is stale")
    at = new_symbol_offset + (seed_function_index + 1) * 18
    output[at + 4:at + 8] = dp["raw_size"].to_bytes(4, "little")

    seed_begin_index, seed_begin = _coff_marker(seed, ".bf", sp["number"])
    donor_begin_index, donor_begin = _coff_marker(donor, ".bf", dp["number"])
    seed_begin_aux = coff_auxiliary(seed, seed_begin_index, seed_begin)
    donor_begin_aux = coff_auxiliary(donor, donor_begin_index, donor_begin)
    # The seed's .bf aux keeps BOTH its absolute line base (the donor's is
    # shifted by any prefix carrier) and its next-.bf chain tail; only the
    # non-line metadata must agree.
    require(seed_begin_aux[:4] == donor_begin_aux[:4]
            and seed_begin_aux[6:12] == donor_begin_aux[6:12]
            and seed_begin_aux[16:] == donor_begin_aux[16:],
            ".bf non-line metadata changed")

    seed_end_index, seed_end = _coff_marker(seed, ".ef", sp["number"])
    donor_end_index, donor_end = _coff_marker(donor, ".ef", dp["number"])
    require(donor_end["value"] == dp["raw_size"], "donor .ef value is stale")
    seed_end_aux = coff_auxiliary(seed, seed_end_index, seed_end)
    donor_end_aux = coff_auxiliary(donor, donor_end_index, donor_end)
    require(seed_end_aux[:4] == donor_end_aux[:4]
            and seed_end_aux[6:] == donor_end_aux[6:],
            ".ef non-line metadata changed")
    at = new_symbol_offset + seed_end_index * 18
    output[at + 8:at + 12] = donor_end["value"].to_bytes(4, "little")

    # The .lf marker carries the function's COFF line-row count; LINK reads
    # exactly that many rows.  When the donor table has a different row count
    # the seed's stale value makes LINK read past (or short of) the donor
    # table and drop the function's line information, which in turn makes
    # the row unmatchable by file:line.  Carry the donor's count.
    seed_lf = [
        (index, symbol) for index, symbol in seed.symbols.items()
        if symbol["name"] == ".lf" and symbol["section"] == sp["number"]
        and symbol["storage"] == 101
    ]
    donor_lf = [
        (index, symbol) for index, symbol in donor.symbols.items()
        if symbol["name"] == ".lf" and symbol["section"] == dp["number"]
        and symbol["storage"] == 101
    ]
    require(len(seed_lf) == len(donor_lf) <= 1,
            "target .lf line-count markers differ in presence")
    if seed_lf:
        seed_lf_index, seed_lf_symbol = seed_lf[0]
        _, donor_lf_symbol = donor_lf[0]
        require(seed_lf_symbol["value"] == sp["line_count"]
                and donor_lf_symbol["value"] == dp["line_count"],
                ".lf line-count marker is stale")
        at = new_symbol_offset + seed_lf_index * 18
        output[at + 8:at + 12] = donor_lf_symbol["value"].to_bytes(
            4, "little")

    seed_section_index, seed_section_sym = _coff_section_symbol(seed, sp)
    donor_section_index, donor_section_sym = _coff_section_symbol(donor, dp)
    at = new_symbol_offset + (seed_section_index + 1) * 18
    output[at:at + 18] = coff_auxiliary(donor, donor_section_index,
                                        donor_section_sym)
    if reduced_debug_raw is not None:
        # The section header is not the only place that states the child's
        # size: its COMDAT section symbol's auxiliary Length must agree, or
        # the composed object would still claim the removed record through
        # the symbol table.  Relocation and line counts are untouched by a
        # local-set removal, so only Length moves.
        debug_section_index, _ = _coff_section_symbol(seed, sd)
        aux_at = new_symbol_offset + (debug_section_index + 1) * 18
        output[aux_at:aux_at + 4] = len(expected_debug_raw).to_bytes(
            4, "little")

    debug_output = shifted(sd["raw_offset"])
    output[debug_output:debug_output + len(expected_debug_raw)] = (
        expected_debug_raw)
    if fpo_closure:
        fpo_output = shifted(sx["raw_offset"])
        output[fpo_output:fpo_output + len(donor_fpo)] = donor_fpo
    composed = _append_undefined_external_symbols(bytes(output),
                                                  imported_symbols)
    total_delta += len(composed) - len(output)

    checked = CoffObject(composed)
    cp = checked.function_section(mangled)
    require(len(composed) == len(seed_bytes) + total_delta,
            "output file-size delta is wrong")
    require(coff_body(checked, cp) == donor_code,
            "output target body differs from donor")
    cx = _comdat_child(checked, cp,
                       ".debug$F" if fpo_closure else ".xdata$x")
    cd = _comdat_child(checked, cp, ".debug$S")
    require(coff_body(checked, cx)
            == (donor_fpo if fpo_closure else coff_body(seed, sx)),
            "output xdata/FPO record differs from its policy source")
    require(coff_body(checked, cd) == bytes(expected_debug_raw),
            "output debug$S policy differs")
    if reduced_debug_raw is not None:
        checked_debug_index, checked_debug_symbol = _coff_section_symbol(
            checked, cd)
        require(
            int.from_bytes(
                coff_auxiliary(checked, checked_debug_index,
                               checked_debug_symbol)[:4], "little")
            == cd["raw_size"] == len(expected_debug_raw),
            "output debug$S section symbol still claims the removed locals",
        )
    require(function_multiset(checked) == function_multiset(seed),
            "output function set changed")
    require(checked.symbol_count == seed.symbol_count + len(imported_symbols)
            and all(
                checked.symbols[seed.symbol_count + index]["name"] == item[0]
                and checked.symbols[seed.symbol_count + index]["section"] == 0
                and checked.symbols[seed.symbol_count + index]["value"] == 0
                and checked.symbols[seed.symbol_count + index]["type"]
                == item[1]
                and checked.symbols[seed.symbol_count + index]["storage"]
                == item[2]
                for index, item in enumerate(imported_symbols)
            ), "output imported undefined symbol set changed")
    require(_coff_table_bytes(checked, cp, "lines") == donor_lines,
            "output line table differs from the normalized donor")
    require(_coff_table_bytes(checked, cx, "relocations")
            == _coff_table_bytes(seed, sx, "relocations"),
            "output xdata relocation records changed")
    require(_coff_table_bytes(checked, cd, "relocations")
            == _coff_table_bytes(seed, sd, "relocations"),
            "output debug$S relocation records changed")
    for before, after in zip(seed.sections, checked.sections):
        if before["number"] in allowed_sections:
            continue
        require(coff_body(seed, before) == coff_body(checked, after),
                f"non-target raw section changed: {before['number']}")
        require(_coff_table_bytes(seed, before, "relocations")
                == _coff_table_bytes(checked, after, "relocations"),
                f"non-target relocation table changed: {before['number']}")
        require(_coff_table_bytes(seed, before, "lines")
                == _coff_table_bytes(checked, after, "lines"),
                f"non-target line table changed: {before['number']}")
    if divergent:
        # Prove the substitution actually landed: the composed table must now
        # name the donor's targets, resolved into the seed's symbol table.
        composed_rows = detailed_relocations(checked, cp)
        require(len(composed_rows) == len(dpr),
                "composed relocation count differs from the donor's")
        for left, right in zip(composed_rows, dpr):
            # Compiler-local targets legitimately keep the SEED's symbol: the
            # mapping moves its VALUE, not its name.  Only ordinary symbols
            # must now read as the donor's.
            if local_symbol_kind(right["target"]) is not None:
                require(local_symbol_kind(left["target"])
                        == local_symbol_kind(right["target"]),
                        f"composed local relocation class changed at "
                        f"offset {left['offset']}")
                continue
            require(left["target"] == right["target"],
                    f"composed relocation target {left['target']!r} is not "
                    f"the donor's {right['target']!r}")
    return composed, {
        "mangled": mangled,
        "splice_class": (function["splice_class"] if divergent
                         else "same_slot_resize"),
        "section_number": cp["number"],
        "seed_length": sp["raw_size"],
        "donor_length": dp["raw_size"],
        "file_size_delta": total_delta,
        "linked_span": function["expected_linked_span"],
        "mapped_locals": len(mapping),
        "changed_local_values": local_value_updates,
        "substituted_relocations": len(substitutions),
        "imported_undefined_symbols": [item[0] for item in imported_symbols],
        "retail_exact": bool(divergent),
        **local_set_detail,
        **topology_detail,
        **semantic_detail,
    }


def _source_overlay_generators(node: object):
    """Yield every validated generator in an operation, sequences included."""
    if isinstance(node, dict):
        if "kind" in node and "params" in node:
            yield node
            yield from _source_overlay_generators(node["params"])
            return
        for value in node.values():
            yield from _source_overlay_generators(value)
    elif isinstance(node, list):
        for value in node:
            yield from _source_overlay_generators(value)


def assert_member_signature_is_donor_only(overlay: object) -> None:
    """A7d: the member-signature generator may never appear in the SHIPPED
    tree's rendering -- only in a donor rendering.  Asserted, not assumed."""
    for generator in _source_overlay_generators(overlay):
        require(
            generator.get("kind") != "member_signature_v1",
            "member_signature_v1 appears in the shipped tree's source "
            "overlay; A7d restricts it to donor renderings",
        )


def assert_source_permutations_are_donor_only(overlay: object) -> None:
    """Bind-once source permutations describe donor alternatives.

    They may feed a target-only retail-exact composition, but may never alter
    the source rendering compiled directly into the shipped object graph.
    """
    for generator in _source_overlay_generators(overlay):
        require(
            generator.get("kind") not in {
                "single_evaluation_binding_source_permutation_v1",
                "for_initializer_declaration_reseat_v1",
                "captured_pointer_tail_return_fragment_v1",
                "fixed_array_fill_loop_v1",
                "fixed_array_shuffle_pointer_countdown_v1",
                "inclusive_extent_assignment_v1",
                "discarded_postfix_increment_v1",
                "dead_local_linear_updates_v1",
                "inline_default_constructor_dead_updates_v1",
            },
            f"{generator.get('kind')} appears in the shipped tree's source "
            "overlay; it is donor-only",
        )


def validate_donor_object_excluded(
    composed_object: bytes, donor_objects,
) -> None:
    """A4: a donor object is a BYTE SOURCE only and must never enter the link.

    Asserted rather than left to convention: the object handed to the linker
    must not be any donor object.  A donor is compiled from a rendering that
    deliberately differs from the shipped tree, so linking one would ship code
    that no checked-in source produces.
    """
    composed_sha = sha256_bytes(composed_object)
    for index, donor in enumerate(donor_objects):
        require(
            sha256_bytes(donor) != composed_sha,
            f"donor object {index} reached the link: the object being linked "
            f"is byte-identical to a donor, which is a byte source only",
        )


def validate_clean_current_source_cross_tu_recipe(
    recipe: object,
    root,
    owner_source: str,
    overlaid_paths: set[str],
    context: str,
) -> dict:
    """Validate an unmodified checked-in translation-unit donor.

    This recipe has no payload generator at all.  Its content identity is the
    pinned checked-in source, and the build must compile it through the one
    ordinary command lane selected here.  An effective source overlay would
    make the "clean" claim false, so even a typed overlay is rejected.
    """
    require(isinstance(recipe, dict), f"{context} must be an object")
    exact_audit_keys(recipe, {
        "kind", "donor_source", "source_sha256", "compile_lane",
        "emission_policy", "authenticity_rationale",
    }, context)
    require(recipe.get("kind") == CLEAN_CURRENT_SOURCE_CROSS_TU_RECIPE,
            f"{context}.kind differs")
    source = source_overlay_relative_path(
        recipe.get("donor_source"), context + ".donor_source")
    require(PurePosixPath(source).suffix.casefold()
            in {".c", ".cc", ".cpp", ".cxx"},
            f"{context}.donor_source is not a translation unit")
    require(source != owner_source,
            f"{context}.donor_source is not cross-translation-unit")
    require(source not in overlaid_paths,
            f"{context}.donor_source has an effective source overlay")
    source_sha = require_sha(recipe.get("source_sha256"),
                             context + ".source_sha256")
    canonical_root = Path(root).resolve(strict=True)
    source_path = source_overlay_logical_path(canonical_root, source)
    try:
        metadata = source_path.lstat()
        resolved_source = source_path.resolve(strict=True)
    except OSError as error:
        raise ByteIdentityError(
            f"{context}.donor_source is absent or redirected: {error}"
        ) from error
    require(
        stat.S_ISREG(metadata.st_mode)
        and not source_path.is_symlink()
        and resolved_source == source_path
        and resolved_source.is_relative_to(canonical_root),
        f"{context}.donor_source is redirected or non-regular",
    )
    require(sha256_file(source_path) == source_sha,
            f"{context}.donor_source differs from its checked-in pin")
    lane = recipe.get("compile_lane")
    require(isinstance(lane, dict)
            and set(lane) == {"required_define"}
            and isinstance(lane.get("required_define"), str)
            and lane["required_define"],
            f"{context}.compile_lane differs")
    require(recipe.get("emission_policy")
            == "unmodified_checked_in_translation_unit_only",
            f"{context}.emission_policy differs")
    rationale = recipe.get("authenticity_rationale")
    require(isinstance(rationale, str) and len(rationale) >= 32,
            f"{context}.authenticity_rationale is too weak")
    serialized = json.dumps(recipe, sort_keys=True).casefold()
    require(not any(word in serialized for word in FORBIDDEN_RECIPE_WORDS),
            f"{context} contains forbidden provenance")
    return {
        **recipe,
        "donor_source": source,
        "source_sha256": source_sha,
        "compile_lane": {"required_define": lane["required_define"]},
    }


def validate_overlaid_cross_tu_instruction_source_recipe(
    recipe: object,
    root,
    owner_source: str,
    source_overlay_by_path: dict,
    rendered_by_path: dict,
    context: str,
) -> dict:
    """Validate an OVERLAID sibling translation unit as an instruction source.

    The framework already admits an overlaid sibling as a donor: the
    ``cross_tu_complete_target_only_v1`` policy lets one supply an entire
    COMDAT body, pinned by ``donor_source`` plus
    ``donor_effective_source_sha256``.  This role is that same provenance
    object confined to a strictly smaller transfer -- the manifest-pinned
    instruction bytes of a cross-TU instruction hybrid -- and it may never
    supply a whole body.

    What it must never become is the thing the *clean* cross-TU recipe
    forbids: a pin naming the checked-in text as the origin of bytes the
    overlay produced.  So the overlay is not merely tolerated here, it is
    **declared**: the recipe carries the donor path's clean sha, its
    effective sha, size and line count, every one of them checked against
    the manifest's own validated ``source_overlay`` record and against the
    rendering the overlay actually produced.  An overlaid donor whose
    overlay is not declared refuses; a declared overlay that does not match
    the rendering refuses; and a donor path with no overlay at all refuses,
    because that case is the clean recipe's and keeps its own bar.
    """
    require(isinstance(recipe, dict), f"{context} must be an object")
    exact_audit_keys(recipe, {
        "kind", "donor_source", "donor_source_overlay",
        "donor_effective_source_sha256", "rendered_source_sha256",
        "rendered_source_size", "rendered_source_line_count",
        "compile_lane", "emission_policy", "role_policy",
        "authenticity_rationale",
    }, context)
    require(recipe.get("kind") == CROSS_TU_INSTRUCTION_SOURCE_RECIPE,
            f"{context}.kind differs")
    require(recipe.get("role_policy")
            == CROSS_TU_INSTRUCTION_SOURCE_RECIPE_POLICY,
            f"{context}.role_policy differs")
    source = source_overlay_relative_path(
        recipe.get("donor_source"), context + ".donor_source")
    require(PurePosixPath(source).suffix.casefold()
            in {".c", ".cc", ".cpp", ".cxx"},
            f"{context}.donor_source is not a translation unit")
    require(source != owner_source,
            f"{context}.donor_source is not cross-translation-unit")

    declaration = recipe.get("donor_source_overlay")
    require(isinstance(declaration, dict), f"{context}.donor_source_overlay "
            "must be an object")
    exact_audit_keys(declaration, {
        "declared", "clean_source_sha256", "effective_source_sha256",
        "effective_source_size", "effective_source_line_count",
    }, context + ".donor_source_overlay")
    require(declaration.get("declared") is True,
            f"{context}: the donor translation unit's effective source "
            "overlay is not declared")
    clean_sha = require_sha(
        declaration.get("clean_source_sha256"),
        context + ".donor_source_overlay.clean_source_sha256")
    effective_sha = require_sha(
        declaration.get("effective_source_sha256"),
        context + ".donor_source_overlay.effective_source_sha256")
    effective_size = require_exact_int(
        declaration.get("effective_source_size"),
        context + ".donor_source_overlay.effective_source_size", minimum=1)
    effective_lines = require_exact_int(
        declaration.get("effective_source_line_count"),
        context + ".donor_source_overlay.effective_source_line_count",
        minimum=1)

    overlay_output = source_overlay_by_path.get(source)
    require(
        overlay_output is not None,
        f"{context}.donor_source has no effective source overlay to declare",
    )
    overlay_clean = (overlay_output.get("clean") or {}).get("baseline_sha256")
    overlay_effective = overlay_output.get("effective") or {}
    require(
        clean_sha == overlay_clean
        and effective_sha == overlay_effective.get("baseline_sha256")
        and effective_size == overlay_effective.get("baseline_size")
        and effective_lines == overlay_effective.get("baseline_line_count"),
        f"{context}: the declared donor overlay differs from the manifest's "
        "effective rendering",
    )

    donor_effective_sha = require_sha(
        recipe.get("donor_effective_source_sha256"),
        context + ".donor_effective_source_sha256")
    rendered_sha = require_sha(
        recipe.get("rendered_source_sha256"),
        context + ".rendered_source_sha256")
    rendered_size = require_exact_int(
        recipe.get("rendered_source_size"),
        context + ".rendered_source_size", minimum=1)
    rendered_lines = require_exact_int(
        recipe.get("rendered_source_line_count"),
        context + ".rendered_source_line_count", minimum=1)
    require(
        donor_effective_sha == effective_sha
        and rendered_sha == effective_sha
        and rendered_size == effective_size
        and rendered_lines == effective_lines,
        f"{context}: the donor rendering is not the unmodified effective "
        "translation unit",
    )
    rendered = rendered_by_path.get(source)
    if rendered is not None:
        require(
            sha256_bytes(rendered) == rendered_sha
            and len(rendered) == rendered_size
            and rendered.count(b"\n") == rendered_lines,
            f"{context}: the donor rendering differs from the overlay's own "
            "output",
        )

    canonical_root = Path(root).resolve(strict=True)
    source_path = source_overlay_logical_path(canonical_root, source)
    try:
        metadata = source_path.lstat()
        resolved_source = source_path.resolve(strict=True)
    except OSError as error:
        raise ByteIdentityError(
            f"{context}.donor_source is absent or redirected: {error}"
        ) from error
    require(
        stat.S_ISREG(metadata.st_mode)
        and not source_path.is_symlink()
        and resolved_source == source_path
        and resolved_source.is_relative_to(canonical_root),
        f"{context}.donor_source is redirected or non-regular",
    )
    require(sha256_file(source_path) == clean_sha,
            f"{context}.donor_source differs from its checked-in pin")

    lane = recipe.get("compile_lane")
    require(isinstance(lane, dict)
            and set(lane) == {"required_define"}
            and isinstance(lane.get("required_define"), str)
            and lane["required_define"],
            f"{context}.compile_lane differs")
    require(recipe.get("emission_policy")
            == "unmodified_effective_translation_unit_only",
            f"{context}.emission_policy differs")
    rationale = recipe.get("authenticity_rationale")
    require(isinstance(rationale, str) and len(rationale) >= 32,
            f"{context}.authenticity_rationale is too weak")
    serialized = json.dumps(recipe, sort_keys=True).casefold()
    require(not any(word in serialized for word in FORBIDDEN_RECIPE_WORDS),
            f"{context} contains forbidden provenance")
    return {
        **recipe,
        "donor_source": source,
        "donor_source_overlay": {
            "declared": True,
            "clean_source_sha256": clean_sha,
            "effective_source_sha256": effective_sha,
            "effective_source_size": effective_size,
            "effective_source_line_count": effective_lines,
        },
        "donor_effective_source_sha256": donor_effective_sha,
        "rendered_source_sha256": rendered_sha,
        "rendered_source_size": rendered_size,
        "rendered_source_line_count": rendered_lines,
        "compile_lane": {"required_define": lane["required_define"]},
    }


def validate_donor_source_overlay_recipe(
    recipe: object, root, *, seed_outputs_touched: bool = False,
    canonical_operations: list[dict] | None = None,
) -> dict:
    """Extension A: a donor recipe carrying typed per-path renderings.

    Obligations enforced here: A1/A6a (typed ops over checked-in source, no
    literal payloads -- the op grammar itself admits no literals), A2/A6b (the
    shipped tree's renderings are untouched), A3 (clean and rendered shas are
    pinned), and A5 (every anchor seats uniquely against the clean input, and
    drift refuses).  A6c -- scoping the private include to the donor compile
    -- belongs to the build and is asserted there.
    """
    require(isinstance(recipe, dict),
            "donor source overlay recipe must be an object")
    require(recipe.get("kind") == "donor_source_overlay",
            "donor source overlay recipe kind differs")
    canonical_replay = recipe.get("canonical_overlay_replay")
    require(canonical_replay in {None, "owning_translation_unit_v1"},
            "donor source canonical-overlay replay differs")
    if canonical_replay is not None:
        require(isinstance(canonical_operations, list)
                and canonical_operations,
                "donor source canonical-overlay replay is unavailable")
    require(
        not seed_outputs_touched,
        "donor source overlay op-list perturbs the seed rendering: the "
        "shipped tree's rendered outputs must stay bit-identical (A2/A6b)",
    )
    lane = recipe.get("compile_lane")
    require(isinstance(lane, dict)
            and set(lane) <= {"required_define", "include_projection"}
            and "required_define" in lane
            and isinstance(lane.get("required_define"), str)
            and lane["required_define"]
            and (
                "include_projection" not in lane
                or lane["include_projection"] == "source_root_mirror_v1"
            ),
            "donor source overlay compile lane differs")
    renderings = recipe.get("renderings")
    require(isinstance(renderings, list) and renderings,
            "donor source overlay renderings must be a non-empty array")
    root = Path(root).resolve(strict=True)
    seen: set[str] = set()
    normalized = []
    clean_inputs: list[bytes] = []
    pending_signatures: list[tuple[str, dict]] = []
    for index, item in enumerate(renderings):
        context = f"donor rendering[{index}]"
        require(isinstance(item, dict), f"{context} must be an object")
        exact_audit_keys(item, {
            "path", "clean_sha256", "rendered_sha256", "operations",
        }, context)
        path = source_overlay_relative_path(item.get("path"),
                                            context + ".path")
        require(path not in seen, f"{context}: duplicate rendering path")
        seen.add(path)
        clean = require_sha(item.get("clean_sha256"),
                            context + ".clean_sha256")
        rendered = require_sha(item.get("rendered_sha256"),
                               context + ".rendered_sha256")
        target = source_overlay_logical_path(root, path)
        try:
            metadata = target.lstat()
            resolved_target = target.resolve(strict=True)
        except OSError as error:
            raise ByteIdentityError(
                f"{context}: {path} is absent or redirected: {error}"
            ) from error
        require(
            stat.S_ISREG(metadata.st_mode) and not target.is_symlink()
            and resolved_target == target
            and resolved_target.is_relative_to(root),
            f"{context}: {path} is redirected or non-regular",
        )
        data = target.read_bytes()
        require(
            sha256_bytes(data) == clean,
            f"{context}: clean input drifted from its pin -- re-pin "
            f"deliberately rather than letting the donor follow the tree",
        )
        operations = item.get("operations")
        require(isinstance(operations, list),
                f"{context}.operations must be an array")
        validated_ops = []
        for op_index, operation in enumerate(operations):
            op_context = f"{context}.operations[{op_index}]"
            validated = validate_source_overlay_operation(
                operation, op_context, logical_path=path, index=op_index,
            )
            # A5: every anchor must seat uniquely against the clean input.
            # resolve_source_overlay_anchor refuses on BOTH ambiguity and
            # absence, exactly as repin_overlay.py already refuses.
            for role in ("start_anchor", "end_anchor"):
                anchor = validated.get(role)
                if anchor is not None:
                    resolve_source_overlay_anchor(
                        data, anchor, f"{op_context}.{role}",
                        logical_path=path,
                    )
            for generator in _source_overlay_generators(validated):
                if generator.get("kind") == "member_signature_v1":
                    pending_signatures.append((op_context, generator))
            validated_ops.append(validated)
        if canonical_replay is not None:
            require(index == 0 and len(renderings) == 1,
                    "canonical-overlay replay requires one source rendering")
            replay_ids = [item.get("id") for item in canonical_operations]
            require(all(isinstance(item, dict) and isinstance(item.get("id"), str)
                        for item in canonical_operations)
                    and len(set(replay_ids)) == len(replay_ids)
                    and not set(replay_ids).intersection(
                        item["id"] for item in validated_ops),
                    "canonical-overlay replay operation census differs")
            for operation in canonical_operations:
                for role in ("start_anchor", "end_anchor"):
                    anchor = operation.get(role)
                    if anchor is not None:
                        resolve_source_overlay_anchor(
                            data, anchor,
                            f"canonical replay {operation['id']}.{role}",
                            logical_path=path,
                        )
            validated_ops = list(canonical_operations) + validated_ops
        clean_inputs.append(data)
        normalized.append({
            "path": path, "clean_sha256": clean,
            "rendered_sha256": rendered, "operations": validated_ops,
        })
    # A7a: every emitted signature names a class and member that exist in the
    # checked-in source this recipe renders from.  Deferred to here so a
    # signature seated in the .cpp can be authorised by the header that
    # actually declares the class.
    for op_context, generator in pending_signatures:
        params = generator["params"]
        class_identifier = params["class_identifier"]
        member_identifier = params["member_identifier"]
        spelling = (
            f"{class_identifier}::~{member_identifier}"
            if params["kind"] == "destructor"
            else f"{class_identifier}::{member_identifier}"
        )
        require(
            any(source_overlay_member_is_declared(
                data, class_identifier, member_identifier, params["kind"])
                for data in clean_inputs),
            f"{op_context}: member signature "
            f"{spelling} is not declared in any "
            f"checked-in source this recipe renders from",
        )
        if params["kind"] == "constructor":
            # A7a(ii) -- the freshness half, and the half that keeps A7a a
            # gate for constructors.  It is UNIVERSAL over the recipe's clean
            # inputs: no rendered input may already declare this overload at
            # class scope, so the generator can only ever ADD a constructor
            # the checked-in tree does not have, never restate or shadow one.
            for data in clean_inputs:
                require(
                    source_overlay_constructor_overload_count(
                        data, class_identifier, params["parameters"]) == 0,
                    f"{op_context}: member signature "
                    f"{spelling} already declares this parameter type "
                    f"sequence in checked-in source this recipe renders from",
                )
    normalized_lane = {"required_define": lane["required_define"]}
    if "include_projection" in lane:
        normalized_lane["include_projection"] = lane["include_projection"]
    normalized = {
        "kind": "donor_source_overlay",
        "compile_lane": normalized_lane,
        "renderings": normalized,
    }
    if canonical_replay is not None:
        normalized["canonical_overlay_replay"] = canonical_replay
    carrier = recipe.get("compiler_state_carrier")
    if carrier is not None:
        normalized["compiler_state_carrier"] = (
            validate_donor_source_compiler_state_carrier(
                carrier, "donor source overlay compiler-state carrier"
            )
        )
    return normalized


DONOR_SOURCE_CARRIER_SEATS = {
    "extern_run_pair_v1": (
        "after_includes_and_eof_v1", ("header", "seat"),
    ),
    "declaration_run_triple_v1": (
        "start_after_includes_and_eof_v1", ("pre", "post", "eof"),
    ),
}


def validate_donor_source_compiler_state_carrier(
    value: object, context: str,
) -> dict:
    """Validate one closed, declaration-only multi-seat source carrier.

    Two grammars are admitted, both already part of the mosaic carrier
    vocabulary and both emitting nothing at all: the two-seat extern run
    (declarations of never-defined objects, after the include block and at
    physical EOF) and the three-seat forward-declaration run (bare class
    declarations at file start, after the include block, and at EOF).  Every
    obligation -- per-seat count bounds, identity non-collision, and the
    exact generated-declaration digest -- applies to both.
    """
    require(isinstance(value, dict), f"{context} must be an object")
    kind = value.get("kind")
    require(kind in DONOR_SOURCE_CARRIER_SEATS,
            f"{context} kind or placement differs")
    placement, roles = DONOR_SOURCE_CARRIER_SEATS[kind]
    keys = {"kind", "placement", "width", "generated_declarations_sha256"}
    for role in roles:
        keys |= {f"{role}_prefix", f"{role}_count"}
    exact_audit_keys(value, keys, context)
    require(value.get("placement") == placement,
            f"{context} kind or placement differs")
    width = require_exact_int(
        value.get("width"), context + ".width", minimum=1, maximum=3)
    generator = (
        entropy_generator.generate_extern_run
        if kind == "extern_run_pair_v1"
        else entropy_generator.generate_forward_run
    )
    counts = {}
    payloads = []
    identities = set()
    for role in roles:
        prefix = value.get(f"{role}_prefix")
        count = require_exact_int(
            value.get(f"{role}_count"), context + f".{role}_count",
            minimum=1, maximum=999,
        )
        require(isinstance(prefix, str),
                f"{context}.{role}_prefix differs")
        try:
            payload = generator(prefix, count, width).encode("ascii")
        except ValueError as error:
            raise ByteIdentityError(
                f"{context}.{role} declaration run is invalid: {error}"
            ) from error
        names = {
            f"{prefix}{index:0{width}d}" for index in range(count)
        }
        require(len(names) == count and not identities.intersection(names),
                f"{context} declaration identities collide")
        identities.update(names)
        payloads.append(payload)
        counts[role] = (prefix, count)
    generated = b"".join(payloads)
    require(
        require_sha(value.get("generated_declarations_sha256"),
                    context + ".generated_declarations_sha256")
        == sha256_bytes(generated),
        f"{context} generated declarations differ from their pin",
    )
    normalized = {"kind": kind, "placement": placement, "width": width,
                  "generated_declarations_sha256": sha256_bytes(generated)}
    for role in roles:
        normalized[f"{role}_prefix"] = counts[role][0]
        normalized[f"{role}_count"] = counts[role][1]
    return normalized


def render_donor_source_compiler_state_carrier(
    data: bytes, carrier: dict,
) -> bytes:
    """Seat a validated declaration-only carrier at its exact seats."""
    kind = carrier["kind"]
    require(kind in DONOR_SOURCE_CARRIER_SEATS
            and carrier["placement"]
            == DONOR_SOURCE_CARRIER_SEATS[kind][0],
            "donor source compiler-state carrier differs")
    roles = DONOR_SOURCE_CARRIER_SEATS[kind][1]
    generator = (
        entropy_generator.generate_extern_run
        if kind == "extern_run_pair_v1"
        else entropy_generator.generate_forward_run
    )
    runs = {
        role: generator(
            carrier[f"{role}_prefix"], carrier[f"{role}_count"],
            carrier["width"],
        ).encode("ascii").rstrip(b"\n").split(b"\n")
        for role in roles
    }
    lines = data.split(b"\n")
    include_rows = [
        index for index, line in enumerate(lines)
        if line.startswith(b"#include")
    ]
    require(include_rows,
            "donor source compiler-state carrier lacks an include seat")
    insert_at = include_rows[-1] + 1
    if kind == "extern_run_pair_v1":
        return b"\n".join(
            lines[:insert_at] + runs["header"]
            + lines[insert_at:] + runs["seat"]
        )
    return b"\n".join(
        runs["pre"] + lines[:insert_at] + runs["post"]
        + lines[insert_at:] + runs["eof"]
    )


def render_donor_source_overlay(
    recipe: object, root, *, repin: bool = False,
    canonical_operations: list[dict] | None = None,
) -> dict[str, bytes]:
    """Render each donor-private path from checked-in source plus typed ops.

    Extension A's renderer.  It reuses the existing op machinery wholesale --
    the same verbs, the same typed generators, the same content-hash anchors,
    and the same `source_range_relocation_v1` producer/consumer pairing that
    the shipped overlay uses.  Nothing here is literal: every emitted byte is
    either a typed generator's render or an authenticated range copied out of
    checked-in source.

    Returns {path: rendered bytes}.  The caller stages these for the donor
    compile ONLY; A2/A6b keep the shipped tree's renderings untouched.
    """
    validated = validate_donor_source_overlay_recipe(
        recipe, root, seed_outputs_touched=False,
        canonical_operations=canonical_operations)
    root = Path(root)
    clean: dict[str, bytes] = {}
    edits: dict[str, list] = {}
    relocation_ranges: dict[tuple[str, str], bytes] = {}
    consumers: list[tuple[str, dict, list]] = []

    # Pass 1 -- resolve every seat and capture the ranges producers remove.
    for item in validated["renderings"]:
        path = item["path"]
        data = (root / path).read_bytes()
        clean[path] = data
        edits[path] = []
        for operation in item["operations"]:
            action = operation["action"]
            generator = operation["generator"]
            if action in {"replace", "delete"}:
                start = resolve_source_overlay_anchor(
                    data, operation["start_anchor"],
                    f"{path} {operation['id']}.from", logical_path=path)
                end = resolve_source_overlay_anchor(
                    data, operation["end_anchor"],
                    f"{path} {operation['id']}.to", logical_path=path)
                require(start <= end,
                        f"{path} {operation['id']}: range is inverted")
                removed = data[start:end]
                pins = operation["baseline_input_range"]
                require(
                    sha256_bytes(removed) == pins["baseline_sha256"]
                    and len(removed) == pins["baseline_size"],
                    f"{path} {operation['id']}: removed range differs from "
                    f"its authenticated pins",
                )
                params = generator["params"]
                if (generator["kind"] == "source_range_relocation_v1"
                        and "byte_destination" in params):
                    require(params["source_operation_id"] == operation["id"]
                            and params["ordinary_owner"] == path,
                            f"{path} {operation['id']}: relocation producer "
                            f"identity differs")
                    require_source_overlay_range_pin(
                        removed, params["source_range_token_pin"],
                        f"{path} {operation['id']} producer range")
                    key = (operation["id"], params["range_dependency_id"])
                    require(key not in relocation_ranges,
                            f"relocation dependency is duplicated: {key}")
                    relocation_ranges[key] = removed
                if action == "delete":
                    # A delete removes; its generator exists only to declare
                    # the relocation producer identity, exactly as the
                    # shipped overlay uses it (vector3d.inl.h keeps none of
                    # the moved range).
                    require(
                        generator["kind"] == "source_range_relocation_v1"
                        and "byte_destination" in generator["params"],
                        f"{path} {operation['id']}: a donor delete must "
                        f"declare a relocation producer",
                    )
                    edits[path].append([start, end, b""])
                    continue
                slot = [start, end, None]
            elif action == "insert":
                at = resolve_source_overlay_anchor(
                    data, operation["start_anchor"],
                    f"{path} {operation['id']}.anchor", logical_path=path)
                slot = [at, at, None]
            else:
                slot = [len(data), len(data), None]
            edits[path].append(slot)
            consumers.append((path, generator, slot))

    # Pass 2 -- render, now that every producer's range is held.
    for path, generator, slot in consumers:
        slot[2] = render_source_overlay_generator(
            generator, relocation_ranges=relocation_ranges)

    rendered: dict[str, bytes] = {}
    for item in validated["renderings"]:
        path = item["path"]
        output = apply_replacements(
            clean[path],
            [(start, end, payload) for start, end, payload in edits[path]])
        carrier = validated.get("compiler_state_carrier")
        if carrier is not None:
            require(len(validated["renderings"]) == 1,
                    "compiler-state carrier requires one source rendering")
            output = render_donor_source_compiler_state_carrier(
                output, carrier)
        require(
            repin or sha256_bytes(output) == item["rendered_sha256"],
            f"{path}: donor rendering differs from its pinned sha256 -- "
            f"re-pin deliberately rather than letting the donor drift",
        )
        rendered[path] = output
    return rendered


def checked_source_root() -> Path:
    """The checked-in tree this tool ships inside, as repin_overlay.py uses."""
    return Path(__file__).resolve().parent.parent


def retail_image_body(
    manifest: dict, image_name: str, address: int, length: int,
) -> bytes:
    """B1's extraction: retail's own bytes at a pinned VA and length.

    The image is re-hashed against `images.<t>.original_sha256` before a byte
    is read, so this can never quote something that is not the pinned retail
    image.  Kept in the build's half of the split because the build already
    owns image identity; the composer only masks and compares.
    """
    entries = [item for item in manifest["images"].values()
               if PurePosixPath(item["original"]).name == image_name]
    require(len(entries) == 1,
            f"retail oracle image {image_name!r} is not pinned exactly once")
    image = entries[0]
    data = (checked_source_root() / image["original"]).read_bytes()
    require(sha256_bytes(data) == image["original_sha256"],
            f"retail oracle image {image_name!r} differs from its pin")
    require(len(data) == image["original_size"],
            f"retail oracle image {image_name!r} size differs from its pin")

    pe = coff_unpack("<I", data, 0x3C, "retail image PE offset")[0]
    section_count = coff_unpack("<H", data, pe + 6, "retail image sections")[0]
    optional_size = coff_unpack("<H", data, pe + 20, "retail image optional")[0]
    image_base = coff_unpack("<I", data, pe + 24 + 28, "retail image base")[0]
    table = pe + 24 + optional_size
    for index in range(section_count):
        header = table + index * 40
        virtual_size, virtual_address, raw_size, raw_offset = coff_unpack(
            "<IIII", data, header + 8, f"retail image section {index}")
        start = image_base + virtual_address
        if not start <= address < start + max(virtual_size, raw_size):
            continue
        offset = raw_offset + (address - start)
        require(offset + length <= raw_offset + raw_size,
                f"retail oracle window at 0x{address:08x} leaves its section")
        return data[offset:offset + length]
    raise ByteIdentityError(
        f"retail oracle address 0x{address:08x} is not mapped by {image_name}")


def instruction_mosaic_metadata_sha256(
    coff: CoffObject, primary: dict,
) -> str:
    """Hash the target's seed-authoritative line/debug/EH metadata closure."""
    definitions = section_definitions(coff)
    closure = _comdat_child_closure(coff, primary)
    children = []
    for name in closure[1]:
        child = _comdat_child(coff, primary, name)
        definition = definitions[child["number"]]
        children.append({
            "name": name,
            "section_number": child["number"],
            "raw_size": child["raw_size"],
            "relocation_count": child["relocation_count"],
            "line_count": child["line_count"],
            "characteristics": child["characteristics"],
            "selection": definition["selection"],
            "associated": definition["associated"],
            "body_sha256": sha256_bytes(coff_body(coff, child)),
            "relocations_sha256": sha256_bytes(
                _coff_table_bytes(coff, child, "relocations")),
            "lines_sha256": sha256_bytes(
                _coff_table_bytes(coff, child, "lines")),
        })
    return sha256_bytes(canonical_json_bytes({
        "target_line_table_sha256": sha256_bytes(
            _coff_table_bytes(coff, primary, "lines")),
        "target_relocation_table_sha256": sha256_bytes(
            _coff_table_bytes(coff, primary, "relocations")),
        "closure": children,
    }))


def compose_retail_exact_cross_tu_complete_target_resize(
    seed_bytes: bytes,
    target_donor_bytes: bytes,
    complete_donor_bytes: bytes,
    function: dict,
    retail_body: bytes,
) -> tuple[bytes, dict]:
    """Normalize one complete cross-TU COMDAT into an owner-TU carrier.

    The complete donor supplies the entire code body, COFF line rows, FPO
    record, and CodeView procedure range.  The equal-sized owner-TU carrier
    supplies only object-local seats, symbol indices, and CodeView type-index
    namespace.  No instruction ranges or partial code transfers exist in
    this class.  The normalized whole target is then passed to the unchanged
    retail-exact same-slot resize composer.
    """
    require(
        function.get("splice_class")
        == CROSS_TU_COMPLETE_TARGET_RESIZE_CLASS,
        "splice class is not the cross-TU complete-target resize",
    )
    forbidden = {
        "instruction_ranges", "instruction_donor", "target_bytes",
        "instruction_donor_bytes", "donor_variants",
    }
    require(not forbidden.intersection(function),
            "complete-target resize may not carry instruction ranges")
    require(isinstance(retail_body, (bytes, bytearray)) and retail_body,
            "retail oracle body is missing")

    seed = CoffObject(seed_bytes)
    target = CoffObject(target_donor_bytes)
    complete = CoffObject(complete_donor_bytes)
    mangled = function["mangled"]
    seed_primary = seed.function_section(mangled)
    target_primary = target.function_section(mangled)
    complete_primary = complete.function_section(mangled)

    def require_object_pins(role, coff, primary, prefix, length_name):
        require(
            len(coff.sections) == function[f"expected_{prefix}_section_count"]
            and primary["number"]
            == function[f"expected_{prefix}_section_number"],
            f"{role} section census or seat changed",
        )
        require(
            primary["raw_size"] == function[length_name]
            and primary["relocation_count"]
            == function[f"expected_{prefix}_relocation_count"]
            and primary["line_count"]
            == function[f"expected_{prefix}_line_count"],
            f"{role} body/table census changed",
        )
        require(
            sha256_bytes(coff_body(coff, primary))
            == function[f"expected_{prefix}_body_sha256"],
            f"{role} body differs from its pin",
        )
        require(
            instruction_mosaic_metadata_sha256(coff, primary)
            == function[f"expected_{prefix}_metadata_sha256"],
            f"{role} metadata differs from its pin",
        )
        require(
            sum(function_multiset(coff).values())
            == function[f"expected_{prefix}_function_count"]
            and sum(comdat_primary_identity_multiset(coff).values())
            == function[f"expected_{prefix}_comdat_count"],
            f"{role} function/COMDAT census changed",
        )

    require_object_pins(
        "seed", seed, seed_primary, "seed", "expected_seed_length")
    require_object_pins(
        "target donor", target, target_primary, "target_donor",
        "expected_donor_length")
    require_object_pins(
        "complete donor", complete, complete_primary, "complete_donor",
        "expected_complete_donor_length")
    require(
        function_multiset(seed) == function_multiset(target)
        and comdat_primary_identity_multiset(seed)
        == comdat_primary_identity_multiset(target),
        "target donor is not an owner-TU topology carrier",
    )
    require(
        comdat_primary_identity(seed, seed_primary)
        == comdat_primary_identity(target, target_primary)
        == comdat_primary_identity(complete, complete_primary),
        "complete donor is not the exact same mangled COMDAT",
    )
    for role, coff, primary in (
        ("seed", seed, seed_primary),
        ("target donor", target, target_primary),
        ("complete donor", complete, complete_primary),
    ):
        require(
            primary["characteristics"]
            == function["expected_characteristics"]
            and section_definitions(coff)[primary["number"]]["selection"]
            == function["expected_selection"],
            f"{role} COMDAT characteristics or selection changed",
        )
        require(
            _comdat_child_closure(coff, primary)
            == (2, tuple(function["expected_donor_closure"])),
            f"{role} complete-target closure changed",
        )
    require(
        target_primary["raw_size"] == complete_primary["raw_size"]
        and target_primary["relocation_count"]
        == complete_primary["relocation_count"]
        and target_primary["line_count"]
        == complete_primary["line_count"],
        "complete donor and owner carrier target shapes differ",
    )

    def preceding_file_aux(coff, primary):
        function_index, _ = function_symbol(
            coff, mangled, primary["number"])
        candidates = [
            (index, symbol) for index, symbol in coff.symbols.items()
            if index < function_index and symbol["name"] == ".file"
            and symbol["storage"] == 103 and symbol["section"] == -2
            and symbol["aux_count"] >= 1
        ]
        require(candidates,
                "complete-target function has no preceding .file record")
        index, symbol = max(candidates, key=lambda item: item[0])
        start = coff.symbol_offset + (index + 1) * 18
        end = start + symbol["aux_count"] * 18
        require(end <= len(coff.data),
                "complete-target preceding .file record is truncated")
        return coff.data[start:end]

    file_aux = preceding_file_aux(seed, seed_primary)
    require(
        file_aux == preceding_file_aux(target, target_primary)
        == preceding_file_aux(complete, complete_primary)
        and sha256_bytes(file_aux)
        == function["expected_preceding_file_aux_sha256"],
        "complete-target preceding .file bytes differ",
    )

    def relocation_semantics(coff, section, primary_number):
        return [
            (
                row["offset"], row["type"], row["addend"], row["target"],
                "primary" if row["target_section"] == primary_number
                else "external",
                row["target_value"], row["target_type"],
                row["target_storage"],
            )
            for row in detailed_relocations(coff, section)
        ]

    require(
        relocation_semantics(target, target_primary,
                             target_primary["number"])
        == relocation_semantics(complete, complete_primary,
                                complete_primary["number"]),
        "complete donor primary relocation semantics differ",
    )
    target_children = {}
    complete_children = {}
    for child_name in function["expected_donor_closure"]:
        target_child = _comdat_child(target, target_primary, child_name)
        complete_child = _comdat_child(
            complete, complete_primary, child_name)
        target_children[child_name] = target_child
        complete_children[child_name] = complete_child
        require(
            all(target_child[field] == complete_child[field] for field in (
                "name", "raw_size", "relocation_count", "line_count",
                "characteristics",
            )),
            f"complete donor {child_name} geometry differs",
        )
        require(
            relocation_semantics(target, target_child,
                                 target_primary["number"])
            == relocation_semantics(complete, complete_child,
                                    complete_primary["number"]),
            f"complete donor {child_name} relocation semantics differ",
        )

    # Both copies come from the same compiler header definition.  Absolute
    # line bases must agree; only the object-local next-function chain may
    # differ between translation units.
    for marker_name in (".bf", ".ef"):
        target_index, target_marker = _coff_marker(
            target, marker_name, target_primary["number"])
        complete_index, complete_marker = _coff_marker(
            complete, marker_name, complete_primary["number"])
        target_aux = coff_auxiliary(target, target_index, target_marker)
        complete_aux = coff_auxiliary(
            complete, complete_index, complete_marker)
        require(
            target_aux[4:6] == complete_aux[4:6]
            and target_aux[:4] == complete_aux[:4]
            and target_aux[6:12] == complete_aux[6:12]
            and target_aux[16:] == complete_aux[16:],
            f"complete donor {marker_name} source-line identity differs",
        )

    target_lines = _coff_table_bytes(target, target_primary, "lines")
    complete_lines = bytearray(_coff_table_bytes(
        complete, complete_primary, "lines"))
    target_function_index, _ = function_symbol(
        target, mangled, target_primary["number"])
    complete_function_index, _ = function_symbol(
        complete, mangled, complete_primary["number"])
    require(
        coff_unpack("<IH", target_lines, 0, "target line sentinel")
        == (target_function_index, 0)
        and coff_unpack("<IH", bytes(complete_lines), 0,
                        "complete line sentinel")
        == (complete_function_index, 0),
        "complete-target COFF line sentinel is invalid",
    )
    complete_lines[0:4] = target_function_index.to_bytes(4, "little")
    previous = -1
    for index in range(1, complete_primary["line_count"]):
        offset, line = coff_unpack(
            "<IH", bytes(complete_lines), index * 6,
            "complete-target line row")
        require(line != 0 and previous <= offset < complete_primary["raw_size"],
                "complete-target COFF line row is outside/nonmonotonic")
        previous = offset
    normalized_lines = bytes(complete_lines)

    target_fpo_section = target_children[".debug$F"]
    complete_fpo_section = complete_children[".debug$F"]
    complete_fpo = coff_body(complete, complete_fpo_section)
    parse_fpo_data(complete_fpo,
                   expected_proc_size=complete_primary["raw_size"])

    target_debug_section = target_children[".debug$S"]
    complete_debug_section = complete_children[".debug$S"]
    target_debug = coff_body(target, target_debug_section)
    complete_debug = coff_body(complete, complete_debug_section)
    require(
        len(target_debug) == len(complete_debug) >= 28
        and target_debug[2:4] == complete_debug[2:4] == b"\x05\x02",
        "complete-target debug$S is not one S_*PROC32 record",
    )
    complete_cbproc, complete_dbgstart, complete_dbgend = coff_unpack(
        "<III", complete_debug, 16, "complete-target debug range")
    require(
        complete_cbproc == complete_primary["raw_size"]
        and 0 <= complete_dbgstart <= complete_dbgend < complete_cbproc,
        "complete-target debug procedure range is stale",
    )
    debug_differences = [
        index for index, (left, right) in enumerate(
            zip(target_debug, complete_debug)) if left != right
    ]
    require(
        debug_differences == function["expected_debug_s_diff_offsets"],
        "complete-target debug$S difference set changed",
    )
    type_bytes = {
        byte for offset in function["expected_codeview_type_index_offsets"]
        for byte in (offset, offset + 1)
    }
    require(
        set(debug_differences) - set(range(16, 28)) == type_bytes,
        "complete-target CodeView differences are not type-index words",
    )
    normalized_debug = bytearray(target_debug)
    normalized_debug[16:28] = complete_debug[16:28]
    normalized_debug = bytes(normalized_debug)

    normalized = bytearray(target_donor_bytes)
    normalized[
        target_primary["raw_offset"]:
        target_primary["raw_offset"] + target_primary["raw_size"]
    ] = coff_body(complete, complete_primary)
    normalized[
        target_primary["line_offset"]:
        target_primary["line_offset"] + len(normalized_lines)
    ] = normalized_lines
    normalized[
        target_fpo_section["raw_offset"]:
        target_fpo_section["raw_offset"] + len(complete_fpo)
    ] = complete_fpo
    normalized[
        target_debug_section["raw_offset"]:
        target_debug_section["raw_offset"] + len(normalized_debug)
    ] = normalized_debug
    normalized = bytes(normalized)

    allowed_offsets = set(range(
        target_primary["raw_offset"],
        target_primary["raw_offset"] + target_primary["raw_size"],
    )) | set(range(
        target_primary["line_offset"],
        target_primary["line_offset"] + len(normalized_lines),
    )) | set(range(
        target_fpo_section["raw_offset"],
        target_fpo_section["raw_offset"] + target_fpo_section["raw_size"],
    )) | set(range(
        target_debug_section["raw_offset"] + 16,
        target_debug_section["raw_offset"] + 28,
    ))
    changed_offsets = {
        index for index, (left, right) in enumerate(
            zip(target_donor_bytes, normalized)) if left != right
    }
    require(changed_offsets and changed_offsets <= allowed_offsets,
            "complete-target normalizer changed a non-target byte")

    normalized_coff = CoffObject(normalized)
    normalized_primary = normalized_coff.function_section(mangled)
    normalized_fpo_section = _comdat_child(
        normalized_coff, normalized_primary, ".debug$F")
    normalized_debug_section = _comdat_child(
        normalized_coff, normalized_primary, ".debug$S")
    require(
        sha256_bytes(coff_body(normalized_coff, normalized_primary))
        == function["expected_normalized_body_sha256"]
        and sha256_bytes(_coff_table_bytes(
            normalized_coff, normalized_primary, "lines"))
        == function["expected_normalized_line_sha256"]
        and sha256_bytes(coff_body(
            normalized_coff, normalized_fpo_section))
        == function["expected_normalized_fpo_sha256"]
        and sha256_bytes(coff_body(
            normalized_coff, normalized_debug_section))
        == function["expected_normalized_debug_s_sha256"]
        and instruction_mosaic_metadata_sha256(
            normalized_coff, normalized_primary)
        == function["expected_normalized_metadata_sha256"],
        "complete-target normalized closure differs from its pins",
    )
    require(
        function_multiset(normalized_coff) == function_multiset(target)
        and comdat_primary_identity_multiset(normalized_coff)
        == comdat_primary_identity_multiset(target)
        and detailed_relocations(normalized_coff, normalized_primary)
        == detailed_relocations(target, target_primary),
        "complete-target normalization changed owner topology/relocations",
    )

    effective = {
        "mangled": mangled,
        "splice_class": "retail_exact_reloc_divergent",
        "expected_seed_length": function["expected_seed_length"],
        "expected_donor_length": function["expected_donor_length"],
        "expected_linked_span": function["expected_linked_span"],
        "expected_body_sha256": function[
            "expected_normalized_body_sha256"],
        "retail_oracle": function["retail_oracle"],
        "retail_relocations": function["retail_relocations"],
    }
    composed, detail = compose_same_slot_resize(
        seed_bytes, normalized, effective, retail_body=bytes(retail_body))
    return composed, {
        **detail,
        "splice_class": CROSS_TU_COMPLETE_TARGET_RESIZE_CLASS,
        "complete_donor_body_sha256": sha256_bytes(
            coff_body(complete, complete_primary)),
        "normalized_metadata_sha256": instruction_mosaic_metadata_sha256(
            normalized_coff, normalized_primary),
        "normalized_changed_byte_count": len(changed_offsets),
    }


def _validate_instruction_mosaic_source_variant(
    seed: CoffObject,
    seed_primary: dict,
    donor_bytes: bytes,
    function: dict,
    variant: dict,
    context: str,
    reseat_windows: list[tuple[int, int]] | None = None,
) -> tuple[CoffObject, dict, bytes]:
    """Authenticate one independently compiled same-COMDAT donor variant."""
    donor = CoffObject(donor_bytes)
    primary = donor.function_section(function["mangled"])
    require(primary["number"] == seed_primary["number"]
            == function["expected_section_number"],
            f"{context} target section seat changed")
    require(len(donor.sections) == len(seed.sections)
            == function["expected_section_count"],
            f"{context} global section count changed")
    require(function_multiset(seed) == function_multiset(donor),
            f"{context} function set differs")
    require(comdat_primary_identity_multiset(seed)
            == comdat_primary_identity_multiset(donor),
            f"{context} COMDAT identity set differs")
    require(all(seed_primary[field] == primary[field]
                for field in ("name", "relocation_count", "characteristics")),
            f"{context} target section header changed")
    require(primary["raw_size"] == variant["expected_body_length"]
            and primary["line_count"] == variant["expected_line_count"]
            and primary["relocation_count"]
            == function["expected_relocation_count"],
            f"{context} target size/table counts changed")
    seed_defs = section_definitions(seed)
    donor_defs = section_definitions(donor)
    require(seed_defs[seed_primary["number"]]["selection"]
            == donor_defs[primary["number"]]["selection"],
            f"{context} COMDAT selection changed")
    closure = _comdat_child_closure(seed, seed_primary)
    require(closure == _comdat_child_closure(donor, primary)
            and closure in {
                (2, (".debug$F", ".debug$S")),
                (2, (".debug$S", ".xdata$x")),
            }, f"{context} target closure changed")
    for child_name in closure[1]:
        left = _comdat_child(seed, seed_primary, child_name)
        right = _comdat_child(donor, primary, child_name)
        require(left["number"] == right["number"]
                and all(left[field] == right[field]
                        for field in ("name", "characteristics")),
                f"{context} {child_name} seat/header changed")
        require_same_semantic_relocations(
            seed, left, donor, right, f"{context} {child_name}")
    require_instruction_mosaic_semantic_relocations(
        seed, seed_primary, donor, primary, f"{context} code",
        reseat_windows=reseat_windows or None)
    body = coff_body(donor, primary)
    require(sha256_bytes(body) == variant["expected_body_sha256"],
            f"{context} body differs from its pin")
    require(instruction_mosaic_metadata_sha256(donor, primary)
            == variant["expected_metadata_sha256"],
            f"{context} metadata differs from its pin")
    lines = _coff_table_bytes(donor, primary, "lines")
    require(len(lines) >= 6 and lines[4:6] == b"\0\0"
            and donor.symbols.get(
                int.from_bytes(lines[:4], "little"), {}).get("name")
            == function["mangled"],
            f"{context} line marker changed identity")
    return donor, primary, body


def _compose_instruction_mosaic_variant_object(
    seed_bytes: bytes,
    main_donor_bytes: bytes,
    additional_donor_bytes: dict[str, bytes],
    function: dict,
) -> tuple[bytes, dict]:
    """Build one provenance-checked donor view from same-COMDAT variants.

    The returned object is an internal view only.  Every copied instruction
    still comes from its named fresh compiler output; no synthesized bytes or
    manifest literals enter the result.
    """
    variants = function.get("donor_variants", [])
    require(variants, "instruction mosaic has no additional donor variants")
    expected_ids = {item["donor"] for item in variants}
    require(set(additional_donor_bytes) == expected_ids,
            "instruction-mosaic additional donor set differs")
    seed = CoffObject(seed_bytes)
    seed_primary = seed.function_section(function["mangled"])
    records = {
        function["donor"]: {
            "expected_body_length": function["expected_donor_body_length"],
            "expected_line_count": function["expected_donor_line_count"],
            "expected_body_sha256": function["expected_donor_body_sha256"],
            "expected_metadata_sha256":
                function["expected_donor_metadata_sha256"],
        },
        **{item["donor"]: item for item in variants},
    }
    objects = {function["donor"]: main_donor_bytes,
               **additional_donor_bytes}
    ranges = validate_instruction_mosaic_ranges(
        function["instruction_ranges"], "instruction mosaic ranges",
        function["expected_body_length"],
    )
    reseat_windows = [
        (item["start"], item["end"]) for item in ranges
        if item.get("relocation_reseat")
    ]
    parsed = {}
    for donor_id, record in records.items():
        parsed[donor_id] = _validate_instruction_mosaic_source_variant(
            seed, seed_primary, objects[donor_id], function, record,
            f"instruction-mosaic variant {donor_id}",
            reseat_windows=reseat_windows,
        )

    main = parsed[function["donor"]]
    hybrid = bytearray(main_donor_bytes)
    used = set()
    for index, item in enumerate(ranges):
        donor_id = item.get("donor")
        require(donor_id in parsed,
                f"instruction-mosaic range {index} donor is not declared")
        used.add(donor_id)
        variant_coff, primary, body = parsed[donor_id]
        start, end = item["start"], item["end"]
        require(end <= len(body),
                f"instruction-mosaic range {index} leaves its donor")
        require(body[start:end].hex() == item["donor_bytes"]
                and sha256_bytes(body[start:end]) == item["donor_sha256"],
                f"instruction-mosaic range {index} donor provenance differs")
        at = main[1]["raw_offset"] + start
        hybrid[at:at + end - start] = body[start:end]
        if item.get("relocation_reseat") and donor_id != function["donor"]:
            # the combined view carries the main donor's relocation table;
            # a reseat range supplied by another variant brings that
            # variant's operand seats for the records it moved
            for row in detailed_relocations(variant_coff, primary):
                if start <= row["offset"] and row["offset"] + row["width"] <= end:
                    record_offset = (main[1]["relocation_offset"]
                                     + 10 * row["ordinal"])
                    hybrid[record_offset:record_offset + 4] = (
                        row["offset"].to_bytes(4, "little"))
    require(used == set(records),
            "instruction-mosaic donor variant is unused")
    hybrid = bytes(hybrid)
    hybrid_coff = CoffObject(hybrid)
    hybrid_primary = hybrid_coff.function_section(function["mangled"])
    hybrid_body = coff_body(hybrid_coff, hybrid_primary)
    require(sha256_bytes(hybrid_body)
            == function["expected_mosaic_donor_body_sha256"],
            "instruction-mosaic combined donor view differs from its pin")
    return hybrid, {
        "variant_donors": sorted(records),
        "combined_donor_body_sha256": sha256_bytes(hybrid_body),
    }


def _compose_retail_exact_instruction_mosaic_core(
    seed_bytes: bytes,
    donor_bytes: bytes,
    function: dict,
    retail_body: bytes,
    *,
    source_permutation: bool,
) -> tuple[bytes, dict]:
    """Import pinned complete instructions into an otherwise canonical COMDAT.

    Both objects are fresh compiler outputs of the same checked-in source;
    only the manifest-declared compiler-state carrier differs.  The output is
    the seed object byte-for-byte except for authenticated, same-offset donor
    instructions.  In particular the seed relocation, line, debug and EH
    tables remain authoritative.  A pinned retail body plus its complete
    semantic relocation oracle proves that the resulting instruction mosaic
    is retail's exact code rather than a free-form binary patch.
    """
    require(function.get("splice_class")
            == "retail_exact_instruction_mosaic",
            "splice class is not retail_exact_instruction_mosaic")
    require(isinstance(retail_body, (bytes, bytearray)) and retail_body,
            "retail oracle body is missing")
    ordinary_fpo = "ordinary_fpo_identity" in function
    source_fpo = "source_fpo_identity" in function
    self_permutation = "instruction_self_permutation" in function
    require(not (ordinary_fpo and source_fpo),
            "instruction mosaic FPO identity classes are mutually exclusive")
    require(not (source_permutation and ordinary_fpo),
            "ordinary FPO mosaic cannot cross the source-permutation branch")
    require(not source_fpo or source_permutation,
            "source FPO mosaic requires the source-permutation branch")
    require(not self_permutation or (
                not source_fpo and not source_permutation
                and "same_function_source_identity" in function),
            "instruction self-permutation requires an isolated "
            "source-authentic mosaic class")
    permuted_relocations = "relocation_order" in function
    require(not permuted_relocations
            or function["relocation_order"]
            == MOSAIC_PERMUTED_RELOCATION_ORDER,
            "instruction mosaic names an unknown relocation order")
    require(not permuted_relocations or not (
                ordinary_fpo or source_fpo or self_permutation
                or source_permutation or "donor_variants" in function),
            "permuted relocation order requires the plain single-donor "
            "declaration-carrier mosaic class")
    expected_length = function["expected_body_length"]
    donor_expected_length = function.get(
        "expected_donor_body_length", expected_length)
    ranges = validate_instruction_mosaic_ranges(
        function.get("instruction_ranges"), "instruction mosaic ranges",
        expected_length,
    )
    reseat_windows = [
        (item["start"], item["end"]) for item in ranges
        if item.get("relocation_reseat")
    ]
    reseated = bool(reseat_windows)
    require(not reseated or not (
                source_fpo or self_permutation
                or source_permutation or permuted_relocations),
            "relocation reseat requires the plain or ordinary-FPO "
            "declaration-carrier mosaic class")
    require(reseated == ("expected_output_relocation_sha256" in function),
            "relocation reseat requires exactly its output relocation "
            "table pin")
    require((reseated and ordinary_fpo)
            == ("expected_output_metadata_sha256" in function),
            "ordinary FPO relocation reseat requires exactly its output "
            "metadata pin")
    permutation = (
        validate_instruction_self_permutation(
            function["instruction_self_permutation"],
            "instruction self-permutation", expected_length)
        if self_permutation else None
    )
    if permutation is not None:
        require(
            all(
                item["end"] <= permutation["target_start"]
                or item["start"] >= permutation["target_end"]
                for item in ranges
            ),
            "instruction mosaic same-offset ranges overlap the "
            "self-permutation window",
        )
    if ordinary_fpo or source_fpo or self_permutation:
        require(
            all(item["kind"]
                == "same_offset_complete_x86_instruction_sequence_v1"
                for item in ranges),
            "FPO and self-permutation instruction mosaics require exact "
            "sequence partitions",
        )
    seed = CoffObject(seed_bytes)
    donor = CoffObject(donor_bytes)
    mangled = function["mangled"]
    sp = seed.function_section(mangled)
    dp = donor.function_section(mangled)
    require(
        sp["number"] == dp["number"]
        == function["expected_section_number"],
        "instruction-mosaic target section seat changed",
    )
    require(len(seed.sections) == len(donor.sections)
            == function["expected_section_count"],
            "instruction-mosaic global section count changed")
    require(function_multiset(seed) == function_multiset(donor),
            "instruction-mosaic donor function set differs")
    require(comdat_primary_identity_multiset(seed)
            == comdat_primary_identity_multiset(donor),
            "instruction-mosaic donor COMDAT identity set differs")
    common_header_fields = ("name", "relocation_count", "characteristics")
    require(all(sp[field] == dp[field] for field in common_header_fields),
            "instruction-mosaic target section header changed")
    if not source_permutation:
        require(all(sp[field] == dp[field]
                    for field in ("raw_size", "line_count")),
                "instruction-mosaic target size/line header changed")
    require(sp["raw_size"] == expected_length
            and dp["raw_size"] == donor_expected_length
            and sp["relocation_count"]
            == function["expected_relocation_count"]
            and sp["line_count"] == function["expected_line_count"],
            "instruction-mosaic target size/table counts changed")
    if source_permutation:
        require(dp["line_count"] == function["expected_donor_line_count"],
                "instruction-mosaic donor line count changed")
    seed_defs = section_definitions(seed)
    donor_defs = section_definitions(donor)
    require(seed_defs[sp["number"]]["selection"]
            == donor_defs[dp["number"]]["selection"],
            "instruction-mosaic COMDAT selection changed")
    closure = _comdat_child_closure(seed, sp)
    require(closure == _comdat_child_closure(donor, dp),
            "instruction-mosaic target closure changed")
    if ordinary_fpo:
        require(closure == (2, (".debug$F", ".debug$S")),
                "ordinary FPO instruction-mosaic closure class differs")
        require_ordinary_fpo_mosaic_identity(
            seed, sp, donor, dp, function,
            function["ordinary_fpo_identity"],
            "ordinary FPO instruction mosaic",
        )
        if self_permutation:
            require_ordinary_fpo_self_permutation_receipts(
                seed, donor, function,
                "ordinary FPO instruction self-permutation",
            )
    elif source_fpo:
        require(closure == (2, (".debug$F", ".debug$S")),
                "source FPO instruction-mosaic closure class differs")
        require_source_fpo_mosaic_identity(
            seed, sp, donor, dp, function,
            function["source_fpo_identity"],
            "source FPO instruction mosaic",
        )
    else:
        allowed_closures = {(2, EH_CLOSURE_CHILDREN)}
        if source_permutation:
            allowed_closures.add((2, ORDINARY_FPO_CLOSURE_CHILDREN))
        require(closure in allowed_closures,
                "instruction-mosaic target closure class differs")
        if self_permutation:
            require(closure == (2, EH_CLOSURE_CHILDREN),
                    "EH-closure instruction self-permutation closure class "
                    "differs")
            require_self_permutation_receipts(
                seed, donor, function, EH_CLOSURE_CHILDREN,
                "EH-closure instruction self-permutation",
            )
    closure_pairs = []
    closure_relocation_renames = {}
    for child_name in closure[1]:
        left = _comdat_child(seed, sp, child_name)
        right = _comdat_child(donor, dp, child_name)
        require(left["number"] == right["number"],
                f"instruction-mosaic {child_name} seat changed")
        require(all(left[field] == right[field]
                    for field in ("name", "characteristics")),
                f"instruction-mosaic {child_name} header changed")
        closure_relocation_renames[child_name] = (
            require_same_semantic_relocations(
                seed, left, donor, right,
                f"instruction-mosaic {child_name}",
            )
        )
        left_body = coff_body(seed, left)
        right_body = coff_body(donor, right)
        if source_permutation or ordinary_fpo:
            pass
        elif child_name == ".xdata$x":
            require(left_body == right_body,
                    "instruction-mosaic EH xdata raw bytes changed")
        else:
            require(len(left_body) >= 28
                    and left_body[:28] == right_body[:28]
                    and left_body[2:4] == b"\x05\x02",
                    "instruction-mosaic debug procedure identity changed")
        closure_pairs.append((left, right))

    if source_permutation or ordinary_fpo or self_permutation:
        require(instruction_mosaic_metadata_sha256(seed, sp)
                == function["expected_seed_metadata_sha256"],
                "instruction-mosaic seed metadata differs from its pin")
        require(instruction_mosaic_metadata_sha256(donor, dp)
                == function["expected_donor_metadata_sha256"],
                "instruction-mosaic donor metadata differs from its pin")

    seed_body = coff_body(seed, sp)
    donor_body = coff_body(donor, dp)
    require(sha256_bytes(seed_body)
            == function["expected_seed_body_sha256"],
            "instruction-mosaic seed body differs from its pin")
    require(sha256_bytes(donor_body)
            == function["expected_donor_body_sha256"],
            "instruction-mosaic donor body differs from its pin")
    seed_rows = detailed_relocations(seed, sp)
    donor_rows = detailed_relocations(donor, dp)
    require(len(seed_rows) == len(donor_rows)
            == function["expected_relocation_count"],
            "instruction-mosaic relocation count changed")
    seed_lines = _coff_table_bytes(seed, sp, "lines")
    donor_lines = _coff_table_bytes(donor, dp, "lines")
    require(len(seed_lines) >= 6 and len(donor_lines) >= 6,
            "instruction-mosaic function line table is missing")
    if not source_permutation:
        require(len(seed_lines) == len(donor_lines)
                and seed_lines[4:] == donor_lines[4:],
                "instruction-mosaic function line table changed")
    for role, coff, line_bytes in (
        ("seed", seed, seed_lines), ("donor", donor, donor_lines),
    ):
        symbol_index = int.from_bytes(line_bytes[:4], "little")
        function_index, _ = function_symbol(
            coff, mangled,
            sp["number"] if role == "seed" else dp["number"],
        )
        require(line_bytes[4:6] == b"\0\0"
                and symbol_index == function_index,
                f"instruction-mosaic {role} line marker changed identity")

    if self_permutation:
        # The composed object keeps the seed's line table verbatim, so a
        # permutation may not move code across a compiler line boundary:
        # no line row may fall strictly inside the exchanged window in
        # either compiler state.
        window = (permutation["target_start"], permutation["target_end"])
        for role, coff, section, line_bytes in (
            ("seed", seed, sp, seed_lines), ("donor", donor, dp, donor_lines),
        ):
            for index in range(1, section["line_count"]):
                offset, line = coff_unpack(
                    "<IH", line_bytes, index * 6,
                    f"instruction self-permutation {role} line row {index}")
                require(
                    line != 0
                    and not (window[0] < offset < window[1]),
                    f"instruction self-permutation crosses a {role} "
                    "compiler line boundary",
                )

    if ordinary_fpo or source_fpo or self_permutation:
        require_coff_line_certified_ia32_boundaries(
            seed, sp, seed_body, ranges, "seed", mangled,
            "instruction-mosaic seed",
        )
        require_coff_line_certified_ia32_boundaries(
            donor, dp, donor_body, ranges, "donor", mangled,
            "instruction-mosaic donor",
        )

    code_relocation_renames = (
        require_instruction_mosaic_semantic_relocations(
            seed, sp, donor, dp, "instruction-mosaic code",
            permuted_ranges=(
                [(item["start"], item["end"]) for item in ranges]
                if permuted_relocations else None
            ),
            reseat_windows=reseat_windows if reseated else None,
        )
    )

    mosaic = bytearray(seed_body)
    range_detail = []
    output_rows = [dict(row) for row in seed_rows]
    reseat_detail = []
    for index, item in enumerate(ranges):
        start, end = item["start"], item["end"]
        require(end <= len(donor_body),
                f"instruction-mosaic donor instruction {index} is absent")
        seed_instruction = seed_body[start:end]
        donor_instruction = donor_body[start:end]
        require(seed_instruction.hex() == item["seed_bytes"]
                and sha256_bytes(seed_instruction) == item["seed_sha256"],
                f"instruction-mosaic seed instruction {index} drifted")
        require(donor_instruction.hex() == item["donor_bytes"]
                and sha256_bytes(donor_instruction) == item["donor_sha256"],
                f"instruction-mosaic donor instruction {index} drifted")
        contained = []
        for role, rows, body in (
            ("seed", seed_rows, seed_body),
            ("donor", donor_rows, donor_body),
        ):
            ordinals = []
            for ordinal, row in enumerate(rows):
                operand_start = row["offset"]
                operand_end = operand_start + row["width"]
                if end <= operand_start or start >= operand_end:
                    continue
                require(start <= operand_start and operand_end <= end,
                        f"instruction-mosaic range {index} partially overlaps "
                        f"a {role} relocation operand")
                ordinals.append(ordinal)
            contained.append(ordinals)
        if permuted_relocations:
            # ordinals may differ outside the ranges; inside a range the
            # records are paired by offset and must be identical
            require(len(contained[0]) == len(contained[1]),
                    f"instruction-mosaic range {index} contains unpaired "
                    "relocation operands")
            pairs = list(zip(
                sorted(contained[0], key=lambda o: seed_rows[o]["offset"]),
                sorted(contained[1], key=lambda o: donor_rows[o]["offset"]),
            ))
        else:
            require(contained[0] == contained[1],
                    f"instruction-mosaic range {index} contains unpaired "
                    "relocation operands")
            pairs = [(ordinal, ordinal) for ordinal in contained[0]]
        if source_fpo:
            require(not contained[0],
                    f"source FPO instruction-mosaic range {index} overlaps "
                    "a relocation operand")
        reseat = bool(item.get("relocation_reseat"))
        if reseat:
            require(
                [seed_rows[o]["offset"] for o in contained[0]]
                == item["seed_relocation_offsets"]
                and [donor_rows[o]["offset"] for o in contained[1]]
                == item["donor_relocation_offsets"],
                f"instruction-mosaic range {index} relocation operands "
                "differ from the declared reseat",
            )
        for seed_ordinal, donor_ordinal in pairs:
            left, right = seed_rows[seed_ordinal], donor_rows[donor_ordinal]
            strict_fields = (
                "offset", "width", "type", "addend", "target",
                "target_section", "target_value", "target_type",
                "target_storage",
            )
            if reseat:
                # the record itself is identical; only its operand seat
                # inside this range follows the donor's instruction order
                strict_fields = strict_fields[1:]
            require(all(left[field] == right[field]
                        for field in strict_fields),
                    f"instruction-mosaic range {index} contains a changed "
                    "relocation")
            if reseat:
                output_rows[seed_ordinal]["offset"] = right["offset"]
                reseat_detail.append({
                    "range": index, "ordinal": seed_ordinal,
                    "seed_offset": left["offset"],
                    "output_offset": right["offset"],
                    "target": left["target"],
                })
                continue
            operand_start, width = left["offset"], left["width"]
            require(seed_body[operand_start:operand_start + width]
                    == donor_body[operand_start:operand_start + width],
                    f"instruction-mosaic range {index} relocation operand "
                    "bytes differ")
        mosaic[start:end] = donor_instruction
        range_detail.append({
            "start": start, "end": end,
            "donor": item.get("donor", function["donor"]),
            "seed_sha256": item["seed_sha256"],
            "donor_sha256": item["donor_sha256"],
        })
    permutation_detail = []
    if self_permutation:
        source_start = permutation["source_start"]
        source_end = permutation["source_end"]
        target_start = permutation["target_start"]
        target_end = permutation["target_end"]
        for role, rows, start, end in (
            ("seed target", seed_rows, target_start, target_end),
            ("donor source", donor_rows, source_start, source_end),
        ):
            require(
                all(end <= row["offset"]
                    or start >= row["offset"] + row["width"]
                    for row in rows),
                f"instruction self-permutation intersects a {role} "
                "relocation operand",
            )
        for index, move in enumerate(permutation["moves"]):
            donor_instruction = donor_body[
                move["donor_start"]:move["donor_end"]]
            require(
                donor_instruction.hex() == move["donor_bytes"]
                and sha256_bytes(donor_instruction)
                == move["donor_sha256"],
                f"instruction self-permutation donor instruction {index} "
                "drifted",
            )
            require(
                donor_instruction.hex() == move["target_bytes"]
                and sha256_bytes(donor_instruction)
                == move["target_sha256"],
                f"instruction self-permutation target instruction {index} "
                "differs from its donor",
            )
            mosaic[move["target_start"]:move["target_end"]] = (
                donor_instruction)
            permutation_detail.append({
                "target_start": move["target_start"],
                "target_end": move["target_end"],
                "donor_start": move["donor_start"],
                "donor_end": move["donor_end"],
                "sha256": move["donor_sha256"],
            })
    mosaic = bytes(mosaic)
    if self_permutation:
        source_certificate = [{
            "start": permutation["source_start"],
            "end": permutation["source_end"],
            "donor_instruction_lengths": permutation[
                "source_instruction_lengths"],
        }]
        target_certificate = [{
            "start": permutation["target_start"],
            "end": permutation["target_end"],
            "seed_instruction_lengths": permutation[
                "target_instruction_lengths"],
        }]
        require_coff_line_certified_ia32_boundaries(
            donor, dp, donor_body, source_certificate, "donor", mangled,
            "FPO self-permutation donor source",
        )
        require_coff_line_certified_ia32_boundaries(
            seed, sp, mosaic, target_certificate, "seed", mangled,
            "FPO self-permutation target output",
        )
    require(sha256_bytes(mosaic) == function["expected_body_sha256"],
            "instruction-mosaic final body differs from its pin")

    pinned_length = function["retail_oracle"]["length"]
    require(len(retail_body) == pinned_length == expected_length,
            "instruction-mosaic retail body length changed")
    if reseated:
        require(reseat_detail,
                "relocation reseat ranges reseat no relocation")
        require(
            all(a["offset"] + a["width"] <= b["offset"]
                for a, b in zip(output_rows, output_rows[1:])),
            "reseated relocation table is not in ascending operand order",
        )
    semantic_detail = require_retail_relocation_oracle(
        output_rows, bytes(retail_body),
        int(function["retail_oracle"]["address"], 16),
        function["retail_relocations"],
        "instruction-mosaic retail relocation oracle",
    )
    masked_mosaic = bytearray(mosaic)
    masked_retail = bytearray(retail_body)
    for row in output_rows:
        start, width = row["offset"], row["width"]
        masked_mosaic[start:start + width] = b"\0" * width
        masked_retail[start:start + width] = b"\0" * width
    differing = sum(a != b for a, b in zip(masked_mosaic, masked_retail))
    require(differing == 0,
            f"instruction mosaic is not retail-exact: {differing} byte(s) "
            "differ under the relocation mask")

    replacements = [
        (sp["raw_offset"] + item["start"],
         sp["raw_offset"] + item["end"],
         donor_body[item["start"]:item["end"]])
        for item in ranges
    ]
    if self_permutation:
        replacements.extend(
            (sp["raw_offset"] + item["target_start"],
             sp["raw_offset"] + item["target_end"],
             donor_body[item["donor_start"]:item["donor_end"]])
            for item in permutation["moves"]
        )
        replacements.sort(key=lambda item: item[0])
    reseat_file_offsets = set()
    for entry in reseat_detail:
        record_offset = sp["relocation_offset"] + 10 * entry["ordinal"]
        replacements.append((
            record_offset, record_offset + 4,
            entry["output_offset"].to_bytes(4, "little"),
        ))
        reseat_file_offsets.update(range(record_offset, record_offset + 4))
    replacements.sort(key=lambda item: item[0])
    output = apply_replacements(seed_bytes, replacements)
    require(len(output) == len(seed_bytes),
            "instruction-mosaic object size changed")
    changed_file_offsets = {
        index for index, (before, after) in enumerate(zip(seed_bytes, output))
        if before != after
    }
    allowed_file_offsets = {
        sp["raw_offset"] + offset
        for item in ranges
        for offset in range(item["start"], item["end"])
    }
    if self_permutation:
        allowed_file_offsets.update(
            sp["raw_offset"] + offset
            for item in permutation["moves"]
            for offset in range(item["target_start"], item["target_end"])
        )
    allowed_file_offsets |= reseat_file_offsets
    require(changed_file_offsets and changed_file_offsets <= allowed_file_offsets,
            "instruction mosaic changed a non-target byte")
    if self_permutation:
        changed_body_offsets = sorted(
            offset - sp["raw_offset"] for offset in changed_file_offsets)
        require(
            changed_body_offsets == permutation["expected_changed_offsets"],
            "instruction self-permutation changed-offset set differs",
        )

    checked = CoffObject(output)
    cp = checked.function_section(mangled)
    require(coff_body(checked, cp) == mosaic,
            "instruction-mosaic output body differs")
    require(detailed_relocations(checked, cp) == output_rows,
            "instruction-mosaic seed relocations changed")
    if reseated:
        require(
            sha256_bytes(_coff_table_bytes(checked, cp, "relocations"))
            == function["expected_output_relocation_sha256"],
            "instruction-mosaic reseated relocation table differs from "
            "its pin",
        )
    else:
        require(_coff_table_bytes(checked, cp, "relocations")
                == _coff_table_bytes(seed, sp, "relocations"),
                "instruction-mosaic seed relocation table changed")
    require(_coff_table_bytes(checked, cp, "lines")
            == _coff_table_bytes(seed, sp, "lines"),
            "instruction-mosaic seed line table changed")
    if ordinary_fpo or source_fpo or self_permutation:
        require(
            instruction_mosaic_metadata_sha256(checked, cp)
            == function[
                "expected_output_metadata_sha256" if reseated
                else "expected_seed_metadata_sha256"],
            "instruction-mosaic output metadata changed",
        )
    require(function_multiset(checked) == function_multiset(seed),
            "instruction-mosaic output function set changed")
    for left, _ in closure_pairs:
        child = _comdat_child(checked, cp, left["name"])
        require(coff_body(checked, child) == coff_body(seed, left)
                and _coff_table_bytes(checked, child, "relocations")
                == _coff_table_bytes(seed, left, "relocations")
                and _coff_table_bytes(checked, child, "lines")
                == _coff_table_bytes(seed, left, "lines"),
                f"instruction-mosaic seed {left['name']} changed")
    return output, {
        "mangled": mangled,
        "splice_class": "retail_exact_instruction_mosaic",
        "section_number": cp["number"],
        "body_length": cp["raw_size"],
        "instruction_ranges": range_detail,
        "instruction_self_permutation": permutation_detail,
        "body_changed_offsets": sorted(
            offset - sp["raw_offset"]
            for offset in changed_file_offsets - reseat_file_offsets),
        "relocations": len(seed_rows),
        "relocation_reseats": reseat_detail,
        "line_count": cp["line_count"],
        "closure": list(closure[1]),
        "ordinary_fpo_identity": ordinary_fpo,
        "source_fpo_identity": source_fpo,
        "code_relocation_renames": code_relocation_renames,
        "closure_relocation_renames": closure_relocation_renames,
        "relocation_order": (
            MOSAIC_PERMUTED_RELOCATION_ORDER if permuted_relocations
            else "ordinal"),
        "retail_exact": True,
        **semantic_detail,
    }


def compose_retail_exact_instruction_mosaic(
    seed_bytes: bytes,
    donor_bytes: bytes,
    function: dict,
    retail_body: bytes,
    additional_donor_bytes: dict[str, bytes] | None = None,
) -> tuple[bytes, dict]:
    """Compose a declaration-carrier instruction mosaic.

    With ``donor_variants`` the mosaic may draw its same-offset complete
    instructions from several freshly compiled declaration-carrier states of
    the same translation unit.  Every variant is authenticated against the
    seed exactly like the main donor (seat, section census, function and
    COMDAT identity sets, relocation semantics, closure, pinned body and
    metadata) before its instructions enter the combined donor view, and the
    combined view is then handed to the unchanged single-donor composer.
    """
    require("target_source_refactor" not in function,
            "source-permutation mosaic requires its source-proof composer")
    variant_detail = {}
    effective_donor = donor_bytes
    effective_function = function
    if function.get("donor_variants"):
        require(instruction_mosaic_metadata_sha256(
                    CoffObject(seed_bytes),
                    CoffObject(seed_bytes).function_section(
                        function["mangled"]))
                == function["expected_seed_metadata_sha256"],
                "instruction-mosaic seed metadata differs from its pin")
        effective_donor, variant_detail = (
            _compose_instruction_mosaic_variant_object(
                seed_bytes, donor_bytes, additional_donor_bytes or {},
                function,
            )
        )
        effective_function = dict(function)
        effective_function["expected_donor_body_sha256"] = (
            function["expected_mosaic_donor_body_sha256"])
        if "instruction_self_permutation" in function:
            # Only the main donor carries the same-function source identity,
            # so the exchanged window must still be that donor's own output.
            # Every mosaic range is separately required to stay clear of the
            # window, and this binds the resulting bytes to the pinned
            # main-donor body rather than to any variant.
            window = function["instruction_self_permutation"]
            start, end = window["target_start"], window["target_end"]
            main = CoffObject(donor_bytes)
            combined = CoffObject(effective_donor)
            main_body = coff_body(
                main, main.function_section(function["mangled"]))
            combined_body = coff_body(
                combined, combined.function_section(function["mangled"]))
            require(
                len(main_body) == len(combined_body)
                and main_body[start:end] == combined_body[start:end],
                "instruction self-permutation window is not the "
                "source-authentic main donor's own output",
            )
    else:
        require(not additional_donor_bytes,
                "instruction mosaic names undeclared donor variants")
    composed, detail = _compose_retail_exact_instruction_mosaic_core(
        seed_bytes, effective_donor, effective_function, retail_body,
        source_permutation=False,
    )
    return composed, {**detail, **variant_detail}


def compose_retail_exact_source_instruction_mosaic(
    seed_bytes: bytes,
    donor_bytes: bytes,
    function: dict,
    retail_body: bytes,
    seed_source: bytes,
    donor_source: bytes,
    additional_donor_bytes: dict[str, bytes] | None = None,
) -> tuple[bytes, dict]:
    """Compose a mosaic from one authenticated source permutation."""
    require(function.get("splice_class")
            == "retail_exact_instruction_mosaic"
            and "target_source_refactor" in function,
            "source-permutation mosaic contract is missing")
    owner = function["target_source_refactor"].get(
        "source_owner_mangled")
    if owner is not None:
        # The source proof names the function whose checked-in spelling is
        # permuted.  Bind that claim to both compiled objects even when a
        # future consumer imports a different same-TU COMDAT.
        CoffObject(seed_bytes).function_section(owner)
        CoffObject(donor_bytes).function_section(owner)
    source_detail = require_target_source_refactor_identity(
        seed_source, donor_source, function["target_source_refactor"],
        "retail-exact instruction-mosaic source proof",
    )
    variant_detail = {}
    effective_donor = donor_bytes
    effective_function = function
    if function.get("donor_variants"):
        effective_donor, variant_detail = (
            _compose_instruction_mosaic_variant_object(
                seed_bytes, donor_bytes, additional_donor_bytes or {},
                function,
            )
        )
        effective_function = dict(function)
        effective_function["expected_donor_body_sha256"] = (
            function["expected_mosaic_donor_body_sha256"])
    composed, detail = _compose_retail_exact_instruction_mosaic_core(
        seed_bytes, effective_donor, effective_function, retail_body,
        source_permutation=True,
    )
    return composed, {**detail, **source_detail, **variant_detail}


def _compose_retail_exact_instruction_hybrid_resize_core(
    seed_bytes: bytes,
    target_donor_bytes: bytes,
    instruction_donor_bytes: bytes,
    function: dict,
    retail_body: bytes,
    *, source_aware: bool, same_tu_source_identical: bool = False,
) -> tuple[bytes, dict]:
    """Import complete same-mangled instructions, then resize normally.

    The target donor supplies the complete resize closure.  A second freshly
    compiled donor state may supply only manifest-pinned instruction bytes
    from its definition of that exact mangled COMDAT.  The temporary hybrid
    is never a link input: after proving that it differs from the target donor
    only inside the declared text ranges, it is handed to the unchanged
    retail-exact same-slot composer.
    """
    require(not (source_aware and same_tu_source_identical),
            "instruction hybrid source modes overlap")
    expected_class = (
        SAME_TU_INSTRUCTION_HYBRID_RESIZE_CLASS
        if same_tu_source_identical else
        SOURCE_INSTRUCTION_HYBRID_RESIZE_CLASS
        if source_aware else CROSS_TU_INSTRUCTION_HYBRID_RESIZE_CLASS
    )
    fully_pinned = source_aware or same_tu_source_identical
    require(function.get("splice_class") == expected_class,
            "splice class is not the selected instruction hybrid resize")
    require(isinstance(retail_body, (bytes, bytearray)) and retail_body,
            "retail oracle body is missing")
    seed = CoffObject(seed_bytes)
    target = CoffObject(target_donor_bytes)
    instruction_donor = CoffObject(instruction_donor_bytes)
    mangled = function["mangled"]
    seed_primary = seed.function_section(mangled)
    target_primary = target.function_section(mangled)
    instruction_primary = instruction_donor.function_section(mangled)

    require(
        len(target.sections) == function["expected_target_donor_section_count"]
        and target_primary["number"]
        == function["expected_target_donor_section_number"],
        "target donor section census or seat changed",
    )
    require(
        len(instruction_donor.sections)
        == function["expected_instruction_donor_section_count"]
        and instruction_primary["number"]
        == function["expected_instruction_donor_section_number"],
        "instruction donor section census or seat changed",
    )
    require(
        target_primary["raw_size"] == function["expected_donor_length"]
        and target_primary["relocation_count"]
        == function["expected_target_donor_relocation_count"]
        and target_primary["line_count"]
        == function["expected_target_donor_line_count"],
        "target donor body/table census changed",
    )
    require(
        instruction_primary["raw_size"]
        == function["expected_instruction_donor_length"]
        and instruction_primary["relocation_count"]
        == function["expected_instruction_donor_relocation_count"]
        and instruction_primary["line_count"]
        == function["expected_instruction_donor_line_count"],
        "instruction donor body/table census changed",
    )
    require(
        comdat_primary_identity(target, target_primary)
        == comdat_primary_identity(instruction_donor, instruction_primary),
        "instruction donor is not the exact same mangled COMDAT",
    )
    require(
        all(target_primary[field] == instruction_primary[field]
            for field in ("name", "characteristics")),
        "same-mangled donor COMDAT header class changed",
    )
    if fully_pinned:
        require(
            len(seed.sections) == function["expected_seed_section_count"]
            and seed_primary["number"]
            == function["expected_seed_section_number"],
            "source hybrid seed section census or seat changed",
        )
        require(
            seed_primary["raw_size"] == function["expected_seed_length"]
            and seed_primary["relocation_count"]
            == function["expected_seed_relocation_count"]
            and seed_primary["line_count"]
            == function["expected_seed_line_count"],
            "source hybrid seed body/table census changed",
        )
        require(
            sha256_bytes(coff_body(seed, seed_primary))
            == function["expected_seed_body_sha256"],
            "source hybrid seed body differs from its pin",
        )
        require(
            instruction_mosaic_metadata_sha256(seed, seed_primary)
            == function["expected_seed_metadata_sha256"],
            "source hybrid seed metadata differs from its pin",
        )
        require(
            sum(function_multiset(seed).values())
            == function["expected_seed_function_count"]
            and
            sum(function_multiset(target).values())
            == function["expected_target_donor_function_count"]
            and sum(function_multiset(instruction_donor).values())
            == function["expected_instruction_donor_function_count"],
            "source hybrid donor function census changed",
        )
        require(
            sum(comdat_primary_identity_multiset(seed).values())
            == function["expected_seed_comdat_count"]
            and
            sum(comdat_primary_identity_multiset(target).values())
            == function["expected_target_donor_comdat_count"]
            and sum(comdat_primary_identity_multiset(
                instruction_donor).values())
            == function["expected_instruction_donor_comdat_count"],
            "source hybrid donor COMDAT census changed",
        )
        closure = tuple(function["expected_donor_closure"])
        expected_closure = (len(closure), closure)
        require(
            all(value == expected_closure for value in (
                _comdat_child_closure(seed, seed_primary),
                _comdat_child_closure(target, target_primary),
                _comdat_child_closure(
                    instruction_donor, instruction_primary),
            )),
            "source hybrid donor closure changed",
        )
        require(
            instruction_mosaic_metadata_sha256(target, target_primary)
            == function["expected_target_donor_metadata_sha256"],
            "source hybrid target-donor metadata differs from its pin",
        )
        require(
            instruction_mosaic_metadata_sha256(
                instruction_donor, instruction_primary)
            == function["expected_instruction_donor_metadata_sha256"],
            "source hybrid instruction-donor metadata differs from its pin",
        )
    if same_tu_source_identical:
        require(
            function_multiset(seed) == function_multiset(target)
            == function_multiset(instruction_donor),
            "same-TU hybrid function universe changed",
        )
        require(
            comdat_primary_identity_multiset(seed)
            == comdat_primary_identity_multiset(target)
            == comdat_primary_identity_multiset(instruction_donor),
            "same-TU hybrid COMDAT universe changed",
        )
        require_instruction_mosaic_semantic_relocations(
            target, target_primary, instruction_donor,
            instruction_primary, "same-TU hybrid code",
        )

    target_body = coff_body(target, target_primary)
    instruction_body = coff_body(instruction_donor, instruction_primary)
    require(sha256_bytes(target_body)
            == function["expected_target_donor_body_sha256"],
            "target donor body differs from its pin")
    require(sha256_bytes(instruction_body)
            == function["expected_instruction_donor_body_sha256"],
            "instruction donor body differs from its pin")
    ranges = validate_cross_tu_instruction_hybrid_ranges(
        function.get("instruction_ranges"),
        "instruction hybrid ranges",
        len(target_body), len(instruction_body),
        range_kind=(
            "same_tu_source_identical_complete_x86_instruction_v1"
            if same_tu_source_identical else
            "source_same_mangled_complete_x86_instruction_v1"
            if source_aware else
            "cross_tu_same_mangled_complete_x86_instruction_v1"
        ),
        require_same_offsets=fully_pinned,
    )
    require_coff_line_certified_ia32_boundaries(
        target, target_primary, target_body, ranges, "target", mangled,
        "instruction hybrid target donor")
    require_coff_line_certified_ia32_boundaries(
        instruction_donor, instruction_primary, instruction_body, ranges,
        "instruction_donor", mangled,
        "instruction hybrid instruction donor")
    target_relocations = detailed_relocations(target, target_primary)
    instruction_relocations = detailed_relocations(
        instruction_donor, instruction_primary)

    hybrid = bytearray(target_donor_bytes)
    range_detail = []
    for index, item in enumerate(ranges):
        target_start, target_end = (
            item["target_start"], item["target_end"])
        source_start, source_end = (
            item["instruction_donor_start"],
            item["instruction_donor_end"],
        )
        target_instruction = target_body[target_start:target_end]
        source_instruction = instruction_body[source_start:source_end]
        require(
            target_instruction.hex() == item["target_bytes"]
            and sha256_bytes(target_instruction) == item["target_sha256"],
            f"cross-TU target instruction {index} drifted",
        )
        require(
            source_instruction.hex() == item["instruction_donor_bytes"]
            and sha256_bytes(source_instruction)
            == item["instruction_donor_sha256"],
            f"cross-TU instruction donor instruction {index} drifted",
        )
        for role, rows, start, end in (
            ("target donor", target_relocations, target_start, target_end),
            ("instruction donor", instruction_relocations,
             source_start, source_end),
        ):
            require(all(
                end <= row["offset"]
                or start >= row["offset"] + row["width"]
                for row in rows
            ), f"cross-TU range {index} overlaps a {role} relocation operand")
        at = target_primary["raw_offset"] + target_start
        hybrid[at:at + target_end - target_start] = source_instruction
        range_detail.append({
            "target_start": target_start,
            "target_end": target_end,
            "instruction_donor_start": source_start,
            "instruction_donor_end": source_end,
            "target_sha256": item["target_sha256"],
            "instruction_donor_sha256": item[
                "instruction_donor_sha256"],
        })

    hybrid = bytes(hybrid)
    changed_file_offsets = {
        offset for offset, (before, after) in enumerate(
            zip(target_donor_bytes, hybrid)) if before != after
    }
    allowed_file_offsets = {
        target_primary["raw_offset"] + offset
        for item in ranges
        for offset in range(item["target_start"], item["target_end"])
    }
    require(changed_file_offsets
            and changed_file_offsets <= allowed_file_offsets,
            "cross-TU hybrid changed a non-target-donor byte")
    hybrid_coff = CoffObject(hybrid)
    hybrid_primary = hybrid_coff.function_section(mangled)
    hybrid_body = coff_body(hybrid_coff, hybrid_primary)
    require(sha256_bytes(hybrid_body)
            == function["expected_hybrid_body_sha256"],
            "cross-TU hybrid body differs from its pin")
    require(detailed_relocations(hybrid_coff, hybrid_primary)
            == target_relocations,
            "cross-TU hybrid changed target-donor relocations")
    require(_coff_table_bytes(hybrid_coff, hybrid_primary, "lines")
            == _coff_table_bytes(target, target_primary, "lines"),
            "cross-TU hybrid changed the target-donor line table")
    require(_comdat_child_closure(hybrid_coff, hybrid_primary)
            == _comdat_child_closure(target, target_primary),
            "cross-TU hybrid changed the target-donor closure")
    if fully_pinned:
        require(
            instruction_mosaic_metadata_sha256(
                hybrid_coff, hybrid_primary)
            == function["expected_target_donor_metadata_sha256"],
            "source hybrid changed target-donor metadata",
        )

    effective_function = dict(function)
    effective_function["splice_class"] = "retail_exact_reloc_divergent"
    effective_function["expected_body_sha256"] = function[
        "expected_hybrid_body_sha256"]
    if fully_pinned:
        effective_function["expected_donor_line_count"] = function[
            "expected_target_donor_line_count"]
    composed, detail = compose_same_slot_resize(
        seed_bytes, hybrid, effective_function,
        retail_body=bytes(retail_body),
    )
    return composed, {
        **detail,
        "splice_class": expected_class,
        "target_donor_body_sha256": sha256_bytes(target_body),
        "instruction_donor_body_sha256": sha256_bytes(instruction_body),
        "hybrid_body_sha256": sha256_bytes(hybrid_body),
        "instruction_ranges": range_detail,
    }


def compose_retail_exact_cross_tu_instruction_hybrid_resize(
    seed_bytes: bytes,
    target_donor_bytes: bytes,
    instruction_donor_bytes: bytes,
    function: dict,
    retail_body: bytes,
) -> tuple[bytes, dict]:
    """Compose the existing clean-current-source cross-TU hybrid class."""
    require("instruction_donor_source_refactor" not in function,
            "clean cross-TU hybrid may not carry a source-refactor proof")
    return _compose_retail_exact_instruction_hybrid_resize_core(
        seed_bytes, target_donor_bytes, instruction_donor_bytes,
        function, retail_body, source_aware=False,
    )


def compose_retail_exact_source_instruction_hybrid_resize(
    seed_bytes: bytes,
    target_donor_bytes: bytes,
    instruction_donor_bytes: bytes,
    function: dict,
    retail_body: bytes,
    seed_source: bytes,
    instruction_donor_source: bytes,
) -> tuple[bytes, dict]:
    """Authenticate one source permutation before importing instructions."""
    require(
        function.get("splice_class")
        == SOURCE_INSTRUCTION_HYBRID_RESIZE_CLASS
        and "instruction_donor_source_refactor" in function,
        "source instruction-hybrid contract is missing",
    )
    proof = function["instruction_donor_source_refactor"]
    require(proof.get("source_owner_mangled") == function.get("mangled"),
            "source instruction-hybrid owner differs")
    owner = proof["source_owner_mangled"]
    CoffObject(target_donor_bytes).function_section(owner)
    CoffObject(instruction_donor_bytes).function_section(owner)
    source_detail = require_target_source_refactor_identity(
        seed_source, instruction_donor_source, proof,
        "source instruction-hybrid source proof",
    )
    composed, detail = _compose_retail_exact_instruction_hybrid_resize_core(
        seed_bytes, target_donor_bytes, instruction_donor_bytes,
        function, retail_body, source_aware=True,
    )
    return composed, {**detail, **source_detail}


def compose_retail_exact_same_tu_instruction_hybrid_resize(
    seed_bytes: bytes,
    target_donor_bytes: bytes,
    instruction_donor_bytes: bytes,
    function: dict,
    retail_body: bytes,
    seed_source: bytes,
    target_donor_source: bytes,
    instruction_donor_source: bytes,
) -> tuple[bytes, dict]:
    """Compose two source-identical, declaration-carrier same-TU donors."""
    require(
        function.get("splice_class")
        == SAME_TU_INSTRUCTION_HYBRID_RESIZE_CLASS
        and "same_tu_source_identity" in function
        and "instruction_donor_source_refactor" not in function,
        "same-TU instruction-hybrid contract is missing",
    )
    proof = function["same_tu_source_identity"]
    require(proof.get("source_owner_mangled") == function.get("mangled"),
            "same-TU instruction-hybrid owner differs")
    owner = proof["source_owner_mangled"]
    for data in (seed_bytes, target_donor_bytes, instruction_donor_bytes):
        CoffObject(data).function_section(owner)
    source_detail = require_same_tu_source_identity(
        seed_source, target_donor_source, instruction_donor_source,
        proof, "same-TU instruction-hybrid source proof",
    )
    composed, detail = _compose_retail_exact_instruction_hybrid_resize_core(
        seed_bytes, target_donor_bytes, instruction_donor_bytes,
        function, retail_body, source_aware=False,
        same_tu_source_identical=True,
    )
    return composed, {**detail, **source_detail}


def compose_retail_exact_reloc_divergent(
    seed_bytes: bytes,
    donor_bytes: bytes,
    function: dict,
    retail_body: bytes,
) -> tuple[bytes, dict]:
    """Splice a donor body whose EXTERNAL relocation target set diverges.

    Every `same_slot_resize` check applies except relocation-target equality.
    In its place stands B1: the composed body must be byte-identical to
    retail's own code under the relocation mask, so this class can only ever
    install retail's code and can never become a general escape hatch from
    relocation-equivalence discipline.

    `retail_body` is extracted by the build from the sha256-pinned retail
    image at the function's pinned `retail_va`/`retail_length`.
    """
    require(function.get("splice_class") == "retail_exact_reloc_divergent",
            "splice class is not retail_exact_reloc_divergent")
    require("target_source_refactor" not in function,
            "source-refactor function requires its source-proof composer")
    require(isinstance(retail_body, (bytes, bytearray)) and retail_body,
            "retail oracle body is missing")
    return compose_same_slot_resize(seed_bytes, donor_bytes, function,
                                    retail_body=bytes(retail_body))


def compose_retail_exact_source_refactor(
    seed_bytes: bytes,
    donor_bytes: bytes,
    function: dict,
    retail_body: bytes,
    seed_source: bytes,
    donor_source: bytes,
) -> tuple[bytes, dict]:
    """Compose a retail-exact body from one closed source refactor donor.

    Keeping the source proof in this public wrapper makes it impossible for a
    caller to honor ``target_source_refactor`` while accidentally invoking
    only the object-level divergent composer.
    """
    require(function.get("splice_class") == "retail_exact_reloc_divergent"
            and "target_source_refactor" in function,
            "retail-exact source-refactor contract is missing")
    require(isinstance(retail_body, (bytes, bytearray)) and retail_body,
            "retail oracle body is missing")
    source_detail = require_target_source_refactor_identity(
        seed_source, donor_source, function["target_source_refactor"],
        "retail-exact source-refactor proof",
    )
    composed, detail = compose_same_slot_resize(
        seed_bytes, donor_bytes, function, retail_body=bytes(retail_body),
    )
    return composed, {**detail, **source_detail}


def compose_retail_exact_target_closure(
    seed_bytes: bytes,
    donor_bytes: bytes,
    function: dict,
    retail_body: bytes,
    seed_source: bytes,
    donor_source: bytes,
) -> tuple[bytes, dict]:
    """Extract one retail-exact target closure from an authenticated donor.

    The donor may omit only a pinned set of unrelated definitions.  Those
    omissions never enter the output: the seed remains the object shell and
    retains its full function multiset, while the target source range is
    proven byte-identical between the two complete pinned renderings.
    """
    require(function.get("splice_class") == "retail_exact_target_closure",
            "splice class is not retail_exact_target_closure")
    require(isinstance(retail_body, (bytes, bytearray)) and retail_body,
            "retail oracle body is missing")
    source_detail = require_target_source_range_identity(
        seed_source, donor_source, function["target_source_range"],
        "target-closure source proof",
    )
    composed, detail = compose_same_slot_resize(
        seed_bytes, donor_bytes, function,
        retail_body=bytes(retail_body), target_closure_extract=True,
    )
    return composed, {**detail, **source_detail}


def compose_retail_exact_source_target_closure(
    seed_bytes: bytes,
    donor_bytes: bytes,
    function: dict,
    retail_body: bytes,
    seed_source: bytes,
    donor_source: bytes,
) -> tuple[bytes, dict]:
    """Extract one pinned retail target from a closed source permutation."""
    require(function.get("splice_class")
            == "retail_exact_source_target_closure",
            "splice class is not retail_exact_source_target_closure")
    source_detail = require_target_source_range_identity(
        seed_source, donor_source, function["target_source_range"],
        "source-target closure source proof",
    )
    composed, detail = compose_same_slot_resize(
        seed_bytes, donor_bytes, function, retail_body=bytes(retail_body),
        source_target_extract=True,
    )
    return composed, {**detail, **source_detail}


def compose_swap_comdat_group_order(
    seed_bytes: bytes,
    specification: dict,
) -> tuple[bytes, dict]:
    """Swap the link-visible order of two complete compiler-produced COMDAT
    groups (primary + associated children) inside one object, renumbering
    section ordinals and associations only.

    No raw code, relocation, xdata, data, line, or debug payload byte moves;
    every symbol keeps its exact raw contribution.  The permutation makes
    the `first` function's group precede the `second` function's group; the
    intervening contributions keep their relative order.
    """
    seed = CoffObject(seed_bytes)
    first = seed.function_section(specification["first"])
    second = seed.function_section(specification["second"])
    definitions = section_definitions(seed)

    def group(primary: dict) -> list[int]:
        children = [
            section["number"]
            for section in seed.sections
            if definitions.get(section["number"], {}).get("selection") == 5
            and definitions[section["number"]]["associated"]
            == primary["number"]
        ]
        return [primary["number"], *children]

    first_group = group(first)
    second_group = group(second)
    require(not set(first_group) & set(second_group),
            "COMDAT groups overlap")
    require(second["number"] < first["number"],
            "the requested group order already holds")
    window = sorted(set(first_group) | set(second_group))
    low, high = min(window), max(
        max(first_group), max(second_group))
    window_numbers = list(range(low, high + 1))
    rest = [number for number in window_numbers
            if number not in first_group and number not in second_group]
    new_order = first_group + second_group + rest
    require(sorted(new_order) == window_numbers,
            "group window is not a permutation")
    old_to_new = {
        old: window_numbers[index] for index, old in enumerate(new_order)
    }

    def mapped(number: int) -> int:
        return old_to_new.get(number, number)

    work = bytearray(seed_bytes)
    original_headers = {
        number: seed_bytes[20 + (number - 1) * 40:20 + number * 40]
        for number in window_numbers
    }
    for old, new in old_to_new.items():
        start = 20 + (new - 1) * 40
        work[start:start + 40] = original_headers[old]

    symbol_writes = 0
    association_writes = 0
    for index, symbol in seed.symbols.items():
        if symbol["section"] > 0 and mapped(symbol["section"]) != symbol["section"]:
            offset = seed.symbol_offset + index * 18 + 12
            work[offset:offset + 2] = mapped(symbol["section"]).to_bytes(
                2, "little", signed=True)
            symbol_writes += 1
        definition = definitions.get(symbol["section"])
        if (definition is not None
                and symbol["storage"] == 3
                and symbol["aux_count"]
                and symbol["name"]
                == seed.sections[symbol["section"] - 1]["name"]
                and definition["selection"] == 5
                and mapped(definition["associated"])
                != definition["associated"]):
            aux = seed.symbol_offset + (index + 1) * 18
            parent = mapped(definition["associated"])
            work[aux + 12:aux + 14] = (parent & 0xFFFF).to_bytes(2, "little")
            work[aux + 16:aux + 18] = (parent >> 16).to_bytes(2, "little")
            association_writes += 1

    composed = bytes(work)
    require(len(composed) == len(seed_bytes), "object size changed")
    checked = CoffObject(composed)
    checked_definitions = section_definitions(checked)
    section_fields = (
        "name", "raw_size", "raw_offset", "relocation_offset",
        "relocation_count", "line_offset", "line_count", "characteristics",
    )
    for section in seed.sections:
        peer = checked.sections[mapped(section["number"]) - 1]
        require(all(section[field] == peer[field]
                    for field in section_fields),
                f"semantic section changed: old {section['number']}")
    require(seed.symbols.keys() == checked.symbols.keys(),
            "symbol index set changed")
    for index, symbol in seed.symbols.items():
        peer = checked.symbols[index]
        require(
            all(symbol[field] == peer[field]
                for field in ("name", "value", "type", "storage",
                              "aux_count"))
            and peer["section"] == mapped(symbol["section"]),
            f"symbol identity changed at {index}",
        )
    for old_number, definition in definitions.items():
        peer = checked_definitions.get(mapped(old_number))
        require(peer is not None
                and peer["selection"] == definition["selection"]
                and peer["associated"] == mapped(definition["associated"]),
                f"section definition mapping changed: {old_number}")
    checked_first = checked.function_section(specification["first"])
    checked_second = checked.function_section(specification["second"])
    require(checked_first["number"] < checked_second["number"],
            "target group order was not swapped")
    for name in sorted({
        section["name"] for section in seed.sections
        if not section["name"].startswith(".debug$")
    }):
        before = [section["raw_offset"] for section in seed.sections
                  if section["name"] == name]
        after = [section["raw_offset"] for section in checked.sections
                 if section["name"] == name]
        if name == first["name"]:
            expected = list(before)
            left = expected.index(first["raw_offset"])
            right = expected.index(second["raw_offset"])
            require(left > right,
                    "target contributions were already ordered")
            expected[left], expected[right] = expected[right], expected[left]
            require(after == expected,
                    "more than the target contribution pair moved")
        else:
            require(after == before,
                    f"link-visible {name} contribution order changed")
    return composed, {
        "first": specification["first"],
        "second": specification["second"],
        "window": [low, high],
        "symbol_section_writes": symbol_writes,
        "association_writes": association_writes,
    }


def compose_restore_comdat_group_order(
    seed_bytes: bytes,
    specification: dict,
) -> tuple[bytes, dict]:
    """Restore the link-visible order of several complete compiler-produced
    `.text` COMDAT groups (primary + associated children) inside one object.

    This is the list form of :func:`compose_swap_comdat_group_order`: the
    ``group_order`` list names `.text` COMDAT primaries in the desired
    (retail-anchored) first-to-last order.  The permutation window is the
    contiguous section-number range spanned by the listed groups.  Every
    `.text` COMDAT group inside that window must be listed (fail-closed), so
    the transform is a pure whole-group permutation of text contributions.
    Sections of any other kind that sit inside the window (string literals,
    data, vftables and their children) keep their own relative order and are
    reseated after the listed groups, so no other link-visible contribution
    order changes.  Only section ordinals and associations are renumbered;
    no raw code, relocation, xdata, data, line, or debug payload byte moves
    and every symbol keeps its exact raw contribution.
    """
    order = specification["group_order"]
    require(isinstance(order, list) and 2 <= len(order) <= 512
            and len(set(order)) == len(order),
            "group_order must be a list of 2..512 distinct names")
    require(all(isinstance(name, str) and name for name in order),
            "group_order names must be non-empty strings")
    seed = CoffObject(seed_bytes)
    definitions = section_definitions(seed)

    def group(primary: dict) -> list[int]:
        children = [
            section["number"]
            for section in seed.sections
            if definitions.get(section["number"], {}).get("selection") == 5
            and definitions[section["number"]]["associated"]
            == primary["number"]
        ]
        return [primary["number"], *children]

    groups = []
    listed = set()
    kinds = set()
    for name in order:
        primary = comdat_primary_section(seed, name)
        members = group(primary)
        require(not set(members) & listed, f"COMDAT groups overlap: {name}")
        listed.update(members)
        kinds.add(primary["name"].split("$")[0])
        groups.append((name, primary, members))
    require(len(kinds) == 1,
            "group_order must name COMDATs of one section kind")
    kind = next(iter(kinds))
    low = min(min(members) for _, _, members in groups)
    high = max(max(members) for _, _, members in groups)
    window_numbers = list(range(low, high + 1))
    # Every contribution of the listed kind inside the window must belong to
    # a listed group; other section kinds may float but keep their relative
    # order.
    unlisted = [number for number in window_numbers if number not in listed]
    for number in unlisted:
        section = seed.sections[number - 1]
        require(section["name"].split("$")[0] != kind,
                f"unlisted {kind} contribution inside the window: "
                f"section {number}")
        definition = definitions.get(number)
        if definition is not None and definition.get("selection") == 5:
            require(definition["associated"] not in listed,
                    f"orphaned associated section inside the window: "
                    f"section {number}")
    new_order = [number for _, _, members in groups for number in members]
    new_order += unlisted
    require(sorted(new_order) == window_numbers,
            "group window is not a permutation")
    old_to_new = {
        old: window_numbers[index] for index, old in enumerate(new_order)
    }
    require(any(old != new for old, new in old_to_new.items()),
            "the requested group order already holds")

    def mapped(number: int) -> int:
        return old_to_new.get(number, number)

    work = bytearray(seed_bytes)
    original_headers = {
        number: seed_bytes[20 + (number - 1) * 40:20 + number * 40]
        for number in window_numbers
    }
    for old, new in old_to_new.items():
        start = 20 + (new - 1) * 40
        work[start:start + 40] = original_headers[old]
    symbol_writes = 0
    association_writes = 0
    for index, symbol in seed.symbols.items():
        if symbol["section"] > 0 and mapped(symbol["section"]) != symbol["section"]:
            offset = seed.symbol_offset + index * 18 + 12
            work[offset:offset + 2] = mapped(symbol["section"]).to_bytes(
                2, "little", signed=True)
            symbol_writes += 1
        definition = definitions.get(symbol["section"])
        if (definition is not None
                and symbol["storage"] == 3
                and symbol["aux_count"]
                and symbol["name"]
                == seed.sections[symbol["section"] - 1]["name"]
                and definition["selection"] == 5
                and mapped(definition["associated"])
                != definition["associated"]):
            aux = seed.symbol_offset + (index + 1) * 18
            parent = mapped(definition["associated"])
            work[aux + 12:aux + 14] = (parent & 0xFFFF).to_bytes(2, "little")
            work[aux + 16:aux + 18] = (parent >> 16).to_bytes(2, "little")
            association_writes += 1

    composed = bytes(work)
    require(len(composed) == len(seed_bytes), "object size changed")
    checked = CoffObject(composed)
    checked_definitions = section_definitions(checked)
    section_fields = (
        "name", "raw_size", "raw_offset", "relocation_offset",
        "relocation_count", "line_offset", "line_count", "characteristics",
    )
    for section in seed.sections:
        peer = checked.sections[mapped(section["number"]) - 1]
        require(all(section[field] == peer[field]
                    for field in section_fields),
                f"semantic section changed: old {section['number']}")
    require(seed.symbols.keys() == checked.symbols.keys(),
            "symbol index set changed")
    for index, symbol in seed.symbols.items():
        peer = checked.symbols[index]
        require(
            all(symbol[field] == peer[field]
                for field in ("name", "value", "type", "storage",
                              "aux_count"))
            and peer["section"] == mapped(symbol["section"]),
            f"symbol identity changed at {index}",
        )
    for old_number, definition in definitions.items():
        peer = checked_definitions.get(mapped(old_number))
        require(peer is not None
                and peer["selection"] == definition["selection"]
                and peer["associated"] == mapped(definition["associated"]),
                f"section definition mapping changing: {old_number}")
    final_numbers = [comdat_primary_section(checked, name)["number"]
                     for name in order]
    require(final_numbers == sorted(final_numbers),
            "target group order was not restored")
    # Link-visible contribution order: only the listed text groups (each
    # primary with its associated children, which the compiler emits with it)
    # may move relative to one another; every section outside the listed
    # groups keeps its relative order under every section name.
    listed_offsets = {
        seed.sections[number - 1]["raw_offset"]
        for _, _, members in groups for number in members
    }
    for name in sorted({
        section["name"] for section in seed.sections
        if not section["name"].startswith(".debug$")
    }):
        before = [section["raw_offset"] for section in seed.sections
                  if section["name"] == name]
        after = [section["raw_offset"] for section in checked.sections
                 if section["name"] == name]
        require(sorted(before) == sorted(after),
                f"{name} contribution set changed")
        require([offset for offset in before if offset not in listed_offsets]
                == [offset for offset in after if offset not in listed_offsets],
                f"an unlisted {name} contribution moved")
        if name.split("$")[0] != kind:
            # Children move exactly with their primaries: the order of the
            # listed children under this name must follow the group order.
            group_rank = {}
            for rank, (_, _, members) in enumerate(groups):
                for number in members:
                    group_rank[seed.sections[number - 1]["raw_offset"]] = rank
            ranks = [group_rank[offset] for offset in after
                     if offset in listed_offsets]
            require(ranks == sorted(ranks),
                    f"listed {name} children do not follow the group order")
    return composed, {
        "group_order": list(order),
        "window": [low, high],
        "unlisted_reseated": len(unlisted),
        "symbol_section_writes": symbol_writes,
        "association_writes": association_writes,
    }


def compose_comdat_selection_override(
    seed_bytes: bytes,
    donor_bytes: bytes,
    function: dict,
    retail_body: bytes,
) -> tuple[bytes, dict]:
    """Class C: install another object's copy of a multiply-defined COMDAT.

    Some template instantiations are emitted by several objects in one link.
    The linker keeps whichever comes first and discards the rest, so the
    copies are interchangeable *to the linker* and the choice is pure link
    order.  This installs a copy the linker itself could have chosen -- it
    selects among genuine compiler outputs and invents nothing.

    The donor is a DIFFERENT translation unit, so the whole-object
    equivalences every other class relies on (section count, function
    multiset, section seat) do not apply and are deliberately not required.
    What replaces them is C2 -- the installed body must be byte-identical to
    retail -- plus an exact structural match of the COMDAT and its closure.
    Every assumption below is a hard require, so any deviation refuses rather
    than composing something unproven.
    """
    seed = CoffObject(seed_bytes)
    donor = CoffObject(donor_bytes)
    mangled = function["mangled"]
    sp = seed.function_section(mangled)
    dp = donor.function_section(mangled)

    # C1: the seed defines this COMDAT too -- this is an override of a copy we
    # already emit, never an insertion of a function the seed lacks.
    require(
        section_definitions(seed)[sp["number"]]["selection"]
        == section_definitions(donor)[dp["number"]]["selection"],
        "COMDAT selection differs between the two copies",
    )
    require(
        all(sp[key] == dp[key] for key in
            ("name", "raw_size", "relocation_count", "line_count",
             "characteristics")),
        "the two COMDAT copies differ in shape",
    )
    require(sp["raw_size"] == function["expected_seed_length"]
            and dp["raw_size"] == function["expected_donor_length"],
            "target body lengths changed")

    # C2 -- THE LOAD-BEARING OBLIGATION.  Only retail's own bytes may be
    # installed, so the body is compared before anything is written.
    donor_code = coff_body(donor, dp)
    require(sha256_bytes(donor_code) == function["expected_body_sha256"],
            "donor body differs from its pinned compiler output")
    pinned_length = function["retail_oracle"]["length"]
    require(len(retail_body) == pinned_length
            and len(donor_code) == len(retail_body),
            "retail oracle length differs from the composed body")
    masked_donor = bytearray(donor_code)
    masked_retail = bytearray(retail_body)
    for record in detailed_relocations(donor, dp):
        start, width = record["offset"], record["width"]
        masked_donor[start:start + width] = b"\0" * width
        masked_retail[start:start + width] = b"\0" * width
    differing = sum(1 for a, b in zip(masked_donor, masked_retail) if a != b)
    require(differing == 0,
            f"composed body is not retail-exact: {differing} byte(s) differ "
            f"from the retail oracle under the relocation mask")

    # C3: the relocations must be the SAME work against the SAME names, so
    # the seed's own table already describes the donor's body.  Anything else
    # would need a remap this class does not perform.
    spr = detailed_relocations(seed, sp)
    dpr = detailed_relocations(donor, dp)
    require(len(spr) == len(dpr), "relocation counts differ")
    for index, (left, right) in enumerate(zip(spr, dpr)):
        require(
            (left["offset"], left["type"], left["addend"])
            == (right["offset"], right["type"], right["addend"]),
            f"relocation {index}: offset/type/addend differs",
        )
        require(local_symbol_kind(right["target"]) is None,
                f"relocation {index}: compiler-local target "
                f"{right['target']!r} cannot cross objects")
        require(left["target"] == right["target"],
                f"relocation {index}: target name differs "
                f"({left['target']!r} vs {right['target']!r})")

    # C4: the COFF line table must be identical apart from its leading symbol
    # sentinel, which names the enclosing object's function symbol.
    seed_lines = _coff_table_bytes(seed, sp, "lines")
    donor_lines = _coff_table_bytes(donor, dp, "lines")
    require(len(seed_lines) == len(donor_lines)
            and seed_lines[4:] == donor_lines[4:],
            "COFF line rows differ between the two copies")

    # C5: the debug closure must match in kind, and its records must agree
    # apart from the procedure range, which describes the body.
    closure = _comdat_child_closure(seed, sp)
    require(closure == _comdat_child_closure(donor, dp)
            and closure in ((2, (".debug$S", ".xdata$x")),
                            (2, (".debug$F", ".debug$S"))),
            "target closure is not an EH or FPO debug pair")
    fpo = closure == (2, (".debug$F", ".debug$S"))
    child = ".debug$F" if fpo else ".xdata$x"
    sx = _comdat_child(seed, sp, child)
    dx = _comdat_child(donor, dp, child)
    require(coff_body(seed, sx) == coff_body(donor, dx),
            f"{child} bytes differ between the two copies")
    sd = _comdat_child(seed, sp, ".debug$S")
    dd = _comdat_child(donor, dp, ".debug$S")
    seed_debug = coff_body(seed, sd)
    donor_debug = coff_body(donor, dd)
    require(len(seed_debug) >= 28 and seed_debug[2:4] == b"\x05\x02"
            and donor_debug[2:4] == b"\x05\x02",
            "debug$S is not an S_*PROC32 record")
    require(seed_debug[16:28] == donor_debug[16:28],
            "debug$S procedure range differs between the two copies")

    # Everything is proven identical except the code itself, so the splice is
    # exactly one raw-byte replacement; no table is rewritten.
    old_end = sp["raw_offset"] + sp["raw_size"]
    output = apply_replacements(
        seed_bytes, [(sp["raw_offset"], old_end, donor_code)])
    checked = CoffObject(output)
    cp = checked.function_section(mangled)
    require(coff_body(checked, cp) == donor_code,
            "composed body is not the donor body")
    require(_coff_table_bytes(checked, cp, "relocations")
            == _coff_table_bytes(seed, sp, "relocations"),
            "composed relocation table changed")
    require(len(output) == len(seed_bytes),
            "composed object size changed")
    return output, {
        "splice_class": "comdat_selection_override",
        "mangled": mangled,
        "seed_section": sp["number"],
        "donor_section": dp["number"],
        "body_length": len(donor_code),
        "relocations": len(dpr),
        "retail_exact": True,
    }


# ---------------------------------------------------------------------------
# Composition RE-PINNING
# ---------------------------------------------------------------------------
#
# A deliberate source recovery routinely moves COMDATs the manifest already
# composes, and every one of those units then refuses -- "target COMDAT body
# length changed", "donor body differs from its pinned compiler output",
# "seed/donor body delta changed".  Those messages are the framework working
# correctly: a pin is a claim about what the compiler produced, and the
# compiler now produces something else.  But they are also, in practice, the
# standing blocker on source recovery, because re-deriving them by hand is
# what makes a two-line edit cost a day.
#
# This is the composition analogue of `repin_overlay.py`, and it rests on
# exactly the same argument.  Every pin it refreshes is a MEASUREMENT of our
# own compiler's output -- a length, a digest, a byte-delta, a rename set --
# and none of them encodes a design decision.  The decisions live in
# `splice_class`, `donor`, `mangled`, the certificate free parameters
# (regions, mappings, window orders) and the retail oracle, and this function
# refuses to touch any of them.
#
# What makes re-pinning SAFE rather than a weakening is that nothing else
# changes: after the pins are refreshed the entry goes through the UNCHANGED
# composer, so every proof that class carries still runs and a refusal is
# still a refusal; and above that, the row gate independently requires the
# composed image to reproduce the accepted raw-1.0 set with zero losses.  A
# re-pin that silently broke a row would be caught there, by name.
#
# It handles a CLOSED set of splice classes -- the equal-body family and the
# same-slot resize, 187 of the manifest's 220 entries -- and REFUSES for any
# other.  A certificate class is deliberately excluded: when its seed moves,
# its free parameters may genuinely need re-deriving, and that is a decision,
# not a measurement.


REPINNABLE_SPLICE_CLASSES = frozenset({
    "equal_body_strict",
    "equal_body_eh_structural_local",
    "equal_body_eh_reloc_layout",
    "same_slot_resize",
})


# The pins each class states about the objects, and nothing else.  A key the
# entry does not already carry is never added: re-pinning refreshes a
# declaration, it never widens one.
REPINNABLE_PIN_KEYS = {
    "equal_body_strict": frozenset({
        "expected_body_length", "expected_body_sha256",
        "expected_changed_offsets",
    }),
    "equal_body_eh_structural_local": frozenset({
        "expected_body_length", "expected_body_sha256",
        "expected_changed_offsets", "expected_code_renames",
        "expected_xdata_rename_offsets", "expected_donor_section_number",
    }),
    "equal_body_eh_reloc_layout": frozenset({
        "expected_body_length", "expected_body_sha256",
        "expected_changed_offsets", "expected_relocation_moves",
        "expected_xdata_rename_offsets",
    }),
    "same_slot_resize": frozenset({
        "expected_seed_length", "expected_donor_length",
        "expected_linked_span", "expected_body_sha256",
        "expected_seed_line_count", "expected_donor_line_count",
    }),
}


def measure_composition_pins(
    seed_bytes: bytes, donor_bytes: bytes, function: dict, context: str,
) -> dict:
    """Measure, from the two objects, every pin this entry states about them.

    Returns only keys the entry ALREADY carries.  Raises for a splice class
    outside the closed repinnable set.
    """
    splice_class = function.get("splice_class")
    require(splice_class in REPINNABLE_SPLICE_CLASSES,
            f"{context}: {splice_class} is outside the repinnable classes; "
            "its free parameters are decisions, not measurements")
    seed = CoffObject(seed_bytes)
    donor = CoffObject(donor_bytes)
    mangled = function["mangled"]
    seed_primary = seed.function_section(mangled)
    donor_primary = donor.function_section(mangled)
    seed_body = bytes(coff_body(seed, seed_primary))
    donor_body = bytes(coff_body(donor, donor_primary))
    measured = {
        "expected_body_sha256": sha256_bytes(donor_body),
        "expected_seed_length": seed_primary["raw_size"],
        "expected_donor_length": donor_primary["raw_size"],
        "expected_seed_line_count": seed_primary["line_count"],
        "expected_donor_line_count": donor_primary["line_count"],
        "expected_linked_span": (
            ((donor_primary["raw_size"] + 15) // 16) * 16),
        "expected_donor_section_number": donor_primary["number"],
    }
    if splice_class != "same_slot_resize":
        require(seed_primary["raw_size"] == donor_primary["raw_size"],
                f"{context}: an equal-body entry's seed and donor bodies are "
                "no longer the same length; the composition is not a re-pin "
                "away from valid")
        measured["expected_body_length"] = seed_primary["raw_size"]
        measured["expected_changed_offsets"] = [
            index for index, pair in enumerate(zip(seed_body, donor_body))
            if pair[0] != pair[1]
        ]
    if splice_class in ("equal_body_eh_structural_local",
                        "equal_body_eh_reloc_layout"):
        closure = _comdat_child_closure(seed, seed_primary)
        seat_map = None
        if "expected_donor_section_number" in function:
            seat_map = {donor_primary["number"]: seed_primary["number"]}
            for child_name in (".debug$S", ".xdata$x"):
                seat_map[_comdat_child(
                    donor, donor_primary, child_name)["number"]] = (
                    _comdat_child(seed, seed_primary, child_name)["number"])
        if closure in ((2, (".debug$F", ".debug$S")), (1, (".debug$S",))):
            measured["expected_xdata_rename_offsets"] = []
        else:
            measured["expected_xdata_rename_offsets"] = [
                offset for offset, _ in _normalized_relocation_renames(
                    seed, _comdat_child(seed, seed_primary, ".xdata$x"),
                    donor, _comdat_child(donor, donor_primary, ".xdata$x"),
                    "xdata", seat_map=seat_map)
            ]
        if splice_class == "equal_body_eh_structural_local":
            measured["expected_code_renames"] = [
                [offset, kind] for offset, kind
                in _normalized_relocation_renames(
                    seed, seed_primary, donor, donor_primary, "code",
                    seat_map=seat_map)
            ]
        else:
            left = detailed_relocations(seed, seed_primary)
            right = detailed_relocations(donor, donor_primary)
            require(len(left) == len(right),
                    f"{context}: relocation counts differ, so the reloc-layout "
                    "move set is not a re-pin away from valid")
            measured["expected_relocation_moves"] = [
                [a["offset"], b["offset"]] for a, b in zip(left, right)
                if a["offset"] != b["offset"]
            ]
    return {key: value for key, value in measured.items()
            if key in function and key in REPINNABLE_PIN_KEYS[splice_class]}


def repin_composition_function(
    seed_bytes: bytes, donor_bytes: bytes, function: dict, context: str,
) -> tuple[dict, list[str]]:
    """Refresh one composition entry's measured pins.

    Returns the refreshed entry and the names of the pins that moved.  The
    caller is expected to run the refreshed entry through the ordinary
    composer: this function proves nothing on its own, it only restates what
    the objects say, and every obligation the class carries still has to hold
    afterwards.
    """
    measured = measure_composition_pins(
        seed_bytes, donor_bytes, function, context)
    moved = sorted(key for key, value in measured.items()
                   if function[key] != value)
    return {**function, **measured}, moved


def compose_equal_body_comdat(
    seed_bytes: bytes,
    donor_bytes: bytes,
    function: dict,
) -> tuple[bytes, dict]:
    """Copy one equal-size compiler-produced COMDAT code body from a donor
    object into the seed object, retaining every seed relocation, xdata,
    debug, and symbol byte.

    Two proved splice classes:
    - equal_body_strict: (.debug$F, .debug$S) closure, literal-equal
      relocation tuples.
    - equal_body_eh_structural_local: (.debug$S, .xdata$x) closure with
      byte-identical xdata and paired object-local $L/$T relocation renames
      resolving to structurally identical targets.
    """
    require("target_source_refactor" not in function,
            "equal-body source permutations are unsupported")
    seed = CoffObject(seed_bytes)
    donor = CoffObject(donor_bytes)
    mangled = function["mangled"]
    splice_class = function["splice_class"]
    seed_primary = seed.function_section(mangled)
    donor_primary = donor.function_section(mangled)

    require(
        seed_primary["raw_size"] == donor_primary["raw_size"]
        == function["expected_body_length"],
        "target COMDAT body length changed",
    )
    for field in ("name", "characteristics"):
        require(seed_primary[field] == donor_primary[field],
                f"target section {field} differs")
    seed_definitions = section_definitions(seed)
    donor_definitions = section_definitions(donor)
    seed_definition = seed_definitions.get(seed_primary["number"])
    donor_definition = donor_definitions.get(donor_primary["number"])
    require(seed_definition is not None and donor_definition is not None,
            "target COMDAT definition record is missing")
    require(
        all(
            seed_definition[field] == donor_definition[field]
            for field in ("selection", "associated", "length", "relocations")
        ),
        "target COMDAT definition record differs",
    )

    donor_body = coff_body(donor, donor_primary)
    require(sha256_bytes(donor_body) == function["expected_body_sha256"],
            "donor body differs from its pinned compiler output")
    seed_body = coff_body(seed, seed_primary)
    changed = [
        index for index, pair in enumerate(zip(seed_body, donor_body))
        if pair[0] != pair[1]
    ]
    require(changed == function["expected_changed_offsets"],
            "seed/donor body delta changed")

    closure = _comdat_child_closure(seed, seed_primary)
    require(closure == _comdat_child_closure(donor, donor_primary),
            "target COMDAT child closure differs")

    relocation_moves = []
    if splice_class == "equal_body_eh_reloc_layout":
        # The donor reschedules instructions, moving relocated operands.
        # Pair the tables by ordinal, require identical types and
        # structurally identical targets, and record the offset moves; the
        # seed's relocation records then take the donor's operand offsets.
        left = detailed_relocations(seed, seed_primary)
        right = detailed_relocations(donor, donor_primary)
        require(len(left) == len(right),
                "reloc-layout splice: relocation counts differ")
        for a, b in zip(left, right):
            require(a["type"] == b["type"] and a["addend"] == b["addend"],
                    "reloc-layout splice: relocation type/addend differs")
            if a["target"] != b["target"]:
                kind = local_symbol_kind(a["target"])
                require(kind is not None
                        and kind == local_symbol_kind(b["target"])
                        and all(a["target_" + field] == b["target_" + field]
                                for field in ("section", "value", "type",
                                              "storage")),
                        "reloc-layout splice: non-local relocation rename")
            if a["offset"] != b["offset"]:
                relocation_moves.append([a["offset"], b["offset"]])
        require(relocation_moves == function["expected_relocation_moves"],
                "reloc-layout splice: relocation move set changed")

    if splice_class == "equal_body_strict":
        require(closure == (2, (".debug$F", ".debug$S")),
                "strict splice requires the FPO debug closure")
        renames = _normalized_relocation_renames(
            seed, seed_primary, donor, donor_primary, "code"
        )
        require(renames == [], "strict splice forbids relocation renames")
        detail = {"code_renames": []}
    else:
        require(splice_class in ("equal_body_eh_structural_local",
                                 "equal_body_eh_reloc_layout"),
                "unsupported equal-body splice class")
        fpo_closure = closure in ((2, (".debug$F", ".debug$S")),
                                  (1, (".debug$S",)))
        require(
            closure == (2, (".debug$S", ".xdata$x")) or fpo_closure,
            "splice closure kind is unsupported for this class",
        )
        # A carrier-state donor owns its own global tail layout; the target
        # closure seats, the xdata byte-equality, and the per-relocation
        # target checks carry the equivalence proof.  The primary and its
        # closure children must keep identical seats in both objects —
        # except for a declared cross-lane donor (another real compile lane
        # of the same TU text), whose seat is pinned explicitly instead.
        if "expected_donor_section_number" in function:
            require(
                donor_primary["number"]
                == function["expected_donor_section_number"],
                "declared cross-lane donor seat changed",
            )
            seat_map = {donor_primary["number"]: seed_primary["number"]}
            for child_name in (".debug$S", ".xdata$x"):
                seat_map[
                    _comdat_child(donor, donor_primary, child_name)["number"]
                ] = _comdat_child(seed, seed_primary, child_name)["number"]
        else:
            require(
                seed_primary["number"] == donor_primary["number"],
                "target closure seats differ",
            )
            seat_map = None
        if fpo_closure:
            require(function["expected_xdata_rename_offsets"] == [],
                    "FPO-closure splice cannot declare xdata renames")
            xdata_renames = []
        else:
            seed_xdata = _comdat_child(seed, seed_primary, ".xdata$x")
            donor_xdata = _comdat_child(donor, donor_primary, ".xdata$x")
            require(
                coff_body(seed, seed_xdata) == coff_body(donor, donor_xdata),
                "EH xdata raw bytes differ")
            xdata_renames = _normalized_relocation_renames(
                seed, seed_xdata, donor, donor_xdata, "xdata",
                seat_map=seat_map,
            )
            require(
                [offset for offset, _ in xdata_renames]
                == function["expected_xdata_rename_offsets"],
                "xdata local-relocation rename set changed",
            )
        if splice_class == "equal_body_eh_structural_local":
            code_renames = _normalized_relocation_renames(
                seed, seed_primary, donor, donor_primary, "code",
                seat_map=seat_map,
            )
            require(
                [[offset, kind] for offset, kind in code_renames]
                == function["expected_code_renames"],
                "code local-relocation rename set changed",
            )
            relocation_mask = {
                record["offset"] + byte
                for record in detailed_relocations(donor, donor_primary)
                for byte in range(record["width"])
            }
            require(all(offset not in relocation_mask for offset in changed),
                    "donor changes a relocated operand")
            detail = {
                "code_renames": code_renames,
                "xdata_rename_offsets": [o for o, _ in xdata_renames],
            }
        else:
            detail = {
                "relocation_moves": relocation_moves,
                "xdata_rename_offsets": [o for o, _ in xdata_renames],
            }

    composed = bytearray(seed_bytes)
    start = seed_primary["raw_offset"]
    composed[start:start + seed_primary["raw_size"]] = donor_body
    if relocation_moves:
        donor_offsets = [
            record["offset"]
            for record in detailed_relocations(donor, donor_primary)
        ]
        for ordinal, offset in enumerate(donor_offsets):
            record_at = seed_primary["relocation_offset"] + ordinal * 10
            composed[record_at:record_at + 4] = offset.to_bytes(4, "little")
    composed = bytes(composed)

    checked = CoffObject(composed)
    checked_primary = checked.function_section(mangled)
    require(coff_body(checked, checked_primary) == donor_body,
            "composed body differs from the donor")
    checked_relocations = detailed_relocations(checked, checked_primary)
    seed_relocations = detailed_relocations(seed, seed_primary)
    if relocation_moves:
        donor_relocations = detailed_relocations(donor, donor_primary)
        require(
            [(r["offset"], r["type"], r["addend"], r["symbol_index"])
             for r in checked_relocations]
            == [(d["offset"], d["type"], d["addend"], s["symbol_index"])
                for d, s in zip(donor_relocations, seed_relocations)],
            "composed relocations differ from the donor layout",
        )
    else:
        require(checked_relocations == seed_relocations,
                "composed relocations differ from the seed")
    changed_offsets = [
        index for index, pair in enumerate(zip(seed_bytes, composed))
        if pair[0] != pair[1]
    ]
    allowed = set(range(start, start + seed_primary["raw_size"]))
    if relocation_moves:
        allowed |= {
            seed_primary["relocation_offset"] + ordinal * 10 + byte
            for ordinal in range(seed_primary["relocation_count"])
            for byte in range(4)
        }
    require(set(changed_offsets) <= allowed,
            "composition changed bytes outside the selected body")
    return composed, {
        "mangled": mangled,
        "splice_class": splice_class,
        "section_number": seed_primary["number"],
        "body_length": seed_primary["raw_size"],
        "body_changed_offsets": changed,
        **detail,
    }


def compose_retail_exact_source_equal_body(
    seed_bytes: bytes,
    donor_bytes: bytes,
    function: dict,
    retail_body: bytes,
    seed_source: bytes,
    donor_source: bytes,
) -> tuple[bytes, dict]:
    """Install one complete equal-size body from a closed source refactor.

    This is deliberately a separate wrapper around the ordinary equal-body
    composer.  The ordinary entry point continues to reject source proofs;
    this class adds the source identity, complete target/closure pins,
    semantic-relocation equivalence, and retail oracle before delegating the
    one allowed mutation: replacing the target's raw body while retaining all
    seed line, debug, unwind/FPO, relocation, and symbol bytes.
    """
    require(
        function.get("splice_class")
        == RETAIL_EXACT_SOURCE_EQUAL_BODY_CLASS
        and "target_source_refactor" in function,
        "retail-exact source equal-body contract is missing",
    )
    require(isinstance(retail_body, (bytes, bytearray)) and retail_body,
            "retail oracle body is missing")
    source_detail = require_target_source_refactor_identity(
        seed_source, donor_source, function["target_source_refactor"],
        "retail-exact source equal-body proof",
    )

    seed = CoffObject(seed_bytes)
    donor = CoffObject(donor_bytes)
    mangled = function["mangled"]
    sp = seed.function_section(mangled)
    dp = donor.function_section(mangled)
    require(
        sp["number"] == dp["number"]
        == function["expected_section_number"],
        "source equal-body target section seat changed",
    )
    require(
        len(seed.sections) == len(donor.sections)
        == function["expected_section_count"],
        "source equal-body global section count changed",
    )
    seed_functions = function_multiset(seed)
    donor_functions = function_multiset(donor)
    require(
        seed_functions == donor_functions
        and sum(seed_functions.values()) == function["expected_function_count"],
        "source equal-body donor function set differs",
    )
    seed_comdats = comdat_primary_identity_multiset(seed)
    donor_comdats = comdat_primary_identity_multiset(donor)
    require(
        seed_comdats == donor_comdats
        and sum(seed_comdats.values()) == function["expected_comdat_count"],
        "source equal-body donor COMDAT identity set differs",
    )
    require(
        sp["raw_size"] == dp["raw_size"]
        == function["expected_body_length"]
        and sp["relocation_count"] == dp["relocation_count"]
        == function["expected_relocation_count"]
        and sp["line_count"] == function["expected_seed_line_count"]
        and dp["line_count"] == function["expected_donor_line_count"]
        and sp["name"] == dp["name"]
        and sp["characteristics"] == dp["characteristics"]
        == function["expected_characteristics"],
        "source equal-body target header/count pins changed",
    )
    seed_defs = section_definitions(seed)
    donor_defs = section_definitions(donor)
    require(
        seed_defs[sp["number"]]["selection"]
        == donor_defs[dp["number"]]["selection"]
        == function["expected_selection"],
        "source equal-body COMDAT selection changed",
    )

    expected_closure = tuple(function["expected_closure"])
    closure = _comdat_child_closure(seed, sp)
    source_fpo = "source_fpo_identity" in function
    required_closure = (
        (2, (".debug$F", ".debug$S")) if source_fpo else
        (2, (".debug$S", ".xdata$x"))
    )
    require(
        closure == _comdat_child_closure(donor, dp)
        == (len(expected_closure), expected_closure)
        == required_closure,
        "source equal-body target closure changed",
    )
    if source_fpo:
        closure_pairs = require_source_fpo_mosaic_identity(
            seed, sp, donor, dp, function,
            function["source_fpo_identity"],
            "source equal-body FPO identity",
        )
    else:
        closure_pairs = [
            (_comdat_child(seed, sp, child_name),
             _comdat_child(donor, dp, child_name))
            for child_name in expected_closure
        ]

    closure_renames = {}
    for child_name, (left, right) in zip(
            expected_closure, closure_pairs, strict=True):
        if not source_fpo:
            require(
                left["number"] == right["number"]
                and all(left[field] == right[field]
                        for field in (
                            "name", "raw_size", "relocation_count",
                            "line_count", "characteristics",
                        )),
                f"source equal-body {child_name} closure geometry changed",
            )
        closure_renames[child_name] = require_same_semantic_relocations(
            seed, left, donor, right,
            f"source equal-body {child_name}",
        )
    if source_fpo:
        require(
            function["expected_xdata_rename_offsets"] == [],
            "source equal-body FPO closure cannot declare xdata renames",
        )
    else:
        require(
            [offset for offset, _ in closure_renames[".xdata$x"]]
            == function["expected_xdata_rename_offsets"],
            "source equal-body xdata rename set changed",
        )
    require(
        [[offset, kind]
         for offset, kind in closure_renames[".debug$S"]]
        == function["expected_debug_s_renames"],
        "source equal-body debug$S rename set changed",
    )
    if not source_fpo:
        seed_xdata = _comdat_child(seed, sp, ".xdata$x")
        donor_xdata = _comdat_child(donor, dp, ".xdata$x")
        require(coff_body(seed, seed_xdata) == coff_body(donor, donor_xdata),
                "source equal-body runtime xdata bytes changed")
        seed_debug = coff_body(seed, _comdat_child(seed, sp, ".debug$S"))
        donor_debug = coff_body(donor, _comdat_child(donor, dp, ".debug$S"))
        require(
            len(seed_debug) >= 28 and len(seed_debug) == len(donor_debug)
            and seed_debug[:28] == donor_debug[:28]
            and seed_debug[2:4] == b"\x05\x02",
            "source equal-body CodeView procedure identity changed",
        )
    require(
        instruction_mosaic_metadata_sha256(seed, sp)
        == function["expected_seed_metadata_sha256"]
        and instruction_mosaic_metadata_sha256(donor, dp)
        == function["expected_donor_metadata_sha256"],
        "source equal-body metadata differs from its pin",
    )

    seed_body = coff_body(seed, sp)
    donor_body = coff_body(donor, dp)
    require(
        sha256_bytes(seed_body) == function["expected_seed_body_sha256"]
        and sha256_bytes(donor_body)
        == function["expected_donor_body_sha256"]
        == function["expected_body_sha256"],
        "source equal-body target body differs from its pin",
    )
    code_renames = require_instruction_mosaic_semantic_relocations(
        seed, sp, donor, dp, "source equal-body code",
    )
    require(
        [[offset, kind] for offset, kind in code_renames]
        == function["expected_code_renames"],
        "source equal-body code rename set changed",
    )
    seed_rows = detailed_relocations(seed, sp)
    require(len(seed_rows) == function["expected_relocation_count"],
            "source equal-body relocation count changed")
    pinned_length = function["retail_oracle"]["length"]
    require(
        len(retail_body) == pinned_length == len(donor_body),
        "source equal-body retail length changed",
    )
    semantic_detail = require_retail_relocation_oracle(
        seed_rows, bytes(retail_body),
        int(function["retail_oracle"]["address"], 16),
        function["retail_relocations"],
        "source equal-body retail relocation oracle",
    )
    masked_donor = bytearray(donor_body)
    masked_retail = bytearray(retail_body)
    for row in seed_rows:
        start, width = row["offset"], row["width"]
        masked_donor[start:start + width] = b"\0" * width
        masked_retail[start:start + width] = b"\0" * width
    differing = sum(left != right
                    for left, right in zip(masked_donor, masked_retail))
    require(differing == 0,
            f"source equal-body output is not retail-exact: {differing} "
            "byte(s) differ under the relocation mask")

    # Delegate only the body replacement to the existing closed primitive.
    # The proof is intentionally omitted from this private effective record,
    # so the public ordinary equal-body entry point retains its source-proof
    # rejection contract.
    effective = {
        "mangled": mangled,
        "splice_class": "equal_body_eh_structural_local",
        "expected_body_length": function["expected_body_length"],
        "expected_body_sha256": function["expected_body_sha256"],
        "expected_changed_offsets": function["expected_changed_offsets"],
        "expected_code_renames": function["expected_code_renames"],
        "expected_xdata_rename_offsets":
            function["expected_xdata_rename_offsets"],
    }
    composed, detail = compose_equal_body_comdat(
        seed_bytes, donor_bytes, effective)
    checked = CoffObject(composed)
    cp = checked.function_section(mangled)
    require(
        _coff_table_bytes(checked, cp, "lines")
        == _coff_table_bytes(seed, sp, "lines")
        and detailed_relocations(checked, cp) == seed_rows
        and instruction_mosaic_metadata_sha256(checked, cp)
        == function["expected_seed_metadata_sha256"],
        "source equal-body output changed seed-authoritative metadata",
    )
    return composed, {
        **detail,
        "splice_class": RETAIL_EXACT_SOURCE_EQUAL_BODY_CLASS,
        "closure": list(expected_closure),
        "closure_relocation_renames": closure_renames,
        "source_fpo_identity": source_fpo,
        "retail_exact": True,
        **semantic_detail,
        **source_detail,
    }


def compose_equal_linked_span_fpo(
    seed_bytes: bytes,
    donor_bytes: bytes,
    function: dict,
    shape_identifiers: set[str],
) -> tuple[bytes, dict]:
    """Compose one compiler-produced FPO COMDAT and prove its full closure."""
    seed = CoffObject(seed_bytes)
    donor = CoffObject(donor_bytes)
    mangled = function["mangled"]
    seed_primary = seed.function_section(mangled)
    donor_primary = donor.function_section(mangled)
    require(
        seed_primary["number"] == donor_primary["number"]
        == function["expected_section_number"],
        "target COMDAT section seat changed",
    )
    require(seed_primary["raw_size"] == function["expected_seed_length"],
            "seed target length changed")
    require(donor_primary["raw_size"] == function["expected_donor_length"],
            "donor target length changed")
    require(
        ((seed_primary["raw_size"] + 15) // 16) * 16
        == function["expected_linked_span"]
        == ((donor_primary["raw_size"] + 15) // 16) * 16,
        "target 16-byte linked contribution span changed",
    )
    require(
        seed_primary["name"] == donor_primary["name"]
        and seed_primary["characteristics"] == donor_primary["characteristics"]
        == function["expected_characteristics"],
        "target section kind or characteristics changed",
    )
    require((seed_primary["characteristics"] & 0x00F00000) == 0x00500000,
            "target COMDAT does not declare 16-byte section alignment")
    require(
        seed_primary["relocation_count"] == donor_primary["relocation_count"]
        == function["expected_relocation_count"],
        "target relocation count changed",
    )
    require(seed_primary["line_count"] == function["expected_seed_line_count"]
            and donor_primary["line_count"] == function["expected_donor_line_count"],
            "target COFF line count changed")

    seed_definitions = section_definitions(seed)
    donor_definitions = section_definitions(donor)
    require(seed_primary["number"] in seed_definitions
            and donor_primary["number"] in donor_definitions,
            "target Section Definition auxiliary record is absent")
    require(
        seed_definitions[seed_primary["number"]]["selection"]
        == donor_definitions[donor_primary["number"]]["selection"]
        == function["expected_selection"],
        "target COMDAT selection changed",
    )
    seed_associated = associated_sections(seed, seed_definitions, seed_primary["number"])
    donor_associated = associated_sections(donor, donor_definitions, donor_primary["number"])
    require(seed_associated == donor_associated,
            "target associative-section seats changed")
    require(tuple(sorted(name for _, name in seed_associated)) == (".debug$F", ".debug$S"),
            "target closure is not exactly .debug$S + .debug$F; xdata is unsupported")
    provenance = verify_non_emitting_donor(seed, donor, shape_identifiers)
    seed_closure = {
        name: seed.sections[number - 1] for number, name in seed_associated
    }
    donor_closure = {
        name: donor.sections[number - 1] for number, name in donor_associated
    }
    for name in (".debug$S", ".debug$F"):
        left = seed_closure[name]
        right = donor_closure[name]
        require(
            left["number"] == right["number"]
            and left["raw_size"] == right["raw_size"]
            and left["relocation_count"] == right["relocation_count"]
            and left["line_count"] == right["line_count"] == 0
            and left["characteristics"] == right["characteristics"],
            f"{name} closure geometry changed",
        )
        left_rows = detailed_relocations(seed, left)
        right_rows = detailed_relocations(donor, right)
        require(
            [
                (
                    row["offset"], row["type"], row["addend"], row["target"],
                    row["target_section"], row["target_value"],
                    row["target_type"], row["target_storage"],
                )
                for row in left_rows
            ]
            == [
                (
                    row["offset"], row["type"], row["addend"], row["target"],
                    row["target_section"], row["target_value"],
                    row["target_type"], row["target_storage"],
                )
                for row in right_rows
            ],
            f"{name} relocation target/type/addend closure changed",
        )

    seed_relocations = detailed_relocations(seed, seed_primary)
    donor_relocations = detailed_relocations(donor, donor_primary)
    compatibility = relocation_compatibility(
        seed_relocations,
        donor_relocations,
        seed_primary["number"],
        donor_primary["number"],
    )
    require(compatibility is not None,
            "primary relocation target/type/addend semantics changed")
    require(len(compatibility["local_updates"])
            == function["expected_local_symbol_updates"],
            "primary local-symbol update count changed")
    donor_body = coff_body(donor, donor_primary)
    require(sha256_bytes(donor_body) == function["compiler_output_body_sha256"],
            "compiler donor body hash differs from the retail-approved oracle pin")

    seed_function_index, seed_function = function_symbol(
        seed, mangled, seed_primary["number"]
    )
    donor_function_index, donor_function = function_symbol(
        donor, mangled, donor_primary["number"]
    )
    donor_lines = normalized_donor_lines(
        seed, donor, seed_primary, donor_primary,
        seed_function_index, donor_function_index,
    )
    replacements = [
        (
            seed_primary["raw_offset"],
            seed_primary["raw_offset"] + seed_primary["raw_size"],
            donor_body,
        ),
        (
            seed_primary["line_offset"],
            seed_primary["line_offset"] + seed_primary["line_count"] * 6,
            donor_lines,
        ),
    ]
    output = bytearray(apply_replacements(seed_bytes, replacements))
    total_delta = sum(len(replacement) - (end - start)
                      for start, end, replacement in replacements)
    new_symbol_offset = shifted_pointer(seed.symbol_offset, replacements)
    struct.pack_into("<I", output, 8, new_symbol_offset)

    expected_headers = bytearray(seed.data[20 : 20 + seed.section_count * 40])
    for section in seed.sections:
        relative_header = (section["number"] - 1) * 40
        if section["number"] == seed_primary["number"]:
            struct.pack_into("<I", expected_headers, relative_header + 16,
                             donor_primary["raw_size"])
            struct.pack_into("<H", expected_headers, relative_header + 34,
                             donor_primary["line_count"])
        for field, relative in (
            ("raw_offset", 20), ("relocation_offset", 24), ("line_offset", 28)
        ):
            struct.pack_into(
                "<I", expected_headers, relative_header + relative,
                shifted_pointer(section[field], replacements),
            )
    output[20 : 20 + len(expected_headers)] = expected_headers

    new_primary_relocation_offset = shifted_pointer(
        seed_primary["relocation_offset"], replacements
    )
    for ordinal, (seed_row, donor_row) in enumerate(
        zip(seed_relocations, donor_relocations)
    ):
        struct.pack_into(
            "<IIH", output, new_primary_relocation_offset + ordinal * 10,
            donor_row["offset"], seed_row["symbol_index"], donor_row["type"],
        )

    expected_symbols = bytearray(
        seed.data[seed.symbol_offset : seed.symbol_offset + seed.symbol_count * 18]
    )
    shifted_function_line_pointers = 0
    for symbol_index, symbol in seed.symbols.items():
        if symbol["type"] != 0x20 or symbol["aux_count"] < 1:
            continue
        auxiliary_offset = (symbol_index + 1) * 18
        line_pointer, = struct.unpack_from("<I", expected_symbols, auxiliary_offset + 8)
        mapped = shifted_pointer(line_pointer, replacements)
        if mapped != line_pointer:
            struct.pack_into("<I", expected_symbols, auxiliary_offset + 8, mapped)
            shifted_function_line_pointers += 1
    for symbol_index, donor_value in compatibility["local_updates"].items():
        struct.pack_into("<I", expected_symbols, symbol_index * 18 + 8, donor_value)

    donor_function_auxiliary = coff_auxiliary(
        donor, donor_function_index, donor_function
    )
    seed_function_auxiliary = coff_auxiliary(
        seed, seed_function_index, seed_function
    )
    require(
        seed_function["type"] == donor_function["type"]
        and seed_function["storage"] == donor_function["storage"]
        and seed_function["aux_count"] == donor_function["aux_count"] == 1
        and seed_function_auxiliary[:4] == donor_function_auxiliary[:4]
        and seed_function_auxiliary[12:] == donor_function_auxiliary[12:],
        "Function Definition tag/next-function auxiliary metadata changed",
    )
    seed_total_size, seed_line_pointer = struct.unpack_from(
        "<II", seed_function_auxiliary, 4
    )
    donor_total_size, donor_line_pointer = struct.unpack_from(
        "<II", donor_function_auxiliary, 4
    )
    require(seed_total_size == seed_primary["raw_size"]
            and seed_line_pointer == seed_primary["line_offset"],
            "seed Function Definition size/line pointer is stale")
    require(donor_total_size == donor_primary["raw_size"]
            and donor_line_pointer == donor_primary["line_offset"],
            "donor Function Definition size/line pointer is stale")
    struct.pack_into("<I", expected_symbols, (seed_function_index + 1) * 18 + 4,
                     donor_total_size)

    seed_begin_index, seed_begin = marker_symbol(seed, ".bf", seed_primary["number"])
    donor_begin_index, donor_begin = marker_symbol(donor, ".bf", donor_primary["number"])
    seed_begin_auxiliary = coff_auxiliary(seed, seed_begin_index, seed_begin)
    donor_begin_auxiliary = coff_auxiliary(donor, donor_begin_index, donor_begin)
    require(
        seed_begin["aux_count"] == donor_begin["aux_count"] == 1
        and seed_begin["value"] == donor_begin["value"]
        and seed_begin["type"] == donor_begin["type"]
        and seed_begin["storage"] == donor_begin["storage"]
        and seed_begin_auxiliary[:4] == donor_begin_auxiliary[:4]
        and seed_begin_auxiliary[6:] == donor_begin_auxiliary[6:],
        ".bf tag/next-function auxiliary metadata changed",
    )
    expected_symbols[(seed_begin_index + 1) * 18 + 4:
                     (seed_begin_index + 1) * 18 + 6] = donor_begin_auxiliary[4:6]

    seed_end_index, seed_end = marker_symbol(seed, ".ef", seed_primary["number"])
    donor_end_index, donor_end = marker_symbol(donor, ".ef", donor_primary["number"])
    require(seed_end["value"] == seed_primary["raw_size"],
            "seed .ef value is stale")
    require(donor_end["value"] == donor_primary["raw_size"],
            "donor .ef value is stale")
    seed_end_auxiliary = coff_auxiliary(seed, seed_end_index, seed_end)
    donor_end_auxiliary = coff_auxiliary(donor, donor_end_index, donor_end)
    require(
        seed_end["aux_count"] == donor_end["aux_count"] == 1
        and seed_end["type"] == donor_end["type"]
        and seed_end["storage"] == donor_end["storage"]
        and seed_end_auxiliary[:4] == donor_end_auxiliary[:4]
        and seed_end_auxiliary[6:] == donor_end_auxiliary[6:],
        ".ef tag/next-function auxiliary metadata changed",
    )
    struct.pack_into("<I", expected_symbols, seed_end_index * 18 + 8,
                     donor_end["value"])
    expected_symbols[(seed_end_index + 1) * 18 + 4:
                     (seed_end_index + 1) * 18 + 6] = donor_end_auxiliary[4:6]

    seed_section_index, seed_section_symbol = section_symbol(seed, seed_primary)
    donor_section_index, donor_section_symbol = section_symbol(donor, donor_primary)
    donor_section_auxiliary = coff_auxiliary(
        donor, donor_section_index, donor_section_symbol
    )
    seed_section_auxiliary = coff_auxiliary(
        seed, seed_section_index, seed_section_symbol
    )
    require(
        seed_section_symbol["aux_count"]
        == donor_section_symbol["aux_count"] == 1
        and seed_section_symbol["type"] == donor_section_symbol["type"]
        and seed_section_symbol["storage"] == donor_section_symbol["storage"]
        and seed_section_auxiliary[12:] == donor_section_auxiliary[12:]
        and int.from_bytes(seed_section_auxiliary[0:4], "little")
        == seed_primary["raw_size"]
        and int.from_bytes(seed_section_auxiliary[4:6], "little")
        == seed_primary["relocation_count"]
        and int.from_bytes(seed_section_auxiliary[6:8], "little")
        == seed_primary["line_count"]
        and int.from_bytes(donor_section_auxiliary[0:4], "little")
        == donor_primary["raw_size"]
        and int.from_bytes(donor_section_auxiliary[4:6], "little")
        == donor_primary["relocation_count"]
        and int.from_bytes(donor_section_auxiliary[6:8], "little")
        == donor_primary["line_count"]
        and donor_section_auxiliary[14] == function["expected_selection"],
        "donor Section Definition auxiliary record is stale",
    )
    expected_symbols[(seed_section_index + 1) * 18:
                     (seed_section_index + 2) * 18] = donor_section_auxiliary
    output[new_symbol_offset:new_symbol_offset + len(expected_symbols)] = expected_symbols

    seed_debug_s_raw = coff_body(seed, seed_closure[".debug$S"])
    donor_debug_s_raw = coff_body(donor, donor_closure[".debug$S"])
    require(len(seed_debug_s_raw) == len(donor_debug_s_raw) >= 28,
            "CodeView procedure record size changed or is truncated")
    require(seed_debug_s_raw[2:4] == donor_debug_s_raw[2:4] == b"\x05\x02",
            "associated CodeView record is not S_*PROC32")
    donor_cbproc, donor_dbgstart, donor_dbgend = struct.unpack_from(
        "<III", donor_debug_s_raw, 16
    )
    require(donor_cbproc == donor_primary["raw_size"]
            and 0 <= donor_dbgstart <= donor_dbgend < donor_cbproc,
            "donor CodeView procedure range is invalid")
    expected_debug_s = bytearray(seed_debug_s_raw)
    expected_debug_s[16:28] = donor_debug_s_raw[16:28]
    debug_s_offset = shifted_pointer(seed_closure[".debug$S"]["raw_offset"], replacements)
    output[debug_s_offset:debug_s_offset + len(expected_debug_s)] = expected_debug_s

    seed_debug_f_raw = coff_body(seed, seed_closure[".debug$F"])
    donor_debug_f_raw = coff_body(donor, donor_closure[".debug$F"])
    seed_fpo = parse_fpo_data(
        seed_debug_f_raw, expected_proc_size=seed_primary["raw_size"]
    )
    donor_fpo = parse_fpo_data(
        donor_debug_f_raw, expected_proc_size=donor_primary["raw_size"]
    )
    require(exact_json_equal(donor_fpo, function["expected_donor_fpo"]),
            "compiler donor FPO record differs from the manifest pin")
    require(donor_fpo["cbProcSize"] == donor_cbproc,
            "donor FPO and CodeView procedure sizes differ")
    debug_f_offset = shifted_pointer(seed_closure[".debug$F"]["raw_offset"], replacements)
    output[debug_f_offset:debug_f_offset + 16] = donor_debug_f_raw
    output_bytes = bytes(output)

    checked = CoffObject(output_bytes)
    checked_primary = checked.function_section(mangled)
    require(len(output_bytes) == len(seed_bytes) + total_delta,
            "composed COFF file length delta is wrong")
    require(function_multiset(checked) == function_multiset(seed),
            "composed COFF function multiset changed")
    require(coff_body(checked, checked_primary) == donor_body,
            "composed target body differs from compiler donor")
    require(coff_table(checked, checked_primary, "lines") == donor_lines,
            "composed COFF line table differs from normalized donor")
    checked_relocations = detailed_relocations(checked, checked_primary)
    require(
        [
            (row["offset"], row["symbol_index"], row["type"], row["addend"])
            for row in checked_relocations
        ]
        == [
            (donor_row["offset"], seed_row["symbol_index"], donor_row["type"], donor_row["addend"])
            for seed_row, donor_row in zip(seed_relocations, donor_relocations)
        ],
        "composed primary relocation table is incoherent",
    )
    checked_definitions = section_definitions(checked)
    checked_associated = associated_sections(
        checked, checked_definitions, checked_primary["number"]
    )
    require(checked_associated == seed_associated,
            "composed associative closure changed")
    expected_closure_raw = {
        seed_closure[".debug$S"]["number"]: bytes(expected_debug_s),
        seed_closure[".debug$F"]["number"]: donor_debug_f_raw,
    }
    for before, after in zip(seed.sections, checked.sections):
        require(before["number"] == after["number"]
                and before["name"] == after["name"]
                and before["characteristics"] == after["characteristics"],
                "composed section order/characteristics changed")
        number = before["number"]
        if number in expected_closure_raw:
            require(coff_body(checked, after) == expected_closure_raw[number],
                    f"composed debug closure raw bytes differ: section {number}")
            require(coff_table(seed, before, "relocations")
                    == coff_table(checked, after, "relocations"),
                    f"composed debug closure relocations changed: section {number}")
        elif number != seed_primary["number"]:
            require(coff_body(seed, before) == coff_body(checked, after),
                    f"non-target raw section changed: section {number}")
            require(coff_table(seed, before, "relocations")
                    == coff_table(checked, after, "relocations"),
                    f"non-target relocation table changed: section {number}")
        if number != seed_primary["number"]:
            require(coff_table(seed, before, "lines")
                    == coff_table(checked, after, "lines"),
                    f"non-target COFF line table changed: section {number}")

    require(
        checked.data[checked.symbol_offset:
                     checked.symbol_offset + checked.symbol_count * 18]
        == bytes(expected_symbols),
        "composed symbol/auxiliary table differs from the proven reconstruction",
    )
    checked_function_index, checked_function = function_symbol(
        checked, mangled, checked_primary["number"]
    )
    checked_function_auxiliary = coff_auxiliary(
        checked, checked_function_index, checked_function
    )
    require(struct.unpack_from("<I", checked_function_auxiliary, 4)[0]
            == donor_primary["raw_size"]
            and struct.unpack_from("<I", checked_function_auxiliary, 8)[0]
            == checked_primary["line_offset"],
            "composed Function Definition auxiliary record is stale")
    checked_begin_index, checked_begin = marker_symbol(
        checked, ".bf", checked_primary["number"]
    )
    require(coff_auxiliary(checked, checked_begin_index, checked_begin)[4:6]
            == donor_begin_auxiliary[4:6],
            "composed .bf line is stale")
    checked_end_index, checked_end = marker_symbol(
        checked, ".ef", checked_primary["number"]
    )
    require(checked_end["value"] == donor_primary["raw_size"]
            and coff_auxiliary(checked, checked_end_index, checked_end)
            == coff_auxiliary(donor, donor_end_index, donor_end),
            "composed .ef metadata differs from donor")
    checked_section_index, checked_section_symbol = section_symbol(checked, checked_primary)
    require(coff_auxiliary(checked, checked_section_index, checked_section_symbol)
            == donor_section_auxiliary,
            "composed Section Definition auxiliary record differs from donor")
    require(not any(identifier.encode("ascii") in output_bytes
                    for identifier in shape_identifiers),
            "declaration-shape identifiers leaked into the composed object")

    return output_bytes, {
        "mangled": mangled,
        "address": function["retail_oracle"]["address"],
        "retail_oracle": dict(function["retail_oracle"]),
        "retail_payload_bytes_read": 0,
        "section_number": checked_primary["number"],
        "seed_length": seed_primary["raw_size"],
        "donor_length": donor_primary["raw_size"],
        "linked_span": function["expected_linked_span"],
        "file_size_delta": total_delta,
        "relocation_count": len(checked_relocations),
        "relocation_offsets_moved": sum(
            left["offset"] != right["offset"]
            for left, right in zip(seed_relocations, donor_relocations)
        ),
        "local_symbols_updated": len(compatibility["local_updates"]),
        "function_line_pointers_shifted": shifted_function_line_pointers,
        "coff_line_policy": "whole_donor_normalized_function_index",
        "coff_line_rows": donor_primary["line_count"],
        "codeview_policy": "seed_types_names_locals_with_donor_cbProc_DbgStart_DbgEnd",
        "codeview_range": {
            "cbProc": donor_cbproc,
            "DbgStart": donor_dbgstart,
            "DbgEnd": donor_dbgend,
        },
        "fpo_policy": "whole_donor_debug_F_record",
        "seed_fpo": seed_fpo,
        "donor_fpo": donor_fpo,
        "target_body_sha256": sha256_bytes(donor_body),
        "input_sha256": sha256_bytes(seed_bytes),
        "donor_sha256": sha256_bytes(donor_bytes),
        "output_sha256": sha256_bytes(output_bytes),
        "provenance": provenance,
    }


def pe_resource_sections(data: bytes) -> tuple[int, int, int] | None:
    """Return (virtual_address, raw_offset, raw_size) of .rsrc, or None."""
    pe = int.from_bytes(data[0x3C:0x40], "little")
    section_count = int.from_bytes(data[pe + 6:pe + 8], "little")
    optional_size = int.from_bytes(data[pe + 20:pe + 22], "little")
    table = pe + 24 + optional_size
    for index in range(section_count):
        header = table + index * 40
        if data[header:header + 8].rstrip(b"\0") == b".rsrc":
            virtual = int.from_bytes(data[header + 12:header + 16], "little")
            raw_size = int.from_bytes(data[header + 16:header + 20], "little")
            raw_offset = int.from_bytes(data[header + 20:header + 24],
                                        "little")
            return (virtual, raw_offset, raw_size)
    return None


def pe_resource_directory_offsets(data: bytes) -> list[int]:
    """File offsets of every resource DIRECTORY record in the .rsrc tree."""
    section = pe_resource_sections(data)
    if section is None:
        return []
    _, raw_offset, _ = section
    offsets = []

    def walk(directory: int) -> None:
        offsets.append(raw_offset + directory)
        named = int.from_bytes(
            data[raw_offset + directory + 12:raw_offset + directory + 14],
            "little")
        idents = int.from_bytes(
            data[raw_offset + directory + 14:raw_offset + directory + 16],
            "little")
        for index in range(named + idents):
            entry = raw_offset + directory + 16 + index * 8
            value = int.from_bytes(data[entry + 4:entry + 8], "little")
            if value & 0x80000000:
                walk(value & 0x7FFFFFFF)

    walk(0)
    return offsets


def pe_resource_directory_times(data: bytes) -> set[int]:
    return {
        int.from_bytes(data[offset + 4:offset + 8], "little")
        for offset in pe_resource_directory_offsets(data)
    }


def restore_adjacent_thunk_pair_order(built: bytes, retail: bytes) -> bytes:
    """Swap one adjacent pair of 6-byte import thunks (ff 25 imm32) whose
    emission order differs from the retail image, adjusting every call site
    to keep calling the same import.

    Only the ORDER comes from the retail image: the rewritten operands are
    the built image's own thunk operands and rel32 displacements adjusted by
    the thunk stride.  Fail-closed: the built/retail delta must consist of
    exactly the swapped thunk pair plus call-site rel32 bytes that this
    order swap fully explains; the result must equal retail byte-for-byte
    wherever it differed before.
    """
    require(len(built) == len(retail), "image sizes differ")
    diffs = [index for index, pair in enumerate(zip(built, retail))
             if pair[0] != pair[1]]
    require(diffs, "images are already identical")

    pe = int.from_bytes(built[0x3C:0x40], "little")
    optional = pe + 24
    image_base = int.from_bytes(built[optional + 28:optional + 32], "little")
    section_count = int.from_bytes(built[pe + 6:pe + 8], "little")
    optional_size = int.from_bytes(built[pe + 20:pe + 22], "little")
    table = optional + optional_size
    sections = []
    for index in range(section_count):
        header = table + index * 40
        virtual = int.from_bytes(built[header + 12:header + 16], "little")
        raw_size = int.from_bytes(built[header + 16:header + 20], "little")
        raw_offset = int.from_bytes(built[header + 20:header + 24], "little")
        sections.append((virtual, raw_size, raw_offset))

    def offset_to_va(offset: int) -> int:
        for virtual, raw_size, raw_offset in sections:
            if raw_offset <= offset < raw_offset + raw_size:
                return image_base + virtual + (offset - raw_offset)
        raise ByteIdentityError("diff offset outside mapped sections")

    # Locate the swapped adjacent thunk pair.
    pair_offset = None
    for offset in diffs:
        for start in (offset - 2, offset - 3, offset - 4, offset - 5):
            if start < 0 or start + 12 > len(built):
                continue
            if (built[start:start + 2] == b"\xff\x25"
                    and built[start + 6:start + 8] == b"\xff\x25"
                    and retail[start:start + 2] == b"\xff\x25"
                    and retail[start + 6:start + 8] == b"\xff\x25"
                    and built[start + 2:start + 6]
                    == retail[start + 8:start + 12]
                    and built[start + 8:start + 12]
                    == retail[start + 2:start + 6]
                    and built[start + 2:start + 6]
                    != built[start + 8:start + 12]):
                require(pair_offset in (None, start),
                        "more than one swapped thunk pair")
                pair_offset = start
    require(pair_offset is not None, "no swapped adjacent thunk pair found")
    first_va = offset_to_va(pair_offset)
    second_va = first_va + 6
    thunk_span = set(range(pair_offset + 2, pair_offset + 6)) | set(
        range(pair_offset + 8, pair_offset + 12))

    output = bytearray(built)
    output[pair_offset + 2:pair_offset + 6] = built[
        pair_offset + 8:pair_offset + 12]
    output[pair_offset + 8:pair_offset + 12] = built[
        pair_offset + 2:pair_offset + 6]

    for offset in diffs:
        if offset in thunk_span:
            continue
        # Must be the rel32 of a near call targeting one of the two thunks.
        sites = [start for start in range(offset - 4, offset)
                 if start >= 0 and built[start] == 0xE8]
        adjusted = False
        for start in sites:
            rel = int.from_bytes(built[start + 1:start + 5], "little",
                                 signed=True)
            target = offset_to_va(start) + 5 + rel
            if target == first_va:
                moved = rel + 6
            elif target == second_va:
                moved = rel - 6
            else:
                continue
            output[start + 1:start + 5] = moved.to_bytes(4, "little",
                                                         signed=True)
            adjusted = True
            break
        require(adjusted,
                f"diff at {offset:#x} is not a thunk-pair call site")

    require(bytes(output) == retail,
            "thunk order swap does not fully explain the image delta")
    return bytes(output)


def validate_reccmp_report_snapshot(data: bytes, image_gate: dict) -> dict:
    """Validate the image's fixed row universe and report exact score-set facts."""
    try:
        document = strict_json_loads(data)
    except (UnicodeError, json.JSONDecodeError) as error:
        raise ByteIdentityError(f"cannot parse final reccmp report: {error}") from error
    require(isinstance(document, dict), "final reccmp report must be an object")
    exact_audit_keys(document, {"file", "format", "timestamp", "data"},
                     "final reccmp report")
    require(
        document.get("file") == image_gate["recompiled"]
        and type(document.get("format")) is int
        and document.get("format") == 1,
        "final reccmp report identity/schema differs",
    )
    require_nonnegative_finite_number(
        document.get("timestamp"), "final reccmp report timestamp"
    )
    rows = document.get("data")
    required_count = image_gate["required_row_count"]
    require(isinstance(rows, list) and len(rows) == required_count,
            f"final reccmp row count must be exactly {required_count}")
    identity_rows = []
    accepted_rows = []
    accepted_address_aligned = 0
    address_aligned = 0
    previous_address = -1
    seen_addresses = set()
    for index, row in enumerate(rows):
        context = f"final reccmp row[{index}]"
        require(isinstance(row, dict), f"{context} must be an object")
        required_keys = {"address", "name", "matching", "recomp", "type"}
        require(
            required_keys <= set(row)
            and set(row) <= required_keys | {"effective"},
            f"{context} schema differs",
        )
        address = row.get("address")
        name = row.get("name")
        row_type = row.get("type")
        require(
            isinstance(address, str)
            and ADDRESS_RE.fullmatch(address) is not None
            and isinstance(name, str) and bool(name)
            and type(row_type) is int and row_type in (1, 5),
            f"{context} identity is invalid",
        )
        numeric_address = int(address, 16)
        require(
            numeric_address > previous_address and address not in seen_addresses,
            f"{context} address order/uniqueness differs",
        )
        previous_address = numeric_address
        seen_addresses.add(address)
        matching = row.get("matching")
        recomp = row.get("recomp")
        require(type(matching) is float and math.isfinite(matching)
                and 0.0 <= matching <= 1.0,
                f"{context} raw matching score is invalid")
        require(isinstance(recomp, str)
                and ADDRESS_RE.fullmatch(recomp) is not None,
                f"{context} recompiled address is invalid")
        if "effective" in row:
            require(row["effective"] is True,
                    f"{context}.effective must be exact JSON true")
        identity_rows.append([address, name, row_type])
        if recomp == address:
            address_aligned += 1
        if matching == 1.0:
            accepted_rows.append([address, name, row_type])
            if recomp == address:
                accepted_address_aligned += 1
    identity_bytes = (
        "\n".join(
            json.dumps(row, separators=(",", ":"), ensure_ascii=True)
            for row in identity_rows
        ) + "\n"
    ).encode("utf-8")
    identity_sha = sha256_bytes(identity_bytes)
    require(
        identity_sha == image_gate["row_identity_sha256"],
        "final reccmp row identity/order universe differs from the retail pin",
    )
    accepted_bytes = (
        "\n".join(
            json.dumps(row, separators=(",", ":"), ensure_ascii=True)
            for row in accepted_rows
        ) + "\n"
    ).encode("utf-8")
    return {
        "row_count": len(rows),
        "raw_1_0_count": len(accepted_rows),
        "raw_1_0_address_aligned_count": accepted_address_aligned,
        "address_aligned_row_count": address_aligned,
        "accepted_row_identity_sha256": sha256_bytes(accepted_bytes),
        "row_identity_sha256": identity_sha,
    }


def validate_iteration_reccmp_report(data: bytes, image_gate: dict) -> dict:
    """Require the manifest-pinned accepted score set with zero losses/gains."""
    result = validate_reccmp_report_snapshot(data, image_gate)
    baseline = image_gate["iteration_baseline"]
    require(
        result["raw_1_0_count"] == baseline["exact_raw_1_0_count"]
        and result["accepted_row_identity_sha256"]
        == baseline["accepted_row_identity_sha256"],
        "iteration reccmp accepted raw-1.0 row set differs from its exact pin",
    )
    return result


def validate_complete_reccmp_report(data: bytes, image_gate: dict) -> dict:
    """Require every fixed diagnostic row to be raw-exact.

    The diagnostic /debug image is intentionally a different link lane and is
    not required to share retail addresses.  Final address/layout identity is
    proved by literal equality of the stamped no-/debug terminal image.
    """
    result = validate_reccmp_report_snapshot(data, image_gate)
    required = image_gate["required_row_count"]
    require(
        result["raw_1_0_count"] == required,
        f"final reccmp report is not exactly {required}/{required} raw-exact",
    )
    return result


# ---------------------------------------------------------------------------
# retail_exact_register_bijection: a register-renaming CERTIFICATE
# ---------------------------------------------------------------------------
#
# WHY THIS CLASS IS A CERTIFICATE AND NOT A GENERATOR
#
# Every other retail-exact class installs bytes some compile of the project's
# own source produced.  This class installs bytes derived from such a body by
# one bijective renaming of general registers -- so it must earn its place by
# proving, instruction by instruction, that the renaming is a *semantics-
# preserving* rewriting of an authenticated compiler-produced body, and then
# by REFUSING unless the rewritten body is byte-identical to the pinned retail
# oracle under the relocation mask.  It can therefore only ever install
# retail's own code; it can never invent a body, and it can never be used to
# nudge an arbitrary object towards an arbitrary target.
#
# That is the same epistemic class as `instruction_self_permutation`, which
# reorders two closed, provably independent compiler-produced instructions and
# is likewise gated on retail equality.  The obligations below are the ones
# that make the claim honest; each is a `require` in this module, not a
# comment:
#
#  1  provenance       the pre-image is a freshly compiled, census-pinned seed
#                      or donor COMDAT of the same mangled function
#  2  bijection        sigma is a bijection on the 8 general registers whose
#                      support excludes ESP and EBP, so no ModRM/SIB escape
#                      encoding (mod 0 rm 5, rm 4, index 4, base 5) can be
#                      created or destroyed and every length is preserved
#  3  frame invariance the region excludes the prologue and epilogue, whose
#                      bytes are required to be untouched: the callee-saved
#                      SET is what the ABI fixes, and it is unchanged
#  4  total decode     the whole body decodes to complete instructions with
#                      the fail-closed table, ends exactly on the last byte,
#                      and every COFF line-table row lands on a boundary
#  5  closed forms     every instruction in the body is in a closed semantic
#                      table that names its register fields and its implicit
#                      operands; anything else -- prefixes, implicit-operand
#                      forms (MUL/DIV/CDQ/string/shift-by-CL), indirect
#                      control flow -- is refused
#  6  relocations      no rewritten byte may overlap a relocation, and the
#                      relocation table is the seed's own, unmoved
#  7  liveness         every register in sigma's support is dead on entry to
#                      the region and dead on every edge leaving it, proved by
#                      a backward liveness fixpoint over the body's own CFG.
#                      A call CLOBBERS eax/ecx/edx unconditionally; whether it
#                      READS one of them is the callee's calling convention,
#                      DERIVED from the callee's own decoration through a
#                      closed table and never assumed.  The derivation tries
#                      every `@@` in the name as the scope terminator and
#                      demands EXACTLY ONE distinct reading: the true scope
#                      terminator is always one of those positions, so a
#                      single reading necessarily agrees with the truth and
#                      anything else -- an unmangled C symbol, a CRT helper,
#                      an import or adjustor thunk, an indirect call, a call
#                      with no relocation -- falls back to reading the whole
#                      caller-saved set.  That is the ONLY safe direction and
#                      it is the detail the soundness rests on.
#  8  retail equality  the image must equal the retail oracle exactly under
#                      the relocation mask, or the composition is refused
#  9  debug fidelity   the CodeView S_REGISTER records that name which
#                      register holds a local are mapped through sigma, and
#                      the record stream is re-parsed to exhaustion with an
#                      unchanged record identity/size list
# 10  scope            one named COMDAT, one sigma, one pinned oracle, and the
#                      ordinary output-conservation proof of the equal-body
#                      primitive, which this class delegates to unchanged.
#                      WHICH primitive is read off the manifest's own
#                      `expected_closure` pin -- never off the objects -- and
#                      the objects' closure is required to equal that pin
#                      first, so a pin that disagrees refuses before any
#                      delegate is chosen.  `(.debug$F, .debug$S)` names
#                      `equal_body_strict`; `(.debug$S, .xdata$x)`, the shape
#                      a C++ EH function carries, names
#                      `equal_body_eh_structural_local`, which additionally
#                      requires byte-identical xdata and proves each declared
#                      object-local $L/$T rename structurally.  Both are
#                      pre-existing classes with landed rows; this class adds
#                      no installation proof of its own, it selects one, and
#                      it pins the EXACT symbol pair of every rename it
#                      declares.


REGISTER_BIJECTION_CLASS = "retail_exact_register_bijection"


REGISTER_BIJECTION_KIND = "callee_saved_register_bijection_v1"


# The two COMDAT closure shapes this certificate installs through, and the
# PRE-EXISTING equal-body delegate each one names.  The delegate is chosen
# from the manifest PIN, never from the objects: the composer requires the
# objects' own closure to equal the pin first, so a pin that disagrees with
# what the seed and donor carry refuses before any delegate is selected.
# Both delegates are ordinary, independently proved classes of this module
# that already carry landed rows; this certificate adds no installation
# proof of its own, it selects one.
REGISTER_BIJECTION_FPO_CLOSURE = [".debug$F", ".debug$S"]
REGISTER_BIJECTION_EH_CLOSURE = [".debug$S", ".xdata$x"]


def register_bijection_delegate(
    expected_closure: object, expected_code_renames: object,
    expected_relocation_moves: object = (),
) -> str:
    """Name the installation delegate from the PINS alone.

    Both inputs are manifest declarations, never measurements of the objects
    -- the composer requires the objects' own closure and rename set to equal
    these pins first, so a pin that disagrees refuses before this is reached.
    `equal_body_strict` is kept wherever the pins allow it (the FPO closure
    with no declared rename), which is exactly the shape every row landed on
    this class so far.  Otherwise the delegate is
    `equal_body_eh_structural_local`, the pre-existing class that admits both
    closure shapes, requires byte-identical xdata, and proves each declared
    object-local $L/$T rename structurally.

    A donor that reaches a different compiler state can also SCHEDULE its
    instructions differently, which moves the operands its relocations cover.
    That is the pre-existing `equal_body_eh_reloc_layout` class: it pairs the
    two tables by ordinal, requires identical types and addends and
    structurally identical targets, and gives the seed's own relocation
    RECORDS the donor's offsets.  A non-empty `expected_relocation_moves` pin
    names it; an empty one can never reach it.
    """
    if expected_relocation_moves:
        return "equal_body_eh_reloc_layout"
    if (list(expected_closure) == REGISTER_BIJECTION_FPO_CLOSURE
            and not expected_code_renames):
        return "equal_body_strict"
    return "equal_body_eh_structural_local"


IA32_GENERAL_REGISTER_NAMES = (
    "eax", "ecx", "edx", "ebx", "esp", "ebp", "esi", "edi",
)


_IA32_REGISTER_NUMBERS = {
    name: number for number, name in enumerate(IA32_GENERAL_REGISTER_NAMES)
}


# The two registers whose encodings carry structural meaning in ModRM/SIB:
# rm == 4 selects a SIB byte, rm == 5 with mod == 0 selects disp32, index == 4
# means "no index" and base == 5 with mod == 0 means "no base".  A sigma whose
# support avoids them cannot change any instruction's length or addressing
# form, which is obligation 2.
_IA32_STRUCTURAL_REGISTERS = frozenset({"esp", "ebp"})


# cdecl/thiscall on this toolchain: EAX/ECX/EDX are call-clobbered, the rest
# are callee-saved.  The call model reads the clobbered set as well, which is
# the conservative direction for a liveness proof (it can only make a register
# look MORE live, never less).
_IA32_CALL_CLOBBERED = frozenset({"eax", "ecx", "edx"})


_IA32_RETURN_LIVE = frozenset({
    "eax", "ebx", "esi", "edi", "ebp", "esp",
})


# CodeView 4 x86 register numbers, for the S_REGISTER records that name which
# register holds a source local.
CODEVIEW_X86_REGISTER_NUMBERS = {
    "eax": 17, "ecx": 18, "edx": 19, "ebx": 20,
    "esp": 21, "ebp": 22, "esi": 23, "edi": 24,
}


CODEVIEW_REGISTER_RECORD_TYPE = 0x0002


def _bijection_form(
    *, modrm: bool = False, reg: str | None = None,
    reg_read: bool = False, reg_write: bool = False,
    rm_read: bool = False, rm_write: bool = False,
    ext_no_write: frozenset = frozenset(),
    ext_write: frozenset = frozenset(),
    ext_allowed: frozenset | None = None,
    ext_implicit: dict | None = None,
    ext_flow: dict | None = None,
    implicit_frozen: frozenset = frozenset(),
    opreg: str | None = None,
    reads: frozenset = frozenset(), writes: frozenset = frozenset(),
    flow: str = "fall", displacement: int = 0,
    width: int = 32, x87: bool = False, size16_ok: bool = False,
    size16_ext: frozenset | None = None,
    string_memory: dict | None = None,
) -> dict:
    return {
        "modrm": modrm, "reg": reg, "reg_read": reg_read,
        "reg_write": reg_write, "rm_read": rm_read, "rm_write": rm_write,
        # `ext_no_write` and `ext_write` are the two directions of the same
        # per-digit correction: a group whose members mostly write their r/m
        # names the exceptions in the first, a group whose members mostly do
        # not names the writers in the second.  Both are read off the
        # encoding's own extension digit, never assumed.
        "ext_no_write": ext_no_write, "ext_write": ext_write,
        "ext_allowed": ext_allowed,
        # `ext_implicit` gives, per ModRM extension digit, the complete
        # implicit (reads, writes, frozen) triple of that member; `ext_flow`
        # lets one opcode's members differ in control flow.  `implicit_frozen`
        # names the general registers a form touches through an encoding with
        # NO rewritable field at all (an accumulator or an EDX:EAX pair), so
        # sigma is refused inside the region rather than silently skipping it.
        "ext_implicit": ext_implicit or {}, "ext_flow": ext_flow or {},
        "implicit_frozen": implicit_frozen,
        "opreg": opreg,
        "reads": reads, "writes": writes, "flow": flow,
        "displacement": displacement,
        # `width` is the width of the form's REGISTER operands, not of its
        # address registers -- a memory operand's base and index are always
        # 32-bit and are always remappable.  `x87` marks a form whose ModRM
        # reg field is an opcode extension and whose mod == 3 operand is an
        # FPU stack register, i.e. not a general register at all.
        "width": width, "x87": x87, "size16_ok": size16_ok,
        # `size16_ext` restricts the operand-size prefix to named extension
        # digits of a group whose other members would be nonsense (or
        # unmodelled) at 16 bits; None admits the prefix for every admitted
        # digit.  `string_memory` marks a form whose memory operand is an
        # implicit, UNBOUNDED span through ESI/EDI whose extent is a runtime
        # count: it is described as unknown so that every consumer that
        # disambiguates memory refuses it rather than reading a descriptor
        # that does not exist.
        "size16_ext": size16_ext, "string_memory": string_memory,
    }


def _ia32_bijection_table() -> dict:
    """The closed semantic table this class will rewrite.

    An opcode is admitted only when its register fields and its *complete*
    implicit-operand set are known exactly.  Everything outside the table --
    including every form with an implicit general-register operand, every
    unadmitted prefix and every indirect *jump* -- is refused rather than
    guessed.
    """
    table = {}
    stack = frozenset({"esp"})
    # 31 /r XOR r/m32, r32 ; 33 /r XOR r32, r/m32
    table[0x31] = _bijection_form(modrm=True, reg="gpr", reg_read=True,
                                  rm_read=True, rm_write=True, size16_ok=True)
    table[0x33] = _bijection_form(modrm=True, reg="gpr", reg_read=True,
                                  reg_write=True, rm_read=True,
                                  size16_ok=True)
    # 39 /r CMP r/m32, r32 ; 3B /r CMP r32, r/m32 ; 85 /r TEST r/m32, r32
    table[0x39] = _bijection_form(modrm=True, reg="gpr", reg_read=True,
                                  rm_read=True, size16_ok=True)
    table[0x3B] = _bijection_form(modrm=True, reg="gpr", reg_read=True,
                                  rm_read=True, size16_ok=True)
    table[0x85] = _bijection_form(modrm=True, reg="gpr", reg_read=True,
                                  rm_read=True, size16_ok=True)
    # 2B /r SUB r32, r/m32 ; 03 /r ADD r32, r/m32 ; 1B /r SBB r32, r/m32
    for opcode in (0x03, 0x0B, 0x1B, 0x23, 0x2B):
        table[opcode] = _bijection_form(modrm=True, reg="gpr", reg_read=True,
                                        reg_write=True, rm_read=True,
                                        size16_ok=True)
    # 89 /r MOV r/m32, r32 ; 8B /r MOV r32, r/m32 ; 8D /r LEA r32, m
    table[0x89] = _bijection_form(modrm=True, reg="gpr", reg_read=True,
                                  rm_write=True, size16_ok=True)
    table[0x8B] = _bijection_form(modrm=True, reg="gpr", reg_write=True,
                                  rm_read=True, size16_ok=True)
    table[0x8D] = _bijection_form(modrm=True, reg="gpr", reg_write=True)
    # 83 /n group 1 with imm8, 81 /n group 1 with imm32: every member reads
    # r/m and writes it except /7 CMP, which only reads.
    table[0x83] = _bijection_form(modrm=True, reg="ext", rm_read=True,
                                  rm_write=True, ext_no_write=frozenset({7}),
                                  size16_ok=True)
    table[0x81] = _bijection_form(modrm=True, reg="ext", rm_read=True,
                                  rm_write=True, ext_no_write=frozenset({7}),
                                  size16_ok=True)
    # C7 /0 MOV r/m32, imm32 -- a pure definition of its r/m operand
    table[0xC7] = _bijection_form(modrm=True, reg="ext",
                                  ext_allowed=frozenset({0}), rm_write=True,
                                  size16_ok=True)
    # --- byte-operand forms.  The 3-bit register fields of these name AL..BH,
    # where 4..7 are the HIGH bytes of EAX..EBX, so the 32-bit sigma's
    # permutation of the field is NOT the right rewriting.  The decoder marks
    # such fields FROZEN: it reports the parent register they touch (so
    # liveness stays exact) but never offers them for rewriting, and
    # apply_register_bijection refuses if a frozen register is in sigma's
    # support inside the region.  A byte write is a PARTIAL write and is
    # therefore reported as a read only -- it must not kill the parent.
    table[0x38] = _bijection_form(modrm=True, reg="gpr", reg_read=True,
                                  rm_read=True, width=8)
    table[0x3A] = _bijection_form(modrm=True, reg="gpr", reg_read=True,
                                  rm_read=True, width=8)
    table[0x84] = _bijection_form(modrm=True, reg="gpr", reg_read=True,
                                  rm_read=True, width=8)
    table[0x88] = _bijection_form(modrm=True, reg="gpr", reg_read=True,
                                  rm_write=True, width=8)
    table[0x8A] = _bijection_form(modrm=True, reg="gpr", reg_write=True,
                                  rm_read=True, width=8)
    table[0x1A] = _bijection_form(modrm=True, reg="gpr", reg_read=True,
                                  reg_write=True, rm_read=True, width=8)
    table[0x80] = _bijection_form(modrm=True, reg="ext", rm_read=True,
                                  rm_write=True, ext_no_write=frozenset({7}),
                                  width=8)
    table[0xC6] = _bijection_form(modrm=True, reg="ext",
                                  ext_allowed=frozenset({0}), rm_write=True,
                                  width=8)
    # F6 /0 TEST r/m8, imm8 (read only), /2 NOT, /3 NEG.  /4 MUL, /5 IMUL,
    # /6 DIV and /7 IDIV carry implicit EAX/EDX operands and stay refused.
    table[0xF6] = _bijection_form(modrm=True, reg="ext", rm_read=True,
                                  rm_write=True,
                                  ext_no_write=frozenset({0}),
                                  ext_allowed=frozenset({0, 2, 3}), width=8)
    # FE /0 INC r/m8, FE /1 DEC r/m8 -- the byte siblings of 40+r/48+r.  A
    # byte write is partial, so `_touch` reports it as a read and the field
    # is frozen, exactly as for the other byte forms.
    table[0xFE] = _bijection_form(modrm=True, reg="ext", rm_read=True,
                                  rm_write=True,
                                  ext_allowed=frozenset({0, 1}), width=8)
    # 3C ib CMP AL, imm8 -- the byte accumulator form.  It names AL through
    # no field at all, so EAX is reported read and FROZEN.
    table[0x3C] = _bijection_form(reads=frozenset({"eax"}),
                                  implicit_frozen=frozenset({"eax"}))
    # 99 CDQ -- sign-extends EAX into EDX:EAX.  Both registers are implicit
    # and unrewritable, so both are frozen.
    table[0x99] = _bijection_form(reads=frozenset({"eax"}),
                                  writes=frozenset({"edx"}),
                                  implicit_frozen=frozenset({"eax", "edx"}))
    # F7 group 3, 32-bit.  /0 TEST imm32 reads only; /2 NOT and /3 NEG read
    # and write their r/m.  /4 MUL, /5 IMUL, /6 DIV and /7 IDIV additionally
    # carry the implicit EDX:EAX pair: all four WRITE both halves, and the
    # read set is declared as both halves for all four -- over-claiming a
    # read is conservative for liveness, over-claiming a write would not be.
    # EAX and EDX are frozen there because neither is named by a field.
    _muldiv = (frozenset({"eax", "edx"}), frozenset({"eax", "edx"}),
               frozenset({"eax", "edx"}))
    table[0xF7] = _bijection_form(
        modrm=True, reg="ext", rm_read=True, rm_write=True,
        ext_no_write=frozenset({0, 4, 5, 6, 7}),
        ext_allowed=frozenset({0, 2, 3, 4, 5, 6, 7}),
        ext_implicit={4: _muldiv, 5: _muldiv, 6: _muldiv, 7: _muldiv})
    # 40+r INC r32 ; 48+r DEC r32 ; 50+r PUSH r32 ; 58+r POP r32
    # B8+r MOV r32, imm32
    # The operand-size prefix is admitted on INC/DEC r16 and MOV r16, imm16,
    # whose 3-bit opcode field numbers AX..DI -- the same eight registers the
    # 32-bit field numbers, so sigma's permutation is the right rewriting and
    # the write is a PARTIAL one that kills only the low two atoms.  It is
    # NOT admitted on 50+r/58+r: a 16-bit push moves ESP by two, and the
    # stack model this decoder hands its callers describes a four-byte slot.
    for index in range(8):
        table[0x40 + index] = _bijection_form(opreg="readwrite",
                                              size16_ok=True)
        table[0x48 + index] = _bijection_form(opreg="readwrite",
                                              size16_ok=True)
        table[0x50 + index] = _bijection_form(
            opreg="read", reads=stack, writes=stack)
        table[0x58 + index] = _bijection_form(
            opreg="write", reads=stack, writes=stack)
        table[0xB8 + index] = _bijection_form(opreg="write", size16_ok=True)
    # 05 ADD eax, imm32 -- the accumulator form names EAX implicitly and has
    # no register field to rewrite, so it is admitted with EAX pinned.
    table[0x05] = _bijection_form(reads=frozenset({"eax"}),
                                  writes=frozenset({"eax"}),
                                  implicit_frozen=frozenset({"eax"}))
    # A1 MOV eax, moffs32 ; A3 MOV moffs32, eax -- no ModRM, no rewritable
    # field; the moffs is an absolute address, optionally segment-prefixed.
    table[0xA1] = _bijection_form(writes=frozenset({"eax"}),
                                  implicit_frozen=frozenset({"eax"}))
    table[0xA3] = _bijection_form(reads=frozenset({"eax"}),
                                  implicit_frozen=frozenset({"eax"}))
    # 68 PUSH imm32 ; 6A PUSH imm8
    table[0x68] = _bijection_form(reads=stack, writes=stack)
    table[0x6A] = _bijection_form(reads=stack, writes=stack)
    # 70..7F Jcc rel8, EB JMP rel8, E9 JMP rel32, E8 CALL rel32
    for opcode in range(0x70, 0x80):
        table[opcode] = _bijection_form(flow="jcc", displacement=1)
    table[0xEB] = _bijection_form(flow="jmp", displacement=1)
    table[0xE9] = _bijection_form(flow="jmp", displacement=4)
    # The call's ARGUMENT read set is decided by the decoder: fully
    # conservative unless the callee is resolved through a relocation to a
    # name the closed decoration table recognises.  The CLOBBER set is
    # unconditional -- a clobber kills liveness, it never creates it.
    table[0xE8] = _bijection_form(
        flow="call", displacement=4, reads=stack,
        writes=_IA32_CALL_CLOBBERED)
    # FF /2 CALL r/m32 -- an indirect call.  It does not disturb the control
    # -flow graph (it falls through), and its callee can never be named, so
    # it stays fully conservative.  FF /4 and /5 are indirect JUMPS, which
    # would break the graph, and stay refused with every other extension.
    # FF /4 JMP r/m32 -- a computed jump (a switch dispatch through this
    # COMDAT's own table).  Its successors cannot be read from the encoding,
    # so it is modelled as an EXIT that reads EVERY general register: no
    # successor edge, and a live-in set that is the maximum possible, which
    # is strictly more conservative than any edge set could be.  The targets
    # it can reach are proved not to enter the region separately, from the
    # relocated in-body label set.  FF /5 is a far jump and stays refused.
    # FF /0 INC r/m32 and FF /1 DEC r/m32 are the ordinary read-modify-write
    # members of the group: no implicit operand, no control transfer, and
    # they fall through.  Their write is named through `ext_write` because
    # the group's OTHER admitted members do not write their r/m at all.
    # The operand-size prefix is admitted for those two digits only: a
    # 16-bit indirect CALL or computed JUMP is not this table's to model.
    # /3 and /5 are far transfers and /6 is PUSH r/m32, whose store at
    # [esp-4] this decoder does not describe; all three stay refused.
    table[0xFF] = _bijection_form(
        modrm=True, reg="ext", ext_allowed=frozenset({0, 1, 2, 4}),
        rm_read=True, ext_write=frozenset({0, 1}),
        size16_ok=True, size16_ext=frozenset({0, 1}),
        flow="call", ext_flow={0: "fall", 1: "fall", 2: "call", 4: "exit"},
        ext_implicit={
            2: (stack, _IA32_CALL_CLOBBERED, frozenset()),
            4: (frozenset(IA32_GENERAL_REGISTER_NAMES), frozenset(),
                frozenset()),
        })
    # C2 iw / C3 RET
    table[0xC2] = _bijection_form(flow="ret", reads=_IA32_RETURN_LIVE)
    table[0xC3] = _bijection_form(flow="ret", reads=_IA32_RETURN_LIVE)
    # D8..DF x87.  The ModRM reg field is an opcode extension and a mod == 3
    # operand is an FPU stack register, so no x87 form has a general-register
    # operand at all; a memory form reads its address registers and nothing
    # else.  The FPU stack is invisible to a general-register bijection.
    for opcode in range(0xD8, 0xE0):
        table[opcode] = _bijection_form(modrm=True, reg="ext", x87=True)
    return _ia32_bijection_table_widening(table)


# Group 2 (shift/rotate) extension digits this table admits: ROL, ROR, SHL,
# SHR and SAR.  /2 RCL and /3 RCR additionally rotate THROUGH CF, and /6 is an
# undefined slot; none of the three is emitted by this compiler anywhere in
# the build, and all three stay refused rather than guessed.
_IA32_SHIFT_DIGITS = frozenset({0, 1, 4, 5, 7})


def _ia32_bijection_table_widening(table: dict) -> dict:
    """The forms this compiler emits that the first hundred did not name.

    Every entry here was measured before it was written: `$W/BF-probe`
    compiles each encoding with this project's own MSVC 4.2, runs it under
    Wine over a register file of distinct arena pointers, perturbs one
    liveness ATOM at a time, and refuses the entry unless

      * every atom the entry does not declare READ leaves the whole final
        state -- registers, flags and memory -- unchanged except for its own
        preserved copy, and
      * every atom the entry declares written and not read comes out
        independent of its input, and
      * every register the instruction is observed to touch is either named
        by a rewritable field of the encoding or declared FROZEN.

    The same three checks are re-run over the pre-existing entries as a
    control.  A form whose complete effect could not be stated is left out
    and named in the refusal tests instead.
    """
    # ---- 90 NOP.  It is the degenerate member of the 90+r XCHG EAX, r32
    # family and the ONLY member admitted: 91..97 exchange two registers, one
    # of which is named by no rewritable field.  NOP touches no register, no
    # memory and no flag.
    table[0x90] = _bijection_form()
    # ---- Byte ALU, both directions.  `op r/m8, r8` reads both operands and
    # writes r/m; `op r8, r/m8` reads both and writes reg.  Every byte write
    # is PARTIAL, so `_touch` reports it as a read and the field is frozen.
    # 00 ADD r/m8, r8 is deliberately absent: `00 00` is this linker's
    # alignment filler, and refusing it is what keeps an unpinned data tail
    # from decoding silently as code.
    for opcode in (0x08, 0x10, 0x18, 0x20, 0x28, 0x30):
        table[opcode] = _bijection_form(modrm=True, reg="gpr", reg_read=True,
                                        rm_read=True, rm_write=True, width=8)
    for opcode in (0x02, 0x0A, 0x12, 0x22, 0x2A, 0x32):
        table[opcode] = _bijection_form(modrm=True, reg="gpr", reg_read=True,
                                        reg_write=True, rm_read=True, width=8)
    # ---- Dword ALU, the `op r/m32, r32` direction the first table omitted,
    # plus ADC r32, r/m32.  ADC and SBB read CF as well; a flag is not a
    # general register, and the flag-modelling tables are separate and
    # fail-closed.
    for opcode in (0x01, 0x09, 0x11, 0x19, 0x21, 0x29):
        table[opcode] = _bijection_form(modrm=True, reg="gpr", reg_read=True,
                                        rm_read=True, rm_write=True,
                                        size16_ok=True)
    table[0x13] = _bijection_form(modrm=True, reg="gpr", reg_read=True,
                                  reg_write=True, rm_read=True,
                                  size16_ok=True)
    # ---- The accumulator forms.  AL or EAX is named by NO field, so the
    # register is reported read and FROZEN, exactly as the pre-existing
    # `3C CMP AL, imm8` and `05 ADD EAX, imm32` entries do.  The byte members
    # write AL, which is a partial write and is therefore declared as a read
    # and never as a kill; the dword members define EAX outright.  The
    # operand-size prefix is NOT admitted on any of them: `add ax, imm16` is
    # a partial write, and these entries have no field for `_touch` to widen.
    for opcode in (0x04, 0x0C, 0x14, 0x1C, 0x24, 0x2C, 0x34, 0xA8):
        table[opcode] = _bijection_form(reads=frozenset({"eax"}),
                                        implicit_frozen=frozenset({"eax"}),
                                        width=8)
    for opcode in (0x0D, 0x15, 0x1D, 0x25, 0x2D, 0x35):
        table[opcode] = _bijection_form(reads=frozenset({"eax"}),
                                        writes=frozenset({"eax"}),
                                        implicit_frozen=frozenset({"eax"}))
    # CMP EAX, imm32 and TEST EAX, imm32 are the only accumulator forms that
    # WRITE no register, so they are the only ones the operand-size prefix
    # can safely widen: `cmp ax, imm16` reads a subset of the atoms the
    # entry already declares read, and there is no kill to get wrong.  The
    # read-modify-write members (05/0D/15/1D/25/2D/35) stay refused under the
    # prefix -- their declared definition of EAX is a full 32-bit one, and at
    # 16 bits that would be a false kill of the upper half.
    for opcode in (0x3D, 0xA9):
        table[opcode] = _bijection_form(reads=frozenset({"eax"}),
                                        implicit_frozen=frozenset({"eax"}),
                                        size16_ok=True)
    # ---- B0+r MOV r8, imm8.  The 3-bit opcode field numbers AL..BH, whose
    # 4..7 are the HIGH bytes of EAX..EBX, so it is a frozen field and the
    # write is partial: it kills exactly one byte atom of one of four
    # registers and reports the parent as read.
    for index in range(8):
        table[0xB0 + index] = _bijection_form(opreg="write", width=8)
    # ---- Group 2, shift and rotate.  Every admitted member reads and writes
    # its r/m and names no other general register, except the by-CL forms,
    # which read CL through no field at all and therefore freeze ECX.
    for opcode in (0xC0, 0xD0):
        table[opcode] = _bijection_form(modrm=True, reg="ext", rm_read=True,
                                        rm_write=True, width=8,
                                        ext_allowed=_IA32_SHIFT_DIGITS)
    for opcode in (0xC1, 0xD1):
        table[opcode] = _bijection_form(modrm=True, reg="ext", rm_read=True,
                                        rm_write=True, size16_ok=True,
                                        ext_allowed=_IA32_SHIFT_DIGITS)
    table[0xD2] = _bijection_form(modrm=True, reg="ext", rm_read=True,
                                  rm_write=True, width=8,
                                  ext_allowed=_IA32_SHIFT_DIGITS,
                                  reads=frozenset({"ecx"}),
                                  implicit_frozen=frozenset({"ecx"}))
    table[0xD3] = _bijection_form(modrm=True, reg="ext", rm_read=True,
                                  rm_write=True, size16_ok=True,
                                  ext_allowed=_IA32_SHIFT_DIGITS,
                                  reads=frozenset({"ecx"}),
                                  implicit_frozen=frozenset({"ecx"}))
    return table


def _ia32_bijection_two_byte_table() -> dict:
    """The 0F escape forms this class admits: near Jcc, MOVZX/MOVSX r32,r16.

    `0F B7`/`0F BF` widen a 16-bit source into a 32-bit destination.  Both
    fields number the SAME eight registers (a mod == 3 r/m16 is AX..DI, not
    AL..BH), so sigma's permutation is the right rewriting for both, and the
    destination write is a full 32-bit definition that legitimately kills.
    The byte-source siblings `0F B6`/`0F BE` are deliberately absent: their
    r/m8 is a frozen field, and no row needs them.
    """
    table = {}
    for opcode in range(0x80, 0x90):
        table[opcode] = _bijection_form(flow="jcc", displacement=4)
    for opcode in (0xB7, 0xBF):
        table[opcode] = _bijection_form(modrm=True, reg="gpr",
                                        reg_write=True, rm_read=True)
    return table


IA32_BIJECTION_FORMS = _ia32_bijection_table()
IA32_BIJECTION_TWO_BYTE_FORMS = _ia32_bijection_two_byte_table()


# Segment overrides are inert for a general-register bijection: they select
# the segment a memory operand is resolved in and touch no register field.
_IA32_INERT_SEGMENT_PREFIXES = frozenset({0x26, 0x2E, 0x36, 0x3E, 0x64, 0x65})
_IA32_OPERAND_SIZE_PREFIX = 0x66
_IA32_REPEAT_PREFIXES = frozenset({0xF2, 0xF3})


def _ia32_string_form(reads, writes, *, memory_read, memory_write) -> dict:
    """One repeated string operation, with its COMPLETE implicit operand set.

    Every general register such a form touches -- the count in ECX, the
    source pointer in ESI, the destination pointer in EDI, the value or
    comparand in EAX -- is named by NO field of the encoding, so all of them
    are FROZEN and a sigma whose support meets one is refused inside the
    region.  A register the form defines is also a register it reads (the
    pointers advance from their own value, and the count is read before it is
    zeroed), so the declared write can never under-approximate liveness: the
    read re-adds every atom the write would kill.

    The MEMORY it touches is a span whose extent is the runtime value of ECX.
    That extent is not a descriptor any disambiguation rule can compare, so
    the form declares its memory UNKNOWN and every consumer that reasons
    about memory refuses it outright rather than reading an address that was
    never derived.
    """
    return _bijection_form(
        reads=frozenset(reads), writes=frozenset(writes),
        implicit_frozen=frozenset(set(reads) | set(writes)),
        string_memory={"read": memory_read, "write": memory_write})


# `rep movs` copies ECX elements from [ESI] to [EDI]; `rep stos` writes the
# accumulator ECX times to [EDI]; `repe/repne scas` compares the accumulator
# against [EDI] and `repe/repne cmps` compares [ESI] against [EDI], both
# stopping on ZF.  All four advance their pointers, all four run the count
# down to zero, and none of them writes a general register the encoding could
# have named differently.  A string opcode WITHOUT a repeat prefix is not in
# this table and stays refused; so does every other use of F2/F3, and LOCK.
IA32_BIJECTION_REPEATED_STRING_FORMS = {
    (prefix, opcode): _ia32_string_form(
        ("ecx", "esi", "edi"), ("ecx", "esi", "edi"),
        memory_read=True, memory_write=True)
    for prefix in (0xF3,) for opcode in (0xA4, 0xA5)
}
IA32_BIJECTION_REPEATED_STRING_FORMS.update({
    (0xF3, opcode): _ia32_string_form(
        ("eax", "ecx", "edi"), ("ecx", "edi"),
        memory_read=False, memory_write=True)
    for opcode in (0xAA, 0xAB)
})
IA32_BIJECTION_REPEATED_STRING_FORMS.update({
    (prefix, opcode): _ia32_string_form(
        ("eax", "ecx", "edi"), ("ecx", "edi"),
        memory_read=True, memory_write=False)
    for prefix in (0xF2, 0xF3) for opcode in (0xAE, 0xAF)
})
IA32_BIJECTION_REPEATED_STRING_FORMS.update({
    (prefix, opcode): _ia32_string_form(
        ("ecx", "esi", "edi"), ("ecx", "esi", "edi"),
        memory_read=True, memory_write=False)
    for prefix in (0xF2, 0xF3) for opcode in (0xA6, 0xA7)
})


# An unconditional branch whose displacement is entirely covered by a
# relocation leaves this COMDAT (a tail-jump into another symbol).  It is
# modelled as a function exit that reads EVERY general register -- strictly
# more conservative than `ret`, which reads only the ABI's live-out set.
_IA32_EXTERNAL_TRANSFER_LIVE = frozenset(IA32_GENERAL_REGISTER_NAMES)


# ---------------------------------------------------------------------------
# Sub-register liveness atoms
#
# Register-granular liveness cannot express `fnstsw ax` -- a 16-bit write that
# genuinely DEFINES the bits `test ah, imm8` then reads.  Modelling a partial
# write as "not a kill" is sound but so imprecise that it reports a register
# live across a definition of it.  The lattice below is the ordinary
# sub-register refinement: EAX/ECX/EDX/EBX split into their low byte, high
# byte and upper half, and the four index/pointer registers stay whole because
# no encoding in the closed table writes a part of them.
#
# It is a REFINEMENT, not a relaxation: every access still reads exactly the
# atoms it reads, and an access kills an atom only when it writes ALL of that
# atom's bits.  A 16-bit write to SI, had the table admitted one, would still
# kill nothing.
# ---------------------------------------------------------------------------
_IA32_BYTE_ADDRESSABLE = ("eax", "ecx", "edx", "ebx")


def _ia32_register_atoms(name: str) -> tuple:
    """Every liveness atom of one general register."""
    if name in _IA32_BYTE_ADDRESSABLE:
        return (name + ".l", name + ".h", name + ".u")
    return (name + ".w",)


_IA32_ATOMS_OF = {
    name: frozenset(_ia32_register_atoms(name))
    for name in IA32_GENERAL_REGISTER_NAMES
}


def ia32_register_atoms(names) -> frozenset:
    """The atom set of a collection of whole general registers."""
    return frozenset().union(*[_IA32_ATOMS_OF[name] for name in names]) \
        if names else frozenset()


def _ia32_atom_registers(atoms) -> list:
    """The register names an atom set touches, for a refusal message."""
    return sorted({atom.split(".")[0] for atom in atoms})


def _bijection_form_for(opcode: int) -> dict | None:
    """Look one decoded opcode key up in the closed table."""
    if opcode & 0xFF00 == 0x0F00:
        return IA32_BIJECTION_TWO_BYTE_FORMS.get(opcode & 0xFF)
    return IA32_BIJECTION_FORMS.get(opcode)


# ---------------------------------------------------------------------------
# The callee-argument model (obligation 7)
#
# `call` CLOBBERS EAX/ECX/EDX on this ABI; whether it READS one of them is a
# different fact, and it is decided by the callee's calling convention.
# Modelling every call as reading all three conflates the two and makes a
# caller-scratch register look live when the callee cannot possibly read it.
# This table DERIVES the fact from the callee's own decoration and FAILS
# CLOSED: any name it does not recognise -- an unmangled C symbol, a CRT
# helper, an import thunk, an adjustor thunk, or a decoration whose readings
# disagree -- returns None and the call stays fully conservative.  An indirect
# call can never be named and is therefore always conservative.
# ---------------------------------------------------------------------------

# MSVC function-class letters.  Non-static members carry a CV letter before
# the calling convention; statics and globals do not.  G/H/O/P/W/X are
# adjustor-thunk classes and are deliberately absent: a thunk is refused.
_MSVC_MEMBER_FUNCTION_CLASSES = frozenset("ABEFIJMNQRUV")
_MSVC_STATIC_FUNCTION_CLASSES = frozenset("CDKLST")
_MSVC_GLOBAL_FUNCTION_CLASSES = frozenset("YZ")
_MSVC_THUNK_FUNCTION_CLASSES = frozenset("GHOPWX")
_MSVC_CV_LETTERS = frozenset("ABCD")

# Calling-convention letters -> the general registers that carry ARGUMENTS.
_MSVC_CALL_ARGUMENT_REGISTERS = {
    "A": frozenset(), "B": frozenset(),                      # __cdecl
    "C": frozenset(), "D": frozenset(),                      # __pascal
    "E": frozenset({"ecx"}), "F": frozenset({"ecx"}),        # __thiscall
    "G": frozenset(), "H": frozenset(),                      # __stdcall
    "I": frozenset({"ecx", "edx"}),                          # __fastcall
    "J": frozenset({"ecx", "edx"}),                          # __fastcall
}


def msvc_call_argument_registers(symbol: object) -> frozenset | None:
    """Which general registers a callee reads as arguments, or None.

    Closed decode of an MSVC 4.2 decorated name.  Every `@@` in the name is
    tried as the scope terminator; a position is a *reading* only if the
    letters after it form a complete (function class, [CV], calling
    convention) triple.  The true scope terminator is always one such
    position, so requiring **exactly one distinct reading** means the answer
    agrees with the truth or is refused.  Adjustor thunks, undecorated names
    and anything else return None, which the caller must treat as "read the
    whole caller-saved set".
    """
    if not isinstance(symbol, str) or not symbol.startswith("?"):
        return None
    if not symbol.endswith("Z"):        # data decorations are not callees
        return None
    readings = set()
    for index in range(len(symbol) - 1):
        if symbol[index:index + 2] != "@@":
            continue
        cursor = index + 2
        if cursor >= len(symbol):
            continue
        letter = symbol[cursor]
        cursor += 1
        if letter in _MSVC_THUNK_FUNCTION_CLASSES:
            # A strict thunk decoration is class + displacement digit + CV +
            # convention.  If one is present anywhere, refuse the whole name:
            # a thunk's own convention is not this table's to guess.
            if (cursor + 2 < len(symbol) and symbol[cursor].isdigit()
                    and symbol[cursor + 1] in _MSVC_CV_LETTERS
                    and symbol[cursor + 2] in _MSVC_CALL_ARGUMENT_REGISTERS):
                return None
            continue
        if letter in _MSVC_MEMBER_FUNCTION_CLASSES:
            if cursor >= len(symbol) or symbol[cursor] not in _MSVC_CV_LETTERS:
                continue
            cursor += 1
        elif letter not in (_MSVC_STATIC_FUNCTION_CLASSES
                            | _MSVC_GLOBAL_FUNCTION_CLASSES):
            continue
        if cursor >= len(symbol):
            continue
        registers = _MSVC_CALL_ARGUMENT_REGISTERS.get(symbol[cursor])
        if registers is None:
            continue
        readings.add(registers)
    if len(readings) != 1:
        return None
    return next(iter(readings))


def decode_ia32_bijection_instruction(
    body: bytes, offset: int, context: str,
    relocations: dict | None = None,
) -> dict:
    """Decode one instruction into register fields, operands and control flow.

    Returns the encoding's general-register fields as `(byte, shift)` pairs so
    a bijection can rewrite them in place, together with the exact set of
    general registers the instruction reads and writes -- explicit operands
    and the table's implicit ones alike.  `frozen` names the general registers
    an instruction touches through a field that cannot be rewritten (a
    sub-register encoding); `relocations`, when given, maps a relocation's
    offset to `{"width": int, "target": str}` and is what lets a direct call's
    callee be named.
    """
    require(0 <= offset < len(body), f"{context}: instruction offset is out "
            "of range")
    window = body[offset:]
    length = supported_ia32_instruction_length(window, context)
    encoded = body[offset:offset + length]
    require(len(encoded) == length,
            f"{context}: instruction is truncated")
    cursor = 0
    segment_prefix = False
    operand_size_16 = False
    repeat_prefix = None
    while encoded[cursor] in _IA32_PREFIXES:
        prefix = encoded[cursor]
        if prefix in _IA32_INERT_SEGMENT_PREFIXES:
            require(not segment_prefix,
                    f"{context}: repeated segment prefix")
            segment_prefix = True
        elif prefix == _IA32_OPERAND_SIZE_PREFIX:
            require(not operand_size_16,
                    f"{context}: repeated operand-size prefix")
            operand_size_16 = True
        elif prefix in _IA32_REPEAT_PREFIXES:
            # F2/F3 are admitted ONLY as the repeat prefix of a string
            # operation named in the closed table below; every other use of
            # them, and LOCK, is refused with the message that follows.
            require(repeat_prefix is None,
                    f"{context}: repeated repeat prefix")
            repeat_prefix = prefix
        else:
            raise ByteIdentityError(
                f"{context}: prefixed instructions are outside the "
                "register-bijection table")
        cursor += 1
        require(cursor < length, f"{context}: instruction is only prefixes")
    opcode_at = offset + cursor
    opcode = encoded[cursor]
    cursor += 1
    if opcode == 0x0F:
        require(cursor < length,
                f"{context}: truncated two-byte opcode")
        opcode = 0x0F00 | encoded[cursor]
        cursor += 1
    if repeat_prefix is not None:
        form = IA32_BIJECTION_REPEATED_STRING_FORMS.get(
            (repeat_prefix, opcode))
        require(form is not None,
                f"{context}: the repeat prefix 0x{repeat_prefix:02x} on "
                f"opcode 0x{opcode:02x} is outside the register-bijection "
                "table")
        require(not operand_size_16,
                f"{context}: an operand-size prefix on a repeated string "
                "operation is outside the register-bijection table")
    else:
        form = _bijection_form_for(opcode)
    require(form is not None,
            f"{context}: opcode 0x{opcode:02x} is outside the "
            "register-bijection table")
    width = form["width"]
    if operand_size_16:
        require(form["size16_ok"] and width == 32,
                f"{context}: the operand-size prefix is outside the "
                "register-bijection table for this opcode")
        width = 16
    fields = []
    # The ModRM/SIB LAYOUT of this instruction, or None when it has none.
    # A register bijection never reads it; the re-encoding bijection needs it
    # to change a ModRM `mod` field structurally rather than by
    # re-disassembling its own output, and deriving it here keeps ONE decoder
    # authoritative for every consumer.
    encoding = None
    flow_override = None
    frozen = set(form["implicit_frozen"])
    memory = None
    reads = set(form["reads"])
    writes = set(form["writes"])
    # The atom sets are the liveness model; `reads`/`writes` stay
    # register-granular because they are this decoder's public operand
    # description and the image check compares them under sigma.
    read_atoms = set(ia32_register_atoms(form["reads"]))
    write_atoms = set(ia32_register_atoms(form["writes"]))
    read_atoms |= ia32_register_atoms(form["implicit_frozen"])
    indirect = False
    names = IA32_GENERAL_REGISTER_NAMES

    def _touch(value: int, is_read: bool, is_write: bool) -> None:
        """Account for one register-operand field of the form's own width.

        32- and 16-bit fields number the same eight registers, so they are
        rewritable; an 8-bit field numbers AL..BH, whose 4..7 are the HIGH
        bytes of EAX..EBX, so it is frozen.  At REGISTER granularity a write
        narrower than 32 bits is reported as a read and never as a kill; at
        ATOM granularity it reads and kills exactly the atoms it touches.
        """
        if width == 8:
            name = names[value & 3]
            frozen.add(name)
            atoms = frozenset({name + (".l" if value < 4 else ".h")})
        else:
            name = names[value]
            if width == 16 and name in _IA32_BYTE_ADDRESSABLE:
                atoms = frozenset({name + ".l", name + ".h"})
            elif width == 16:
                # A 16-bit access to a whole-atom register reads all of it and
                # -- were such a form ever admitted -- would kill none of it.
                atoms = _IA32_ATOMS_OF[name]
            else:
                atoms = _IA32_ATOMS_OF[name]
        if is_read or (is_write and width != 32):
            reads.add(name)
        if is_write and width == 32:
            writes.add(name)
        if is_read:
            read_atoms.update(atoms)
        if is_write:
            if width == 32 or name in _IA32_BYTE_ADDRESSABLE:
                write_atoms.update(atoms)
            else:
                read_atoms.update(atoms)

    if form["opreg"] is not None:
        # The 3-bit opcode field is accounted for by exactly the same
        # width-aware rule as a ModRM register field: at 32 bits it names one
        # of the eight general registers and is rewritable, at 16 it names
        # the same eight but writes only two of their atoms, and at 8 it
        # names AL..BH and is FROZEN.  At 32 bits this is bit-for-bit what
        # the register-granular code it replaces did.
        if width != 8:
            fields.append((opcode_at, 0))
        _touch(opcode & 7, form["opreg"] in ("read", "readwrite"),
               form["opreg"] in ("write", "readwrite"))
    if form["modrm"]:
        require(cursor < length, f"{context}: instruction lacks ModRM")
        modrm_at = offset + cursor
        modrm = encoded[cursor]
        cursor += 1
        modrm_byte = modrm
        mode = modrm >> 6
        rm = modrm & 7
        register_field = (modrm >> 3) & 7
        rm_write = form["rm_write"]
        sib_at = None
        displacement_at = None
        displacement_size = 0
        absolute_operand = False
        if form["reg"] == "gpr":
            if width != 8:
                fields.append((modrm_at, 3))
            _touch(register_field, form["reg_read"], form["reg_write"])
        else:
            require(form["reg"] == "ext",
                    f"{context}: ModRM register field role is undeclared")
            allowed = form["ext_allowed"]
            require(allowed is None or register_field in allowed,
                    f"{context}: ModRM extension /{register_field} of opcode "
                    f"0x{opcode:02x} is outside the register-bijection table")
            require(width != 16 or form["size16_ext"] is None
                    or register_field in form["size16_ext"],
                    f"{context}: the operand-size prefix on extension "
                    f"/{register_field} of opcode 0x{opcode:02x} is outside "
                    "the register-bijection table")
            if register_field in form["ext_no_write"]:
                rm_write = False
            if register_field in form["ext_write"]:
                rm_write = True
            implicit = form["ext_implicit"].get(register_field)
            if implicit is not None:
                extra_reads, extra_writes, extra_frozen = implicit
                reads |= extra_reads
                writes |= extra_writes
                frozen |= extra_frozen
                read_atoms |= ia32_register_atoms(extra_reads | extra_frozen)
                write_atoms |= ia32_register_atoms(extra_writes)
            member_flow = form["ext_flow"].get(register_field)
            if member_flow is not None:
                flow_override = member_flow
        if mode == 3:
            if form["x87"]:
                # An FPU stack register: not a general register at all --
                # except for the single encoding DF E0 FNSTSW AX, which
                # stores the FPU status word into AX.  It is a complete
                # definition of AL and AH and reads no general register, so
                # it kills exactly those two atoms and nothing else.  At
                # register granularity it is still only a partial write and
                # therefore appears in neither `reads` nor `writes`.
                if opcode == 0xDF and modrm == 0xE0:
                    write_atoms |= {"eax.l", "eax.h"}
                    frozen.add("eax")
            else:
                if width != 8:
                    fields.append((modrm_at, 0))
                _touch(rm, form["rm_read"], rm_write)
        else:
            # A memory operand: the base and index registers are read for the
            # address computation and are always 32-bit, whatever the form's
            # operand width; the memory cell itself is irrelevant to
            # general-register liveness.  The read is recorded in BOTH
            # descriptions -- the register-granular `reads` and the ATOM
            # lattice the liveness fixpoint actually runs on.  Recording it
            # in only the first made an address register invisible to the
            # fixpoint, which is a read a proof may never miss; the hardware
            # probe in `$W/BF-probe` found it, and
            # `test_semantic_decoder.py` fixes it.
            #
            # `memory` additionally describes the ADDRESS ITSELF -- base,
            # index, scale, constant displacement, access width and whether
            # the form reads or writes the cell.  A register bijection never
            # reads it; the instruction-schedule certificate needs it to
            # discharge its memory-disambiguation obligation, and deriving it
            # here keeps one decoder authoritative for both.
            base_name = None
            index_name = None
            scale = 1
            absolute = False
            if rm == 4:
                require(cursor < length, f"{context}: instruction lacks SIB")
                sib_at = offset + cursor
                sib = encoded[cursor]
                cursor += 1
                base = sib & 7
                index = (sib >> 3) & 7
                scale = 1 << (sib >> 6)
                if not (mode == 0 and base == 5):
                    fields.append((sib_at, 0))
                    reads.add(names[base])
                    read_atoms |= _IA32_ATOMS_OF[names[base]]
                    base_name = names[base]
                else:
                    absolute = True
                if index != 4:
                    fields.append((sib_at, 3))
                    reads.add(names[index])
                    read_atoms |= _IA32_ATOMS_OF[names[index]]
                    index_name = names[index]
            elif not (mode == 0 and rm == 5):
                fields.append((modrm_at, 0))
                reads.add(names[rm])
                read_atoms |= _IA32_ATOMS_OF[names[rm]]
                base_name = names[rm]
            else:
                absolute = True
            displacement = 0
            absolute_operand = absolute
            if mode == 1:
                require(cursor < length,
                        f"{context}: instruction lacks its disp8")
                displacement_at = offset + cursor
                displacement_size = 1
                displacement = int.from_bytes(
                    encoded[cursor:cursor + 1], "little", signed=True)
            elif mode == 2 or absolute:
                require(cursor + 4 <= length,
                        f"{context}: instruction lacks its disp32")
                displacement_at = offset + cursor
                displacement_size = 4
                displacement = int.from_bytes(
                    encoded[cursor:cursor + 4], "little", signed=True)
            if form["rm_read"] or rm_write or form["x87"]:
                memory = {
                    "base": base_name, "index": index_name, "scale": scale,
                    "displacement": displacement, "absolute": absolute,
                    "width": max(width // 8, 1),
                    "read": bool(form["rm_read"]) or bool(form["x87"]),
                    "write": bool(rm_write),
                    # A ModRM operand's address IS derived, so it is never
                    # unknown; only a repeated string operation's is.
                    "unknown": False,
                }
        require(form["reg"] != "gpr" or not (form["reg_write"]
                                             and form["rm_write"]),
                f"{context}: instruction form writes two operands")
        encoding = {
            "modrm_at": modrm_at,
            "mode": mode,
            "rm": rm,
            "reg": register_field,
            "sib_at": sib_at,
            "displacement_at": displacement_at,
            "displacement_size": displacement_size,
            "absolute": absolute_operand,
        }
    target = None
    flow = form["flow"] if flow_override is None else flow_override
    if flow == "exit" and form["modrm"]:
        # A computed jump: no successor inside the body, and the maximally
        # conservative live-out already came from the form's ext_implicit.
        indirect = True
    if flow in ("jcc", "jmp", "call") and form["displacement"]:
        width_bytes = form["displacement"]
        displacement_at = offset + length - width_bytes
        row = (relocations or {}).get(displacement_at)
        external = (row is not None and row.get("width") == width_bytes)
        if external and flow == "jmp":
            # A relocated unconditional branch leaves this COMDAT.
            flow = "exit"
            reads = set(_IA32_EXTERNAL_TRANSFER_LIVE)
            writes = set()
            read_atoms = set(ia32_register_atoms(_IA32_EXTERNAL_TRANSFER_LIVE))
            write_atoms = set()
        elif external and flow == "jcc":
            raise ByteIdentityError(
                f"{context}: a relocated conditional branch is outside the "
                "register-bijection table")
        elif not external:
            relative = int.from_bytes(
                encoded[length - width_bytes:], "little", signed=True)
            target = offset + length + relative
        if flow == "call":
            symbol = row.get("target") if row is not None else None
            argument = (msvc_call_argument_registers(symbol)
                        if external else None)
            extra = (_IA32_CALL_CLOBBERED if argument is None else argument)
            reads |= extra
            read_atoms |= ia32_register_atoms(extra)
            target = None
    elif flow == "call":
        # An indirect call: the callee can never be named.
        reads |= _IA32_CALL_CLOBBERED
        read_atoms |= ia32_register_atoms(_IA32_CALL_CLOBBERED)
    if form["string_memory"] is not None:
        # The implicit span through ESI/EDI, whose extent is the runtime
        # count.  It is declared UNKNOWN with no base, no index and no
        # width, so any consumer that compares addresses refuses it.
        memory = {
            "base": None, "index": None, "scale": 1, "displacement": 0,
            "absolute": False, "width": 0,
            "read": form["string_memory"]["read"],
            "write": form["string_memory"]["write"],
            "unknown": True,
        }
    # The XOR-zero idiom is an exact, closed special case: `xor r, r` does not
    # read r, it defines it.  Recognising it is required for a sound liveness
    # answer, and it is recognised by the encoding, never by a heuristic.
    # It is admitted at 32 bits ONLY: `xor di, di` zeroes DI and leaves the
    # upper half of EDI exactly as it was, so it kills nothing and claiming
    # the whole register would be a false kill.
    if opcode in (0x31, 0x33) and form["modrm"] and width == 32:
        if (modrm_byte >> 6 == 3
                and (modrm_byte & 7) == ((modrm_byte >> 3) & 7)):
            zeroed = names[modrm_byte & 7]
            reads.discard(zeroed)
            writes.add(zeroed)
            read_atoms -= _IA32_ATOMS_OF[zeroed]
            write_atoms |= _IA32_ATOMS_OF[zeroed]
    return {
        "offset": offset, "length": length, "opcode": opcode,
        "fields": fields, "reads": frozenset(reads),
        "writes": frozenset(writes), "flow": flow, "target": target,
        "frozen": frozenset(frozen), "memory": memory,
        "encoding": encoding,
        "indirect": indirect,
        "read_atoms": frozenset(read_atoms),
        "write_atoms": frozenset(write_atoms),
    }


def decode_ia32_bijection_body(
    body: bytes, context: str, relocations: dict | None = None,
    code_length: int | None = None,
) -> list[dict]:
    """Decode a COMDAT body to exhaustion with the closed table.

    `code_length`, when given, is the pinned extent of the body's CODE: a
    COMDAT that ends in a compiler-emitted switch table carries data after
    its last instruction, and decoding that data as instructions would be
    nonsense.  The tail is never decoded, never rewritten, and is proved
    unreachable from the decoded control flow: the code must decode to
    exactly `code_length` with no straddling instruction, and its last
    instruction may not fall through into the tail.
    """
    require(isinstance(body, (bytes, bytearray)) and body,
            f"{context}: body is empty")
    body = bytes(body)
    limit = len(body) if code_length is None else code_length
    require(isinstance(limit, int) and not isinstance(limit, bool)
            and 0 < limit <= len(body),
            f"{context}: code length is out of range")
    code = body[:limit]
    instructions = []
    offset = 0
    while offset < len(code):
        instruction = decode_ia32_bijection_instruction(
            code, offset, f"{context} at {offset}", relocations)
        instructions.append(instruction)
        offset += instruction["length"]
    require(offset == len(code),
            f"{context}: body does not decode to exhaustion")
    if limit < len(body):
        require(instructions[-1]["flow"] in ("ret", "jmp", "exit"),
                f"{context}: code falls through into the body's data tail")
    starts = {item["offset"] for item in instructions}
    for item in instructions:
        if item["target"] is not None:
            require(item["target"] in starts,
                    f"{context}: branch at {item['offset']} does not target "
                    "an instruction boundary in this body")
    return instructions


def _ia32_backward_liveness(
    instructions: list[dict], successors: list[list[int]], context: str,
    blind: dict | None = None,
) -> list[frozenset]:
    """Backward atom liveness over a supplied control-flow graph.

    The lattice is the sub-register ATOM set, so a partial definition
    (`fnstsw ax`, `mov al, m`) kills exactly the bits it defines and no more.
    The fixpoint is monotone and bounded by the twenty atoms, so it
    terminates.  `blind`, when given, maps an instruction index to atoms
    subtracted from its READ set -- the way to ask "would this register still
    be live here if this particular consumer did not exist", which is how the
    web certificate proves a value has no consumer outside its own web.
    """
    blind = blind or {}
    live = [frozenset() for _ in instructions]
    for _ in range(len(instructions) * 20 + 20):
        changed = False
        for index in reversed(range(len(instructions))):
            item = instructions[index]
            out = frozenset().union(
                *[live[edge] for edge in successors[index]]) \
                if successors[index] else frozenset()
            reads = item["read_atoms"] - blind.get(index, frozenset())
            value = (out - item["write_atoms"]) | reads
            if value != live[index]:
                live[index] = value
                changed = True
        if not changed:
            break
    else:  # pragma: no cover - the lattice is finite and monotone
        raise ByteIdentityError(f"{context}: liveness did not converge")
    return live


def _ia32_live_out(live: list[frozenset], successors: list[list[int]],
                   index: int) -> frozenset:
    """The union of the live sets on an instruction's outgoing edges."""
    return frozenset().union(*[live[edge] for edge in successors[index]]) \
        if successors[index] else frozenset()


def _register_bijection_live_sets(
    instructions: list[dict], context: str,
) -> list[frozenset]:
    """Backward liveness over the body's own control-flow graph.

    Successors are the fall-through and the decoded branch target; `ret` has
    none and instead reads the ABI's live-out set, so the epilogue's `pop`s
    kill exactly the callee-saved registers they restore.
    """
    index_of = {item["offset"]: index for index, item in enumerate(
        instructions)}
    successors = []
    for index, item in enumerate(instructions):
        edges = []
        if item["flow"] in ("fall", "jcc", "call"):
            if index + 1 < len(instructions):
                edges.append(index + 1)
            else:
                require(item["flow"] != "fall",
                        f"{context}: body falls off its end")
        # `exit` is a relocated tail-jump out of this COMDAT: like `ret` it
        # has no successor inside the body and instead reads its live-out
        # set, which for an external transfer is every general register.
        if item["flow"] in ("jcc", "jmp"):
            edges.append(index_of[item["target"]])
        successors.append(edges)
    return _ia32_backward_liveness(instructions, successors, context), \
        successors


def apply_register_bijection(
    body: bytes, mapping: dict, region: tuple[int, int],
    relocation_offsets: frozenset, context: str,
    relocations: dict | None = None,
    code_length: int | None = None,
    internal_targets: frozenset | None = None,
) -> tuple[bytes, dict]:
    """Rewrite one region's general-register fields under a proved bijection.

    Every obligation this class rests on is checked here: total decode, closed
    forms, structural-register exclusion, relocation disjointness, the
    liveness proof for the region's boundary, and length preservation verified
    by re-decoding the image.
    """
    body = bytes(body)
    start, end = region
    instructions = decode_ia32_bijection_body(
        body, context, relocations, code_length)
    limit = len(body) if code_length is None else code_length
    boundaries = {item["offset"] for item in instructions}
    boundaries.add(limit)
    require(end <= limit,
            f"{context}: region reaches past the body's code")
    # A computed jump has no decodable successors, so the "control enters the
    # region only at its head" obligation cannot be discharged from the
    # decoded graph alone.  The relocated in-body label set -- every target a
    # relocation in this body names inside this same COMDAT -- closes it, and
    # it must be SUPPLIED: a body with a computed jump and no such set is
    # refused rather than proved on an incomplete graph.
    if any(item["indirect"] for item in instructions):
        require(internal_targets is not None,
                f"{context}: a computed jump requires the relocated in-body "
                "target set")
        entered = sorted(target for target in internal_targets
                         if start < target < end)
        require(not entered,
                f"{context}: a relocated in-body target at {entered[:1]} "
                "enters the region other than at its first instruction")
    require(start in boundaries and end in boundaries and start < end,
            f"{context}: region does not span whole instructions")
    numbers = {}
    for source, destination in mapping.items():
        require(source in _IA32_REGISTER_NUMBERS
                and destination in _IA32_REGISTER_NUMBERS,
                f"{context}: mapping names an unknown register")
        numbers[_IA32_REGISTER_NUMBERS[source]] = (
            _IA32_REGISTER_NUMBERS[destination])
    support = set(mapping) | set(mapping.values())
    require(len(set(mapping.values())) == len(mapping)
            and set(mapping.values()) == set(mapping),
            f"{context}: mapping is not a bijection of one register set")
    require(all(source != destination
                for source, destination in mapping.items()),
            f"{context}: mapping fixes a register it names")
    require(not (support & _IA32_STRUCTURAL_REGISTERS),
            f"{context}: mapping touches ESP or EBP, whose encodings carry "
            "ModRM/SIB structure")

    live, successors = _register_bijection_live_sets(instructions, context)
    inside = [item for item in instructions
              if start <= item["offset"] < end]
    require(inside, f"{context}: region contains no instruction")
    require(inside[-1]["offset"] + inside[-1]["length"] == end,
            f"{context}: region does not end on an instruction boundary")
    entry = instructions.index(inside[0])
    for item in inside:
        # A sub-register field names a general register but cannot carry
        # sigma's permutation (AL..BH number the low AND high bytes of only
        # four registers), so a frozen register inside the region is refused
        # rather than silently left unrewritten.
        blocked = support & set(item.get("frozen", frozenset()))
        require(not blocked,
                f"{context}: {sorted(blocked)} is named by a sub-register "
                f"field at {item['offset']} that sigma cannot rewrite")
    for index, item in enumerate(instructions):
        for edge in successors[index]:
            crosses_in = (not (start <= item["offset"] < end)
                          and start <= instructions[edge]["offset"] < end)
            if crosses_in:
                require(edge == entry,
                        f"{context}: control enters the region other than at "
                        "its first instruction")
    support_atoms = ia32_register_atoms(support)
    dead_in = support_atoms & set(live[entry])
    require(not dead_in,
            f"{context}: {_ia32_atom_registers(dead_in)} is live on entry "
            "to the region")
    for index, item in enumerate(instructions):
        if not (start <= item["offset"] < end):
            continue
        for edge in successors[index]:
            if start <= instructions[edge]["offset"] < end:
                continue
            leaking = support_atoms & set(live[edge])
            require(not leaking,
                    f"{context}: {_ia32_atom_registers(leaking)} is live on "
                    f"an edge leaving the region at {item['offset']}")
        if item["flow"] in ("ret", "exit"):
            leaking = support_atoms & set(item["read_atoms"])
            require(not leaking,
                    f"{context}: {_ia32_atom_registers(leaking)} is live at "
                    "the region's return")

    image = bytearray(body)
    rewritten = []
    for item in inside:
        for byte_index, shift in item["fields"]:
            value = (image[byte_index] >> shift) & 7
            if value not in numbers:
                continue
            require(byte_index not in relocation_offsets,
                    f"{context}: a rewritten byte overlaps a relocation")
            image[byte_index] = (
                (image[byte_index] & ~(7 << shift))
                | (numbers[value] << shift)
            ) & 0xFF
            rewritten.append(byte_index)
    require(rewritten, f"{context}: the bijection rewrites nothing")
    image = bytes(image)
    require(len(image) == len(body),
            f"{context}: the image changed the body length")
    image_instructions = decode_ia32_bijection_body(
        image, f"{context} image", relocations, code_length)
    require(
        [(item["offset"], item["length"]) for item in image_instructions]
        == [(item["offset"], item["length"]) for item in instructions],
        f"{context}: the image changed an instruction boundary",
    )
    for left, right in zip(image_instructions, instructions):
        # `+r` forms encode their register in the opcode's low three bits, so
        # the bijection legitimately moves those three bits and nothing else.
        # A form the ONE-BYTE table does not name -- a repeated string
        # operation, whose opcode lives in its own prefixed table -- has no
        # `+r` field at all, so it takes the STRICTER full-opcode mask.  It
        # must never index a missing entry: that is a crash, not a proof.
        form = _bijection_form_for(right["opcode"])
        opreg = form is not None and form["opreg"] is not None
        mask = 0xF8 if opreg else 0xFFFF
        require(
            left["opcode"] & mask == right["opcode"] & mask
            and left["flow"] == right["flow"]
            and left["target"] == right["target"],
            f"{context}: the image changed an opcode or a branch",
        )
    for left, right in zip(image_instructions, instructions):
        expected_reads = frozenset(
            mapping.get(name, name) if start <= right["offset"] < end
            else name for name in right["reads"])
        expected_writes = frozenset(
            mapping.get(name, name) if start <= right["offset"] < end
            else name for name in right["writes"])
        require(left["reads"] == expected_reads
                and left["writes"] == expected_writes,
                f"{context}: the image's operand set at {right['offset']} is "
                "not the bijection's image")
    changed = sorted({index for index in range(len(body))
                      if body[index] != image[index]})
    require(changed == sorted(set(rewritten)),
            f"{context}: the image changed a byte the bijection did not name")
    return image, {
        "rewritten_offsets": changed,
        "region_instruction_count": len(inside),
        "instruction_count": len(instructions),
        "code_length": limit,
    }


def _codeview_register_field(record: dict, context: str) -> int:
    """The offset of one S_REGISTER record's two-byte register field."""
    field_at = record["offset"] + 4 + 2
    require(field_at + 2 <= record["offset"] + record["size"],
            f"{context}: S_REGISTER record has no register field")
    return field_at


def _codeview_register_name(stream: bytes, field_at: int, context: str) -> str:
    number = int.from_bytes(stream[field_at:field_at + 2], "little")
    name = next((key for key, value in CODEVIEW_X86_REGISTER_NUMBERS.items()
                 if value == number), None)
    require(name is not None,
            f"{context}: S_REGISTER names a non-general register")
    return name


def apply_codeview_register_bijection(
    stream: bytes, mapping: dict, declared: list[dict], context: str,
    donor_stream: bytes | None = None,
) -> bytes:
    """Map the S_REGISTER records that name a bijected register.

    Obligation 9.  The stream is parsed to exhaustion before and after with
    the module's closed record table, only the two-byte register field of a
    declared record changes, and the resulting record identity/size list must
    be unchanged -- so debug information continues to name the register the
    installed code actually uses.

    `donor_stream`, when given, is the DONOR's own `.debug$S`.  It is needed
    whenever the donor reaches a different compiler state, because then the
    installed code is the donor's OUTSIDE the region too and the seed's
    debug information would name the seed's register allocation for locals
    the composition never installs.  In that mode the two streams are first
    proved to describe the same debug structure -- identical record list, and
    byte differences confined to S_REGISTER register fields and to the name
    bytes of object-local `$L`/`$T` symbols, whose seed names the composition
    keeps because it keeps the seed's symbol table -- and then every
    S_REGISTER record takes the DONOR's register, with sigma applied to
    exactly the declared records.  Declaring a record is the statement that
    the local it names lives inside the region; a local outside it keeps the
    register the installed code actually uses, which is the donor's.
    """
    records = parse_codeview_symbol_stream(stream, context)
    image = bytearray(stream)
    if donor_stream is None:
        seen = []
        for record in records:
            if record["type"] != CODEVIEW_REGISTER_RECORD_TYPE:
                continue
            field_at = _codeview_register_field(record, context)
            name = _codeview_register_name(image, field_at, context)
            if name not in mapping:
                continue
            seen.append({
                "name": record["name"], "record_offset": record["offset"],
                "donor_register": name, "image_register": mapping[name],
            })
            image[field_at:field_at + 2] = CODEVIEW_X86_REGISTER_NUMBERS[
                mapping[name]].to_bytes(2, "little")
        require(seen == declared,
                f"{context}: the S_REGISTER map differs from its declaration")
    else:
        donor_records = parse_codeview_symbol_stream(
            donor_stream, f"{context} donor")
        require(
            [(item["offset"], item["size"], item["type"])
             for item in donor_records]
            == [(item["offset"], item["size"], item["type"])
                for item in records],
            f"{context}: the donor's debug$S record list differs from the "
            "seed's",
        )
        movable = set()
        for seed_record, donor_record in zip(records, donor_records):
            if seed_record["type"] == CODEVIEW_REGISTER_RECORD_TYPE:
                field_at = _codeview_register_field(seed_record, context)
                movable.update((field_at, field_at + 1))
                continue
            if seed_record["name"] == donor_record["name"]:
                continue
            kind = local_symbol_kind(seed_record["name"])
            require(kind is not None
                    and kind == local_symbol_kind(donor_record["name"])
                    and len(seed_record["name"])
                    == len(donor_record["name"]),
                    f"{context}: the donor's debug$S renames a non-local "
                    "symbol")
            name_at = (seed_record["offset"] + 4
                       + CODEVIEW_SYMBOL_NAME_OFFSETS[seed_record["type"]]
                       + 1)
            movable.update(range(name_at,
                                 name_at + len(seed_record["name"])))
        differing = {index for index in range(len(stream))
                     if stream[index] != donor_stream[index]}
        require(differing <= movable,
                f"{context}: the donor's debug$S differs outside its "
                "S_REGISTER fields and object-local names")
        for seed_record in records:
            if seed_record["type"] != CODEVIEW_REGISTER_RECORD_TYPE:
                continue
            field_at = _codeview_register_field(seed_record, context)
            name = _codeview_register_name(donor_stream, field_at, context)
            image[field_at:field_at + 2] = CODEVIEW_X86_REGISTER_NUMBERS[
                name].to_bytes(2, "little")
        offsets = [item["record_offset"] for item in declared]
        require(len(set(offsets)) == len(offsets),
                f"{context}: the S_REGISTER map declares a record twice")
        by_offset = {item["offset"]: item for item in records}
        for item in declared:
            record = by_offset.get(item["record_offset"])
            require(record is not None
                    and record["type"] == CODEVIEW_REGISTER_RECORD_TYPE
                    and record["name"] == item["name"],
                    f"{context}: the S_REGISTER map names no such record")
            field_at = _codeview_register_field(record, context)
            name = _codeview_register_name(donor_stream, field_at, context)
            require(name == item["donor_register"]
                    and mapping.get(name) == item["image_register"],
                    f"{context}: the S_REGISTER map differs from its "
                    "declaration")
            image[field_at:field_at + 2] = CODEVIEW_X86_REGISTER_NUMBERS[
                item["image_register"]].to_bytes(2, "little")
    image = bytes(image)
    require(
        [(item["offset"], item["size"], item["type"], item["name"])
         for item in parse_codeview_symbol_stream(
             image, f"{context} image")]
        == [(item["offset"], item["size"], item["type"], item["name"])
            for item in records],
        f"{context}: the mapped stream is not the same record list",
    )
    return image


def validate_register_bijection_reencoding(
    value: object, context: str, preimage_length: int, image_length: int,
) -> dict:
    """Validate one re-encoding register-bijection declaration.

    Every quantity the composer will MEASURE is declared here first, so a
    manifest that disagrees with the objects refuses before anything is
    installed.  The regions are the only free parameters; growth, branch
    repairs, reseats and the boundary-derived debug ranges are consequences,
    and pinning them is what makes a silent change to the primitive visible.
    """
    require(isinstance(value, dict), f"{context} must be an object")
    exact_audit_keys(value, {
        "kind", "regions", "expected_fpo_record", "expected_growth",
        "expected_branch_repairs", "expected_relocation_reseat",
        "expected_rewritten_field_offsets",
        "expected_region_instruction_counts", "expected_instruction_count",
        "expected_image_code_length", "expected_procedure_range",
        "expected_carried_code_symbols", "authenticity_rationale",
        "expected_code_length", "expected_internal_relocation_targets",
    }, context, optional={"expected_code_length",
                          "expected_internal_relocation_targets"})
    require(value.get("kind") == REGISTER_BIJECTION_REENCODING_KIND,
            f"{context}.kind differs")
    regions = value.get("regions")
    require(isinstance(regions, list) and 1 <= len(regions) <= 8,
            f"{context}.regions is invalid")
    normalized = []
    previous_end = 0
    names_ebp = False
    for index, item in enumerate(regions):
        item_context = f"{context}.regions[{index}]"
        require(isinstance(item, dict), f"{item_context} must be an object")
        exact_keys(item, {"start", "end", "mapping"}, item_context)
        start = require_exact_int(item.get("start"),
                                  f"{item_context}.start",
                                  minimum=1, maximum=preimage_length - 1)
        end = require_exact_int(item.get("end"), f"{item_context}.end",
                                minimum=2, maximum=preimage_length - 1)
        require(start >= previous_end and start < end,
                f"{item_context}: regions are unsorted, empty or overlapping")
        previous_end = end
        mapping = item.get("mapping")
        require(isinstance(mapping, dict) and 2 <= len(mapping) <= 8
                and all(isinstance(key, str) and isinstance(entry, str)
                        and key in _IA32_REGISTER_NUMBERS
                        and entry in _IA32_REGISTER_NUMBERS
                        for key, entry in mapping.items()),
                f"{item_context}.mapping is invalid")
        require(set(mapping) == set(mapping.values())
                and len(set(mapping.values())) == len(mapping)
                and all(key != entry for key, entry in mapping.items()),
                f"{item_context}.mapping is not a fixed-point-free bijection")
        # EBP is the whole point of this class and is admitted only against
        # the FPO record proved below; ESP is refused here as it is in the
        # parent, because a rename to or from it is not an encoding change.
        require("esp" not in set(mapping) | set(mapping.values()),
                f"{item_context}.mapping touches ESP")
        if "ebp" in set(mapping) | set(mapping.values()):
            names_ebp = True
        normalized.append({"start": start, "end": end,
                           "mapping": dict(sorted(mapping.items()))})
    require(names_ebp,
            f"{context}: no region names EBP, so this is an ordinary "
            f"{REGISTER_BIJECTION_CLASS} and must be declared as one")
    record = value.get("expected_fpo_record")
    require(isinstance(record, dict)
            and set(record) == FPO_RECORD_KEYS - {"raw_sha256"},
            f"{context}.expected_fpo_record is invalid")
    require(record.get("cbFrame") == FPO_FRAME_KIND_FPO
            and record.get("fHasSEH") == 0,
            f"{context}.expected_fpo_record does not declare a "
            "frame-pointer-free, SEH-free frame")
    growth = value.get("expected_growth")
    require(isinstance(growth, list) and growth and len(growth) <= 64
            and all(isinstance(row, list) and len(row) == 4
                    and all(type(entry) is int for entry in row)
                    and 0 <= row[0] < preimage_length
                    and 0 <= row[1] < image_length
                    and 1 <= row[2] <= 15 and 1 <= row[3] <= 15
                    and abs(row[3] - row[2]) == 1
                    for row in growth)
            and [row[0] for row in growth] == sorted({row[0]
                                                      for row in growth}),
            f"{context}.expected_growth is invalid")
    require(image_length - preimage_length
            == sum(row[3] - row[2] for row in growth),
            f"{context}.expected_growth does not account for the image's "
            "length change")
    repairs = value.get("expected_branch_repairs")
    require(isinstance(repairs, list) and len(repairs) <= 256
            and repairs == sorted(set(repairs))
            and all(type(entry) is int and 0 <= entry < image_length
                    for entry in repairs),
            f"{context}.expected_branch_repairs is invalid")
    reseat = value.get("expected_relocation_reseat")
    require(isinstance(reseat, list) and len(reseat) <= 256
            and all(isinstance(pair, list) and len(pair) == 2
                    and all(type(entry) is int for entry in pair)
                    and 0 <= pair[0] < preimage_length
                    and 0 <= pair[1] < image_length
                    and pair[0] != pair[1]
                    for pair in reseat)
            and [pair[0] for pair in reseat]
            == sorted({pair[0] for pair in reseat})
            and len({pair[1] for pair in reseat}) == len(reseat),
            f"{context}.expected_relocation_reseat is invalid")
    fields = value.get("expected_rewritten_field_offsets")
    require(isinstance(fields, list) and fields
            and fields == sorted(set(fields))
            and all(type(entry) is int
                    and any(item["start"] <= entry < item["end"]
                            for item in normalized)
                    for entry in fields),
            f"{context}.expected_rewritten_field_offsets is invalid")
    counts = value.get("expected_region_instruction_counts")
    total = require_exact_int(value.get("expected_instruction_count"),
                              f"{context}.expected_instruction_count",
                              minimum=2)
    require(isinstance(counts, list) and len(counts) == len(normalized)
            and all(type(entry) is int and entry >= 1 for entry in counts)
            and sum(counts) <= total,
            f"{context}.expected_region_instruction_counts is invalid")
    require(require_exact_int(value.get("expected_image_code_length"),
                              f"{context}.expected_image_code_length",
                              minimum=1) <= image_length,
            f"{context}.expected_image_code_length exceeds the image")
    procedure = value.get("expected_procedure_range")
    require(isinstance(procedure, list) and len(procedure) == 3
            and all(type(entry) is int for entry in procedure)
            and procedure[0] == image_length
            and 0 <= procedure[1] <= procedure[2] < image_length,
            f"{context}.expected_procedure_range is invalid")
    carried = value.get("expected_carried_code_symbols")
    require(isinstance(carried, list) and len(carried) <= 64
            and all(isinstance(row, list) and len(row) == 3
                    and isinstance(row[0], str) and row[0]
                    and type(row[1]) is int and type(row[2]) is int
                    and 0 <= row[1] < preimage_length
                    and 0 <= row[2] < image_length
                    for row in carried),
            f"{context}.expected_carried_code_symbols is invalid")
    targets = value.get("expected_internal_relocation_targets")
    if targets is not None:
        require(isinstance(targets, list)
                and targets == sorted(set(targets))
                and all(type(entry) is int and 0 <= entry < preimage_length
                        for entry in targets),
                f"{context}.expected_internal_relocation_targets is invalid")
    code_length = value.get("expected_code_length")
    if code_length is not None:
        require_exact_int(code_length, f"{context}.expected_code_length",
                          minimum=1, maximum=preimage_length)
    normalized_value = {
        **value,
        "regions": normalized,
        "expected_fpo_record": dict(sorted(record.items())),
    }
    return normalized_value


def validate_register_bijection(
    value: object, context: str, body_length: int,
) -> dict:
    """Validate one register-bijection certificate declaration."""
    require(isinstance(value, dict), f"{context} must be an object")
    exact_audit_keys(value, {
        "kind", "mapping", "region_start", "region_end",
        "expected_region_instruction_count", "expected_instruction_count",
        "expected_rewritten_offsets", "debug_s_register_map",
        "expected_seed_debug_s_sha256", "expected_image_debug_s_sha256",
        "authenticity_rationale",
        "expected_code_length", "expected_internal_relocation_targets",
        "expected_rewritten_offsets_restoring_seed",
    }, context, optional={"expected_code_length",
                          "expected_internal_relocation_targets",
                          "expected_rewritten_offsets_restoring_seed"})
    require(value.get("kind") == REGISTER_BIJECTION_KIND,
            f"{context}.kind differs")
    mapping = value.get("mapping")
    require(isinstance(mapping, dict) and 2 <= len(mapping) <= 8
            and all(isinstance(key, str) and isinstance(item, str)
                    and key in _IA32_REGISTER_NUMBERS
                    and item in _IA32_REGISTER_NUMBERS
                    for key, item in mapping.items()),
            f"{context}.mapping is invalid")
    require(set(mapping) == set(mapping.values())
            and len(set(mapping.values())) == len(mapping)
            and all(key != item for key, item in mapping.items()),
            f"{context}.mapping is not a fixed-point-free bijection")
    require(not (set(mapping) & _IA32_STRUCTURAL_REGISTERS),
            f"{context}.mapping touches ESP or EBP")
    start = require_exact_int(value.get("region_start"),
                              f"{context}.region_start",
                              minimum=1, maximum=body_length - 1)
    end = require_exact_int(value.get("region_end"),
                            f"{context}.region_end",
                            minimum=2, maximum=body_length - 1)
    require(start < end,
            f"{context}: region is empty")
    require(
        require_exact_int(value.get("expected_region_instruction_count"),
                          f"{context}.expected_region_instruction_count",
                          minimum=1)
        <= require_exact_int(value.get("expected_instruction_count"),
                             f"{context}.expected_instruction_count",
                             minimum=2),
        f"{context}: region instruction count exceeds the body's",
    )
    offsets = value.get("expected_rewritten_offsets")
    require(isinstance(offsets, list) and offsets
            and offsets == sorted(set(offsets))
            and all(type(offset) is int and start <= offset < end
                    for offset in offsets),
            f"{context}.expected_rewritten_offsets is invalid")
    declared = value.get("debug_s_register_map")
    require(isinstance(declared, list) and len(declared) <= 8,
            f"{context}.debug_s_register_map is invalid")
    normalized_map = []
    for index, item in enumerate(declared):
        item_context = f"{context}.debug_s_register_map[{index}]"
        require(isinstance(item, dict), f"{item_context} must be an object")
        exact_audit_keys(item, {
            "name", "record_offset", "donor_register", "image_register",
        }, item_context)
        require(isinstance(item.get("name"), str) and item["name"],
                f"{item_context}.name is invalid")
        require(item.get("donor_register") in mapping
                and mapping[item["donor_register"]] == item.get(
                    "image_register"),
                f"{item_context} is not the declared mapping")
        normalized_map.append({
            "name": item["name"],
            "record_offset": require_exact_int(
                item.get("record_offset"), f"{item_context}.record_offset",
                minimum=0),
            "donor_register": item["donor_register"],
            "image_register": item["image_register"],
        })
    rationale = value.get("authenticity_rationale")
    require(isinstance(rationale, str) and len(rationale) >= 40,
            f"{context}.authenticity_rationale is missing")
    # A COMDAT that ends in a compiler-emitted switch table carries DATA
    # after its last instruction.  `expected_code_length` pins where the code
    # ends; the tail is never decoded and never rewritten, and the decoder
    # proves the code cannot fall through into it.  The in-body relocated
    # target set is what closes the "control enters the region only at its
    # head" obligation for a computed jump.
    code_length = value.get("expected_code_length")
    if code_length is not None:
        code_length = require_exact_int(
            code_length, f"{context}.expected_code_length",
            minimum=2, maximum=body_length)
        require(end <= code_length,
                f"{context}: region reaches past the declared code length")
    # A rewritten byte whose image happens to equal the SEED's own byte is
    # not a changed byte of the composition.  That can only happen where the
    # donor already differed from the seed, so the set is pinned exactly
    # rather than tolerated: the composer measures it against the bodies.
    restoring = value.get("expected_rewritten_offsets_restoring_seed")
    if restoring is not None:
        require(isinstance(restoring, list)
                and restoring == sorted(set(restoring))
                and set(restoring) <= set(offsets),
                f"{context}.expected_rewritten_offsets_restoring_seed "
                "is invalid")
    targets = value.get("expected_internal_relocation_targets")
    if targets is not None:
        require(isinstance(targets, list)
                and targets == sorted(set(targets))
                and all(type(item) is int and 0 <= item < body_length
                        for item in targets),
                f"{context}.expected_internal_relocation_targets is invalid")
        require(not any(start < item < end for item in targets),
                f"{context}: a relocated in-body target enters the region")
    normalized = {
        "kind": REGISTER_BIJECTION_KIND,
        "mapping": dict(sorted(mapping.items())),
        "region_start": start, "region_end": end,
        "expected_region_instruction_count":
            value["expected_region_instruction_count"],
        "expected_instruction_count": value["expected_instruction_count"],
        "expected_rewritten_offsets": list(offsets),
        "debug_s_register_map": normalized_map,
        "expected_seed_debug_s_sha256": require_sha(
            value.get("expected_seed_debug_s_sha256"),
            f"{context}.expected_seed_debug_s_sha256"),
        "expected_image_debug_s_sha256": require_sha(
            value.get("expected_image_debug_s_sha256"),
            f"{context}.expected_image_debug_s_sha256"),
        "authenticity_rationale": rationale,
    }
    if code_length is not None:
        normalized["expected_code_length"] = code_length
    if targets is not None:
        normalized["expected_internal_relocation_targets"] = list(targets)
    if restoring is not None:
        normalized["expected_rewritten_offsets_restoring_seed"] = list(
            restoring)
    return normalized


def compose_retail_exact_register_bijection(
    seed_bytes: bytes,
    donor_bytes: bytes,
    function: dict,
    retail_body: bytes,
) -> tuple[bytes, dict]:
    """Install sigma(donor body) after proving it is retail's own code.

    See the class comment above: this is a certificate.  The donor is an
    ordinary, census-pinned carrier compile of the same translation unit; the
    bijection is proved sound against the body's own control flow; and the
    result is refused unless it equals the pinned retail oracle under the
    relocation mask.  Body installation itself is delegated, unchanged, to the
    equal-body primitive, so output conservation is proved by the same code
    every other equal-body class uses.
    """
    require(function.get("splice_class") == REGISTER_BIJECTION_CLASS,
            "splice class is not retail_exact_register_bijection")
    require("target_source_refactor" not in function,
            "register-bijection functions carry no source refactor")
    require(isinstance(retail_body, (bytes, bytearray)) and retail_body,
            "retail oracle body is missing")
    spec = function["register_bijection"]
    seed = CoffObject(seed_bytes)
    donor = CoffObject(donor_bytes)
    mangled = function["mangled"]
    sp = seed.function_section(mangled)
    dp = donor.function_section(mangled)
    require(sp["number"] == dp["number"]
            == function["expected_section_number"],
            "register-bijection target section seat changed")
    require(len(seed.sections) == len(donor.sections)
            == function["expected_section_count"],
            "register-bijection global section count changed")
    seed_functions = function_multiset(seed)
    donor_functions = function_multiset(donor)
    require(seed_functions == donor_functions
            and sum(seed_functions.values())
            == function["expected_function_count"],
            "register-bijection donor function set differs")
    seed_comdats = comdat_primary_identity_multiset(seed)
    donor_comdats = comdat_primary_identity_multiset(donor)
    require(seed_comdats == donor_comdats
            and sum(seed_comdats.values())
            == function["expected_comdat_count"],
            "register-bijection donor COMDAT identity set differs")
    require(
        sp["raw_size"] == dp["raw_size"] == function["expected_body_length"]
        and sp["relocation_count"] == dp["relocation_count"]
        == function["expected_relocation_count"]
        and sp["line_count"] == function["expected_seed_line_count"]
        and dp["line_count"] == function["expected_donor_line_count"]
        and sp["name"] == dp["name"]
        and sp["characteristics"] == dp["characteristics"]
        == function["expected_characteristics"],
        "register-bijection target header/count pins changed",
    )
    require(
        section_definitions(seed)[sp["number"]]["selection"]
        == section_definitions(donor)[dp["number"]]["selection"]
        == function["expected_selection"],
        "register-bijection COMDAT selection changed",
    )
    expected_closure = tuple(function["expected_closure"])
    # Obligation 10.  The pin is checked against BOTH objects first, so the
    # delegate below is a function of the pin alone.
    require(_comdat_child_closure(seed, sp)
            == _comdat_child_closure(donor, dp)
            == (len(expected_closure), expected_closure),
            "register-bijection target closure changed")
    require(list(expected_closure) in (REGISTER_BIJECTION_FPO_CLOSURE,
                                       REGISTER_BIJECTION_EH_CLOSURE),
            "register-bijection closure pin names no installation delegate")
    delegate = register_bijection_delegate(
        function["expected_closure"], function["expected_code_renames"],
        function.get("expected_relocation_moves"))
    require(instruction_mosaic_metadata_sha256(seed, sp)
            == function["expected_seed_metadata_sha256"]
            and instruction_mosaic_metadata_sha256(donor, dp)
            == function["expected_donor_metadata_sha256"],
            "register-bijection metadata differs from its pin")
    seed_body = coff_body(seed, sp)
    donor_body = coff_body(donor, dp)
    require(sha256_bytes(seed_body) == function["expected_seed_body_sha256"]
            and sha256_bytes(donor_body)
            == function["expected_donor_body_sha256"],
            "register-bijection seed/donor body differs from its pin")
    seed_rows = detailed_relocations(seed, sp)
    donor_rows = detailed_relocations(donor, dp)
    if (register_bijection_delegate(
            function["expected_closure"], function["expected_code_renames"],
            function.get("expected_relocation_moves"))
            == "equal_body_eh_reloc_layout"):
        # The donor's relocated operands sit at its OWN offsets, so the two
        # tables pair by ordinal, not by offset.  The classification is the
        # delegate's own: only an object-local $L/$T may be renamed, and its
        # target must be structurally identical in both objects.  Each rename
        # is pinned at the offset the composition will install it at.
        require(len(seed_rows) == len(donor_rows),
                "register-bijection donor relocation count differs")
        code_renames = []
        for left, right in zip(seed_rows, donor_rows):
            if left["target"] == right["target"]:
                continue
            kind = local_symbol_kind(left["target"])
            require(kind is not None
                    and kind == local_symbol_kind(right["target"])
                    and all(left["target_" + field] == right["target_" + field]
                            for field in ("section", "value", "type",
                                          "storage")),
                    "register-bijection donor renames a non-local relocation")
            code_renames.append((right["offset"], kind))
    else:
        code_renames = require_instruction_mosaic_semantic_relocations(
            seed, sp, donor, dp, "register-bijection code")
    require([[offset, kind] for offset, kind in code_renames]
            == function["expected_code_renames"],
            "register-bijection code rename set changed")
    # Each declared rename pins its EXACT symbol pair.  The delegate proves
    # the pair is object-local and structurally identical; this pins WHICH
    # pair, so a different rename at the same offset refuses.
    seed_targets = {right["offset"]: left["target"]
                    for left, right in zip(seed_rows, donor_rows)}
    donor_targets = {row["offset"]: row["target"] for row in donor_rows}
    require([[offset, seed_targets.get(offset), donor_targets.get(offset)]
             for offset, _ in code_renames]
            == function.get("expected_code_rename_symbols", []),
            "register-bijection code rename symbol pair changed")
    require(len(seed_rows) == len(donor_rows)
            and [(row["type"], row["addend"]) for row in seed_rows]
            == [(row["type"], row["addend"]) for row in donor_rows],
            "register-bijection donor relocation layout differs from the seed")
    # A donor that reaches a different compiler state may also SCHEDULE its
    # instructions differently, which moves the operands its relocations
    # cover.  The moves are pinned here and the `equal_body_eh_reloc_layout`
    # delegate re-proves them: the seed's own relocation RECORDS take the
    # donor's offsets, so the installed table is the seed's symbols at the
    # donor's operands.
    moves = [[left["offset"], right["offset"]]
             for left, right in zip(seed_rows, donor_rows)
             if left["offset"] != right["offset"]]
    require(moves == (function.get("expected_relocation_moves") or []),
            "register-bijection relocation move set changed")
    # The callee-argument model and the external-tail-jump model read the
    # INSTALLED relocation table -- the seed's symbols at the operand offsets
    # the composition will actually carry: the callee that will execute is
    # the seed's, whatever the donor compile happened to name, and the
    # operand it covers is the donor body's.  REL32 is the only type a call
    # or branch displacement can carry, so the seed and the donor must name
    # the same symbol there; DIR32 rows may legitimately differ in
    # compiler-generated label numbering (`$Lnnnnn` jump-table labels), which
    # no model reads.
    require([row["target"] for row in seed_rows if row["type"] == 0x0014]
            == [row["target"] for row in donor_rows if row["type"] == 0x0014],
            "register-bijection donor call/branch relocation targets differ "
            "from the seed")
    installed_rows = [
        {**left, "offset": right["offset"]}
        for left, right in zip(seed_rows, donor_rows)]
    relocation_offsets = frozenset(
        row["offset"] + byte
        for row in installed_rows for byte in range(row["width"]))
    relocation_symbols = {
        row["offset"]: {"width": row["width"], "target": row["target"]}
        for row in installed_rows}
    # Every label this body's own relocations name inside this same COMDAT.
    # A computed jump can reach only these, so this set is what discharges
    # the "control enters the region only at its head" obligation for one.
    internal_targets = frozenset(
        row["target_value"] for row in donor_rows
        if row["target_section"] == dp["number"])
    declared_targets = spec.get("expected_internal_relocation_targets")
    if declared_targets is not None:
        require(sorted(internal_targets) == declared_targets,
                "register-bijection in-body relocated target set changed")

    image, proof = apply_register_bijection(
        donor_body, spec["mapping"],
        (spec["region_start"], spec["region_end"]),
        relocation_offsets, "register-bijection image",
        relocation_symbols, spec.get("expected_code_length"),
        internal_targets,
    )
    require(proof["code_length"]
            == (spec.get("expected_code_length") or len(donor_body)),
            "register-bijection code length differs from its pin")
    require(proof["rewritten_offsets"] == spec["expected_rewritten_offsets"]
            and proof["region_instruction_count"]
            == spec["expected_region_instruction_count"]
            and proof["instruction_count"]
            == spec["expected_instruction_count"],
            "register-bijection image differs from its declaration")
    require(donor_body[:spec["region_start"]] == image[:spec["region_start"]]
            and donor_body[spec["region_end"]:] == image[spec["region_end"]:],
            "register-bijection changed the prologue or epilogue")
    require(sorted(offset for offset in proof["rewritten_offsets"]
                   if seed_body[offset] == image[offset])
            == (spec.get("expected_rewritten_offsets_restoring_seed") or []),
            "register-bijection seed-restoring rewrite set changed")
    require(sha256_bytes(image) == function["expected_body_sha256"],
            "register-bijection image differs from its pin")
    require(image != donor_body,
            "register-bijection image does not move the donor body")

    pinned_length = function["retail_oracle"]["length"]
    require(len(retail_body) == pinned_length == len(image),
            "register-bijection retail length changed")
    semantic_detail = require_retail_relocation_oracle(
        installed_rows, bytes(retail_body),
        int(function["retail_oracle"]["address"], 16),
        function["retail_relocations"],
        "register-bijection retail relocation oracle",
    )
    masked_image = bytearray(image)
    masked_retail = bytearray(retail_body)
    for row in installed_rows:
        start, width = row["offset"], row["width"]
        masked_image[start:start + width] = b"\0" * width
        masked_retail[start:start + width] = b"\0" * width
    differing = sum(left != right
                    for left, right in zip(masked_image, masked_retail))
    require(differing == 0,
            f"register-bijection output is not retail-exact: {differing} "
            "byte(s) differ under the relocation mask")

    # The image is installed through the unchanged equal-body primitive by
    # handing it the authenticated donor object carrying the proved image.
    derived = bytearray(donor_bytes)
    derived[dp["raw_offset"]:dp["raw_offset"] + dp["raw_size"]] = image
    derived = bytes(derived)
    effective = {
        "mangled": mangled,
        "splice_class": delegate,
        "expected_body_length": function["expected_body_length"],
        "expected_body_sha256": function["expected_body_sha256"],
        "expected_changed_offsets": function["expected_changed_offsets"],
    }
    if delegate == "equal_body_eh_structural_local":
        effective["expected_code_renames"] = function["expected_code_renames"]
        effective["expected_xdata_rename_offsets"] = function[
            "expected_xdata_rename_offsets"]
    elif delegate == "equal_body_eh_reloc_layout":
        effective["expected_relocation_moves"] = function[
            "expected_relocation_moves"]
        effective["expected_xdata_rename_offsets"] = function[
            "expected_xdata_rename_offsets"]
    composed, detail = compose_equal_body_comdat(seed_bytes, derived, effective)

    checked = CoffObject(composed)
    cp = checked.function_section(mangled)
    require(coff_body(checked, cp) == image,
            "register-bijection composed body differs from the image")
    # The installed table is the SEED's records at the operands the donor
    # body actually carries: the same symbol indices in the same order,
    # moved only where the pinned move set says so.
    composed_rows = detailed_relocations(checked, cp)
    require(composed_rows == installed_rows
            and [row["symbol_index"] for row in composed_rows]
            == [row["symbol_index"] for row in seed_rows]
            and _coff_table_bytes(checked, cp, "lines")
            == _coff_table_bytes(seed, sp, "lines"),
            "register-bijection output changed seed relocation/line bytes")

    debug_child = _comdat_child(checked, cp, ".debug$S")
    debug_stream = coff_body(checked, debug_child)
    require(sha256_bytes(debug_stream)
            == spec["expected_seed_debug_s_sha256"],
            "register-bijection debug$S differs from its pin")
    donor_debug = None
    if delegate == "equal_body_eh_reloc_layout":
        # The donor reached a different compiler state, so the installed code
        # is its own outside the region too and its debug$S is the one that
        # describes the installed body.
        donor_debug = bytes(coff_body(
            donor, _comdat_child(donor, dp, ".debug$S")))
    debug_image = apply_codeview_register_bijection(
        debug_stream, spec["mapping"], spec["debug_s_register_map"],
        "register-bijection debug$S", donor_debug,
    )
    require(sha256_bytes(debug_image)
            == spec["expected_image_debug_s_sha256"],
            "register-bijection mapped debug$S differs from its pin")
    composed = bytearray(composed)
    composed[debug_child["raw_offset"]:
             debug_child["raw_offset"] + debug_child["raw_size"]] = debug_image
    composed = bytes(composed)
    final = CoffObject(composed)
    fp = final.function_section(mangled)
    require(coff_body(final, fp) == image,
            "register-bijection output changed the installed body")
    for child_name in expected_closure:
        if child_name == ".debug$S":
            continue        # the one child this class maps, pinned above
        require(coff_body(final, _comdat_child(final, fp, child_name))
                == coff_body(seed, _comdat_child(seed, sp, child_name)),
                f"register-bijection output changed its {child_name} child")
    allowed = set(range(sp["raw_offset"], sp["raw_offset"] + sp["raw_size"]))
    allowed |= set(range(debug_child["raw_offset"],
                         debug_child["raw_offset"] + debug_child["raw_size"]))
    if delegate == "equal_body_eh_reloc_layout":
        # The delegate gives the seed's own relocation RECORDS the donor's
        # operand offsets.  Only the 4-byte offset field of a record the
        # pinned move set names may change, and nothing else in the table:
        # the symbol index and the type keep the seed's bytes.
        moving = [ordinal for ordinal, (left, right)
                  in enumerate(zip(seed_rows, donor_rows))
                  if left["offset"] != right["offset"]]
        allowed |= {sp["relocation_offset"] + ordinal * 10 + byte
                    for ordinal in moving for byte in range(4)}
    require({index for index in range(len(seed_bytes))
             if seed_bytes[index] != composed[index]} <= allowed,
            "register-bijection changed bytes outside its own COMDAT")
    return composed, {
        **detail,
        "splice_class": REGISTER_BIJECTION_CLASS,
        "register_bijection": dict(sorted(spec["mapping"].items())),
        "region": [spec["region_start"], spec["region_end"]],
        "rewritten_offsets": proof["rewritten_offsets"],
        "region_instruction_count": proof["region_instruction_count"],
        "instruction_count": proof["instruction_count"],
        "debug_s_register_map": spec["debug_s_register_map"],
        "retail_exact": True,
        **semantic_detail,
    }


# ---------------------------------------------------------------------------
# retail_exact_register_bijection_reencoding: the FPO re-encoding CERTIFICATE
# ---------------------------------------------------------------------------
#
# WHY THIS CLASS EXISTS, AND WHY IT IS STILL A CERTIFICATE
#
# `retail_exact_register_bijection` structurally excludes EBP from sigma's
# support for ONE stated reason: `[ebp]` has no mod=00 encoding, so a memory
# BASE that becomes EBP must grow a zero disp8 and one that stops being EBP
# may shrink.  That reason is entirely about LENGTH, and a rewriting that
# re-encodes the ModRM `mod` field and then repairs every dependent offset
# discharges it.  ESP stays excluded for a different and irreducible reason:
# ESP cannot be a ModRM r/m base at all (r/m 4 introduces a SIB) and cannot be
# a SIB index, so a rename to or from it is not an encoding question but a
# change of what the operand MEANS.
#
# EBP is only an ordinary callee-saved general register when the function does
# not use it as a frame pointer.  This class therefore refuses to admit EBP
# unless the COMDAT's own compiler-emitted FPO record says so -- `cbFrame`
# equal to FRAME_FPO -- AND no instruction in the body derives EBP from ESP.
# Those two facts together are what make the renaming a renaming rather than a
# reinterpretation of the frame.
#
# Everything else is the parent class, unchanged in kind: the pre-image is a
# census-pinned, compiler-produced COMDAT; the renaming is proved sound by a
# backward liveness fixpoint over the body's own CFG; and the composition is
# REFUSED unless the image is byte-identical to the pinned retail oracle under
# the (reseated) relocation mask.  It can only ever install retail's own code.
#
# The obligations this class adds to the parent's ten, each a `require` here:
#
# 11  frame proof     the closure's `.debug$F` record parses, describes this
#                     body, declares FRAME_FPO, and declares no SEH; and no
#                     instruction reads ESP while writing EBP.  Without this
#                     proof EBP is refused exactly as the parent refuses it.
# 12  minimal re-encoding
#                     an instruction may change length ONLY because its
#                     memory operand's BASE register crossed EBP, and only by
#                     the one byte the `mod` field forces: mod 00 -> mod 01
#                     with a zero disp8 when the base becomes EBP, and mod 01
#                     with a zero disp8 -> mod 00 when it stops being EBP.
#                     Register-direct forms, absolute forms, `+r` opcode
#                     fields and SIB INDEX fields never change length.  Every
#                     instruction is classified into exactly one of
#                     unchanged / field-rewrite / field-rewrite-and-re-encode
#                     / branch-repair, and the image is required to be the
#                     concatenation of those classified pieces.
# 13  branch fixpoint every relative branch's displacement is re-derived from
#                     the new layout and iterated to a fixpoint; no branch may
#                     change its own encoding length, so a short branch that
#                     would need widening REFUSES the composition rather than
#                     inventing a wider encoding.  A relocated branch operand
#                     is never touched.
# 14  reseat          every relocation lies wholly inside one instruction; its
#                     new offset is that instruction's new start plus its
#                     position within the instruction plus that instruction's
#                     own growth; no two collide; symbol, type, width and
#                     addend are untouched.
# 15  line fidelity   every COFF line row's offset is an instruction boundary
#                     of the PRE-image and is carried to the corresponding
#                     boundary of the image; the row count, the sentinel and
#                     every line NUMBER are unchanged.
# 16  debug ranges    the CodeView procedure record's code length becomes the
#                     image length and its debug start/end are carried through
#                     the same boundary map and required to stay boundaries;
#                     the FPO record's `cbProcSize` follows, and every other
#                     FPO field is byte-identical.
# 17  installation    the proved image is installed through the PRE-EXISTING
#                     `compose_same_slot_resize` primitive in its
#                     `retail_exact_reloc_divergent` mode -- the same code
#                     path a dozen landed rows already use to seat a
#                     different-length body in the same 16-byte contribution
#                     slot.  This class adds no installation proof of its own.


REGISTER_BIJECTION_REENCODING_CLASS = (
    "retail_exact_register_bijection_reencoding"
)


REGISTER_BIJECTION_REENCODING_KIND = (
    "frame_pointer_free_register_bijection_v1"
)


# A static-library translation unit links into exactly one image and must say
# which.  This is a CLOSED set of (TU target, image target) pairs, each a fact
# about the link graph in `CMakeLists.txt`: `viewmanager` is listed once, in
# the LEGO1 DLL's own `target_link_libraries`, exactly as `roi` is for the
# instruction-schedule certificate.  A pair outside the set is refused -- and
# a wrong image would in any case make the retail comparison fail.
REGISTER_BIJECTION_REENCODING_IMAGE_TARGETS = frozenset({
    ("viewmanager", "lego1"),
})


# The one frame kind in which EBP is an ordinary general register.
FPO_FRAME_KIND_FPO = 0


def require_frame_pointer_free_frame(
    coff: "CoffObject", section: dict, body: bytes,
    instructions: list[dict], context: str,
) -> dict:
    """Obligation 11: prove EBP is not this body's frame pointer.

    Two independent facts are required, and BOTH come from the object itself:
    the compiler's own FPO record for this COMDAT declares FRAME_FPO with no
    structured exception handling, and no instruction in the decoded body
    derives EBP from ESP.  The first is the compiler's statement that the
    function has no EBP frame; the second is a structural check on the code
    that no `mov ebp, esp` / `lea ebp, [esp+d]` establishes one anyway.
    """
    closure = _comdat_child_closure(coff, section)
    require(closure == (2, (".debug$F", ".debug$S")),
            f"{context}: a frame-pointer-free proof needs the FPO closure")
    record = parse_fpo_data(
        bytes(coff_body(coff, _comdat_child(coff, section, ".debug$F"))),
        expected_proc_size=section["raw_size"],
    )
    require(record["cbFrame"] == FPO_FRAME_KIND_FPO,
            f"{context}: the FPO record does not declare FRAME_FPO, so EBP "
            "may be this body's frame pointer")
    require(record["fHasSEH"] == 0,
            f"{context}: the FPO record declares structured exception "
            "handling, whose unwind may read EBP")
    for item in instructions:
        # ESP is read IMPLICITLY by every push and pop, including the
        # prologue's `push ebp` and the epilogue's `pop ebp`, and that says
        # nothing about frames.  What establishes a frame pointer is EBP
        # taking ESP's VALUE or an ADDRESS derived from it:
        #
        #     mov ebp, esp        register-direct     -> a frame pointer
        #     add ebp, esp        register-direct     -> a frame pointer
        #     lea ebp, [esp+d]    address computed    -> a frame pointer
        #     mov ebp, [esp+d]    value LOADED        -> NOT a frame pointer
        #
        # The last one matters: reading a spilled value out of the frame into
        # EBP leaves EBP an ordinary register holding ordinary data.  Treating
        # every appearance of ESP as frame-establishing refused `0x10051ac0`,
        # whose own FPO record declares FRAME_FPO and which merely does
        # `mov ebp, [esp+0x14]`.  So look at HOW ESP is named, not whether.
        if "ebp" not in item["writes"]:
            continue
        encoding = item["encoding"]
        direct = set()
        for byte_index, shift in item["fields"]:
            name = IA32_GENERAL_REGISTER_NAMES[(body[byte_index] >> shift) & 7]
            if encoding is None:
                direct.add(name)
                continue
            memory_base = (byte_index == (encoding["sib_at"]
                                          if encoding["sib_at"] is not None
                                          else encoding["modrm_at"])
                           and shift == 0 and encoding["mode"] != 3)
            memory_index = (encoding["sib_at"] is not None
                            and byte_index == encoding["sib_at"]
                            and shift == 3 and encoding["mode"] != 3)
            if memory_base or memory_index:
                # An address operand.  It only establishes a frame pointer if
                # the ADDRESS ITSELF is what lands in EBP, i.e. `lea`.
                if item["opcode"] == 0x8D:
                    direct.add(name)
                continue
            direct.add(name)
        require("esp" not in direct,
                f"{context}: the instruction at {item['offset']} derives EBP "
                "from ESP, which establishes a frame pointer")
    return record


def _reencoding_region_for(regions: list[dict], offset: int) -> dict | None:
    """The declared region covering one instruction, or None."""
    for region in regions:
        if region["start"] <= offset < region["end"]:
            return region
    return None


def _reencoded_instruction(
    body: bytes, item: dict, mapping: dict, numbers: dict,
    relocation_offsets: frozenset, context: str,
) -> tuple[bytes, str, list[int]]:
    """Rewrite ONE instruction's register fields, re-encoding if EBP forces it.

    Obligation 12.  Returns the new encoding, the class of change and the
    pre-image byte offsets whose value the rewrite changed:
    `"field"` when only register fields moved, `"reencode"` when the ModRM
    `mod` field additionally had to change because the memory BASE crossed
    EBP.  The re-encoding is derived from the decoder's own layout
    description, never by re-disassembling this function's own output.
    """
    start, length = item["offset"], item["length"]
    raw = bytearray(body[start:start + length])
    encoding = item["encoding"]
    base_field = None
    if (encoding is not None and encoding["mode"] != 3
            and not encoding["absolute"]):
        # The BASE register's field: the SIB base when a SIB is present, the
        # ModRM r/m field otherwise.  The decoder emits exactly one such
        # field, at shift 0 of that byte.
        base_field = (encoding["sib_at"] if encoding["sib_at"] is not None
                      else encoding["modrm_at"])
    base_before = None
    base_after = None
    touched = []
    for byte_index, shift in item["fields"]:
        value = (raw[byte_index - start] >> shift) & 7
        if byte_index == base_field and shift == 0:
            base_before = value
        if value not in numbers:
            if byte_index == base_field and shift == 0:
                base_after = value
            continue
        require(byte_index not in relocation_offsets,
                f"{context}: a rewritten byte at {byte_index} overlaps a "
                "relocation")
        raw[byte_index - start] = (
            (raw[byte_index - start] & ~(7 << shift))
            | (numbers[value] << shift)
        ) & 0xFF
        if raw[byte_index - start] != body[byte_index]:
            touched.append(byte_index)
        if byte_index == base_field and shift == 0:
            base_after = numbers[value]
    touched = sorted(set(touched))
    if base_field is None or base_before is None or base_before == base_after:
        return bytes(raw), "field", touched
    ebp = _IA32_REGISTER_NUMBERS["ebp"]
    modrm_local = encoding["modrm_at"] - start
    mode = encoding["mode"]
    if base_after == ebp:
        require(mode in (0, 1, 2),
                f"{context}: unexpected ModRM mode at {start}")
        if mode != 0:
            return bytes(raw), "field", touched
        # mod 00 with base EBP would mean "no base": grow the zero disp8 the
        # encoding forces.  The inserted byte goes immediately after the SIB
        # when one is present, and after the ModRM byte otherwise -- i.e.
        # exactly where the decoder said the displacement would start.
        insert_at = (encoding["sib_at"] - start + 1
                     if encoding["sib_at"] is not None else modrm_local + 1)
        require(encoding["displacement_size"] == 0,
                f"{context}: a mod-00 operand at {start} already carries a "
                "displacement")
        raw[modrm_local] = (raw[modrm_local] & 0x3F) | 0x40
        raw = raw[:insert_at] + bytearray(b"\x00") + raw[insert_at:]
        return bytes(raw), "reencode", touched
    if base_before == ebp:
        if mode != 1:
            return bytes(raw), "field", touched
        require(encoding["displacement_size"] == 1
                and encoding["displacement_at"] is not None,
                f"{context}: a mod-01 operand at {start} has no disp8")
        displacement_local = encoding["displacement_at"] - start
        if raw[displacement_local] != 0:
            # A non-zero disp8 is legal for every base: nothing to re-encode.
            return bytes(raw), "field", touched
        raw[modrm_local] = raw[modrm_local] & 0x3F
        del raw[displacement_local]
        return bytes(raw), "reencode", touched
    return bytes(raw), "field", touched


# The relative-branch encodings this class is willing to repair.  Each names
# the width of the displacement field and its offset from the END of the
# instruction, so a repair writes exactly those bytes and nothing else.  A
# branch outside this table, or one whose displacement is relocated, is never
# touched -- and if the layout moved it, the fixpoint's own re-decode refuses.
IA32_REPAIRABLE_BRANCH_WIDTHS = (1, 4)


REGISTER_BIJECTION_REENCODING_FIXPOINT_ROUNDS = 64


def apply_register_bijection_reencoding(
    body: bytes, regions: list[dict], relocation_offsets: frozenset,
    context: str,
    relocations: dict | None = None,
    code_length: int | None = None,
    internal_targets: frozenset | None = None,
    frame_pointer_free: bool = False,
) -> tuple[bytes, dict]:
    """Rewrite several regions under proved bijections, re-encoding for EBP.

    This is `apply_register_bijection` generalised on two axes: sigma may name
    EBP when the caller has discharged obligation 11, and an instruction may
    change length when -- and only when -- the ModRM `mod` field forces it.
    Every obligation of the parent still holds, and obligations 12 to 14 are
    checked here.  The result is re-decoded to exhaustion so that every claim
    about the image is measured ON the image.
    """
    body = bytes(body)
    instructions = decode_ia32_bijection_body(
        body, context, relocations, code_length)
    limit = len(body) if code_length is None else code_length
    boundaries = {item["offset"] for item in instructions}
    boundaries.add(limit)
    index_of = {item["offset"]: index
                for index, item in enumerate(instructions)}

    require(regions, f"{context}: no region is declared")
    previous_end = 0
    for position, region in enumerate(regions):
        region_context = f"{context} region {position}"
        start, end = region["start"], region["end"]
        require(start >= previous_end and start < end,
                f"{region_context}: regions are unsorted, empty or "
                "overlapping")
        previous_end = end
        require(end <= limit,
                f"{region_context}: region reaches past the body's code")
        require(start in boundaries and end in boundaries,
                f"{region_context}: region does not span whole instructions")
        mapping = region["mapping"]
        require(set(mapping.values()) == set(mapping)
                and all(source != destination
                        for source, destination in mapping.items()),
                f"{region_context}: mapping is not a bijection of one "
                "register set")
        for name in set(mapping) | set(mapping.values()):
            require(name in _IA32_REGISTER_NUMBERS,
                    f"{region_context}: mapping names an unknown register")
        support = set(mapping) | set(mapping.values())
        require("esp" not in support,
                f"{region_context}: ESP cannot be a ModRM base or a SIB "
                "index, so a rename to or from it is not an encoding change")
        require(frame_pointer_free or "ebp" not in support,
                f"{region_context}: EBP is refused without a "
                "frame-pointer-free proof for this body")

    # A computed jump has no decodable successors, so the "control enters the
    # region only at its head" obligation cannot be discharged from the
    # decoded graph alone.  Exactly as in the parent class, the relocated
    # in-body label set must be SUPPLIED for such a body or it is refused.
    if any(item["indirect"] for item in instructions):
        require(internal_targets is not None,
                f"{context}: a computed jump requires the relocated in-body "
                "target set")
        for position, region in enumerate(regions):
            entered = sorted(target for target in internal_targets
                             if region["start"] < target < region["end"])
            require(not entered,
                    f"{context} region {position}: a relocated in-body "
                    f"target at {entered[:1]} enters the region other than "
                    "at its first instruction")

    live, successors = _register_bijection_live_sets(instructions, context)
    for position, region in enumerate(regions):
        region_context = f"{context} region {position}"
        start, end = region["start"], region["end"]
        mapping = region["mapping"]
        support = set(mapping) | set(mapping.values())
        inside = [item for item in instructions
                  if start <= item["offset"] < end]
        require(inside, f"{region_context}: region contains no instruction")
        require(inside[-1]["offset"] + inside[-1]["length"] == end,
                f"{region_context}: region does not end on an instruction "
                "boundary")
        entry = index_of[inside[0]["offset"]]
        for item in inside:
            blocked = support & set(item.get("frozen", frozenset()))
            require(not blocked,
                    f"{region_context}: {sorted(blocked)} is named by a "
                    f"sub-register field at {item['offset']} that sigma "
                    "cannot rewrite")
        for index, item in enumerate(instructions):
            for edge in successors[index]:
                if (not (start <= item["offset"] < end)
                        and start <= instructions[edge]["offset"] < end):
                    require(edge == entry,
                            f"{region_context}: control enters the region "
                            "other than at its first instruction")
        support_atoms = ia32_register_atoms(support)
        dead_in = support_atoms & set(live[entry])
        require(not dead_in,
                f"{region_context}: {_ia32_atom_registers(dead_in)} is live "
                "on entry to the region")
        for index, item in enumerate(instructions):
            if not (start <= item["offset"] < end):
                continue
            for edge in successors[index]:
                if start <= instructions[edge]["offset"] < end:
                    continue
                leaking = support_atoms & set(live[edge])
                require(not leaking,
                        f"{region_context}: "
                        f"{_ia32_atom_registers(leaking)} is live on an edge "
                        f"leaving the region at {item['offset']}")
            if item["flow"] in ("ret", "exit"):
                leaking = support_atoms & set(item["read_atoms"])
                require(not leaking,
                        f"{region_context}: "
                        f"{_ia32_atom_registers(leaking)} is live at the "
                        "region's return")

    # --- obligation 12: rewrite each instruction, classified ---------------
    pieces = []
    classes = []
    rewritten_fields = []
    for item in instructions:
        region = _reencoding_region_for(regions, item["offset"])
        if region is None:
            pieces.append(body[item["offset"]:item["offset"] + item["length"]])
            classes.append("unchanged")
            continue
        numbers = {_IA32_REGISTER_NUMBERS[source]:
                   _IA32_REGISTER_NUMBERS[destination]
                   for source, destination in region["mapping"].items()}
        raw, kind, touched = _reencoded_instruction(
            body, item, region["mapping"], numbers, relocation_offsets,
            context)
        rewritten_fields.extend(touched)
        require(len(raw) - item["length"] in (-1, 0, 1),
                f"{context}: the re-encoding at {item['offset']} changed the "
                "length by more than the one byte a mod field forces")
        require(kind == "reencode" or len(raw) == item["length"],
                f"{context}: the instruction at {item['offset']} changed "
                "length without a mod re-encoding")
        pieces.append(raw)
        classes.append(kind)
    tail = body[limit:]

    def _starts(current: list[bytes]) -> list[int]:
        cursor, out = 0, []
        for raw in current:
            out.append(cursor)
            cursor += len(raw)
        return out

    # --- obligation 13: the branch-displacement fixpoint -------------------
    repaired = set()
    for _round in range(REGISTER_BIJECTION_REENCODING_FIXPOINT_ROUNDS):
        starts = _starts(pieces)
        changed = False
        for index, item in enumerate(instructions):
            if item["flow"] not in ("jcc", "jmp") or item["target"] is None:
                continue
            raw = bytearray(pieces[index])
            width = _reencoding_branch_width(item, raw, context)
            destination = starts[index_of[item["target"]]]
            delta = destination - (starts[index] + len(raw))
            require(-(1 << (8 * width - 1)) <= delta < (1 << (8 * width - 1)),
                    f"{context}: the branch at {item['offset']} no longer "
                    f"reaches its target in {width} displacement byte(s); "
                    "widening it would be a code change, not a renaming")
            encoded = delta.to_bytes(width, "little", signed=True)
            if bytes(raw[len(raw) - width:]) != encoded:
                raw[len(raw) - width:] = encoded
                pieces[index] = bytes(raw)
                repaired.add(item["offset"])
                changed = True
        if not changed:
            break
    else:
        raise ByteIdentityError(
            f"{context}: the branch-displacement fixpoint did not converge")

    starts = _starts(pieces)
    image = b"".join(pieces) + tail
    offset_map = {item["offset"]: starts[index]
                  for index, item in enumerate(instructions)}
    image_limit = starts[-1] + len(pieces[-1]) if pieces else 0
    offset_map[limit] = image_limit
    require(len(image) == image_limit + len(tail),
            f"{context}: the image is not the concatenation of its pieces")

    # Every changed piece is accounted for by its class, and by nothing else.
    for index, item in enumerate(instructions):
        original = body[item["offset"]:item["offset"] + item["length"]]
        if pieces[index] == original:
            continue
        require(classes[index] in ("field", "reencode")
                or item["offset"] in repaired,
                f"{context}: the instruction at {item['offset']} changed "
                "outside a declared region and is not a branch repair")

    # --- obligation 14: where every relocation lands ----------------------
    reseat = []
    for offset in sorted(relocations or {}):
        record = (relocations or {})[offset]
        width = record["width"]
        owner = None
        for index, item in enumerate(instructions):
            if (item["offset"] <= offset
                    and offset + width <= item["offset"] + item["length"]):
                owner = index
                break
        require(owner is not None,
                f"{context}: the relocation at {offset} does not lie wholly "
                "inside one decoded instruction")
        item = instructions[owner]
        growth = len(pieces[owner]) - item["length"]
        # The re-encoding inserts (or removes) its byte immediately after the
        # ModRM/SIB pair, so every trailing field keeps its distance from the
        # END of the instruction.  That invariant is the reseat, and it is
        # required rather than assumed: a relocation that is NOT strictly
        # after the ModRM/SIB of a re-encoded instruction refuses.
        from_end = item["offset"] + item["length"] - offset
        new_offset = starts[owner] + len(pieces[owner]) - from_end
        if growth:
            encoding = item["encoding"]
            require(encoding is not None,
                    f"{context}: a re-encoded instruction at {item['offset']} "
                    "has no ModRM layout")
            fixed_end = (encoding["sib_at"] if encoding["sib_at"] is not None
                         else encoding["modrm_at"]) + 1
            require(offset >= fixed_end,
                    f"{context}: the relocation at {offset} overlaps the "
                    "ModRM/SIB bytes the re-encoding changed")
            require(new_offset == offset + (starts[owner] - item["offset"])
                    + growth,
                    f"{context}: the reseat of {offset} is inconsistent")
        require(starts[owner] <= new_offset
                and new_offset + width <= starts[owner] + len(pieces[owner]),
                f"{context}: the reseat of {offset} leaves its instruction")
        reseat.append([offset, new_offset])
    require(len({pair[1] for pair in reseat}) == len(reseat),
            f"{context}: the reseat collides two relocation records")
    image_relocations = None
    if relocations is not None:
        moved = dict(reseat)
        image_relocations = {moved[offset]: record
                             for offset, record in relocations.items()}
    image_internal = None
    if internal_targets is not None:
        for target in internal_targets:
            require(target in offset_map,
                    f"{context}: a relocated in-body target at {target} is "
                    "not an instruction boundary")
        image_internal = frozenset(offset_map[target]
                                   for target in internal_targets)

    # --- the image is re-decoded and every claim measured ON it -----------
    image_instructions = decode_ia32_bijection_body(
        image, f"{context} image", image_relocations,
        None if code_length is None else image_limit)
    require(len(image_instructions) == len(instructions),
            f"{context}: the image has a different instruction count")
    for left, right, raw in zip(image_instructions, instructions, pieces):
        require(left["offset"] == offset_map[right["offset"]]
                and left["length"] == len(raw),
                f"{context}: the image's instruction at "
                f"{right['offset']} did not land where the layout says")
        form = _bijection_form_for(right["opcode"])
        opreg = form is not None and form["opreg"] is not None
        mask = 0xF8 if opreg else 0xFFFF
        require(left["opcode"] & mask == right["opcode"] & mask
                and left["flow"] == right["flow"],
                f"{context}: the image changed an opcode or a control flow "
                f"at {right['offset']}")
        require(left["target"] == (None if right["target"] is None
                                   else offset_map[right["target"]]),
                f"{context}: the image changed a branch target at "
                f"{right['offset']}")
        region = _reencoding_region_for(regions, right["offset"])
        mapping = {} if region is None else region["mapping"]
        require(left["reads"] == frozenset(mapping.get(name, name)
                                           for name in right["reads"])
                and left["writes"] == frozenset(mapping.get(name, name)
                                                for name in right["writes"]),
                f"{context}: the image's operand set at {right['offset']} is "
                "not the bijection's image")
    require(image[image_limit:] == tail,
            f"{context}: the image changed the body's data tail")

    growth_detail = [
        [item["offset"], starts[index], item["length"], len(pieces[index])]
        for index, item in enumerate(instructions)
        if len(pieces[index]) != item["length"]
    ]
    rewritten = sorted(set(rewritten_fields))
    require(rewritten, f"{context}: the bijection rewrites no register field")
    require(image != body or growth_detail,
            f"{context}: the bijection moves nothing")
    return image, {
        "offset_map": {str(key): value
                       for key, value in sorted(offset_map.items())},
        "growth": growth_detail,
        "branch_repairs": sorted(offset_map[offset] for offset in repaired),
        "relocation_reseat": [pair for pair in reseat if pair[0] != pair[1]],
        "region_instruction_counts": [
            sum(1 for item in instructions
                if region["start"] <= item["offset"] < region["end"])
            for region in regions
        ],
        "rewritten_field_offsets": rewritten,
        "instruction_count": len(instructions),
        "code_length": limit,
        "image_code_length": image_limit,
    }


def _reencoding_branch_width(item: dict, raw: bytes, context: str) -> int:
    """The displacement width of one repairable relative branch.

    Read off the module's own closed form table, never guessed, and refused
    for any encoding whose displacement this class will not repair.
    """
    form = _bijection_form_for(item["opcode"])
    require(form is not None
            and form["displacement"] in IA32_REPAIRABLE_BRANCH_WIDTHS,
            f"{context}: the branch at {item['offset']} has no repairable "
            "displacement field")
    require(len(raw) == item["length"],
            f"{context}: the branch at {item['offset']} changed its own "
            "encoding length")
    return form["displacement"]


def _reencoded_donor_object(
    donor_bytes: bytes, mangled: str, image: bytes, proof: dict, context: str,
) -> bytes:
    """Re-seat one COMDAT's dependent COFF records around a resized body.

    Obligations 14 to 16.  The donor is an authentic compiler object; this
    produces the same object with the proved image in place of the target
    body and every record that states a code offset carried through the
    bijection's own boundary map.  Nothing outside the target COMDAT's own
    data, tables and closure children is touched, and the result is re-parsed
    and re-checked before it is handed to the installation primitive.
    """
    donor = CoffObject(donor_bytes)
    primary = donor.function_section(mangled)
    offset_map = {int(key): value for key, value in proof["offset_map"].items()}
    body_length = len(image)
    require(offset_map[primary["raw_size"]] == body_length
            if primary["raw_size"] in offset_map else True,
            f"{context}: the boundary map does not end at the image length")

    # The COFF line table: the sentinel keeps the donor's function symbol
    # index, and every row keeps its LINE NUMBER and moves only by the map.
    line_bytes = _coff_table_bytes(donor, primary, "lines")
    require(len(line_bytes) == primary["line_count"] * 6
            and primary["line_count"] >= 1,
            f"{context}: the donor line table is missing")
    rebuilt_lines = bytearray(line_bytes[:6])
    require(coff_unpack("<IH", line_bytes, 0,
                        f"{context} line sentinel")[1] == 0,
            f"{context}: the donor line sentinel is invalid")
    for position in range(1, primary["line_count"]):
        offset, line = coff_unpack("<IH", line_bytes, position * 6,
                                   f"{context} line row {position}")
        require(line != 0,
                f"{context}: line row {position} has no line number")
        require(offset in offset_map,
                f"{context}: line row {position} at {offset} is not an "
                "instruction boundary of the pre-image")
        rebuilt_lines += offset_map[offset].to_bytes(4, "little")
        rebuilt_lines += line.to_bytes(2, "little")
    require(len(rebuilt_lines) == len(line_bytes),
            f"{context}: the rebuilt line table changed size")

    # The relocation table: only the four offset bytes of a moved record.
    relocation_bytes = _coff_table_bytes(donor, primary, "relocations")
    moved = dict(proof["relocation_reseat"])
    rebuilt_relocations = bytearray(relocation_bytes)
    for ordinal in range(primary["relocation_count"]):
        at = ordinal * 10
        offset = int.from_bytes(relocation_bytes[at:at + 4], "little")
        rebuilt_relocations[at:at + 4] = moved.get(
            offset, offset).to_bytes(4, "little")
    require(len(rebuilt_relocations) == len(relocation_bytes),
            f"{context}: the rebuilt relocation table changed size")

    # The CodeView procedure record: its code length becomes the image's and
    # its debug range is carried through the same map.
    debug_child = _comdat_child(donor, primary, ".debug$S")
    debug_raw = bytes(coff_body(donor, debug_child))
    require(len(debug_raw) >= 28 and debug_raw[2:4] == b"\x05\x02",
            f"{context}: the donor debug$S is not an S_LPROC32 record")
    code_length, debug_start, debug_end = coff_unpack(
        "<III", debug_raw, 16, f"{context} debug range")
    require(code_length == primary["raw_size"]
            and 0 <= debug_start <= debug_end < code_length,
            f"{context}: the donor debug procedure range is stale")
    require(debug_start in offset_map and debug_end in offset_map,
            f"{context}: the debug range is not on instruction boundaries")
    rebuilt_debug = bytearray(debug_raw)
    rebuilt_debug[16:28] = (
        body_length.to_bytes(4, "little")
        + offset_map[debug_start].to_bytes(4, "little")
        + offset_map[debug_end].to_bytes(4, "little"))

    # The FPO record: only cbProcSize moves; every other field is identical.
    fpo_child = _comdat_child(donor, primary, ".debug$F")
    fpo_raw = bytes(coff_body(donor, fpo_child))
    parse_fpo_data(fpo_raw, expected_proc_size=primary["raw_size"])
    rebuilt_fpo = bytearray(fpo_raw)
    rebuilt_fpo[4:8] = body_length.to_bytes(4, "little")
    parse_fpo_data(bytes(rebuilt_fpo), expected_proc_size=body_length)
    require(rebuilt_fpo[:4] == fpo_raw[:4] and rebuilt_fpo[8:] == fpo_raw[8:],
            f"{context}: the rebuilt FPO record changed a field other than "
            "cbProcSize")

    replacements = [
        (primary["raw_offset"], primary["raw_offset"] + primary["raw_size"],
         bytes(image)),
        (primary["line_offset"],
         primary["line_offset"] + primary["line_count"] * 6,
         bytes(rebuilt_lines)),
        (primary["relocation_offset"],
         primary["relocation_offset"] + primary["relocation_count"] * 10,
         bytes(rebuilt_relocations)),
        (debug_child["raw_offset"],
         debug_child["raw_offset"] + debug_child["raw_size"],
         bytes(rebuilt_debug)),
        (fpo_child["raw_offset"],
         fpo_child["raw_offset"] + fpo_child["raw_size"],
         bytes(rebuilt_fpo)),
    ]
    output = bytearray(apply_replacements(donor_bytes, replacements))

    def shifted(pointer: int) -> int:
        return shifted_pointer(pointer, replacements)

    new_symbol_offset = shifted(donor.symbol_offset)
    output[8:12] = new_symbol_offset.to_bytes(4, "little")
    for section in donor.sections:
        header = 20 + (section["number"] - 1) * 40
        if section["number"] == primary["number"]:
            output[header + 16:header + 20] = body_length.to_bytes(
                4, "little")
        for field, relative in (("raw_offset", 20),
                                ("relocation_offset", 24),
                                ("line_offset", 28)):
            pointer = shifted(section[field])
            if pointer != section[field]:
                output[header + relative:header + relative + 4] = (
                    pointer.to_bytes(4, "little"))
    for symbol_index, item in donor.symbols.items():
        if item["type"] == 0x20 and item["aux_count"] >= 1:
            auxiliary = coff_auxiliary(donor, symbol_index, item)
            line_pointer = int.from_bytes(auxiliary[8:12], "little")
            mapped = shifted(line_pointer) if line_pointer else line_pointer
            if mapped != line_pointer:
                at = new_symbol_offset + (symbol_index + 1) * 18
                output[at + 8:at + 12] = mapped.to_bytes(4, "little")

    function_index, function_symbol_record = function_symbol(
        donor, mangled, primary["number"])
    function_aux = coff_auxiliary(donor, function_index,
                                  function_symbol_record)
    require(int.from_bytes(function_aux[4:8], "little")
            == primary["raw_size"],
            f"{context}: the donor Function Definition TotalSize is stale")
    at = new_symbol_offset + (function_index + 1) * 18
    output[at + 4:at + 8] = body_length.to_bytes(4, "little")

    section_index, section_symbol_record = _coff_section_symbol(donor, primary)
    aux_at = new_symbol_offset + (section_index + 1) * 18
    require(int.from_bytes(
        coff_auxiliary(donor, section_index, section_symbol_record)[0:4],
        "little") == primary["raw_size"],
        f"{context}: the donor COMDAT auxiliary Length is stale")
    output[aux_at:aux_at + 4] = body_length.to_bytes(4, "little")

    end_index, end_symbol = _coff_marker(donor, ".ef", primary["number"])
    require(end_symbol["value"] == primary["raw_size"],
            f"{context}: the donor .ef marker is stale")
    output[new_symbol_offset + end_index * 18 + 8:
           new_symbol_offset + end_index * 18 + 12] = body_length.to_bytes(
        4, "little")

    # Every OTHER symbol seated in this section states a code offset and is
    # carried through the same map; one that is not a boundary refuses.
    carried = []
    for symbol_index, item in donor.symbols.items():
        if item["section"] != primary["number"]:
            continue
        if symbol_index in (function_index, section_index, end_index):
            continue
        if item["name"] in (".bf", ".lf"):
            continue
        require(item["value"] in offset_map,
                f"{context}: the symbol {item['name']} at {item['value']} is "
                "not an instruction boundary of the pre-image")
        mapped = offset_map[item["value"]]
        if mapped != item["value"]:
            at = new_symbol_offset + symbol_index * 18
            output[at + 8:at + 12] = mapped.to_bytes(4, "little")
            carried.append([item["name"], item["value"], mapped])

    derived = bytes(output)
    checked = CoffObject(derived)
    checked_primary = checked.function_section(mangled)
    require(coff_body(checked, checked_primary) == bytes(image),
            f"{context}: the derived donor body is not the image")
    require(checked_primary["raw_size"] == body_length
            and checked_primary["line_count"] == primary["line_count"]
            and checked_primary["relocation_count"]
            == primary["relocation_count"]
            and checked_primary["number"] == primary["number"]
            and checked_primary["characteristics"]
            == primary["characteristics"],
            f"{context}: the derived donor target header is inconsistent")
    require(function_multiset(checked) == function_multiset(donor)
            and comdat_primary_identity_multiset(checked)
            == comdat_primary_identity_multiset(donor)
            and len(checked.sections) == len(donor.sections),
            f"{context}: the derived donor changed the object's topology")
    require(_comdat_child_closure(checked, checked_primary)
            == _comdat_child_closure(donor, primary),
            f"{context}: the derived donor changed the target closure")
    require([row["target"] for row in detailed_relocations(
                checked, checked_primary)]
            == [row["target"] for row in detailed_relocations(donor, primary)],
            f"{context}: the derived donor changed a relocation target")
    require([row["offset"] for row in detailed_relocations(
                checked, checked_primary)]
            == [moved.get(row["offset"], row["offset"])
                for row in detailed_relocations(donor, primary)],
            f"{context}: the derived donor relocation offsets are not the "
            "proved reseat")
    return derived, {"carried_code_symbols": carried,
                     "line_rows": primary["line_count"],
                     "procedure_range": [body_length,
                                         offset_map[debug_start],
                                         offset_map[debug_end]]}


def compose_retail_exact_register_bijection_reencoding(
    seed_bytes: bytes,
    donor_bytes: bytes,
    function: dict,
    retail_body: bytes,
) -> tuple[bytes, dict]:
    """Install sigma(donor body) after proving it is retail's own code.

    The parent class with EBP admitted: see the class comment above for the
    seven obligations that admission costs.  The pre-image is an ordinary,
    census-pinned carrier compile of the same translation unit; the renaming
    is proved sound against the body's own control flow AND against the
    compiler's own frame declaration; the resized image is re-seated through
    the bijection's own boundary map; and the composition is refused unless
    the result equals the pinned retail oracle under the reseated relocation
    mask.  Installation is delegated, unchanged, to `compose_same_slot_resize`
    in the mode a dozen landed rows already use.
    """
    require(function.get("splice_class")
            == REGISTER_BIJECTION_REENCODING_CLASS,
            "splice class is not retail_exact_register_bijection_reencoding")
    require("target_source_refactor" not in function,
            "register-bijection functions carry no source refactor")
    require(isinstance(retail_body, (bytes, bytearray)) and retail_body,
            "retail oracle body is missing")
    spec = function["register_bijection_reencoding"]
    require(spec["kind"] == REGISTER_BIJECTION_REENCODING_KIND,
            "re-encoding bijection kind differs")
    seed = CoffObject(seed_bytes)
    donor = CoffObject(donor_bytes)
    mangled = function["mangled"]
    sp = seed.function_section(mangled)
    dp = donor.function_section(mangled)

    # --- obligation 1: provenance, pinned exactly as the parent pins it ---
    require(sp["number"] == dp["number"]
            == function["expected_section_number"],
            "re-encoding target section seat changed")
    require(len(seed.sections) == len(donor.sections)
            == function["expected_section_count"],
            "re-encoding global section count changed")
    seed_functions = function_multiset(seed)
    require(seed_functions == function_multiset(donor)
            and sum(seed_functions.values())
            == function["expected_function_count"],
            "re-encoding donor function set differs")
    seed_comdats = comdat_primary_identity_multiset(seed)
    require(seed_comdats == comdat_primary_identity_multiset(donor)
            and sum(seed_comdats.values())
            == function["expected_comdat_count"],
            "re-encoding donor COMDAT identity set differs")
    require(sp["raw_size"] == function["expected_seed_length"]
            and dp["raw_size"] == function["expected_preimage_length"]
            and sp["relocation_count"] == dp["relocation_count"]
            == function["expected_relocation_count"]
            and sp["line_count"] == function["expected_seed_line_count"]
            and dp["line_count"] == function["expected_donor_line_count"]
            and sp["name"] == dp["name"]
            and sp["characteristics"] == dp["characteristics"]
            == function["expected_characteristics"],
            "re-encoding target header/count pins changed")
    require(section_definitions(seed)[sp["number"]]["selection"]
            == section_definitions(donor)[dp["number"]]["selection"]
            == function["expected_selection"],
            "re-encoding COMDAT selection changed")
    expected_closure = tuple(function["expected_closure"])
    require(_comdat_child_closure(seed, sp)
            == _comdat_child_closure(donor, dp)
            == (len(expected_closure), expected_closure)
            and list(expected_closure) == REGISTER_BIJECTION_FPO_CLOSURE,
            "re-encoding target closure is not the FPO debug pair")
    require(instruction_mosaic_metadata_sha256(seed, sp)
            == function["expected_seed_metadata_sha256"]
            and instruction_mosaic_metadata_sha256(donor, dp)
            == function["expected_donor_metadata_sha256"],
            "re-encoding metadata differs from its pin")
    seed_body = coff_body(seed, sp)
    donor_body = bytes(coff_body(donor, dp))
    require(sha256_bytes(seed_body) == function["expected_seed_body_sha256"]
            and sha256_bytes(donor_body)
            == function["expected_donor_body_sha256"],
            "re-encoding seed/donor body differs from its pin")

    donor_rows = detailed_relocations(donor, dp)
    require([row["target"] for row in donor_rows]
            == [row["target"] for row in detailed_relocations(seed, sp)],
            "re-encoding donor relocation targets differ from the seed")
    relocation_offsets = frozenset(
        row["offset"] + byte
        for row in donor_rows for byte in range(row["width"]))
    relocation_symbols = {
        row["offset"]: {"width": row["width"], "target": row["target"]}
        for row in donor_rows}
    internal_targets = frozenset(
        row["target_value"] for row in donor_rows
        if row["target_section"] == dp["number"])
    declared_targets = spec.get("expected_internal_relocation_targets")
    if declared_targets is not None:
        require(sorted(internal_targets) == declared_targets,
                "re-encoding in-body relocated target set changed")

    # --- obligation 11: EBP is not this body's frame pointer --------------
    instructions = decode_ia32_bijection_body(
        donor_body, "re-encoding frame proof", relocation_symbols,
        spec.get("expected_code_length"))
    fpo_record = require_frame_pointer_free_frame(
        donor, dp, donor_body, instructions, "re-encoding frame proof")
    measured_fpo = {key: value for key, value in fpo_record.items()
                    if key != "raw_sha256"}
    require(measured_fpo == spec["expected_fpo_record"],
            "re-encoding FPO record differs from its declaration")

    regions = [
        {"start": item["start"], "end": item["end"],
         "mapping": dict(item["mapping"])}
        for item in spec["regions"]
    ]
    image, proof = apply_register_bijection_reencoding(
        donor_body, regions, relocation_offsets, "re-encoding image",
        relocation_symbols, spec.get("expected_code_length"),
        internal_targets or None, True,
    )
    require(proof["code_length"]
            == (spec.get("expected_code_length") or len(donor_body)),
            "re-encoding code length differs from its pin")
    require(proof["growth"] == spec["expected_growth"]
            and proof["branch_repairs"] == spec["expected_branch_repairs"]
            and proof["relocation_reseat"]
            == spec["expected_relocation_reseat"]
            and proof["rewritten_field_offsets"]
            == spec["expected_rewritten_field_offsets"]
            and proof["region_instruction_counts"]
            == spec["expected_region_instruction_counts"]
            and proof["instruction_count"]
            == spec["expected_instruction_count"]
            and proof["image_code_length"]
            == spec["expected_image_code_length"],
            "re-encoding image differs from its declaration")
    require(sha256_bytes(image) == function["expected_body_sha256"],
            "re-encoding image differs from its pin")
    require(len(image) == function["expected_body_length"]
            == function["expected_donor_length"],
            "re-encoding image length differs from its pin")
    require(image != donor_body,
            "re-encoding image does not move the donor body")

    # --- obligation 8: the image is retail's own code ---------------------
    pinned_length = function["retail_oracle"]["length"]
    require(len(retail_body) == pinned_length == len(image),
            "re-encoding retail length changed")
    moved = dict(proof["relocation_reseat"])
    installed_rows = [{**row, "offset": moved.get(row["offset"],
                                                  row["offset"])}
                      for row in donor_rows]
    semantic_detail = require_retail_relocation_oracle(
        installed_rows, bytes(retail_body),
        int(function["retail_oracle"]["address"], 16),
        function["retail_relocations"],
        "re-encoding retail relocation oracle",
    )
    masked_image = bytearray(image)
    masked_retail = bytearray(retail_body)
    for row in installed_rows:
        start, width = row["offset"], row["width"]
        masked_image[start:start + width] = b"\0" * width
        masked_retail[start:start + width] = b"\0" * width
    differing = sum(left != right
                    for left, right in zip(masked_image, masked_retail))
    require(differing == 0,
            f"re-encoding output is not retail-exact: {differing} byte(s) "
            "differ under the relocation mask")

    # --- obligations 14 to 17: re-seat, then delegate ---------------------
    derived, derived_detail = _reencoded_donor_object(
        donor_bytes, mangled, image, proof, "re-encoding derived donor")
    require(derived_detail["procedure_range"]
            == spec["expected_procedure_range"]
            and derived_detail["carried_code_symbols"]
            == spec["expected_carried_code_symbols"],
            "re-encoding derived donor differs from its declaration")
    effective = {
        "mangled": mangled,
        "splice_class": "retail_exact_reloc_divergent",
        "expected_seed_length": function["expected_seed_length"],
        "expected_donor_length": function["expected_donor_length"],
        "expected_linked_span": function["expected_linked_span"],
        "expected_body_sha256": function["expected_body_sha256"],
        "expected_seed_line_count": function["expected_seed_line_count"],
        "expected_donor_line_count": function["expected_donor_line_count"],
        "retail_oracle": function["retail_oracle"],
        "retail_relocations": function["retail_relocations"],
    }
    composed, detail = compose_same_slot_resize(
        seed_bytes, derived, effective, retail_body=bytes(retail_body))

    checked = CoffObject(composed)
    cp = checked.function_section(mangled)
    require(coff_body(checked, cp) == image,
            "re-encoding composed body differs from the image")
    require([row["offset"] for row in detailed_relocations(checked, cp)]
            == [row["offset"] for row in installed_rows]
            and [row["target"] for row in detailed_relocations(checked, cp)]
            == [row["target"] for row in installed_rows],
            "re-encoding composed relocation table is not the proved reseat")
    return composed, {
        **detail,
        "splice_class": REGISTER_BIJECTION_REENCODING_CLASS,
        "register_bijection_reencoding": [
            {"start": item["start"], "end": item["end"],
             "mapping": dict(sorted(item["mapping"].items()))}
            for item in regions
        ],
        "fpo_record": measured_fpo,
        "growth": proof["growth"],
        "branch_repairs": proof["branch_repairs"],
        "relocation_reseat": proof["relocation_reseat"],
        "rewritten_field_offsets": proof["rewritten_field_offsets"],
        "instruction_count": proof["instruction_count"],
        "carried_code_symbols": derived_detail["carried_code_symbols"],
        "procedure_range": derived_detail["procedure_range"],
        "retail_exact": True,
        **semantic_detail,
    }


# ---------------------------------------------------------------------------
# retail_exact_instruction_schedule: a topological-reordering CERTIFICATE
# ---------------------------------------------------------------------------
#
# WHY THIS CLASS IS A CERTIFICATE AND NOT A GENERATOR
#
# `instruction_self_permutation` exchanges ONE adjacent pair of provably
# independent compiler-produced instructions and is gated on retail equality.
# This class generalises that statement from a pair to a WINDOW:
#
#     the target's instruction sequence over a closed window is a TOPOLOGICAL
#     REORDERING of the same multiset of instructions under the window's own
#     dependence DAG.
#
# That is strictly stronger than a pairwise-independence proof -- a pair is
# the two-node case, where the DAG is required to be empty -- and it is
# provable on the same terms.  Nothing is invented: every byte installed is a
# byte the compiler emitted for this function, in a different order, and the
# composition is REFUSED unless the result is byte-identical to the pinned
# retail oracle under the relocation mask.
#
# The obligations, each a `require` in this module rather than a comment:
#
#  1  provenance     the pre-image is a freshly compiled, census-pinned seed
#                    or donor COMDAT of the same mangled function; the
#                    object-wide function/COMDAT/section/closure census is
#                    pinned exactly as every other retail-exact class pins it
#  2  total decode   the whole body decodes to complete instructions with the
#                    register class's own fail-closed table, to exhaustion,
#                    and every instruction inside a window is additionally
#                    required to sit in the CLOSED schedule table below, which
#                    names its complete flag effect and its memory operand.
#                    x87, string, stack, absolute-memory, prefixed and every
#                    control-transfer form are refused rather than analysed.
#  3  same multiset  the window's instructions after the reordering are the
#                    same bag of encoded byte strings as before -- a
#                    permutation, never a rewrite -- so the window's total
#                    length is unchanged by construction and re-verified.
#  4  dependence     the declared order is a topological order of the window's
#                    dependence DAG: RAW, WAR and WAW on general registers AND
#                    on the flags, plus memory.  MEMORY IS THE HARD PART and
#                    it is deliberately conservative: two accesses may be
#                    reordered ONLY when both name the SAME base register with
#                    no index, neither is absolute, that base is written by no
#                    instruction in the window, and their [displacement,
#                    displacement+width) spans are disjoint.  Anything else --
#                    different base registers above all -- is a dependence
#                    edge, so a store never crosses a load or a store this
#                    cannot disambiguate.  The complete edge set is PINNED in
#                    the manifest, so a body whose dependences differ from the
#                    declaration refuses before anything moves.
#  5  control flow   no window may contain a branch, a call or any
#                    non-fall-through form, no branch anywhere in the body may
#                    target the interior of a window, and windows may not
#                    overlap.  A window may BEGIN at a branch target: that is
#                    a basic-block entry, and the whole window then executes
#                    from its first instruction on every path.
#  6  relocations    no relocation operand may intersect a window.  Every
#                    relocation therefore keeps its offset, and the output's
#                    relocation table is required to be the seed's own bytes.
#                    A window that would MOVE a relocation is refused: the
#                    reseat is not expressed here rather than expressed
#                    approximately.
#  7  line + debug   the image is decoded again to exhaustion and EVERY COFF
#                    line row is re-derived against it: each must still land
#                    on an instruction boundary.  The rows lying inside a
#                    window are PINNED, together with which source instruction
#                    now begins at each of them, so a reordering can never
#                    silently move a source-line boundary.  The `.debug$S`
#                    procedure record's code length and debug range are pinned
#                    and required to stay outside every window's interior, and
#                    no closure-child relocation may name a code symbol whose
#                    value falls inside one.
#  8  retail equal   the image must equal the retail oracle under the
#                    relocation mask, or the composition is refused.
#  9  scope          one named COMDAT, a declared window list, one pinned
#                    oracle, and the ordinary output-conservation proof of the
#                    equal-body primitive, which this class delegates to
#                    UNCHANGED.  Which primitive is read off the manifest's
#                    `expected_closure` pin exactly as the register-bijection
#                    certificate reads it.
#
# WHAT THIS CLASS DELIBERATELY DOES NOT CLAIM.  A COFF line table for
# optimised MSVC 4.2 output is a sequence of (offset, statement) markers, not
# a per-instruction attribution: our own unpermuted body already has hoisted
# instructions sitting inside a previous statement's row.  Obligation 7
# preserves every marker offset, proves each still begins an instruction, and
# pins which instruction that now is.  It does not claim to reproduce the line
# table retail's own compiler emitted for retail's schedule -- that table is
# not in the shipped image and no oracle for it exists.


INSTRUCTION_SCHEDULE_CLASS = "retail_exact_instruction_schedule"


# Which library target may name which final image.  A CLOSED pair set,
# not a wildcard: a static-library TU links into exactly one image and
# says so, mirroring the `omni -> lego1` allowance the source-equal-body
# class already carries.
INSTRUCTION_SCHEDULE_IMAGE_TARGETS = frozenset({
    ("roi", "lego1"),
})


INSTRUCTION_SCHEDULE_KIND = "topological_window_reordering_v1"


INSTRUCTION_SCHEDULE_FPO_CLOSURE = [".debug$F", ".debug$S"]
INSTRUCTION_SCHEDULE_EH_CLOSURE = [".debug$S", ".xdata$x"]


CODEVIEW_PROCEDURE_RECORD_TYPES = (0x0205, 0x0204)


def instruction_schedule_delegate(
    expected_closure: object, expected_code_renames: object,
    relocation_reseat: bool = False,
) -> str:
    """Name the installation delegate from the PINS alone.

    Identical policy to the register-bijection certificate: the composer
    requires the objects' own closure and rename set to equal these pins
    first, so a pin that disagrees refuses before this is reached.

    A window that moves a relocated operand needs the one primitive that can
    install a moved relocation record -- `equal_body_eh_reloc_layout`, which
    already pairs the two tables by ordinal, proves type/addend/target
    identity, and rewrites nothing but the four offset bytes.  The other two
    delegates retain the seed table verbatim and so cannot express a reseat.
    """
    if relocation_reseat:
        return "equal_body_eh_reloc_layout"
    if (list(expected_closure) == INSTRUCTION_SCHEDULE_FPO_CLOSURE
            and not expected_code_renames):
        return "equal_body_strict"
    return "equal_body_eh_structural_local"


# ---------------------------------------------------------------------------
# The CLOSED schedule table (obligation 2)
#
# An opcode may appear inside a window only if this table names its COMPLETE
# effect on the flags.  Everything absent is refused, which is why the
# control-transfer forms, the x87 forms, the stack forms (whose memory operand
# is an implicit [esp] this module does not model), the moffs32 forms (whose
# address is absolute and relocated) and every group-3 implicit-operand form
# are simply not here.  `(reads_flags, writes_flags)` is deliberately
# over-approximated wherever a form only touches some flags: over-approximating
# can only ADD dependence edges, never remove one.
# ---------------------------------------------------------------------------
def _ia32_schedule_flag_table() -> dict:
    table = {}
    for opcode in (0x88, 0x89, 0x8A, 0x8B, 0x8D, 0xC6, 0xC7):
        table[opcode] = (False, False)          # MOV / LEA touch no flag
    for index in range(8):
        table[0xB8 + index] = (False, False)    # MOV r32, imm32
    for opcode in (0x03, 0x0B, 0x23, 0x2B, 0x31, 0x33, 0x38, 0x39, 0x3A,
                   0x3B, 0x80, 0x81, 0x83, 0x84, 0x85):
        table[opcode] = (False, True)           # ALU / CMP / TEST write flags
    for index in range(8):                      # INC/DEC preserve CF; the
        table[0x40 + index] = (False, True)     # over-approximation is safe
        table[0x48 + index] = (False, True)
    for opcode in (0x1A, 0x1B):
        table[opcode] = (True, True)            # SBB reads and writes CF
    table[0xF6] = (False, True)                 # /0 TEST, /2 NOT, /3 NEG
    for index in range(8):
        table[0x50 + index] = (False, False)    # PUSH r32 touches no flag
    return table


# The stack obligation, ruled on by the owner.  On Win32 there is no red zone,
# so memory strictly BELOW esp is volatile and can hold no live value: a
# `push`'s store at [esp-4] cannot alias a live cell, and it is therefore
# admitted into a window without a memory descriptor.  But a push also
# MODIFIES esp, so moving one across an esp-relative access changes that
# access's effective address.  This class admits only the first branch of the
# ruling -- a window that carries a push may carry NO esp-relative memory
# operand at all.  The second branch (track the stack delta instruction by
# instruction and prove esp equal at every esp-relative access) is
# deliberately not implemented, so a window that would need it refuses.
# `pop` is NOT admitted: it READS [esp], which is live memory, and the
# below-esp axiom says nothing about it.  Two pushes can never be reordered
# relative to each other because both read and write esp, which is an edge.
_IA32_SCHEDULE_STACK_PUSH_OPCODES = frozenset(range(0x50, 0x58))


IA32_SCHEDULE_FLAG_EFFECTS = _ia32_schedule_flag_table()


IA32_STACK_SLOT_BYTES = 4


def ia32_esp_relative_displacement(body: bytes, item: dict) -> tuple | None:
    """(byte offset, size, signed value) of an ESP-relative displacement.

    ESP can only be a memory base through a SIB whose base field is 4, so this
    reads the SIB rather than guessing from the r/m field.  It deliberately
    covers `lea` as well as loads and stores: `lea edx, [esp+0x14]` carries an
    ESP displacement that a moved push shifts exactly as it shifts a load's,
    and `lea` has no memory OPERAND for the decoder to report.

    Returns None when the instruction has no ESP displacement, and also when
    it has an ESP base with NO displacement byte (mod 0), which cannot absorb
    an adjustment without growing an encoding -- the caller refuses that.
    """
    encoding = item["encoding"]
    if encoding is None or encoding["mode"] == 3 or encoding["absolute"]:
        return None
    if encoding["sib_at"] is None:
        return None
    sib = body[encoding["sib_at"]]
    base = sib & 7
    if base != _IA32_REGISTER_NUMBERS["esp"]:
        return None
    if encoding["mode"] == 0:
        return ("no_displacement", 0, 0)
    at, size = encoding["displacement_at"], encoding["displacement_size"]
    if at is None or size == 0:
        return ("no_displacement", 0, 0)
    return (at, size, int.from_bytes(body[at:at + size], "little", signed=True))


def ia32_esp_used_only_as_a_base(body: bytes, item: dict) -> bool:
    """Does this instruction touch ESP ONLY through an adjusted address?

    True when the instruction has a real ESP-relative displacement AND ESP
    appears in no register-direct field.  For such an instruction the stack
    adjustment restores the exact address it names, so a moved push changes
    nothing it observes -- which is what lets the ESP dependence between the
    two be discharged.  `lea edx, [esp+0x14]` qualifies: its displacement is
    adjusted too, so the ADDRESS it computes is preserved.
    """
    found = ia32_esp_relative_displacement(body, item)
    if found is None or found[0] == "no_displacement":
        return False
    encoding = item["encoding"]
    for byte_index, shift in item["fields"]:
        name = IA32_GENERAL_REGISTER_NAMES[(body[byte_index] >> shift) & 7]
        if name != "esp":
            continue
        is_base = (encoding is not None and encoding["sib_at"] is not None
                   and byte_index == encoding["sib_at"] and shift == 0)
        if not is_base:
            return False
    return True


def ia32_schedule_stack_adjustments(
    body: bytes, inside: list[dict], order: list[int], context: str,
) -> list[list]:
    """Obligation 6c: what a moved PUSH does to every ESP displacement.

    A `push` lowers ESP by four, so an ESP-relative operand that the
    permutation moves from one side of a push to the other must have its
    displacement changed by four in order to name the SAME address.  The
    adjustment is DERIVED here from the declared permutation -- it is never a
    free parameter -- as

        delta(i) = 4 * (pushes before i in the TARGET order
                        - pushes before i in the SOURCE order)

    and it is required to be absorbable without changing the instruction's
    encoded length, so a `disp8` that would overflow, or an ESP base with no
    displacement byte at all, REFUSES rather than growing an encoding.

    Returns `[[source index, byte offset, old value, new value], ...]`, sorted.
    """
    pushes = [index for index, item in enumerate(inside)
              if item["opcode"] in _IA32_SCHEDULE_STACK_PUSH_OPCODES]
    if not pushes:
        return []
    position = {source: index for index, source in enumerate(order)}
    adjustments = []
    for index, item in enumerate(inside):
        found = ia32_esp_relative_displacement(body, item)
        if found is None:
            continue
        before_source = sum(1 for push in pushes if push < index)
        before_target = sum(1 for push in pushes
                            if position[push] < position[index])
        delta = IA32_STACK_SLOT_BYTES * (before_target - before_source)
        if not delta:
            continue
        at, size, value = found
        require(at != "no_displacement",
                f"{context}: the instruction at {item['offset']} has an ESP "
                "base with no displacement byte, so it cannot absorb the "
                f"{delta:+d} a moved push forces without growing its encoding")
        updated = value + delta
        low, high = -(1 << (8 * size - 1)), (1 << (8 * size - 1)) - 1
        require(low <= updated <= high,
                f"{context}: adjusting the ESP displacement at "
                f"{item['offset']} by {delta:+d} would overflow its "
                f"{size}-byte field, which would change the encoding's length")
        adjustments.append([index, at, value, updated])
    return sorted(adjustments)


def ia32_schedule_instruction_facts(instruction: dict, context: str) -> dict:
    """Flag effect and memory operand of one window instruction, or refuse."""
    opcode = instruction["opcode"]
    effect = IA32_SCHEDULE_FLAG_EFFECTS.get(opcode)
    require(effect is not None,
            f"{context}: opcode 0x{opcode:02x} is outside the "
            "instruction-schedule table")
    require(instruction["flow"] == "fall",
            f"{context}: a control-transfer instruction is outside the "
            "instruction-schedule table")
    memory = instruction["memory"]
    if memory is not None:
        require(not memory.get("unknown"),
                f"{context}: a repeated string operation's memory span is an "
                "unknown extent and cannot be disambiguated")
        require(not memory["absolute"],
                f"{context}: an absolute memory operand cannot be "
                "disambiguated")
        require(memory["index"] is None,
                f"{context}: an indexed memory operand cannot be "
                "disambiguated")
        require(memory["base"] is not None,
                f"{context}: a memory operand without a base register cannot "
                "be disambiguated")
    return {
        "offset": instruction["offset"],
        "length": instruction["length"],
        "opcode": opcode,
        "reads": instruction["reads"],
        "writes": instruction["writes"],
        "reads_flags": effect[0],
        "writes_flags": effect[1],
        "memory": memory,
    }


def ia32_memory_provably_disjoint(left: dict, right: dict) -> bool:
    """Two memory cells that provably cannot alias.

    The ONLY admitted proof: the same base register, no index on either side,
    neither absolute, and non-overlapping [displacement, displacement+width)
    spans.  Two different base registers are NOT a proof of anything and this
    returns False for them, which makes the pair a dependence edge.
    """
    if left["absolute"] or right["absolute"]:
        return False
    if left["index"] is not None or right["index"] is not None:
        return False
    if left["base"] is None or left["base"] != right["base"]:
        return False
    return (left["displacement"] + left["width"] <= right["displacement"]
            or right["displacement"] + right["width"] <= left["displacement"])


def ia32_schedule_dependence_edges(
    instructions: list[dict], context: str,
    body: bytes | None = None, stack_adjusted: bool = False,
) -> tuple[list[dict], list[list]]:
    """The window's dependence DAG (obligation 4).

    Every ordered pair carries an edge unless it is proved independent on
    registers, on flags AND on memory.  The memory proof is the conservative
    one above, and a base register written anywhere inside the window
    invalidates every displacement comparison against it, so that is refused
    outright rather than reasoned around.

    `stack_adjusted` says the caller has DECLARED the ESP-displacement
    adjustments a moved push forces (obligation 6c).  Without it a push in the
    window is refused exactly as before, so every landed entry is unaffected.
    """
    facts = [ia32_schedule_instruction_facts(item, f"{context} at "
                                             f"{item['offset']}")
             for item in instructions]
    # The stack obligation, stated in its own right rather than inherited
    # from the displacement rule below.
    if any(item["opcode"] in _IA32_SCHEDULE_STACK_PUSH_OPCODES
           for item in facts):
        offending = sorted(
            item["offset"] for item in facts
            if item["memory"] is not None and item["memory"]["base"] == "esp")
        require(not offending or stack_adjusted,
                f"{context}: a push shares the window with the esp-relative "
                f"memory operand at {offending[:1]}, whose address the push's "
                "own esp delta would move")
        if stack_adjusted:
            # The refusal was also carrying an ALIASING fact for free: a push
            # writes the four bytes BELOW esp.  Once pushes are admitted that
            # has to be stated.  Every ESP displacement in the window must be
            # non-negative, so the pushed slot (at esp-4, and at every lower
            # address a later push reaches) lies strictly below every operand
            # the window names and can alias none of them.
            require(body is not None,
                    f"{context}: a stack-adjusted window needs its body")
            for item in instructions:
                found = ia32_esp_relative_displacement(body, item)
                if found is None or found[0] == "no_displacement":
                    continue
                require(found[2] >= 0,
                        f"{context}: the ESP displacement {found[2]} at "
                        f"{item['offset']} is below ESP, where a push in this "
                        "window writes, so disjointness does not hold")
    # A base register written inside the window invalidates any DISPLACEMENT
    # COMPARISON against it -- `[ecx+4]` and `[ecx+8]` need not be disjoint
    # once something writes `ecx` between them.  This used to REFUSE the whole
    # window, which was both stricter and less precise than necessary: the
    # comparison is only ever consulted for a pair where one side WRITES
    # memory, so a window whose same-base operands are all reads was being
    # turned away for a proof it never asked for (`0x10051ac0`'s
    # `mov ebp,[ecx+4]` and `mov ecx,[ecx+8]` are both loads).  The condition
    # is now applied where it belongs -- per pair, as a dependence EDGE, which
    # is strictly conservative: an unproved pair is ordered, never permitted.
    written = set()
    for item in facts:
        written |= set(item["writes"])
    # Which instructions touch ESP only through an address the stack
    # adjustment restores.  Only meaningful once pushes are admitted.
    esp_compensated = [
        stack_adjusted and body is not None
        and ia32_esp_used_only_as_a_base(body, item)
        for item in instructions
    ]
    is_stack_operation = [
        item["opcode"] in _IA32_SCHEDULE_STACK_PUSH_OPCODES for item in facts]
    edges = []
    for left in range(len(facts)):
        for right in range(left + 1, len(facts)):
            first, second = facts[left], facts[right]
            reasons = []
            # A push and an instruction whose ONLY use of ESP is an adjusted
            # address do not depend on each other THROUGH ESP: the adjustment
            # makes the address identical either way, and the push's own slot
            # is below every displacement in the window (required above).
            # Every other ESP dependence -- push against push, or anything
            # that reads ESP as a value -- is left exactly as it was.
            discharged = frozenset({"esp"}) if (
                (is_stack_operation[left] and esp_compensated[right])
                or (is_stack_operation[right] and esp_compensated[left])
            ) else frozenset()
            first_reads = first["reads"] - discharged
            first_writes = first["writes"] - discharged
            second_reads = second["reads"] - discharged
            second_writes = second["writes"] - discharged
            if first_writes & second_reads:
                reasons.append("register_raw")
            if first_reads & second_writes:
                reasons.append("register_war")
            if first_writes & second_writes:
                reasons.append("register_waw")
            if first["writes_flags"] and second["reads_flags"]:
                reasons.append("flags_raw")
            if first["reads_flags"] and second["writes_flags"]:
                reasons.append("flags_war")
            if first["writes_flags"] and second["writes_flags"]:
                reasons.append("flags_waw")
            one, two = first["memory"], second["memory"]
            if one is not None and two is not None and (one["write"]
                                                        or two["write"]):
                base_is_written = (one["base"] in written
                                   or two["base"] in written)
                if (base_is_written
                        or not ia32_memory_provably_disjoint(one, two)):
                    reasons.append("memory")
            if reasons:
                edges.append([left, right, sorted(reasons)])
    return facts, edges


def require_topological_instruction_order(
    count: int, edges: list[list], order: list[int], context: str,
) -> None:
    """The declared order must respect every edge of the DAG."""
    require(sorted(order) == list(range(count)),
            f"{context}: the target order is not a permutation of the window")
    position = {source: index for index, source in enumerate(order)}
    for left, right, reasons in edges:
        require(position[left] < position[right],
                f"{context}: the target order moves instruction {right} "
                f"before {left}, which the dependence DAG forbids "
                f"({', '.join(reasons)})")
    require(order != list(range(count)),
            f"{context}: the declared order does not reorder the window")


# The whole-body walk this class needs is WEAKER than the register-bijection
# decoder's: outside a window only lengths and control-flow targets matter, and
# demanding the register class's closed semantic table for every instruction of
# a 1,700-byte function would refuse bodies whose windows are perfectly
# analysable.  So the body is walked with the module's existing fail-closed
# LENGTH decoder -- the same one every instruction-mosaic class already trusts
# for boundary certification -- and the branch targets are read off a closed
# table of relative-transfer encodings.  An INDIRECT jump is refused outright:
# its targets are not statically knowable, so it could hide an entry into a
# window's interior.
_IA32_SCHEDULE_INTERIOR_PREFIXES = (
    _IA32_INERT_SEGMENT_PREFIXES | frozenset({_IA32_OPERAND_SIZE_PREFIX})
)


# A COMDAT that ends in a compiler-emitted switch table carries DATA after its
# last instruction, and decoding that data as instructions is nonsense.
# `code_length` pins where the code ends -- recovered from the dispatch's own
# `jmp dword ptr [reg*4 + BASE]` relocation, never from a walk that runs off
# the end -- and the tail is PROVED unreachable rather than assumed: the code
# must decode to exactly the pin with no straddling instruction, and its last
# instruction may not fall through into the tail.  These are the opcodes that
# end a basic block without falling through; anything else refuses.
_IA32_SCHEDULE_TERMINAL_OPCODES = frozenset({0xC2, 0xC3, 0xCA, 0xCB,
                                             0xE9, 0xEB})


def ia32_schedule_body_walk(
    body: bytes, relocations: dict | None, context: str,
    code_length: int | None = None,
    internal_targets: frozenset | None = None,
) -> tuple[list[tuple[int, int]], set]:
    """Boundaries and interior branch targets of a whole COMDAT body."""
    require(isinstance(body, (bytes, bytearray)) and body,
            f"{context}: body is empty")
    body = bytes(body)
    relocations = relocations or {}
    limit = len(body) if code_length is None else code_length
    require(isinstance(limit, int) and not isinstance(limit, bool)
            and 0 < limit <= len(body),
            f"{context}: code length is out of range")
    code = body[:limit]
    spans = []
    targets = set()
    computed = []
    offset = 0
    while offset < len(code):
        length = supported_ia32_instruction_length(
            code[offset:], f"{context} at {offset}")
        spans.append((offset, length))
        cursor = offset
        while code[cursor] in _IA32_SCHEDULE_INTERIOR_PREFIXES:
            cursor += 1
            require(cursor < offset + length,
                    f"{context}: instruction at {offset} is only prefixes")
        opcode = code[cursor]
        width = 0
        if opcode in range(0x70, 0x80) or opcode in (0xEB, 0xE0, 0xE1,
                                                     0xE2, 0xE3):
            width = 1
        elif opcode in (0xE9, 0xE8):
            width = 4
        elif opcode == 0x0F and cursor + 1 < offset + length \
                and 0x80 <= code[cursor + 1] <= 0x8F:
            width = 4
        elif opcode == 0xFF:
            require(cursor + 1 < offset + length,
                    f"{context}: FF form at {offset} lacks its ModRM")
            extension = (code[cursor + 1] >> 3) & 7
            require(extension not in (3, 5),
                    f"{context}: a far jump at {offset} makes the window's "
                    "entry set unknowable")
            if extension == 4:
                computed.append(offset)
        if width:
            displacement_at = offset + length - width
            row = relocations.get(displacement_at)
            if row is None or row.get("width") != width:
                relative = int.from_bytes(
                    code[displacement_at:offset + length],
                    "little", signed=True)
                targets.add(offset + length + relative)
        offset += length
    require(offset == len(code),
            f"{context}: body does not decode to exhaustion")
    starts = {start for start, _ in spans}
    for target in sorted(targets):
        require(target in starts,
                f"{context}: a branch targets {target}, which is not an "
                "instruction boundary of this body")
    if limit < len(body):
        last_at, last_length = spans[-1]
        cursor = last_at
        while code[cursor] in _IA32_SCHEDULE_INTERIOR_PREFIXES:
            cursor += 1
        opcode = code[cursor]
        terminal = opcode in _IA32_SCHEDULE_TERMINAL_OPCODES
        if opcode == 0xFF:
            terminal = ((code[cursor + 1] >> 3) & 7) == 4
        require(terminal,
                f"{context}: code falls through into the body's data tail")
    # A computed jump has no decodable successors, so the window's entry set
    # cannot be closed from the decoded graph alone.  The relocated in-body
    # label set -- every target a relocation in this body names inside this
    # same COMDAT -- closes it, and it must be SUPPLIED: a body with a
    # computed jump and no such set is refused rather than proved on an
    # incomplete graph.  Every one of those targets that lies inside the CODE
    # must be an instruction boundary of it; one that lies inside the pinned
    # data tail is the dispatch's own table base, which no control transfer
    # reaches, and is kept in the set anyway so the caller's entry check stays
    # conservative.
    if computed:
        require(internal_targets is not None,
                f"{context}: a computed jump at {computed[0]} makes the "
                "window's entry set unknowable without the relocated in-body "
                "target set")
        stray = sorted(target for target in internal_targets
                       if target < limit and target not in starts)
        require(not stray,
                f"{context}: the relocated in-body target {stray[:1]} is not "
                "an instruction boundary of this body")
        targets |= set(internal_targets)
    return spans, targets


def apply_instruction_schedule(
    body: bytes, windows: list[dict], relocation_offsets: frozenset,
    context: str, relocations: dict | None = None,
    code_length: int | None = None,
    internal_targets: frozenset | None = None,
) -> tuple[bytes, dict]:
    """Reorder each declared window under a proved dependence DAG.

    Obligations 2 through 6 are checked here, and the result is re-decoded to
    exhaustion so that every claim about the image is measured on the image.

    `code_length` pins where a switch-table body's code ends; the tail is
    never decoded, never inside a window and never rewritten.
    """
    body = bytes(body)
    limit = len(body) if code_length is None else code_length
    spans, targets = ia32_schedule_body_walk(
        body, relocations, context, code_length, internal_targets)
    instructions = [
        {"offset": start, "length": length} for start, length in spans]
    boundaries = {start for start, _ in spans}
    boundaries.add(limit)
    image = bytearray(body)
    detail = []
    previous_end = 0
    for index, window in enumerate(windows):
        window_context = f"{context} window {index}"
        start, end = window["start"], window["end"]
        require(start >= previous_end,
                f"{window_context}: windows are unsorted or overlapping")
        previous_end = end
        require(end <= limit,
                f"{window_context}: the window reaches into the body's data "
                "tail")
        require(start in boundaries and end in boundaries and start < end,
                f"{window_context}: the window does not span whole "
                "instructions")
        inside = [item for item in instructions
                  if start <= item["offset"] < end]
        require(inside
                and inside[-1]["offset"] + inside[-1]["length"] == end,
                f"{window_context}: the window does not end on an "
                "instruction boundary")
        require(len(inside) >= 2,
                f"{window_context}: a window needs at least two instructions")
        # Inside a window every instruction is decoded with the register
        # class's own closed semantic table, to exhaustion, so its complete
        # register read/write set and its memory operand are known exactly.
        inside = [
            decode_ia32_bijection_instruction(
                body, item["offset"],
                f"{window_context} at {item['offset']}", relocations)
            for item in inside
        ]
        require([item["offset"] + item["length"] for item in inside][-1] == end,
                f"{window_context}: the decoded window does not end on the "
                "window boundary")
        # Obligation 5.
        crossing = sorted(target for target in targets if start < target < end)
        require(not crossing,
                f"{window_context}: a branch targets the window interior at "
                f"{crossing}")
        # Obligation 6.  A window that carries no relocation still refuses
        # to touch one, exactly as before.  A window that DECLARES a reseat
        # must carry its relocations wholly inside single instructions, and
        # the reseat is then derived from the permutation and required to
        # equal the declaration -- the record moves with its own instruction
        # and by nothing else.  Its symbol, type, width and addend are
        # untouched (only the four offset bytes of the COFF record change),
        # and the installation is delegated to the existing
        # `equal_body_eh_reloc_layout` primitive, which already pairs the
        # tables by ordinal and proves target identity.
        overlapping = sorted(offset for offset in range(start, end)
                             if offset in relocation_offsets)
        declared_reseat = window.get("relocation_reseat")
        window_reseat = []
        if declared_reseat is None:
            require(not overlapping,
                    f"{window_context}: a relocation operand lies inside the "
                    f"window at {overlapping[:4]}; this class refuses to move "
                    "a relocation rather than reseat it approximately")
        else:
            require(overlapping,
                    f"{window_context}: a relocation reseat is declared but "
                    "no relocation operand lies inside the window")
            require(relocations,
                    f"{window_context}: a relocation reseat needs the "
                    "relocation records")
            lengths_in = [item["length"] for item in inside]
            starts_in = [item["offset"] for item in inside]
            seated = {}
            cursor = start
            for position in window["target_order"]:
                seated[position] = cursor
                cursor += lengths_in[position]
            for offset in sorted(relocations):
                record = relocations[offset]
                width = record["width"]
                if offset + width <= start or offset >= end:
                    require(
                        not (start < offset + width and offset < end),
                        f"{window_context}: a relocation straddles the "
                        f"window boundary at {offset}",
                    )
                    continue
                require(start <= offset and offset + width <= end,
                        f"{window_context}: a relocation straddles the "
                        f"window boundary at {offset}")
                position = next(
                    (index for index in range(len(inside))
                     if starts_in[index] <= offset
                     and offset + width <= starts_in[index]
                     + lengths_in[index]),
                    None,
                )
                require(position is not None,
                        f"{window_context}: the relocation at {offset} "
                        "straddles an instruction boundary")
                window_reseat.append(
                    [offset, seated[position] + (offset - starts_in[position])]
                )
            require(window_reseat == declared_reseat,
                    f"{window_context}: the measured relocation reseat "
                    f"{window_reseat} differs from its declaration")
        declared_stack = window.get("stack_adjustments")
        facts, edges = ia32_schedule_dependence_edges(
            inside, window_context, body, declared_stack is not None)
        require(edges == window["expected_dependence_edges"],
                f"{window_context}: the measured dependence DAG differs from "
                "its declaration")
        order = list(window["target_order"])
        require_topological_instruction_order(
            len(inside), edges, order, window_context)
        original = [bytes(body[item["offset"]:item["offset"] + item["length"]])
                    for item in inside]
        require([len(piece) for piece in original]
                == list(window["source_instruction_lengths"]),
                f"{window_context}: the window's instruction partition "
                "differs from its declaration")
        # Obligation 6c.  A push the permutation moves past an ESP-relative
        # operand shifts that operand's address by the push's own four bytes,
        # so the displacement is adjusted to name the SAME address.  The
        # adjustment set is DERIVED from the permutation and required to equal
        # the declaration; a window that declares none must need none.
        window_stack = ia32_schedule_stack_adjustments(
            body, inside, order, window_context)
        if declared_stack is None:
            require(not window_stack,
                    f"{window_context}: the permutation moves a push past an "
                    "ESP-relative operand but declares no stack adjustment")
        else:
            require(window_stack == declared_stack,
                    f"{window_context}: the measured stack adjustment "
                    f"{window_stack} differs from its declaration")
        pieces = [bytearray(piece) for piece in original]
        adjusted_spans = {}
        for index, at, _old_value, new_value in window_stack:
            found = ia32_esp_relative_displacement(body, inside[index])
            local = at - inside[index]["offset"]
            size = found[1]
            pieces[index][local:local + size] = new_value.to_bytes(
                size, "little", signed=True)
            adjusted_spans[index] = list(range(local, local + size))
        pieces = [bytes(piece) for piece in pieces]
        # Each piece is its ORIGINAL with only the declared displacement bytes
        # changed -- nothing else in the window may be rewritten.
        for index, (before_piece, after_piece) in enumerate(
                zip(original, pieces)):
            changed_bytes = [position
                             for position in range(len(before_piece))
                             if before_piece[position] != after_piece[position]]
            require(changed_bytes == adjusted_spans.get(index, []),
                    f"{window_context}: the instruction at "
                    f"{inside[index]['offset']} changed outside its declared "
                    "ESP displacement")
        reordered = b"".join(pieces[source] for source in order)
        # Obligation 3: the same bag of encoded instructions, so the same
        # total length.  Both halves are asserted, not assumed.
        require(sorted(pieces) == sorted(
                    reordered[offset:offset + length]
                    for offset, length in _instruction_spans(order, pieces)),
                f"{window_context}: the reordering is not a permutation of "
                "the window's own instructions")
        require(len(reordered) == end - start,
                f"{window_context}: the reordering changed the window length")
        image[start:end] = reordered
        detail.append({
            "start": start, "end": end,
            "relocation_reseat": window_reseat,
            "stack_adjustments": window_stack,
            "adjusted_instructions": sorted(pieces),
            "instruction_count": len(inside),
            "source_instruction_lengths": [len(piece) for piece in pieces],
            "target_order": order,
            "dependence_edges": edges,
            "memory_disambiguation": [
                {
                    "instruction": position,
                    "base": item["memory"]["base"],
                    "displacement": item["memory"]["displacement"],
                    "width": item["memory"]["width"],
                    "read": item["memory"]["read"],
                    "write": item["memory"]["write"],
                }
                for position, item in enumerate(facts)
                if item["memory"] is not None
            ],
        })
    image = bytes(image)
    require(len(image) == len(body),
            f"{context}: the reordering changed the body length")
    require(image != body, f"{context}: the reordering moves nothing")
    reseat = [pair for item in detail for pair in item["relocation_reseat"]]
    image_relocations = relocations
    if reseat:
        moved = dict(reseat)
        image_relocations = {
            moved.get(offset, offset): record
            for offset, record in (relocations or {}).items()
        }
        require(len(image_relocations) == len(relocations or {}),
                f"{context}: the reseat collides two relocation records")
    image_spans, _ = ia32_schedule_body_walk(
        image, image_relocations, f"{context} image", code_length,
        internal_targets)
    image_instructions = [
        {"offset": start, "length": length} for start, length in image_spans]
    window_spans = [(item["start"], item["end"]) for item in windows]

    def _in_window(offset):
        return any(start <= offset < end for start, end in window_spans)

    require(
        [(item["offset"], item["length"]) for item in image_instructions
         if not _in_window(item["offset"])]
        == [(item["offset"], item["length"]) for item in instructions
            if not _in_window(item["offset"])],
        f"{context}: the image moved an instruction boundary outside a "
        "declared window",
    )
    for (start, end), item in zip(window_spans, detail):
        # The bag the image must hold is the window's own instructions with
        # exactly the declared ESP adjustments applied -- identical to the
        # source bag whenever no push moved.
        before = item["adjusted_instructions"]
        after = sorted(image[position["offset"]:
                             position["offset"] + position["length"]]
                       for position in image_instructions
                       if start <= position["offset"] < end)
        require(before == after,
                f"{context}: window {start:#x} is not the same instruction "
                "multiset in the image")
    changed = sorted(index for index in range(len(body))
                     if body[index] != image[index])
    require(all(_in_window(offset) for offset in changed),
            f"{context}: the image changed a byte outside a declared window")
    for item in detail:
        item.pop("adjusted_instructions", None)
    return image, {
        "windows": detail,
        "instruction_count": len(instructions),
        "changed_offsets": changed,
        "relocation_reseat": reseat,
        "stack_adjustments": [pair for item in detail
                              for pair in item["stack_adjustments"]],
        "code_length": limit,
    }


def _instruction_spans(order: list[int], pieces: list[bytes]):
    """The (offset, length) spans the reordered pieces occupy."""
    cursor = 0
    for source in order:
        yield cursor, len(pieces[source])
        cursor += len(pieces[source])


def require_instruction_schedule_debug_fidelity(
    coff: "CoffObject", section: dict, image: bytes, windows: list[dict],
    spec: dict, mangled: str, context: str,
    relocations: dict | None = None,
    code_length: int | None = None,
    internal_targets: frozenset | None = None,
) -> dict:
    """Obligation 7: re-derive the line rows and the debug ranges.

    Every COFF line row is checked against the IMAGE's own instruction
    boundaries, the rows inside each window are pinned together with the
    source instruction that now begins at them, the CodeView procedure
    record's code length and debug range are pinned and required to stay
    clear of every window interior, and no closure-child relocation may name
    a code symbol whose value falls inside one.
    """
    spans, _ = ia32_schedule_body_walk(image, relocations,
                                       f"{context} image", code_length,
                                       internal_targets)
    boundaries = {start for start, _ in spans}
    boundaries.add(len(image) if code_length is None else code_length)
    index_of = {start: position for position, (start, _) in enumerate(spans)}
    line_bytes = _coff_table_bytes(coff, section, "lines")
    require(len(line_bytes) == section["line_count"] * 6
            and len(line_bytes) >= 12,
            f"{context}: the compiler line table is missing")
    marker_index, marker_line = coff_unpack(
        "<IH", line_bytes, 0, f"{context} line sentinel")
    function_index, _ = function_symbol(coff, mangled, section["number"])
    require(marker_line == 0 and marker_index == function_index,
            f"{context}: the compiler line sentinel differs")
    rows = []
    for position in range(1, section["line_count"]):
        offset, line = coff_unpack(
            "<IH", line_bytes, position * 6, f"{context} line row {position}")
        require(line != 0 and 0 <= offset < len(image),
                f"{context}: line row {position} is invalid")
        require(offset in boundaries,
                f"{context}: line row {position} at {offset:#x} is not an "
                "instruction boundary of the image")
        rows.append([offset, line])
    interior = []
    # A web-recolour certificate may declare a second, TRAILING phase of
    # windows -- reorderings its own recolour made legal.  Line fidelity is
    # measured over both phases at once, in the order they were applied.
    declared_windows = list(spec.get("windows") or []) \
        + list(spec.get("trailing_windows") or [])
    require(len(windows) == len(declared_windows),
            f"{context}: the window list differs from its declaration")
    for window, declared in zip(windows, declared_windows):
        start, end = window["start"], window["end"]
        order = list(window["target_order"])
        # For each line row INSIDE a window, name the SOURCE instruction that
        # now begins at it.  A reordering cannot move a source-line boundary
        # silently: the manifest states which instruction each interior row
        # now heads, and a different reordering changes that triple.
        attribution = [
            [offset, line, order[index_of[offset] - index_of[start]]]
            for offset, line in rows if start <= offset < end
        ]
        require(attribution == declared["expected_line_rows"],
                f"{context}: the line rows inside window {start:#x} differ "
                "from their declaration")
        interior.extend(attribution)
    child = _comdat_child(coff, section, ".debug$S")
    stream = coff_body(coff, child)
    records = parse_codeview_symbol_stream(stream, f"{context} debug$S")
    procedures = [record for record in records
                  if record["type"] in CODEVIEW_PROCEDURE_RECORD_TYPES]
    require(len(procedures) == 1,
            f"{context}: the .debug$S stream does not carry exactly one "
            "procedure record")
    record = procedures[0]
    code_length, debug_start, debug_end = coff_unpack(
        "<III", stream, record["offset"] + 16, f"{context} procedure record")
    require([code_length, debug_start, debug_end]
            == spec["expected_procedure_range"],
            f"{context}: the procedure record's code range differs from its "
            "declaration")
    require(code_length == len(image),
            f"{context}: the procedure record's code length is not the body")
    for name, value in (("debug_start", debug_start), ("debug_end", debug_end)):
        require(value in boundaries,
                f"{context}: the procedure record's {name} is not an "
                "instruction boundary of the image")
        require(not any(start < value < end
                        for start, end in [(item["start"], item["end"])
                                           for item in windows]),
                f"{context}: the procedure record's {name} falls inside a "
                "reordered window")
    values = {}
    for symbol in coff.symbols.values():
        if symbol["section"] == section["number"]:
            values[symbol["name"]] = symbol["value"]
    referenced = []
    for child_name in _comdat_child_closure(coff, section)[1]:
        sibling = _comdat_child(coff, section, child_name)
        for row in detailed_relocations(coff, sibling):
            if row["target"] in values:
                value = values[row["target"]]
                require(not any(start < value < end
                                for start, end in
                                [(item["start"], item["end"])
                                 for item in windows]),
                        f"{context}: {child_name} names the code symbol "
                        f"{row['target']} at {value:#x}, inside a reordered "
                        "window")
                referenced.append([child_name, row["target"], value])
    require(sorted(referenced) == sorted(spec["expected_code_symbol_references"]),
            f"{context}: the closure's code-symbol references differ from "
            "their declaration")
    return {
        "line_rows": len(rows),
        "window_line_rows": interior,
        "procedure_range": [code_length, debug_start, debug_end],
        "code_symbol_references": referenced,
    }


def _validate_schedule_windows(
    windows: list, context: str, body_length: int,
    code_length: int | None = None, targets: list | None = None,
) -> list[dict]:
    """Normalise a list of reordering windows.

    Shared by the instruction-schedule certificate and the web-recolour
    certificate, which applies the same reordering primitive before its own
    proof.
    """
    normalized_windows = []
    previous_end = 0
    for index, window in enumerate(windows):
        window_context = f"{context}.windows[{index}]"
        require(isinstance(window, dict),
                f"{window_context} must be an object")
        exact_audit_keys(window, {
            "start", "end", "source_instruction_lengths", "target_order",
            "expected_dependence_edges", "expected_line_rows",
            "relocation_reseat", "stack_adjustments",
        }, window_context, optional={"relocation_reseat",
                                     "stack_adjustments"})
        start = require_exact_int(window.get("start"),
                                  f"{window_context}.start",
                                  minimum=0, maximum=body_length - 1)
        end = require_exact_int(window.get("end"), f"{window_context}.end",
                                minimum=1, maximum=body_length)
        require(start >= previous_end and start < end,
                f"{window_context}: windows are unsorted, empty or "
                "overlapping")
        require(code_length is None or end <= code_length,
                f"{window_context}: the window reaches past the declared "
                "code length")
        require(targets is None
                or not any(start < item < end for item in targets),
                f"{window_context}: a relocated in-body target enters the "
                "window's interior")
        previous_end = end
        lengths = window.get("source_instruction_lengths")
        require(isinstance(lengths, list) and 2 <= len(lengths) <= 64
                and all(type(item) is int and 1 <= item <= 15
                        for item in lengths)
                and sum(lengths) == end - start,
                f"{window_context}.source_instruction_lengths differs")
        order = window.get("target_order")
        require(isinstance(order, list)
                and sorted(order) == list(range(len(lengths)))
                and order != list(range(len(lengths))),
                f"{window_context}.target_order is not a non-identity "
                "permutation")
        edges = window.get("expected_dependence_edges")
        require(isinstance(edges, list)
                and all(isinstance(edge, list) and len(edge) == 3
                        and type(edge[0]) is int and type(edge[1]) is int
                        and 0 <= edge[0] < edge[1] < len(lengths)
                        and isinstance(edge[2], list) and edge[2]
                        and edge[2] == sorted(set(edge[2]))
                        and all(reason in INSTRUCTION_SCHEDULE_EDGE_REASONS
                                for reason in edge[2])
                        for edge in edges)
                and [edge[:2] for edge in edges]
                == sorted(edge[:2] for edge in edges),
                f"{window_context}.expected_dependence_edges is invalid")
        line_rows = window.get("expected_line_rows")
        require(isinstance(line_rows, list)
                and all(isinstance(row, list) and len(row) == 3
                        and all(type(item) is int for item in row)
                        and start <= row[0] < end
                        and 0 <= row[2] < len(lengths)
                        for row in line_rows)
                and [row[0] for row in line_rows]
                == sorted({row[0] for row in line_rows}),
                f"{window_context}.expected_line_rows is invalid")
        # Obligation 6b (the reseat declaration).  A window that moves a
        # relocated operand must say so, and must say exactly where every one
        # of its relocations lands.  The pairs are (seed offset, image
        # offset); `apply_instruction_schedule` derives the same list from the
        # permutation itself and refuses on any disagreement, so this is a
        # declaration the measurement has to reproduce, not a free parameter.
        # Obligation 6c (the stack declaration).  A window whose permutation
        # moves a push past an ESP-relative operand must say, for every such
        # operand, exactly which displacement byte changes and from what to
        # what.  `ia32_schedule_stack_adjustments` DERIVES the same list from
        # the permutation and refuses on any disagreement, so this is a
        # declaration the measurement has to reproduce, not a free parameter.
        stack = window.get("stack_adjustments")
        normalized_stack = None
        if stack is not None:
            require(isinstance(stack, list) and 1 <= len(stack) <= 64
                    and all(isinstance(row, list) and len(row) == 4
                            and all(type(value) is int for value in row)
                            and 0 <= row[0] < len(lengths)
                            and start <= row[1] < end
                            and row[2] != row[3]
                            and abs(row[3] - row[2]) % 4 == 0
                            for row in stack)
                    and stack == sorted(stack)
                    and len({row[1] for row in stack}) == len(stack),
                    f"{window_context}.stack_adjustments is invalid")
            normalized_stack = [list(row) for row in stack]
        reseat = window.get("relocation_reseat")
        normalized_reseat = None
        if reseat is not None:
            require(isinstance(reseat, list) and 1 <= len(reseat) <= 64
                    and all(isinstance(pair, list) and len(pair) == 2
                            and all(type(item) is int for item in pair)
                            and start <= pair[0] < end
                            and start <= pair[1] < end
                            for pair in reseat)
                    and [pair[0] for pair in reseat]
                    == sorted({pair[0] for pair in reseat})
                    and len({pair[1] for pair in reseat}) == len(reseat)
                    and any(pair[0] != pair[1] for pair in reseat),
                    f"{window_context}.relocation_reseat is invalid")
            normalized_reseat = [list(pair) for pair in reseat]
        normalized_window = {
            "start": start, "end": end,
            "source_instruction_lengths": list(lengths),
            "target_order": list(order),
            "expected_dependence_edges": [
                [edge[0], edge[1], list(edge[2])] for edge in edges],
            "expected_line_rows": [list(row) for row in line_rows],
        }
        if normalized_reseat is not None:
            normalized_window["relocation_reseat"] = normalized_reseat
        if normalized_stack is not None:
            normalized_window["stack_adjustments"] = normalized_stack
        normalized_windows.append(normalized_window)
    return normalized_windows



def validate_web_recolour(
    value: object, context: str, body_length: int,
) -> dict:
    """Validate one web-recolour certificate declaration."""
    require(isinstance(value, dict), f"{context} must be an object")
    exact_audit_keys(value, {
        "kind", "windows", "webs", "expected_instruction_count",
        "expected_changed_offsets", "expected_procedure_range",
        "expected_code_symbol_references", "expected_debug_s_registers",
        "expected_code_length", "expected_internal_relocation_targets",
        "expected_fpo_record", "trailing_windows", "authenticity_rationale",
    }, context, optional={"windows", "trailing_windows",
                          "expected_code_length",
                          "expected_internal_relocation_targets",
                          "expected_fpo_record"})
    require(value.get("kind") == WEB_RECOLOUR_KIND,
            f"{context}.kind differs")
    code_length = value.get("expected_code_length")
    if code_length is not None:
        code_length = require_exact_int(
            code_length, f"{context}.expected_code_length",
            minimum=2, maximum=body_length)
    targets = value.get("expected_internal_relocation_targets")
    if targets is not None:
        require(isinstance(targets, list)
                and targets == sorted(set(targets))
                and all(type(item) is int and 0 <= item < body_length
                        for item in targets),
                f"{context}.expected_internal_relocation_targets is invalid")
    def _windows(key):
        if value.get(key) is None:
            return []
        windows = value[key]
        require(isinstance(windows, list) and 1 <= len(windows) <= 32,
                f"{context}.{key} must contain 1..32 windows")
        return _validate_schedule_windows(
            windows, f"{context}.{key}" if key != "windows" else context,
            body_length, code_length, targets)

    normalized_windows = _windows("windows")
    # A reordering may be legal only AFTER a recolour.  Site 2 of
    # `LegoAct2::SpawnBricks` is the case: retail hoists a `lea edx` above a
    # store that, in OUR colours, still reads edx -- an anti-dependence that
    # the recolour removes by moving that value to EBP.  Declaring such a
    # window here runs it on the recoloured image, where the dependence
    # graph the schedule proves against is the one that actually holds.
    normalized_trailing = _windows("trailing_windows")
    # The two phases are proved separately but the line-table fidelity check
    # sees one window list, so they may not overlap -- an offset reordered
    # twice has no single source instruction to map a line row through.
    for leading in normalized_windows:
        for trailing in normalized_trailing:
            require(leading["end"] <= trailing["start"]
                    or trailing["end"] <= leading["start"],
                    f"{context}: a trailing window overlaps a leading one")
    # EBP is a general register in a frame-pointer-free frame, and retail
    # colours webs into it.  It is admitted only against a PROVED FPO record
    # -- the same evidence the re-encoding bijection demands -- because that
    # is what says EBP is not holding the frame.  ESP is never admitted: a
    # rename to or from it is not a recolour but a change of addressing form.
    fpo_record = value.get("expected_fpo_record")
    if fpo_record is not None:
        require(isinstance(fpo_record, dict)
                and set(fpo_record) == FPO_RECORD_KEYS - {"raw_sha256"},
                f"{context}.expected_fpo_record is invalid")
        require(fpo_record.get("cbFrame") == FPO_FRAME_KIND_FPO
                and fpo_record.get("fHasSEH") == 0,
                f"{context}.expected_fpo_record does not declare a "
                "frame-pointer-free, SEH-free frame")
    structural = ({"esp"} if fpo_record is not None
                  else _IA32_STRUCTURAL_REGISTERS)
    webs = value.get("webs")
    require(isinstance(webs, list) and 1 <= len(webs) <= 32,
            f"{context}.webs must contain 1..32 webs")
    normalized_webs = []
    rewritten = []
    for index, web in enumerate(webs):
        web_context = f"{context}.webs[{index}]"
        require(isinstance(web, dict), f"{web_context} must be an object")
        exact_audit_keys(web, {
            "source_register", "image_register", "definitions", "uses",
            "expected_rewritten_offsets",
        }, web_context)
        source = web.get("source_register")
        image_register = web.get("image_register")
        require(source in _IA32_REGISTER_NUMBERS
                and image_register in _IA32_REGISTER_NUMBERS
                and source != image_register,
                f"{web_context} does not name two distinct general registers")
        require(not ({source, image_register} & structural),
                f"{web_context} touches "
                + ("ESP" if fpo_record is not None else "ESP or EBP"))
        # A membership entry is an instruction offset, or a two-element
        # [offset, field_ordinal] pair naming WHICH of that instruction's
        # register fields belongs to this web.  The scoped form is what lets
        # one instruction carry two webs -- `mov ecx,[ecx+8]` whose base
        # belongs to one web and whose destination to another -- and it makes
        # that case DECIDABLE rather than merely permitted.
        role_offsets = {}
        field_scopes = {}
        for role in ("definitions", "uses"):
            offsets, scopes = _ia32_web_membership(web, role, web_context)
            require(offsets == sorted(set(offsets))
                    and all(0 <= offset < (code_length or body_length)
                            for offset in offsets),
                    f"{web_context}.{role} is invalid")
            for offset, ordinal in scopes.items():
                require(offset not in field_scopes,
                        f"{web_context} scopes {offset} twice")
                field_scopes[offset] = ordinal
            role_offsets[role] = offsets
        require(not (set(role_offsets["definitions"])
                     & set(role_offsets["uses"])),
                f"{web_context}: an instruction is both a definition and a "
                "use")
        offsets = web.get("expected_rewritten_offsets")
        require(isinstance(offsets, list) and offsets
                and offsets == sorted(set(offsets))
                and len(offsets) == len(role_offsets["definitions"])
                + len(role_offsets["uses"])
                and all(type(item) is int
                        and 0 <= item < (code_length or body_length)
                        for item in offsets),
                f"{web_context}.expected_rewritten_offsets is invalid")
        rewritten.extend(offsets)
        normalized_webs.append({
            "source_register": source, "image_register": image_register,
            "definitions": list(role_offsets["definitions"]),
            "uses": list(role_offsets["uses"]),
            "field_scopes": dict(field_scopes),
            "expected_rewritten_offsets": list(offsets),
        })
    changed = value.get("expected_changed_offsets")
    require(isinstance(changed, list) and changed
            and changed == sorted(set(changed))
            and all(type(offset) is int
                    and (offset in rewritten
                         or any(item["start"] <= offset < item["end"]
                                for item in normalized_windows
                                + normalized_trailing))
                    for offset in changed),
            f"{context}.expected_changed_offsets is invalid")
    require(set(rewritten) <= set(changed),
            f"{context}.expected_changed_offsets omits a recoloured byte")
    procedure = value.get("expected_procedure_range")
    require(isinstance(procedure, list) and len(procedure) == 3
            and all(type(item) is int and item >= 0 for item in procedure)
            and procedure[0] == body_length
            and procedure[1] <= procedure[2] <= body_length,
            f"{context}.expected_procedure_range is invalid")
    references = value.get("expected_code_symbol_references")
    require(isinstance(references, list)
            and all(isinstance(item, list) and len(item) == 3
                    and isinstance(item[0], str) and isinstance(item[1], str)
                    and type(item[2]) is int and 0 <= item[2] <= body_length
                    for item in references),
            f"{context}.expected_code_symbol_references is invalid")
    registers = value.get("expected_debug_s_registers")
    require(isinstance(registers, list)
            and all(isinstance(item, list) and len(item) == 3
                    and isinstance(item[0], str)
                    and type(item[1]) is int and item[1] >= 0
                    and item[2] in CODEVIEW_X86_REGISTER_NUMBERS
                    for item in registers),
            f"{context}.expected_debug_s_registers is invalid")
    rationale = value.get("authenticity_rationale")
    require(isinstance(rationale, str) and len(rationale) >= 40,
            f"{context}.authenticity_rationale is missing")
    normalized = {
        "kind": WEB_RECOLOUR_KIND,
        "webs": normalized_webs,
        "expected_instruction_count": require_exact_int(
            value.get("expected_instruction_count"),
            f"{context}.expected_instruction_count", minimum=2),
        "expected_changed_offsets": list(changed),
        "expected_procedure_range": list(procedure),
        "expected_code_symbol_references": [list(item)
                                            for item in references],
        "expected_debug_s_registers": [list(item) for item in registers],
        "authenticity_rationale": rationale,
    }
    if normalized_windows:
        normalized["windows"] = normalized_windows
    if normalized_trailing:
        normalized["trailing_windows"] = normalized_trailing
    if code_length is not None:
        normalized["expected_code_length"] = code_length
    if targets is not None:
        normalized["expected_internal_relocation_targets"] = list(targets)
    return normalized


def compose_retail_exact_web_recolour(
    seed_bytes: bytes,
    donor_bytes: bytes,
    function: dict,
    retail_body: bytes,
) -> tuple[bytes, dict]:
    """Install a recoloured def-use web after proving it is retail's own code.

    See the class comment above.  The pre-image is the SEED's own
    compiler-produced body -- no donor bytes are installed, and the donor the
    manifest names is required to reproduce that body exactly, which is what
    makes it a provenance witness rather than decoration.  A declared
    reordering is applied first through the unchanged
    `apply_instruction_schedule` primitive; every web obligation is then
    measured on the reordered body.  The result is refused unless it equals
    the pinned retail oracle under the relocation mask, and installation is
    delegated, unchanged, to the equal-body primitive.
    """
    require(function.get("splice_class") == WEB_RECOLOUR_CLASS,
            "splice class is not retail_exact_web_recolour")
    require("target_source_refactor" not in function,
            "web-recolour functions carry no source refactor")
    require(isinstance(retail_body, (bytes, bytearray)) and retail_body,
            "retail oracle body is missing")
    spec = function["web_recolour"]
    seed = CoffObject(seed_bytes)
    donor = CoffObject(donor_bytes)
    mangled = function["mangled"]
    sp = seed.function_section(mangled)
    dp = donor.function_section(mangled)
    require(sp["number"] == dp["number"]
            == function["expected_section_number"],
            "web-recolour target section seat changed")
    require(len(seed.sections) == len(donor.sections)
            == function["expected_section_count"],
            "web-recolour global section count changed")
    seed_functions = function_multiset(seed)
    require(seed_functions == function_multiset(donor)
            and sum(seed_functions.values())
            == function["expected_function_count"],
            "web-recolour donor function set differs")
    seed_comdats = comdat_primary_identity_multiset(seed)
    require(seed_comdats == comdat_primary_identity_multiset(donor)
            and sum(seed_comdats.values())
            == function["expected_comdat_count"],
            "web-recolour donor COMDAT identity set differs")
    require(
        sp["raw_size"] == dp["raw_size"] == function["expected_body_length"]
        and sp["relocation_count"] == dp["relocation_count"]
        == function["expected_relocation_count"]
        and sp["line_count"] == function["expected_seed_line_count"]
        and dp["line_count"] == function["expected_donor_line_count"]
        and sp["name"] == dp["name"]
        and sp["characteristics"] == dp["characteristics"]
        == function["expected_characteristics"],
        "web-recolour target header/count pins changed",
    )
    require(
        section_definitions(seed)[sp["number"]]["selection"]
        == section_definitions(donor)[dp["number"]]["selection"]
        == function["expected_selection"],
        "web-recolour COMDAT selection changed",
    )
    expected_closure = tuple(function["expected_closure"])
    require(_comdat_child_closure(seed, sp)
            == _comdat_child_closure(donor, dp)
            == (len(expected_closure), expected_closure),
            "web-recolour target closure changed")
    require(list(expected_closure) == INSTRUCTION_SCHEDULE_FPO_CLOSURE,
            "web-recolour closure pin names no installation delegate")
    require(instruction_mosaic_metadata_sha256(seed, sp)
            == function["expected_seed_metadata_sha256"]
            and instruction_mosaic_metadata_sha256(donor, dp)
            == function["expected_donor_metadata_sha256"],
            "web-recolour metadata differs from its pin")
    seed_body = coff_body(seed, sp)
    donor_body = coff_body(donor, dp)
    require(sha256_bytes(seed_body) == function["expected_seed_body_sha256"]
            and sha256_bytes(donor_body)
            == function["expected_donor_body_sha256"],
            "web-recolour seed/donor body differs from its pin")
    # The donor is a provenance WITNESS: an independent compiler state that
    # emits this same body.  It is never installed, so it must reproduce the
    # seed's body exactly or the pin it carries means nothing.
    require(donor_body == seed_body,
            "web-recolour donor does not reproduce the seed's body")

    seed_rows = detailed_relocations(seed, sp)
    relocation_offsets = frozenset(
        row["offset"] + byte
        for row in seed_rows for byte in range(row["width"]))
    relocation_symbols = {
        row["offset"]: {"width": row["width"], "target": row["target"]}
        for row in seed_rows}
    internal_targets = frozenset(
        row["target_value"] for row in seed_rows
        if row["target_section"] == sp["number"])
    declared_targets = spec.get("expected_internal_relocation_targets")
    if declared_targets is not None:
        require(sorted(internal_targets) == declared_targets,
                "web-recolour in-body relocated target set changed")
    code_length = spec.get("expected_code_length")

    def _schedule(windows, phase):
        nonlocal image
        if not windows:
            return []
        image, schedule_proof = apply_instruction_schedule(
            image, windows, relocation_offsets, f"web-recolour {phase}",
            relocation_symbols, code_length, internal_targets)
        require(not schedule_proof["relocation_reseat"],
                "web-recolour refuses to move a relocation")
        return schedule_proof["windows"]

    image = seed_body
    schedule_detail = _schedule(spec.get("windows") or [], "schedule")
    # When any web names EBP the declaration must carry an FPO record, and it
    # is PROVED here against the seed's own `.debug$F` and decoded body before
    # a single field is rewritten.
    declared_fpo = spec.get("expected_fpo_record")
    names_ebp = any("ebp" in {web.get("source_register"),
                             web.get("image_register")}
                    for web in spec["webs"])
    require(declared_fpo is not None or not names_ebp,
            "web-recolour names EBP without a frame-pointer-free record")
    if declared_fpo is not None:
        measured = require_frame_pointer_free_frame(
            seed, sp, seed_body,
            decode_ia32_bijection_body(seed_body, "web-recolour frame proof",
                                       relocation_symbols, code_length),
            "web-recolour frame proof")
        require({key: value for key, value in measured.items()
                 if key != "raw_sha256"} == declared_fpo,
                "web-recolour FPO record differs from its declaration")
    image, proof = apply_web_recolour(
        image, spec["webs"], relocation_offsets, "web-recolour image",
        relocation_symbols, code_length, internal_targets,
        declared_fpo is not None)
    require(proof["code_length"] == (code_length or len(seed_body)),
            "web-recolour code length differs from its pin")
    require(proof["instruction_count"] == spec["expected_instruction_count"],
            "web-recolour instruction count differs from its declaration")
    # A window whose legality the recolour ESTABLISHED runs here, on the
    # recoloured image, and is proved by the unchanged schedule primitive.
    schedule_detail = schedule_detail + _schedule(
        spec.get("trailing_windows") or [], "trailing schedule")
    changed = sorted(index for index in range(len(seed_body))
                     if seed_body[index] != image[index])
    require(changed == spec["expected_changed_offsets"],
            "web-recolour image differs from its declaration")
    require(sha256_bytes(image) == function["expected_body_sha256"],
            "web-recolour image differs from its pin")
    require(changed == function["expected_changed_offsets"],
            "web-recolour changed offsets differ from their pin")

    # Obligation 7, measured on the IMAGE with the SEED's own tables -- which
    # are the tables this composition installs, unchanged.
    debug_detail = require_instruction_schedule_debug_fidelity(
        seed, sp, image,
        (spec.get("windows") or []) + (spec.get("trailing_windows") or []),
        spec, mangled,
        "web-recolour debug fidelity", relocation_symbols, code_length,
        internal_targets,
    )
    debug_registers = require_web_recolour_debug_registers(
        coff_body(seed, _comdat_child(seed, sp, ".debug$S")),
        spec["expected_debug_s_registers"], "web-recolour debug registers")

    pinned_length = function["retail_oracle"]["length"]
    require(len(retail_body) == pinned_length == len(image),
            "web-recolour retail length changed")
    semantic_detail = require_retail_relocation_oracle(
        seed_rows, bytes(retail_body),
        int(function["retail_oracle"]["address"], 16),
        function["retail_relocations"],
        "web-recolour retail relocation oracle",
    )
    masked_image = bytearray(image)
    masked_retail = bytearray(retail_body)
    for row in seed_rows:
        start, width = row["offset"], row["width"]
        masked_image[start:start + width] = b"\0" * width
        masked_retail[start:start + width] = b"\0" * width
    differing = sum(left != right
                    for left, right in zip(masked_image, masked_retail))
    require(differing == 0,
            f"web-recolour output is not retail-exact: {differing} byte(s) "
            "differ under the relocation mask")

    derived = bytearray(seed_bytes)
    derived[sp["raw_offset"]:sp["raw_offset"] + sp["raw_size"]] = image
    effective = {
        "mangled": mangled,
        "splice_class": "equal_body_strict",
        "expected_body_length": function["expected_body_length"],
        "expected_body_sha256": function["expected_body_sha256"],
        "expected_changed_offsets": function["expected_changed_offsets"],
    }
    composed, detail = compose_equal_body_comdat(
        seed_bytes, bytes(derived), effective)

    checked = CoffObject(composed)
    cp = checked.function_section(mangled)
    require(coff_body(checked, cp) == image,
            "web-recolour composed body differs from the image")
    require(detailed_relocations(checked, cp) == seed_rows
            and _coff_table_bytes(checked, cp, "relocations")
            == _coff_table_bytes(seed, sp, "relocations")
            and _coff_table_bytes(checked, cp, "lines")
            == _coff_table_bytes(seed, sp, "lines"),
            "web-recolour output changed seed relocation/line bytes")
    for child_name in expected_closure:
        require(coff_body(checked, _comdat_child(checked, cp, child_name))
                == coff_body(seed, _comdat_child(seed, sp, child_name)),
                f"web-recolour output changed its {child_name} child")
    allowed = set(range(sp["raw_offset"], sp["raw_offset"] + sp["raw_size"]))
    require({index for index in range(len(seed_bytes))
             if seed_bytes[index] != composed[index]} <= allowed,
            "web-recolour changed bytes outside its own COMDAT")
    return composed, {
        **detail,
        "splice_class": WEB_RECOLOUR_CLASS,
        "instruction_schedule": schedule_detail,
        "web_recolour": proof["webs"],
        "instruction_count": proof["instruction_count"],
        "changed_offsets": changed,
        "debug_fidelity": debug_detail,
        "debug_s_registers": debug_registers,
        "retail_exact": True,
        **semantic_detail,
    }


def validate_instruction_schedule(
    value: object, context: str, body_length: int,
) -> dict:
    """Validate one instruction-schedule certificate declaration."""
    require(isinstance(value, dict), f"{context} must be an object")
    exact_audit_keys(value, {
        "kind", "windows", "expected_instruction_count",
        "expected_changed_offsets", "expected_procedure_range",
        "expected_code_symbol_references", "authenticity_rationale",
        "expected_code_length", "expected_internal_relocation_targets",
    }, context, optional={"expected_code_length",
                          "expected_internal_relocation_targets"})
    require(value.get("kind") == INSTRUCTION_SCHEDULE_KIND,
            f"{context}.kind differs")
    # A COMDAT that ends in a compiler-emitted switch table carries DATA after
    # its last instruction.  `expected_code_length` pins where the code ends;
    # the tail is never decoded, never inside a window and never rewritten,
    # and `ia32_schedule_body_walk` proves the code cannot fall through into
    # it.  The in-body relocated target set is what closes the "no branch
    # enters a window's interior" obligation for a computed jump.
    code_length = value.get("expected_code_length")
    if code_length is not None:
        code_length = require_exact_int(
            code_length, f"{context}.expected_code_length",
            minimum=2, maximum=body_length)
    targets = value.get("expected_internal_relocation_targets")
    if targets is not None:
        require(isinstance(targets, list)
                and targets == sorted(set(targets))
                and all(type(item) is int and 0 <= item < body_length
                        for item in targets),
                f"{context}.expected_internal_relocation_targets is invalid")
    windows = value.get("windows")
    require(isinstance(windows, list) and 1 <= len(windows) <= 32,
            f"{context}.windows must contain 1..32 windows")
    normalized_windows = _validate_schedule_windows(
        windows, context, body_length, code_length, targets)
    changed = value.get("expected_changed_offsets")
    require(isinstance(changed, list) and changed
            and changed == sorted(set(changed))
            and all(type(offset) is int
                    and any(item["start"] <= offset < item["end"]
                            for item in normalized_windows)
                    for offset in changed),
            f"{context}.expected_changed_offsets is invalid")
    procedure = value.get("expected_procedure_range")
    require(isinstance(procedure, list) and len(procedure) == 3
            and all(type(item) is int and item >= 0 for item in procedure)
            and procedure[0] == body_length
            and procedure[1] <= procedure[2] <= body_length,
            f"{context}.expected_procedure_range is invalid")
    references = value.get("expected_code_symbol_references")
    require(isinstance(references, list)
            and all(isinstance(item, list) and len(item) == 3
                    and isinstance(item[0], str) and isinstance(item[1], str)
                    and type(item[2]) is int and 0 <= item[2] <= body_length
                    for item in references),
            f"{context}.expected_code_symbol_references is invalid")
    rationale = value.get("authenticity_rationale")
    require(isinstance(rationale, str) and len(rationale) >= 40,
            f"{context}.authenticity_rationale is missing")
    normalized = {
        "kind": INSTRUCTION_SCHEDULE_KIND,
        "windows": normalized_windows,
        "expected_instruction_count": require_exact_int(
            value.get("expected_instruction_count"),
            f"{context}.expected_instruction_count", minimum=2),
        "expected_changed_offsets": list(changed),
        "expected_procedure_range": list(procedure),
        "expected_code_symbol_references": [list(item)
                                            for item in references],
        "authenticity_rationale": rationale,
    }
    if code_length is not None:
        normalized["expected_code_length"] = code_length
    if targets is not None:
        normalized["expected_internal_relocation_targets"] = list(targets)
    return normalized


# ---------------------------------------------------------------------------
# The web-recolour CERTIFICATE.
#
# `retail_exact_register_bijection` proves its case by permuting the register
# FILE: a bijection sigma is an isomorphism of machine states, so once sigma's
# support is dead at the region's boundary every instruction's semantics carry
# over for free.  Retail sometimes differs from us by a map that is NOT a
# bijection -- one architectural register's occurrences go to a register that
# another value already occupies elsewhere.  That is a live-range COALESCE,
# not a relabelling, and the bijection's argument does not reach it: two
# distinct live ranges become one, which is sound only if they are provably
# NON-OVERLAPPING.
#
# So this class proves exactly that, and nothing weaker.  It renames one
# def-use WEB -- a set of definitions and the uses they reach, closed in both
# directions under the body's own control flow -- from a source register to an
# image register, having first proved:
#
#   W1  the body decodes to exhaustion under the closed semantic table, its
#       control-flow graph is complete (a computed jump is admitted only
#       against the pinned relocated in-body target set), and EVERY
#       instruction is reachable from the entry, so no part of the function is
#       analysed on a disconnected graph;
#   W2  neither register is esp/ebp, no rewritten field is a sub-register
#       field, and each rewritten instruction names the source register in
#       EXACTLY ONE register field -- so every appearance of it in that
#       instruction's read/write sets traces to the field being rewritten;
#   W3  the web is DERIVED, not declared: every use a declared definition
#       reaches is declared, and every definition that reaches a declared use
#       is declared.  A partial (sub-register) redefinition inside the range
#       refuses, and a use the function's entry reaches -- an undefined value
#       -- refuses;
#   W4  THE COALESCE OBLIGATION.  Over the web's whole live range the image
#       register carries no live value: it is dead on every out-edge of every
#       definition, and no instruction strictly inside the range reads it,
#       writes it, or has it live on entry.  The two ranges therefore ABUT and
#       never overlap, which is what makes merging them sound;
#   W5  with the web's own uses blinded, the source register is dead on every
#       out-edge of every definition -- so the web has no consumer outside
#       itself and removing its definitions strands nothing;
#   W6  no rewritten byte overlaps a relocation operand;
#   W7  the image re-decodes to the same instruction boundaries, opcodes,
#       flow and branch targets, and each rewritten instruction's read/write
#       sets are exactly the source sets with the rename applied;
#   W8  the `.debug$S` S_REGISTER record list is pinned and unchanged.  W4 and
#       W5 together are what make that sound rather than an author's claim: no
#       value of EITHER register is live across the web's range, so no named
#       register local can be the web, and none can survive a definition.
#
# A reordering may be declared alongside, and is applied FIRST through the
# unchanged `apply_instruction_schedule` primitive -- because a coalesce is
# often only legal AFTER the schedule that separates the two ranges.  Every
# web obligation is then measured on the reordered body, which is the body the
# composition installs.  If neither order has a legal intermediate, the class
# refuses; that is the correct answer and it is what retires a candidate.
#
# The pre-image is the SEED's own compiler-produced body: this class installs
# no donor bytes at all.  The donor the manifest names is a provenance witness
# and is required to reproduce the seed's body exactly.
# ---------------------------------------------------------------------------

WEB_RECOLOUR_CLASS = "retail_exact_web_recolour"
WEB_RECOLOUR_KIND = "web_recolour_v1"


def ia32_web_control_flow(
    instructions: list[dict], context: str,
    internal_targets: frozenset | None = None,
) -> list[list[int]]:
    """The body's complete control-flow graph, or a refusal.

    Successors are the fall-through and the decoded branch target.  A computed
    jump has no decodable successors, so it is admitted only against the
    relocated in-body target set, whose in-code members become its successors.
    `ret` and a relocated tail-jump out of the COMDAT have none.  Every
    instruction must then be reachable from the entry: an unreachable block
    would make every reaching-definition statement about it vacuous.
    """
    index_of = {item["offset"]: index
                for index, item in enumerate(instructions)}
    successors = []
    for index, item in enumerate(instructions):
        edges = []
        if item["flow"] in ("fall", "jcc", "call"):
            if index + 1 < len(instructions):
                edges.append(index + 1)
            else:
                require(item["flow"] != "fall",
                        f"{context}: body falls off its end")
        if item["flow"] in ("jcc", "jmp") and item["target"] is not None:
            edges.append(index_of[item["target"]])
        if item["indirect"]:
            require(internal_targets is not None,
                    f"{context}: a computed jump at {item['offset']} requires "
                    "the relocated in-body target set")
            edges.extend(index_of[target] for target in sorted(internal_targets)
                         if target in index_of)
        successors.append(sorted(set(edges)))
    seen = set()
    stack = [0]
    while stack:
        index = stack.pop()
        if index in seen:
            continue
        seen.add(index)
        stack.extend(successors[index])
    unreachable = sorted(instructions[index]["offset"]
                         for index in range(len(instructions))
                         if index not in seen)
    require(not unreachable,
            f"{context}: the instruction at {unreachable[:1]} is unreachable "
            "from the entry, so the control-flow graph is incomplete")
    return successors


def _ia32_web_predecessors(successors: list[list[int]]) -> list[list[int]]:
    predecessors = [[] for _ in successors]
    for index, edges in enumerate(successors):
        for edge in edges:
            predecessors[edge].append(index)
    return predecessors


def _ia32_web_reached_uses(
    instructions: list[dict], successors: list[list[int]],
    definitions: list[int], atoms: frozenset, context: str,
) -> tuple[set, set]:
    """Every reader of `atoms` a definition reaches, and the range between.

    Traversal stops at a full redefinition.  A PARTIAL redefinition inside the
    range refuses: the value would be half the web's and half something else,
    which no rename can express.
    """
    reached = set()
    interior = set()
    stack = [edge for index in definitions for edge in successors[index]]
    while stack:
        index = stack.pop()
        if index in interior:
            continue
        interior.add(index)
        item = instructions[index]
        if atoms & item["read_atoms"]:
            reached.add(index)
        overlap = atoms & item["write_atoms"]
        if overlap:
            require(atoms <= item["write_atoms"],
                    f"{context}: the instruction at {item['offset']} "
                    "partially redefines the web's register inside its range")
            continue
        stack.extend(successors[index])
    return reached, interior


def _ia32_web_reaching_definitions(
    instructions: list[dict], predecessors: list[list[int]],
    uses: list[int], atoms: frozenset, context: str,
) -> tuple[set, set]:
    """Every definition of `atoms` that reaches one of `uses`.

    Also returns the backward cone -- every instruction that can reach a use
    without passing a redefinition.  Intersected with the forward cone that
    is the web's LIVE RANGE, and nothing outside it is the coalesce's concern.
    """
    reaching = set()
    seen = set()
    stack = list(uses)
    while stack:
        index = stack.pop()
        if index in seen:
            continue
        seen.add(index)
        require(index != 0 or index in uses,
                f"{context}: the function's entry reaches a declared use, so "
                "the web's value is not defined on every path")
        for previous in predecessors[index]:
            item = instructions[previous]
            if atoms & item["write_atoms"]:
                require(atoms <= item["write_atoms"],
                        f"{context}: the instruction at {item['offset']} "
                        "partially defines the web's register")
                reaching.add(previous)
            else:
                stack.append(previous)
        require(predecessors[index] or index in uses,
                f"{context}: the instruction at {instructions[index]['offset']}"
                " has no predecessor, so a use is reached by no definition")
    return reaching, seen


def _ia32_web_membership(web: dict, role: str, context: str) -> tuple:
    """Split a web's membership list into offsets and their field scopes.

    An entry is an instruction offset, or a two-element `[offset, ordinal]`
    pair naming WHICH register field of that instruction belongs to the web.
    Both the manifest schema and the composer read membership through here,
    so a declaration means the same thing on both sides -- the composer is
    handed the RAW manifest dict, and a normalizer that lived only in the
    schema would be silently bypassed.
    """
    entries = web.get(role)
    require(isinstance(entries, list) and entries,
            f"{context}.{role} is invalid")
    offsets = []
    scopes = {}
    for item in entries:
        if type(item) is int:
            offsets.append(item)
            continue
        require(isinstance(item, list) and len(item) == 2
                and type(item[0]) is int and type(item[1]) is int
                and item[1] >= 0,
                f"{context}.{role} entry is invalid")
        require(item[0] not in scopes, f"{context}.{role} scopes {item[0]} "
                "twice")
        scopes[item[0]] = item[1]
        offsets.append(item[0])
    declared = web.get("field_scopes") or {}
    for offset, ordinal in declared.items():
        offset = int(offset)
        require(offset not in scopes or scopes[offset] == ordinal,
                f"{context}.{role} scopes {offset} twice")
        if offset in offsets:
            scopes[offset] = ordinal
    return offsets, scopes


def apply_web_recolour(
    body: bytes, webs: list[dict], relocation_offsets: frozenset,
    context: str, relocations: dict | None = None,
    code_length: int | None = None,
    internal_targets: frozenset | None = None,
    frame_pointer_free: bool = False,
) -> tuple[bytes, dict]:
    """Recolour each declared web, proving W1..W7 on the body it is given.

    Webs are applied in order and each one's proof is measured on the body the
    previous ones produced, so a certificate that declares several is a
    composition of individually proved steps.
    """
    body = bytes(body)
    image = bytes(body)
    detail = []
    rewritten_all = []
    instruction_count = None
    for position, web in enumerate(webs):
        web_context = f"{context} web {position}"
        instructions = decode_ia32_bijection_body(
            image, web_context, relocations, code_length)
        instruction_count = len(instructions)
        successors = ia32_web_control_flow(
            instructions, web_context, internal_targets)
        predecessors = _ia32_web_predecessors(successors)
        index_of = {item["offset"]: index
                    for index, item in enumerate(instructions)}
        source = web["source_register"]
        target = web["image_register"]
        # W2.
        require(source in _IA32_REGISTER_NUMBERS
                and target in _IA32_REGISTER_NUMBERS and source != target,
                f"{web_context}: the recolour names an unknown register")
        # EBP carries ModRM structure -- `mod=00, r/m=101` is a bare disp32,
        # not `[ebp]` -- so a rename into or out of it can change the
        # ADDRESSING FORM rather than just the register.  It is admitted only
        # when the caller has discharged the frame-pointer-free obligation,
        # and the encoding hazard is then caught where every other claim
        # about the image is: W7 re-decodes the result to exhaustion and
        # refuses any changed instruction boundary or operand set, which is
        # exactly what a silently reinterpreted ModRM would produce.  ESP
        # stays refused: `r/m=100` means a SIB byte follows, and a rename to
        # or from the stack pointer is not a recolour at all.
        structural = ({"esp"} if frame_pointer_free
                      else _IA32_STRUCTURAL_REGISTERS)
        require(not ({source, target} & structural),
                f"{web_context}: the recolour touches "
                + ("ESP" if frame_pointer_free else "ESP or EBP")
                + ", whose encodings carry ModRM/SIB structure")
        source_atoms = ia32_register_atoms({source})
        target_atoms = ia32_register_atoms({target})
        source_number = _IA32_REGISTER_NUMBERS[source]
        target_number = _IA32_REGISTER_NUMBERS[target]
        # An entry may name WHICH register field of its instruction belongs
        # to this web.  A scoped entry is what makes an instruction that names
        # the source register twice -- `mov ecx,[ecx+8]`, whose base is one
        # web's use and whose destination is another's definition -- decidable
        # instead of ambiguous.  Nothing about the dataflow proofs changes:
        # W3 already stops propagating at a read-then-kill instruction and the
        # W5 blinding already subtracts the read before the write.  What the
        # scope removes is only the refusal to DECIDE, and W7 below re-earns
        # that by measuring the field-exact operand image.
        definition_offsets, field_scopes = _ia32_web_membership(
            web, "definitions", web_context)
        use_offsets, use_scopes = _ia32_web_membership(
            web, "uses", web_context)
        for offset, ordinal in use_scopes.items():
            require(offset not in field_scopes,
                    f"{web_context} scopes {offset} twice")
            field_scopes[offset] = ordinal
        for role, offsets in (("definitions", definition_offsets),
                              ("uses", use_offsets)):
            for offset in offsets:
                require(offset in index_of,
                        f"{web_context}: {role} names {offset}, which is not "
                        "an instruction boundary of this body")
        definitions = [index_of[offset] for offset in definition_offsets]
        uses = [index_of[offset] for offset in use_offsets]
        require(not (set(definitions) & set(uses)),
                f"{web_context}: an instruction is both a definition and a "
                "use of the web")
        for index in definitions:
            item = instructions[index]
            require(source_atoms <= item["write_atoms"],
                    f"{web_context}: the declared definition at "
                    f"{item['offset']} does not define the whole register")
            # A definition that also READS the source register consumes some
            # other value of it, so which occurrence belongs to the web is not
            # decidable and the rename would change what the instruction
            # computes -- unless the entry says which field is the definition,
            # in which case the read is another web's use and stays put.
            require(not (source_atoms & item["read_atoms"])
                    or item["offset"] in field_scopes,
                    f"{web_context}: the declared definition at "
                    f"{item['offset']} also reads the source register")
            require(target not in item["writes"],
                    f"{web_context}: the declared definition at "
                    f"{item['offset']} already writes the image register")
        for index in uses:
            item = instructions[index]
            # Likewise a use that also DEFINES the source register: the read
            # is this web's, the write begins the next one, and only a scoped
            # entry says so.  The read obligation itself never relaxes.
            require(source_atoms <= item["read_atoms"]
                    and (not (source_atoms & item["write_atoms"])
                         or item["offset"] in field_scopes),
                    f"{web_context}: the declared use at {item['offset']} "
                    "does not read the whole register without defining it")
            # A use that already names the image register would, after the
            # rename, read one value where it read two.
            require(target not in item["reads"]
                    and target not in item["writes"],
                    f"{web_context}: the declared use at {item['offset']} "
                    "already names the image register")
        # W3.  Both closure directions, derived from the graph.
        reached, forward = _ia32_web_reached_uses(
            instructions, successors, definitions, source_atoms, web_context)
        require(reached == set(uses),
                f"{web_context}: the definitions reach the uses at "
                f"{sorted(instructions[index]['offset'] for index in reached)}"
                ", which is not the declared use set")
        reaching, backward = _ia32_web_reaching_definitions(
            instructions, predecessors, uses, source_atoms, web_context)
        require(reaching == set(definitions),
                f"{web_context}: the uses are reached by the definitions at "
                f"{sorted(instructions[index]['offset'] for index in reaching)}"
                ", which is not the declared definition set")
        # The live range: on a path from a definition to a use, both cones.
        interior = (forward & backward) | set(uses)
        # W4.  The coalesce obligation, on the web's own live range.
        live = _ia32_backward_liveness(instructions, successors, web_context)
        for index in definitions:
            leaking = target_atoms & _ia32_live_out(live, successors, index)
            require(not leaking,
                    f"{web_context}: {_ia32_atom_registers(leaking)} is live "
                    f"on an out-edge of the definition at "
                    f"{instructions[index]['offset']}, so the two live ranges "
                    "overlap and cannot be coalesced")
        for index in sorted(interior):
            item = instructions[index]
            if index in uses:
                require(not (target_atoms & item["write_atoms"]),
                        f"{web_context}: the use at {item['offset']} defines "
                        "the image register")
                continue
            touching = target_atoms & (item["read_atoms"] | item["write_atoms"])
            require(not touching,
                    f"{web_context}: the instruction at {item['offset']} "
                    f"names {_ia32_atom_registers(touching)} inside the web's "
                    "live range")
            leaking = target_atoms & live[index]
            require(not leaking,
                    f"{web_context}: {_ia32_atom_registers(leaking)} is live "
                    f"at {item['offset']}, inside the web's live range")
        # W5.  With the web's own uses blinded, the source register must be
        # dead out of every definition -- so the web has no outside consumer.
        blind = _ia32_backward_liveness(
            instructions, successors, web_context,
            {index: source_atoms for index in uses})
        for index in definitions:
            leaking = source_atoms & _ia32_live_out(blind, successors, index)
            require(not leaking,
                    f"{web_context}: {_ia32_atom_registers(leaking)} still has"
                    f" a consumer outside the web at "
                    f"{instructions[index]['offset']}")
        # W2 (encoding) and W6.
        buffer = bytearray(image)
        rewritten = []
        for index in sorted(definitions + uses):
            item = instructions[index]
            blocked = {source, target} & set(item.get("frozen", frozenset()))
            require(not blocked,
                    f"{web_context}: {sorted(blocked)} is named by a "
                    f"sub-register field at {item['offset']} that the "
                    "recolour cannot rewrite")
            ordinal = field_scopes.get(item["offset"])
            if ordinal is None:
                hits = [(byte_index, shift)
                        for byte_index, shift in item["fields"]
                        if (buffer[byte_index] >> shift) & 7 == source_number]
                require(len(hits) == 1,
                        f"{web_context}: the instruction at {item['offset']} "
                        f"names {source} in {len(hits)} register fields, so "
                        "which occurrence belongs to the web is not decidable")
                byte_index, shift = hits[0]
            else:
                require(ordinal < len(item["fields"]),
                        f"{web_context}: the instruction at {item['offset']} "
                        f"has no register field {ordinal}")
                byte_index, shift = item["fields"][ordinal]
                require((buffer[byte_index] >> shift) & 7 == source_number,
                        f"{web_context}: register field {ordinal} at "
                        f"{item['offset']} does not name {source}")
            require(byte_index not in relocation_offsets,
                    f"{web_context}: a rewritten byte overlaps a relocation")
            buffer[byte_index] = (
                (buffer[byte_index] & ~(7 << shift))
                | (target_number << shift)) & 0xFF
            rewritten.append(byte_index)
        require(rewritten, f"{web_context}: the recolour rewrites nothing")
        candidate = bytes(buffer)
        require(len(candidate) == len(image),
                f"{web_context}: the recolour changed the body length")
        # W7.  Every claim about the image is measured on the image.
        image_instructions = decode_ia32_bijection_body(
            candidate, f"{web_context} image", relocations, code_length)
        require(
            [(item["offset"], item["length"]) for item in image_instructions]
            == [(item["offset"], item["length"]) for item in instructions],
            f"{web_context}: the image changed an instruction boundary")
        mapping = {source: target}
        for left, right in zip(image_instructions, instructions):
            # See `apply_register_bijection`: a form outside the one-byte
            # table (a repeated string operation) has no `+r` field and takes
            # the stricter full-opcode mask rather than crashing.
            form = _bijection_form_for(right["opcode"])
            opreg = form is not None and form["opreg"] is not None
            mask = 0xF8 if opreg else 0xFFFF
            require(left["opcode"] & mask == right["opcode"] & mask
                    and left["flow"] == right["flow"]
                    and left["target"] == right["target"],
                    f"{web_context}: the image changed an opcode or a branch")
            offset = right["offset"]
            is_definition = offset in definition_offsets
            recoloured = is_definition or offset in use_offsets
            # A scoped entry moves exactly one side of the operand set: a
            # scoped definition renames what the instruction WRITES and leaves
            # its reads -- the other web's use -- alone, and a scoped use is
            # the mirror.  This is the field-exact re-measurement that pays
            # for the relaxed membership refusals above.
            scoped = recoloured and offset in field_scopes
            rename_reads = recoloured and not (scoped and is_definition)
            rename_writes = recoloured and not (scoped and not is_definition)
            expected_reads = frozenset(
                mapping.get(name, name) if rename_reads else name
                for name in right["reads"])
            expected_writes = frozenset(
                mapping.get(name, name) if rename_writes else name
                for name in right["writes"])
            require(left["reads"] == expected_reads
                    and left["writes"] == expected_writes,
                    f"{web_context}: the image's operand set at "
                    f"{right['offset']} is not the recolour's image")
        changed = sorted({index for index in range(len(image))
                          if image[index] != candidate[index]})
        require(changed == sorted(set(rewritten)),
                f"{web_context}: the image changed a byte the recolour did "
                "not name")
        require(changed == list(web["expected_rewritten_offsets"]),
                f"{web_context}: the rewritten offset set {changed} differs "
                "from its declaration")
        entry = {
            "source_register": source, "image_register": target,
            "definitions": list(definition_offsets),
            "uses": list(use_offsets),
            "live_range": sorted(instructions[index]["offset"]
                                 for index in interior),
            "rewritten_offsets": changed,
        }
        if field_scopes:
            entry["field_scopes"] = {str(offset): ordinal for offset, ordinal
                                     in sorted(field_scopes.items())}
        detail.append(entry)
        rewritten_all.extend(changed)
        image = candidate
    require(image != body, f"{context}: the recolour moves nothing")
    return image, {
        "webs": detail,
        "instruction_count": instruction_count,
        "rewritten_offsets": sorted(set(rewritten_all)),
        "code_length": len(body) if code_length is None else code_length,
    }


def require_web_recolour_debug_registers(
    stream: bytes, declared: list, context: str,
) -> list:
    """W8.  Pin the `.debug$S` S_REGISTER record list.

    The recolour leaves the stream alone.  That is sound rather than
    optimistic because of W4 and W5: no value of the image register is live
    anywhere in the web's range, and no value of the source register survives
    a definition, so no named register local can BE the web and none can span
    it.  What is pinned here is that the record list has not changed -- a
    different allocation would produce a different one and must be re-proved.
    """
    records = parse_codeview_symbol_stream(stream, context)
    measured = []
    for record in records:
        if record["type"] != CODEVIEW_REGISTER_RECORD_TYPE:
            continue
        field_at = _codeview_register_field(record, context)
        measured.append([record["name"], record["offset"],
                         _codeview_register_name(stream, field_at, context)])
    require(measured == [list(item) for item in declared],
            f"{context}: the S_REGISTER record list {measured} differs from "
            "its declaration")
    return measured


INSTRUCTION_SCHEDULE_EDGE_REASONS = frozenset({
    "register_raw", "register_war", "register_waw",
    "flags_raw", "flags_war", "flags_waw", "memory",
})


def compose_retail_exact_instruction_schedule(
    seed_bytes: bytes,
    donor_bytes: bytes,
    function: dict,
    retail_body: bytes,
) -> tuple[bytes, dict]:
    """Install a topological reordering after proving it is retail's own code.

    See the class comment above: this is a certificate.  The pre-image is an
    ordinary, census-pinned compile of the same translation unit; the
    reordering is proved to respect the window's own dependence DAG; and the
    result is refused unless it equals the pinned retail oracle under the
    relocation mask.  Body installation itself is delegated, unchanged, to the
    equal-body primitive.
    """
    require(function.get("splice_class") == INSTRUCTION_SCHEDULE_CLASS,
            "splice class is not retail_exact_instruction_schedule")
    require("target_source_refactor" not in function,
            "instruction-schedule functions carry no source refactor")
    require(isinstance(retail_body, (bytes, bytearray)) and retail_body,
            "retail oracle body is missing")
    spec = function["instruction_schedule"]
    seed = CoffObject(seed_bytes)
    donor = CoffObject(donor_bytes)
    mangled = function["mangled"]
    sp = seed.function_section(mangled)
    dp = donor.function_section(mangled)
    require(sp["number"] == function["expected_section_number"]
            and dp["number"] == function["expected_donor_section_number"],
            "instruction-schedule target section seat changed")
    require(len(seed.sections) == len(donor.sections)
            == function["expected_section_count"],
            "instruction-schedule global section count changed")
    seed_functions = function_multiset(seed)
    donor_functions = function_multiset(donor)
    require(seed_functions == donor_functions
            and sum(seed_functions.values())
            == function["expected_function_count"],
            "instruction-schedule donor function set differs")
    seed_comdats = comdat_primary_identity_multiset(seed)
    donor_comdats = comdat_primary_identity_multiset(donor)
    require(seed_comdats == donor_comdats
            and sum(seed_comdats.values())
            == function["expected_comdat_count"],
            "instruction-schedule donor COMDAT identity set differs")
    require(
        sp["raw_size"] == dp["raw_size"] == function["expected_body_length"]
        and sp["relocation_count"] == dp["relocation_count"]
        == function["expected_relocation_count"]
        and sp["line_count"] == function["expected_seed_line_count"]
        and dp["line_count"] == function["expected_donor_line_count"]
        and sp["name"] == dp["name"]
        and sp["characteristics"] == dp["characteristics"]
        == function["expected_characteristics"],
        "instruction-schedule target header/count pins changed",
    )
    require(
        section_definitions(seed)[sp["number"]]["selection"]
        == section_definitions(donor)[dp["number"]]["selection"]
        == function["expected_selection"],
        "instruction-schedule COMDAT selection changed",
    )
    expected_closure = tuple(function["expected_closure"])
    require(_comdat_child_closure(seed, sp)
            == _comdat_child_closure(donor, dp)
            == (len(expected_closure), expected_closure),
            "instruction-schedule target closure changed")
    require(list(expected_closure) in (INSTRUCTION_SCHEDULE_FPO_CLOSURE,
                                       INSTRUCTION_SCHEDULE_EH_CLOSURE),
            "instruction-schedule closure pin names no installation delegate")
    reseat_declared = any(window.get("relocation_reseat")
                          for window in spec["windows"])
    delegate = instruction_schedule_delegate(
        function["expected_closure"], function["expected_code_renames"],
        reseat_declared)
    require(instruction_mosaic_metadata_sha256(seed, sp)
            == function["expected_seed_metadata_sha256"]
            and instruction_mosaic_metadata_sha256(donor, dp)
            == function["expected_donor_metadata_sha256"],
            "instruction-schedule metadata differs from its pin")
    seed_body = coff_body(seed, sp)
    donor_body = coff_body(donor, dp)
    require(sha256_bytes(seed_body) == function["expected_seed_body_sha256"]
            and sha256_bytes(donor_body)
            == function["expected_donor_body_sha256"],
            "instruction-schedule seed/donor body differs from its pin")
    code_renames = require_instruction_mosaic_semantic_relocations(
        seed, sp, donor, dp, "instruction-schedule code")
    require([[offset, kind] for offset, kind in code_renames]
            == function["expected_code_renames"],
            "instruction-schedule code rename set changed")
    seed_rows = detailed_relocations(seed, sp)
    donor_rows = detailed_relocations(donor, dp)
    seed_targets = {row["offset"]: row["target"] for row in seed_rows}
    donor_targets = {row["offset"]: row["target"] for row in donor_rows}
    require([[offset, seed_targets.get(offset), donor_targets.get(offset)]
             for offset, _ in code_renames]
            == function.get("expected_code_rename_symbols", []),
            "instruction-schedule code rename symbol pair changed")
    require([(row["offset"], row["type"], row["addend"]) for row in seed_rows]
            == [(row["offset"], row["type"], row["addend"])
                for row in donor_rows],
            "instruction-schedule donor relocation layout differs from the "
            "seed")
    require([(row["offset"], row["target"]) for row in seed_rows
             if row["type"] == 0x0014]
            == [(row["offset"], row["target"]) for row in donor_rows
                if row["type"] == 0x0014],
            "instruction-schedule donor call/branch relocation targets differ "
            "from the seed")
    relocation_offsets = frozenset(
        row["offset"] + byte
        for row in seed_rows for byte in range(row["width"]))
    relocation_symbols = {
        row["offset"]: {"width": row["width"], "target": row["target"]}
        for row in seed_rows}
    # Every label this body's own relocations name inside this same COMDAT.
    # The installed BODY is the donor's, so its control flow is the donor's
    # and the set is read there; a computed jump can reach only these, so this
    # is what discharges the window-entry obligation for one.
    internal_targets = frozenset(
        row["target_value"] for row in donor_rows
        if row["target_section"] == dp["number"])
    declared_targets = spec.get("expected_internal_relocation_targets")
    if declared_targets is not None:
        require(sorted(internal_targets) == declared_targets,
                "instruction-schedule in-body relocated target set changed")

    image, proof = apply_instruction_schedule(
        donor_body, spec["windows"], relocation_offsets,
        "instruction-schedule image", relocation_symbols,
        spec.get("expected_code_length"), internal_targets,
    )
    require(proof["code_length"]
            == (spec.get("expected_code_length") or len(donor_body)),
            "instruction-schedule code length differs from its pin")
    require(proof["changed_offsets"] == spec["expected_changed_offsets"]
            and proof["instruction_count"]
            == spec["expected_instruction_count"],
            "instruction-schedule image differs from its declaration")
    require(sha256_bytes(image) == function["expected_body_sha256"],
            "instruction-schedule image differs from its pin")
    require(image != donor_body,
            "instruction-schedule image does not move the donor body")

    # Obligation 6b.  The reseat the permutation derives is now turned into
    # the image's own relocation table: the same records, in the same order,
    # with the same symbols, types, widths and addends, and with exactly the
    # declared offsets.  The ascending-offset invariant every MSVC table has
    # must survive, and the schedule's reseat must equal the move set the
    # installation delegate is pinned to.
    moved = {old_offset: new_offset
             for old_offset, new_offset in proof["relocation_reseat"]}
    require(bool(moved) == reseat_declared,
            "instruction-schedule reseat declaration and measurement differ")
    if moved:
        require(function.get("expected_relocation_moves")
                == [[old_offset, new_offset]
                    for old_offset, new_offset in proof["relocation_reseat"]
                    if old_offset != new_offset],
                "instruction-schedule relocation move set differs from its "
                "pin")
    image_rows = []
    for row in seed_rows:
        if row["offset"] in moved:
            row = dict(row)
            row["offset"] = moved[row["offset"]]
        image_rows.append(row)
    require([row["offset"] for row in image_rows]
            == sorted(row["offset"] for row in image_rows),
            "instruction-schedule reseat breaks the relocation table's "
            "ascending offset order")
    image_relocation_symbols = {
        row["offset"]: {"width": row["width"], "target": row["target"]}
        for row in image_rows}
    require(len(image_relocation_symbols) == len(image_rows),
            "instruction-schedule reseat collides two relocation records")

    # Obligation 7, measured on the IMAGE with the SEED's own tables -- those
    # are the tables the composition installs (with the reseated relocation
    # offsets, which are the image's own).
    debug_detail = require_instruction_schedule_debug_fidelity(
        seed, sp, image, spec["windows"], spec, mangled,
        "instruction-schedule debug fidelity", image_relocation_symbols,
        spec.get("expected_code_length"), internal_targets,
    )

    pinned_length = function["retail_oracle"]["length"]
    require(len(retail_body) == pinned_length == len(image),
            "instruction-schedule retail length changed")
    semantic_detail = require_retail_relocation_oracle(
        image_rows, bytes(retail_body),
        int(function["retail_oracle"]["address"], 16),
        function["retail_relocations"],
        "instruction-schedule retail relocation oracle",
    )
    masked_image = bytearray(image)
    masked_retail = bytearray(retail_body)
    for row in image_rows:
        start, width = row["offset"], row["width"]
        masked_image[start:start + width] = b"\0" * width
        masked_retail[start:start + width] = b"\0" * width
    differing = sum(left != right
                    for left, right in zip(masked_image, masked_retail))
    require(differing == 0,
            f"instruction-schedule output is not retail-exact: {differing} "
            "byte(s) differ under the relocation mask")

    derived = bytearray(donor_bytes)
    derived[dp["raw_offset"]:dp["raw_offset"] + dp["raw_size"]] = image
    if moved:
        # The derived object is the image AND the image's relocation table:
        # only the four offset bytes of a moved record change, and only to
        # the offset the permutation put its own instruction at.
        for ordinal, row in enumerate(donor_rows):
            if row["offset"] not in moved:
                continue
            record_at = dp["relocation_offset"] + ordinal * 10
            derived[record_at:record_at + 4] = moved[row["offset"]].to_bytes(
                4, "little")
    derived = bytes(derived)
    effective = {
        "mangled": mangled,
        "splice_class": delegate,
        "expected_body_length": function["expected_body_length"],
        "expected_body_sha256": function["expected_body_sha256"],
        "expected_changed_offsets": function["expected_changed_offsets"],
    }
    if delegate == "equal_body_eh_structural_local":
        effective["expected_code_renames"] = function["expected_code_renames"]
        effective["expected_xdata_rename_offsets"] = function[
            "expected_xdata_rename_offsets"]
    if delegate == "equal_body_eh_reloc_layout":
        effective["expected_relocation_moves"] = function[
            "expected_relocation_moves"]
        effective["expected_xdata_rename_offsets"] = function[
            "expected_xdata_rename_offsets"]
    composed, detail = compose_equal_body_comdat(seed_bytes, derived, effective)

    checked = CoffObject(composed)
    cp = checked.function_section(mangled)
    require(coff_body(checked, cp) == image,
            "instruction-schedule composed body differs from the image")
    expected_relocation_table = bytearray(
        _coff_table_bytes(seed, sp, "relocations"))
    for ordinal, row in enumerate(seed_rows):
        if row["offset"] in moved:
            record_at = ordinal * 10
            expected_relocation_table[record_at:record_at + 4] = (
                moved[row["offset"]].to_bytes(4, "little"))
    require(detailed_relocations(checked, cp) == image_rows
            and _coff_table_bytes(checked, cp, "relocations")
            == bytes(expected_relocation_table)
            and _coff_table_bytes(checked, cp, "lines")
            == _coff_table_bytes(seed, sp, "lines"),
            "instruction-schedule output changed seed relocation/line bytes")
    for child_name in expected_closure:
        require(coff_body(checked, _comdat_child(checked, cp, child_name))
                == coff_body(seed, _comdat_child(seed, sp, child_name)),
                f"instruction-schedule output changed its {child_name} child")
    allowed = set(range(sp["raw_offset"], sp["raw_offset"] + sp["raw_size"]))
    if moved:
        allowed |= {
            sp["relocation_offset"] + ordinal * 10 + byte
            for ordinal, row in enumerate(seed_rows)
            if row["offset"] in moved for byte in range(4)}
    require({index for index in range(len(seed_bytes))
             if seed_bytes[index] != composed[index]} <= allowed,
            "instruction-schedule changed bytes outside its own COMDAT")
    return composed, {
        **detail,
        "splice_class": INSTRUCTION_SCHEDULE_CLASS,
        "instruction_schedule": proof["windows"],
        "instruction_count": proof["instruction_count"],
        "changed_offsets": proof["changed_offsets"],
        "debug_fidelity": debug_detail,
        "relocation_reseat": proof["relocation_reseat"],
        "retail_exact": True,
        **semantic_detail,
    }


# ---------------------------------------------------------------------------
# retail_exact_relational_form: a comparison-DIRECTION CERTIFICATE
# ---------------------------------------------------------------------------
#
# WHY THIS CLASS IS A CERTIFICATE AND NOT A GENERATOR
#
# MSVC 4.2 emits both directions of the same comparison -- `cmp r, m` (opcode
# 3B) and `cmp m, r` (opcode 39) -- at different sites of one translation
# unit, and which one a site gets is not a source lever: it has been refuted
# as one four separate times, and it flips by itself when an unrelated
# declaration changes.  So the difference has to be discharged as a PROOF
# about two instructions, not searched for.
#
# The rewriting is: exchange the compare's two operands by flipping the
# direction bit of its opcode -- the ModRM, SIB and displacement bytes are
# left BYTE-IDENTICAL, which is what makes "the same two operands, the other
# way round" a structural fact rather than an author's claim -- and replace
# the condition of the branch that consumes its flags by the condition's
# MIRROR.  Both instructions keep their length; nothing moves.
#
# Its obligations are strictly WEAKER than the landed register bijection's --
# no register changes role, no live range moves, no length can change -- with
# one exception, and the exception is the whole of the interesting work:
#
#     `cmp a, b` and `cmp b, a` do NOT leave the same flags.
#
# ZF is the only flag the reversal preserves.  CF, PF, AF, SF and OF all
# change.  That is MEASURED, not asserted: `$SCRATCH/BD-flags.py` enumerates
# every ordered pair of a closed domain and reports which flags survive, and
# an x86 binary built by this project's own MSVC 4.2 and run under Wine
# reproduces the same six counts on hardware (65280 / 43520 / 61440 / 0 /
# 65024 / 256 changed pairs of 65536 for CF/PF/AF/ZF/SF/OF).  The same two
# instruments derive the mirror table below by exhaustion over all 16x16
# condition pairs, at byte and at dword width: exactly ten conditions have a
# mirror, each mirror is unique, the map is an involution, and the six
# sign/overflow/parity conditions have NO mirror at all and are refused.
#
# THE TWO-TIER DECODE, and why this class reaches bodies the others cannot.
#
# The register-bijection certificate proves its case by REWRITING register
# fields, so it needs a complete semantic decode of every instruction in the
# body.  That decode refuses 17 of the 19 rows on the current board -- a
# `rep movsd`, a 66-prefixed form, a `shl`, a `nop` is enough.  This class
# rewrites nothing but two opcode bytes, so it needs only:
#
#   A  the body's instruction BOUNDARIES and its CONTROL FLOW, from the same
#      length decoder the instruction-schedule certificate already trusts
#      whole-body, plus a closed flow classification; and
#   B  the full semantic table on the two rewritten instructions ALONE.
#
# The flag model on tier A is FAIL-CLOSED and that is what makes the gap
# sound: an opcode whose flag effect is not in the table READS every flag and
# WRITES none.  Over-claiming a read and under-claiming a write can only make
# a flag look MORE live, never less, so an unmodelled instruction can only
# cause a REFUSAL.  Where the effect depends on the ModRM extension digit the
# digit is read from the encoding, so those forms are exact rather than the
# union/intersection an opcode-granular table would have to take.
#
# THE OBLIGATIONS, in the order the composer checks them:
#
#  1  provenance     the pre-image is a census-pinned, compiler-produced seed
#                    or donor COMDAT of the same mangled function, with the
#                    same section seat, section count, function and COMDAT
#                    multisets, header counts, selection, closure and pinned
#                    metadata -- the identical battery the bijection uses.
#  2  total decode   the body decodes to exhaustion on tier A, every decoded
#                    branch lands on an instruction boundary, no far
#                    transfer, no LOCK, no unclassifiable flow, and every
#                    instruction is reachable from the entry OR from a
#                    DERIVED external entry point.  The external entry set is
#                    every in-body target a relocation of this COMDAT or of
#                    its closure children names -- which is exactly the C++
#                    EH unwind funclet heads in `.xdata$x` -- and it is pinned
#                    in the manifest, so a body whose funclet set changed
#                    refuses instead of being proved on a partial graph.
#  3  the pair       at each site the instruction is a two-operand `cmp` in
#                    one of the four admitted encodings (38/3A byte, 39/3B
#                    word or dword), the NEXT instruction by offset is a Jcc
#                    (short 7x or near 0F 8x), and the branch's ONLY
#                    predecessor in the graph is that compare.  A compare
#                    against an immediate has no reversed form and refuses; a
#                    branch another edge can reach refuses, because that path
#                    would consume flags this compare did not produce.
#  4  the mirror     the image condition is the CLOSED table's mirror of the
#                    seed condition, and the declaration must reproduce it.
#                    `o/no/s/ns/p/np` are absent from the table and refuse.
#  5  flag deadness  a backward per-flag liveness fixpoint over the body's own
#                    control-flow graph -- the SAME fixpoint the register and
#                    web certificates use, with flags as its atoms -- proves
#                    that none of the five flags the reversal CHANGES is live
#                    on any out-edge of any rewritten branch, nor at any
#                    external entry point.  ZF may be live: it is the one flag
#                    the reversal provably preserves, and admitting it is the
#                    refinement the measurement earns.  Any successor that
#                    reads a flag the reversal changes REFUSES.
#  6  length         the image re-decodes on tier A to exactly the same
#                    boundaries, the same flow classification and the same
#                    branch targets, and it differs from the pre-image in
#                    exactly the declared bytes: one opcode byte per compare
#                    and one condition byte per branch, with every ModRM, SIB,
#                    displacement and immediate byte untouched.
#  7  relocations    no rewritten byte overlaps a relocation operand, and the
#                    relocation table is the seed's own, unmoved.  Nothing in
#                    this class can move one.
#  8  retail equality  the image must equal the pinned retail oracle under the
#                    relocation mask, or the composition is REFUSED.
#  9  debug fidelity  no instruction moves and no register changes role, so
#                    `.debug$S` and the COFF line table are required to be
#                    BYTE-IDENTICAL, and every line row is re-checked against
#                    the image's own boundaries.
# 10  scope         one named COMDAT, one pinned oracle, and the ordinary
#                    output-conservation proof of the equal-body primitive,
#                    which this class delegates to unchanged and selects from
#                    the manifest's own `expected_closure` pin.


RELATIONAL_FORM_CLASS = "retail_exact_relational_form"


RELATIONAL_FORM_KIND = "mirrored_relational_form_v1"


RELATIONAL_FORM_FPO_CLOSURE = [".debug$F", ".debug$S"]
RELATIONAL_FORM_EH_CLOSURE = [".debug$S", ".xdata$x"]


# The six arithmetic flags.  DF is deliberately absent: no Jcc reads it and no
# operand reversal can change it, so modelling it would add nothing.
IA32_ARITHMETIC_FLAGS = frozenset({"cf", "pf", "af", "zf", "sf", "of"})


# MEASURED (`$SCRATCH/BD-flags.py`, and on hardware by `$SCRATCH/fp.c` /
# `fp32.c` built with this project's own MSVC 4.2 and run under Wine): ZF is
# the only flag `cmp a,b` and `cmp b,a` agree on for every ordered pair.
IA32_RELATIONAL_PRESERVED_FLAGS = frozenset({"zf"})
IA32_RELATIONAL_CHANGED_FLAGS = IA32_ARITHMETIC_FLAGS - \
    IA32_RELATIONAL_PRESERVED_FLAGS


# The condition each Jcc consumes, by its 4-bit condition code.
IA32_CONDITION_FLAGS = {
    0x0: frozenset({"of"}),                 # o
    0x1: frozenset({"of"}),                 # no
    0x2: frozenset({"cf"}),                 # b / c / nae
    0x3: frozenset({"cf"}),                 # ae / nb / nc
    0x4: frozenset({"zf"}),                 # e / z
    0x5: frozenset({"zf"}),                 # ne / nz
    0x6: frozenset({"cf", "zf"}),           # be / na
    0x7: frozenset({"cf", "zf"}),           # a / nbe
    0x8: frozenset({"sf"}),                 # s
    0x9: frozenset({"sf"}),                 # ns
    0xA: frozenset({"pf"}),                 # p / pe
    0xB: frozenset({"pf"}),                 # np / po
    0xC: frozenset({"sf", "of"}),           # l / nge
    0xD: frozenset({"sf", "of"}),           # ge / nl
    0xE: frozenset({"zf", "sf", "of"}),     # le / ng
    0xF: frozenset({"zf", "sf", "of"}),     # g / nle
}


IA32_CONDITION_NAMES = {
    0x0: "o", 0x1: "no", 0x2: "b", 0x3: "ae", 0x4: "e", 0x5: "ne",
    0x6: "be", 0x7: "a", 0x8: "s", 0x9: "ns", 0xA: "p", 0xB: "np",
    0xC: "l", 0xD: "ge", 0xE: "le", 0xF: "g",
}


IA32_CONDITION_CODES = {name: code
                        for code, name in IA32_CONDITION_NAMES.items()}


# THE CLOSED MIRROR TABLE.  Derived by exhaustion, never by hand: for every
# ordered pair (a, b) of a closed domain, `cond C` after `cmp a,b` was
# compared against `cond D` after `cmp b,a` for all 16x16 (C, D).  Exactly
# these ten pairs agree on the whole domain; each mirror is unique; the map is
# an involution; and `o`, `no`, `s`, `ns`, `p`, `np` have NO agreeing
# condition at all, which is why they are absent and refuse.  Confirmed on
# hardware at byte width (all 65536 pairs) and at dword width (160000
# boundary-lattice pairs).
IA32_RELATIONAL_MIRROR = {
    "b": "a", "a": "b",
    "ae": "be", "be": "ae",
    "e": "e", "ne": "ne",
    "l": "g", "g": "l",
    "ge": "le", "le": "ge",
}


# The four admitted two-operand `cmp` encodings, as the pairs the direction
# bit exchanges.  38/39 are `cmp r/m, r`; 3A/3B are `cmp r, r/m`.  The ModRM
# byte means exactly the same thing in both members of a pair, so flipping the
# opcode -- and NOTHING else -- is precisely the operand exchange.  Forms with
# an immediate operand (80 /7, 81 /7, 83 /7, 3C, 3D) have no reversed encoding
# and are absent.
IA32_RELATIONAL_COMPARE_PAIRS = {0x38: 0x3A, 0x3A: 0x38,
                                 0x39: 0x3B, 0x3B: 0x39}


# Instruction prefixes tier A walks through.  F2/F3 are admitted only in front
# of a string opcode, which is the only thing they can prefix on a 386/486
# target; anything else refuses.
_IA32_RELATIONAL_PREFIXES = frozenset({0x26, 0x2E, 0x36, 0x3E,
                                       0x64, 0x65, 0x66})
_IA32_RELATIONAL_REPEAT_PREFIXES = frozenset({0xF2, 0xF3})
_IA32_RELATIONAL_STRING_QUIET = frozenset({0x6C, 0x6D, 0x6E, 0x6F,
                                           0xA4, 0xA5, 0xAA, 0xAB,
                                           0xAC, 0xAD})
_IA32_RELATIONAL_STRING_COMPARE = frozenset({0xA6, 0xA7, 0xAE, 0xAF})
# Opcodes that make the graph unknowable or the body unmodellable.
_IA32_RELATIONAL_REFUSED_OPCODES = frozenset({
    0x9A, 0xEA,                             # far call / far jump
    0xCC, 0xCD, 0xCE, 0xCF,                 # int / into / iret
    0xF0, 0xF1, 0xF4,                       # lock / icebp / hlt
})


def _ia32_relational_flag_table() -> dict:
    """Flag effect by opcode for the forms whose effect is opcode-determined.

    Everything absent falls back to the fail-closed default (reads every
    flag, writes none), which can only cause a refusal.
    """
    quiet = (frozenset(), frozenset())
    table = {}
    for opcode in (0x88, 0x89, 0x8A, 0x8B, 0x8C, 0x8D, 0x8E,
                   0xA0, 0xA1, 0xA2, 0xA3, 0xC6, 0xC7,
                   0x86, 0x87, 0x98, 0x99, 0xC8, 0xC9,
                   0x60, 0x61, 0x68, 0x6A,
                   0x06, 0x0E, 0x16, 0x1E, 0x07, 0x17, 0x1F,
                   0xFC, 0xFD):                       # cld / std touch DF only
        table[opcode] = quiet
    for opcode in range(0xB0, 0xC0):                  # mov r, imm
        table[opcode] = quiet
    for opcode in range(0x50, 0x60):                  # push / pop r32
        table[opcode] = quiet
    for opcode in range(0x90, 0x98):                  # nop / xchg eax, r32
        table[opcode] = quiet
    for opcode in range(0xD8, 0xE0):                  # x87: no EFLAGS
        table[opcode] = quiet
    for opcode in _IA32_RELATIONAL_STRING_QUIET:      # movs / stos / lods
        table[opcode] = quiet
    for base in (0x00, 0x08, 0x20, 0x28, 0x30, 0x38):  # add or and sub xor cmp
        for step in range(6):
            table[base + step] = (frozenset(), IA32_ARITHMETIC_FLAGS)
    for base in (0x10, 0x18):                         # adc / sbb read CF
        for step in range(6):
            table[base + step] = (frozenset({"cf"}), IA32_ARITHMETIC_FLAGS)
    for opcode in (0x84, 0x85, 0xA8, 0xA9):           # test
        table[opcode] = (frozenset(), IA32_ARITHMETIC_FLAGS)
    for opcode in _IA32_RELATIONAL_STRING_COMPARE:    # cmps / scas
        table[opcode] = (frozenset(), IA32_ARITHMETIC_FLAGS)
    for opcode in range(0x40, 0x50):                  # inc / dec preserve CF
        table[opcode] = (frozenset(), IA32_ARITHMETIC_FLAGS - {"cf"})
    for opcode in (0x69, 0x6B, 0x0FAF):               # imul
        table[opcode] = (frozenset(), frozenset({"cf", "of"}))
    for opcode in (0x0FB6, 0x0FB7, 0x0FBE, 0x0FBF):   # movzx / movsx
        table[opcode] = quiet
    for opcode in (0x0FA3, 0x0FAB, 0x0FB3, 0x0FBB):   # bt / bts / btr / btc
        table[opcode] = (frozenset(), frozenset({"cf"}))
    for opcode in (0x0FBC, 0x0FBD):                   # bsf / bsr
        table[opcode] = (frozenset(), frozenset({"zf"}))
    for code in range(16):
        table[0x0F90 | code] = (IA32_CONDITION_FLAGS[code], frozenset())
        table[0x0F40 | code] = (IA32_CONDITION_FLAGS[code], frozenset())
    table[0x9C] = (IA32_ARITHMETIC_FLAGS, frozenset())          # pushfd
    table[0x9D] = (frozenset(), IA32_ARITHMETIC_FLAGS)          # popfd
    table[0x9E] = (frozenset(), IA32_ARITHMETIC_FLAGS - {"of"})  # sahf
    table[0x9F] = (IA32_ARITHMETIC_FLAGS - {"of"}, frozenset())  # lahf
    table[0xF5] = (frozenset({"cf"}), frozenset({"cf"}))        # cmc
    table[0xF8] = (frozenset(), frozenset({"cf"}))              # clc
    table[0xF9] = (frozenset(), frozenset({"cf"}))              # stc
    return table


IA32_RELATIONAL_FLAG_EFFECTS = _ia32_relational_flag_table()


def _ia32_relational_group_table() -> dict:
    """Flag effect by (opcode, ModRM extension digit).

    Reading the digit off the encoding makes these forms EXACT.  An
    opcode-granular table would have to take the union of the members' reads
    and the intersection of their writes -- sound, but it leaves CF live
    across every `cmp m, imm` in the body because ADC and SBB share the
    opcode, and that alone turned a provable site into a refusal.
    """
    group1 = {digit: (frozenset({"cf"}) if digit in (2, 3) else frozenset(),
                      IA32_ARITHMETIC_FLAGS)
              for digit in range(8)}
    group3 = {
        0: (frozenset(), IA32_ARITHMETIC_FLAGS),        # test r/m, imm
        1: (frozenset(), IA32_ARITHMETIC_FLAGS),        # test (alias)
        2: (frozenset(), frozenset()),                  # not: no flag at all
        3: (frozenset(), IA32_ARITHMETIC_FLAGS),        # neg
        4: (frozenset(), frozenset({"cf", "of"})),      # mul
        5: (frozenset(), frozenset({"cf", "of"})),      # imul
        6: (frozenset(), frozenset()),                  # div: all undefined
        7: (frozenset(), frozenset()),                  # idiv: all undefined
    }
    group5 = {digit: (frozenset(),
                      IA32_ARITHMETIC_FLAGS - {"cf"} if digit in (0, 1)
                      else frozenset())
              for digit in range(8)}
    # Shift/rotate BY ONE: the count is fixed, so the write set is guaranteed.
    shift_one = {digit: (frozenset({"cf"}) if digit in (2, 3) else frozenset(),
                         frozenset({"cf", "of"}))
                 for digit in range(8)}
    # Shift/rotate by imm8 or by CL: a count of zero leaves every flag
    # untouched, so NOTHING is guaranteed to be written.
    shift_var = {digit: (frozenset({"cf"}) if digit in (2, 3) else frozenset(),
                         frozenset())
                 for digit in range(8)}
    return {
        0x80: group1, 0x81: group1, 0x83: group1,
        0xF6: group3, 0xF7: group3,
        0xFE: group5, 0xFF: group5,
        0xD0: shift_one, 0xD1: shift_one,
        0xC0: shift_var, 0xC1: shift_var, 0xD2: shift_var, 0xD3: shift_var,
    }


IA32_RELATIONAL_GROUP_FLAG_EFFECTS = _ia32_relational_group_table()


def relational_form_delegate(
    expected_closure: object, expected_code_renames: object,
) -> str:
    """Name the installation delegate from the PINS alone.

    Identical in spirit to `register_bijection_delegate`, minus its relocation
    branch: this class can never move a relocation, so
    `equal_body_eh_reloc_layout` is unreachable and is not offered.
    """
    if (list(expected_closure) == RELATIONAL_FORM_FPO_CLOSURE
            and not expected_code_renames):
        return "equal_body_strict"
    return "equal_body_eh_structural_local"


def ia32_relational_flow_walk(
    body: bytes, relocations: dict | None, context: str,
    code_length: int | None = None,
    external_entries: frozenset | None = None,
) -> tuple[list[dict], list[list[int]], list[int]]:
    """Tier A: boundaries, closed flow classification, CFG and flag facts.

    Obligation 2.  Returns `(items, successors, entry_indices)`.  Every item
    carries `reads_flags` / `writes_flags`; an opcode outside the table reads
    every flag and writes none, so an unmodelled instruction can only make a
    flag look MORE live.
    """
    require(isinstance(body, (bytes, bytearray)) and body,
            f"{context}: body is empty")
    body = bytes(body)
    relocations = relocations or {}
    limit = len(body) if code_length is None else code_length
    require(isinstance(limit, int) and not isinstance(limit, bool)
            and 0 < limit <= len(body),
            f"{context}: code length is out of range")
    code = body[:limit]
    items = []
    offset = 0
    while offset < len(code):
        length = supported_ia32_instruction_length(
            code[offset:], f"{context} at {offset}")
        cursor = offset
        repeated = False
        while (code[cursor] in _IA32_RELATIONAL_PREFIXES
               or code[cursor] in _IA32_RELATIONAL_REPEAT_PREFIXES):
            if code[cursor] in _IA32_RELATIONAL_REPEAT_PREFIXES:
                require(cursor + 1 < offset + length
                        and (code[cursor + 1] in _IA32_RELATIONAL_STRING_QUIET
                             or code[cursor + 1]
                             in _IA32_RELATIONAL_STRING_COMPARE),
                        f"{context}: the repeat prefix at {offset} does not "
                        "prefix a string opcode")
                repeated = True
            cursor += 1
            require(cursor < offset + length,
                    f"{context}: instruction at {offset} is only prefixes")
        opcode = code[cursor]
        require(opcode not in _IA32_RELATIONAL_REFUSED_OPCODES,
                f"{context}: opcode 0x{opcode:02x} at {offset} is outside the "
                "relational-form flow table")
        if opcode == 0x0F:
            require(cursor + 1 < offset + length,
                    f"{context}: truncated two-byte opcode at {offset}")
            opcode = 0x0F00 | code[cursor + 1]
        flow, target, condition = "fall", None, None
        if 0x70 <= opcode <= 0x7F:
            flow, condition = "jcc", opcode & 0xF
            target = offset + length + int.from_bytes(
                code[offset + length - 1:offset + length], "little",
                signed=True)
        elif 0x0F80 <= opcode <= 0x0F8F:
            flow, condition = "jcc", opcode & 0xF
            target = offset + length + int.from_bytes(
                code[offset + length - 4:offset + length], "little",
                signed=True)
        elif opcode in (0xEB, 0xE9):
            flow = "jmp"
            width = 1 if opcode == 0xEB else 4
            target = offset + length + int.from_bytes(
                code[offset + length - width:offset + length], "little",
                signed=True)
        elif opcode == 0xE8:
            flow = "call"
        elif opcode in (0xC2, 0xC3):
            flow = "ret"
        elif opcode in (0xE0, 0xE1, 0xE2, 0xE3):
            # loop / loopz / loopnz / jecxz: two successors, and the two
            # `loopz` forms read ZF -- which the reversal preserves.
            flow = "jcc"
            target = offset + length + int.from_bytes(
                code[offset + length - 1:offset + length], "little",
                signed=True)
        elif opcode == 0xFF:
            require(cursor + 1 < offset + length,
                    f"{context}: FF form at {offset} lacks its ModRM")
            extension = (code[cursor + 1] >> 3) & 7
            require(extension not in (3, 5),
                    f"{context}: a far transfer at {offset} makes the "
                    "control-flow graph unknowable")
            if extension == 2:
                flow = "call"
            elif extension == 4:
                raise ByteIdentityError(
                    f"{context}: a computed jump at {offset} makes the "
                    "control-flow graph unknowable")
        if (flow in ("jmp", "jcc")
                and (opcode == 0xE9 or 0x0F80 <= opcode <= 0x0F8F)
                and relocations.get(offset + length - 4, {}).get("width") == 4):
            # A relocated rel32 transfer leaves this COMDAT.  No calling
            # convention on this toolchain reads a flag, so it consumes none.
            flow, target, condition = "exit", None, None
        if flow == "jcc" and condition is not None:
            reads = IA32_CONDITION_FLAGS[condition]
            writes = frozenset()
        elif flow in ("jcc", "jmp", "call", "ret", "exit"):
            # loop/jecxz read no arithmetic flag except ZF for the two `loopz`
            # forms; a call, a return and a tail transfer read none, because
            # no calling convention on this toolchain passes or returns one.
            reads = (frozenset({"zf"}) if opcode in (0xE0, 0xE1)
                     else frozenset())
            writes = frozenset()
        elif opcode in IA32_RELATIONAL_GROUP_FLAG_EFFECTS:
            digit = (code[cursor + 1] >> 3) & 7
            reads, writes = IA32_RELATIONAL_GROUP_FLAG_EFFECTS[opcode][digit]
        else:
            reads, writes = IA32_RELATIONAL_FLAG_EFFECTS.get(
                opcode, (IA32_ARITHMETIC_FLAGS, frozenset()))
            if repeated and opcode in _IA32_RELATIONAL_STRING_COMPARE:
                reads = reads | {"zf"}
        items.append({
            "offset": offset, "length": length, "opcode": opcode,
            "opcode_at": cursor, "flow": flow, "target": target,
            "condition": condition,
            "reads_flags": frozenset(reads), "writes_flags": frozenset(writes),
        })
        offset += length
    require(offset == len(code),
            f"{context}: body does not decode to exhaustion")
    starts = {item["offset"] for item in items}
    for item in items:
        require(item["target"] is None or item["target"] in starts,
                f"{context}: the branch at {item['offset']} does not target "
                "an instruction boundary of this body")
    index_of = {item["offset"]: index for index, item in enumerate(items)}
    successors = []
    for index, item in enumerate(items):
        edges = []
        if item["flow"] in ("fall", "jcc", "call"):
            if index + 1 < len(items):
                edges.append(index + 1)
            else:
                require(item["flow"] != "fall",
                        f"{context}: body falls off its end")
        if item["flow"] in ("jcc", "jmp") and item["target"] is not None:
            edges.append(index_of[item["target"]])
        successors.append(sorted(set(edges)))
    external = sorted(external_entries or ())
    for target in external:
        require(target in index_of,
                f"{context}: the external entry {target} is not an "
                "instruction boundary of this body")
    entries = [0] + [index_of[target] for target in external if target != 0]
    seen, stack = set(), list(entries)
    while stack:
        index = stack.pop()
        if index in seen:
            continue
        seen.add(index)
        stack.extend(successors[index])
    unreachable = sorted(items[index]["offset"]
                         for index in range(len(items)) if index not in seen)
    require(not unreachable,
            f"{context}: the instruction at {unreachable[:1]} is reachable "
            "neither from the entry nor from a declared external entry, so "
            "the control-flow graph is incomplete")
    return items, successors, entries


def ia32_relational_flag_liveness(
    items: list[dict], successors: list[list[int]], context: str,
) -> list[frozenset]:
    """Backward per-flag liveness, on the SAME fixpoint the register and web
    certificates use -- the flags are simply its atoms."""
    shim = [{"read_atoms": item["reads_flags"],
             "write_atoms": item["writes_flags"]} for item in items]
    return _ia32_backward_liveness(shim, successors, context)


def apply_relational_form(
    body: bytes, sites: list, relocation_offsets: frozenset, context: str,
    relocations: dict | None = None, code_length: int | None = None,
    external_entries: frozenset | None = None,
) -> tuple[bytes, dict]:
    """Reverse each declared compare and mirror its branch, or refuse.

    Obligations 2 through 7 are discharged here; the composer adds
    provenance, retail equality and debug fidelity around it.
    """
    require(isinstance(body, (bytes, bytearray)) and body,
            f"{context}: body is empty")
    body = bytes(body)
    require(isinstance(sites, list) and sites,
            f"{context}: no site is declared")
    items, successors, entries = ia32_relational_flow_walk(
        body, relocations, context, code_length, external_entries)
    index_of = {item["offset"]: index for index, item in enumerate(items)}
    predecessors = [[] for _ in items]
    for index, edges in enumerate(successors):
        for edge in edges:
            predecessors[edge].append(index)
    live = ia32_relational_flag_liveness(items, successors, context)

    image = bytearray(body)
    rewritten = []
    proved = []
    for ordinal, site in enumerate(sites):
        site_context = f"{context} site {ordinal}"
        compare_at = site["compare_offset"]
        branch_at = site["branch_offset"]
        require(compare_at in index_of and branch_at in index_of,
                f"{site_context}: an offset is not an instruction boundary")
        compare_index = index_of[compare_at]
        branch_index = index_of[branch_at]
        compare = items[compare_index]
        branch = items[branch_index]
        # Obligation 3: the pair, and only the pair.
        require(branch_index == compare_index + 1,
                f"{site_context}: the branch does not immediately follow the "
                "compare")
        require(compare["opcode"] in IA32_RELATIONAL_COMPARE_PAIRS,
                f"{site_context}: the instruction at {compare_at} is not a "
                "two-operand cmp with a reversible encoding")
        require(compare["flow"] == "fall",
                f"{site_context}: the compare is a control transfer")
        require(branch["flow"] == "jcc" and branch["condition"] is not None,
                f"{site_context}: the instruction at {branch_at} is not a "
                "conditional branch this table can mirror")
        require(predecessors[branch_index] == [compare_index],
                f"{site_context}: the branch has a predecessor other than "
                "its compare, so another path would consume flags this "
                "compare did not produce")
        # The full semantic table on the pair alone (tier B): this is what
        # proves the compare really is the two-operand form the direction bit
        # exchanges, with its operands named.
        decoded = decode_ia32_bijection_instruction(
            body, compare_at, f"{site_context} compare", relocations)
        require(decoded["opcode"] == compare["opcode"]
                and decoded["length"] == compare["length"],
                f"{site_context}: the two decoders disagree about the compare")
        decode_ia32_bijection_instruction(
            body, branch_at, f"{site_context} branch", relocations)
        # Obligation 4: the mirror, from the closed table.
        seed_name = IA32_CONDITION_NAMES[branch["condition"]]
        require(seed_name in IA32_RELATIONAL_MIRROR,
                f"{site_context}: condition 'j{seed_name}' has no mirror -- "
                "it reads a flag whose value under the reversal is not a "
                "function of the original flags")
        image_name = IA32_RELATIONAL_MIRROR[seed_name]
        require(site["seed_condition"] == seed_name
                and site["image_condition"] == image_name,
                f"{site_context}: the declared condition pair is not the "
                "closed table's mirror")
        # Obligation 5: flag deadness at both successors.
        out = frozenset().union(*[live[edge] for edge in successors[
            branch_index]]) if successors[branch_index] else frozenset()
        offending = sorted(out & IA32_RELATIONAL_CHANGED_FLAGS)
        require(not offending,
                f"{site_context}: the reversal changes {offending} and a "
                "successor of the branch reads it")
        # Obligation 7: no rewritten byte is a relocation operand.
        compare_byte = compare["opcode_at"]
        branch_byte = branch["opcode_at"] + (
            1 if branch["opcode"] >= 0x0F00 else 0)
        require(compare_byte not in relocation_offsets
                and branch_byte not in relocation_offsets,
                f"{site_context}: a rewritten byte overlaps a relocation")
        image[compare_byte] = IA32_RELATIONAL_COMPARE_PAIRS[compare["opcode"]]
        image[branch_byte] = (image[branch_byte] & 0xF0) | \
            IA32_CONDITION_CODES[image_name]
        rewritten.extend([compare_byte, branch_byte])
        proved.append({
            "compare_offset": compare_at, "branch_offset": branch_at,
            "seed_condition": seed_name, "image_condition": image_name,
            "seed_compare_opcode": compare["opcode"],
            "image_compare_opcode":
                IA32_RELATIONAL_COMPARE_PAIRS[compare["opcode"]],
            "changed_flags": sorted(IA32_RELATIONAL_CHANGED_FLAGS),
            "flags_live_out": sorted(out),
        })
    # Obligation 5 (continued): an external entry point is entered by the
    # runtime, not by a decoded edge, so nothing proves what flag state it
    # was given.  Requiring the changed flags dead there is what makes an EH
    # funclet unable to observe the reversal.
    for entry in entries[1:]:
        offending = sorted(live[entry] & IA32_RELATIONAL_CHANGED_FLAGS)
        require(not offending,
                f"{context}: the external entry at {items[entry]['offset']} "
                f"has {offending} live, and the reversal changes it")
    image = bytes(image)
    require(image != body, f"{context}: the image does not move the body")
    rewritten = sorted(set(rewritten))
    require(len(rewritten) == 2 * len(sites),
            f"{context}: two sites rewrite the same byte")
    require({index for index in range(len(body)) if body[index] != image[index]}
            <= set(rewritten),
            f"{context}: the image changed a byte no site declares")
    # Obligation 6: the image re-decodes to the same shape.
    image_items, image_successors, image_entries = ia32_relational_flow_walk(
        image, relocations, f"{context} image", code_length, external_entries)
    require(len(image_items) == len(items)
            and all(left["offset"] == right["offset"]
                    and left["length"] == right["length"]
                    and left["flow"] == right["flow"]
                    and left["target"] == right["target"]
                    for left, right in zip(items, image_items))
            and image_successors == successors
            and image_entries == entries,
            f"{context}: the image does not re-decode to the same "
            "boundaries, flow and branch targets")
    for site in proved:
        item = image_items[index_of[site["branch_offset"]]]
        require(IA32_CONDITION_NAMES[item["condition"]]
                == site["image_condition"],
                f"{context}: the image branch is not the mirrored condition")
    # Every claim about the image is measured ON the image.  The mirrored
    # condition can read a flag the seed's did not (`jg` reads ZF where `jl`
    # does not), so the deadness proof is re-run on the rewritten body and the
    # image's own live sets are recorded in the proof.
    image_live = ia32_relational_flag_liveness(
        image_items, image_successors, f"{context} image")
    for site in proved:
        branch_index = index_of[site["branch_offset"]]
        edges = image_successors[branch_index]
        out = frozenset().union(*[image_live[edge] for edge in edges]) \
            if edges else frozenset()
        offending = sorted(out & IA32_RELATIONAL_CHANGED_FLAGS)
        require(not offending,
                f"{context}: after the rewrite a successor of the branch at "
                f"{site['branch_offset']} reads {offending}")
        site["image_flags_live_out"] = sorted(out)
    for entry in image_entries[1:]:
        offending = sorted(image_live[entry] & IA32_RELATIONAL_CHANGED_FLAGS)
        require(not offending,
                f"{context}: after the rewrite the external entry at "
                f"{image_items[entry]['offset']} has {offending} live")
    return image, {
        "kind": RELATIONAL_FORM_KIND,
        "sites": proved,
        "instruction_count": len(items),
        "rewritten_offsets": rewritten,
        "external_entries": [items[index]["offset"] for index in entries[1:]],
        "preserved_flags": sorted(IA32_RELATIONAL_PRESERVED_FLAGS),
        "changed_flags": sorted(IA32_RELATIONAL_CHANGED_FLAGS),
    }


def relational_form_external_entries(
    obj: "CoffObject", section: dict, context: str,
) -> frozenset:
    """Every in-body offset a relocation of this COMDAT or of its closure
    children names.

    On a C++ EH function these are exactly the unwind funclet heads the
    `.xdata$x` table hands to the runtime -- code no decoded edge reaches.
    Deriving them (rather than letting an author declare them) is what makes
    obligation 2's reachability requirement closable without weakening it.
    """
    number = section["number"]
    entries = {row["target_value"] for row in detailed_relocations(obj, section)
               if row.get("target_section") == number}
    count, names = _comdat_child_closure(obj, section)
    require(count == len(names), f"{context}: malformed COMDAT closure")
    for child_name in names:
        child = _comdat_child(obj, section, child_name)
        entries |= {row["target_value"]
                    for row in detailed_relocations(obj, child)
                    if row.get("target_section") == number}
    entries.discard(0)
    return frozenset(entries)


def validate_relational_form(
    value: object, context: str, body_length: int,
) -> dict:
    """Validate one relational-form certificate declaration."""
    require(isinstance(value, dict), f"{context} must be an object")
    exact_audit_keys(value, {
        "kind", "sites", "expected_instruction_count",
        "expected_rewritten_offsets", "expected_external_entries",
        "expected_seed_debug_s_sha256", "authenticity_rationale",
        "expected_code_length",
    }, context, optional={"expected_code_length"})
    require(value.get("kind") == RELATIONAL_FORM_KIND,
            f"{context}.kind differs")
    sites = value.get("sites")
    require(isinstance(sites, list) and 1 <= len(sites) <= 64,
            f"{context}.sites is invalid")
    normalized_sites = []
    previous = -1
    for index, site in enumerate(sites):
        site_context = f"{context}.sites[{index}]"
        require(isinstance(site, dict), f"{site_context} must be an object")
        exact_audit_keys(site, {
            "compare_offset", "branch_offset",
            "seed_condition", "image_condition",
        }, site_context)
        compare_at = require_exact_int(
            site.get("compare_offset"), f"{site_context}.compare_offset",
            minimum=0, maximum=body_length - 2)
        branch_at = require_exact_int(
            site.get("branch_offset"), f"{site_context}.branch_offset",
            minimum=1, maximum=body_length - 1)
        require(compare_at > previous,
                f"{site_context}: sites are unsorted or overlapping")
        require(compare_at < branch_at,
                f"{site_context}: the branch does not follow the compare")
        previous = branch_at
        seed_condition = site.get("seed_condition")
        require(seed_condition in IA32_RELATIONAL_MIRROR,
                f"{site_context}.seed_condition has no mirror in the closed "
                "table")
        require(site.get("image_condition")
                == IA32_RELATIONAL_MIRROR[seed_condition],
                f"{site_context}.image_condition is not the closed table's "
                "mirror")
        normalized_sites.append({
            "compare_offset": compare_at, "branch_offset": branch_at,
            "seed_condition": seed_condition,
            "image_condition": IA32_RELATIONAL_MIRROR[seed_condition],
        })
    offsets = value.get("expected_rewritten_offsets")
    require(isinstance(offsets, list)
            and len(offsets) == 2 * len(normalized_sites)
            and offsets == sorted(set(offsets))
            and all(type(offset) is int and 0 <= offset < body_length
                    for offset in offsets),
            f"{context}.expected_rewritten_offsets is invalid")
    external = value.get("expected_external_entries")
    require(isinstance(external, list)
            and external == sorted(set(external))
            and all(type(item) is int and 0 < item < body_length
                    for item in external),
            f"{context}.expected_external_entries is invalid")
    rationale = value.get("authenticity_rationale")
    require(isinstance(rationale, str) and len(rationale) >= 40,
            f"{context}.authenticity_rationale is missing")
    normalized = {
        "kind": RELATIONAL_FORM_KIND,
        "sites": normalized_sites,
        "expected_instruction_count": require_exact_int(
            value.get("expected_instruction_count"),
            f"{context}.expected_instruction_count", minimum=2),
        "expected_rewritten_offsets": list(offsets),
        "expected_external_entries": list(external),
        "expected_seed_debug_s_sha256": require_sha(
            value.get("expected_seed_debug_s_sha256"),
            f"{context}.expected_seed_debug_s_sha256"),
        "authenticity_rationale": rationale,
    }
    code_length = value.get("expected_code_length")
    if code_length is not None:
        normalized["expected_code_length"] = require_exact_int(
            code_length, f"{context}.expected_code_length",
            minimum=2, maximum=body_length)
    return normalized


def compose_retail_exact_relational_form(
    seed_bytes: bytes,
    donor_bytes: bytes,
    function: dict,
    retail_body: bytes,
) -> tuple[bytes, dict]:
    """Install the reversed compares after proving they are retail's own code.

    See the class comment: this is a certificate.  The pre-image is an
    ordinary census-pinned compile of the same translation unit; the reversal
    is proved sound against the body's own control flow with a per-flag
    liveness fixpoint; and the result is REFUSED unless it equals the pinned
    retail oracle under the relocation mask.  Body installation delegates,
    unchanged, to the equal-body primitive.
    """
    require(function.get("splice_class") == RELATIONAL_FORM_CLASS,
            "splice class is not retail_exact_relational_form")
    require("target_source_refactor" not in function,
            "relational-form functions carry no source refactor")
    require(isinstance(retail_body, (bytes, bytearray)) and retail_body,
            "retail oracle body is missing")
    spec = function["relational_form"]
    seed = CoffObject(seed_bytes)
    donor = CoffObject(donor_bytes)
    mangled = function["mangled"]
    sp = seed.function_section(mangled)
    dp = donor.function_section(mangled)
    # Obligation 1: the provenance battery, identical to the bijection's.
    require(sp["number"] == dp["number"]
            == function["expected_section_number"],
            "relational-form target section seat changed")
    require(len(seed.sections) == len(donor.sections)
            == function["expected_section_count"],
            "relational-form global section count changed")
    seed_functions = function_multiset(seed)
    donor_functions = function_multiset(donor)
    require(seed_functions == donor_functions
            and sum(seed_functions.values())
            == function["expected_function_count"],
            "relational-form donor function set differs")
    seed_comdats = comdat_primary_identity_multiset(seed)
    donor_comdats = comdat_primary_identity_multiset(donor)
    require(seed_comdats == donor_comdats
            and sum(seed_comdats.values())
            == function["expected_comdat_count"],
            "relational-form donor COMDAT identity set differs")
    require(
        sp["raw_size"] == dp["raw_size"] == function["expected_body_length"]
        and sp["relocation_count"] == dp["relocation_count"]
        == function["expected_relocation_count"]
        and sp["line_count"] == function["expected_seed_line_count"]
        and dp["line_count"] == function["expected_donor_line_count"]
        and sp["name"] == dp["name"]
        and sp["characteristics"] == dp["characteristics"]
        == function["expected_characteristics"],
        "relational-form target header/count pins changed",
    )
    require(
        section_definitions(seed)[sp["number"]]["selection"]
        == section_definitions(donor)[dp["number"]]["selection"]
        == function["expected_selection"],
        "relational-form COMDAT selection changed",
    )
    expected_closure = tuple(function["expected_closure"])
    require(_comdat_child_closure(seed, sp)
            == _comdat_child_closure(donor, dp)
            == (len(expected_closure), expected_closure),
            "relational-form target closure changed")
    require(list(expected_closure) in (RELATIONAL_FORM_FPO_CLOSURE,
                                       RELATIONAL_FORM_EH_CLOSURE),
            "relational-form closure pin names no installation delegate")
    delegate = relational_form_delegate(function["expected_closure"],
                                        function["expected_code_renames"])
    require(instruction_mosaic_metadata_sha256(seed, sp)
            == function["expected_seed_metadata_sha256"]
            and instruction_mosaic_metadata_sha256(donor, dp)
            == function["expected_donor_metadata_sha256"],
            "relational-form metadata differs from its pin")
    seed_body = coff_body(seed, sp)
    donor_body = coff_body(donor, dp)
    require(sha256_bytes(seed_body) == function["expected_seed_body_sha256"]
            and sha256_bytes(donor_body)
            == function["expected_donor_body_sha256"],
            "relational-form seed/donor body differs from its pin")
    seed_rows = detailed_relocations(seed, sp)
    donor_rows = detailed_relocations(donor, dp)
    code_renames = require_instruction_mosaic_semantic_relocations(
        seed, sp, donor, dp, "relational-form code")
    require([[offset, kind] for offset, kind in code_renames]
            == function["expected_code_renames"],
            "relational-form code rename set changed")
    # Obligation 7: this class can never move a relocation.
    require(len(seed_rows) == len(donor_rows)
            and [(row["offset"], row["type"], row["addend"])
                 for row in seed_rows]
            == [(row["offset"], row["type"], row["addend"])
                for row in donor_rows],
            "relational-form donor relocation layout differs from the seed")
    require([row["target"] for row in seed_rows if row["type"] == 0x0014]
            == [row["target"] for row in donor_rows if row["type"] == 0x0014],
            "relational-form donor call/branch relocation targets differ "
            "from the seed")
    installed_rows = [{**left, "offset": right["offset"]}
                      for left, right in zip(seed_rows, donor_rows)]
    relocation_offsets = frozenset(
        row["offset"] + byte
        for row in installed_rows for byte in range(row["width"]))
    relocation_symbols = {
        row["offset"]: {"width": row["width"], "target": row["target"]}
        for row in installed_rows}
    # Obligation 2's external entry set is DERIVED from both objects and must
    # equal the pin: a body whose EH funclet set moved refuses here rather
    # than being proved on a partial graph.
    external = relational_form_external_entries(
        seed, sp, "relational-form seed")
    require(external == relational_form_external_entries(
                donor, dp, "relational-form donor"),
            "relational-form donor external entry set differs from the seed")
    require(sorted(external) == spec["expected_external_entries"],
            "relational-form external entry set changed")

    image, proof = apply_relational_form(
        donor_body, spec["sites"], relocation_offsets, "relational-form image",
        relocation_symbols, spec.get("expected_code_length"), external,
    )
    require(proof["rewritten_offsets"] == spec["expected_rewritten_offsets"]
            and proof["instruction_count"]
            == spec["expected_instruction_count"],
            "relational-form image differs from its declaration")
    require(sha256_bytes(image) == function["expected_body_sha256"],
            "relational-form image differs from its pin")

    # Obligation 8.
    pinned_length = function["retail_oracle"]["length"]
    require(len(retail_body) == pinned_length == len(image),
            "relational-form retail length changed")
    semantic_detail = require_retail_relocation_oracle(
        installed_rows, bytes(retail_body),
        int(function["retail_oracle"]["address"], 16),
        function["retail_relocations"],
        "relational-form retail relocation oracle",
    )
    masked_image = bytearray(image)
    masked_retail = bytearray(retail_body)
    for row in installed_rows:
        start, width = row["offset"], row["width"]
        masked_image[start:start + width] = b"\0" * width
        masked_retail[start:start + width] = b"\0" * width
    differing = sum(left != right
                    for left, right in zip(masked_image, masked_retail))
    require(differing == 0,
            f"relational-form output is not retail-exact: {differing} "
            "byte(s) differ under the relocation mask")

    derived = bytearray(donor_bytes)
    derived[dp["raw_offset"]:dp["raw_offset"] + dp["raw_size"]] = image
    derived = bytes(derived)
    effective = {
        "mangled": mangled,
        "splice_class": delegate,
        "expected_body_length": function["expected_body_length"],
        "expected_body_sha256": function["expected_body_sha256"],
        "expected_changed_offsets": function["expected_changed_offsets"],
    }
    if delegate == "equal_body_eh_structural_local":
        effective["expected_code_renames"] = function["expected_code_renames"]
        effective["expected_xdata_rename_offsets"] = function[
            "expected_xdata_rename_offsets"]
    composed, detail = compose_equal_body_comdat(seed_bytes, derived, effective)

    checked = CoffObject(composed)
    cp = checked.function_section(mangled)
    require(coff_body(checked, cp) == image,
            "relational-form composed body differs from the image")
    composed_rows = detailed_relocations(checked, cp)
    require(composed_rows == installed_rows
            and [row["symbol_index"] for row in composed_rows]
            == [row["symbol_index"] for row in seed_rows]
            and _coff_table_bytes(checked, cp, "relocations")
            == _coff_table_bytes(seed, sp, "relocations")
            and _coff_table_bytes(checked, cp, "lines")
            == _coff_table_bytes(seed, sp, "lines"),
            "relational-form output changed seed relocation/line bytes")
    # Obligation 9.  Nothing moves and no register changes role, so every
    # closure child -- `.debug$S` included, which the bijection has to map --
    # must come out byte-identical to the seed's.
    debug_child = _comdat_child(checked, cp, ".debug$S")
    require(sha256_bytes(coff_body(checked, debug_child))
            == spec["expected_seed_debug_s_sha256"],
            "relational-form debug$S differs from its pin")
    for child_name in expected_closure:
        require(coff_body(checked, _comdat_child(checked, cp, child_name))
                == coff_body(seed, _comdat_child(seed, sp, child_name)),
                f"relational-form output changed its {child_name} child")
    # Every COFF line row still lands on an instruction boundary of the image.
    boundaries = {item["offset"] for item in ia32_relational_flow_walk(
        image, relocation_symbols, "relational-form image lines",
        spec.get("expected_code_length"), external)[0]}
    if cp["line_count"] > 1:
        line_table = coff_table(checked, cp, "lines")
        for index in range(1, cp["line_count"]):
            row_offset, row_line = struct.unpack_from("<IH", line_table,
                                                      index * 6)
            require(row_line != 0 and row_offset in boundaries,
                    f"relational-form line row at {row_offset} does not land "
                    "on an image instruction boundary")
    allowed = set(range(sp["raw_offset"], sp["raw_offset"] + sp["raw_size"]))
    require({index for index in range(len(seed_bytes))
             if seed_bytes[index] != composed[index]} <= allowed,
            "relational-form changed bytes outside its own COMDAT")
    return composed, {
        **detail,
        "splice_class": RELATIONAL_FORM_CLASS,
        "relational_form": proof["sites"],
        "instruction_count": proof["instruction_count"],
        "rewritten_offsets": proof["rewritten_offsets"],
        "external_entries": proof["external_entries"],
        "preserved_flags": proof["preserved_flags"],
        "changed_flags": proof["changed_flags"],
        "retail_exact": True,
        **semantic_detail,
    }


# ---------------------------------------------------------------------------
# retail_exact_composed_rewriting: THREE CERTIFICATES INSIDE ONE ENTRY
# ---------------------------------------------------------------------------
#
# WHY THIS CLASS EXISTS
#
# Four certificate classes already state, each on its own terms, that some
# part of a compiled body is retail's own code rearranged: the topological
# window reordering, the regional register bijection, the web recolour and
# the mirrored relational form.  Each ends with `differing == 0` against the
# pinned retail oracle, and the manifest admits exactly one entry per mangled
# name.  Together those two facts mean a class can only ever be handed a
# function it finishes ALONE -- there is no seam at which one certificate
# could hand a partially corrected body to the next.
#
# A real compiled function is not so tidy.  `LegoROI::Read` differs from
# retail in five reordered windows, two regionally renamed spans and three
# reversed comparisons, and no one of those statements is true of the whole
# body.  This class is the seam: it applies the three primitives IN ONE
# ENTRY, in the one order that is sound, and proves the composition.
#
# It invents no new licence.  Every byte it installs is a byte this compiler
# emitted for this function; every obligation is the obligation the
# corresponding single-statement class already discharges, checked by the
# very same `apply_*` primitive, unchanged; and the result is refused unless
# it equals the pinned retail oracle under the relocation mask.  What is new
# is the composition, and the composition carries four obligations of its
# own:
#
#  C1  ORDER.  A reordering moves instruction boundaries; a bijection and a
#      relational reversal are byte-local and rewrite fields of instructions
#      identified BY those boundaries.  So every declared window is applied
#      first, and the byte-local certificates are then measured on the
#      reordered image -- which is where their declared offsets live.  A
#      bijection and a relational reversal commute exactly (disjoint byte
#      sets, each proof invariant under the other), so their relative order
#      is free and is fixed here as declared.
#
#  C2  DISJOINTNESS.  The bijection regions are required to be sorted and
#      non-overlapping, the relational sites to be sorted, and the three
#      rewritten byte sets to be pairwise disjoint.  A byte rewritten twice
#      would make the second proof's pre-image something no certificate
#      described.
#
#  C3  SEPARATE DEBUG CLAIMS.  A regional bijection maps the `.debug$S`
#      S_REGISTER records naming a register in its support.  Two bijections
#      applied one after the other would map the same record twice -- the
#      second one reading the first one's output as if it were the compiler's
#      allocation -- and the result would name a register no region uses.
#      So every bijection's record set is measured on the SEED's stream, the
#      sets are required to be PAIRWISE DISJOINT, and each is then applied
#      once.  A record two regions both claim is refused.
#
#  C4  PROVENANCE.  The pre-image is the SEED's own compiler-produced body:
#      no donor bytes are installed.  The donor the manifest names is a
#      WITNESS -- an independent compiler state of the same translation unit
#      that emits this same body -- and is required to reproduce it exactly,
#      which is what makes the pin it carries mean anything.
#
# Everything else is the existing machinery: obligation 7 of the schedule
# class (`require_instruction_schedule_debug_fidelity`) re-derives every COFF
# line row against the image, obligation 5 of the relational class derives
# the external entry set from the object's own relocations, the retail
# relocation oracle binds every masked operand to the symbol it resolves to,
# and installation is delegated UNCHANGED to `compose_equal_body_comdat`.


COMPOSED_REWRITING_CLASS = "retail_exact_composed_rewriting"


COMPOSED_REWRITING_KIND = "schedule_bijection_relational_v1"


def composed_rewriting_delegate(expected_closure: object) -> str:
    """Name the installation delegate from the closure pin alone.

    The installed object is the SEED with its own body replaced, so there is
    no donor rename to express and no relocation to move: the FPO closure
    takes the strict primitive and the EH closure takes the structural-local
    one, whose rename and xdata-rename sets are then required to be empty.
    """
    if list(expected_closure) == INSTRUCTION_SCHEDULE_FPO_CLOSURE:
        return "equal_body_strict"
    return "equal_body_eh_structural_local"


def validate_composed_rewriting(
    value: object, context: str, body_length: int,
) -> dict:
    """Validate one composed-rewriting certificate declaration."""
    require(isinstance(value, dict), f"{context} must be an object")
    exact_audit_keys(value, {
        "kind", "windows", "register_bijections", "relational_sites",
        "expected_instruction_count", "expected_changed_offsets",
        "expected_procedure_range", "expected_code_symbol_references",
        "expected_external_entries", "expected_seed_debug_s_sha256",
        "expected_image_debug_s_sha256", "expected_code_length",
        "expected_internal_relocation_targets", "authenticity_rationale",
    }, context, optional={"windows", "register_bijections",
                          "relational_sites", "expected_code_length",
                          "expected_internal_relocation_targets"})
    require(value.get("kind") == COMPOSED_REWRITING_KIND,
            f"{context}.kind differs")
    code_length = value.get("expected_code_length")
    if code_length is not None:
        code_length = require_exact_int(
            code_length, f"{context}.expected_code_length",
            minimum=2, maximum=body_length)
    targets = value.get("expected_internal_relocation_targets")
    if targets is not None:
        require(isinstance(targets, list)
                and targets == sorted(set(targets))
                and all(type(item) is int and 0 <= item < body_length
                        for item in targets),
                f"{context}.expected_internal_relocation_targets is invalid")
    normalized_windows = []
    if value.get("windows") is not None:
        windows = value["windows"]
        require(isinstance(windows, list) and 1 <= len(windows) <= 32,
                f"{context}.windows must contain 1..32 windows")
        normalized_windows = _validate_schedule_windows(
            windows, context, body_length, code_length, targets)
        require(not any(window.get("relocation_reseat")
                        for window in normalized_windows),
                f"{context}: this class refuses to move a relocation")
    # The bijections.  Each is exactly the declaration the single-statement
    # certificate validates, minus the pins that belong to the composition as
    # a whole (the instruction count and the two debug$S digests).
    normalized_bijections = []
    bijection_bytes = []
    previous_end = 0
    for index, item in enumerate(value.get("register_bijections") or []):
        item_context = f"{context}.register_bijections[{index}]"
        require(isinstance(item, dict), f"{item_context} must be an object")
        exact_audit_keys(item, {
            "mapping", "region_start", "region_end",
            "expected_region_instruction_count",
            "expected_rewritten_offsets", "debug_s_register_map",
        }, item_context)
        mapping = item.get("mapping")
        require(isinstance(mapping, dict) and 2 <= len(mapping) <= 8
                and all(isinstance(key, str) and isinstance(name, str)
                        and key in _IA32_REGISTER_NUMBERS
                        and name in _IA32_REGISTER_NUMBERS
                        for key, name in mapping.items()),
                f"{item_context}.mapping is invalid")
        require(set(mapping) == set(mapping.values())
                and len(set(mapping.values())) == len(mapping)
                and all(key != name for key, name in mapping.items()),
                f"{item_context}.mapping is not a fixed-point-free bijection")
        require(not (set(mapping) & _IA32_STRUCTURAL_REGISTERS),
                f"{item_context}.mapping touches ESP or EBP")
        start = require_exact_int(item.get("region_start"),
                                  f"{item_context}.region_start",
                                  minimum=1, maximum=body_length - 1)
        end = require_exact_int(item.get("region_end"),
                                f"{item_context}.region_end",
                                minimum=2, maximum=body_length - 1)
        # C2: sorted and non-overlapping.
        require(previous_end <= start < end,
                f"{item_context}: regions are unsorted or overlapping")
        previous_end = end
        offsets = item.get("expected_rewritten_offsets")
        require(isinstance(offsets, list) and offsets
                and offsets == sorted(set(offsets))
                and all(type(offset) is int and start <= offset < end
                        for offset in offsets),
                f"{item_context}.expected_rewritten_offsets is invalid")
        bijection_bytes.extend(offsets)
        declared = item.get("debug_s_register_map")
        require(isinstance(declared, list) and len(declared) <= 8,
                f"{item_context}.debug_s_register_map is invalid")
        normalized_map = []
        for position, record in enumerate(declared):
            record_context = f"{item_context}.debug_s_register_map[{position}]"
            require(isinstance(record, dict),
                    f"{record_context} must be an object")
            exact_audit_keys(record, {
                "name", "record_offset", "donor_register", "image_register",
            }, record_context)
            require(isinstance(record.get("name"), str) and record["name"],
                    f"{record_context}.name is invalid")
            require(record.get("donor_register") in mapping
                    and mapping[record["donor_register"]]
                    == record.get("image_register"),
                    f"{record_context} is not the declared mapping")
            normalized_map.append({
                "name": record["name"],
                "record_offset": require_exact_int(
                    record.get("record_offset"),
                    f"{record_context}.record_offset", minimum=0),
                "donor_register": record["donor_register"],
                "image_register": record["image_register"],
            })
        normalized_bijections.append({
            "mapping": dict(sorted(mapping.items())),
            "region_start": start, "region_end": end,
            "expected_region_instruction_count": require_exact_int(
                item.get("expected_region_instruction_count"),
                f"{item_context}.expected_region_instruction_count",
                minimum=1),
            "expected_rewritten_offsets": list(offsets),
            "debug_s_register_map": normalized_map,
        })
    # The relational sites, validated exactly as the single-statement class
    # validates them.
    normalized_sites = []
    relational_bytes = []
    previous = -1
    for index, site in enumerate(value.get("relational_sites") or []):
        site_context = f"{context}.relational_sites[{index}]"
        require(isinstance(site, dict), f"{site_context} must be an object")
        exact_audit_keys(site, {
            "compare_offset", "branch_offset", "seed_condition",
            "image_condition", "expected_rewritten_offsets",
        }, site_context)
        compare_at = require_exact_int(
            site.get("compare_offset"), f"{site_context}.compare_offset",
            minimum=0, maximum=body_length - 2)
        branch_at = require_exact_int(
            site.get("branch_offset"), f"{site_context}.branch_offset",
            minimum=1, maximum=body_length - 1)
        require(compare_at > previous,
                f"{site_context}: sites are unsorted or overlapping")
        require(compare_at < branch_at,
                f"{site_context}: the branch does not follow the compare")
        previous = branch_at
        seed_condition = site.get("seed_condition")
        require(seed_condition in IA32_RELATIONAL_MIRROR,
                f"{site_context}.seed_condition has no mirror in the closed "
                "table")
        require(site.get("image_condition")
                == IA32_RELATIONAL_MIRROR[seed_condition],
                f"{site_context}.image_condition is not the closed table's "
                "mirror")
        offsets = site.get("expected_rewritten_offsets")
        require(isinstance(offsets, list) and len(offsets) == 2
                and offsets == sorted(set(offsets))
                and all(type(offset) is int and 0 <= offset < body_length
                        for offset in offsets),
                f"{site_context}.expected_rewritten_offsets is invalid")
        relational_bytes.extend(offsets)
        normalized_sites.append({
            "compare_offset": compare_at, "branch_offset": branch_at,
            "seed_condition": seed_condition,
            "image_condition": IA32_RELATIONAL_MIRROR[seed_condition],
            "expected_rewritten_offsets": list(offsets),
        })
    require(normalized_windows or normalized_bijections or normalized_sites,
            f"{context} declares no certificate")
    require(len(normalized_windows) + len(normalized_bijections)
            + len(normalized_sites) >= 2,
            f"{context} composes nothing: a single statement belongs to its "
            "own class")
    # C2, the byte-level half.
    window_bytes = {offset for window in normalized_windows
                    for offset in range(window["start"], window["end"])}
    require(len(set(bijection_bytes)) == len(bijection_bytes),
            f"{context}: two bijections rewrite the same byte")
    require(len(set(relational_bytes)) == len(relational_bytes),
            f"{context}: two relational sites rewrite the same byte")
    require(not (set(bijection_bytes) & set(relational_bytes)),
            f"{context}: a bijection and a relational reversal rewrite the "
            "same byte")
    require(not (window_bytes & (set(bijection_bytes)
                                 | set(relational_bytes))),
            f"{context}: a byte-local certificate rewrites a byte inside a "
            "reordered window")
    changed = value.get("expected_changed_offsets")
    require(isinstance(changed, list) and changed
            and changed == sorted(set(changed))
            and all(type(offset) is int and 0 <= offset < body_length
                    for offset in changed),
            f"{context}.expected_changed_offsets is invalid")
    require(set(bijection_bytes) | set(relational_bytes) <= set(changed),
            f"{context}.expected_changed_offsets omits a rewritten byte")
    require(all(offset in window_bytes
                or offset in set(bijection_bytes) | set(relational_bytes)
                for offset in changed),
            f"{context}.expected_changed_offsets names a byte no declared "
            "certificate can move")
    procedure = value.get("expected_procedure_range")
    require(isinstance(procedure, list) and len(procedure) == 3
            and all(type(item) is int and item >= 0 for item in procedure)
            and procedure[0] == body_length
            and procedure[1] <= procedure[2] <= body_length,
            f"{context}.expected_procedure_range is invalid")
    references = value.get("expected_code_symbol_references")
    require(isinstance(references, list)
            and all(isinstance(item, list) and len(item) == 3
                    and isinstance(item[0], str) and isinstance(item[1], str)
                    and type(item[2]) is int and 0 <= item[2] <= body_length
                    for item in references),
            f"{context}.expected_code_symbol_references is invalid")
    external = value.get("expected_external_entries")
    require(isinstance(external, list)
            and external == sorted(set(external))
            and all(type(item) is int and 0 < item < body_length
                    for item in external),
            f"{context}.expected_external_entries is invalid")
    rationale = value.get("authenticity_rationale")
    require(isinstance(rationale, str) and len(rationale) >= 40,
            f"{context}.authenticity_rationale is missing")
    normalized = {
        "kind": COMPOSED_REWRITING_KIND,
        "expected_instruction_count": require_exact_int(
            value.get("expected_instruction_count"),
            f"{context}.expected_instruction_count", minimum=2),
        "expected_changed_offsets": list(changed),
        "expected_procedure_range": list(procedure),
        "expected_code_symbol_references": [list(item)
                                            for item in references],
        "expected_external_entries": list(external),
        "expected_seed_debug_s_sha256": require_sha(
            value.get("expected_seed_debug_s_sha256"),
            f"{context}.expected_seed_debug_s_sha256"),
        "expected_image_debug_s_sha256": require_sha(
            value.get("expected_image_debug_s_sha256"),
            f"{context}.expected_image_debug_s_sha256"),
        "authenticity_rationale": rationale,
    }
    normalized["windows"] = normalized_windows
    normalized["register_bijections"] = normalized_bijections
    normalized["relational_sites"] = normalized_sites
    if code_length is not None:
        normalized["expected_code_length"] = code_length
    if targets is not None:
        normalized["expected_internal_relocation_targets"] = list(targets)
    return normalized


def compose_retail_exact_composed_rewriting(
    seed_bytes: bytes,
    donor_bytes: bytes,
    function: dict,
    retail_body: bytes,
) -> tuple[bytes, dict]:
    """Apply a reordering, then regional bijections, then reversed compares.

    See the class comment above.  Each primitive is the LANDED one, called
    unchanged; C1 fixes the order, C2 the disjointness, C3 the debug$S
    claims and C4 the provenance; and the result is refused unless it equals
    the pinned retail oracle under the relocation mask.
    """
    require(function.get("splice_class") == COMPOSED_REWRITING_CLASS,
            "splice class is not retail_exact_composed_rewriting")
    require("target_source_refactor" not in function,
            "composed-rewriting functions carry no source refactor")
    require(isinstance(retail_body, (bytes, bytearray)) and retail_body,
            "retail oracle body is missing")
    spec = function["composed_rewriting"]
    seed = CoffObject(seed_bytes)
    donor = CoffObject(donor_bytes)
    mangled = function["mangled"]
    sp = seed.function_section(mangled)
    dp = donor.function_section(mangled)
    require(sp["number"] == function["expected_section_number"]
            and dp["number"] == function["expected_donor_section_number"],
            "composed-rewriting target section seat changed: seed "
            f"{sp['number']} donor {dp['number']}")
    require(len(seed.sections) == function["expected_section_count"]
            and len(donor.sections)
            == function["expected_donor_section_count"],
            "composed-rewriting global section count changed: seed "
            f"{len(seed.sections)} donor {len(donor.sections)}")
    seed_functions = function_multiset(seed)
    require(seed_functions == function_multiset(donor)
            and sum(seed_functions.values())
            == function["expected_function_count"],
            "composed-rewriting witness function set differs: "
            f"{sum(seed_functions.values())} vs "
            f"{sum(function_multiset(donor).values())}")
    seed_comdats = comdat_primary_identity_multiset(seed)
    require(seed_comdats == comdat_primary_identity_multiset(donor)
            and sum(seed_comdats.values())
            == function["expected_comdat_count"],
            "composed-rewriting witness COMDAT identity set differs: "
            f"{sum(seed_comdats.values())} vs "
            f"{sum(comdat_primary_identity_multiset(donor).values())}")
    require(
        sp["raw_size"] == dp["raw_size"] == function["expected_body_length"]
        and sp["relocation_count"] == dp["relocation_count"]
        == function["expected_relocation_count"]
        and sp["line_count"] == function["expected_seed_line_count"]
        and dp["line_count"] == function["expected_donor_line_count"]
        and sp["name"] == dp["name"]
        and sp["characteristics"] == dp["characteristics"]
        == function["expected_characteristics"],
        "composed-rewriting target header/count pins changed: raw "
        f"{sp['raw_size']}/{dp['raw_size']} relocations "
        f"{sp['relocation_count']}/{dp['relocation_count']} lines "
        f"{sp['line_count']}/{dp['line_count']} characteristics "
        f"{sp['characteristics']}/{dp['characteristics']}",
    )
    require(
        section_definitions(seed)[sp["number"]]["selection"]
        == section_definitions(donor)[dp["number"]]["selection"]
        == function["expected_selection"],
        "composed-rewriting COMDAT selection changed: "
        f"{section_definitions(seed)[sp['number']]['selection']}",
    )
    expected_closure = tuple(function["expected_closure"])
    require(_comdat_child_closure(seed, sp)
            == _comdat_child_closure(donor, dp)
            == (len(expected_closure), expected_closure),
            "composed-rewriting target closure changed: seed "
            f"{_comdat_child_closure(seed, sp)} donor "
            f"{_comdat_child_closure(donor, dp)}")
    require(list(expected_closure) in (INSTRUCTION_SCHEDULE_FPO_CLOSURE,
                                       INSTRUCTION_SCHEDULE_EH_CLOSURE),
            "composed-rewriting closure pin names no installation delegate")
    delegate = composed_rewriting_delegate(function["expected_closure"])
    require(instruction_mosaic_metadata_sha256(seed, sp)
            == function["expected_seed_metadata_sha256"]
            and instruction_mosaic_metadata_sha256(donor, dp)
            == function["expected_donor_metadata_sha256"],
            "composed-rewriting metadata differs from its pin: seed "
            f"{instruction_mosaic_metadata_sha256(seed, sp)} donor "
            f"{instruction_mosaic_metadata_sha256(donor, dp)}")
    seed_body = coff_body(seed, sp)
    donor_body = coff_body(donor, dp)
    require(sha256_bytes(seed_body) == function["expected_seed_body_sha256"]
            and sha256_bytes(donor_body)
            == function["expected_donor_body_sha256"],
            "composed-rewriting seed/witness body differs from its pin: "
            f"seed {sha256_bytes(seed_body)} witness "
            f"{sha256_bytes(donor_body)}")
    # C4.  The donor is a provenance WITNESS: an independent compiler state
    # that emits this same body.  It is never installed, so it must reproduce
    # the seed's body exactly or the pin it carries means nothing.
    require(donor_body == seed_body,
            "composed-rewriting witness does not reproduce the seed's body")

    seed_rows = detailed_relocations(seed, sp)
    relocation_offsets = frozenset(
        row["offset"] + byte
        for row in seed_rows for byte in range(row["width"]))
    relocation_symbols = {
        row["offset"]: {"width": row["width"], "target": row["target"]}
        for row in seed_rows}
    internal_targets = frozenset(
        row["target_value"] for row in seed_rows
        if row["target_section"] == sp["number"])
    declared_targets = spec.get("expected_internal_relocation_targets")
    if declared_targets is not None:
        require(sorted(internal_targets) == declared_targets,
                "composed-rewriting in-body relocated target set changed")
    code_length = spec.get("expected_code_length")

    # C1, first half: every reordering, applied to the seed's own body.
    image = seed_body
    schedule_detail = []
    windows = spec["windows"]
    if windows:
        image, schedule_proof = apply_instruction_schedule(
            image, windows, relocation_offsets,
            "composed-rewriting schedule", relocation_symbols, code_length,
            internal_targets)
        require(not schedule_proof["relocation_reseat"],
                "composed-rewriting refuses to move a relocation")
        schedule_detail = schedule_proof["windows"]
    # C1, second half: the byte-local certificates, measured on the image the
    # reordering produced.
    bijection_detail = []
    for index, item in enumerate(spec["register_bijections"]):
        image, proof = apply_register_bijection(
            image, item["mapping"],
            (item["region_start"], item["region_end"]),
            relocation_offsets, f"composed-rewriting bijection {index}",
            relocation_symbols, code_length, internal_targets)
        require(proof["rewritten_offsets"]
                == item["expected_rewritten_offsets"],
                f"composed-rewriting bijection {index} rewrote a different "
                "byte set from its declaration")
        require(proof["region_instruction_count"]
                == item["expected_region_instruction_count"],
                f"composed-rewriting bijection {index} region instruction "
                "count differs from its declaration")
        bijection_detail.append({
            "mapping": dict(sorted(item["mapping"].items())),
            "region": [item["region_start"], item["region_end"]],
            "rewritten_offsets": proof["rewritten_offsets"],
            "region_instruction_count": proof["region_instruction_count"],
        })
    external_entries = relational_form_external_entries(
        seed, sp, "composed-rewriting external entries")
    require(sorted(external_entries) == spec["expected_external_entries"],
            "composed-rewriting external entry set differs from its "
            "declaration")
    relational_detail = []
    if spec["relational_sites"]:
        sites = [{key: item[key] for key in ("compare_offset",
                                             "branch_offset",
                                             "seed_condition",
                                             "image_condition")}
                 for item in spec["relational_sites"]]
        image, proof = apply_relational_form(
            image, sites, relocation_offsets,
            "composed-rewriting relational", relocation_symbols,
            code_length, external_entries)
        require(proof["rewritten_offsets"]
                == sorted(offset for item in spec["relational_sites"]
                          for offset in item["expected_rewritten_offsets"]),
                "composed-rewriting relational rewrite set differs from its "
                "declaration")
        relational_detail = proof["sites"]
    require(image != seed_body,
            "composed-rewriting image does not move the seed body")
    image_instructions = decode_ia32_bijection_body(
        image, "composed-rewriting image", relocation_symbols, code_length)
    require(len(image_instructions) == spec["expected_instruction_count"],
            "composed-rewriting instruction count differs from its "
            "declaration")
    changed = sorted(index for index in range(len(seed_body))
                     if seed_body[index] != image[index])
    require(changed == spec["expected_changed_offsets"],
            "composed-rewriting image differs from its declaration")
    require(sha256_bytes(image) == function["expected_body_sha256"],
            "composed-rewriting image differs from its pin")
    require(changed == function["expected_changed_offsets"],
            "composed-rewriting changed offsets differ from their pin")

    # Obligation 7 of the schedule class, measured on the IMAGE with the
    # SEED's own tables -- which are the tables this composition installs.
    debug_detail = require_instruction_schedule_debug_fidelity(
        seed, sp, image, windows, spec, mangled,
        "composed-rewriting debug fidelity", relocation_symbols,
        code_length, internal_targets,
    )

    pinned_length = function["retail_oracle"]["length"]
    require(len(retail_body) == pinned_length == len(image),
            "composed-rewriting retail length changed")
    semantic_detail = require_retail_relocation_oracle(
        seed_rows, bytes(retail_body),
        int(function["retail_oracle"]["address"], 16),
        function["retail_relocations"],
        "composed-rewriting retail relocation oracle",
    )
    masked_image = bytearray(image)
    masked_retail = bytearray(retail_body)
    for row in seed_rows:
        start, width = row["offset"], row["width"]
        masked_image[start:start + width] = b"\0" * width
        masked_retail[start:start + width] = b"\0" * width
    differing = sum(left != right
                    for left, right in zip(masked_image, masked_retail))
    require(differing == 0,
            f"composed-rewriting output is not retail-exact: {differing} "
            "byte(s) differ under the relocation mask")

    derived = bytearray(seed_bytes)
    derived[sp["raw_offset"]:sp["raw_offset"] + sp["raw_size"]] = image
    effective = {
        "mangled": mangled,
        "splice_class": delegate,
        "expected_body_length": function["expected_body_length"],
        "expected_body_sha256": function["expected_body_sha256"],
        "expected_changed_offsets": function["expected_changed_offsets"],
    }
    # The installed object is the seed with its own body replaced, so there
    # is nothing to rename -- whichever delegate the closure selects.  The
    # pins must say so, and the primitive then measures it.
    require(function["expected_code_renames"] == []
            and function["expected_xdata_rename_offsets"] == [],
            "composed-rewriting installs the seed's own tables and can "
            "declare no rename")
    if delegate == "equal_body_eh_structural_local":
        effective["expected_code_renames"] = []
        effective["expected_xdata_rename_offsets"] = []
    composed, detail = compose_equal_body_comdat(
        seed_bytes, bytes(derived), effective)

    checked = CoffObject(composed)
    cp = checked.function_section(mangled)
    require(coff_body(checked, cp) == image,
            "composed-rewriting composed body differs from the image")
    require(detailed_relocations(checked, cp) == seed_rows
            and _coff_table_bytes(checked, cp, "relocations")
            == _coff_table_bytes(seed, sp, "relocations")
            and _coff_table_bytes(checked, cp, "lines")
            == _coff_table_bytes(seed, sp, "lines"),
            "composed-rewriting output changed seed relocation/line bytes")

    # C3.  Every bijection's S_REGISTER record set is measured on the SEED's
    # stream, the sets are required to be pairwise disjoint, and each map is
    # then applied once -- so no record is ever read back as if the previous
    # bijection's output were the compiler's own allocation.
    debug_child = _comdat_child(checked, cp, ".debug$S")
    debug_stream = coff_body(checked, debug_child)
    require(sha256_bytes(debug_stream)
            == spec["expected_seed_debug_s_sha256"],
            "composed-rewriting debug$S differs from its pin")
    claimed = {}
    for index, item in enumerate(spec["register_bijections"]):
        for record in parse_codeview_symbol_stream(
                debug_stream, "composed-rewriting debug$S"):
            if record["type"] != CODEVIEW_REGISTER_RECORD_TYPE:
                continue
            field_at = _codeview_register_field(
                record, "composed-rewriting debug$S")
            name = _codeview_register_name(
                debug_stream, field_at, "composed-rewriting debug$S")
            if name not in item["mapping"]:
                continue
            require(record["offset"] not in claimed,
                    f"composed-rewriting bijections {claimed.get(record['offset'])} "
                    f"and {index} both name the S_REGISTER record "
                    f"{record['name']!r}")
            claimed[record["offset"]] = index
    debug_image = debug_stream
    debug_maps = []
    for index, item in enumerate(spec["register_bijections"]):
        mapped = apply_codeview_register_bijection(
            debug_stream, item["mapping"], item["debug_s_register_map"],
            f"composed-rewriting debug$S bijection {index}")
        moved = bytearray(debug_image)
        for position in range(len(debug_stream)):
            if mapped[position] != debug_stream[position]:
                moved[position] = mapped[position]
        debug_image = bytes(moved)
        debug_maps.append(item["debug_s_register_map"])
    require(sha256_bytes(debug_image)
            == spec["expected_image_debug_s_sha256"],
            "composed-rewriting mapped debug$S differs from its pin")
    composed = bytearray(composed)
    composed[debug_child["raw_offset"]:
             debug_child["raw_offset"] + debug_child["raw_size"]] = debug_image
    composed = bytes(composed)
    final = CoffObject(composed)
    fp = final.function_section(mangled)
    require(coff_body(final, fp) == image,
            "composed-rewriting output changed the installed body")
    for child_name in expected_closure:
        if child_name == ".debug$S":
            continue        # the one child this class maps, pinned above
        require(coff_body(final, _comdat_child(final, fp, child_name))
                == coff_body(seed, _comdat_child(seed, sp, child_name)),
                f"composed-rewriting output changed its {child_name} child")
    allowed = set(range(sp["raw_offset"], sp["raw_offset"] + sp["raw_size"]))
    allowed |= set(range(debug_child["raw_offset"],
                         debug_child["raw_offset"] + debug_child["raw_size"]))
    require({index for index in range(len(seed_bytes))
             if seed_bytes[index] != composed[index]} <= allowed,
            "composed-rewriting changed bytes outside its own COMDAT")
    return composed, {
        **detail,
        "splice_class": COMPOSED_REWRITING_CLASS,
        "instruction_schedule": schedule_detail,
        "register_bijections": bijection_detail,
        "relational_form": relational_detail,
        "instruction_count": len(image_instructions),
        "changed_offsets": changed,
        "debug_fidelity": debug_detail,
        "debug_s_register_maps": debug_maps,
        "external_entries": sorted(external_entries),
        "retail_exact": True,
        **semantic_detail,
    }
